def test_schedule_uncertain_record_never_fires_twice():
    section("scheduler: a clock stepped back or an unreadable record never "
            "fires a show twice")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import schedule_service as SV

    def ticks(svc, now, *times):
        for t in times:
            now[0] = _den(S, *t)
            svc.tick()

    # The auditor's case, grace 0: show 1 fires at 18:00:00 and is confirmed
    # at 18:00:03; the clock is stepped back about 6 s; ltcplay restarts at
    # 17:59:57.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59, 50)]
    a = _svc(S, work, now).start(thread=False)
    ticks(a, now, (18, 0, 0))
    now[0] = _den(S, 18, 0, 3)
    a._apply(S.Event(S.SHOW_CONFIRMED, "madmapper"))
    check(_starts(a) == [1], "show 1 started at 18:00:00")
    path = SV.tonight_path(_den(S, 0, 0).date(), work)
    now[0] = _den(S, 17, 59, 57)
    b = _svc(S, work, now).start(thread=False)
    s1 = b.machine.slot(1)
    check(s1.status == S.FAULT and "restarted" in s1.reason,
          f"the show cut off by the restart is recorded as FAULT: "
          f"{s1.status} {s1.reason!r}")
    check(os.path.exists(path)
          and not os.path.exists(path[:-5] + ".unreadable.json"),
          "a clock step is not corruption: the record is kept")
    check(any("set back by about 6 s" in r["text"] for r in b.journal),
          "the journal names the step")
    ticks(b, now, (17, 59, 59), (18, 0, 0), (18, 0, 1), (18, 0, 3),
          (18, 1), (18, 19, 59))
    check(not _starts(b), f"show 1 must not start again: started "
                          f"{_starts(b)}")
    ticks(b, now, (18, 20))
    check(_starts(b) == [2], "and the 18:20 show still starts on time")

    # Grace 15, a record that became unreadable 3 s after a show fired.
    rule15 = _sched_doc(weekly={"sat": {"first_start": "18:00",
                                        "interval_min": 20,
                                        "last_end": "22:00"}},
                        exceptions={}, late_grace_s=15)
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59, 50)]
    a = _svc(S, work, now, rule=rule15).start(thread=False)
    ticks(a, now, (18, 0, 0))
    check(_starts(a) == [1], "show 1 started at 18:00:00")
    open(SV.tonight_path(_den(S, 0, 0).date(), work), "w",
         encoding="utf-8").write("{torn")
    now[0] = _den(S, 18, 0, 3)
    b = _svc(S, work, now).start(thread=False)
    check(b.machine.late_grace_s == 15, "the rule's grace is 15")
    ticks(b, now, (18, 0, 4), (18, 0, 10), (18, 0, 15), (18, 1))
    s1 = b.machine.slot(1)
    check(not _starts(b) and s1.status == S.MISSED
          and s1.reason == S.UNREADABLE,
          f"inside a 15 s grace, an unreadable record must not start show 1 "
          f"again: started {_starts(b)}, {s1.reason!r}")
    check(b.machine.last_end == _den(S, 18, 0, 3),
          "the last show is assumed to have ended at the restart")
    check(any(r["outcome"] == "assumed the worst" and "18:02:03" in r["text"]
              for r in b.journal),
          "the journal says nothing starts before the guard runs out")
    ticks(b, now, (18, 20))
    check(_starts(b) == [2], "the next show starts on time")

    # Clean boots keep the grace: no file at all, and a good file saved
    # before the show, both start show 1 five seconds late with grace 15.
    for with_file in (False, True):
        work = tempfile.mkdtemp()
        now = [_den(S, 17, 59)]
        if with_file:
            _svc(S, work, now, rule=rule15).start(thread=False)
        else:
            _svc(S, work, now, rule=rule15)        # the rule file only
            check(not os.path.exists(SV.tonight_path(
                _den(S, 0, 0).date(), work)), "no tonight file yet")
        now[0] = _den(S, 18, 0, 5)
        c = _svc(S, work, now).start(thread=False)
        check(_starts(c) == [1] and c.machine.slot(1).reason == "FIRED",
              f"a clean boot {'with a good file ' if with_file else ''}"
              f"5 s into a 15 s grace still starts show 1: "
              f"{_starts(c)} {c.machine.slot(1).reason!r}")
        check(not any(r["outcome"] == "assumed the worst"
                      for r in c.journal),
              "and assumes nothing")
    for r in b.journal:
        _no_dashes(r["text"], "uncertain record")
    print("  ok")


def test_schedule_delayed_and_paused_survive_a_restart():
    section("scheduler: a delayed show and a paused show across a restart")
    S = _sched()
    if S is None:
        return
    import tempfile

    def at(svc, now, t, ev=None):
        now[0] = _den(S, *t)
        svc._apply(ev) if ev else svc.tick()

    # On hold with a delayed show, restart: still on hold, still delayed,
    # and the Hold rules carry on after it.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 5)]
    a = _svc(S, work, now).start(thread=False)
    at(a, now, (18, 10), _op(S, S.HOLD_ON))
    at(a, now, (18, 20, 1))
    check(a.machine.slot(2).status == S.DELAYED, "18:20 delayed by the Hold")
    now[0] = _den(S, 18, 25)
    b = _svc(S, work, now).start(thread=False)
    check(b.machine.state == S.HOLD and b.machine.slot(2).status == S.DELAYED
          and b.machine.slot(2).reason == "DELAYED (on hold)",
          f"after a restart the Hold and the delayed show are kept: "
          f"{b.machine.state} {b.machine.slot(2).status}")
    at(b, now, (18, 40, 1))
    check(b.machine.slot(2).status == S.MISSED
          and b.machine.slot(3).status == S.DELAYED,
          "and the newest delayed show still wins after it")
    at(b, now, (18, 41), _op(S, S.RESUME))
    at(b, now, (18, 42), _op(S, S.START_NOW))
    check(_starts(b) == [3]
          and b.machine.slot(3).reason == "DELAYED START (operator hold)",
          "Start now starts the delayed show after the restart")

    # Down across two slot times while on hold: the time it was down counts
    # as Hold.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 5)]
    a = _svc(S, work, now).start(thread=False)
    at(a, now, (18, 10), _op(S, S.HOLD_ON))
    now[0] = _den(S, 18, 41)
    b = _svc(S, work, now).start(thread=False)
    check([s.status for s in b.machine.slots[1:3]] == [S.MISSED, S.DELAYED]
          and b.machine.state == S.HOLD and not _starts(b),
          f"a restart on hold after two slot times: {[s.status for s in b.machine.slots[1:3]]}")

    # STANDBY with a delayed show waiting, restart: it still waits and never
    # starts by itself.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 5)]
    a = _svc(S, work, now).start(thread=False)
    at(a, now, (18, 10), _op(S, S.HOLD_ON))
    at(a, now, (18, 20, 1))
    at(a, now, (18, 25), _op(S, S.RESUME))
    now[0] = _den(S, 18, 26)
    b = _svc(S, work, now).start(thread=False)
    check(b.machine.state == S.STANDBY
          and b.machine.slot(2).status == S.DELAYED,
          "a delayed show waiting in STANDBY survives the restart")
    for t in ((18, 26, 1), (18, 30), (18, 35)):
        at(b, now, t)
    check(not _starts(b), "and still never starts by itself")

    # The dry run respects a pause: a paused show never "ends", and after
    # Resume it ends at its new, later time, with nothing refused on the way.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59, 50)]
    c = _svc(S, work, now).start(thread=False)
    at(c, now, (18, 0))
    at(c, now, (18, 3), _op(S, S.HOLD_ON))
    for t in ((18, 7, 20), (18, 10), (18, 12, 59)):
        at(c, now, t)
    check(c.machine.state == S.PAUSED
          and not any(r["outcome"] == "refused" for r in c.journal),
          "the dry run never tries to end a paused show")
    at(c, now, (18, 13), _op(S, S.RESUME))
    at(c, now, (18, 17, 19))
    check(c.machine.state == S.SHOW, "ten minutes paused: still running at "
                                     "18:17:19")
    at(c, now, (18, 17, 20))
    check(c.machine.slot(1).status == S.DONE
          and c.machine.slot(1).ended_at == _den(S, 18, 17, 20),
          f"and it ends at 18:17:20: {c.machine.slot(1).status}")

    # Paused, restart: treated as a restart during a show.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59, 50)]
    a = _svc(S, work, now).start(thread=False)
    at(a, now, (18, 0))
    at(a, now, (18, 3), _op(S, S.HOLD_ON))
    check(a.machine.state == S.PAUSED, "show 1 paused")
    now[0] = _den(S, 18, 5)
    b = _svc(S, work, now).start(thread=False)
    s1 = b.machine.slot(1)
    check(s1.status == S.FAULT and "restarted" in s1.reason
          and b.machine.state == S.STANDBY and b.machine.fault,
          f"a restart while paused ends the show as FAULT: {s1.status} "
          f"{s1.reason!r} {b.machine.state}")
    acts = [r["action"] for r in b.journal if r["outcome"] == "not performed"]
    check("ZERO_FLAME_CUES" in acts and "RESUME_SHOW" not in acts
          and "START_SHOW" not in acts,
          f"the rig is made safe and nothing resumes: {acts}")
    print("  ok")


def test_schedule_operator_list():
    section("scheduler: operator names come from a list in data_dir()")
    S = _sched()
    if S is None:
        return
    import json
    import tempfile
    from ltcplay import schedule_service as SV
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 30)]
    svc = _svc(S, work, now).start(thread=False)
    path = SV.operators_path(work)
    check(os.path.dirname(SV.operators_path()) == SV.data_dir(),
          "the operators file lives in data_dir()")
    check(json.load(open(path, encoding="utf-8")) ==
          {"operators": ["Andy", "Jeff"]}
          and svc.operators == ("Andy", "Jeff")
          and svc.machine.operators == ("Andy", "Jeff"),
          "a missing list is written with Andy and Jeff")
    for who in ("Bob", "", "  "):
        try:
            svc.edit_tonight({"op": "remove", "show": 3, "who": who,
                              "screen": "rack screen"})
            check(False, f"an edit by {who!r} was accepted")
        except ValueError as e:
            check(("not on the operator list" in str(e)) if who.strip()
                  else ("who pressed it" in str(e)),
                  f"an edit by {who!r} is refused with a sentence: {e}")
    check(svc.machine.slot(3).status == S.PENDING, "nothing was changed")
    svc.edit_tonight({"op": "remove", "show": 3, "who": "jeff",
                      "screen": "rack screen"})
    check(svc.machine.slot(3).status == S.SKIPPED, "Jeff may edit")
    # Somebody else's list is the list in force.
    json.dump({"operators": ["Casey", "Andy"]},
              open(path, "w", encoding="utf-8"))
    other = _svc(S, work, now).start(thread=False)
    check(other.machine.operators == ("Casey", "Andy"),
          "the list on disk is the list in force")
    try:
        other.edit_tonight({"op": "remove", "show": 4, "who": "Jeff",
                            "screen": "rack screen"})
        check(False, "Jeff was accepted though not on this list")
    except ValueError as e:
        check("Casey, Andy" in str(e), f"the sentence names the list: {e}")
    # A broken list: the defaults stay in force and the journal says why.
    for bad in ('{"operators": []}', '{"operators": ["Andy", "andy"]}',
                '{"names": ["Andy"]}', '{"operators": [""]}', "{nope"):
        open(path, "w", encoding="utf-8").write(bad)
        b = _svc(S, work, now).start(thread=False)
        check(b.operators == ("Andy", "Jeff")
              and any("could not be used" in r["text"] for r in b.journal),
              f"a broken list {bad!r} falls back to Andy and Jeff, and "
              f"says so")
        for r in b.journal:
            _no_dashes(r["text"], "operators")
    print("  ok")


def test_schedule_a_paused_show_is_never_overlapped():
    section("scheduler: nothing fires over a paused show; a pause keeps the "
            "night past midnight")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import timedelta
    # Paused at 18:01, ticked every second through 18:20 and past its grace:
    # nothing fires, the show stays paused, 18:20 is DELAYED.
    for grace in (0, 15, 120, 300):
        rule = _one_night_rule(S, grace=grace)
        n = _Night(S, rule)
        n.boot(_den(S, 17, 50))
        n.tick(_den(S, 18, 0))
        n.op(S.HOLD_ON, _den(S, 18, 1))
        t, fired = _den(S, 18, 1), []
        while t <= _den(S, 18, 21) + timedelta(seconds=grace):
            fired += _fired(n.tick(t), S)
            t += timedelta(seconds=1)
        check(not fired, f"grace {grace}: a paused show must never be "
                         f"overlapped; started {fired}")
        running = [s.n for s in n.m.slots if s.status == S.RUNNING]
        check(n.m.state == S.PAUSED and n.m.running == 1 and running == [1],
              f"grace {grace}: show 1 stays paused and is the only one "
              f"running: {n.m.state} {running}")
        check(n.m.slot(2).status == S.DELAYED,
              f"grace {grace}: 18:20 is DELAYED: {n.m.slot(2).status}")
        n.audit(f"paused overlap grace {grace}")

    # Paused across midnight: the night is kept until the show is over.
    work = tempfile.mkdtemp()
    now = [_den(S, 23, 57)]
    a = _svc(S, work, now).start(thread=False)
    now[0] = _den(S, 23, 58)
    a._apply(_op(S, S.START_NOW))
    now[0] = _den(S, 23, 59)
    a._apply(_op(S, S.HOLD_ON))
    check(a.machine.state == S.PAUSED, "a show paused at 23:59")
    for t in ((0, 0, 0), (0, 0, 30), (0, 10)):
        now[0] = _den(S, *t, d=(2026, 11, 15))
        a.tick()
        check(str(a.machine.date) == "2026-11-14"
              and a.machine.state == S.PAUSED and a.machine.running,
              f"at {t} the paused night is kept, got {a.machine.date} "
              f"{a.machine.state}")
    now[0] = _den(S, 0, 11, d=(2026, 11, 15))
    a._apply(_op(S, S.RESUME))
    check(str(a.machine.date) == "2026-11-14" and a.machine.state == S.SHOW,
          "Resume after midnight carries on in the same night")
    now[0] = _den(S, 0, 30, d=(2026, 11, 15))
    a.tick()
    a.tick()
    check(str(a.machine.date) == "2026-11-14" and a.machine.running == 0,
          f"the show is over at 00:30, and Saturday's night runs on until "
          f"the 2 AM reset: {a.machine.date} {a.machine.state}")
    now[0] = _den(S, 2, 0, d=(2026, 11, 15))
    a.tick()
    check(str(a.machine.date) == "2026-11-15",
          f"the new night starts at the 2 AM reset: {a.machine.date}")
    print("  ok")


def test_schedule_a_clock_step_during_a_pause():
    section("scheduler: a clock set back during a pause never makes the "
            "paused time negative")
    S = _sched()
    if S is None:
        return
    import copy
    import json
    import tempfile
    from ltcplay import schedule_service as SV
    rule = _one_night_rule(S)
    for last, how in ((S.RESUME, {}), (S.STOP_SHOW, {"confirmed": True})):
        n = _Night(S, rule)
        n.boot(_den(S, 17, 50))
        n.tick(_den(S, 18, 0))
        n.op(S.HOLD_ON, _den(S, 18, 1))
        check(n.m.hm(n.m.expected_end(_den(S, 18, 0, 50))) == "18:07:20",
              "while the clock reads earlier than the pause, the end does "
              "not move earlier")
        o = n.op(last, _den(S, 18, 0, 50), **how)
        check(n.m.slot(1).paused_s == 0.0,
              f"{last} after a 10 s step back: paused time is 0, not "
              f"{n.m.slot(1).paused_s}")
        step = [le for le in o.log if le.outcome == "clock stepped back"]
        check(len(step) == 1 and "about 10 s" in step[0].text
              and step[0].actor == "system",
              f"{last}: the step is journalled: {[le.text for le in o.log]}")
        if last == S.RESUME:
            check(n.m.hm(n.m.expected_end()) == "18:07:20",
                  "and the end stays at 18:07:20")
        n.audit(f"clock step during a pause, {last}")

    # A saved negative paused time is clamped with a sentence, not refused.
    n = _Night(S, rule)
    n.boot(_den(S, 17, 50))
    n.tick(_den(S, 18, 0))
    n.do(S.SHOW_ENDED, "madmapper", _den(S, 18, 7, 20))
    doc = copy.deepcopy(S.machine_to_doc(n.m))
    doc["slots"][0]["paused_s"] = -10.0
    notes = []
    m = S.machine_from_doc(doc, rule, n.m.date, _den(S, 18, 10), notes)
    check(m.slot(1).paused_s == 0.0 and len(notes) == 1
          and "taken as 0 s" in notes[0] and "-10 s" in notes[0],
          f"a negative saved paused time reads as 0 with a sentence: "
          f"{notes}")

    # The whole story through the service: pause, clock back, Resume,
    # restart. Tonight's record is kept, not set aside.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59, 50)]
    a = _svc(S, work, now).start(thread=False)
    for t, ev in (((18, 0), None), ((18, 1), _op(S, S.HOLD_ON)),
                  ((18, 0, 50), _op(S, S.RESUME))):
        now[0] = _den(S, *t)
        a._apply(ev) if ev else a.tick()
    saved = json.load(open(SV.tonight_path(a.machine.date, work),
                           encoding="utf-8"))
    check(saved["slots"][0]["paused_s"] == 0.0,
          f"the saved paused time is 0: {saved['slots'][0]['paused_s']}")
    now[0] = _den(S, 18, 0, 55)
    b = _svc(S, work, now).start(thread=False)
    path = SV.tonight_path(b.machine.date, work)
    check(os.path.exists(path)
          and not os.path.exists(path[:-5] + ".unreadable.json")
          and not any(r["outcome"] == "assumed the worst" for r in b.journal),
          "the record survives the restart; nothing is assumed")
    check(b.machine.slot(1).status == S.FAULT
          and "restarted" in b.machine.slot(1).reason,
          "and the restart is handled as a restart during a show")
    for r in a.journal + b.journal:
        _no_dashes(r["text"], "clock step during a pause")
    print("  ok")


# ------------------------------------------------------ the show clock ----
# Fire & Ice 2026, handoff section 4. None of these import ltcplay.clock at
# module scope: the GPL test below proves the program never loads it unless
# a show file asks, and this file importing it up top would hide nothing but
# would make that test harder to trust.


class _TcOut:
    """Stands in for the Art-Net timecode socket and keeps every packet."""

    def __init__(self, dests=(("test", "127.0.0.1"),)):
        self.dests = list(dests)
        self.sent = []
        self.packets_sent = 0
        self.send_errors = 0
        self.last_error = ""
        self.closed = 0

    last_error_at = None
    seconds_since_error = None
    failing_labels = ()

    @property
    def seconds_since_ok(self):
        return 0.0

    def send(self, pkt):
        self.sent.append((time.perf_counter(), bytes(pkt)))
        self.packets_sent += 1
        return True

    def close(self):
        self.closed += 1


def _tc_of(pkt):
    """(h, m, s, f, type) out of an ArtTimeCode packet."""
    return pkt[17], pkt[16], pkt[15], pkt[14], pkt[18]


# ------------------------------------------------------------ announcements


def _ann():
    from ltcplay import announce as A
    return A


def _ann_write_wav(path, seconds=1.0, rate=8000, channels=1):
    import struct
    import wave as _wave
    n = int(seconds * rate)
    with _wave.open(path, "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(2)
        w.setframerate(rate)
        # A quiet square wave (-30 dBFS), never all zeros: a recording
        # that decodes to silence is refused (Jeff's field report,
        # 2026-10-28).
        w.writeframes(struct.pack(f"<{n * channels}h", *[
            1000 if (i // (channels * 8)) % 2 else -1000
            for i in range(n * channels)]))
    return n / float(rate)


def _ann_workdir(device="MOTU M4"):
    """A tempdir with three short, valid WAV files and a config naming them.
    Returns (workdir, config_path, {id: length_s})."""
    A = _ann()
    work = tempfile.mkdtemp()
    lengths = {}
    for aid, secs in zip(A.IDS, (1.0, 1.5, 0.5)):
        lengths[aid] = _ann_write_wav(os.path.join(work, aid + ".wav"),
                                      seconds=secs)
    cfg = {"device": device,
           "files": {aid: aid + ".wav" for aid in A.IDS}}
    path = os.path.join(work, "ltcplay_announce.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(cfg, fh)
    return work, path, lengths


def _ann_write_24bit(path, seconds=1.0, rate=8000):
    """A real 24-bit PCM WAV: 3 bytes per sample, valid RIFF/WAVE, which
    Python's `wave` opens fine (getsampwidth() == 3) -- it does not reject
    24-bit on its own."""
    import wave as _wave
    n = int(seconds * rate)
    with _wave.open(path, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(3)
        w.setframerate(rate)
        # A quiet tone, never all zeros (a silent recording is refused).
        w.writeframes(b"".join(
            (40000 if (i // 8) % 2 else -40000).to_bytes(3, "little",
                                                         signed=True)
            for i in range(n)))


def _ann_write_float32(path, seconds=1.0, rate=8000, value=0.9):
    """A real 32-bit IEEE-float WAV (format tag 3), built by hand: Python's
    `wave` module cannot write float, only PCM, and cannot read the format
    tag back out either -- exactly what an external tool (a DAW, a field
    recorder) would hand an operator."""
    import array
    import struct
    n = int(seconds * rate)
    data = array.array("f", [value] * n).tobytes()
    byte_rate = rate * 4
    fmt_chunk = struct.pack("<HHIIHH", 3, 1, rate, byte_rate, 4, 32)
    riff = (b"RIFF" +
           struct.pack("<I", 4 + 8 + len(fmt_chunk) + 8 + len(data)) +
           b"WAVE")
    fmt = b"fmt " + struct.pack("<I", len(fmt_chunk)) + fmt_chunk
    data_chunk = b"data" + struct.pack("<I", len(data)) + data
    with open(path, "wb") as fh:
        fh.write(riff + fmt + data_chunk)


def test_announce_probe_matches_open_for_format():
    section("announcements: 16-bit, 24-bit and 32-bit float WAVs are all "
            "accepted (Jeff, 2026-09-26), and the startup probe agrees "
            "with the press-time open on exactly what will play")
    A = _ann()
    work = tempfile.mkdtemp()
    _ann_write_wav(os.path.join(work, "delayed.wav"), seconds=1.0)
    _ann_write_24bit(os.path.join(work, "cancellation.wav"), seconds=1.0)
    _ann_write_float32(os.path.join(work, "cannot_continue.wav"),
                       seconds=1.0)
    cfg = {"device": "MOTU M4",
           "files": {"delayed": "delayed.wav",
                    "cancellation": "cancellation.wav",
                    "cannot_continue": "cannot_continue.wav"}}
    path = os.path.join(work, "ltcplay_announce.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(cfg, fh)
    svc = A.AnnounceService(path, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    by_id = {i["id"]: i for i in svc.status()["announcements"]}
    check(by_id[A.DELAYED]["available"], "a plain 16-bit WAV is fine")
    check(by_id[A.CANCELLATION]["available"],
          f"a 24-bit WAV must be accepted, at startup: "
          f"{by_id[A.CANCELLATION]}")
    check(by_id[A.CANNOT_CONTINUE]["available"],
          f"a 32-bit float WAV must be accepted too, at startup: "
          f"{by_id[A.CANNOT_CONTINUE]}")
    for aid in A.IDS:
        r = svc.play(aid, "Andy", "rack screen")
        check(r["playing"]["id"] == aid,
              f"{aid} must actually play, agreeing with the probe, not "
              f"just look clean and then fail at the press: {r}")
        svc.stop("Andy", "rack screen")
    print("  ok")


def test_announce_unsupported_wav_formats_rejected():
    section("announcements: a WAV format this module cannot play safely "
            "is still refused, the same way at startup and at the press")
    A = _ann()
    work = tempfile.mkdtemp()

    def write_alaw(path, seconds=1.0, rate=8000):
        import struct
        n = int(seconds * rate)
        data = b"\x00" * n
        fmt_chunk = struct.pack("<HHIIHH", 6, 1, rate, rate, 1, 8)
        riff = (b"RIFF" +
               struct.pack("<I", 4 + 8 + len(fmt_chunk) + 8 + len(data)) +
               b"WAVE")
        fmt = b"fmt " + struct.pack("<I", len(fmt_chunk)) + fmt_chunk
        data_chunk = b"data" + struct.pack("<I", len(data)) + data
        with open(path, "wb") as fh:
            fh.write(riff + fmt + data_chunk)

    def write_float64(path, seconds=1.0, rate=8000):
        import array
        import struct
        n = int(seconds * rate)
        data = array.array("d", [0.1] * n).tobytes()
        byte_rate = rate * 8
        fmt_chunk = struct.pack("<HHIIHH", 3, 1, rate, byte_rate, 8, 64)
        riff = (b"RIFF" +
               struct.pack("<I", 4 + 8 + len(fmt_chunk) + 8 + len(data)) +
               b"WAVE")
        fmt = b"fmt " + struct.pack("<I", len(fmt_chunk)) + fmt_chunk
        data_chunk = b"data" + struct.pack("<I", len(data)) + data
        with open(path, "wb") as fh:
            fh.write(riff + fmt + data_chunk)

    write_alaw(os.path.join(work, "delayed.wav"))
    write_float64(os.path.join(work, "cancellation.wav"))
    _ann_write_wav(os.path.join(work, "cannot_continue.wav"), seconds=1.0)
    cfg = {"device": "MOTU M4",
           "files": {"delayed": "delayed.wav",
                    "cancellation": "cancellation.wav",
                    "cannot_continue": "cannot_continue.wav"}}
    path = os.path.join(work, "ltcplay_announce.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(cfg, fh)
    svc = A.AnnounceService(path, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    by_id = {i["id"]: i for i in svc.status()["announcements"]}
    check(not by_id[A.DELAYED]["available"]
          and "format 6" in by_id[A.DELAYED]["reason"],
          f"A-law (a non-PCM, non-float tag) must still be caught at "
          f"startup: {by_id[A.DELAYED]}")
    check(not by_id[A.CANCELLATION]["available"]
          and "64-bit" in by_id[A.CANCELLATION]["reason"],
          f"64-bit float must still be caught at startup, never silently "
          f"truncated to 32-bit: {by_id[A.CANCELLATION]}")
    check(by_id[A.CANNOT_CONTINUE]["available"], "the plain WAV is fine")
    for aid in (A.DELAYED, A.CANCELLATION):
        try:
            svc.play(aid, "Andy", "rack screen")
            check(False, f"{aid} must never actually play")
        except ValueError as e:
            check("not available" in str(e), f"{e}")
    print("  ok")


def test_announce_wav_decode_values():
    section("announcements: 24-bit PCM and 32-bit float samples decode "
            "to the right values, not just the right length")
    import struct
    import wave
    import numpy as np
    A = _ann()
    work = tempfile.mkdtemp()

    # 24-bit: known samples, left-justified (shifted up 8 bits) into
    # int32 is the only conversion that keeps both the sign and the full
    # scale right.
    path24 = os.path.join(work, "a24.wav")
    samples = (0, 1, -1, 8388607, -8388608, 12345)
    raw = b"".join(int(s & 0xFFFFFF).to_bytes(3, "little")
                  for s in samples)
    with wave.open(path24, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(3)
        w.setframerate(8000)
        w.writeframes(raw)
    pcm, channels, rate, _length = A._wav_info(path24, decode=True)
    check(pcm.dtype == np.int32, f"24-bit PCM must decode to int32: "
                                 f"{pcm.dtype}")
    got = pcm.reshape(-1).astype(np.int64).tolist()
    want = [s * 256 for s in samples]
    check(got == want,
          f"24-bit samples must be shifted up 8 bits, sign and all, not "
          f"reinterpreted some other way: want {want}, got {got}")

    # 32-bit float: the wav module cannot write this format, so it is
    # built by hand, the same way a DAW or field recorder would hand one
    # over (Jeff, 2026-09-26: recordings may be float).
    path32 = os.path.join(work, "a32f.wav")
    values = (0.5, -0.5, 0.999, -1.0)
    data = _pack_float32(values)
    byte_rate = 8000 * 4
    fmt_chunk = struct.pack("<HHIIHH", 3, 1, 8000, byte_rate, 4, 32)
    riff = (b"RIFF" +
           struct.pack("<I", 4 + 8 + len(fmt_chunk) + 8 + len(data)) +
           b"WAVE")
    fmt = b"fmt " + struct.pack("<I", len(fmt_chunk)) + fmt_chunk
    data_chunk = b"data" + struct.pack("<I", len(data)) + data
    with open(path32, "wb") as fh:
        fh.write(riff + fmt + data_chunk)
    pcm2, channels2, rate2, length2 = A._wav_info(path32, decode=True)
    check(pcm2.dtype == np.float32,
          f"32-bit float must decode to float32, not be reinterpreted as "
          f"int32 (loud noise, no error anywhere): {pcm2.dtype}")
    got2 = [round(float(v), 3) for v in pcm2.reshape(-1)]
    check(got2 == list(values),
          f"the float samples themselves must round-trip: want "
          f"{list(values)}, got {got2}")
    check(rate2 == 8000 and channels2 == 1 and abs(length2 - 0.0005) < 1e-6,
          f"channels, rate and length must all be read off the float "
          f"file's own fmt chunk: {channels2} {rate2} {length2}")

    # The probe (decode=False) must agree with the open on both.
    _, ch3, rate3, len3 = A._wav_info(path24, decode=False)
    check(ch3 == 1 and rate3 == 8000, f"probe must read the same header "
                                      f"a real open would: {ch3} {rate3}")
    _, ch4, rate4, len4 = A._wav_info(path32, decode=False)
    check(ch4 == 1 and rate4 == 8000 and abs(len4 - 0.0005) < 1e-6,
          f"the probe must agree with the open on the float file too: "
          f"{ch4} {rate4} {len4}")
    print("  ok")


def _pack_float32(values):
    import array
    return array.array("f", values).tobytes()


def _chunk(cid, body):
    import struct
    out = cid + struct.pack("<I", len(body)) + body
    if len(body) % 2:
        out += b"\x00"
    return out


def _riff(body):
    import struct
    return b"RIFF" + struct.pack("<I", 4 + len(body)) + b"WAVE" + body


def _fmt_extensible(channels, rate, bits, subformat_guid):
    import struct
    block_align = channels * (bits // 8)
    byte_rate = rate * block_align
    body = struct.pack("<HHIIHH", 0xFFFE, channels, rate, byte_rate,
                       block_align, bits)
    body += struct.pack("<H", 22)          # cbSize
    body += struct.pack("<H", bits)        # wValidBitsPerSample
    body += struct.pack("<I", 0)           # dwChannelMask
    body += subformat_guid
    return _chunk(b"fmt ", body)


_SUBTYPE_FLOAT = bytes.fromhex("0300000000001000800000aa00389b71")
_SUBTYPE_PCM = bytes.fromhex("0100000000001000800000aa00389b71")


def test_announce_wav_extensible_float_accepted():
    section("announcements: WAVE_FORMAT_EXTENSIBLE wrapping IEEE float is "
            "accepted and decoded as float, not refused with a raw GUID "
            "(review round 2, 2026-09-26, should-fix 5: many DAWs, "
            "Audacity among them, write 32-bit float this way)")
    A = _ann()
    n = 50
    data = _pack_float32([0.5] * n)
    body = _fmt_extensible(1, 48000, 32, _SUBTYPE_FLOAT) + _chunk(b"data",
                                                                  data)
    work = tempfile.mkdtemp()
    path = os.path.join(work, "ext_float.wav")
    with open(path, "wb") as fh:
        fh.write(_riff(body))
    pcm, channels, rate, length_s = A._wav_info(path, decode=True)
    check(str(pcm.dtype) == "float32",
          f"an extensible float file must decode as float32, not be "
          f"reinterpreted as integers: {pcm.dtype}")
    check(float(pcm.ravel()[0]) == 0.5,
          f"the float value itself must round-trip: {pcm.ravel()[:1]}")
    _, ch2, rate2, len2 = A._wav_info(path, decode=False)
    check(ch2 == 1 and rate2 == 48000,
          f"the probe must agree with the open: {ch2} {rate2}")

    # An extensible sub-format this module does not recognize (A-law
    # under extensible) must still be a PLAIN sentence, never a raw GUID.
    alaw_guid = bytes.fromhex("0600000000001000800000aa00389b71")
    body2 = _fmt_extensible(1, 8000, 8, alaw_guid) + _chunk(
        b"data", b"\x00" * 100)
    path2 = os.path.join(work, "ext_alaw.wav")
    with open(path2, "wb") as fh:
        fh.write(_riff(body2))
    try:
        A._wav_info(path2, decode=False)
        check(False, "an unrecognized extensible sub-format must be "
                     "refused, not accepted")
    except ValueError as e:
        msg = str(e)
        check("8000-00aa00389b71" not in msg and "0000-0010" not in msg,
              f"the refusal must never contain a raw GUID: {msg}")
        _no_dashes(msg, "extensible unrecognized sub-format refusal")
    print("  ok")


def test_announce_wav_data_chunk_sanity():
    section("announcements: a WAV whose data chunk declares an impossible "
            "size is refused loudly, the same way at the probe and the "
            "press, for BOTH the PCM and the float path (review round 2, "
            "2026-09-26, should-fix 6: audit15_wav_floatparser.py / "
            "audit15_wav_edgecases.py)")
    A = _ann()
    work = tempfile.mkdtemp()

    def write_pcm16(name, real_frames, declared_size):
        import struct
        real = struct.pack(f"<{real_frames}h", *([1000] * real_frames))
        fmt = _chunk(b"fmt ", struct.pack("<HHIIHH", 1, 1, 8000, 16000,
                                          2, 16))
        header = b"data" + struct.pack("<I", declared_size)
        path = os.path.join(work, name)
        with open(path, "wb") as fh:
            fh.write(_riff(fmt + header + real))
        return path

    def write_float(name, real_frames, declared_size):
        import struct
        real = _pack_float32([0.25] * real_frames)
        fmt_chunk = _chunk(b"fmt ", struct.pack("<HHIIHH", 3, 1, 48000,
                                                48000 * 4, 4, 32))
        header = b"data" + struct.pack("<I", declared_size)
        path = os.path.join(work, name)
        with open(path, "wb") as fh:
            fh.write(_riff(fmt_chunk + header + real))
        return path

    cases = [
        ("pcm_truncated.wav", write_pcm16, 100, 400, "cut off"),
        ("pcm_zero.wav", write_pcm16, 100, 0, "placeholder"),
        ("pcm_ffffffff.wav", write_pcm16, 100, 0xFFFFFFFF, "placeholder"),
        ("float_truncated.wav", write_float, 50, 1000, "cut off"),
        ("float_zero.wav", write_float, 50, 0, "placeholder"),
        ("float_ffffffff.wav", write_float, 50, 0xFFFFFFFF, "placeholder"),
    ]
    for name, writer, frames, declared, must_say in cases:
        path = writer(name, frames, declared)
        for decode in (False, True):
            try:
                A._wav_info(path, decode=decode)
                check(False, f"{name} (decode={decode}) must be refused, "
                             f"not read as a healthy file")
            except ValueError as e:
                msg = str(e)
                check(must_say in msg,
                      f"{name} (decode={decode}): the refusal must say "
                      f"why: {msg}")
                _no_dashes(msg, f"{name} data-chunk-sanity refusal")
    print("  ok")


def test_announce_device_exact_match_only():
    section("announcements: the output device is matched by its EXACT "
            "name, never a substring")
    A = _ann()

    class _SD:
        def __init__(self, devices):
            self._devices = devices

            class _Default:
                device = (0, 0)
            self.default = _Default()

        def query_devices(self):
            return self._devices

    # The configured device is gone; the only device left merely CONTAINS
    # the configured text, and is a different physical device (here: the
    # show's own DSP output). A substring match would silently pick it
    # (audit13_device_wrong_match.py).
    devices_after_unplug = [
        {"name": "Line In (Realtek)", "max_output_channels": 0,
         "default_samplerate": 48000},
        {"name": "Speakers (High Definition Audio Device)",
         "max_output_channels": 8, "default_samplerate": 48000},
    ]
    try:
        A.resolve_output_device(_SD(devices_after_unplug), "Speakers")
        check(False, "a substring match must be refused, not returned")
    except ValueError as e:
        check("not attached" in str(e),
              f"a device gone with only a substring hit left must refuse "
              f"plainly: {e}")

    devices_present = devices_after_unplug + [
        {"name": "Speakers", "max_output_channels": 2,
         "default_samplerate": 48000}]
    dev = A.resolve_output_device(_SD(devices_present), "Speakers")
    check(dev["name"] == "Speakers",
          f"the exact name must still resolve: {dev}")
    dev2 = A.resolve_output_device(_SD(devices_present), "SPEAKERS")
    check(dev2["name"] == "Speakers",
          "the match is case-insensitive, just never partial")
    print("  ok")


def test_announce_toctou_recheck_before_start():
    section("announcements: the SECOND look at the Hold, immediately before "
            "the sound starts, is read-only: an operator's Resume during the "
            "file read wins, nothing is Held again, and the announcement "
            "still plays, with nothing held (review round 2, 2026-09-26: "
            "audit15_resume_race.py; Jeff's field report, 2026-10-28: "
            "announcements are independent of the schedule)")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    fake = {"state": "STANDBY", "epoch": 0}
    hold_calls = []
    claimed_checks = []

    def fake_hold(who, screen, detail=None):
        # Hold always succeeds here and moves the fake schedule to HOLD,
        # bumping its epoch, exactly as the real Service would.
        hold_calls.append((who, screen, detail, fake["state"]))
        fake["state"] = "HOLD"
        fake["epoch"] += 1
        return None, fake["epoch"]

    def fake_still_claimed(claim_epoch):
        claimed_checks.append(claim_epoch)
        return (claim_epoch == fake["epoch"]
                and fake["state"] in ("HOLD", "PAUSED"))

    sd = FakeSD()
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: fake["state"])
    svc.hold_requester = fake_hold
    svc.hold_still_claimed = fake_still_claimed
    real_decode = svc._decode

    def decode_and_flip(ann_id):
        # Stands in for real wall time elapsing during the file read: an
        # operator resuming (a real Resume bumps the epoch, same as
        # fake_hold above) in that window is entirely realistic, since
        # the scheduler ticks on its own thread with no lock shared with
        # this service (audit13_toctou_race.py / audit15_resume_race.py).
        fake["state"] = "SHOW"
        fake["epoch"] += 1
        return real_decode(ann_id)

    svc._decode = decode_and_flip
    try:
        r = svc.play(A.DELAYED, "Andy", "rack screen")
    finally:
        svc._decode = real_decode
    check(r["playing"] and r["playing"]["id"] == A.DELAYED,
          f"a Resume during the file read never stops the announcement "
          f"playing: {r['playing']}")
    check(r["playing"]["held_schedule"] is False and
          "resumed while it loaded" in (r["playing"]["note"] or ""),
          f"it plays with nothing held, and says the schedule was "
          f"resumed: {r['playing']}")
    check(fake["state"] == "SHOW",
          "the operator's Resume stands: nothing re-Held the show")
    check(len(hold_calls) == 1,
          f"Hold must be requested only ONCE, before the file read: the "
          f"second look must be read-only, never Hold again: {hold_calls}")
    check(len(claimed_checks) == 1 and claimed_checks[0] == 1,
          f"the second look must ask about the epoch captured at the "
          f"FIRST Hold, not the current one: {claimed_checks}")
    svc.stop("Andy", "rack screen")
    print("  ok")


def test_announce_plays_whatever_the_schedule_state():
    section("announcements are independent of the schedule (Jeff's field "
            "report, 2026-10-28: \"It refuses because the night is over. "
            "That should not be this way.\"): every announcement plays with "
            "the scheduler closed (night over), in BOOT, with no schedule "
            "loaded, with no scheduler at all, during a running show, and "
            "on HOLD or PAUSED; a Hold is taken only between shows, and "
            "when none can be taken the press says so in one line")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    # The real scheduler's own refusals, by state, for HOLD_ON (schedule.py
    # _why_not), and None where hold_for_announcement succeeds.
    refusals = {"OFF": "The night is over, so there is nothing to hold.",
                "CLOSING": "The night is over, so there is nothing to hold.",
                "BOOT": "The scheduler is still starting up and has not "
                        "worked out the night yet.",
                None: "There is no schedule loaded."}
    cases = [("OFF", True), ("CLOSING", True), ("BOOT", True),
             (None, True), ("NOSCHED", False), ("SHOW", True),
             ("PAUSED", True), ("HOLD", True), ("IDLE", True),
             ("STANDBY", True)]
    for state, wired in cases:
        for aid in A.IDS:
            fake = {"state": None if state == "NOSCHED" else state,
                    "epoch": 0}
            calls = []

            def hold(who, screen, detail=None, fake=fake, calls=calls):
                calls.append(fake["state"])
                st = fake["state"]
                if st in ("HOLD", "PAUSED", "SHOW"):
                    return None, fake["epoch"]
                if st in ("IDLE", "STANDBY"):
                    fake["state"] = "HOLD"
                    fake["epoch"] += 1
                    return None, fake["epoch"]
                return refusals[st], fake["epoch"]

            def still(epoch, fake=fake):
                return epoch == fake["epoch"] and \
                    fake["state"] in ("HOLD", "PAUSED")

            svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                    state_provider=lambda f=fake: f["state"])
            if wired:
                svc.hold_requester = hold
                svc.hold_still_claimed = still
            try:
                r = svc.play(aid, "Andy", "rack screen", surface=True)
            except ValueError as e:
                check(False, f"{aid} in {state}: refused: {e}")
                continue
            p = r["playing"] or {}
            check(p.get("id") == aid, f"{aid} in {state}: it plays: {p}")
            want_held = wired and state in ("IDLE", "STANDBY", "HOLD")
            check(p.get("held_schedule") is want_held,
                  f"{aid} in {state}: held_schedule {want_held}: {p}")
            check(calls == ([] if not wired or state in ("SHOW", "PAUSED")
                            else
                            [state if state != "NOSCHED" else None]),
                  f"{aid} in {state}: a Hold is asked for only when no show "
                  f"is running: {calls}")
            if state in ("OFF", "CLOSING", "BOOT", None):
                check("No hold was possible" in (p.get("note") or "") and
                      refusals[state].rstrip(".") in p.get("note"),
                      f"{aid} in {state}: one line says why nothing was "
                      f"held: {p}")
            if state == "NOSCHED":
                check("nothing was held" in (p.get("note") or ""),
                      f"{aid} with no scheduler: said: {p}")
            if state in ("SHOW", "PAUSED"):
                check("nothing was paused" in (p.get("note") or ""),
                      f"{aid} over a show: said: {p}")
            line = [j for j in svc.journal if j["outcome"] == "started"]
            check(bool(line), f"{aid} in {state}: journaled as started")
            if line:
                _no_dashes(line[-1]["text"], f"{aid} in {state}")
            svc.stop("Andy", "rack screen", surface=True)
    print("  ok")


def test_announce_show_start_stops_announcement():
    section("announcements: a scheduled show stops a playing "
            "announcement, faded, and logs it")
    A = _ann()
    from ltcplay import schedule as S
    from ltcplay import schedule_service as SV
    work, cfg, _lengths = _ann_workdir()
    # A long announcement, so it is still going when the next slot fires.
    _ann_write_wav(os.path.join(work, "delayed.wav"), seconds=90.0,
                   rate=8000)

    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    doc = {"timezone": "America/Denver",
           "season": {"first_date": "2026-11-14", "last_date": "2027-01-02"},
           "weekly": {"sat": {"first_start": "17:30", "interval_min": 20,
                              "last_end": "22:00"}},
           "exceptions": {}, "show_len_s": 440, "guard_s": 120,
           "late_grace_s": 0}
    SV.save_rule(spath, doc)
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY,
          f"setup: the scheduler is in intermission: {svc.machine.state}")

    sd = FakeSD()
    ann = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started

    ann.play(A.DELAYED, "Andy", "rack screen")
    check(ann.playing == A.DELAYED, "setup: the announcement is playing "
                                    "during intermission, fully allowed")
    stream = sd.output_streams[-1]

    now[0] = _den(S, 17, 50, 0)          # the next slot fires
    svc.tick()
    check(svc.machine.state == S.SHOW,
          f"setup: the next slot fired: {svc.machine.state}")
    # The hook runs on a thread of its own now (review round 2, blocker
    # 1a/1b: tick() itself must return in under 50 ms even if a hook is
    # slow, so it cannot wait for the hook either) -- svc.tick() returning
    # says only that the hook was QUEUED, not that it has run yet. This is
    # the one place that gap is visible from the outside, and a short poll
    # is the deterministic way to wait for it, the same as any other
    # cross-thread handoff in this suite.
    check(wait_for(lambda: ann._player is not None
                   and ann._player.stop_reason == "a show started",
                   timeout=2.0),
          "the show-started hook must put the player into a fade: it is "
          "a push, not something announce.py polled the scheduler for")
    check(ann.playing == A.DELAYED,
          "the fade has not finished yet, so it is still the one playing")

    # The real audio driver keeps calling back on its own thread in
    # production; the test drives that explicitly, the same way the
    # natural-completion test does.
    stream.pump(int(8000 * A.SHOW_START_FADE_S) + 100)
    status = ann.status()
    check(status["playing"] is None,
          "once the fade finishes, the announcement must show as stopped")
    check(any(r["outcome"] == "stopped" and r["reason"] == "a show started"
             for r in status["journal"]),
          f"the stop must be journalled with why: {status['journal']}")
    check(stream.stopped and stream.closed,
          "the device stream must actually be closed")

    # The alternative Jeff has not chosen -- flip the one constant, and a
    # show starting must leave whatever is playing alone.
    old = A.SHOW_START_STOPS_ANNOUNCEMENT
    A.SHOW_START_STOPS_ANNOUNCEMENT = False
    try:
        # A provider of its own, deliberately not tied to the real
        # scheduler above (which is already in SHOW by now): this checks
        # only what the constant itself controls.
        ann2 = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                 state_provider=lambda: "STANDBY")
        ann2.play(A.CANCELLATION, "Andy", "rack screen")
        ann2.on_show_started("SHOW")
        check(ann2.playing == A.CANCELLATION,
              "with the constant off, a show starting must not touch "
              "what is playing")
    finally:
        A.SHOW_START_STOPS_ANNOUNCEMENT = old
    print("  ok")


def test_announce_stall_watchdog():
    section("announcements: a device that stops answering is caught and "
            "marked failed, not stuck forever")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    sd = FakeSD()
    clock_box = [0.0]
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "STANDBY",
                            clock=lambda: clock_box[0])
    svc.play(A.DELAYED, "Andy", "rack screen")
    stream = sd.output_streams[-1]
    stream.pump(256)          # some real audio came out
    stream.pump(256)
    check(svc.playing == A.DELAYED,
          "setup: still playing after two real callbacks")

    # The device dies: the backend simply stops calling back. Nothing
    # about the fake stream itself changes -- that IS the failure mode
    # (audit13_stuck_on_output_error.py). Time passes with no more
    # callbacks at all.
    clock_box[0] += A.STALL_S + 1.0
    status = svc.status()
    check(status["playing"] is None,
          "a device that stopped answering must not stay 'playing' "
          "forever")
    check(any(r["outcome"] == "failed" for r in status["journal"]),
          f"the stall must be journalled as a failure: {status['journal']}")
    check(svc.playing is None, "the one-at-a-time lock must be released")
    svc.play(A.CANCELLATION, "Andy", "rack screen")
    check(svc.playing == A.CANCELLATION,
          "a different announcement must be playable again once the "
          "stall is caught")
    print("  ok")


def test_announce_callback_status_errors():
    section("announcements: repeated callback errors are also caught, "
            "even while the device keeps answering")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    sd = FakeSD()
    clock_box = [0.0]
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "STANDBY",
                            clock=lambda: clock_box[0])
    svc.play(A.DELAYED, "Andy", "rack screen")
    stream = sd.output_streams[-1]
    for _ in range(A.CALLBACK_ERROR_LIMIT):
        stream.pump(64, status=1)
        clock_box[0] += 0.01          # well under STALL_S: not a stall
    status = svc.status()
    check(status["playing"] is None,
          "enough reported problems in a row must also be caught, even "
          "though the device kept calling back")
    check(any(r["outcome"] == "failed"
             and "reported a problem" in r["text"]
             for r in status["journal"]),
          f"the reason must say it was reported errors, not a stall: "
          f"{status['journal']}")
    print("  ok")


def test_announce_minor_hardening():
    section("announcements: size and duration caps, dash-free text, "
            "channels dropped are logged")
    A = _ann()
    work = tempfile.mkdtemp()

    long_path = os.path.join(work, "long.wav")
    _ann_write_wav(long_path, seconds=A.MAX_LENGTH_S + 1, rate=200)
    st = A.AnnounceService._probe_file(long_path)
    check(not st["available"] and "s long" in st["reason"],
          f"over the length cap must be unavailable: {st}")

    small_path = os.path.join(work, "small.wav")
    _ann_write_wav(small_path, seconds=1.0, rate=8000)
    real_cap = A.MAX_FILE_BYTES
    A.MAX_FILE_BYTES = 100          # smaller than the file just written
    try:
        st2 = A.AnnounceService._probe_file(small_path)
    finally:
        A.MAX_FILE_BYTES = real_cap
    check(not st2["available"] and "MB" in st2["reason"],
          f"over the byte cap must be unavailable: {st2}")
    ok_path = os.path.join(work, "ok.wav")
    _ann_write_wav(ok_path, seconds=1.0)
    st3 = A.AnnounceService._probe_file(ok_path)
    check(st3["available"], "an ordinary file under both caps is fine")

    class _BoomSD:
        def __init__(self):
            class _Default:
                device = (0, 0)
            self.default = _Default()

        def query_devices(self):
            raise RuntimeError("PortAudio failed — device busy")

    work2, cfg2, _lengths2 = _ann_workdir()
    svc2 = A.AnnounceService(cfg2, sd=_BoomSD(), operators_folder=work2,
                             state_provider=lambda: "STANDBY")
    try:
        svc2.play(A.CANCELLATION, "Andy", "rack screen")
        check(False, "a broken audio system must refuse the press")
    except ValueError as e:
        check("—" not in str(e) and "–" not in str(e),
              f"an em or en dash from a third-party error must be "
              f"scrubbed: {e!r}")

    work3, cfg3, _lengths3 = _ann_workdir()
    _ann_write_wav(os.path.join(work3, "delayed.wav"), seconds=1.0,
                   channels=2)

    class _MonoSD(FakeSD):
        def __init__(self):
            super().__init__()
            self.devices = [{"name": "MOTU M4", "max_input_channels": 4,
                            "max_output_channels": 1,
                            "default_samplerate": 48000, "hostapi": 0}]
    svc3 = A.AnnounceService(cfg3, sd=_MonoSD(), operators_folder=work3,
                             state_provider=lambda: "STANDBY")
    svc3.play(A.DELAYED, "Andy", "rack screen")
    check(any(r["reason"] == "channels dropped" for r in svc3.journal),
          f"playing a 2-channel file on a 1-channel device must log a "
          f"note: {list(svc3.journal)}")

    # The _emit() backstop: even text this module did not build from a
    # path or an exception (a call site that forgot its own _clean(), the
    # way load_operators() once did) must come out of the journal clean.
    row = svc3._emit(actor="system", action="test", outcome="note",
                     reason="a — dash", text="another – dash",
                     state=None)
    _no_dashes(row["reason"], "_emit's own reason backstop")
    _no_dashes(row["text"], "_emit's own text backstop")
    print("  ok")


