def test_announce_show_start_hook_never_touches_the_stream():
    section("announcements: the show-start hook only flips in-memory "
            "state, it never calls into the output stream itself")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()

    class SlowCloseStream:
        def start(self):
            pass

        def stop(self):
            time.sleep(2.0)   # would hang THIS test if ever actually called

        def close(self):
            pass

    class SlowSD:
        def __init__(self):
            self.devices = [{"name": "MOTU M4", "max_output_channels": 2,
                            "default_samplerate": 8000}]

            class _Default:
                device = (None, None)
            self.default = _Default()

        def query_devices(self):
            return self.devices

        def OutputStream(self, **kw):
            return SlowCloseStream()

    svc = A.AnnounceService(cfg, sd=SlowSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    svc.play(A.DELAYED, "Andy", "rack screen")
    # Finished on its own, but unnoticed: nobody has polled status(),
    # Play or Stop since, exactly the case that used to reach
    # _finish() -> stream.stop() from inside the hook.
    svc._player.frames_written = svc._player.total_frames
    svc._player.done = True

    t0 = time.time()
    svc.on_show_started("SHOW")
    elapsed = time.time() - t0
    # Half the hang: a hook that reached stop() takes 2 s or more, a hook
    # that did not takes milliseconds, and a slow runner's hiccup is not 1 s.
    check(elapsed < 1.0,
          f"on_show_started must never call into the output stream "
          f"(stop() here deliberately hangs for 2 s): took {elapsed:.2f} s"
          f" (audit13b_scheduler_stall.py)")
    check(svc._player is not None
          and svc._player.stop_reason == "a show started",
          "it must still record why, for whatever settles it later")
    check(svc.playing == A.DELAYED,
          "the actual teardown is left to announce.py's own path (a "
          "status poll, Play, Stop, the stall watchdog), never the hook "
          "itself")
    print("  ok")


def test_schedule_hook_runs_outside_service_lock():
    section("scheduler: on_show_started is called strictly after "
            "Service.lock is released, never while nested inside it")
    S = _sched()
    if S is None:
        return
    from ltcplay import schedule_service as SV
    work = tempfile.mkdtemp()
    path = os.path.join(work, SV.RULE_FILE)
    # first_start 17:30, not the shared _sched_doc()'s 17:00: the slot this
    # test fires is 17:50, and it has to actually land on a real boundary.
    doc = {"timezone": "America/Denver",
           "season": {"first_date": "2026-11-14", "last_date": "2027-01-02"},
           "weekly": {"sat": {"first_start": "17:30", "interval_min": 20,
                              "last_end": "22:00"}},
           "exceptions": {}, "show_len_s": 440, "guard_s": 120,
           "late_grace_s": 0}
    SV.save_rule(path, doc)
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(path, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=work)
    svc.tick()
    check(svc.machine.state == S.STANDBY,
          f"setup: expected STANDBY, got {svc.machine.state}")

    HANG_S = 1.0
    calls = []
    release = threading.Event()

    def slow_hook(state, reason=None):
        calls.append(state)
        # A deliberately slow hook, standing in for ANY future hook that
        # is not as careful as announce.py's own about never touching a
        # stream: schedule_service.py must not trust that. It must simply
        # never let a hook run while Service.lock is held, by anyone, at
        # any depth (audit13b_scheduler_stall.py). It stays stuck until
        # this test lets it go, after the checks below, so a tick() or a
        # lock that waited for it waits the whole HANG_S + 5 s, never
        # something a slow runner could also take.
        release.wait(HANG_S + 5)

    svc.on_show_started = slow_hook
    now[0] = _den(S, 17, 50, 0)

    lock_wait = {}

    def other_thread():
        t0 = time.monotonic()
        with svc.lock:
            pass
        lock_wait["s"] = time.monotonic() - t0

    t0 = time.monotonic()
    tick_thread = threading.Thread(target=svc.tick)
    tick_thread.start()
    # The hook is running on its own, well outside svc.lock, by the time
    # it has actually been called -- if it were not, a thread wanting the
    # same lock would simply queue up behind whichever one holds it.
    check(wait_for(lambda: calls, timeout=2.0),
          "setup: the hook must actually run")
    other = threading.Thread(target=other_thread)
    other.start()
    tick_thread.join(timeout=HANG_S + 5)
    tick_elapsed = time.monotonic() - t0
    other.join(timeout=HANG_S + 5)

    check(svc.machine.state == S.SHOW,
          f"setup: expected the slot to fire into SHOW, got "
          f"{svc.machine.state}")
    check(calls == [S.SHOW],
          f"the hook must fire exactly once, with the new state: {calls}")
    check(tick_elapsed < 3.0,
          f"tick() must not wait for the hook it queued: took "
          f"{tick_elapsed:.2f} s (the hook itself is stuck for "
          f"{HANG_S + 5:g} s)")
    check(lock_wait.get("s", 999) < 3.0,
          f"a separate thread wanting Service.lock (Abort, Hold, Start "
          f"now, any status poll) must not wait behind a slow hook: "
          f"waited {lock_wait.get('s')} s")
    release.set()
    print("  ok")


def test_announce_reentrant_claim_does_not_orphan_a_stream():
    section("announcements: a stale, superseded Play attempt can never "
            "overwrite a later one's live stream")
    A = _ann()
    work, cfg, _lengths = _ann_workdir(device="Sound Blaster Play! 3")

    class FakeStream:
        _n = 0

        def __init__(self):
            FakeStream._n += 1
            self.id = FakeStream._n
            self.started = self.stopped = self.closed = False

        def start(self):
            self.started = True

        def stop(self):
            self.stopped = True

        def close(self):
            self.closed = True

    class _SD:
        def __init__(self):
            self.devices = [{"name": "Sound Blaster Play! 3",
                            "max_output_channels": 2,
                            "default_samplerate": 8000}]

            class _Default:
                device = (None, None)
            self.default = _Default()
            self.streams = []

        def query_devices(self):
            return self.devices

        def OutputStream(self, device=None, channels=None,
                         samplerate=None, blocksize=None, dtype=None,
                         callback=None):
            s = FakeStream()
            self.streams.append(s)
            return s

    sd = _SD()
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "STANDBY")
    real_decode = svc._decode
    release_t1 = threading.Event()
    t1_blocked = threading.Event()
    calls = {"n": 0}

    def controlled_decode(ann_id):
        calls["n"] += 1
        if calls["n"] == 1:
            t1_blocked.set()
            release_t1.wait(timeout=5)
        return real_decode(ann_id)

    svc._decode = controlled_decode
    errors = []

    def t1_play():
        try:
            svc.play(A.DELAYED, "Andy", "rack screen")
        except Exception as e:
            errors.append(e)

    t1 = threading.Thread(target=t1_play)
    t1.start()
    check(t1_blocked.wait(timeout=5), "setup: T1 reached its blocked decode")
    check(svc.playing == A.DELAYED and svc._player is None,
          "setup: T1 has claimed it, but built nothing yet")

    # A legitimate Stop while T1's claim is still outstanding, exactly the
    # interleaving the fix's own design is meant to allow.
    svc.stop("Andy", "rack screen")
    check(svc.playing is None, "Stop clears the claim mid-decode")

    # A second, independent press for the SAME id, fully synchronous.
    svc.play(A.DELAYED, "Andy", "rack screen")
    check(svc.playing == A.DELAYED, "a fresh press for the same id plays")
    live_stream = svc._stream

    # Now let T1's stale decode finish and race to reacquire the lock.
    release_t1.set()
    t1.join(timeout=5)
    check(bool(errors),
          "T1's stale attempt must be refused, not silently swallowed")
    check(errors and "stopped and played again" in str(errors[0]),
          f"and must say so, in a sentence: {errors}")
    check(svc._stream is live_stream,
          f"the live stream operators and the page believe is playing "
          f"must be untouched by the stale attempt: now stream #"
          f"{svc._stream.id if svc._stream else None}, expected #"
          f"{live_stream.id}")
    check(live_stream.started and not live_stream.stopped
          and not live_stream.closed,
          "the live stream must still be running")
    check(len(sd.streams) == 1,
          f"T1's stale attempt must never open a device stream at all "
          f"once it is superseded, not open-then-close: "
          f"{len(sd.streams)} opened (audit13b_reentrant_claim.py)")
    print("  ok")


def test_announce_interlock_matrix():
    section("announcements: every scheduler state, with a state provider but "
            "no Hold wired: every announcement plays (nothing can Hold, and "
            "the schedule's state is never a reason to refuse; Jeff's field "
            "report, 2026-10-28)")
    from ltcplay import schedule as sch_mod
    A = _ann()
    states = (sch_mod.BOOT, sch_mod.IDLE, sch_mod.STANDBY, sch_mod.SHOW,
              sch_mod.PAUSED, sch_mod.CLOSING, sch_mod.OFF, sch_mod.HOLD)
    check(len(set(states)) == 8,
          "the matrix must cover all 8 scheduler states")
    check(not hasattr(A, "interlock_refusal"),
          "there is no interlock any more: nothing refuses on state alone")
    # Stop is the operator's way out of SHOW or PAUSED in the real machine
    # (Abort removed, 2026-10-30).
    check(not hasattr(sch_mod, "ABORT") and
          sch_mod.ALLOWED[sch_mod.STOP_SHOW] ==
          frozenset((sch_mod.SHOW, sch_mod.PAUSED)),
          "Stop must be exactly the exit from SHOW and PAUSED")
    work, cfg, _lengths = _ann_workdir()
    for state in states + (None,):
        svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                state_provider=(lambda s=state: s))
        check(svc.hold_requester is None, "setup: no scheduler wired")
        for aid in A.IDS:
            r = svc.play(aid, "Andy", "rack screen")
            check(svc.playing == aid,
                  f"{state}, no hold_requester: {aid} must be allowed to "
                  f"play")
            check(r["playing"]["held_schedule"] is False,
                  f"{state}: nothing held: {r['playing']}")
            svc.stop("Andy", "rack screen")
            check(svc.playing is None, "Stop must clear it for the next id")
    print("  ok")


def test_announce_hold_between_shows():
    section("announcements: between shows, Play Holds the schedule first "
            "(the same path the operator's own Hold uses), then plays, "
            "and the next show does not start at its time")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY,
          f"setup: intermission running, waiting for the next slot: "
          f"{svc.machine.state}")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement

    r = ann.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"]["id"] == A.DELAYED,
          f"the announcement must actually play: {r}")
    check(svc.machine.state == S.HOLD,
          f"between shows, Hold is what Play must trigger first: "
          f"{svc.machine.state}")
    # The journal line for the Hold itself carries the SAME who/screen the
    # Play press used, exactly as the operator's own Hold would, and reads
    # as held FOR the announcement (review round 2, 2026-09-26:
    # audit15_journal_noise2.py), not as an indistinguishable operator
    # Hold press.
    hold_lines = [r for r in svc.journal
                 if r.get("action") == S.HOLD_ON]
    check(hold_lines and hold_lines[0]["who"] == "Andy"
          and hold_lines[0]["screen"] == "rack screen",
          f"the Hold the announcement triggered must be attributed to the "
          f"SAME operator and screen as the Play press: {hold_lines}")
    check(hold_lines and "played the Delayed announcement" in
          hold_lines[0]["text"],
          f"the Hold's own journal line must name the announcement, not "
          f"just say 'pressed Hold': {hold_lines}")

    # The next show's time passes while held: it must not fire.
    now[0] = _den(S, 17, 55)
    svc.tick()
    check(svc.machine.state == S.HOLD, "still on hold")
    slot2 = svc.machine.slot(2)
    check(slot2.status == S.DELAYED,
          f"the next show's time passed during the Hold, so it waits "
          f"instead of starting: {slot2.status} {slot2.reason}")
    ann.stop("Andy", "rack screen")
    print("  ok")


def test_announce_hold_during_show():
    section("announcements: during a show, Play plays over the show and "
            "Holds, pauses and stops nothing (Jeff, 2026-10-26: Hold is a "
            "schedule pause; the operator ends a show with Stop)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 30, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.SHOW,
          f"setup: a show is running at its start time: {svc.machine.state}")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    asked = []

    def hold(who, screen, detail=None):
        asked.append((who, screen, detail))
        return svc.hold_for_announcement(who, screen, detail=detail)
    ann.hold_requester = hold
    ann.hold_still_claimed = svc.hold_still_claimed
    journal_before = len(svc.journal)

    r = ann.play(A.CANCELLATION, "Andy", "rack screen")
    check(r["playing"]["id"] == A.CANCELLATION
          and r["playing"]["held_schedule"] is False,
          f"the announcement must play over the running show: {r}")
    check(svc.machine.state == S.SHOW,
          f"during a show nothing is paused: {svc.machine.state}")
    check(asked == [], f"no Hold may even be asked for during a show: "
                       f"{asked}")
    check(not [row for row in list(svc.journal)[journal_before:]
               if row.get("action") == S.HOLD_ON],
          "no Hold line in the schedule's journal")
    started = [row for row in r["journal"] if row["outcome"] == "started"]
    check(started and "nothing was paused or stopped" in
          started[0]["text"], f"the journal says it played over the "
                              f"show: {started}")
    _no_dashes(started[0]["text"] if started else "", "play over show")
    ann.stop("Andy", "rack screen")
    check(svc.machine.state == S.SHOW,
          f"Stop on the announcement stops only its audio: "
          f"{svc.machine.state}")

    # Paused by the operator's own Hold: still a show; it plays, and the
    # show stays exactly as paused as the operator left it.
    with svc._locked():
        svc._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                           screen="Rack"))
    check(svc.machine.state == S.PAUSED, "setup: the operator paused it")
    r = ann.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"]["id"] == A.DELAYED and asked == []
          and svc.machine.state == S.PAUSED,
          f"over a paused show: plays, asks no Hold: {asked} "
          f"{svc.machine.state}")
    ann.stop("Andy", "rack screen")
    print("  ok")


def test_announce_hold_refused_still_plays():
    section("announcements: with the REAL scheduler, a Hold it refuses (the "
            "night is over) or cannot take (no schedule file) never refuses "
            "the announcement: it plays with nothing held, and the press "
            "says so in one line (Jeff's field report, 2026-10-28)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "18:00"}},
        exceptions={}))
    now = [_den(S, 23, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state in (S.CLOSING, S.OFF),
          f"setup: the night is over: {svc.machine.state}")
    # No schedule file at all: the scheduler loads with no machine.
    nwork = tempfile.mkdtemp()
    none_svc = SV.Service(os.path.join(nwork, SV.RULE_FILE),
                          clock=lambda: now[0], ntp_query=lambda: 0.0,
                          state_dir=nwork)
    none_svc.tick()
    check(none_svc.machine is None, "setup: no schedule loaded")
    for sv, what in ((svc, "the night is over"),
                     (none_svc, "no schedule file")):
        before = sv.machine.state if sv.machine else None
        ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                state_provider=lambda sv=sv:
                                    sv.machine.state if sv.machine else None)
        sv.on_show_started = ann.on_show_started
        ann.hold_requester = sv.hold_for_announcement
        ann.hold_still_claimed = sv.hold_still_claimed
        for aid in A.IDS:
            try:
                r = ann.play(aid, "Andy", "rack screen")
            except ValueError as e:
                check(False, f"{what}: {aid} was refused: {e}")
                continue
            p = r["playing"] or {}
            check(p.get("id") == aid and p.get("held_schedule") is False,
                  f"{what}: {aid} plays, nothing held: {p}")
            check("No hold was possible" in (p.get("note") or ""),
                  f"{what}: one line says no hold was possible: {p}")
            _no_dashes(p.get("note") or "", f"{what} note")
            check((sv.machine.state if sv.machine else None) == before,
                  f"{what}: the schedule is not changed by it")
            ann.stop("Andy", "rack screen")
    print("  ok")


def test_announce_stays_held_after_it_ends():
    section("announcements: when the announcement ends, the system STAYS "
            "on Hold until an operator presses Resume; nothing resumes "
            "by itself")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY, "setup: between shows")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement

    ann.play(A.CANCELLATION, "Andy", "rack screen")
    check(svc.machine.state == S.HOLD, "setup: the schedule is held")
    # The announcement finishes on its own (a natural end, not a Stop).
    ann._player.done = True
    ann._settle()
    check(ann.playing is None, "the announcement itself must clear")
    check(svc.machine.state == S.HOLD,
          f"the schedule must STAY held after the announcement ends: "
          f"{svc.machine.state}")
    # More time passing changes nothing by itself.
    now[0] = _den(S, 18, 5)
    svc.tick()
    check(svc.machine.state == S.HOLD,
          f"nothing resumes by itself, however much time passes: "
          f"{svc.machine.state}")
    # Only an operator's own Resume moves it on.
    svc._apply(S.Event(S.RESUME, "operator", who="Andy",
                       screen="rack screen"))
    check(svc.machine.state != S.HOLD,
          f"an operator's Resume, and only that, carries the schedule on: "
          f"{svc.machine.state}")
    print("  ok")


def test_announce_resume_wins_over_second_hold_request():
    section("announcements: an operator's Resume, pressed while an "
            "announcement is still loading, wins outright -- the second "
            "check never re-Holds the show it was just resumed from "
            "(review round 2, 2026-09-26: audit15_resume_race.py)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    _ann_write_wav(os.path.join(work, "cannot_continue.wav"), seconds=1.0)
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY, "setup: between shows")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement
    ann.hold_still_claimed = svc.hold_still_claimed

    decode_paused = threading.Event()
    resume_done = threading.Event()
    real_decode = ann._decode

    def slow_decode(ann_id):
        decode_paused.set()
        resume_done.wait(timeout=5)
        return real_decode(ann_id)

    ann._decode = slow_decode
    result = {}

    def do_play():
        try:
            result["status"] = ann.play(A.CANNOT_CONTINUE, "Jeff",
                                        "Announce Panel")
        except ValueError as e:
            result["error"] = str(e)

    t = threading.Thread(target=do_play, daemon=True)
    t.start()
    try:
        check(decode_paused.wait(timeout=5),
              "setup: the announcement thread must reach the file read")
        check(wait_for(lambda: svc.machine.state == S.HOLD, timeout=2.0),
              f"setup: the FIRST Hold request must hold the schedule: "
              f"{svc.machine.state}")
        # The operator, on a different screen, presses Resume -- a real,
        # independent action -- while the announcement is still mid-decode.
        with svc._locked():
            out = svc._apply(S.Event(S.RESUME, "operator", who="Andy",
                                     screen="Rack"))
        check(not out.refused, f"setup: Resume must be accepted: "
                               f"{out.refused}")
        check(svc.machine.state != S.HOLD,
              f"the operator's Resume must take effect immediately, not "
              f"wait for the announcement: {svc.machine.state}")
    finally:
        resume_done.set()
        t.join(timeout=5)

    p = (result.get("status") or {}).get("playing") or {}
    check(p.get("id") == A.CANNOT_CONTINUE and
          p.get("held_schedule") is False and
          "resumed while it loaded" in (p.get("note") or ""),
          f"the announcement still plays (it is independent of the "
          f"schedule), with nothing held, and says the schedule was "
          f"resumed: {result}")
    check(svc.machine.state != S.HOLD,
          f"the operator's Resume must still hold, never silently undone "
          f"by the announcement's own second check: {svc.machine.state}")
    ann.stop("Jeff", "Announce Panel")
    print("  ok")


def test_announce_resume_then_rehold_still_refuses():
    section("announcements: Resume immediately followed by a FRESH Hold "
            "(the state looks the same again, PAUSED, but it is a "
            "DIFFERENT claim) must still refuse a stale announcement "
            "attempt -- this is exactly why the second check compares an "
            "epoch, not just the state (review round 2, 2026-09-26: "
            "\"Resume then Hold again should still refuse this attempt\")")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    _ann_write_wav(os.path.join(work, "cannot_continue.wav"), seconds=1.0)
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY, "setup: between shows")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement
    ann.hold_still_claimed = svc.hold_still_claimed

    decode_paused = threading.Event()
    resume_done = threading.Event()
    real_decode = ann._decode

    def slow_decode(ann_id):
        decode_paused.set()
        resume_done.wait(timeout=5)
        return real_decode(ann_id)

    ann._decode = slow_decode
    result = {}

    def do_play():
        try:
            result["status"] = ann.play(A.CANNOT_CONTINUE, "Jeff",
                                        "Announce Panel")
        except ValueError as e:
            result["error"] = str(e)

    t = threading.Thread(target=do_play, daemon=True)
    t.start()
    try:
        check(decode_paused.wait(timeout=5), "setup: reached the file read")
        check(wait_for(lambda: svc.machine.state == S.HOLD, timeout=2.0),
              "setup: the first Hold request must hold the schedule")
        # Resume, then IMMEDIATELY Hold again from someone else (a real
        # scenario: an operator's own Hold press, back to back with the
        # Resume, both real actions the announcement never asked for).
        # State ends up PAUSED again -- the same as the original claim --
        # but this is a DIFFERENT hold, and the stale attempt must still
        # be refused.
        with svc._locked():
            svc._apply(S.Event(S.RESUME, "operator", who="Andy",
                               screen="Rack"))
        with svc._locked():
            svc._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                               screen="Rack"))
        check(svc.machine.state == S.HOLD,
              f"setup: the state must look the same again (HOLD), which "
              f"is exactly what makes this case need the epoch, not just "
              f"the state: {svc.machine.state}")
    finally:
        resume_done.set()
        t.join(timeout=5)

    p = (result.get("status") or {}).get("playing") or {}
    check(p.get("id") == A.CANNOT_CONTINUE and
          p.get("held_schedule") is False,
          f"a stale claim is not this announcement's Hold even though the "
          f"state looks unchanged: it plays, and does not say it held the "
          f"schedule: {result}")
    ann.stop("Jeff", "Announce Panel")
    print("  ok")


def test_announce_on_show_started_reason_new_vs_resume():
    section("announcements: on_show_started's journal wording says WHY "
            "the show is moving -- 'a show started' for a genuinely new "
            "show, 'the show resumed' for a Resume from Hold (review "
            "round 2, 2026-09-26: audit15_resume_fires_showstart.py)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    _ann_write_wav(os.path.join(work, "delayed.wav"), seconds=90.0,
                   rate=8000)
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34, 0)]
    sd = FakeSD()
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY, "setup: intermission running")
    ann = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement
    ann.hold_still_claimed = svc.hold_still_claimed

    # Between shows: Play Holds (HOLD), then the next slot's time arrives
    # -- but the schedule is held, so nothing fires by itself. Resume it
    # by hand via Start now instead, landing the announcement's own show
    # start under the "new show" label.
    ann.play(A.DELAYED, "Andy", "rack screen")
    check(svc.machine.state == S.HOLD, "setup: held between shows")
    stream_a = sd.output_streams[-1]
    # Through _locked(), not a bare _apply(): the on_show_started hook is
    # only ever drained on the outermost exit from _locked() (see
    # Service._locked's own docstring), so a bare _apply() here would
    # queue the hook and never actually run it.
    with svc._locked():
        out = svc._apply(S.Event(S.START_NOW, "operator", who="Andy",
                                 screen="Rack"))
    check(not out.refused and svc.machine.state == S.SHOW,
          f"setup: Start now must fire a genuinely new show: "
          f"{out.refused} {svc.machine.state}")
    check(wait_for(lambda: ann._player is not None
                   and ann._player.stop_reason == "a show started",
                   timeout=2.0),
          "a genuinely new show must fade the announcement out labelled "
          "'a show started'")
    stream_a.pump(int(8000 * A.SHOW_START_FADE_S) + 100)
    status = ann.status()
    check(any(r["outcome"] == "stopped" and r["reason"] == "a show started"
             for r in status["journal"]),
          f"the journal must say 'a show started' for a genuinely new "
          f"show: {status['journal']}")

    # Now the resume case: the operator's own Hold DURING a show (pauses
    # it; an announcement no longer does, Jeff 2026-10-26), play another
    # announcement over the paused show, then Resume while it is still
    # playing.
    now2_ok = svc.machine.state == S.SHOW
    check(now2_ok, "setup: a show is running for the resume case")
    with svc._locked():
        svc._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                           screen="Rack"))
    ann.play(A.CANCELLATION, "Andy", "rack screen")
    check(svc.machine.state == S.PAUSED, "setup: Hold paused the show")
    stream_b = sd.output_streams[-1]
    with svc._locked():
        out2 = svc._apply(S.Event(S.RESUME, "operator", who="Andy",
                                  screen="Rack"))
    check(not out2.refused and svc.machine.state == S.SHOW,
          f"setup: Resume must carry the show on: {out2.refused} "
          f"{svc.machine.state}")
    check(wait_for(lambda: ann._player is not None
                   and ann._player.stop_reason == "the show resumed",
                   timeout=2.0),
          "a Resume from Hold must fade the announcement out labelled "
          "'the show resumed', not 'a show started'")
    stream_b.pump(int(8000 * A.SHOW_START_FADE_S) + 100)
    status2 = ann.status()
    check(any(r["outcome"] == "stopped" and r["reason"] == "the show resumed"
             for r in status2["journal"]),
          f"the journal must say 'the show resumed', not 'a show "
          f"started', for a Resume: {status2['journal']}")
    print("  ok")


def test_announce_claim_wording_is_the_hold_text():
    section("announcements: the Hold an announcement claims reads in the "
            "announcement's own words, exactly, between shows (the real "
            "Play press through the real scheduler) and during a show "
            "(the scheduler's own Hold handed that same claim); an "
            "operator's own Hold keeps its own wording (the full mutation "
            "sweep, 2026-10-27: the claim wording went unused, uncaught)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()

    def service(first_start, at):
        swork = tempfile.mkdtemp()
        spath = os.path.join(swork, SV.RULE_FILE)
        SV.save_rule(spath, _sched_doc(
            weekly={"sat": {"first_start": first_start, "interval_min": 20,
                            "last_end": "23:00"}},
            exceptions={}))
        now = [at]
        svc = SV.Service(spath, clock=lambda: now[0],
                         ntp_query=lambda: 0.0, state_dir=swork)
        svc.tick()
        return svc

    def hold_rows(svc, since):
        return [r for r in list(svc.journal)[since:]
                if r.get("action") == S.HOLD_ON]

    # Between shows: the real Play press claims the Hold; what it asked
    # with is recorded on the way through, never made up here.
    svc = service("17:30", _den(S, 17, 34))
    check(svc.machine.state == S.STANDBY,
          f"setup: between shows: {svc.machine.state}")
    claims = []

    def requester(who, screen, detail=None):
        claims.append((who, screen, detail))
        return svc.hold_for_announcement(who, screen, detail=detail)
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                            if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = requester
    before = len(svc.journal)
    ann.play(A.DELAYED, "Andy", "rack screen")
    ann.stop("Andy", "rack screen")
    check(svc.machine.state == S.HOLD,
          f"setup: the Play press held the schedule: {svc.machine.state}")
    check(len(claims) == 1 and claims[0][:2] == ("Andy", "rack screen")
          and claims[0][2],
          f"setup: the announcement claimed the Hold in its own words: "
          f"{claims}")
    wording = claims[0][2] if claims else ""
    check(wording.startswith("played the ") and
          wording.endswith(" announcement on the rack screen"),
          f"the claim names the announcement and the screen: {wording!r}")
    rows = hold_rows(svc, before)
    want = (f"Andy {wording}. No show starts by itself until Resume; a "
            f"show whose time passes meanwhile is delayed and waits for "
            f"Start now.")
    check(len(rows) == 1 and rows[0]["text"] == want,
          f"between shows, the Hold reads in the announcement's own "
          f"words, exactly:\n    want {want!r}\n    got  "
          f"{[r['text'] for r in rows]}")
    check(rows and "pressed Hold" not in rows[0]["text"],
          f"never as an operator's Hold press: {rows}")

    # During a show: a running show is never paused by an announcement
    # (Jeff, 2026-10-26), so the scheduler itself is handed that same claim
    # and must read it the same way: in the claim's words, the show named.
    svc2 = service("19:00", _den(S, 20, 0))
    check(svc2.machine.state == S.SHOW and svc2.machine.running,
          f"setup: a show running: {svc2.machine.state}")
    n = svc2.machine.running
    before = len(svc2.journal)
    with svc2._locked():
        out = svc2._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                                  screen="rack screen", detail=wording))
    check(not out.refused and svc2.machine.state == S.PAUSED,
          f"setup: the claim pauses the show: {out.refused} "
          f"{svc2.machine.state}")
    rows = hold_rows(svc2, before)
    want = (f"Andy {wording}. Show {n} is held for it: flame cues zeroed, "
            f"lasers blanked, music fading out. Resume carries on from "
            f"there.")
    check(len(rows) == 1 and rows[0]["text"] == want,
          f"during a show, the Hold reads in the announcement's own "
          f"words, exactly:\n    want {want!r}\n    got  "
          f"{[r['text'] for r in rows]}")

    # The pure step agrees, and the operator's own Hold (no claim wording)
    # keeps its own words in both places.
    for first, now, claimed, plain in (
            ("19:00", _den(S, 20, 0), "Show", "during show"),
            ("17:30", _den(S, 17, 34), "No show starts", "No show starts")):
        m = service(first, now).machine
        mine = S.step(m, S.Event(S.HOLD_ON, "operator", who="Andy",
                                 screen="rack screen"), now)
        theirs = S.step(m, S.Event(S.HOLD_ON, "operator", who="Andy",
                                   screen="rack screen", detail=wording),
                        now)
        mt = [e.text for e in mine.log if e.action == S.HOLD_ON]
        tt = [e.text for e in theirs.log if e.action == S.HOLD_ON]
        check(len(tt) == 1 and tt[0].startswith(f"Andy {wording}. ") and
              claimed in tt[0] and "pressed Hold" not in tt[0],
              f"{m.state}: the claimed Hold reads in the claim's words: "
              f"{tt}")
        check(len(mt) == 1 and mt[0].startswith("Andy pressed Hold") and
              plain in mt[0] and wording not in mt[0],
              f"{m.state}: the operator's own Hold keeps its own words: "
              f"{mt}")
    print("  ok")


def test_announce_hold_for_announcement_no_noise_when_already_held():
    section("announcements: hold_for_announcement never writes a "
            "'refused' line for the routine case of asking for Hold when "
            "the schedule is already held or paused (review round 2, "
            "2026-09-26: audit15_journal_noise.py / "
            "audit15_journal_noise2.py)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "19:00", "interval_min": 20,
                        "last_end": "23:00"}},
        exceptions={}))
    now = [_den(S, 20, 0, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.SHOW, "setup: a show fired at boot")

    # A running show is never paused by an announcement (Jeff,
    # 2026-10-26): the claim succeeds, holds nothing, writes nothing.
    before = len(svc.journal)
    r0, _e0 = svc.hold_for_announcement(
        "Jeff", "Announce Panel", detail="played the Delayed "
        "announcement on the Announce Panel")
    check(r0 is None and svc.machine.state == S.SHOW and
          len(svc.journal) == before,
          f"a claim on a running show holds nothing: {r0} "
          f"{svc.machine.state} {list(svc.journal)[before:]}")
    # The operator's own Hold pauses it; claims on the paused show are
    # routine.
    with svc._locked():
        svc._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                           screen="Rack"))
    r1, epoch1 = svc.hold_for_announcement(
        "Jeff", "Announce Panel", detail="played the Cancellation "
        "announcement on the Announce Panel")
    check(r1 is None and svc.machine.state == S.PAUSED,
          f"setup: a claim on the paused show succeeds: {r1} "
          f"{svc.machine.state}")
    before = len(svc.journal)
    r2, epoch2 = svc.hold_for_announcement(
        "Jeff", "Announce Panel", detail="played the Cannot continue "
        "announcement on the Announce Panel")
    check(r2 is None, f"the second, routine claim must also succeed: {r2}")
    check(epoch1 == epoch2,
          f"asking again while already held must NOT bump the epoch: "
          f"{epoch1} {epoch2}")
    check(len(svc.journal) == before,
          f"the routine second claim must add NOTHING to the journal, "
          f"not even a refused line: "
          f"{list(svc.journal)[len(svc.journal) - before:]}")
    check(not any("refused" in (r.get("text") or "").lower()
                 for r in svc.journal),
          f"no 'refused' line must appear anywhere for this routine "
          f"sequence: {list(svc.journal)}")
    print("  ok")


