def _sched_and_service_modules():
    from ltcplay import schedule as S
    from ltcplay import schedule_service as SV
    return S, SV


def test_announce_single_flight():
    section("announcements: one at a time, a second press is refused, "
            "not queued")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "IDLE")
    svc.play(A.DELAYED, "Andy", "rack screen")
    check(svc.playing == A.DELAYED, "the first press should start playing")
    try:
        svc.play(A.CANCELLATION, "Andy", "rack screen")
        check(False, "a second press while one plays must be refused")
    except ValueError as e:
        check("already playing" in str(e), f"the refusal must say so: {e}")
    check(svc.playing == A.DELAYED,
          "the second press must not queue or replace the first")
    try:
        svc.play(A.DELAYED, "Andy", "rack screen")
        check(False, "pressing the SAME one again while it plays must "
                     "also be refused")
    except ValueError as e:
        check("already playing" in str(e), f"{e}")
    svc.stop("Andy", "rack screen")
    check(svc.playing is None, "Stop must clear the playing announcement")
    svc.play(A.CANCELLATION, "Andy", "rack screen")
    check(svc.playing == A.CANCELLATION,
          "after Stop, a different one may play")
    print("  ok")


def test_announce_operator_validation():
    section("announcements: Play and Stop both name an operator on the "
            "list and a screen, like the scheduler")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()

    def svc():
        return A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                 state_provider=lambda: "IDLE")

    for who, screen, must in (("", "rack screen", "who pressed it"),
                              ("Andy", "", "which screen"),
                              ("  ", " ", "who pressed it and which "
                                          "screen"),
                              ("Bob", "rack screen",
                               "not on the operator list")):
        s = svc()
        try:
            s.play(A.DELAYED, who, screen)
            check(False, f"Play with who={who!r} screen={screen!r} must "
                         f"be refused")
        except ValueError as e:
            check(must in str(e), f"Play with who={who!r} screen={screen!r} "
                                  f"must name what is wrong: {e}")
        check(s.playing is None, "a refused Play must not start")
        s2 = svc()
        s2.play(A.DELAYED, "Andy", "rack screen")
        try:
            s2.stop(who, screen)
            check(False, f"Stop with who={who!r} screen={screen!r} must "
                         f"be refused")
        except ValueError as e:
            check(must in str(e), f"Stop with who={who!r} screen={screen!r} "
                                  f"must name what is wrong: {e}")
        check(s2.playing == A.DELAYED,
              "a refused Stop must not touch what is playing")
    for who in ("Jeff", "andy", " Andy "):
        s = svc()
        s.play(A.DELAYED, who, "rack screen")
        check(s.playing == A.DELAYED,
              f"{who!r} is on the default operator list")
    other = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                              state_provider=lambda: "IDLE")
    other.operators = ("Casey",)
    try:
        other.play(A.DELAYED, "Andy", "rack screen")
        check(False, "once the list is Casey only, Andy must be refused")
    except ValueError as e:
        check("Casey" in str(e), f"{e}")
    other.play(A.DELAYED, "Casey", "rack screen")
    check(other.playing == A.DELAYED, "Casey is on this machine's list")
    print("  ok")


def test_announce_missing_files_at_startup():
    section("announcements: a missing or broken file is caught at "
            "startup, never at the press")
    A = _ann()
    work = tempfile.mkdtemp()
    good = os.path.join(work, "delayed.wav")
    _ann_write_wav(good, seconds=1.0)
    broken = os.path.join(work, "cancellation.wav")
    with open(broken, "wb") as fh:
        fh.write(b"not a wav file at all")
    # cannot_continue.wav is simply never written: missing.
    cfg = {"device": "MOTU M4",
           "files": {"delayed": "delayed.wav",
                    "cancellation": "cancellation.wav",
                    "cannot_continue": "cannot_continue.wav"}}
    path = os.path.join(work, "ltcplay_announce.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(cfg, fh)
    svc = A.AnnounceService(path, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "IDLE")
    by_id = {i["id"]: i for i in svc.status()["announcements"]}
    check(by_id[A.DELAYED]["available"]
          and abs(by_id[A.DELAYED]["length_s"] - 1.0) < 1e-6,
          f"a good file must be available with its real length: "
          f"{by_id[A.DELAYED]}")
    check(not by_id[A.CANCELLATION]["available"]
          and by_id[A.CANCELLATION]["reason"],
          f"a broken WAV must be unavailable with a reason: "
          f"{by_id[A.CANCELLATION]}")
    check(not by_id[A.CANNOT_CONTINUE]["available"]
          and by_id[A.CANNOT_CONTINUE]["missing"] is True
          and by_id[A.CANNOT_CONTINUE]["reason"].startswith(
              "Recording missing:"),
          f"a missing file must say plainly the recording is missing: "
          f"{by_id[A.CANNOT_CONTINUE]}")
    for aid in (A.CANCELLATION, A.CANNOT_CONTINUE):
        try:
            svc.play(aid, "Andy", "rack screen")
            check(False, f"playing an unavailable file ({aid}) must be "
                         f"refused")
        except ValueError as e:
            check("not available" in str(e), f"{e}")
    # Deleting the good file AFTER startup must not change its reported
    # availability: discovery happens once, at startup, never at the press.
    os.remove(good)
    by_id2 = {i["id"]: i for i in svc.status()["announcements"]}
    check(by_id2[A.DELAYED]["available"],
          "availability must never be re-probed after startup")
    print("  ok")


def test_announce_device_missing_renamed_reappearing():
    section("announcements: the output device by name, missing, renamed, "
            "and back")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    sd = FakeSD()
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "IDLE")
    st = svc.status()
    check(st["device_available"], f"MOTU M4 should resolve: {st}")
    removed = sd.devices.pop(1)              # "MOTU M4" is index 1
    check(removed["name"] == "MOTU M4", "test setup: removed the right one")
    st2 = svc.status()
    check(not st2["device_available"]
          and "not attached" in st2["device_reason"],
          f"a missing device must say so plainly: {st2}")
    try:
        svc.play(A.DELAYED, "Andy", "rack screen")
        check(False, "playing on a missing device must be refused")
    except ValueError as e:
        check("not attached" in str(e), f"{e}")
    check(svc.playing is None, "a refused play must not start")
    check(sd.output_opened == [],
          "a refused play must never open a stream on some other device: "
          "there is no silent fallback")
    # Plug it back in, at a DIFFERENT index, exactly like a real replug.
    sd.devices.insert(0, removed)
    st3 = svc.status()
    check(st3["device_available"],
          f"a reappeared device must be found by name again: {st3}")
    svc.play(A.DELAYED, "Andy", "rack screen")
    check(svc.playing == A.DELAYED, "it must play now that it is back")
    check(sd.output_opened[-1][0] == 0,
          f"it must open at its NEW index, found by name: "
          f"{sd.output_opened}")
    print("  ok")


def test_announce_progress_and_stop():
    section("announcements: length known before playing, live progress, "
            "Stop cuts it off")
    A = _ann()
    work, cfg, lengths = _ann_workdir()
    sd = FakeSD()
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "STANDBY")
    d = {i["id"]: i for i in svc.status()["announcements"]}
    check(abs(d[A.DELAYED]["length_s"] - lengths[A.DELAYED]) < 1e-6,
          "the length must be known before it is ever played")
    check(svc.status()["playing"] is None, "nothing plays yet")
    svc.play(A.DELAYED, "Andy", "rack screen")
    stream = sd.output_streams[-1]
    check(stream.started, "the output stream must actually be started")
    rate = 8000
    half = int(rate * lengths[A.DELAYED] / 2)
    stream.pump(half)
    st2 = svc.status()
    check(st2["playing"]["id"] == A.DELAYED, "still playing at the halfway "
                                             "point")
    check(abs(st2["playing"]["elapsed_s"] - half / rate) < 1e-6,
          f"progress must reflect exactly the frames handed to the "
          f"device, no clock involved: {st2['playing']}")
    remaining = int(rate * lengths[A.DELAYED]) - half + 10
    stream.pump(remaining)
    st3 = svc.status()
    check(st3["playing"] is None,
          "a finished announcement must clear itself on the next look, "
          "with no operator action and no wall clock")
    check(any(r["outcome"] == "finished" for r in st3["journal"]),
          "the natural finish must be journalled")
    svc.play(A.CANCELLATION, "Andy", "rack screen")
    stream2 = sd.output_streams[-1]
    stream2.pump(100)
    svc.stop("Andy", "rack screen")
    check(svc.playing is None, "Stop must end it immediately")
    check(stream2.stopped and stream2.closed,
          "Stop must actually close the device stream")
    print("  ok")


def test_announce_logging_fields():
    section("announcements: every play, stop, refusal and failure is "
            "logged, in plain English")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()
    svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    svc.play(A.DELAYED, "Andy", "rack screen")                  # started
    try:
        svc.play(A.CANCELLATION, "Andy", "rack screen")         # refused
    except ValueError:
        pass
    svc.stop("Andy", "rack screen")                             # stopped
    svc.stop("Andy", "rack screen")                             # no-op
    sd2 = FakeSD()
    sd2.devices.pop(1)
    svc2 = A.AnnounceService(cfg, sd=sd2, operators_folder=work,
                             state_provider=lambda: "STANDBY")
    try:
        svc2.play(A.DELAYED, "Andy", "rack screen")             # failed
    except ValueError:
        pass
    rows = list(svc.journal) + list(svc2.journal)
    outcomes = {r["outcome"] for r in rows}
    check({"started", "refused", "stopped", "no-op", "failed"} <= outcomes,
          f"every category must appear in the journal: {outcomes}")
    for r in rows:
        check(r["actor"] in ("operator", "system"),
              f"a log row must name an actor: {r}")
        check(bool(r["text"]), f"a log row must have a sentence: {r}")
        _no_dashes(r["text"], "announce journal")
        check("at" in r and r["at"], f"a log row must carry a time: {r}")
        check("show_state" in r, f"a log row must carry the show state "
                                 f"at the time, without exception: {r}")
        if r["action"] in ("play", "stop") and r["outcome"] != "refused":
            check(r["who"], f"an operator action should carry who did "
                            f"it: {r}")
        if r["announcement"]:
            check(r["file"] and r["announcement"] in A.IDS,
                  f"a per-announcement row must carry the file and which "
                  f"one: {r}")
    print("  ok")


def test_announce_routes():
    section("announcements: routes only when configured, wired to the "
            "scheduler when both are")
    A = _ann()
    import json as _json
    import threading as _threading
    import urllib.error
    import urllib.request
    from ltcplay import web as web_mod
    work, cfg, _lengths = _ann_workdir()

    def call(base, route, body=None):
        data = _json.dumps(body).encode() if body is not None else None
        req = urllib.request.Request(
            base + route, data=data,
            method=("POST" if body is not None else "GET"),
            headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=5) as r:
                return r.status, _json.loads(r.read())
        except urllib.error.HTTPError as e:
            return e.code, _json.loads(e.read() or b"{}")

    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work)
    port = _free_port()
    httpd = web_mod.serve(work, port=port, announce=ann)
    t = _threading.Thread(target=httpd.serve_forever,
                          kwargs={"poll_interval": 0.05}, daemon=True)
    t.start()
    base = f"http://127.0.0.1:{port}"
    try:
        check(httpd.schedule is None and httpd.announce is ann,
              "announcements alone, no scheduler")
        code, st = call(base, "/api/announce/status")
        check(code == 200 and len(st["announcements"]) == 3,
              f"GET /api/announce/status: {code} {st}")
        check("blocked" not in st and st["route"]["ok"] and
              st["route"]["kind"] == "device",
              f"with no scheduler wired, nothing reports announcements "
              f"blocked; no show audio runs, so its own output is the "
              f"route: {st}")
        code, got = call(base, "/api/announce/play",
                         {"id": A.DELAYED, "who": "Andy",
                          "screen": "rack screen"})
        check(code == 200 and (got.get("playing") or {}).get("id") ==
              A.DELAYED,
              f"a play with no scheduler plays: {code} {got}")
        call(base, "/api/announce/stop", {"who": "Andy",
                                           "screen": "rack screen"})
        check(callable(ann.show_route),
              "web.serve wires the show audio route provider")
        check(A.AnnounceService.POST_ROUTES ==
              ("/api/announce/play", "/api/announce/stop"),
              "only play and stop can be posted")
        code, _r = call(base, "/api/announce/status", {"id": "x"})
        check(code == 404, "POST to the status route is not a thing")
    finally:
        httpd.shutdown()
        httpd.server_close()

    # Both configured: the announce service reads the scheduler's own
    # state, live, through nothing but the provider web.serve wires up.
    from ltcplay import schedule as S
    from ltcplay import schedule_service as SV
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc())
    now = [_den(S, 18, 4, 12)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    ann2 = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work)
    port = _free_port()
    httpd = web_mod.serve(work, port=port, schedule=svc, announce=ann2)
    t = _threading.Thread(target=httpd.serve_forever,
                          kwargs={"poll_interval": 0.05}, daemon=True)
    t.start()
    base = f"http://127.0.0.1:{port}"
    try:
        check(wait_for(lambda: svc.machine is not None),
              "the scheduler settles")
        code, st = call(base, "/api/announce/status")
        check(code == 200 and st["show_state"] == svc.machine.state,
              f"the announce status must read the SAME state the "
              f"scheduler is in: {st['show_state']} vs "
              f"{svc.machine.state}")
        now[0] = _den(S, 18, 20)
        svc.tick()
        check(svc.machine.state == S.SHOW,
              f"setup: the scheduler should be running a show at 18:20: "
              f"{svc.machine.state}")
        code, ok = call(base, "/api/announce/play",
                        {"id": A.DELAYED, "who": "Andy",
                         "screen": "rack screen"})
        check(code == 200 and ok.get("playing", {}).get("id") == A.DELAYED
              and ok["playing"]["held_schedule"] is False,
              f"a show running: the announcement plays over it, through "
              f"the live link, and Holds nothing: {code} {ok}")
        check(svc.machine.state == S.SHOW,
              f"the show must carry on: an announcement during a show "
              f"never pauses or stops it (Jeff, 2026-10-26): "
              f"{svc.machine.state}")
    finally:
        httpd.shutdown()
        httpd.server_close()
        svc.stop()

    # Not configured at all: every announce route is a plain 404.
    port = _free_port()
    httpd = web_mod.serve(work, port=port)
    t = _threading.Thread(target=httpd.serve_forever,
                          kwargs={"poll_interval": 0.05}, daemon=True)
    t.start()
    base = f"http://127.0.0.1:{port}"
    try:
        check(httpd.announce is None, "no announce config, no service")
        code, _r = call(base, "/api/announce/status")
        check(code == 404, f"GET without --announce is 404, got {code}")
        code, _r = call(base, "/api/announce/play", {"id": A.DELAYED})
        check(code == 404, f"POST without --announce is 404, got {code}")
        code, _r = call(base, "/api/state")
        check(code == 200, "the rest of the page is untouched")
    finally:
        httpd.shutdown()
        httpd.server_close()
    print("  ok")


def test_announce_device_not_set_and_device_missing_refuse_before_hold():
    section("announcements: no output device set yet (the first run's "
            "file) or the device not attached: every press is refused "
            "with a sentence BEFORE any Hold, and the system default is "
            "never used (Jeff, 2026-10-26)")
    A = _ann()
    asked = []

    def hold(who, screen, detail=None):
        asked.append(who)
        return None, 1
    for device, words in (("", "No announcement output is picked"),
                          ("Nothing Called This", "is not attached")):
        work, cfg, _l = _ann_workdir(device=device)
        svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                state_provider=lambda: "STANDBY")
        svc.hold_requester = hold
        svc.hold_still_claimed = lambda epoch: True
        st = svc.status()
        check(svc.error == "" and st["device_set"] is bool(device) and
              st["device_available"] is False and
              all(i["available"] for i in st["announcements"]),
              f"{device!r}: the file loads and the recordings are there; "
              f"only the device is not: {st}")
        try:
            svc.play(A.DELAYED, "Andy", "Rack screen")
            check(False, f"{device!r}: the press must be refused")
        except ValueError as e:
            check(words in str(e), f"{device!r}: said plainly: {e}")
            _no_dashes(str(e), "device refusal")
        check(asked == [] and svc.playing is None,
              f"{device!r}: nothing was held and nothing plays: {asked}")
    print("  ok")


def test_announce_surface_press_and_show_ending_while_loading():
    section("announcements: a surface press (the rack screen or the "
            "Stream Deck, through remote.py) is not looked up on the "
            "operator list; a press over a running show whose show ends "
            "while the file loads still plays, with nothing held, and says "
            "so (announcements are independent of the schedule, Jeff's "
            "field report, 2026-10-28)")
    A = _ann()
    work, cfg, _l = _ann_workdir()
    svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    svc.hold_requester = lambda who, screen, detail=None: (None, 1)
    svc.hold_still_claimed = lambda epoch: True
    try:
        svc.play(A.DELAYED, "Rack screen", "Rack screen")
        check(False, "not a surface: the operator list still applies")
    except ValueError as e:
        check("operator list" in str(e), f"{e}")
    r = svc.play(A.DELAYED, "Rack screen", "Rack screen", surface=True)
    check(r["playing"]["id"] == A.DELAYED and r["playing"]["held_schedule"],
          f"a surface press plays, between shows holding the schedule: {r}")
    try:
        svc.stop("Stream Deck", "Stream Deck")
        check(False, "a Stop not from a surface still needs a listed name")
    except ValueError:
        pass
    svc.stop("Stream Deck", "Stream Deck", surface=True)
    check(svc.playing is None, "a surface Stop stops it")

    state = ["SHOW"]
    asked = []
    svc2 = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                             state_provider=lambda: state[0])
    svc2.hold_requester = lambda who, screen, detail=None: (
        asked.append(who) or (None, 1))
    svc2.hold_still_claimed = lambda epoch: True
    real = svc2._decode

    def decode_then_show_ends(aid):
        state[0] = "STANDBY"
        return real(aid)
    svc2._decode = decode_then_show_ends
    r = svc2.play(A.CANNOT_CONTINUE, "Andy", "Rack screen")
    p = r["playing"] or {}
    check(p.get("id") == A.CANNOT_CONTINUE and
          p.get("held_schedule") is False and
          "show ended while it loaded" in (p.get("note") or ""),
          f"the show ended while loading: it plays, nothing held, said: {p}")
    check(asked == [], f"no Hold was asked for: {asked}")
    svc2.stop("Andy", "Rack screen")
    print("  ok")


def test_announce_remote_routes_rack_screen():
    section("announcements on the rack screen (remote.py): the status "
            "carries the block on the show machine only; one press plays; "
            "a recording missing is a plain refusal; Stop stops only the "
            "sound; never from the network, never on a stale page")
    S = _sched()
    if S is None:
        return
    A = _ann()
    from ltcplay import users as U
    check(U.classify("/api/remote/announce-stop") == "safety" and
          U.classify("/api/remote/announce-play") == "show",
          "Stop is a safety press; Play a show press")
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/status",
                           client=loop)
        check(st == 200 and out["announce"] == {
                  "configured": False, "why": R.remote.ANNOUNCE_OFF},
              f"not configured: the block says so: {out.get('announce')}")
        work, cfg, _l = _ann_workdir()
        os.remove(os.path.join(work, "cannot_continue.wav"))
        ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work)
        sv = R.svc
        ann.state_provider = (lambda: sv.machine.state
                              if sv.machine is not None else None)
        ann.hold_requester = sv.hold_for_announcement
        ann.hold_still_claimed = sv.hold_still_claimed
        R.remote.announce = ann
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/status",
                           client=loop)
        an = out.get("announce") or {}
        by = {i["id"]: i for i in an.get("items") or []}
        check(an.get("configured") and an.get("device_set") and
              an.get("device_available") and
              by[A.CANNOT_CONTINUE]["missing"] is True and
              by[A.DELAYED]["available"] is True,
              f"the block: device there, Cannot continue missing: {an}")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check("announce" not in out, "an iPad's status has no block")
        st, _h, out = R.ask("POST", "/api/remote/announce-play",
                            {"id": A.DELAYED, "seen": R.seen()})
        check(st == 403 and ann.playing is None,
              f"never from the network: {st} {out}")
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/announce-play",
                           {"id": A.DELAYED, "seen": R.seen() - 60_000},
                           client=loop)
        check(st == 409 and out.get("stale") and ann.playing is None,
              f"a stale page's Play is refused: {st} {out}")
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/announce-play",
                           {"id": A.CANNOT_CONTINUE, "seen": R.seen()},
                           client=loop)
        check(st == 409 and "Recording missing" in out.get("error", "")
              and ann.playing is None,
              f"a missing recording is refused plainly: {st} {out}")
        before = sv.machine.state
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/announce-play",
                           {"id": A.DELAYED, "seen": R.seen()},
                           client=loop)
        check(st == 200 and ann.playing == A.DELAYED and
              out["announce"]["playing"]["id"] == A.DELAYED,
              f"one press plays: {st} {out}")
        live = before in ("SHOW", "PAUSED")
        check((sv.machine.state == before) if live else
              (sv.machine.state == "HOLD"),
              f"between shows the schedule is held, during a show nothing "
              f"changes: {before} -> {sv.machine.state}")
        check(("Held" not in out["text"]) and (
                  "Resume" in out["text"] if not live else
                  "nothing was paused" in out["text"]),
              f"the toast says what happened: {out['text']}")
        rows = [r for r in ann.journal if r["outcome"] == "started"]
        check(rows and rows[-1]["who"] == "Rack screen" and
              rows[-1]["screen"] == "Rack screen",
              f"journaled as the surface: {rows[-1:]}")
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/announce-play",
                           {"id": A.CANCELLATION, "seen": R.seen()},
                           client=loop)
        check(st == 409 and "already playing" in out.get("error", ""),
              f"a second press while one plays is refused: {st} {out}")
        held_state = sv.machine.state
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/announce-stop",
                           {"seen": 0}, client=loop)
        check(st == 200 and ann.playing is None and
              sv.machine.state == held_state and
              not hasattr(sv.machine, "abort_latched"),
              f"Stop: only the sound, even from a stale page; the "
              f"schedule stays as it was, nothing latched: {st} {out} "
              f"{sv.machine.state}")
        st, _h, din = _ask(R.httpd, "GET", "/api/remote/deck-input",
                           client=loop)
        da = din.get("announce") or {}
        check(da.get("configured") and da.get("device_ok") and
              da["missing"].get(A.CANNOT_CONTINUE) and
              da["ready"].get(A.DELAYED) and da.get("playing") is None,
              f"the deck reads the same block: {da}")
        for t in (out.get("text", ""), R.remote.ANNOUNCE_OFF):
            _no_dashes(t, "announce route text")
    finally:
        R.close()
    print("  ok")


def test_announce_rack_screen_page_logic():
    section("announcements on the rack screen page: three buttons and "
            "Stop, Recording missing on a button whose file is not on the "
            "PC, Held for announcement while one plays between shows, no "
            "double tap anywhere")
    page = screen_text()
    for el in ('id="ann"', 'id="ann-btns"', 'id="ann-stop"'):
        check(el in page, f"the page has {el}")
    check('annPress("announce-play", {id: b.dataset.ann})' in page and
          'annPress("announce-stop")' in page,
          "one click posts announce-play; Stop posts announce-stop")
    a = page.find("// LOGIC BEGIN")
    b = page.find("// LOGIC END")
    logic = page[a:b]
    check("function announceLook" in logic, "announceLook is pure logic")
    import shutil
    node = shutil.which("node")
    if not node:
        print("  note: node is not here; announceLook checked by reading "
              "only (CI runs it)")
        print("  ok")
        return
    js = logic + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const items = [
  {id:"delayed", name:"Delayed", available:true, missing:false, length_s:12.4},
  {id:"cancellation", name:"Cancellation", available:true, missing:false, length_s:9},
  {id:"cannot_continue", name:"Cannot continue", available:false, missing:true, reason:"Recording missing: x"}];
let L = announceLook(null, null);
t(L.show === false, "no announcements: no block");
L = announceLook({configured:false}, {});
t(L.show === false, "not configured: no block");
const base = {configured:true, ok:true, device:"MOTU M4", device_set:true, device_available:true, items:items, playing:null, over_show:false,
  route:{kind:"device", ok:true, text:"MOTU M4, its own output while the show audio is not running", why:null}};
L = announceLook(base, {configured:true, device:"Booth 16R"});
t(L.show && L.buttons.length === 3, "three buttons");
t(!L.buttons[0].off && L.buttons[0].sub === "12 s", "a ready one is on, with its length: " + JSON.stringify(L.buttons[0]));
t(L.buttons[2].off && L.buttons[2].sub === "Recording missing" && L.buttons[2].missing, "missing: Recording missing, off");
t(L.stopOff && L.banner === "", "nothing playing: Stop off, no banner");
t(/holds the schedule first/.test(L.note), "between shows the note says it holds: " + L.note);
t(/Booth speaker: Booth 16R/.test(L.device), "the booth speaker is named: " + L.device);
t(!/notes found/.test(L.device), "no note count from an engine that sends none: " + L.device);
L = announceLook(base, {configured:true, device:"StudioLive 16R", notes:{expected:23, found:23, missing:[]}});
t(/Booth speaker: StudioLive 16R, 23 of 23 notes found$/.test(L.device), "every note found: " + L.device);
L = announceLook(base, {configured:false, device:"", notes:{expected:23, found:21, missing:["booth_users.wav", "booth_held.wav"]}});
t(/Booth speaker: not set, 21 of 23 notes found; missing booth_users.wav, booth_held.wav$/.test(L.device), "the missing ones named: " + L.device);
L = announceLook(base, {configured:true, device:"X", notes:{expected:23, found:15, missing:["a","b","c","d","e","f","g","h"]}});
t(/15 of 23 notes found; missing a, b, c, d, e, f and 2 more$/.test(L.device), "six named, then how many more: " + L.device);
L = announceLook(Object.assign({}, base, {over_show:true}), {});
t(/plays over it and pauses nothing/.test(L.note), "during a show: " + L.note);
t(/Booth speaker: not set/.test(L.device), "no booth: said");
L = announceLook(Object.assign({}, base, {device_set:false, device:null, device_available:false, device_reason:"No announcement output is picked.", route:{kind:"device", ok:false, text:"", why:"No announcement output is picked."}}), {});
t(L.buttons.every(b => b.off) && L.devBad && /no output of its own is picked/.test(L.device) && /No announcement output/.test(L.note), "no device and no show audio: every button off, said: " + L.device + " / " + L.note);
// Through the show audio (Jeff's field report, 2026-10-28, item 9): on,
// with no output of its own picked, and the line says where it plays.
L = announceLook(Object.assign({}, base, {device_set:false, device:null, device_available:false, route:{kind:"show", ok:true, text:"the show audio, outputs 1 and 2 on StudioLive 16R", why:null}}), {});
t(!L.buttons[0].off && /^Plays on: the show audio, outputs 1 and 2 on StudioLive 16R/.test(L.device) && !L.devBad, "through the show audio: on, said: " + L.device);
L = announceLook(Object.assign({}, base, {route:{kind:"show", ok:false, text:"the show audio, outputs 1 and 2 on StudioLive 16R", why:"The show audio is running, but StudioLive 16R is not open right now (see the Show audio lamp)."}}), {});
t(L.buttons.every(b => b.off) && /not open/.test(L.device) && /Show audio lamp/.test(L.note), "the show audio not open: off, said apart from the lamp: " + L.note);
// Ambiguous name: said plainly, with what to pick.
L = announceLook(Object.assign({}, base, {route:{kind:"device", ok:false, text:"StudioLive WDM 1/2, its own output", why:"StudioLive WDM 1/2 matches 2 outputs on this PC: pick one: StudioLive WDM 1/2 (MME, 2 outputs); StudioLive WDM 1/2 (Windows WASAPI, 2 outputs)."}}), {});
t(L.buttons.every(b => b.off) && /matches 2 outputs on this PC: pick one/.test(L.note), "ambiguous: said: " + L.note);
// The schedule's state never turns a button off (a.blocked is gone).
L = announceLook(Object.assign({}, base, {blocked:"anything", show_state:"OFF"}), {});
t(!L.buttons[0].off, "the night being over never turns them off");
// A press that held nothing says why, from the engine's note.
L = announceLook(Object.assign({}, base, {playing:{id:"delayed", name:"Delayed", held_schedule:false, note:"No hold was possible (The night is over, so there is nothing to hold), so it plays with nothing held."}}), {});
t(L.word === "ANNOUNCEMENT PLAYING" && /No hold was possible/.test(L.banner), "no hold: said: " + L.banner);
// The picker's options.
let O = annOutputOptions([{name:"StudioLive WDM 1/2", hostapi:"MME", channels:2, label:"StudioLive WDM 1/2 (MME, 2 outputs)", same_name:true, picked:false},
  {name:"StudioLive WDM 1/2", hostapi:"Windows WASAPI", channels:2, label:"StudioLive WDM 1/2 (Windows WASAPI, 2 outputs)", same_name:true, picked:false},
  {name:"Speakers", hostapi:"MME", channels:2, label:"Speakers (MME, 2 outputs)", same_name:false, picked:false}], "StudioLive WDM 1/2");
t(O[0].picked && O[0].value === "" && /choose which output/.test(O[0].label), "ambiguous: the top says choose: " + JSON.stringify(O[0]));
t(JSON.parse(O[3].value).hostapi === "Windows WASAPI" && JSON.parse(O[4].value).hostapi === null, "same name: told apart by audio system; a unique one is not: " + JSON.stringify(O));
O = annOutputOptions([{name:"Speakers", hostapi:"MME", channels:2, label:"Speakers (MME, 2 outputs)", same_name:false, picked:true}], "Speakers");
t(O[1].picked && /picked now/.test(O[1].label) && !O[0].picked, "the picked one is selected: " + JSON.stringify(O));
O = annOutputOptions([], "");
t(O.length === 1 && O[0].picked && /only through the show audio/.test(O[0].label), "nothing picked: None: " + JSON.stringify(O));
L = announceLook(Object.assign({}, base, {playing:{id:"delayed", name:"Delayed", held_schedule:true, elapsed_s:3.2, length_s:12.4}}), {});
t(L.word === "HELD FOR ANNOUNCEMENT" && /Delayed \(3 s of 12 s\)/.test(L.banner) && /until Resume/.test(L.banner), "held: " + L.word + " " + L.banner);
t(!L.stopOff && L.buttons.every(b => b.off) && L.buttons[0].on, "while one plays: Stop on, the rest off, it lit");
L = announceLook(Object.assign({}, base, {over_show:true, playing:{id:"cancellation", name:"Cancellation", held_schedule:false}}), {});
t(L.word === "ANNOUNCEMENT PLAYING" && /nothing was paused/.test(L.banner), "over a show: " + L.word + " " + L.banner);
L = announceLook(Object.assign({}, base, {held_failed:{id:"delayed", name:"Delayed", why:"the file could not be read"}}), {});
t(L.word === "HELD, ANNOUNCEMENT FAILED" && /Delayed did not play: the file could not be read/.test(L.banner) && /until Resume/.test(L.banner) && L.stopOff, "held then failed: " + L.word + " " + L.banner);
L = announceLook(Object.assign({}, base, {ok:false, error:"The announcements file is not valid JSON."}), {});
t(L.buttons.every(b => b.off) && /not valid JSON/.test(L.note), "a bad file: every button off, said");
const all = JSON.stringify([announceLook(base, {}), announceLook(Object.assign({}, base, {playing:{id:"delayed", name:"Delayed", held_schedule:true}}), {})]);
t(!/[–—]/.test(all), "no em or en dashes");
console.log(JSON.stringify(out));
"""
    r = _node_js(node, js, capture_output=True, text=True, timeout=60)
    try:
        bad = json.loads(r.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        bad = [f"node failed: {r.stderr[-500:]}"]
    for m in bad:
        check(False, f"announceLook: {m}")

    print("  ok")


def _ann_write_level(path, seconds=1.0, rate=8000, levels=(0.5,)):
    """A 16-bit WAV holding a constant level on each channel (full scale
    1.0), so what reaches each show output can be checked by value."""
    import struct
    import wave as _wave
    n = int(seconds * rate)
    frame = struct.pack(f"<{len(levels)}h",
                        *[int(round(v * 32767)) for v in levels])
    with _wave.open(path, "wb") as w:
        w.setnchannels(len(levels))
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(frame * n)


class _AnnBusEngine:
    """showaudio's real audio process loop (AudioProcess, its Mixer and its
    announcement bus) in this process, on a FakeSoundDevice the test pumps
    block by block: the same face as AudioEngine for what announce.py's
    show route uses (send, announce_read, device_open)."""

    def __init__(self, channels=8, block=480):
        from ltcplay import showaudio as sa
        self.sa = sa
        self.arr = [0.0] * sa.SLOTS
        self.sd = sa.FakeSoundDevice(threaded=False, block=block, devices=[
            {"name": "Show DSP", "hostapi": 0,
             "max_output_channels": channels}])
        self.msgs = []
        # "platform": the fake device lists no Windows audio system, so
        # the stream is opened the way it is on every other OS, whatever
        # this test runs on (open_output_stream's Windows order is proven
        # by the show audio tests of its own).
        self.proc = sa.AudioProcess(
            {"device": "Show DSP", "channels": channels, "rate": sa.RATE,
             "cues": {}, "platform": "linux"}, self.sd,
            sa.Publisher(self.arr), self.msgs.append, sync_load=True)
        self.proc.step(0.0)
        self.sent = []

    def show(self, level=0.25, seconds=10.0):
        import numpy as np
        n = int(seconds * self.sa.RATE)
        ch = self.proc.mixer.out_channels
        self.proc.mixer.add_cue("show", [(np.full((n, 1), level,
                                                  dtype=np.float32), 1.0,
                                          list(range(ch)))])
        self.proc.command(("play", "show", 0, 0, 1))

    def send(self, msg):
        self.sent.append(msg[0])
        self.proc.command(msg)
        return True

    def announce_read(self):
        return self.sa.read_announce(self.arr)

    def device_open(self):
        return self.proc.devstate == self.sa.DEV_OPEN

    def pump(self, n=1):
        import numpy as np
        return np.concatenate([self.proc.stream.pump(0.0)
                               for _ in range(n)])


def test_announce_bus_mixes_into_the_show_outputs():
    section("show audio: the announcement bus adds an announcement onto the "
            "show's own front left and right on the stream the show already "
            "has open; the show's own audio is not ducked or changed; its "
            "Hold, Stop and Abort never touch the announcement; a soft clip "
            "guard only while one plays (Jeff's field report, 2026-10-28, "
            "item 9)")
    import numpy as np
    from ltcplay import showaudio as sa
    bus = sa.AnnounceBus(8)
    out = np.full((100, 8), 0.95, dtype=np.float32)
    bus.mix(out)
    check(np.all(out == np.float32(0.95)),
          "with nothing playing the bus never touches a sample, not even "
          "one above the soft clip knee")
    check(not bus.play(1, np.zeros((10, 1), np.float32), [8], 1.0) and
          not bus.play(1, np.zeros((10, 3), np.float32), [0, 1], 1.0),
          "an output past the last, or channels that do not fit the "
          "outputs, are refused")
    pcm = np.full((150, 1), 0.5, dtype=np.float32)
    check(bus.play(7, pcm, [0, 1], 1.0) and bus.state == sa.PLAYING,
          "a mono announcement on outputs 1 and 2")
    out = np.full((100, 8), 0.25, dtype=np.float32)
    bus.mix(out)
    check(np.allclose(out[:, 0], 0.75) and np.allclose(out[:, 1], 0.75) and
          np.allclose(out[:, 2:], 0.25),
          f"added to the show on 1 and 2 only, nothing ducked: "
          f"{out[0].tolist()}")
    out = np.full((100, 8), 0.8, dtype=np.float32)
    bus.mix(out)
    check(bus.state == sa.ENDED and bus.frame == 150,
          "it ends at its last sample")
    check(float(np.max(np.abs(out[:50, :2]))) < 1.0 and
          float(np.min(out[:50, :2])) > sa.SOFT_KNEE and
          np.allclose(out[50:, :2], 0.8) and np.allclose(out[:, 2:], 0.8),
          f"the sum over full scale is rounded off below 1.0, only where "
          f"the announcement played: {out[0, :3].tolist()} "
          f"{out[60, :3].tolist()}")
    check(bus.softened > 0, "the guard counts what it bent")
    # A stop with the wrong token never cuts a newer announcement; the
    # right one fades it out, then it is ended.
    bus.play(8, np.full((10000, 2), [0.5, -0.25], dtype=np.float32),
             [2, 3], 0.5)
    check(not bus.stop(7, 100), "an older token's stop is ignored")
    out = np.zeros((10, 8), dtype=np.float32)
    bus.mix(out)
    check(np.allclose(out[:, 2], 0.25) and np.allclose(out[:, 3], -0.125)
          and np.allclose(out[:, :2], 0),
          f"stereo: left to the first output, right to the second, at its "
          f"gain: {out[0].tolist()}")
    check(bus.stop(8, 100), "its own token's stop is taken")
    out = np.zeros((300, 8), dtype=np.float32)
    bus.mix(out)
    col = out[:, 2]
    check(bus.state == sa.ENDED and abs(col[0] - 0.25) < 0.01 and
          np.all(np.diff(col[:100]) <= 1e-7) and np.allclose(col[100:], 0),
          "the stop fades down over its frames, never a click, then ends")
    print("  ok")


def test_announce_plays_through_the_show_audio():
    section("announcements play through the show audio process's bus when "
            "it runs: no second device is opened, they play during a show, "
            "a show's Hold or Abort never stops them, Stop fades only the "
            "announcement, a show starting fades it, a natural end and a "
            "stall are noticed, and with no show audio running the "
            "announcement's own output is used (Jeff's field report, "
            "2026-10-28, item 9)")
    import numpy as np
    A = _ann()
    from ltcplay import showaudio as sa
    work, cfg, _l = _ann_workdir(device="")
    _ann_write_level(os.path.join(work, "delayed.wav"), seconds=0.5,
                     rate=8000, levels=(0.5,))
    _ann_write_level(os.path.join(work, "cancellation.wav"), seconds=0.5,
                     rate=48000, levels=(0.5, -0.25))
    g6 = 10 ** (A.DEFAULT_GAIN_DB / 20.0)
    check(A.DEFAULT_GAIN_DB == -6.0,
          "the default level in the show mix is -6 dB (safety review of "
          "#158)")
    eng = _AnnBusEngine()
    if not check(eng.device_open(),
                 f"setup: the show audio is open: {eng.msgs}"):
        return
    eng.show(level=0.25)
    route = sa.ShowRoute(eng, "Show DSP", 8)
    have = [route]
    state = ["SHOW"]
    t = [100.0]
    fsd = FakeSD()
    asked = []
    svc = A.AnnounceService(cfg, sd=fsd, operators_folder=work,
                            state_provider=lambda: state[0],
                            show_route=lambda: have[0],
                            clock=lambda: t[0])
    svc.hold_requester = lambda who, screen, detail=None: (
        asked.append(who) or (None, 1))
    svc.hold_still_claimed = lambda epoch: True
    st = svc.status()
    check(st["route"]["kind"] == "show" and st["route"]["ok"] and
          "the show audio, outputs 1 and 2 on Show DSP" in
          st["route"]["text"],
          f"the announcement check names the show audio route, with no "
          f"output of its own picked: {st['route']}")
    r = svc.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"]["id"] == A.DELAYED and asked == [] and
          not fsd.output_opened,
          f"during a show it plays through the show audio: nothing held, "
          f"no second device opened: {r['playing']} {fsd.output_opened}")
    started = [j for j in svc.journal if j["outcome"] == "started"][-1]
    check("on the show audio (outputs 1 and 2 on Show DSP)" in
          started["text"], f"the journal says where: {started['text']}")
    blk = eng.pump(2)
    check(np.allclose(blk[:, 0], 0.25 + 0.5 * g6, atol=2e-4) and
          np.allclose(blk[:, 1], 0.25 + 0.5 * g6, atol=2e-4) and
          np.allclose(blk[:, 2:], 0.25),
          f"8 kHz mono, resampled to 48 kHz, on outputs 1 and 2 on top of "
          f"the show; every other output is the show alone: "
          f"{blk[0].tolist()}")
    # The show's own Hold (a pause) and Abort (its level) act on the show
    # only.
    eng.proc.command(("pause", 0, 1))
    blk = eng.pump(1)
    check(np.allclose(blk[:, 0], 0.5 * g6, atol=2e-4) and
          np.allclose(blk[:, 2:], 0),
          f"the show held: its audio stops, the announcement goes on: "
          f"{blk[0].tolist()}")
    eng.proc.command(("level", 0.0, 0))
    blk = eng.pump(1)
    check(np.allclose(blk[:, 0], 0.5 * g6, atol=2e-4),
          "an Abort's level fade never touches the announcement")
    eng.proc.command(("level", 1.0, 0))
    eng.proc.command(("resume", 0, 1))
    t[0] += 0.05
    st = svc.status()
    check(st["playing"] and st["playing"]["elapsed_s"] > 0.0,
          f"its progress is read back from the audio process: "
          f"{st['playing']}")
    # Stop: the announcement fades out (no click); the show plays on.
    svc.stop("Andy", "rack screen")
    blk = eng.pump(8)
    check(eng.proc.bus.state == sa.ENDED and
          np.allclose(blk[-480:, 0], 0.25) and
          np.all(np.diff(blk[:2400, 0]) <= 1e-6),
          "Stop fades only the announcement down; the show is untouched")
    # Natural end: noticed, journaled as finished.
    svc.play(A.DELAYED, "Andy", "rack screen")
    eng.pump(60)
    t[0] += 0.1
    st = svc.status()
    check(st["playing"] is None and
          [j for j in svc.journal if j["outcome"] == "finished"],
          f"a natural end is noticed: {st['playing']}")
    check(eng.proc.bus.pcm is None and len(eng.proc.bus.retired) >= 1,
          "the callback never frees a finished recording: it is retired")
    eng.proc.step(0.0)
    check(len(eng.proc.bus.retired) == 0,
          "the process's main thread lets the retired recordings go")
    # Stereo at 48 kHz: left to output 1, right to output 2.
    svc.play(A.CANCELLATION, "Andy", "rack screen")
    blk = eng.pump(1)
    check(np.allclose(blk[:, 0], 0.25 + 0.5 * g6, atol=2e-4) and
          np.allclose(blk[:, 1], 0.25 - 0.25 * g6, atol=2e-4),
          f"stereo: left and right to the front left and right: "
          f"{blk[0, :3].tolist()}")
    # A show starting fades it out (SHOW_START_STOPS_ANNOUNCEMENT).
    svc.on_show_started(reason="new")
    eng.pump(20)
    t[0] += 0.1
    st = svc.status()
    rows = [j for j in svc.journal if j["outcome"] == "stopped"]
    check(st["playing"] is None and rows and
          "a show started" in rows[-1]["text"],
          f"a show starting fades it and says why: {rows[-1:]}")
    # A stall: the audio process stops calling back.
    svc.play(A.DELAYED, "Andy", "rack screen")
    eng.pump(1)
    svc.status()
    t[0] += A.STALL_S + 1.0
    st = svc.status()
    check(st["playing"] is None and
          [j for j in svc.journal if j["outcome"] == "failed"],
          "an announcement the show audio stopped playing is marked failed")
    # The interface dropped by its driver mid-announcement: the bus is
    # stopped with the show's audio, so nothing of it is left playing
    # into the next stream (or said to be playing meanwhile).
    svc.play(A.DELAYED, "Andy", "rack screen")
    eng.pump(1)
    check(eng.proc.bus.state == sa.PLAYING, "setup: the announcement plays")
    eng.proc.stream.running = False
    eng.proc.step(1.0)
    dropped = (eng.proc.stream is None, eng.proc.bus.state,
               eng.proc.bus.pcm is None)
    eng.proc.step(eng.proc.next_try + 0.01)
    check(dropped == (True, sa.IDLE, True) and eng.device_open(),
          f"a dropped stream stops the announcement bus too, and the "
          f"interface opens again: {dropped} {eng.device_open()}")
    svc.status()
    t[0] += A.STALL_S + 1.0
    svc.status()
    eng.show(level=0.25)                # the show again, on the new stream
    # The audio process restarting mid-announcement (its shared memory
    # starts again from nothing): failed at once, said plainly, with no
    # wait for the stall watchdog.
    svc.play(A.DELAYED, "Andy", "rack screen")
    eng.pump(1)
    svc.status()
    for i in range(len(eng.arr)):
        eng.arr[i] = 0.0
    st = svc.status()
    rows = [j for j in svc.journal if j["outcome"] == "failed"]
    check(st["playing"] is None and rows and
          "the show audio process restarted" in rows[-1]["text"],
          f"a restart is reported at once: {rows[-1:]}")
    _no_dashes(rows[-1]["text"] if rows else "", "restart")
    eng.proc.bus.hard_stop()
    # The show audio's interface not open: refused BEFORE any Hold, with
    # a sentence that names the Show audio lamp, and the deck's word.
    state[0] = "STANDBY"
    eng.proc.devstate = sa.DEV_CLOSED
    try:
        svc.play(A.DELAYED, "Andy", "rack screen")
        check(False, "the show audio not open: refused")
    except ValueError as e:
        from ltcplay import streamdeck as SDK
        check("Show audio lamp" in str(e) and asked == [] and
              SDK.announce_refusal_word(str(e)) == "NO OUTPUT",
              f"refused before any Hold, plainly: {e} {asked}")
        _no_dashes(str(e), "show audio not open")
    check(not fsd.output_opened, "and no second device is ever tried")
    eng.proc.devstate = sa.DEV_OPEN
    # The show audio stopping while the file is read: failed, said, and
    # the Hold the press took says HELD, ANNOUNCEMENT FAILED.
    real = svc._decode

    def decode_and_stop(aid):
        have[0] = None
        return real(aid)
    svc._decode = decode_and_stop
    try:
        svc.play(A.DELAYED, "Andy", "rack screen")
        check(False, "the show audio stopped while loading: failed")
    except ValueError as e:
        check("show audio stopped while the announcement was loading" in
              str(e) and svc.held_failed and not fsd.output_opened,
              f"said, and the Hold it took says it failed: {e}")
    svc._decode = real
    svc.held_failed = None
    # No show audio at all: the announcement's own output. None picked:
    # refused plainly, before any Hold.
    asked.clear()
    try:
        svc.play(A.DELAYED, "Andy", "rack screen")
        check(False, "no show audio and no output picked: refused")
    except ValueError as e:
        check("No announcement output is picked" in str(e) and asked == [],
              f"{e}")
    # Run pressed while the file is read: it plays through the show
    # audio, never opening a second device.
    svc.device_name = "MOTU M4"
    plays_before = eng.sent.count("ann_play")

    def decode_and_run(aid):
        have[0] = route
        return real(aid)
    svc._decode = decode_and_run
    r = svc.play(A.DELAYED, "Andy", "rack screen")
    svc._decode = real
    check(r["playing"] and not fsd.output_opened and
          eng.sent.count("ann_play") == plays_before + 1,
          f"the show audio started while loading: it plays there: "
          f"{fsd.output_opened}")
    svc.stop("Andy", "rack screen")
    eng.pump(8)
    have[0] = None
    r = svc.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"] and len(fsd.output_opened) == 1 and
          r["route"]["kind"] == "device",
          f"with no show audio running, its own output plays it: "
          f"{fsd.output_opened} {r['route']}")
    svc.stop("Andy", "rack screen")
    # The level and the outputs come from ltcplay_announce.json.
    with open(cfg, encoding="utf-8") as fh:
        doc = json.load(fh)
    doc.update(show_outputs=[3, 4], gain_db=0)
    with open(cfg, "w", encoding="utf-8") as fh:
        json.dump(doc, fh)
    svc2 = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                             state_provider=lambda: "SHOW",
                             show_route=lambda: route)
    svc2.play(A.DELAYED, "Andy", "rack screen")
    blk = eng.pump(1)
    check(np.allclose(blk[:, 2], 0.75, atol=3e-4) and
          np.allclose(blk[:, 3], 0.75, atol=3e-4) and
          np.allclose(blk[:, 0], 0.25),
          f"show_outputs [3, 4] at gain_db 0: {blk[0, :4].tolist()}")
    svc2.stop("Andy", "rack screen")
    for bad in ({"show_outputs": [0, 1]}, {"show_outputs": [1, 1]},
                {"gain_db": 12}, {"gain_db": True}, {"hostapi": ""},
                {"volume": 3}):
        d = dict(doc, **bad)
        try:
            A.parse_config(d, "ltcplay_announce.json")
            check(False, f"{bad} must be refused")
        except ValueError as e:
            _no_dashes(str(e), f"config {bad}")
    doc["show_outputs"] = [9, 10]
    with open(cfg, "w", encoding="utf-8") as fh:
        json.dump(doc, fh)
    svc3 = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                             state_provider=lambda: "SHOW",
                             show_route=lambda: route)
    chk = svc3.status()["route"]
    check(not chk["ok"] and "has only 8" in chk["why"],
          f"outputs past the show audio's: said: {chk}")
    # ShowRoute.of_clock: only a clock that plays show audio of its own.
    check(sa.ShowRoute.of_clock(None) is None and
          sa.ShowRoute.of_clock(type("C", (), {"source": "ltc"})()) is None,
          "no show audio clock: no route")
    clk = type("C", (), {"source": "audio_master", "engine": eng,
                         "audio": type("Au", (), {"device": "Show DSP",
                                                  "channels": 8})()})()
    rt = sa.ShowRoute.of_clock(clk)
    check(rt is not None and rt.ready() and rt.channels == 8,
          "an audio_master clock is a route")
    print("  ok")


class _AnnPickSD(FakeSD):
    """Outputs as Windows lists them on the show PC: the StudioLive's WDM
    pair under two audio systems with the same name (Jeff's field report,
    2026-10-28, item 10)."""

    APIS = ("MME", "Windows WASAPI")

    def __init__(self):
        super().__init__()
        self.devices = [
            {"name": "StudioLive WDM 1/2 (StudioLive 16R)",
             "max_input_channels": 0, "max_output_channels": 2,
             "default_samplerate": 48000, "hostapi": 0},
            {"name": "StudioLive WDM 1/2 (StudioLive 16R)",
             "max_input_channels": 0, "max_output_channels": 2,
             "default_samplerate": 48000, "hostapi": 1},
            {"name": "Speakers (Realtek)", "max_input_channels": 0,
             "max_output_channels": 2, "default_samplerate": 48000,
             "hostapi": 0},
            {"name": "Mic (Realtek)", "max_input_channels": 2,
             "max_output_channels": 0, "default_samplerate": 48000,
             "hostapi": 0}]

    def query_hostapis(self, i=None):
        if i is None:
            return tuple({"name": n} for n in self.APIS)
        return {"name": self.APIS[i]}


