def _round5_stamped(arm, t):
    """Record (fake time, wanted) of every send while the socket is open."""
    stamps = []
    orig_send = arm.send

    def send(names_):
        if arm.is_open:
            stamps.append((t[0], list(arm.wanted)))
        orig_send(names_)
    arm.send = send
    return stamps


def test_streamdeck_round5_a_long_unplug_never_goes_quiet():
    section("Stream Deck: a deck unplugged for 120 s (fake clock) keeps its "
            "last wanted vector on the arm link the WHOLE time: no gap between two arm "
            "frames is ever longer than one ARM_SEND_HZ period, from the "
            "unplug to the reconnect (round 5 of the safety review, item 1: "
            "the round-4 test's no-deck time added up to exactly 6 s, so "
            "the hand mutation 'the OFF sender stops for good after 6 s' "
            "passed the whole suite)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0])
    stamps = _round5_stamped(arm, t)
    seen = {}

    def deck_a(i):
        if i == 1:
            arm.set_group(0, True)     # the operator arms front row

    def deck_b(i):
        if i == 1:
            seen.setdefault("back_at", t[0])

    # 60 failed opens at 2 s each, plus the 1 s hold after the unplug
    # itself: about 121 s with no deck.
    _round4_run_forever(c, [_Round4Deck(3, deck_a)] + [None] * 60
                        + [_Round4Deck(2, deck_b)], t)
    period = 1.0 / sd.ARM_SEND_HZ
    armed = [i for i, (_, w) in enumerate(stamps) if w[0]]
    check(bool(armed), "set up: front row really was sent armed first")
    back = seen.get("back_at")
    check(back is not None, "set up: the deck came back at the end")
    if not armed or back is None:
        return
    # From the first armed frame through the reconnect's own first frame,
    # so a sender that went silent part way shows as one long gap.
    off = [s for s in stamps[armed[0]:] if s[0] <= back]
    off_span = off[-1][0] - off[0][0] if off else 0.0
    check(off_span >= 120.0,
          f"set up: the deck really was away for 120 s or more "
          f"({off_span:.2f} s)")
    gaps = [b[0] - a[0] for a, b in zip(off, off[1:])]
    worst = max(gaps) if gaps else None
    worst_at = off[gaps.index(worst)][0] if gaps else None
    check(gaps and worst <= period + 1e-9,
          f"through the whole 120 s unplug no gap between two arm frames "
          f"is longer than one {period:g} s send period: longest "
          f"{worst} s, starting at t={worst_at}")
    check(all(w == [True, False, False] for _, w in off),
          "every frame from the arm, through the unplug, to the reconnect "
          "says front row armed and nothing else (ruling 4, 2026-10-12: "
          "an unplug disarms nothing)")
    check(len(off) >= int(120.0 * sd.ARM_SEND_HZ),
          f"{len(off)} steady frames went out in {off_span:.1f} s")


def test_streamdeck_round5_any_deck_error_is_an_unplug_not_an_exit():
    section("Stream Deck: ANY exception from opening the deck, or from one "
            "main-loop pass, is handled as an unplug: run_forever keeps "
            "every group kept as it was on the arm link and only a deliberate "
            "stop ends it, and each kind of failure is journaled once per "
            "outage (round 5 of the safety review, item 2: a plain OSError "
            "from hidapi's set_nonblocking or send_feature_report on a "
            "reconnect ended run_forever after 40 OFF frames, the link went "
            "silent and flamesafe's sender lock lapsed)")
    from ltcplay import streamdeck as sd

    # Part 1: Deck() itself turns every hidapi failure after the import
    # into DeckDisconnected, and closes a half-opened handle.
    class _Dev:
        def __init__(self, fail):
            self.fail = fail
            self.closed = False

        def _maybe(self, what):
            if self.fail == what:
                raise OSError(f"probe: {what} failed mid-plug")

        def open(self, vid, pid):
            self._maybe("open")

        def set_nonblocking(self, on):
            self._maybe("set_nonblocking")

        def send_feature_report(self, data):
            self._maybe("send_feature_report")

        def close(self):
            self.closed = True

    devs = []

    class _Hid:
        fail = None

        def device(self):
            if self.fail == "device":
                raise OSError("probe: no HID device object")
            d = _Dev(self.fail)
            devs.append(d)
            return d

    fake = _Hid()
    orig_import = sd._import_hid
    sd._import_hid = lambda: fake
    try:
        for what in ("device", "open", "set_nonblocking",
                     "send_feature_report"):
            fake.fail = what
            del devs[:]
            try:
                sd.Deck()
                got = "opened"
            except sd.DeckDisconnected as e:
                got = ("DeckDisconnected", type(e.__cause__).__name__)
            except Exception as e:            # noqa: BLE001
                got = f"escaped as {type(e).__name__}: {e}"
            check(got == ("DeckDisconnected", "OSError"),
                  f"Deck(): a {what} failure is raised as DeckDisconnected "
                  f"(from the OSError): {got}")
            check(all(d.closed for d in devs),
                  f"and a half-opened handle is closed again after a "
                  f"{what} failure: {[d.closed for d in devs]}")
        fake.fail = None
        d = sd.Deck()
        check(d.h is devs[-1] and not devs[-1].closed,
              "set up: with nothing failing, Deck() opens and keeps the "
              "handle")
    finally:
        sd._import_hid = orig_import

    # Part 2: the round-5 review's deck_exit probe through the REAL
    # run_forever, plus errors from a pass, a handful of each.
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    events = []
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0])
    stamps = _round5_stamped(arm, t)

    class _PassDeck(_Round4Deck):
        """keys_down() raises `exc` on pass `at`; set_key() raises `key_exc`
        once `key_at` passes have run."""

        def __init__(self, passes, at=None, exc=None, key_at=None,
                     key_exc=None, on_pass=None):
            super().__init__(passes, on_pass)
            self.at, self.exc = at, exc
            self.key_at, self.key_exc = key_at, key_exc

        def keys_down(self):
            if self.at is not None and self.i + 1 == self.at:
                self.i += 1
                raise self.exc
            return super().keys_down()

        def set_key(self, image, key, img):
            if self.key_at is not None and self.i >= self.key_at:
                raise self.key_exc

    def arm_front_row(i):
        if i == 1:
            arm.set_group(0, True)

    oserr = [OSError("probe: hid send_feature_report failed mid-plug")
             for _ in range(30)]                       # 60 s of these
    decks = ([None] + oserr
             + [_PassDeck(50, at=3, exc=RuntimeError("probe: a bug in a "
                                                     "pass"),
                          on_pass=arm_front_row)]
             + [OSError("probe: again"), OSError("probe: and again")]
             + [_PassDeck(50, key_at=2,
                          key_exc=ValueError("probe: bad key image"))]
             + [_PassDeck(int(12 * sd.ARM_SEND_HZ))]   # 12 s clean, unplug
             + [None, None])
    died = None
    try:
        _round4_run_forever(c, decks, t,
                            journal=lambda t_, **kw: events.append((t_, kw)))
    except Exception as e:                    # noqa: BLE001
        died = e
    check(died is None and not decks,
          f"run_forever never died: every error was handled as an unplug "
          f"and only the deliberate stop ended it (died with "
          f"{type(died).__name__ if died else None}: {died}; "
          f"{len(decks)} scripted steps never reached)")
    period = 1.0 / sd.ARM_SEND_HZ
    gaps = [b[0] - a[0] for a, b in zip(stamps, stamps[1:])]
    check(t[0] >= 70.0 and gaps and max(gaps) <= period + 1e-9,
          f"arm frames went out without a gap longer than one period the "
          f"whole {t[0]:.1f} s: longest {max(gaps) if gaps else None} s")
    armed = [i for i, (_, w) in enumerate(stamps) if w[0]]
    check(bool(armed) and all(w == [True, False, False]
                              for _, w in stamps[armed[0]:]),
          "front row was sent armed before the pass error, and every frame "
          "after it, through every error, still says front row armed and "
          "nothing else (ruling 4, 2026-10-12)")
    check(bool(armed) and len(stamps) > armed[0] + 1
          and all(b[0] - a[0] <= period + 1e-9 for a, b in
                  zip(stamps[armed[0]:], stamps[armed[0] + 1:])),
          "no frame after the error is ever late by more than one period")

    def lines(sub):
        return [t_ for t_, kw in events if sub in t_]
    check(len(lines("OSError")) == 1,
          f"32 OSErrors opening the deck in one outage: ONE journal line, "
          f"not one per 2 s retry: {lines('OSError')}")
    check(len(lines("RuntimeError")) == 1 and len(lines("ValueError")) == 1,
          f"an error from a pass and from drawing a key are each "
          f"journaled once: {lines('RuntimeError')} {lines('ValueError')}")
    check(all(kw.get("fault") for t_, kw in events
              if "Error" in t_ or "probe:" in t_),
          "every failure line is a fault")
    check(len(lines("probe: nothing plugged in")) == 1
          and len(lines("probe: unplugged")) == 1,
          f"the deck running {sd.DECK_STABLE_S:g} s clean ends the outage, "
          f"so the next unplug is journaled again: "
          f"{lines('probe: nothing plugged in')} {lines('probe: unplugged')}")
    check(len(lines("running cleanly")) == 1
          and "more failure" in lines("running cleanly")[0],
          f"and the end of the outage says how many went unlogged: "
          f"{lines('running cleanly')}")
    check(len(lines("Stream Deck connected")) == 1,
          f"one connect line per outage (3 reconnects inside one outage, "
          f"1 journaled): "
          f"{len(lines('Stream Deck connected'))}")

    # Part 3: a socket that cannot be opened (no file descriptors left)
    # is retried on the next frame, never the end of run_forever. A send
    # on the socket while it is not open raises OSError, as a real
    # socket's does: the hold-off's catch-all around the send is what
    # keeps that from ending run_forever. (_FakeArmSocket's send never
    # raised, so that except was never reached and the suite stayed green
    # with it narrowed to DeckDisconnected: mutate.py, "the hold-off dies
    # on an arm socket that will not open", found by PR #70's CI.)
    class _StubbornArm(_FakeArmSocket):
        fails = 3

        def __init__(self, n):
            super().__init__(n)
            self.attempts = 0        # every send asked for, open or not

        def open(self):
            if self.fails:
                self.fails -= 1
                raise OSError("probe: too many open files")
            super().open()

        def send(self, names):
            self.attempts += 1
            if not self.is_open:
                raise OSError("probe: sendto on a socket that is not open")
            super().send(names)

    arm2 = _StubbornArm(3)
    t2 = [0.0]
    c2 = sd.Controller(arm2, _FakeStatusSocket(), names,
                       operator_provider=lambda: "Andy",
                       show_running_provider=lambda: True,
                       clock=lambda: t2[0])
    stamps2 = _round5_stamped(arm2, t2)
    died = None
    try:
        _round4_run_forever(c2, [None, None], t2)
    except Exception as e:                    # noqa: BLE001
        died = e
    check(died is None and arm2.opens == 1 and stamps2
          and stamps2[0][0] <= 3 * period + 1e-9,
          f"an arm socket that fails to open 3 times is opened on the 4th "
          f"frame and sends from then on (died: {died!r}, opens "
          f"{arm2.opens}, first frame at "
          f"{stamps2[0][0] if stamps2 else None})")
    frames = 2 * int(round(2.0 * sd.ARM_SEND_HZ))     # two 2 s hold-offs
    check(arm2.attempts == frames and len(stamps2) == frames - 3,
          f"every frame of both hold-offs was attempted, the 3 that raised "
          f"on the unopened socket included, and run_forever reached its "
          f"deliberate stop: {arm2.attempts} attempts, {len(stamps2)} "
          f"sent, expected {frames} and {frames - 3}")

    # And the hold-off on its own, with a send that raises on EVERY frame
    # and not an OSError either (nothing but the catch-all can take it):
    # it runs its full count of frames and returns, raising nothing.
    class _WedgedArm(_FakeArmSocket):
        def send(self, names):
            self.seq += 1
            raise RuntimeError("probe: the arm socket is wedged")

    arm3 = _WedgedArm(3)
    arm3.open()
    t3 = [0.0]
    c3 = sd.Controller(arm3, _FakeStatusSocket(), names,
                       operator_provider=lambda: "Andy",
                       show_running_provider=lambda: True,
                       clock=lambda: t3[0])
    died = None
    try:
        sd._hold_link_steady(c3, lambda s_: t3.__setitem__(0, t3[0] + s_),
                             1.5, sd._DeckOutage(lambda t_, **kw: None))
    except Exception as e:                    # noqa: BLE001
        died = e
    want = int(round(1.5 * sd.ARM_SEND_HZ))
    check(died is None and arm3.seq == want and abs(t3[0] - 1.5) < 1e-9,
          f"the hold-off ran all {want} frames past a send that raised on "
          f"each one and returned (died: {died!r}, frames {arm3.seq}, "
          f"{t3[0]:.2f} s)")


def test_streamdeck_never_imports_flamesafe():
    section("Stream Deck: never imports flamesafe (it is an ltcplay module, "
            "already covered by the wall test, checked again here by name), "
            "and can be imported without hid or Pillow installed")
    import ast
    here = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(here, "ltcplay", "streamdeck.py")
    tree = ast.parse(open(path, encoding="utf-8").read())
    top_level = set()
    for node in tree.body:          # module top level only: a lazy import
        if isinstance(node, ast.Import):               # inside a function
            top_level |= {a.name.split(".")[0] for a in node.names}
        elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
            top_level.add(node.module.split(".")[0])
    all_names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            all_names |= {a.name.split(".")[0] for a in node.names}
        elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
            all_names.add(node.module.split(".")[0])
    check("flamesafe" not in all_names,
          f"ltcplay/streamdeck.py imports flamesafe, anywhere in the file: "
          f"{sorted(all_names)}")
    check("hid" not in top_level and "PIL" not in top_level,
          f"hid and PIL are imported lazily, inside functions, never at "
          f"module top level: {sorted(top_level)}")
    import subprocess as _sp
    r = _sp.run([sys.executable, "-c",
                "import sys; sys.path.insert(0, sys.argv[1]); "
                "import ltcplay.streamdeck; "
                "print('hid' in sys.modules, 'PIL' in sys.modules)", here],
               capture_output=True, text=True, timeout=30)
    check(r.returncode == 0 and r.stdout.strip() == "False False",
          f"importing ltcplay.streamdeck never pulls in hid or PIL as a "
          f"side effect (so the rest of ltcplay keeps working without "
          f"them): rc={r.returncode} {r.stdout!r} {r.stderr[-300:]!r}")


def _on_time_sleep(seconds):
    """time.sleep that ends on time. BEYOND spaces its 3 packets 20 ms
    apart, and the conductor calls anything slower than SLOW_CALL_S a
    fault. macOS CI runners overshoot a 20 ms time.sleep() by up to
    ~130 ms (seen in PR #29 round 3: a blank took 298 ms), which is the
    runner, not the code under test. Any single sleep can overshoot like
    that, so this only ever yields (time.sleep(0) lets other threads run)
    until the deadline. It is only used for those 20 ms gaps."""
    end = time.perf_counter() + seconds
    while time.perf_counter() < end:
        time.sleep(0)


def _rt_rig(beyond_delay=None, gate=None, announcer=None, mm_factory=None):
    from ltcplay import madmapper as MM, beyond as B
    C = _cond_mod()
    log, lines = [], []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    rig = _CondRig(time.perf_counter)
    link = MM.Link(_mm_cfg(ramp_steps=31),
                   socket_factory=mm_factory or (lambda: _RTSock("mm", log)),
                   journal=journal)
    bey = B.Beyond(B.BeyondConfig.parse({}),
                   socket_factory=lambda: _RTSock("beyond", log,
                                                  beyond_delay),
                   sleep=_on_time_sleep, journal=journal)
    dev = C.ConductorDevices(link, bey, show=1, journal=journal)
    c = C.Conductor(dev, rig, gate or (lambda: None),
                    hold_gate=lambda *a: (None, 1), announcer=announcer,
                    journal=journal)
    return c, rig, log, lines, link, bey


def _rt_vals(log, kind, since=None, value=None):
    return [e for e in log if e[0] == kind
            and (since is None or e[3] >= since)
            and (value is None or e[2] == value)]


def test_beyond_a_blank_cuts_an_unblank_short_from_any_thread():
    section("beyond: a blank on another thread stops an unblank before its "
            "next packet, never waits for it, and 0 is BEYOND's last word")
    from ltcplay import beyond as B
    log = []
    release = threading.Event()

    class Stall(_RTSock):
        def sendto(self, pkt, addr):
            from ltcplay import madmapper as MM
            if MM.decode_float(pkt)[1] == 100.0:
                release.wait(2.0)        # the 100 is stuck on its way out
            _RTSock.sendto(self, pkt, addr)

    bey = B.Beyond(B.BeyondConfig.parse({}),
                   socket_factory=lambda: Stall("beyond", log),
                   sleep=_on_time_sleep)      # see _on_time_sleep: macOS CI
    got = {}
    t = threading.Thread(target=lambda: got.setdefault(
        "r", bey.unblank(in_show=True)))
    t.start()
    time.sleep(0.05)                     # inside the first 100's sendto
    t0 = time.perf_counter()
    ok = bey.blank()
    took = time.perf_counter() - t0
    # The unblank's packet is stuck for 2 s (release.wait above); a blank
    # that waited for it takes that long, one that did not takes a few ms.
    # Half the stall, not 0.2 s, which a runner's handoff has exceeded.
    check(ok and took < 1.0,
          f"the blank went out without waiting for the stuck unblank "
          f"({took * 1000:.0f} ms)")
    release.set()
    t.join(2)
    vals = [e[2] for e in sorted(log, key=lambda e: e[4])]
    check(vals.count(100.0) == 1,
          f"no 100 was started after the blank began: {vals}")
    check(vals and vals[-1] == 0.0,
          f"the 100 already on its way out is followed by a 0: {vals}")
    check(got.get("r") is False and bey.last_result in ("cut", "ok"),
          f"the cut unblank does not report success: {got} "
          f"{bey.last_result}")
    # still_wanted: a newer request stops an unblank before any blank.
    log2 = []
    bey2 = B.Beyond(B.BeyondConfig.parse({}),
                    socket_factory=lambda: _RTSock("beyond", log2))
    asked = []

    def wanted():
        asked.append(1)
        return len(asked) < 2
    r = bey2.unblank(in_show=True, still_wanted=wanted)
    check(r is False and [e[2] for e in log2] == [100.0]
          and bey2.last_result == "cut",
          f"still_wanted turning false stops the unblank: {log2}")

    # Review round 3: a blank that lands in the 20 ms gap between two
    # unblank packets, with NO still_wanted, means no further 100 is sent.
    # Both ways round: the unblank wakes while the blank is still sending
    # its 0s (catches a blank that counts itself only after its packets),
    # and after the blank has finished (catches an unblank that takes a
    # fresh count before every packet, so never sees a blank at all).
    for mid in (True, False):
        log3 = []
        in_gap, go = threading.Event(), threading.Event()

        def sleeper(s, mid=mid, in_gap=in_gap, go=go):
            who = threading.current_thread().name
            if who == "unblanker" and not in_gap.is_set():
                in_gap.set()             # after the first 100: the gap
                go.wait(2.0)
                return
            if who == "blanker" and mid and not go.is_set():
                go.set()                 # wake the unblank mid blank
                time.sleep(0.15)
                return
            time.sleep(s)
        bey3 = B.Beyond(B.BeyondConfig.parse({}),
                        socket_factory=lambda log3=log3: _RTSock("beyond",
                                                                 log3),
                        sleep=sleeper)
        got3 = {}
        u = threading.Thread(target=lambda: got3.setdefault(
            "r", bey3.unblank(in_show=True)), name="unblanker")
        u.start()
        check(in_gap.wait(2.0), "the unblank reached its first gap")
        bt = threading.Thread(target=bey3.blank, name="blanker")
        bt.start()
        bt.join(2)
        go.set()
        u.join(2)
        when = "while the blank was sending" if mid else \
            "after the blank had finished"
        seq = sorted(log3, key=lambda e: e[3])
        first0 = next((e[3] for e in seq if e[2] == 0.0), None)
        late100 = [e for e in seq if e[2] == 100.0 and first0 is not None
                   and e[3] >= first0]
        check(first0 is not None and not late100,
              f"an unblank woken {when} sends no further 100: "
              f"{[e[2] for e in seq]}")
        out = [e[2] for e in sorted(log3, key=lambda e: e[4])]
        check(out.count(100.0) == 1 and out[-1] == 0.0,
              f"one 100 before the blank, and 0 last ({when}): {out}")
        check(got3.get("r") is False and bey3.last_result in ("cut", "ok"),
              f"the cut unblank does not report success ({when}): {got3}")

    # Review round 3: the 0 that follows a 100 caught on its way out is
    # retried like any blank. The blank has already returned True by then,
    # so a single lost 0 left BEYOND lit with everything above it sure the
    # lasers were dark.
    log4 = []
    release4 = threading.Event()
    lost = []

    class StallThenLose(_RTSock):
        def sendto(self, pkt, addr):
            from ltcplay import madmapper as MM
            v = MM.decode_float(pkt)[1]
            if threading.current_thread().name == "unblanker4":
                if v == 100.0:
                    release4.wait(2.0)
                elif v == 0.0 and not lost:
                    lost.append(1)
                    raise OSError("the first 0 after the 100 is lost")
            _RTSock.sendto(self, pkt, addr)

    bey4 = B.Beyond(B.BeyondConfig.parse({}),
                    socket_factory=lambda: StallThenLose("beyond", log4))
    u4 = threading.Thread(target=lambda: bey4.unblank(in_show=True),
                          name="unblanker4")
    u4.start()
    time.sleep(0.05)                     # inside the first 100's sendto
    check(bey4.blank(), "the blank itself got out")
    release4.set()
    u4.join(2)
    out4 = [e[2] for e in sorted(log4, key=lambda e: e[4])]
    check(lost and out4 and out4[-1] == 0.0,
          f"one lost 0 after the late 100 does not leave BEYOND lit: "
          f"{out4}")
    print("  ok")


def test_conductor_stop_is_never_held_up_by_a_slow_device():
    section("conductor: Abort's flame cut and laser blank go out within a "
            "few ms of the press, whatever BEYOND, the laser gate or an "
            "announcement is doing (review of PR #29, finding D)")
    C = _cond_mod()
    # Every stall below is 300 ms or longer (a BEYOND packet, the laser
    # gate, an announcement's file read). The Abort lands 150 ms into the
    # stuck packet in case 1, so a flame cut or a blank that waited behind
    # it lands about 150 ms after the press (measured 172 ms under the
    # mutation that makes it wait), and one that did not lands in a few
    # ms. FEW is half of that 150 ms: the same margin either way. It was
    # 20 ms, which measured the runner's thread handoffs, not the
    # conductor.
    FEW = 0.075
    # 1) Every BEYOND packet takes 300 ms to leave; Abort lands while the
    #    show start's unblank is part way out.
    c, rig, log, lines, link, bey = _rt_rig(beyond_delay=lambda v: 0.3)
    try:
        c.show_starting("Andy", "rack screen")
        time.sleep(0.15)
        t0 = time.perf_counter()
        check(c.stop("Andy", "rack screen").ok, "Abort accepted")
        t_ret = time.perf_counter()
        fz = [cl for cl in rig.calls if cl[0] == "flames_zero"
              and cl[2] >= t0]
        check(fz and fz[0][2] - t0 < FEW,
              f"the flame cut went out within {FEW * 1000:.0f} ms "
              f"({(fz[0][2] - t0) * 1000 if fz else None} ms)")
        check(c.wait_idle(5), "the Abort finished")
        time.sleep(0.8)
        zeros = _rt_vals(log, "beyond", since=t0, value=0.0)
        check(zeros and zeros[0][3] - t0 < FEW,
              f"the first blank packet was handed to the socket within "
              f"{FEW * 1000:.0f} ms of the press "
              f"({(zeros[0][3] - t0) * 1000 if zeros else None} ms)")
        check(fz and zeros and fz[0][2] <= zeros[0][3] <= t_ret,
              f"the flame cut, then the first blank packet, both before the "
              f"press returned: cut {(fz[0][2] - t0) * 1000 if fz else None}"
              f" ms, blank {(zeros[0][3] - t0) * 1000 if zeros else None} "
              f"ms, returned {(t_ret - t0) * 1000:.1f} ms")
        check(not _rt_vals(log, "beyond", since=t0, value=100.0),
              "no unblank packet was started after the press")
        b = sorted(_rt_vals(log, "beyond"), key=lambda e: e[4])
        check(b and b[-1][2] == 0.0,
              f"BEYOND's last word is 0: {[e[2] for e in b]}")
        check(c.snapshot()["applied"]["lasers"] == C.BLACK,
              f"recorded dark: {c.snapshot()['applied']}")
    finally:
        c.close()
        link.close()

    # 1b) The same, with a Hold: its blank waits its turn on the executor,
    #     but the restore stops before its next packet all the same (the
    #     conductor's restore guard), so no 100 starts after the press.
    c, rig, log, lines, link, bey = _rt_rig(beyond_delay=lambda v: 0.3)
    try:
        c.show_starting("Andy", "rack screen")
        time.sleep(0.15)
        t0 = time.perf_counter()
        check(c.hold("Andy", "rack screen").ok, "Hold accepted")
        check(c.wait_idle(5), "the Hold finished")
        time.sleep(0.5)
        check(not _rt_vals(log, "beyond", since=t0, value=100.0),
              f"no unblank packet was started after the Hold press: "
              f"{[(e[2], round(e[3] - t0, 3)) for e in log if e[0] == 'beyond']}")
        b = sorted(_rt_vals(log, "beyond"), key=lambda e: e[4])
        check(b and b[-1][2] == 0.0,
              f"BEYOND's last word is 0: {[e[2] for e in b]}")
    finally:
        c.close()
        link.close()

    # 2) A laser gate that takes 500 ms: the Abort's fade does not wait.
    def slow_gate():
        time.sleep(0.5)
        return None
    c, rig, log, lines, link, bey = _rt_rig(gate=slow_gate)
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        c.hold("Andy", "rack screen")
        check(c.wait_idle(5), "hold done")
        c.resume("Andy", "rack screen")
        time.sleep(0.2)                  # the executor is in the gate
        t0 = time.perf_counter()
        c.stop("Andy", "rack screen")
        fz = [cl for cl in rig.calls if cl[0] == "flames_zero"
              and cl[2] >= t0]
        check(c.wait_idle(5), "the Abort finished")
        time.sleep(0.2)
        zeros = _rt_vals(log, "beyond", since=t0, value=0.0)
        px = [cl for cl in rig.calls if cl[0] == "pixels_fade_out"
              and cl[2] >= t0]
        check(fz and fz[0][2] - t0 < FEW and zeros
              and zeros[0][3] - t0 < FEW,
              f"flame cut and blank within {FEW * 1000:.0f} ms during a "
              f"slow gate")
        check(px and px[0][2] - t0 < 0.25,
              f"and the Abort's fades did not wait for the 500 ms gate "
              f"({(px[0][2] - t0) * 1000 if px else None} ms)")
        check(not _rt_vals(log, "beyond", since=t0, value=100.0),
              "the gate's late yes lit nothing")
    finally:
        c.close()
        link.close()

    # 2b) Review round 3: a laser gate that hangs past GATE_TIMEOUT_S and
    #     only then says yes. No Abort this time: the timeout itself has to
    #     be a no, and the late yes must light nothing.
    def hung_gate():
        time.sleep(C.GATE_TIMEOUT_S + 0.5)
        return None
    c, rig, log, lines, link, bey = _rt_rig(gate=hung_gate)
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        c.hold("Andy", "rack screen")
        check(c.wait_idle(5), "hold done")
        t0 = time.perf_counter()
        c.resume("Andy", "rack screen")
        check(c.wait_idle(C.GATE_TIMEOUT_S + 3), "the Resume finished")
        time.sleep(0.8)                  # past the gate's late yes
        check(not _rt_vals(log, "beyond", since=t0, value=100.0),
              f"a gate hung past {C.GATE_TIMEOUT_S:g} s lights nothing: "
              f"{[e[2] for e in _rt_vals(log, 'beyond', since=t0)]}")
        check(c.snapshot()["applied"]["lasers"] == C.BLACK,
              f"and the lasers are recorded dark: "
              f"{c.snapshot()['applied']['lasers']}")
        check(any("did not answer within" in t for t, _f in lines),
              f"the journal says the gate did not answer: "
              f"{[t for t, _f in lines if 'gate' in t]}")
    finally:
        c.close()
        link.close()

    # 3) An announcement still reading its file (400 ms).
    c, rig, log, lines, link, bey = _rt_rig(
        announcer=lambda *a: time.sleep(0.4))
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        c.announce("welcome", "Andy", "rack screen")
        time.sleep(C.ANNOUNCE_FADE_S + C.ANNOUNCE_DARK_S + 0.2)
        t0 = time.perf_counter()
        c.stop("Andy", "rack screen")
        fz = [cl for cl in rig.calls if cl[0] == "flames_zero"
              and cl[2] >= t0]
        check(c.wait_idle(5), "the Abort finished")
        time.sleep(0.2)
        zeros = _rt_vals(log, "beyond", since=t0, value=0.0)
        mh = [cl for cl in rig.calls if cl[0] == "music_halt"
              and cl[2] >= t0]
        check(fz and fz[0][2] - t0 < FEW and zeros
              and zeros[0][3] - t0 < FEW,
              f"flame cut and blank within {FEW * 1000:.0f} ms during an "
              f"announcement's file read")
        check(mh and mh[0][2] - t0 < 0.2,
              f"and the Abort's fades did not wait for the 400 ms file read "
              f"({(mh[0][2] - t0) * 1000 if mh else None} ms)")
    finally:
        c.close()
        link.close()
    print("  ok")


def test_conductor_hears_about_madmapper_failures_and_stalls():
    section("conductor: a MadMapper send that fails, or a MadMapper sender "
            "that stalls, is a fault and leaves the video UNKNOWN, and a "
            "later Abort fades it anyway (review of PR #29, finding A)")
    C = _cond_mod()

    def no_net():
        raise OSError("network is down")
    c, rig, log, lines, link, bey = _rt_rig(mm_factory=no_net)
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        c.hold("Andy", "rack screen")
        check(c.wait_idle(5), "hold done")
        time.sleep(0.4)                  # the Link's worker has run it
        snap = c.snapshot()
        check(snap["applied"]["video"] == C.UNKNOWN,
              f"a video fade that never got out is UNKNOWN, never black: "
              f"{snap['applied']}")
        check(snap["faults"] >= 1 and any(
            f and "not sent to MadMapper" in t for t, f in lines),
              f"and a fault line says so: {[t for t, f in lines if f]}")
        check(not any(len(t) > 600 for t, _f in lines),
              "the fault line names each reason once, not once a packet")
        n = sum(1 for t, f in lines if f and "Video fade to black over 1 s"
                in t)
        c.stop("Andy", "rack screen")
        check(c.wait_idle(5), "the Abort finished")
        time.sleep(0.3)
        check(sum(1 for t, f in lines if f and "Video fade to black over 1 s"
                  in t) > n,
              "a later Abort sends the video fade again (and says it "
              "failed again)")
    finally:
        c.close()
        link.close()

    # A stalled sender: the Link's worker is stuck behind another job.
    saved = C.VIDEO_STALL_S
    C.VIDEO_STALL_S = 0.4
    c, rig, log, lines, link, bey = _rt_rig()
    stuck = threading.Event()
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        time.sleep(0.1)
        link._submit(lambda: stuck.wait(3.0), wait=False)
        t0 = time.perf_counter()
        c.hold("Andy", "rack screen")
        check(c.wait_idle(5), "hold done")
        early = c.snapshot()["applied"]["video"]
        check(time.perf_counter() - t0 > C.HOLD_FADE_S + 0.4 or
              early == C.UNKNOWN,
              f"a fade MadMapper has not sent yet is not recorded black: "
              f"{early}")
        time.sleep(max(0.0, t0 + C.HOLD_FADE_S + 0.4 + 0.3
                       - time.perf_counter()))
        snap = c.snapshot()
        check(snap["applied"]["video"] == C.UNKNOWN and any(
            f and "has not sent it yet" in t for t, f in lines),
              f"a stalled MadMapper sender is a fault and the video is "
              f"UNKNOWN: {snap['applied']} {[t for t, f in lines if f]}")
    finally:
        stuck.set()
        C.VIDEO_STALL_S = saved
        c.close()
        link.close()

    # Only the latest video command's success counts: a Hold's fade that
    # goes out after a Resume asked for the video back up does not make
    # the record say black.
    c, rig, T, lines, link, bey = _cond_devices()
    _cd_live(c, rig, link)
    g1, g2 = threading.Event(), threading.Event()
    link._submit(lambda: g1.wait(3.0), wait=False)
    c.hold("Andy", "rack screen")
    c.run_pending()
    hold_ran = threading.Event()          # queued right after the Hold's
    link._submit(hold_ran.set, wait=False)
    link._submit(lambda: g2.wait(3.0), wait=False)
    check(c.resume("Andy", "rack screen").ok, "Resume accepted")
    c.run_pending()
    check(c.snapshot()["applied"]["video"] == C.UNKNOWN,
          "neither command has gone out yet: UNKNOWN")
    g1.set()
    check(hold_ran.wait(2.0), "the Hold's video command has run")
    time.sleep(0.05)
    check(c.snapshot()["applied"]["video"] == C.UNKNOWN,
          f"the Hold's fade went out, but the Resume's is the latest: not "
          f"black: {c.snapshot()['applied']}")
    g2.set()
    _mm_flush(link)
    check(c.snapshot()["applied"]["video"] == C.LIT,
          f"and once the Resume's goes out, lit: {c.snapshot()['applied']}")
    link.close()

    # And when it all goes out, the record says so (and only then).
    c, rig, log, lines, link, bey = _rt_rig()
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        c.hold("Andy", "rack screen")
        check(c.wait_idle(5), "hold done")
        time.sleep(0.2)
        check(c.snapshot()["applied"]["video"] == C.BLACK,
              f"a fade the Link sent is recorded black: "
              f"{c.snapshot()['applied']}")
        check(not any(f for _t, f in lines),
              f"and nothing is a fault: {[t for t, f in lines if f]}")
    finally:
        c.close()
        link.close()
    print("  ok")


def test_conductor_a_failed_stop_blank_can_be_sent_again():
    section("conductor: BEYOND unreachable at Abort; a second Abort, a "
            "second Hold and intermission() all send the blank again and "
            "say how the lasers really stand (review of PR #29, finding B)")
    C = _cond_mod()
    down = [False]
    vals = []                            # every brightness that got out

    class Flaky(_FakeMMSock):
        def __init__(self):
            if down[0]:
                raise OSError("no route to host")
            super().__init__()

        def sendto(self, pkt, addr):
            from ltcplay import madmapper as MM
            if down[0]:
                raise OSError("no route to host")
            super().sendto(pkt, addr)
            vals.append(MM.decode_float(pkt)[1])
    c, rig, T, lines, link, bey = _cond_devices(beyond_factory=Flaky)
    _cd_live(c, rig, link)
    down[0] = True
    r = c.stop("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    check("did NOT get out" in r.sentence,
          f"the Stop says its blank did not get out: {r.sentence}")
    check(c.snapshot()["applied"]["lasers"] == C.UNKNOWN,
          "the lasers are UNKNOWN after a blank that did not get out")
    r = c.stop("Jeff", "Stream Deck")
    check(r.ok and ("may still be lit" in r.sentence or
                    "did NOT get out" in r.sentence),
          f"a second Stop while BEYOND is still down says so: {r}")
    down[0] = False
    del vals[:]
    r = c.stop("Jeff", "Stream Deck")
    b = list(vals)
    check(b and all(v == 0.0 for v in b) and
          ("the lasers are dark" in r.sentence or
           "lasers blanked" in r.sentence),
          f"once BEYOND is back, a second Stop blanks it: {b} {r}")
    c.run_pending()
    check(c.snapshot()["applied"]["lasers"] == C.BLACK, "recorded dark")
    link.close()
    # A second Hold while held, with the first blank lost.
    c, rig, T, lines, link, bey = _cond_devices(beyond_factory=Flaky)
    _cd_live(c, rig, link)
    down[0] = True
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(c.snapshot()["applied"]["lasers"] == C.UNKNOWN, "hold blank lost")
    # A second Hold while BEYOND is still down: the blank is sent again
    # and does not get out, and the answer says so, never "dark".
    r = c.hold("Andy", "rack screen")
    check("Already on hold" in r.sentence and
          "did not get out: the lasers may still be lit" in r.sentence and
          "the lasers are dark" not in r.sentence,
          f"a second Hold with BEYOND still down says the lasers may still "
          f"be lit (finding B): {r.sentence}")
    down[0] = False
    del vals[:]
    r = c.hold("Andy", "rack screen")
    b = list(vals)
    check(b == [0.0] * 3 and "Already on hold" in r.sentence
          and c.snapshot()["applied"]["lasers"] == C.BLACK,
          f"a second Hold blanks again: {b} {r}")
    link.close()
    print("  ok")


def test_conductor_video_never_rises_after_stop_or_hold():
    section("conductor: Abort or Hold during a Resume's video fade-up stops "
            "it where it is and fades down from there, never up to full "
            "first (review of PR #29, finding C)")
    C = _cond_mod()
    # Stop too (Jeff, 2026-10-30: Stop has every guarantee Abort had).
    for press in ("hold", "stop"):
        for delay in (0.03, 0.12, 0.2):
            c, rig, log, lines, link, bey = _rt_rig()
            rig.move_s = 0.3
            try:
                c.show_starting("Andy", "rack screen")
                check(c.wait_idle(5), "show start done")
                c.hold("Andy", "rack screen")
                check(c.wait_idle(5), "hold done")
                time.sleep(0.4)
                c.resume("Andy", "rack screen")
                time.sleep(delay)
                t0 = time.perf_counter()
                getattr(c, press)("Andy", "rack screen")
                check(c.wait_idle(5), f"{press} done")
                time.sleep(1.3)
                q1 = [e for e in log if e[0] == "mm"
                      and e[1] == "/surfaces/Quad-1/opacity"]
                before = [e[2] for e in q1 if e[3] < t0]
                after = [e[2] for e in q1 if e[3] >= t0]
                at = before[-1] if before else None
                # One ramp step may already have been on its way out at
                # the press (the perceptual fade-up's biggest is 2/30).
                step = 2.0 / 30
                ok = (at is not None and after and after[-1] == 0.0
                      and after[0] <= at + step + 1e-6
                      and all(b <= a + 1e-6 for a, b in
                              zip(after, after[1:])))
                check(ok, f"{press} {delay * 1000:.0f} ms into a Resume: "
                          f"level at the press {at}, then never up: "
                          f"{[round(v, 3) for v in after[:6]]} ... "
                          f"{after[-1:] if after else None}")
            finally:
                c.close()
                link.close()
    print("  ok")


def test_conductor_rehearsal_hold_mid_fade_never_records_the_video_lit():
    section("conductor: a rehearsal Hold that stops a Resume's video fade-up "
            "part way leaves the video recorded unknown, not lit, and the "
            "next Resume brings it back up (review round 3)")
    C = _cond_mod()
    # The Hold has to land inside a 0.25 s fade-up. On a loaded machine it
    # may land after the fade has finished; that run proves nothing, so the
    # setup is tried again (up to 3 times) rather than passed or failed.
    for attempt in range(3):
        c, rig, log, lines, link, bey = _rt_rig()
        rig.move_s = 0.3
        try:
            c.show_starting("Andy", "rack screen")
            check(c.wait_idle(5), "show start done")
            c.hold("Andy", "rack screen")
            check(c.wait_idle(5), "hold done")
            time.sleep(0.5)
            c.resume("Andy", "rack screen")        # a production fade-up
            time.sleep(0.06)
            c.set_mode(C.REHEARSAL)
            check(c.hold("Andy", "rack screen").ok, "rehearsal Hold accepted")
            check(c.wait_idle(5), "hold done")
            time.sleep(1.5)   # the stopped fade's own report has arrived
            q1 = [e for e in log if e[0] == "mm"
                  and e[1] == "/surfaces/Quad-1/opacity"]
            last = q1[-1][2] if q1 else None
            if last is not None and not 0.0 < last < 1.0 and attempt < 2:
                continue                 # the Hold missed the fade
            rec = c.snapshot()["applied"]["video"]
            # video_cancel() has to make the stopped fade's success stale:
            # if it does not, that report lands after the Hold and records
            # the video lit at whatever level the fade had reached.
            check(last is not None and 0.0 < last < 1.0 and rec != C.LIT,
                  f"the fade stopped part way ({last}) and the video is "
                  f"not recorded lit: {rec}")
            t1 = time.perf_counter()
            c.resume("Andy", "rack screen")
            check(c.wait_idle(5), "rehearsal Resume done")
            time.sleep(1.0)
            up = [e[2] for e in log if e[0] == "mm"
                  and e[1] == "/surfaces/Quad-1/opacity" and e[3] >= t1]
            check(up and up[-1] == 1.0,
                  f"the next Resume brings the video back to full: {up}")
            break
        finally:
            c.close()
            link.close()
    print("  ok")


def _mm_values(socks):
    from ltcplay import madmapper as MM
    out = []
    for s in socks:
        for pkt, _addr in s.sent:
            f = MM.decode_float(pkt)
            if f is not None:
                out.append(f)
    return out


def _settle(svc, c=None):
    """The Service's conductor calls all made (they run on their own
    thread, off the scheduler's lock), then the conductor's own effects."""
    check(svc.flush_conductor(5), "the show conductor's calls all ran")
    if c is not None:
        c.run_pending()


def _confirm(S, svc):
    return svc._apply(S.Event(S.SHOW_CONFIRMED, "madmapper"))


def _two_nights(**over):
    doc = _sched_doc(weekly={
        "sat": {"first_start": "18:00", "interval_min": 20,
                "last_end": "22:00"},
        "sun": {"first_start": "18:00", "interval_min": 20,
                "last_end": "22:00"}}, exceptions={})
    doc.update(over)
    return doc


class _RecCond:
    """A conductor that records every request, what tonight's file said at
    that instant, and can raise, fail, return junk or be slow."""

    def __init__(self, S, work=None):
        self.S = S
        self.work = work
        self.calls = []
        self.raise_on, self.fail_on, self.junk_on = set(), set(), set()
        self.sleep_on = {}
        self.block_on = {}
        self.exit_on = set()

    def _do(self, name, who, screen):
        from datetime import date
        from ltcplay import schedule_service as SV
        disk = None
        if self.work:
            p = SV.tonight_path(date(2026, 11, 14), self.work)
            if os.path.exists(p):
                with open(p) as fh:
                    d = json.load(fh)
                disk = (d["state"], d["running"])
        self.calls.append((name, who, screen, disk))
        if name in self.block_on:
            self.block_on[name].wait(10)
        if name in self.sleep_on:
            time.sleep(self.sleep_on[name])
        if name in self.raise_on:
            raise RuntimeError(f"{name} blew up")
        if name in self.exit_on:
            raise SystemExit(f"{name} asked to exit")
        if name in self.junk_on:
            return "fine"
        C = _cond_mod()
        if name in self.fail_on:
            return C.failed(f"{name} could not be done")
        return C.done(f"{name} done")

    def names(self, since=0):
        return [c[0] for c in self.calls[since:]]

    def hold(self, who="", screen=""):
        return self._do("hold", who, screen)

    def resume(self, who="", screen=""):
        return self._do("resume", who, screen)

    def stop(self, who="", screen=""):
        return self._do("stop", who, screen)

    def show_starting(self, who="", screen=""):
        return self._do("show_starting", who, screen)

    def show_stopped(self, who="", screen=""):
        return self._do("show_stopped", who, screen)

    def failed_start(self, who="", screen=""):
        return self._do("failed_start", who, screen)

    def intermission(self, who="", screen=""):
        return self._do("intermission", who, screen)


def test_schedule_drives_the_show_conductor():
    section("scheduler: Hold, Resume, Stop, a confirmed show and every way "
            "out of a show reach the show conductor; what it does not "
            "perform is still journaled as not performed")
    S = _sched()
    if S is None:
        return
    import tempfile
    c, rig, T, lines = _cond()
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 55)]
    svc = _svc(S, work, now, conductor=c)
    svc.tick()
    _settle(svc, c)
    check(svc.machine.state == S.STANDBY,
          f"setup: within the preshow lead, the intermission is already "
          f"running: {svc.machine.state}")
    check(c.snapshot()["look"] == "BETWEEN",
          f"leaving the show (the INTERMISSION bundle) reached the conductor "
          f"as its BETWEEN look: {c.snapshot()}")
    sent = [r for r in svc.journal if r.get("action") == "conductor"
            and r.get("outcome") == "sent"]
    rows = [r for r in svc.journal if r.get("action") == "INTERMISSION"]
    check(sent and rows and "Not performed, dry run" in rows[0]["text"],
          f"the journal says the conductor was told the show was left, AND "
          f"that the intermission timeline itself was not performed (the "
          f"conductor has no such thing): {sent[:1]} {rows[:1]}")

    now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    check(svc.machine.state == S.SHOW, "show 1 starts on schedule")
    check(c.snapshot()["look"] == "BETWEEN",
          f"START_SHOW alone does not bring the rig up: the conductor only "
          f"does that for a show cue that is playing: {c.snapshot()['look']}")
    rows = [r for r in svc.journal if r.get("action") == "START_SHOW"]
    check(rows and "Not performed, dry run" in rows[-1]["text"],
          f"START_SHOW is journaled as not performed, because it was not: "
          f"{rows[-1:]}")
    now[0] = _den(S, 18, 0, 1)
    _confirm(S, svc)
    _settle(svc, c)
    check(c.snapshot()["look"] == "PLAYING" and not svc.machine.fault,
          f"once the show is confirmed running (SHOW_CONFIRMED) the "
          f"conductor brings the rig up: {c.snapshot()} {svc.machine.faults}")

    now[0] = _den(S, 18, 1)
    out = svc._apply(_op(S, S.HOLD_ON))
    _settle(svc, c)
    check(out.accepted and svc.machine.state == S.PAUSED and
          c.snapshot()["look"] == "HELD",
          f"Hold reached the conductor as a Hold: {c.snapshot()}")
    now[0] = _den(S, 18, 2)
    out = svc._apply(_op(S, S.RESUME))
    _settle(svc, c)
    check(out.accepted and svc.machine.state == S.SHOW and
          c.snapshot()["look"] == "PLAYING",
          f"Resume reached the conductor as a Resume: {c.snapshot()}")

    now[0] = _den(S, 18, 3)
    out = svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(svc, c)
    check(out.accepted and c.snapshot()["look"] == "STOPPED_DARK"
          and rig.count("flames_disarm_all") == 1,
          f"Stop reached the conductor as a Stop, disarm included: "
          f"{c.snapshot()}")
    said = [r["text"] for r in svc.journal if r.get("action") == S.STOP_SHOW]
    check(said and "nothing was disarmed" not in said[-1].lower(),
          f"the Stop line never says nothing was disarmed (Jeff, "
          f"2026-09-27): {said[-1:]}")
    done_rows = [r for r in svc.journal if r.get("action") == "conductor"
                 and r.get("outcome") == "done" and "Stop" in r["text"]]
    check(done_rows and "disarm sent" in done_rows[-1]["text"],
          f"and the conductor's own line says what it sent: {done_rows[-1:]}")

    # Close for the night tells the conductor the show is over; closing's
    # pixel fade and blackout have no conductor method and stay "not
    # performed".
    now[0] = _den(S, 18, 5)
    k = len(rig.calls)
    svc._apply(_op(S, S.END_NIGHT, confirmed=True))
    _settle(svc, c)
    snap = c.snapshot()
    # (After the Stop above the rig is already darker than BETWEEN.)
    check(svc.machine.state == S.OFF and
          snap["look"] in ("BETWEEN", "STOPPED_DARK")
          and snap["applied"]["lasers"] == "black"
          and snap["applied"]["flames"] == "zero",
          f"Close for the night takes the conductor out of the show: "
          f"{snap} {rig.names(k)}")
    rows = [r for r in svc.journal if r.get("action") == "BLACKOUT"]
    check(rows and "Not performed, dry run" in rows[-1]["text"],
          f"closing's own blackout is still only journaled: {rows[-1:]}")

    # The LAST show of the night ending tells it too (it used to stay
    # PLAYING, lasers lit and flame cues live, after the night closed).
    c, rig, T, lines = _cond()
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 39)]
    svc = _svc(S, work, now, conductor=c)
    svc.tick()
    now[0] = _den(S, 21, 40)
    svc.tick()
    _confirm(S, svc)
    _settle(svc, c)
    check(c.snapshot()["look"] == "PLAYING", "setup: the last show plays")
    now[0] = _den(S, 21, 47, 21)
    svc.tick()
    _settle(svc, c)
    snap = c.snapshot()
    check(svc.machine.state == S.OFF and snap["look"] == "BETWEEN" and
          snap["applied"]["lasers"] == "black" and
          snap["applied"]["flames"] == "zero",
          f"after the last show ends the conductor is out of the show, "
          f"lasers dark and flame cues zero: {svc.machine.state} {snap}")

    # Without a conductor attached nothing changes from before: every
    # effect is only journaled as a dry run, and nothing is sent.
    work2 = tempfile.mkdtemp()
    now2 = [_den(S, 17, 55)]
    plain = _svc(S, work2, now2)
    plain.tick()
    rows = [r for r in plain.journal if r.get("action") == "INTERMISSION"]
    check(rows and "Not performed, dry run" in rows[0]["text"] and
          not [r for r in plain.journal if r.get("action") == "conductor"],
          f"with no conductor attached, effects are only journaled, "
          f"exactly as before: {rows}")
    print("  ok")


def test_schedule_conductor_calls_after_the_save_and_off_the_lock():
    section("scheduler: the show conductor is asked only after tonight is "
            "saved and journaled, in order, on its own thread, and anything "
            "it raises or refuses is a fault")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date
    from ltcplay import schedule_service as SV
    grace = _sched_doc(weekly={"sat": {"first_start": "18:00",
                                       "interval_min": 20,
                                       "last_end": "22:00"}},
                       exceptions={}, late_grace_s=15)
    # The save comes first (schedule.py's effects contract, rule 1).
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59)]
    rec = _RecCond(S, work)
    svc = _svc(S, work, now, conductor=rec)
    svc.start(thread=False)
    now[0] = _den(S, 18, 0)
    svc.tick()
    now[0] = _den(S, 18, 0, 1)
    _confirm(S, svc)
    now[0] = _den(S, 18, 1)
    svc._apply(_op(S, S.HOLD_ON))
    _settle(svc)
    got = {c[0]: c[3] for c in rec.calls}
    check(got.get("show_starting") == (S.SHOW, 1) and
          got.get("hold") == (S.PAUSED, 1),
          f"each request ran with tonight already saved: {got}")

    # A conductor that raises, fails or returns junk: the start is saved
    # and journaled anyway, the failure is a fault, and a restart inside
    # the grace never starts the same show twice.
    for how in ("raise_on", "fail_on", "junk_on"):
        work = tempfile.mkdtemp()
        now = [_den(S, 17, 59)]
        rec = _RecCond(S, work)
        getattr(rec, how).add("show_starting")
        svc = _svc(S, work, now, rule=grace, conductor=rec)
        svc.start(thread=False)
        now[0] = _den(S, 18, 0)
        svc._safe_tick()
        now[0] = _den(S, 18, 0, 1)
        _confirm(S, svc)
        _settle(svc)
        with open(SV.tonight_path(date(2026, 11, 14), work)) as fh:
            disk = json.load(fh)
        check(disk["state"] == S.SHOW and
              any(r.get("action") == "fire" for r in svc.journal),
              f"[{how}] the start was saved and journaled: {disk['state']}")
        bad = [r for r in svc.journal if r.get("fault") and
               "did not carry out Show start" in r["text"]]
        check(svc.machine.fault and bad,
              f"[{how}] the conductor's failure is a fault, on the page and "
              f"in the journal: {svc.machine.faults}")
        svc.stop()
        now[0] = _den(S, 18, 0, 5)
        again = _svc(S, work, now, rule=grace, conductor=_RecCond(S, work))
        again.start(thread=False)
        check(again.machine.slot(1).status == S.FAULT and
              again.machine.shows_started == 1,
              f"[{how}] restarted inside the grace, show 1 is not started "
              f"twice: {again.machine.slot(1)}")
        again.stop()

    # A slow conductor no longer holds the scheduler: the press, a status
    # poll and the next press all return at once, and the requests still
    # reach it in the order they were made.
    #
    # The conductor here does not answer until this test lets it (a gate it
    # blocks on), so "did not wait" is a fact, not a stopwatch reading: a
    # press that waited would sit on the gate for the conductor's whole 10 s
    # patience, and the proof that one did not is that it has returned
    # while the conductor is still inside the gated call (flush_conductor(0)
    # says the line is still busy). The old form slept 1.5 s in the
    # conductor and bounded each press at 0.75 s of wall clock, which also
    # timed the press's own disk work: a confirm or an Abort saves
    # tonight.json (flushed to disk, os.replace retried with sleeps while a
    # scanner holds the file), creates the latch file and fsyncs several
    # journal lines. On a shared Windows runner that alone passed 0.75 s and
    # "nor does an Abort" failed with the conductor not even slow on abort
    # (#64's windows-latest run, 2026-10-15). The times are still printed,
    # for the eye, and nothing is decided by them.
    import threading as _th
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 0)]
    rec = _RecCond(S)
    gate = _th.Event()
    rec.block_on = {"show_starting": gate}
    svc = _svc(S, work, now, conductor=rec)
    svc.start(thread=False)
    now[0] = _den(S, 18, 0, 1)
    t0 = time.perf_counter()
    _confirm(S, svc)
    a = time.perf_counter() - t0
    t0 = time.perf_counter()
    svc.state_view()
    b = time.perf_counter() - t0
    t0 = time.perf_counter()
    svc._apply(_op(S, S.HOLD_ON))
    svc._apply(_op(S, S.RESUME))
    c_ = time.perf_counter() - t0
    still_in = not svc.flush_conductor(0)
    seen = rec.names()
    gate.set()
    check(still_in and "hold" not in seen,
          f"nothing waits for a conductor that has not answered: the confirm "
          f"({a:.2f} s), a status poll ({b:.2f} s) and Hold then Resume "
          f"({c_:.2f} s) all returned while it was still inside "
          f"show_starting, the Hold still waiting its turn: {seen}")
    _settle(svc)
    check(rec.names() == ["intermission", "show_starting", "hold", "resume"],
          f"and the conductor got them in order: {rec.names()}")
    gate = _th.Event()
    rec.block_on = {"stop": gate}
    t0 = time.perf_counter()
    svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    took = time.perf_counter() - t0
    still_in = not svc.flush_conductor(0)
    gate.set()
    check(still_in, f"nor does a Stop: the press returned ({took:.2f} s) "
                    f"while the conductor had not answered it")
    rec.block_on = {}
    _settle(svc)
    check(rec.names()[-1:] == ["stop"], f"which follows them: {rec.names()}")
    print("  ok")


def test_schedule_failed_start_leaves_groups_and_raises_an_alert():
    section("scheduler: a failed start (no timecode) goes dark, journals "
            "loudly, leaves every flame group AS IT IS, latches nothing, and "
            "raises a 'start' alert for the rack screen and the booth; Start "
            "now works at once (Jeff's ruling 1, 2026-10-12). This test used "
            "to be test_schedule_failed_start_disarms_without_latch and "
            "asserted the disarm.")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import alerts as AL
    c, rig, T, lines = _cond()
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59)]
    svc = _svc(S, work, now, conductor=c)
    alerts = AL.Alerts(journal=lambda text, **kw: None, booth=None)
    svc.alert_sink = alerts.raise_
    svc.tick()
    now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    k = len(rig.calls)
    now[0] = _den(S, 18, 0, 5)
    svc._apply(S.Event(S.SHOW_FAILED, "madmapper", detail="no timecode"))
    _settle(svc)
    c.run_pending()
    a = c.snapshot()["applied"]
    check("flames_disarm_all" not in rig.names(k) and not a["disarmed"]
          and a["flames"] == "zero",
          f"the flame cues are zero (never lit: the show never confirmed) "
          f"and NO group is disarmed: {rig.names(k)} {a}")
    check(not hasattr(c, "latched") and not hasattr(svc, "_aborted")
          and not hasattr(svc.machine, "abort_latched"),
          "nothing latches: the latch is gone")
    check(a["flames"] == "zero" and a["lasers"] == "black" and
          a["video"] in ("black", "stopped") and a["pixels"] == "black" and
          a["music"] == "stopped" and "music_halt" in rig.names(k),
          f"the rig is dark: lasers blanked, video and pixels down, music "
          f"stopped, flame cues zero: {a}")
    rows = [r for r in svc.journal if r.get("action") == S.SHOW_FAILED]
    sent = [r for r in svc.journal if r.get("action") == "conductor" and
            "Failed start" in r["text"]]
    check(rows and rows[-1].get("fault") and
          S.FAILED_START_NOT_DISARMED in rows[-1]["text"] and
          "stays as it was" in rows[-1]["text"] and sent and
          "left as it was" in sent[0]["text"] and
          "is disarmed" not in sent[0]["text"],
          f"the journal says it loudly, as a fault, and says the groups stay "
          f"as they were: {rows[-1:]} {sent[:1]}")
    open_ = alerts.open()
    check(len(open_) == 1 and open_[0].kind == "start"
          and open_[0].text.startswith(svc.start_alert(
              1, "no timecode", svc.FAILED_START_ALERT))
          and open_[0].text.startswith("Show 1 did not start: no timecode.")
          and "stays as it was" in open_[0].text
          and "Acknowledge" in open_[0].text,
          f"one 'start' alert is raised, saying the groups stay as they were "
          f"and what to press: {[x.view() for x in open_]}")
    al_rows = [r for r in svc.journal if r.get("action") == "alert"]
    check(not al_rows, "the alert's own journal line is the alert service's "
                       "(through the Remote), not a second scheduler line")
    rig_before = len(rig.calls)
    check(svc.machine.state == S.STANDBY and svc.machine.dark,
          "the scheduler waits dark, no intermission")
    now[0] = _den(S, 18, 1)
    out = svc._apply(_op(S, S.START_NOW))
    _confirm(S, svc)
    _settle(svc, c)
    check(out.accepted and c.snapshot()["look"] == "PLAYING",
          f"Start now works straight away, with no Reset, and the rig comes "
          f"up: {out.refused} {c.snapshot()['look']}")
    check(not [x for x in rig.names(rig_before) if "arm" in x],
          f"and nothing ltcplay sends arms or disarms a flame group: "
          f"{rig.names(rig_before)}")
    check(len(alerts.open()) == 1,
          "the alert waits for a person; the next start does not clear it")
    # Without a show conductor: the same line, and the same alert.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59)]
    bare = _svc(S, work, now)
    raised = []
    bare.alert_sink = lambda kind, text: raised.append((kind, text))
    bare.tick()
    now[0] = _den(S, 18, 0)
    bare.tick()
    now[0] = _den(S, 18, 0, 5)
    bare._apply(S.Event(S.SHOW_FAILED, "madmapper", detail="no timecode"))
    rows = [r for r in bare.journal if r.get("action") == S.SHOW_FAILED]
    check(rows and S.FAILED_START_NOT_DISARMED in rows[-1]["text"]
          and raised == [("start", bare.start_alert(
              1, "no timecode", bare.FAILED_START_ALERT))],
          f"with no conductor the line says the same and the alert is "
          f"raised too: {rows[-1:]} {raised}")
    # An alert sink that raises never stops the scheduler.
    bare.alert_sink = lambda kind, text: 1 / 0
    now[0] = _den(S, 18, 20)
    bare.tick()
    now[0] = _den(S, 18, 20, 5)
    bare._apply(S.Event(S.SHOW_FAILED, "madmapper", detail="no timecode"))
    bad = [r for r in bare.journal if r.get("action") == "alert"]
    check(bad and bad[-1].get("fault") and "could not be raised" in
          bad[-1]["text"], f"a broken sink is one fault line: {bad[-1:]}")
    for name in ("schedule.py", "schedule_service.py", "conductor.py"):
        src = open(os.path.join(os.path.dirname(S.__file__), name),
                   encoding="utf-8").read()
        check("\u2014" not in src and "\u2013" not in src,
              f"{name} has no em or en dashes")
    # The LAST show fails to start: the night closes at once, and closing
    # must not cut the stop's fade short (video and pixels still go down).
    c, rig, T, lines = _cond()
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 39)]
    svc = _svc(S, work, now, conductor=c)
    svc.tick()
    now[0] = _den(S, 21, 40)
    svc.tick()
    _settle(svc, c)
    now[0] = _den(S, 21, 40, 5)
    svc._apply(S.Event(S.SHOW_FAILED, "madmapper", detail="no timecode"))
    now[0] = _den(S, 21, 40, 6)
    svc.tick()
    _settle(svc, c)
    a = c.snapshot()["applied"]
    check(svc.machine.state == S.OFF and a["video"] in ("black", "stopped")
          and a["pixels"] == "black" and a["lasers"] == "black",
          f"a failed last show still takes video and pixels down, though "
          f"the night closes straight after: {svc.machine.state} {a}")
    print("  ok")


def test_schedule_restart_after_a_stopped_show_stays_dark():
    section("scheduler: a restart after a failed start or a cut "
            "show stays dark until the operator acts or the next show "
            "starts; it no longer brings the intermission loop back")
    S = _sched()
    if S is None:
        return
    rule = _one_night_rule(S)
    I = S.INTERMISSION

    def restart(m, at):
        doc = json.loads(json.dumps(S.machine_to_doc(m)))
        back = S.machine_from_doc(doc, rule, m.date, at)
        return doc, S.step(back, S.Event(S.BOOT_DONE, "system"), at)

    cases = {}
    n = _Night(S, rule)
    n.boot(_den(S, 17, 50))
    n.tick(_den(S, 18, 0))
    n.do(S.SHOW_FAILED, "madmapper", _den(S, 18, 0, 5), detail="no timecode")
    cases["after a failed start"] = n.m
    n = _Night(S, rule)
    n.boot(_den(S, 17, 50))
    n.tick(_den(S, 18, 0))
    _, o = restart(n.m, _den(S, 18, 3))
    cases["after a show cut by a restart"] = o.machine
    for name, m in cases.items():
        # A failed start and a cut show latch nothing (a Stop holds the
        # schedule instead: its own tests).
        check(m.dark and m.state == S.STANDBY, f"{name}: dark, in STANDBY")
        doc, o = restart(m, _den(S, 18, 5))
        kinds = [e.kind for e in o.effects]
        check(doc.get("dark") is True, f"{name}: tonight's file says dark")
        check(o.machine.state == S.STANDBY and I not in kinds and
              o.machine.dark,
              f"{name}: a second restart stays dark: {o.machine.state} "
              f"{kinds}")
        check("stays dark" in o.log[-1].text,
              f"{name}: and says so: {o.log[-1].text}")
        o2 = S.step(o.machine, S.Event(S.TICK, "scheduler"),
                    _den(S, 18, 20))
        o3 = S.step(o.machine, S.Event(S.HOLD_ON, "operator", who="Andy",
                                       screen="rack screen"),
                    _den(S, 18, 6))
        check(o2.machine.running == 2 and not o2.machine.dark,
              f"{name}: the next show still starts on schedule")
        check(I in [e.kind for e in o3.effects] and not o3.machine.dark,
              f"{name}: an operator's press brings the look back")
    # A dark list with every show still to come (an older version's
    # Abort before the first show, or a Stop's Hold that was Resumed):
    # a restart waits dark in STANDBY, no preshow look (cold review A of
    # #199: the mutation lost its latch test).
    from dataclasses import replace as _rp
    n = _Night(S, rule)
    n.boot(_den(S, 16, 0))
    m = _rp(n.m, dark=True)
    check(all(x.status == S.PENDING for x in m.slots),
          "setup: every show still to come")
    doc, o = restart(m, _den(S, 16, 5))
    kinds = [e.kind for e in o.effects]
    check(o.machine.state == S.STANDBY and o.machine.dark and
          S.PRESHOW_LOOK not in kinds and I not in kinds,
          f"a dark night with every show to come waits dark in STANDBY, no "
          f"preshow look: {o.machine.state} {kinds}")
    # A night that never went dark saves exactly as before.
    n = _Night(S, rule)
    n.boot(_den(S, 17, 50))
    check("dark" not in S.machine_to_doc(n.m),
          "a night that was never dark has no `dark` in its file")
    print("  ok")


def test_schedule_preshow_lead_on_tick_and_resume():
    section("scheduler: the intermission loop takes over from the preshow "
            "look 30 minutes before the first show, on the tick and on a "
            "Resume (Jeff, 2026-10-01)")
    S = _sched()
    if S is None:
        return
    rule = _one_night_rule(S)
    n = _Night(S, rule)
    n.boot(_den(S, 17, 0))
    check(n.m.state == S.IDLE, "setup: the preshow look at 17:00")
    o = n.tick(_den(S, 17, 29, 59))
    check(n.m.state == S.IDLE and not o.effects,
          "17:29:59 is still the preshow look")
    o = n.tick(_den(S, 17, 30))
    check(n.m.state == S.STANDBY and
          [e.kind for e in o.effects] == [S.INTERMISSION],
          f"17:30 starts the intermission loop: {n.m.state} {o.effects}")
    for at, want in (((17, 10), S.IDLE), ((17, 45), S.STANDBY)):
        n = _Night(S, rule)
        n.boot(_den(S, 17, 0))
        n.op(S.HOLD_ON, _den(S, 17, 5))
        o = n.op(S.RESUME, _den(S, *at))
        check(n.m.state == want,
              f"Resume at {at[0]}:{at[1]:02d} after a Hold from the preshow "
              f"look lands in {want}: {n.m.state}")
    n.audit("preshow lead")
    print("  ok")


def test_schedule_night_reset_boundary():
    section("scheduler: a show night runs until the 2 AM nightly reset, "
            "local, on the next calendar day: just before it, at it and "
            "just after it, and on the nights the clocks change (Jeff, "
            "2026-10-03)")
    S = _sched()
    if S is None:
        return
    from datetime import date, datetime, time, timedelta, timezone
    check(S.NIGHT_RESET == time(2, 0) and S.reset_words() == "2 AM",
          f"the nightly reset is one constant, 2 AM: {S.NIGHT_RESET} "
          f"{S.reset_words()}")
    den = S.zone("America/Denver")
    sat, sun = date(2026, 11, 14), date(2026, 11, 15)
    for at, want, what in (
            (_den(S, 23, 59, 59, d=(2026, 11, 14)), sat, "Saturday 23:59:59"),
            (_den(S, 0, 0, 0, d=(2026, 11, 15)), sat, "Sunday 00:00"),
            (_den(S, 1, 59, 59, 999999, d=(2026, 11, 15)), sat,
             "Sunday 01:59:59.999999, just before the reset"),
            (_den(S, 2, 0, 0, d=(2026, 11, 15)), sun,
             "Sunday 02:00:00, at the reset"),
            (_den(S, 2, 0, 1, d=(2026, 11, 15)), sun,
             "Sunday 02:00:01, just after it"),
            (_den(S, 4, 30, d=(2026, 11, 15)), sun,
             "Sunday 04:30, a media shoot"),
            (_den(S, 18, 0, d=(2026, 11, 15)), sun, "Sunday 18:00")):
        check(S.night_of(at, den) == want,
              f"{what} belongs to the night of {want}: "
              f"{S.night_of(at, den)}")
    check(S.night_reset(sat, den) == _den(S, 2, 0, d=(2026, 11, 15)),
          f"Saturday's night ends at 02:00 Sunday: "
          f"{S.night_reset(sat, den)}")

    def utc(*a):
        return datetime(*a, tzinfo=timezone.utc)

    # Denver, autumn 2026-11-01: 01:00 to 02:00 happens twice (MDT, then
    # MST); the reset is 02:00 MST, after both. Spring 2027-03-14: 02:00
    # does not exist; the reset is the first instant after the gap, 03:00
    # MDT, the same real instant 02:00 MST would have been.
    for at, want, what in (
            (utc(2026, 11, 1, 7, 30), date(2026, 10, 31), "01:30 MDT"),
            (utc(2026, 11, 1, 8, 30), date(2026, 10, 31),
             "01:30 MST, the repeated hour"),
            (utc(2026, 11, 1, 8, 59, 59), date(2026, 10, 31),
             "01:59:59 MST"),
            (utc(2026, 11, 1, 9, 0), date(2026, 11, 1), "02:00 MST"),
            (utc(2027, 3, 14, 8, 59, 59), date(2027, 3, 13), "01:59:59 MST"),
            (utc(2027, 3, 14, 9, 0), date(2027, 3, 14),
             "03:00 MDT, straight after the spring gap")):
        check(S.night_of(at, den) == want,
              f"Denver, {what}: the night of {want}, got "
              f"{S.night_of(at, den)}")
    check(S.night_reset(date(2026, 10, 31), den) == utc(2026, 11, 1, 9, 0)
          and S.night_reset(date(2027, 3, 13), den) == utc(2027, 3, 14, 9, 0),
          "night_reset agrees with night_of on both Denver change nights")
    # A zone whose autumn change repeats 02:00 to 03:00 (Berlin): the reset
    # is the first 02:00 (CEST), and the repeated hour stays on the new
    # night; the spring gap is 02:00 to 03:00 there too.
    ber = S.zone("Europe/Berlin")
    for at, want, what in (
            (utc(2026, 10, 24, 23, 59, 59), date(2026, 10, 24),
             "01:59:59 CEST"),
            (utc(2026, 10, 25, 0, 0), date(2026, 10, 25), "02:00 CEST"),
            (utc(2026, 10, 25, 1, 30), date(2026, 10, 25),
             "02:30 CET, the repeated hour"),
            (utc(2027, 3, 28, 0, 59, 59), date(2027, 3, 27), "01:59:59 CET"),
            (utc(2027, 3, 28, 1, 0), date(2027, 3, 28), "03:00 CEST")):
        check(S.night_of(at, ber) == want,
              f"Berlin, {what}: the night of {want}, got "
              f"{S.night_of(at, ber)}")
    check(S.night_reset(date(2026, 10, 24), ber) == utc(2026, 10, 25, 0, 0)
          and S.night_reset(date(2027, 3, 27), ber) == utc(2027, 3, 28, 1, 0),
          "night_reset agrees with night_of on both Berlin change nights")
    # A night's first show may be at the reset, never before it.
    ok = S.parse_rule(_sched_doc(exceptions={"2026-12-05": {
        "first_start": "02:00", "interval_min": 20, "last_end": "06:00"}}))
    check(S.clock(S.expand(ok, date(2026, 12, 5)).starts[0]) == "02:00",
          "a night may start at 02:00, the reset itself")

    # The service on both Denver change nights: a delayed show keeps the
    # night open through the repeated hour, or up to the spring gap, and
    # the night closes at the reset's real instant, not an hour off.
    import tempfile
    from ltcplay import schedule_service as SV
    doc = _sched_doc(season={"first_date": "2026-10-01",
                             "last_date": "2027-03-31"},
                     weekly={"sat": {"first_start": "18:00",
                                     "interval_min": 20,
                                     "last_end": "22:00"}}, exceptions={})
    for night, ticks in (
            (date(2026, 10, 31), (utc(2026, 11, 1, 7, 30),
                                  utc(2026, 11, 1, 8, 30),
                                  utc(2026, 11, 1, 8, 59, 59))),
            (date(2027, 3, 13), (utc(2027, 3, 14, 8, 59, 59),))):
        work = tempfile.mkdtemp()
        d3 = (night.year, night.month, night.day)
        now = [_den(S, 21, 30, d=d3)]
        svc = _svc(S, work, now, rule=doc)
        svc.start(thread=False)
        svc._apply(_op(S, S.HOLD_ON))
        now[0] = _den(S, 21, 41, d=d3)
        svc.tick()
        n = svc.machine.delayed().n if svc.machine.delayed() else None
        check(n is not None, f"{night}: setup, a delayed show")
        for t in ticks:
            now[0] = t
            svc.tick()
            check(svc.machine.date == night and
                  svc.machine.delayed() is not None,
                  f"{night}: at {t.astimezone(den):%H:%M:%S %Z} the night is "
                  f"still open: {svc.machine.date}")
        reset = S.night_reset(night, den)
        now[0] = reset
        svc.tick()
        with open(SV.tonight_path(night, work)) as fh:
            old = json.load(fh)
        st = [x for x in old["slots"] if x["n"] == n][0]
        check(svc.machine.date == night + timedelta(days=1) and
              st["status"] == S.MISSED and st["reason"] == S.RESET_MISSED,
              f"{night}: at {reset.astimezone(den):%H:%M %Z} the night "
              f"closes and show {n} is MISSED: {svc.machine.date} {st}")
        svc.stop()
    print("  ok")


def test_schedule_delayed_night_closes_at_the_2am_reset():
    section("scheduler: a night kept open past midnight by a delayed show "
            "closes at the 2 AM nightly reset; the delayed show is MISSED, "
            "out loud, and the next night runs. Start now after the reset "
            "never starts last night's show (Jeff, 2026-10-03)")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date
    from ltcplay import journal as J
    from ltcplay import schedule_service as SV
    for resumed in (True, False):
        work = tempfile.mkdtemp()
        now = [_den(S, 21, 30)]
        svc = _svc(S, work, now, rule=_two_nights())
        svc.start(thread=False)
        svc._apply(_op(S, S.HOLD_ON))
        now[0] = _den(S, 21, 41)
        svc.tick()
        if resumed:
            svc._apply(_op(S, S.RESUME))
        epoch = svc.hold_epoch
        for at in ((23, 59, 59, 0, (2026, 11, 14)),
                   (0, 0, 1, 0, (2026, 11, 15)),
                   (1, 59, 59, 999999, (2026, 11, 15))):
            now[0] = _den(S, *at[:4], d=at[4])
            svc.tick()
            check(str(svc.machine.date) == "2026-11-14" and
                  svc.machine.delayed() is not None,
                  f"[resumed={resumed}] at {now[0]:%a %H:%M:%S.%f} Saturday "
                  f"is still open, show 12 still waits")
        check(svc.hold_epoch == epoch,
              "the hold epoch does not move with the date alone")
        now[0] = _den(S, 2, 0, d=(2026, 11, 15))
        svc.tick()
        check(str(svc.machine.date) == "2026-11-15" and
              svc.machine.state == S.IDLE,
              f"[resumed={resumed}] at Sunday 02:00 Saturday closes and "
              f"Sunday's night begins with its preshow look: "
              f"{svc.machine.date} {svc.machine.state}")
        line = [r for r in svc.journal if r.get("show") == 12 and
                r.get("action") == "miss"]
        check(line and line[-1].get("fault") and
              "Show 12" in line[-1]["text"] and
              "still waiting at the 2 AM nightly reset" in line[-1]["text"],
              f"[resumed={resumed}] a fault line names show 12 and says "
              f"why: {line[-1:]}")
        with open(SV.tonight_path(date(2026, 11, 14), work)) as fh:
            sat = json.load(fh)
        check(sat["slots"][11]["status"] == S.MISSED and
              sat["slots"][11]["reason"] == S.RESET_MISSED and
              "still waiting at the 2 AM nightly reset" in S.RESET_MISSED,
              f"Saturday's saved list says show 12 was MISSED at the reset: "
              f"{sat['slots'][11]}")
        check(any("Show 12" in f and "never started" in f
                  for f in sat["faults"]),
              f"[resumed={resumed}] and it is on Saturday's fault list, the "
              f"one the page shows: {sat['faults']}")
        summary = os.path.join(work, "nights",
                               J.summary_name(date(2026, 11, 14)))
        check(os.path.exists(summary), "Saturday's summary is written")
        if not resumed:
            check(svc.hold_epoch == epoch + 1,
                  f"setting aside a night still on Hold bumps the hold "
                  f"epoch, so an announcement's claim on it is no longer "
                  f"current: {epoch} -> {svc.hold_epoch}")
        if resumed:
            # Start now after the reset is Sunday's extra show, never
            # Saturday's delayed one.
            now[0] = _den(S, 2, 0, 5, d=(2026, 11, 15))
            out = svc._apply(_op(S, S.START_NOW))
            run = svc.machine.slot(svc.machine.running)
            check(out.accepted and str(svc.machine.date) == "2026-11-15" and
                  run is not None and run.origin == "operator",
                  f"Start now at 02:00:05 runs an extra show on Sunday, not "
                  f"Saturday's show 12: {svc.machine.date} {run}")
            svc.stop()
            continue
        now[0] = _den(S, 17, 30, d=(2026, 11, 15))
        svc.tick()
        now[0] = _den(S, 18, 0, d=(2026, 11, 15))
        svc.tick()
        check(svc.machine.state == S.SHOW and svc.machine.running == 1,
              f"[resumed={resumed}] Sunday's 18:00 show starts")
        svc.stop()

    # Start now just before the reset still starts the delayed show, and a
    # show running at the reset is not cut: its night closes once it ends.
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 30)]
    svc = _svc(S, work, now, rule=_two_nights())
    svc.start(thread=False)
    svc._apply(_op(S, S.HOLD_ON))
    now[0] = _den(S, 21, 41)
    svc.tick()
    svc._apply(_op(S, S.RESUME))
    now[0] = _den(S, 1, 59, 59, d=(2026, 11, 15))
    svc.tick()
    out = svc._apply(_op(S, S.START_NOW))
    check(out.accepted and svc.machine.running == 12,
          f"Start now at 01:59:59 starts the delayed show 12: {out.refused}")
    for t in ((2, 0, 0), (2, 5, 0)):
        now[0] = _den(S, *t, d=(2026, 11, 15))
        svc.tick()
        check(str(svc.machine.date) == "2026-11-14" and
              svc.machine.running == 12,
              f"at {t} show 12 is still running on Saturday's night: "
              f"{svc.machine.date} {svc.machine.state}")
    # Show 12 ends at 02:07:19; its 120 s guard is over at 02:09:19, and
    # only then does Saturday hand over (review of PR #196, round 2).
    now[0] = _den(S, 2, 8, d=(2026, 11, 15))
    svc.tick()
    check(str(svc.machine.date) == "2026-11-14",
          "inside the guard after show 12, it is still Saturday's night")
    now[0] = _den(S, 2, 10, d=(2026, 11, 15))
    svc.tick()
    svc.tick()
    with open(SV.tonight_path(date(2026, 11, 14), work)) as fh:
        sat = json.load(fh)
    check(str(svc.machine.date) == "2026-11-15" and
          sat["slots"][11]["status"] == S.DONE,
          f"once it has ended, Saturday closes with show 12 DONE and Sunday "
          f"begins: {svc.machine.date} {sat['slots'][11]['status']}")
    svc.stop()

    # A show paused (a Hold during it) past the next night's preshow: the
    # hand over has come (its planned end and guard are long past), yet a
    # running or paused show is never set aside: the night stays.
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 39)]
    svc = _svc(S, work, now, rule=_two_nights())
    svc.start(thread=False)
    now[0] = _den(S, 21, 40)
    svc.tick()
    now[0] = _den(S, 21, 40, 2)
    _confirm(S, svc)
    now[0] = _den(S, 21, 41)
    svc._apply(_op(S, S.HOLD_ON))
    check(svc.machine.state == S.PAUSED and svc.machine.running == 12,
          f"setup: show 12 paused: {svc.machine.state}")
    now[0] = _den(S, 17, 58, d=(2026, 11, 15))
    svc.tick()
    check(str(svc.machine.date) == "2026-11-14" and
          svc.machine.state == S.PAUSED and svc.machine.running == 12,
          f"a paused show past the next night's preshow is never set aside: "
          f"{svc.machine.date} {svc.machine.state} {svc.machine.running}")
    svc.stop()
    print("  ok")


def test_schedule_restart_across_the_2am_reset():
    section("scheduler: ltcplay restarted before the 2 AM reset carries on "
            "with last night (a delayed show still waits; a show cut by the "
            "restart is FAULT and the rig dark); restarted after it, last "
            "night is closed out loud: a delayed show MISSED, a cut show "
            "FAULT with the rig dark, and nothing from it runs, days later "
            "included")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date
    from ltcplay import journal as J
    from ltcplay import schedule_service as SV

    def held_night():
        work = tempfile.mkdtemp()
        now = [_den(S, 21, 30)]
        svc = _svc(S, work, now, rule=_two_nights())
        svc.start(thread=False)
        svc._apply(_op(S, S.HOLD_ON))
        now[0] = _den(S, 21, 41)
        svc.tick()
        svc._apply(_op(S, S.RESUME))
        return work, now, svc

    def saturday(work):
        with open(SV.tonight_path(date(2026, 11, 14), work)) as fh:
            return json.load(fh)

    # Restarted at 00:30: still Saturday's night, show 12 still waits.
    work, now, svc = held_night()
    now[0] = _den(S, 0, 20, d=(2026, 11, 15))
    svc.tick()
    svc.stop()
    now[0] = _den(S, 0, 30, d=(2026, 11, 15))
    again = _svc(S, work, now, rule=_two_nights())
    again.start(thread=False)
    check(str(again.machine.date) == "2026-11-14" and
          again.machine.delayed() is not None and
          again.machine.delayed().n == 12,
          f"restarted at 00:30, Saturday is still the night with show 12 "
          f"waiting: {again.machine.date} {again.machine.state}")
    out = again._apply(_op(S, S.START_NOW))
    check(out.accepted and again.machine.running == 12,
          f"Start now still starts it: {out.refused}")
    again.stop()

    # The delayed show was running after midnight when ltcplay stopped, and
    # it restarted before the reset: the show is cut, the rig goes dark,
    # and it stays dark through the reset (the next night's preshow look
    # does not bring it back; only a show or an operator does).
    work, now, svc = held_night()
    now[0] = _den(S, 0, 10, d=(2026, 11, 15))
    svc.tick()
    svc._apply(_op(S, S.START_NOW))
    check(svc.machine.running == 12, "setup: show 12 runs at 00:10")
    now[0] = _den(S, 0, 12, d=(2026, 11, 15))
    svc.tick()
    svc.stop()
    c, rig, T, lines = _cond()
    now[0] = _den(S, 0, 15, d=(2026, 11, 15))
    again = _svc(S, work, now, rule=_two_nights(), conductor=c)
    again.start(thread=False)
    _settle(again, c)
    cut = [r for r in again.journal if r.get("fault") and
           "restarted during show 12" in r["text"]]
    check(saturday(work)["slots"][11]["status"] == S.FAULT and cut and
          str(again.machine.date) == "2026-11-14",
          f"show 12 is a cut show: FAULT with a fault line, Saturday still "
          f"the night: {saturday(work)['slots'][11]['status']} "
          f"{again.machine.date}")
    check(c.snapshot()["look"] == "STOPPED_DARK" and not hasattr(c, "latched") and
          "flames_disarm_all" not in rig.names(),
          f"the conductor took the rig dark, no latch, no disarm: "
          f"{c.snapshot()['look']} {rig.names()}")
    now[0] = _den(S, 2, 0, d=(2026, 11, 15))
    again.tick()
    _settle(again, c)
    check(str(again.machine.date) == "2026-11-15" and
          c.snapshot()["look"] == "STOPPED_DARK",
          f"at the 2 AM reset Sunday begins, and the rig stays dark: "
          f"{again.machine.date} {c.snapshot()['look']}")
    again.stop()

    # Restarted at 02:30, after the reset, with show 12 still delayed.
    work, now, svc = held_night()
    svc.stop()
    rec = _RecCond(S)
    now[0] = _den(S, 2, 30, d=(2026, 11, 15))
    again = _svc(S, work, now, rule=_two_nights(), conductor=rec)
    again.start(thread=False)
    _settle(again)
    sat = saturday(work)
    line = [r for r in again.journal if r.get("show") == 12 and
            r.get("action") == "miss"]
    said = [r for r in again.journal
            if r.get("outcome") == "closing open night"]
    check(str(again.machine.date) == "2026-11-15" and
          sat["slots"][11]["status"] == S.MISSED and
          sat["slots"][11]["reason"] == S.RESET_MISSED,
          f"restarted at 02:30, Saturday is closed with show 12 MISSED and "
          f"Sunday is the night: {again.machine.date} {sat['slots'][11]}")
    check(line and line[-1].get("fault") and
          "still waiting at the 2 AM nightly reset" in line[-1]["text"] and
          said and "show 12 is delayed" in said[0]["text"],
          f"a fault line names show 12 and why, and the journal says the "
          f"open night was closed: {line[-1:]} {said[:1]}")
    check(os.path.exists(os.path.join(
              work, "nights", J.summary_name(date(2026, 11, 14)))),
          "Saturday's summary is written")
    check("show_starting" not in rec.names(),
          f"nothing from Saturday runs: {rec.names()}")
    out = again._apply(_op(S, S.START_NOW))
    run = again.machine.slot(again.machine.running)
    check(out.accepted and run.origin == "operator" and
          str(again.machine.date) == "2026-11-15",
          f"Start now runs Sunday's extra show, not show 12: {run}")
    again.stop()

    # Show 12 was running at 02:10 (started at 01:55) when ltcplay
    # stopped; restarted at 02:30: cut, FAULT, the rig dark, Saturday
    # closed, Sunday the night, and the rig still dark.
    work, now, svc = held_night()
    now[0] = _den(S, 1, 55, d=(2026, 11, 15))
    svc.tick()
    svc._apply(_op(S, S.START_NOW))
    now[0] = _den(S, 2, 0, 30, d=(2026, 11, 15))
    svc.tick()
    check(svc.machine.running == 12 and str(svc.machine.date) == "2026-11-14",
          "setup: show 12 started at 01:55 is still running after 02:00")
    svc.stop()
    c, rig, T, lines = _cond()
    now[0] = _den(S, 2, 30, d=(2026, 11, 15))
    again = _svc(S, work, now, rule=_two_nights(), conductor=c)
    again.start(thread=False)
    _settle(again, c)
    sat = saturday(work)
    cut = [r for r in again.journal if r.get("fault") and
           "restarted during show 12" in r["text"]]
    # The guard after a cut show counts from the restart (02:30), so
    # Sunday begins at 02:32 (review of PR #196, round 2).
    now[0] = _den(S, 2, 33, d=(2026, 11, 15))
    again.tick()
    again.tick()
    check(sat["slots"][11]["status"] == S.FAULT and cut and
          str(again.machine.date) == "2026-11-15",
          f"show 12 is a cut show (FAULT, a fault line), Saturday is closed "
          f"and Sunday is the night: {sat['slots'][11]['status']} "
          f"{again.machine.date}")
    check(c.snapshot()["look"] == "STOPPED_DARK" and not hasattr(c, "latched"),
          f"the rig is dark, no latch: {c.snapshot()['look']}")
    again.stop()

    # Days later: Saturday's delayed show, ltcplay off until Wednesday.
    # Start now on Wednesday never starts last Saturday's show.
    work, now, svc = held_night()
    svc.stop()
    now[0] = _den(S, 19, 0, d=(2026, 11, 18))
    again = _svc(S, work, now, rule=_two_nights())
    again.start(thread=False)
    sat = saturday(work)
    check(sat["slots"][11]["status"] == S.MISSED and
          sat["slots"][11]["reason"] == S.RESET_MISSED,
          f"on Wednesday, Saturday's show 12 is closed as MISSED: "
          f"{sat['slots'][11]}")
    out = again._apply(_op(S, S.START_NOW))
    run = again.machine.slot(again.machine.running)
    check(out.accepted and str(again.machine.date) == "2026-11-18" and
          run.origin == "operator",
          f"Start now four days later runs an extra show on Wednesday, not "
          f"Saturday's show 12: {again.machine.date} {run}")
    again.stop()
    print("  ok")


def _tonight_doc(work, d=(2026, 11, 14)):
    from datetime import date
    from ltcplay import schedule_service as SV
    with open(SV.tonight_path(date(*d), work)) as fh:
        return json.load(fh)


def test_upgrade_reads_an_old_abort_latch_as_a_stops_hold():
    section("the upgrade (Abort and Reset removed, Jeff, 2026-10-30): an "
            "older version's saved Abort latch, in tonight's list, in the "
            "latch file or on the night before, is read (never refused or "
            "set aside, tonight's list kept as it is) and becomes a Stop's "
            "Hold: no show starts by itself until Resume; nothing writes "
            "abort_latched again")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date
    from ltcplay import schedule_service as SV
    d = date(2026, 11, 14)

    def old_night(work, state="STANDBY", fmt=None, latched=True):
        """Tonight's list as an older version left it after an Abort that
        nobody Reset: show 1 ended ABORTED, the rest still to come."""
        now = [_den(S, 17, 59)]
        svc = _svc(S, work, now, conductor=_RecCond(S))
        svc.start(thread=False)
        now[0] = _den(S, 18, 0)
        svc.tick()
        now[0] = _den(S, 18, 0, 2)
        _confirm(S, svc)
        _settle(svc)
        now[0] = _den(S, 18, 5)
        svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        _settle(svc)
        svc.stop()
        path = SV.tonight_path(d, work)
        with open(path) as fh:
            doc = json.load(fh)
        doc.pop("stop_hold", None)
        doc["state"] = state
        doc["held_from"] = "STANDBY" if state == "HOLD" else ""
        if latched:
            doc["abort_latched"] = True
            doc["dark"] = True
        doc["format"] = fmt or S.TONIGHT_FORMAT
        with open(path, "w") as fh:
            json.dump(doc, fh)
        hold = os.path.join(work, SV.Service.STOP_HOLD_FILE)
        if os.path.exists(hold):
            os.remove(hold)
        return doc

    # 1. Pure: the reader takes the old key, as a Stop's Hold and dark.
    work = tempfile.mkdtemp()
    doc = old_night(work, state="HOLD")
    probe = _svc(S, tempfile.mkdtemp(), [_den(S, 17, 0)])
    probe.start(thread=False)
    rule = probe.rule
    probe.stop()
    m = S.machine_from_doc(doc, rule, d, _den(S, 18, 6))
    check(S.abort_latch_in(doc) and m.stop_hold and m.dark and
          m.state == "BOOT" and len(m.slots) == len(doc["slots"]),
          f"an old list on Hold with abort_latched reads as a Stop's Hold, "
          f"dark, every show kept: {m.stop_hold} {m.dark}")
    m2 = S.machine_from_doc(dict(doc, state="STANDBY", held_from=""), rule,
                            d, _den(S, 18, 6))
    check(m2.dark and not m2.stop_hold,
          "not on Hold: dark (the service holds it at its first tick)")
    out = S.machine_to_doc(m)
    check("abort_latched" not in out and not hasattr(m, "abort_latched"),
          f"nothing writes or keeps abort_latched any more: {sorted(out)}")
    check(not S.abort_latch_in(None) and not S.abort_latch_in([]) and
          not S.abort_latch_in({"abort_latched": "yes"}),
          "only the JSON word true counts")
    for bad in ("ABORT", "RESET_DETAIL"):
        check(not hasattr(S, bad), f"the scheduler has no {bad}")

    # 2. Tonight's list carries it: read, kept, held until Resume.
    for fmt, state in ((S.TONIGHT_FORMAT, "STANDBY"),
                       (S.TONIGHT_FORMAT, "HOLD"),
                       (S.TONIGHT_NEXT_DAY_FORMAT, "STANDBY")):
        work = tempfile.mkdtemp()
        doc = old_night(work, state=state, fmt=fmt)
        before = [(x["n"], x["status"]) for x in doc["slots"]]
        now = [_den(S, 18, 10)]
        rec = _RecCond(S)
        svc = _svc(S, work, now, conductor=rec)
        svc.start(thread=False)
        _settle(svc)
        aside = SV.set_aside_path(SV.tonight_path(d, work))
        check(not os.path.exists(aside) and svc.stop_held() and
              [(x.n, x.status) for x in svc.machine.slots] == before,
              f"format {fmt}, {state}: read (never set aside), every show "
              f"kept, a Stop's Hold: {svc.stop_held()} "
              f"{os.path.exists(aside)}")
        check(os.path.exists(os.path.join(work, SV.Service.STOP_HOLD_FILE)),
              "the Stop's Hold is in its file, so a restart keeps it")
        check(any(r.get("action") == "upgrade" and
                  "Stop's Hold" in r.get("text", "")
                  for r in svc.journal),
              "the journal says what the upgrade did")
        now[0] = _den(S, 18, 20)
        svc.tick()
        _settle(svc)
        check(svc.machine.state == "HOLD" and svc.machine.running == 0 and
              svc.machine.slot(2).status != "RUNNING",
              f"format {fmt}, {state}: the 18:20 show does not start by "
              f"itself: {svc.machine.state} {svc.machine.slot(2).status}")
        check("abort_latched" not in _tonight_doc(work),
              "the next save writes no abort_latched")
        # A fault standing at the Resume: Resume ending a Hold clears the
        # flag, as Reset did before it was removed.
        svc._apply(S.Event(S.FAULT_RAISED, "madmapper", detail="x"))
        check(svc.machine.fault, "setup: a fault is up")
        r = svc.operator_press("resume", "Jeff", "Rack screen")
        check(r.get("ok") and not svc.stop_held() and
              not os.path.exists(os.path.join(work,
                                              SV.Service.STOP_HOLD_FILE)),
              f"Resume releases it: {r}")
        check(not svc.machine.fault,
              f"and clears the fault flag: {svc.machine.faults}")
        now[0] = _den(S, 18, 40)
        svc.tick()
        check(svc.machine.running == 3,
              f"after Resume the next show starts: {svc.machine.running}")
        svc.stop()

    # 3. The latch file alone (an empty one counts): a Stop's Hold first,
    # then the old file goes.
    work = tempfile.mkdtemp()
    old_night(work, latched=False)
    marker = SV.latch_path(work)
    open(marker, "w").close()
    now = [_den(S, 18, 10)]
    svc = _svc(S, work, now, conductor=_RecCond(S))
    svc.start(thread=False)
    _settle(svc)
    check(svc.stop_held() and not os.path.exists(marker) and
          os.path.exists(os.path.join(work, SV.Service.STOP_HOLD_FILE)),
          f"the old latch file becomes a Stop's Hold and is removed once "
          f"that is saved: {svc.stop_held()} {os.path.exists(marker)}")
    now[0] = _den(S, 18, 20)
    svc.tick()
    check(svc.machine.state == "HOLD" and svc.machine.running == 0,
          "no show starts by itself")
    svc.stop()

    # 4. Only the night before carries it (tonight never saved yet).
    work = tempfile.mkdtemp()
    old_night(work)
    os.replace(SV.tonight_path(d, work),
               SV.tonight_path(date(2026, 11, 13), work))
    now = [_den(S, 17, 0)]
    svc = _svc(S, work, now, conductor=_RecCond(S))
    svc.start(thread=False)
    _settle(svc)
    check(svc.stop_held(),
          "an older night's Abort nobody Reset is a Stop's Hold tonight")
    svc.stop()

    # 5. Only the most recent earlier night counts: an Abort two nights
    # back, with a plain night saved after it, holds nothing tonight.
    work = tempfile.mkdtemp()
    old_night(work)
    os.replace(SV.tonight_path(d, work),
               SV.tonight_path(date(2026, 11, 12), work))
    plain = old_night(work, latched=False)
    plain.pop("stop_held", None)
    plain.pop("dark", None)
    with open(SV.tonight_path(date(2026, 11, 13), work), "w") as fh:
        json.dump(plain, fh)
    os.remove(SV.tonight_path(d, work))
    now = [_den(S, 17, 0)]
    svc = _svc(S, work, now, conductor=_RecCond(S))
    svc.start(thread=False)
    _settle(svc)
    check(not svc.stop_held(),
          "an Abort on an older night, with a plain night saved after it, "
          "is no Stop's Hold tonight: the most recent night is read")
    svc.stop()
    print("  ok")


def test_schedule_conductor_line_stuck_or_dead_is_loud():
    section("scheduler: a show conductor request that hangs, or a line of "
            "requests whose thread died, is a fault on the page and in the "
            "journal, with a line when it is over; a Stop never waits "
            "behind a hung request (fix round 2)")
    S = _sched()
    if S is None:
        return
    import tempfile
    import threading as _th
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59)]
    rec = _RecCond(S)
    gate = _th.Event()
    svc = _svc(S, work, now, conductor=rec)
    svc.CONDUCTOR_STUCK_S = 0.3
    svc.start(thread=False)
    _settle(svc)
    rec.block_on["show_starting"] = gate
    try:
        now[0] = _den(S, 18, 0)
        svc.tick()
        now[0] = _den(S, 18, 0, 2)
        _confirm(S, svc)
        time.sleep(0.05)
        now[0] = _den(S, 18, 1)
        svc._apply(_op(S, S.HOLD_ON))
        now[0] = _den(S, 18, 2)
        t0 = time.perf_counter()
        svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        while "stop" not in rec.names() and time.perf_counter() - t0 < 3:
            time.sleep(0.01)
        took = time.perf_counter() - t0
        # The hung request never finishes inside this wait (its gate is
        # opened in the finally below), so a Stop that waited behind it
        # never arrives here at all; one sent ahead arrives after
        # CONDUCTOR_STUCK_S plus whatever the runner adds. Arriving inside
        # the wait is the proof; 0.6 s, the old bound, measured the runner.
        check("stop" in rec.names(),
              f"Stop reaches the conductor while show_starting hangs: "
              f"{rec.names()} ({took:.2f} s, CONDUCTOR_STUCK_S "
              f"{svc.CONDUCTOR_STUCK_S:g})")
        check("hold" not in rec.names(),
              f"the Hold pressed before the Stop is not sent after it: "
              f"{rec.names()}")
        ahead = [r for r in svc.journal if r.get("outcome") == "sent ahead"]
        check(ahead and "Show start" in ahead[-1]["text"],
              f"the journal says the Stop went ahead of what: {ahead[-1:]}")
        time.sleep(0.35)
        n0 = len([r for r in svc.journal if r.get("fault")])
        svc.tick()
        faults = [r for r in svc.journal if r.get("fault") and
                  "has not answered Show start" in r.get("text", "")]
        page = svc.state_view()
        check(faults and svc.machine.fault and page["conductor"]["trouble"]
              and "Show start" in page["conductor"]["trouble"],
              f"a request with no answer for the limit is a fault, on the "
              f"page and in the journal: {faults[-1:]} "
              f"{page['conductor']}")
        svc.tick()
        svc.tick()
        n1 = len([r for r in svc.journal if r.get("fault")])
        check(n1 - n0 == 1, f"written once, not every tick: {n1 - n0}")
    finally:
        gate.set()
    _settle(svc)
    svc.tick()
    back = [r for r in svc.journal if r.get("outcome") == "recovered" and
            r.get("action") == "conductor"]
    check(back and svc.state_view()["conductor"]["trouble"] is None,
          f"and a line says when it is over: {back[-1:]}")
    svc.stop()

    # The line's thread has died: a request waits, the tick says so once,
    # starts the line again, and the request goes through.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 10)]
    rec = _RecCond(S)
    svc = _svc(S, work, now, conductor=rec)
    dead = _th.Thread(target=lambda: None)
    dead.start()
    dead.join()
    svc._calls._thread = dead
    from ltcplay import schedule_service as SV
    waiting = SV._ConductorCall("Hold", "hold", "Andy", "Rack screen")
    svc._calls.put(waiting)
    check(not waiting.done.wait(0.05) and "hold" not in rec.names(),
          f"setup: with the line dead, a Hold is not made: {rec.names()}")
    svc.start(thread=False)
    _settle(svc)
    faults = [r for r in svc.journal if r.get("fault") and
              "line of requests to the show conductor stopped" in
              r.get("text", "")]
    check(faults and "hold" in rec.names(),
          f"the dead line is a fault, written once, and started again so "
          f"the Hold goes out: {faults[-1:]} {rec.names()}")
    svc.tick()
    back = [r for r in svc.journal if r.get("outcome") == "recovered"]
    check(len(faults) == 1 and back, f"then a line says it is running "
                                     f"again: {back[-1:]}")
    svc.stop()
    print("  ok")


def test_schedule_conductor_wiring_details():
    section("scheduler: no show start reaches the conductor while the "
            "confirmed show is paused; the operator's name and screen reach "
            "it; stop() waits for its last lines; an open night is looked "
            "for more than a day back (fix round 2)")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date
    # A show held before it was confirmed: the confirmation that follows
    # must not light lasers or release flame cues during the Hold.
    c, rig, T, lines = _cond()
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 59)]
    svc = _svc(S, work, now, conductor=c)
    svc.start(thread=False)
    now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    now[0] = _den(S, 18, 0, 1)
    svc._apply(_op(S, S.HOLD_ON))
    _settle(svc, c)
    k = len(rig.calls)
    now[0] = _den(S, 18, 0, 2)
    out = _confirm(S, svc)
    _settle(svc, c)
    check(out.accepted and svc.machine.state == S.PAUSED and
          c.snapshot()["look"] == "HELD" and
          "lasers_restore" not in rig.names(k) and
          "flames_release" not in rig.names(k),
          f"a show confirmed while on Hold stays held: no show start, no "
          f"lasers, no flame cues: {svc.machine.state} "
          f"{c.snapshot()['look']} {rig.names(k)}")
    svc._apply(_op(S, S.RESUME))
    _settle(svc, c)
    check(c.snapshot()["look"] == "PLAYING", "Resume then brings it up")
    svc.stop()

    # Who asked: the operator's name and screen, or the scheduler.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 0)]
    rec = _RecCond(S)
    svc = _svc(S, work, now, conductor=rec)
    svc.start(thread=False)
    _confirm(S, svc)
    svc._apply(_op(S, S.HOLD_ON, who="Jeff", screen="Stream Deck"))
    _settle(svc)
    who = {c_[0]: (c_[1], c_[2]) for c_ in rec.calls}
    check(who.get("hold") == ("Jeff", "Stream Deck") and
          who.get("show_starting") == ("the scheduler", ""),
          f"the conductor is told who pressed what, and from where: {who}")
    svc.stop()

    # stop() waits for the conductor's last request and its journal line.
    work = tempfile.mkdtemp()
    now = [_den(S, 17, 55)]
    rec = _RecCond(S)
    rec.sleep_on = {"intermission": 0.3}
    svc = _svc(S, work, now, conductor=rec)
    svc.start(thread=False)
    svc.stop()
    done = [r for r in svc.journal if r.get("action") == "conductor" and
            r.get("outcome") == "done"]
    check(done, f"stop() waits for the conductor's last request to be made "
                f"and journaled: {done[-1:]}")

    # A conductor request that raises SystemExit is a fault; the line of
    # requests carries on.
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 0)]
    rec = _RecCond(S)
    rec.exit_on.add("show_starting")
    svc = _svc(S, work, now, conductor=rec)
    svc.start(thread=False)
    _confirm(S, svc)
    _settle(svc)
    svc._apply(_op(S, S.HOLD_ON))
    _settle(svc)
    bad = [r for r in svc.journal if r.get("fault") and
           "SystemExit" in r.get("text", "")]
    check(bad and svc.machine.fault and rec.names()[-1:] == ["hold"],
          f"a request that raises SystemExit is a fault and the next one "
          f"still goes out: {bad[-1:]} {rec.names()}")
    svc.stop()

    # A night left open is looked for more than one day back: Saturday's
    # delayed show, found on a Monday 01:00 start (Sunday's night, which
    # has no shows and no file) and closed: MISSED at the 2 AM reset.
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 30)]
    svc = _svc(S, work, now)
    svc.start(thread=False)
    svc._apply(_op(S, S.HOLD_ON))
    now[0] = _den(S, 21, 41)
    svc.tick()
    n = svc.machine.delayed().n
    svc.stop()
    now[0] = _den(S, 1, 0, d=(2026, 11, 16))
    again = _svc(S, work, now)
    again.start(thread=False)
    sat = _tonight_doc(work)
    st = [x for x in sat["slots"] if x["n"] == n][0]
    check(again.machine.date == date(2026, 11, 15) and
          st["status"] == S.MISSED and st["reason"] == S.RESET_MISSED,
          f"Saturday, two days back, is found and closed: "
          f"{again.machine.date} {st}")
    again.stop()
    print("  ok")


def test_schedule_tonight_file_format():
    section("scheduler: tonight's file is format 3 as before unless it is "
            "dark or on a Stop's Hold, then format 4, which an older ltcplay "
            "refuses rather than misreads; a newer format is refused in "
            "words (fix round 2)")
    S = _sched()
    if S is None:
        return
    from dataclasses import replace
    rule = _one_night_rule(S)
    n = _Night(S, rule)
    n.boot(_den(S, 17, 50))
    plain = S.machine_to_doc(n.m)
    check(plain["format"] == 3 and "dark" not in plain and
          "abort_latched" not in plain,
          f"a night that is not dark is format 3, as before: "
          f"{plain['format']}")
    at = _den(S, 17, 51)
    for what, m in (("dark", replace(n.m, dark=True)),
                    ("on a Stop's Hold", replace(
                        n.m, state=S.HOLD, held_from=S.STANDBY, dark=True,
                        stop_hold=True))):
        doc = json.loads(json.dumps(S.machine_to_doc(m)))
        back = S.machine_from_doc(doc, rule, m.date, at)
        check(doc["format"] == 4 and back.dark == m.dark and
              back.stop_hold == m.stop_hold and "abort_latched" not in doc,
              f"a night {what} is format 4 and reads back the same")
    # An older version's file with its Abort latch (the upgrade, Abort
    # removed 2026-10-30): read, never refused, and dark.
    old = dict(plain, format=4, abort_latched=True)
    back = S.machine_from_doc(old, rule, n.m.date, at)
    check(back.dark and S.abort_latch_in(old),
          f"an old latched list reads, dark: {back.dark}")
    bad = dict(plain, dark=True)
    try:
        S.machine_from_doc(bad, rule, n.m.date, at)
        check(False, "a format 3 file carrying dark is refused")
    except ValueError as e:
        check("dark" in str(e), f"format 3 carrying dark is refused: {e}")
    newer = dict(plain, format=6)
    try:
        S.machine_from_doc(newer, rule, n.m.date, at)
        check(False, "a newer format is refused")
    except ValueError as e:
        check("newer ltcplay" in str(e) and "3, 4 and 5" in str(e),
              f"a newer format is refused saying so: {e}")
    # A list with a show on the next morning (review of PR #196) is format
    # 5, so an older ltcplay (formats 3 and 4) refuses it in words rather
    # than reading the 00:30 show as 00:30 on the night's own date.
    from dataclasses import replace as _rp
    late = _rp(n.m, slots=n.m.slots + (S.Slot(
        n=99, start=_den(S, 0, 30, d=(2026, 11, 15)), origin="edit"),))
    doc5 = S.machine_to_doc(late)
    back = S.machine_from_doc(doc5, rule, n.m.date, at)
    check(doc5["format"] == S.TONIGHT_NEXT_DAY_FORMAT == 5 and
          back.slot(99).start == _den(S, 0, 30, d=(2026, 11, 15)) and
          late.hm(late.slot(99).start) == "00:30 (tomorrow)",
          f"a next-morning show is format 5, reads back, and is said as "
          f"tomorrow: {doc5['format']} {late.hm(late.slot(99).start)}")
    # Fix round 3: a latch that is not plainly true or false is refused.
    for k in ("dark", "abort_latched"):
        odd = dict(plain, format=4, **{k: "yes"})
        try:
            S.machine_from_doc(odd, rule, n.m.date, at)
            check(False, f"{k}: \"yes\" is refused")
        except ValueError as e:
            check(k in str(e) and "true or false" in str(e),
                  f"{k} that is not true or false is refused: {e}")
    # A schedule change rebuilds tonight and keeps a Stop's Hold and dark.
    other = _one_night_rule(S, first="18:10")
    back, _notes = S.rebuild_night(other, replace(
        n.m, state=S.HOLD, held_from=S.STANDBY, stop_hold=True, dark=True))
    check(back.stop_hold and back.dark,
          f"a rebuild for a changed schedule keeps the Stop's Hold and "
          f"dark: {back.stop_hold} {back.dark}")
    print("  ok")


def test_schedule_conductor_line_round3_details():
    section("scheduler: a Stop that goes ahead drops a queued show start; "
            "it goes ahead of a dead line too; a hang is a fault after 3 s, "
            "a Stop sent beside the line included; flush waits for it; a "
            "revived line is idle (fix round 3)")
    S = _sched()
    if S is None:
        return
    import tempfile
    import threading as _th
    from ltcplay import schedule_service as SV

    def showing(rec=None):
        work = tempfile.mkdtemp()
        now = [_den(S, 17, 59)]
        rec = rec or _RecCond(S)
        svc = _svc(S, work, now, conductor=rec)
        svc.start(thread=False)
        now[0] = _den(S, 18, 0)
        svc.tick()
        _settle(svc)
        return svc, rec, now, work

    def wait_for(pred, s=2.0):
        t0 = time.perf_counter()
        while not pred() and time.perf_counter() - t0 < s:
            time.sleep(0.01)
        return pred()

    # A show start queued behind a stuck request is dropped by the Stop.
    svc, rec, now, work = showing()
    line = _th.Event()
    rec.block_on["intermission"] = line
    try:
        with svc._locked():
            svc._calls.put(svc._new_call("Out of the show", "intermission",
                                         "the scheduler", ""))
        wait_for(lambda: "intermission" in rec.names(1))
        now[0] = _den(S, 18, 0, 2)
        _confirm(S, svc)
        now[0] = _den(S, 18, 1)
        svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        wait_for(lambda: "stop" in rec.names())
    finally:
        line.set()
    _settle(svc)
    k = rec.names().index("stop")
    check("show_starting" not in rec.names(k),
          f"a show start queued before the Stop is never sent after it: "
          f"{rec.names()}")
    svc.stop()

    # The line's thread is dead: the Stop goes on its own at once. (A
    # fresh line whose thread has ended: the old line's thread would still
    # be serving its own queue.)
    svc, rec, now, work = showing()
    _confirm(S, svc)
    _settle(svc)
    dead = _th.Thread(target=lambda: None)
    dead.start()
    dead.join()
    svc._calls = SV._ConductorCalls(svc._run_conductor_call,
                                    overtaken=svc._stop_overtook)
    svc._calls._thread = dead
    now[0] = _den(S, 18, 1)
    svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    check(wait_for(lambda: "stop" in rec.names(), 1.0),
          f"with the line's thread dead, the Stop still reaches the "
          f"conductor, without waiting for a tick: {rec.names()}")
    svc.tick()
    svc.stop()

    # The stuck limit, on a clock the test moves: 3 s, not more.
    svc, rec, now, work = showing()
    fake = [100.0]
    svc._calls._clock = lambda: fake[0]
    line, gate = _th.Event(), _th.Event()
    rec.block_on["show_starting"] = line
    rec.block_on["stop"] = gate
    try:
        _confirm(S, svc)
        wait_for(lambda: "show_starting" in rec.names())

        def stuck(word):
            return [r for r in svc.journal if r.get("fault") and
                    f"has not answered {word}" in r.get("text", "")]

        fake[0] += 2.9
        svc.tick()
        check(not stuck("Show start"), "2.9 s without an answer is no fault")
        fake[0] += 0.2
        svc.tick()
        check(stuck("Show start"),
              "3.1 s without an answer is a fault (CONDUCTOR_STUCK_S is 3 s)")
        now[0] = _den(S, 18, 1)
        svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        wait_for(lambda: "stop" in rec.names())
        line.set()
        wait_for(lambda: svc._calls.health()["waiting"] == 0 and
                 not svc._calls._busy)
        svc.tick()
        fake[0] += 3.1
        svc.tick()
        check(stuck("Stop"),
              f"a Stop sent beside the line and hanging is a fault too: "
              f"{[r['text'][:80] for r in svc.journal if r.get('fault')][-2:]}")
        _th.Timer(0.3, gate.set).start()
        flushed = svc.flush_conductor(3)
        done = [r for r in svc.journal if r.get("action") == "conductor" and
                r.get("outcome") == "done" and "Stop" in r.get("text", "")]
        check(flushed and done,
              f"flush waits for a Stop sent beside the line: {done[-1:]}")
    finally:
        line.set()
        gate.set()
    svc.stop()

    # A line revived after its thread died is idle, not still busy with
    # whatever it was making when it died.
    svc, rec, now, work = showing()
    fake = [100.0]
    svc._calls._clock = lambda: fake[0]
    dead = _th.Thread(target=lambda: None)
    dead.start()
    dead.join()
    lost = svc._new_call("Lost request", "hold", "the scheduler", "")
    with svc._calls._cv:
        svc._calls._thread = dead
        svc._calls._busy = True
        svc._calls._current, svc._calls._since = lost, fake[0]
    svc.tick()
    fake[0] += 5
    svc.tick()
    bad = [r for r in svc.journal if r.get("fault") and
           "Lost request" in r.get("text", "")]
    check(not bad and not svc._calls._busy,
          f"a revived line does not count the dead thread's request as "
          f"stuck: {bad[-1:]}")
    svc.stop()

    print("  ok")


# ---------------------------------------------------------------------------
# Fire & Ice: the real ShowOutputs (fire_ice.FireIceShow), the show runner,
# and the conductor `ltc serve` builds. The fakes below stand in for the
# running session, its clock.AudioMaster and its player, and write every
# call into the same ordered log as the real BEYOND and MadMapper links.
# ---------------------------------------------------------------------------


class _FiClock:
    """Stands in for clock.AudioMaster, as FireIceShow and the runner use
    it. pause/resume/halt record the fade they were given; the freeze and
    the move come later, through on_pause/on_resume, like the real one."""

    source = "audio_master"

    def __init__(self, calls, T):
        self.calls, self.T = calls, T
        self.on_pause = self.on_resume = None
        self._paused = False
        self.playing = False
        self.cues_played = 0
        self._last_frame = None
        self.last_ended = ""
        self.move_s = 0.05

    def _rec(self, name, *a):
        self.calls.append((name, a, self.T.now()))

    def play(self, label):
        self._rec("music_play", label)
        self.playing = True
        self.cues_played += 1
        self._last_frame = None

    def pause(self, fade_ms=None):
        self._rec("music_hold", fade_ms)
        self.T.at(self.T.t + (fade_ms or 0) / 1000.0, self._freeze)

    def _freeze(self):
        self._paused = True
        if self.on_pause:
            self.on_pause()

    def resume(self, fade_ms=None):
        self._rec("music_resume", fade_ms)
        self.T.at(self.T.t + self.move_s, self._move)

    def _move(self):
        self._paused = False
        if self.on_resume:
            self.on_resume()

    def halt(self, fade_ms=None):
        self._rec("music_halt", fade_ms)
        self.playing = False
        self.last_ended = "Show stopped"


class _FiPlayer:
    """Stands in for player.Player as FireIceShow uses it: the override,
    and a show start's hand-over (hold_until_show), which the real tick
    ends on the first show frame; here first_frame() is that tick."""

    def __init__(self, calls, T):
        self.calls, self.T = calls, T
        self._override = None
        self.show_handoff = None
        self.show_handoff_done = None

    def hold_until_show(self):
        self.show_handoff = (self._override, 0)
        self.show_handoff_done = None
        return self._override

    def cancel_show_handoff(self, hand=None):
        if hand is not None and self.show_handoff is not hand:
            return False
        had = self.show_handoff is not None
        self.show_handoff = None
        return had

    def first_frame(self):
        """The first frame of the show's timecode reaches the tick."""
        hand = self.show_handoff
        if hand is None:
            return
        self.show_handoff = None
        if self._override == hand[0]:
            if self._override is not None:
                self.override = None
            self.show_handoff_done = (hand[0], self.T.now())

    @property
    def override(self):
        return self._override

    @override.setter
    def override(self, v):
        self._override = v
        self.calls.append(("pixels", (v,), self.T.now()))


class _FiSession:
    running = True
    log = None

    def __init__(self, calls, T):
        self.clock = _FiClock(calls, T)
        self.player = _FiPlayer(calls, T)
        self.parks = []
        # What session.open() sets: the player's hard park.
        self.clock.on_pause = lambda: self.parks.append(True)
        self.clock.on_resume = lambda: self.parks.append(False)

    def clock_play(self, cue=None):
        import types
        self.clock.play(cue or "Show")
        return types.SimpleNamespace(name=cue or "Show")


class _FiFlames:
    """Stands in for flamelink.FlameLink: records zero, release and the
    Abort's disarm_all."""

    def __init__(self, calls, T, disarm_ok=True):
        self.calls, self.T = calls, T
        self.disarm_ok = disarm_ok
        self.reasons = []

    def disarm_all(self, reason):
        self.reasons.append(reason)
        self.calls.append(("flames_disarm", (), self.T.now()))
        return self.disarm_ok

    def zero(self):
        self.calls.append(("flames_zero", (), self.T.now()))
        return True

    def release(self):
        self.calls.append(("flames_release", (), self.T.now()))
        return True


def _fi_mod():
    from ltcplay import fire_ice
    return fire_ice


def test_fire_ice_serves_the_rack_screen_not_the_old_page():
    section("fire & ice: the rack screen (/remote) is the one operator "
            "screen; / and /index.html go to it, and the old operator page "
            "is served only on the GPL path")
    import shutil
    import tempfile
    import types
    from ltcplay import web as web_mod
    folder = tempfile.mkdtemp()
    httpd = web_mod.serve(folder, port=0, bind="127.0.0.1")
    try:
        local = ("127.0.0.1", 50000)
        st, _h, page = _ask(httpd, "GET", "/", client=local)
        check(st == 200 and "/api/brand" in str(page),
              f"GPL path: / is the old operator page ({st})")
        httpd.fire_ice_config = types.SimpleNamespace(show_name=None,
                                                      venue=None)
        for path in ("/", "/index.html"):
            st, hd, _ = _ask(httpd, "GET", path, client=local)
            check(st == 302 and hd.get("location") == ["/remote"],
                  f"Fire & Ice: {path} goes to the rack screen: {st} {hd}")
        st, _h, page = _ask(httpd, "GET", "/remote", client=local)
        check(st == 200 and "index.html" not in str(page),
              "the rack screen is served and never links the old page")
        # Stop is the engine's complete halt, from any screen (Jeff,
        # 2026-10-28): Remote.stop_press, the Stream Deck's Stop.
        # Its Run (Run show, Run in Programming) and Stop.
        check('id="p-run"' in str(page) and 'id="b-go"' in str(page) and
              '"/api/start"' in str(page)
              and '"/api/remote/stop"' in str(page),
              "the rack screen has Run and Stop of its own, through the "
              "engine's own guarded routes")
    finally:
        httpd.server_close()
        shutil.rmtree(folder, ignore_errors=True)
    print("  ok")


class _TcSock:
    """A UDP socket stand-in for the BEYOND timecode tests: every packet
    kept with where it went; `fail` makes sendto raise."""

    def __init__(self, log, fail=None):
        self.log, self.fail = log, fail

    def sendto(self, pkt, addr):
        if self.fail and self.fail[0]:
            raise OSError("network unreachable")
        self.log.append((bytes(pkt), addr))

    def setsockopt(self, *a):
        pass

    def close(self):
        pass


def test_beyond_timecode_blanking():
    section("fire & ice: BEYOND's lasers kept dark by timecode (beyond_blank "
            "\"timecode\", selectable; \"osc\" is the default): BEYOND's own stream jumps to the "
            "running hour-23 black zone within one frame in every blanking "
            "case, comes back to the right show frame, MadMapper's stream is "
            "never touched, a send that fails is a fault, and the setting is "
            "checked")
    import types
    from ltcplay import beyondtc as BT, clock as CK
    F = _fi_mod()
    C = _cond_mod()
    # The setting.
    cfg = F.FireIceConfig.parse({})
    check(cfg.beyond_blank == "osc" and cfg.beyond_black_hour == 23 and
          F.FireIceConfig().beyond_blank == "osc" and
          F.BEYOND_BLANK_DEFAULT == BT.DEFAULT_MODE == "osc" and
          not F.blanks_by_timecode(types.SimpleNamespace()),
          "default (Jeff, 2026-10-07): OSC blanking, in the file, the "
          "config object, beyondtc and an object with no setting at all; "
          "black zone hour 23 when timecode is chosen")
    for bad, words in (({"beyond_blank": "dim"}, "beyond_blank"),
                       ({"beyond_black_hour": 24}, "beyond_black_hour"),
                       ({"beyond_black_hour": True}, "beyond_black_hour"),
                       ({"beyond_timecode_ip": "beyond.local"},
                        "beyond_timecode_ip")):
        try:
            F.FireIceConfig.parse(bad)
            check(False, f"{bad} was accepted")
        except F.FireIceConfigError as e:
            check(words in str(e) and "\u2014" not in str(e),
                  f"refused in a sentence: {e}")
    for m in ("timecode", "osc", "both"):
        check(F.FireIceConfig.parse({"beyond_blank": m}).beyond_blank == m,
              f"{m} is a mode")

    # The gate on the show's own timecode sender.
    sent, tsent = [], []
    t = [100.0]
    lines = []
    fail = [False]
    gate = BT.TimecodeGate("127.0.0.2", hour=23, clock=lambda: t[0],
                           socket_factory=lambda: _TcSock(sent, fail),
                           journal=lambda text, **k: lines.append(
                               (text, k.get("fault", False))))
    out = CK.TimecodeOut([("MadMapper", "127.0.0.1"), ("BEYOND", "127.0.0.2")],
                         socket_factory=lambda: _TcSock(tsent))
    CK.DIVERT.clear()
    CK.DIVERT[BT.LABEL] = gate.divert
    CK.DIVERT["127.0.0.2"] = gate.divert
    try:
        show = CK.arttimecode(0, 1, 2, 3)
        out.send(show)
        check([a for _p, a in tsent] == [("127.0.0.1", 6454)],
              f"MadMapper gets the show's timecode: {tsent}")
        check(not sent, "dark from the start: none of the show's timecode "
                        "reaches BEYOND")
        check(gate.dark() and BT.tc_of(sent[-1][0]) == (23, 0, 0, 0) and
              sent[-1][1] == ("127.0.0.2", 6454),
              f"blank: the first black-zone frame goes out at once: "
              f"{BT.tc_of(sent[-1][0])}")
        t[0] += 1.5
        gate.send_black()
        check(BT.tc_of(sent[-1][0]) == (23, 0, 1, 15),
              f"the black zone keeps running, never frozen: "
              f"{BT.tc_of(sent[-1][0])}")
        check(BT.black_tc(23, 3600 * 30 + 5) == (23, 0, 0, 5),
              "the zone wraps inside its own hour")
        gate.light()
        out.send(CK.arttimecode(0, 1, 2, 4))
        check(BT.tc_of(sent[-1][0]) == (0, 1, 2, 4) and
              tsent[-1][1] == ("127.0.0.1", 6454),
              "lit: the very next show frame goes to BEYOND unchanged, and "
              "MadMapper still gets it too")
        # A Hold: the frozen frame repeats; dark, then back to that frame.
        held = CK.arttimecode(0, 1, 9, 12)
        out.send(held)
        n0 = len(tsent)
        gate.dark()
        out.send(held)
        check(BT.tc_of(sent[-1][0])[0] == 23 and len(tsent) == n0 + 1,
              "held and dark: BEYOND is in the black zone; MadMapper still "
              "gets the held frame")
        gate.light()
        out.send(held)
        check(BT.tc_of(sent[-1][0]) == (0, 1, 9, 12),
              "Resume: BEYOND goes back to the exact held frame")
        # A node at BEYOND's address under another name is BEYOND too.
        out2 = CK.TimecodeOut([("Lasers", "127.0.0.2")],
                              socket_factory=lambda: _TcSock(tsent))
        gate.dark()
        n1 = len(tsent)
        out2.send(show)
        check(len(tsent) == n1, "a node at BEYOND's address by another name "
                                "is diverted too")
        # Fail safe.
        fail[0] = True
        check(gate.dark() is False and any(
            f and "UNKNOWN" in x for x, f in lines),
            f"a black frame that cannot be sent is a fault, lasers UNKNOWN: "
            f"{lines[-1:]}")
        fail[0] = False
        check(gate.dark() and "again" in lines[-1][0], "and it says so when "
                                                       "it is sent again")
    finally:
        CK.DIVERT.clear()
    g2 = BT.TimecodeGate("127.0.0.2", socket_factory=lambda: _TcSock([]))
    g2.start()
    try:
        check(CK.DIVERT.get("beyond") == g2.divert and
              CK.DIVERT.get("127.0.0.2") == g2.divert,
              "a started gate takes BEYOND's packets by name and address")
    finally:
        g2.close()
    check(not CK.DIVERT, "closed, it lets them go")
    # attach() gives the conductor the blanking the setting asks for.
    n = _fi_night(session=False)
    if n.S is not None:
        for m in ("timecode", "osc", "both"):
            w = F.attach(n.svc, types.SimpleNamespace(session=None),
                         F.FireIceConfig(beyond_blank=m), threaded=False)
            b = w.devices.beyond
            check(isinstance(b, BT.Blanking) and b.mode == m and
                  (b.gate is None) == (m == "osc") and
                  (b.fault is None) == (m == "timecode"),
                f"attach() with beyond_blank {m!r} and no OSC BEYOND: {b}")
            w.close()

    # Through the conductor: every blanking case puts BEYOND in the zone
    # within the press (one frame), and Resume brings it back.
    for mode in ("timecode", "both"):
        sent.clear()
        osc = types.SimpleNamespace(calls=[], cfg=None, last_result="ok")
        osc.blank = lambda show=None: osc.calls.append("blank") or True
        osc.unblank = lambda show=None, **k: osc.calls.append("unblank") or True
        bl = BT.Blanking(mode, gate=gate, osc=osc)
        T = _CondTime()
        rig = _CondRig(T.now)
        dev = C.ConductorDevices(None, bl, show=1)
        state = ["SHOW"]
        c = C.Conductor(dev, rig, C.laser_gate_for(lambda: state[0]),
                        clock=T.now, waiter=T.wait, threaded=False)
        _cd_live(c, rig, None)
        rig.move_s = 0.1

        def zone():
            return gate.lit is False and sent and \
                BT.tc_of(sent[-1][0])[0] == 23

        def up(what):
            c.resume("Andy", "rack screen")
            c.run_pending()
            check(gate.lit is True, f"{mode}: lit again after {what}")
        check(gate.lit is True, f"{mode}: a confirmed show lights BEYOND")
        for what, press in (("Hold", lambda: c.hold("Andy", "rack screen")),
                            ("Stop", lambda: c.stop("Andy", "rack "
                                                    "screen"))):
            n = len(sent)
            press()
            if what == "Hold":
                c.run_pending()     # Hold's blank is the executor's first
            check(zone() and len(sent) > n,           # laser step
                  f"{mode}: {what} puts BEYOND in the black zone"
                  + (" at the press" if what == "Stop" else ""))
            c.run_pending()
            if what == "Hold":
                up(what)
        c.run_pending()
        check(zone(), f"{mode}: still dark after the Stop")
        # The next show start leaves the Stop's dark (nothing latched).
        c.music_started()
        c.show_starting("scheduler")
        c.run_pending()
        for what, call in (("intermission", c.intermission),
                           ("a failed start", c.failed_start),
                           ("a show stopped", c.show_stopped)):
            gate.light()
            n = len(sent)
            call("scheduler")
            c.run_pending()
            check(zone() and len(sent) > n,
                  f"{mode}: {what} puts BEYOND in the black zone")
        check(("blank" in osc.calls) == (mode == "both"),
              f"{mode}: OSC used only in both: {osc.calls}")
        check(bl.unblank(in_show=1) is False,
              "unblank refuses anything but the real True")
    print("  ok")


def test_beyond_timecode_needs_one_route_through_the_gate():
    section("fire & ice: the lasers' timecode blank fails closed (review of "
            "PR #43, P0-2): a black zone with no address is a fault and "
            "never recorded dark; a show file whose timecode reaches BEYOND "
            "around the gate (broadcast, none, or not exactly one "
            "destination the gate takes) is refused at serve start and at "
            "Run; the one BEYOND address is the gate's")
    import json as _json
    import shutil
    import tempfile
    import types
    from ltcplay import beyondtc as BT
    from ltcplay.session import SessionError
    from ltcplay import web as web_mod
    F = _fi_mod()
    C = _cond_mod()
    # No address: False, a fault, every time; never "dark".
    lines = []
    gate = BT.TimecodeGate(None, socket_factory=lambda: _TcSock([]),
                           journal=lambda text, **k: lines.append(
                               (text, k.get("fault", False))))
    check(gate.send_black() is False and gate.dark() is False,
          "with no address not one black frame goes, and it says False")
    check(lines and all(f for _t, f in lines) and
          "UNKNOWN" in lines[-1][0] and "\u2014" not in lines[-1][0],
          f"a fault in the journal, the lasers UNKNOWN: {lines[-1:]}")
    bl = BT.Blanking("timecode", gate=gate)
    check(bl.blank() is False, "the blank reports it failed")
    dev = C.ConductorDevices(None, bl, show=1)
    check(dev.lasers_blank().ok is False,
          "and the conductor's device layer reports it not done")
    T = _CondTime()
    rig = _CondRig(T.now)
    state = ["SHOW"]
    c = C.Conductor(dev, rig, C.laser_gate_for(lambda: state[0]),
                    clock=T.now, waiter=T.wait, threaded=False)
    _cd_live(c, rig, None)
    c.stop("Andy", "rack screen")
    c.run_pending()
    check(c.snapshot()["applied"]["lasers"] != C.BLACK,
          f"a Stop whose blank could not be sent never records the lasers "
          f"black: {c.snapshot()['applied']}")
    check(gate.adopt("127.0.0.2") == "127.0.0.2" and gate.ip == "127.0.0.2"
          and gate.adopt("10.9.9.9") == "127.0.0.2",
          "the gate takes the show file's address only when it has none")

    work = tempfile.mkdtemp()
    try:
        folder = os.path.join(work, "folder")
        os.makedirs(folder)

        def show_file(name, clock):
            doc = {"name": name, "fps": 30, "show_dir": work,
                   "cues": [{"tc": "01:00:00:00", "fseq": "Show.fseq",
                             "name": "Show"}]}
            if clock is not None:
                doc["clock"] = clock
            p = os.path.join(folder, name + ".json")
            with open(p, "w", encoding="utf-8") as fh:
                _json.dump(doc, fh)
            return p
        good = show_file("good", {"source": "artnet_master", "artnet": {
            "nodes": {"MadMapper": "127.0.0.1", "BEYOND": "127.0.0.2"}}})
        check(F.beyond_timecode_route(good, None) == ("BEYOND", "127.0.0.2"),
              "a show file naming BEYOND: its one destination")
        check(F.beyond_timecode_route(good, "127.0.0.2") ==
              ("BEYOND", "127.0.0.2"),
              "named BEYOND and at the gate's address is still one")
        bad = {
            "broadcast": {"source": "artnet_master",
                          "artnet": {"broadcast": "10.0.0.255"}},
            "no BEYOND": {"source": "artnet_master", "artnet": {
                "nodes": {"MadMapper": "127.0.0.1", "Lasers": "10.0.0.40"}}},
            "two": {"source": "artnet_master", "artnet": {
                "nodes": {"MadMapper": "127.0.0.1", "BEYOND": "127.0.0.2",
                          "Lasers": "127.0.0.3"}}},
        }
        words = {"broadcast": "reaches BEYOND directly",
                 "no BEYOND": "no Art-Net timecode destination is named "
                              "BEYOND",
                 "two": "2 Art-Net timecode destinations"}
        for label, clock in bad.items():
            p = show_file("bad", clock)
            try:
                F.beyond_timecode_route(p, "127.0.0.3")
                check(False, f"{label}: accepted")
            except F.FireIceConfigError as e:
                check(words[label] in str(e) and "\u2014" not in str(e) and
                      "\u2013" not in str(e),
                      f"{label}: refused in a sentence: {e}")
            cfg = F.FireIceConfig(beyond_blank="timecode",
                                  beyond_timecode_ip="127.0.0.3"
                                  if label == "two" else "127.0.0.2")
            try:
                F.check_beyond_timecode_routes(folder, cfg)
                check(False, f"{label}: ltc serve must refuse it at start")
            except F.FireIceConfigError as e:
                check("bad.json" in str(e),
                      f"{label}: refused at serve start, naming the file: "
                      f"{e}")
            F.check_beyond_timecode_routes(
                folder, F.FireIceConfig(beyond_blank="osc"))
            check(True, "by OSC alone there is nothing to route")
        # Re-review P2-a: a show that sends no Art-Net timecode, or names no
        # BEYOND when no BEYOND is configured, has nothing to route: passed
        # over at serve start and said, never a refusal.
        p = show_file("bad", None)
        check(F.beyond_timecode_route(p, "127.0.0.2") is None,
              "a show file with no Art-Net timecode has no route")
        skipped = F.check_beyond_timecode_routes(
            folder, F.FireIceConfig(beyond_blank="timecode", beyond_timecode_ip="127.0.0.2"))
        check(len(skipped) == 1 and "bad.json" in skipped[0] and
              "sends no Art-Net timecode" in skipped[0],
              f"serve starts, saying which show it passed over: {skipped}")
        p = show_file("bad", bad["no BEYOND"])
        check(F.beyond_timecode_route(p, None, lasers=False) is None,
              "no BEYOND configured and none named: nothing to route")
        skipped = F.check_beyond_timecode_routes(folder, F.FireIceConfig(beyond_blank="timecode"))
        check(len(skipped) == 1 and "no BEYOND is configured" in skipped[0],
              f"a bench with no lasers starts: {skipped}")
        # Re-review P2-h: beyond_timecode_ip and the show file's BEYOND
        # must be the same address.
        try:
            F.beyond_timecode_route(good, "127.0.0.3",
                                    timecode_ip="127.0.0.3")
            check(False, "a BEYOND elsewhere than beyond_timecode_ip passed")
        except F.FireIceConfigError as e:
            check("must be the same address" in str(e) and
                  "127.0.0.2" in str(e) and "127.0.0.3" in str(e),
                  f"refused in a sentence naming both: {e}")
        check(F.beyond_timecode_route(good, "127.0.0.2",
                                      timecode_ip="127.0.0.2") ==
              ("BEYOND", "127.0.0.2"), "the same address: fine")
        # The real `ltc serve` start refuses it before binding anything.
        import contextlib
        import io
        from ltcplay import cli as _cli
        show_file("bad", bad["broadcast"])
        with open(os.path.join(work, "ltcplay_fire_ice.json"), "w") as fh:
            # Timecode blanking chosen: "osc" is the default since Jeff,
            # 2026-10-07.
            _json.dump({"beyond_blank": "timecode"}, fh)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), \
                contextlib.redirect_stderr(out):
            rc = _cli._cmd_serve(types.SimpleNamespace(
                folder=folder, schedule=os.path.join(
                    work, "ltcplay_schedule.json")))
        check(rc and "broadcast" in out.getvalue() and
              "bad.json" in out.getvalue(),
              f"ltc serve refuses it in a sentence: {rc} {out.getvalue()!r}")
        os.remove(os.path.join(folder, "bad.json"))
        F.check_beyond_timecode_routes(folder, F.FireIceConfig(beyond_blank="timecode"))
        check(True, "every show file routes BEYOND through the gate: serve "
                    "starts")
        # At Run: attach() refuses it before anything opens, and gives the
        # gate the show file's BEYOND address.
        n = _fi_night(session=False)
        if n.S is None:
            return
        control = web_mod.Control(folder, sd=FakeSD())
        lines = []
        w = F.attach(n.svc, control, F.FireIceConfig(beyond_blank="timecode"), threaded=False,
                     journal=lambda text, **k: lines.append(text))
        try:
            g = w.devices.beyond.gate
            check(g.ip is None, "setup: the gate has no address yet")
            control.before_open(good)
            check(g.ip == "127.0.0.2",
                  f"Run gives the gate the show file's BEYOND address: "
                  f"{g.ip}")
            p = show_file("bad", bad["broadcast"])
            try:
                control.before_open(p)
                check(False, "Run must refuse broadcast timecode")
            except SessionError as e:
                check("will not start" in str(e) and "broadcast" in str(e),
                      f"Run refuses it: {e}")
            # Re-review P1-B: a check that cannot be made refuses.
            p = show_file("bad", {"source": "artnet_master", "artnet": {
                "nodes": {"BEYOND": "not an address"}}})
            try:
                control.before_open(p)
                check(False, "Run must refuse a show whose route check "
                             "could not be made")
            except SessionError as e:
                check("will not start" in str(e) and
                      "could not be checked" in str(e),
                      f"Run refuses it: {e}")
            # Re-review P2-a: no Art-Net timecode: Run goes on, journaled.
            n_lines = len(lines)
            p = show_file("bad", None)
            check(control.before_open(p) == {} and any(
                "no BEYOND timecode to keep dark" in t
                for t in lines[n_lines:]),
                f"a show with no Art-Net timecode runs, and the journal "
                f"says the black zone is not used for it: "
                f"{lines[n_lines:]}")
        finally:
            w.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_beyond_restore_never_outruns_a_stop_blank():
    section("fire & ice: an Abort's blank that lands after a laser "
            "restore's last check, and before the restore lights BEYOND's "
            "timecode, always wins (review of PR #43, P0-3), reproduced "
            "step by step")
    import types
    from ltcplay import beyondtc as BT
    C = _cond_mod()
    # 1. The gate and the blanking alone. The restore reads its guard
    #    (still wanted), then the Abort's blank runs, then the restore
    #    goes on to light the gate: exactly that order, every time.
    sent = []
    gate = BT.TimecodeGate("127.0.0.2", socket_factory=lambda: _TcSock(sent))
    bl = BT.Blanking("timecode", gate=gate)
    check(bl.blank() and gate.lit is False, "setup: dark")
    wanted = [True]
    orig = gate.light
    order = []

    def light_after_abort(*a, **k):
        order.append("abort blank")
        wanted[0] = False
        bl.blank()                    # the Abort lands here
        order.append("restore lights")
        return orig(*a, **k)
    gate.light = light_after_abort

    def guard():
        order.append("guard read")
        return wanted[0]
    r = bl.unblank(in_show=True, still_wanted=guard)
    check(order == ["guard read", "abort blank", "restore lights"],
          f"the interleaving happened as written: {order}")
    check(r is False and gate.lit is False and bl.last_result == "cut",
          f"the restore is refused under the gate's lock and BEYOND stays "
          f"in the black zone: {r} lit={gate.lit}")
    gate.light = orig
    # 1b. The Abort lands just after the guard said yes, before anything
    #     else the restore does: the epoch was read before the guard.
    bl.blank()

    def guard_then_abort():
        yes = True                     # decided: still wanted
        bl.blank()                     # the Abort lands now
        return yes
    r = bl.unblank(in_show=True, still_wanted=guard_then_abort)
    check(r is False and gate.lit is False,
          f"an Abort landing right after the guard said yes wins too: {r} "
          f"lit={gate.lit}")
    check(bl.unblank(in_show=True, still_wanted=lambda: True) and gate.lit,
          "with no blank in between, a restore still lights it")

    # 2. Through the conductor: a Resume's laser restore that the Abort
    #    overtakes at that same point. Right after the restore returns the
    #    lasers are dark, and the Abort's executor sends the blank again.
    sent2 = []
    gate2 = BT.TimecodeGate("127.0.0.2",
                            socket_factory=lambda: _TcSock(sent2))
    bl2 = BT.Blanking("timecode", gate=gate2)
    T = _CondTime()
    rig = _CondRig(T.now)
    dev = C.ConductorDevices(None, bl2, show=1)
    c = C.Conductor(dev, rig, C.laser_gate_for(lambda: "SHOW"),
                    clock=T.now, waiter=T.wait, threaded=False)
    _cd_live(c, rig, None)
    check(gate2.lit is True, "setup: the show lit BEYOND")
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(gate2.lit is False, "setup: the Hold blanked it")
    orig2 = gate2.light
    seen = {}

    def light_after_abort2(*a, **k):
        seen["abort"] = c.stop("Andy", "rack screen")
        got = orig2(*a, **k)
        seen["lit_right_after"] = gate2.lit
        return got
    gate2.light = light_after_abort2
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(seen.get("abort") is not None and seen["abort"].ok,
          f"the Abort landed inside the restore: {seen}")
    check(seen.get("lit_right_after") is False,
          f"BEYOND's timecode never went back to the show after the "
          f"Abort's blank: {seen}")
    gate2.light = orig2
    check(gate2.lit is False and
          c.snapshot()["applied"]["lasers"] == C.BLACK,
          f"after the Stop's executor: dark, recorded black: "
          f"{c.snapshot()['applied']}")
    print("  ok")


def test_beyond_lasers_dark_when_the_engine_stops():
    section("fire & ice: when the engine stops (Ctrl-C, a closed console, the "
            "Windows app's stop), BEYOND's timecode goes to the black zone "
            "first, a few black frames over about 100 ms, and again as the "
            "gate closes (review of PR #43, P1-1)")
    import types
    from ltcplay import beyondtc as BT, cli as _cli
    sent, lines = [], []
    gate = BT.TimecodeGate("127.0.0.2", socket_factory=lambda: _TcSock(sent),
                           journal=lambda text, **k: lines.append(
                               (text, k.get("fault", False))))
    gate.light()
    t0 = time.monotonic()
    gate.close()
    took = time.monotonic() - t0
    black = [p for p, _a in sent if BT.tc_of(p)[0] == 23]
    check(len(black) == BT.CLOSE_BLACK_FRAMES >= 3 and gate.lit is False,
          f"closing sends {BT.CLOSE_BLACK_FRAMES} black frames and leaves "
          f"the gate dark: {len(black)} lit={gate.lit}")
    check(0.06 <= took < 1.0,
          f"spread over about 100 ms, not one burst: {took:.3f} s")
    check(any("black frames sent last" in t and not f for t, f in lines),
          f"journaled: {lines[-1:]}")
    nowhere = BT.TimecodeGate(None, journal=lambda text, **k: lines.append(
        (text, k.get("fault", False))))
    nowhere.close()
    check(lines[-1][1] and "check the lasers are dark" in lines[-1][0],
          f"a close that could send no black frame is a fault: {lines[-1]}")
    # The engine's way out: the black zone before anything else stops.
    order = []
    sent2 = []
    g2 = BT.TimecodeGate("127.0.0.2", socket_factory=lambda: _TcSock(sent2))
    g2.light()
    real_black = g2.send_black

    def black():
        order.append("black")
        return real_black()
    g2.send_black = black
    httpd = types.SimpleNamespace(
        schedule=None, loopback=None,
        control=types.SimpleNamespace(stop=lambda: order.append("stop")),
        fire_ice=types.SimpleNamespace(devices=types.SimpleNamespace(
            beyond=types.SimpleNamespace(gate=g2))),
        server_close=lambda: order.append("close"))
    import contextlib
    import io
    with contextlib.redirect_stdout(io.StringIO()):
        _cli._shutdown(httpd)
    check(order == ["stop"] + ["black"] * BT.CLOSE_BLACK_FRAMES + ["close"]
          and g2.lit is False,
          f"the engine's stop sends the black frames straight after the "
          f"show's own stop (the blackout stays first), before anything "
          f"else closes: {order}")
    print("  ok")


def test_flame_groups_are_a_settings_change_only():
    section("fire & ice: the flame groups live in flamesafe's config only; "
            "renaming or regrouping there changes the deck's labels, and an "
            "edit that cannot work (a channel in two "
            "groups, a head the layout does not have) is refused at start "
            "in a sentence")
    import json as _json
    import shutil
    import tempfile
    import types
    from ltcplay import streamdeck as sd
    F = _fi_mod()
    work = tempfile.mkdtemp()
    try:
        fs, show, doc = _fi_flame_files(work)
        cfg = types.SimpleNamespace(flamesafe_config=fs,
                                    flame_controller="Flames")

        def write(groups):
            d = dict(doc, groups=groups)
            with open(fs, "w", encoding="utf-8") as fh:
                _json.dump(d, fh)

        def refusal(groups):
            write(groups)
            try:
                F.check_flame_groups(show, cfg)
                return ""
            except F.FireIceConfigError as e:
                return str(e)
        good = [{"name": "stage left", "safety": 401,
                 "fire": [411, 412, 421]},
                {"name": "stage right", "safety": 402, "fire": [413, 414]},
                {"name": "finale", "safety": 403, "fire": [431, 432]}]
        check(refusal(good) == "", "a renamed and regrouped config passes")
        check(sd.load_flamesafe_link(fs)[5] ==
              ["stage left", "stage right", "finale"],
              "the deck's labels are the config's new names, in order")
        moved = [dict(good[0], fire=[411, 412]),
                 dict(good[1], fire=[413, 414, 421]), good[2]]
        check(refusal(moved) == "", "a head moved to another group passes")
        four = good + [{"name": "spare", "safety": 404, "fire": [441]}]
        check(refusal(four) == "",
              "a fourth group passes (the fireball, 2026-10-26: the deck "
              "reaches it from a screen only)")
        check(sd.load_flamesafe_link(fs)[5] ==
              ["stage left", "stage right", "finale", "spare"],
              "the deck is given all four names, in config order")
        five = four + [{"name": "extra", "safety": 405, "fire": [451]}]
        check(refusal(five) == "" and len(sd.load_flamesafe_link(fs)[5]) ==
              5, "five groups pass too: the ones past the deck's keys are "
                 "armed from a screen, said at the deck's start")
        twice = [good[0], dict(good[1], fire=[413, 411]), good[2]]
        e = refusal(twice)
        check("channel 411 is in both stage left and stage right" in e, e)
        unknown = [good[0], good[1], dict(good[2], fire=[431, 900])]
        e = refusal(unknown)
        check("finale lists channel 900" in e and "no such head" in e, e)
        # ltc serve refuses to start on such an edit, before binding.
        import contextlib
        import io
        from ltcplay import cli as _cli
        write(twice)
        with open(os.path.join(work, "ltcplay_fire_ice.json"), "w") as fh:
            _json.dump({"flamesafe_config": fs,
                        "flame_controller": "Flames"}, fh)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), \
                contextlib.redirect_stderr(out):
            rc = _cli._cmd_serve(types.SimpleNamespace(
                folder=show, schedule=os.path.join(
                    work, "ltcplay_schedule.json")))
        check(rc and "channel 411 is in both" in out.getvalue(),
              f"ltc serve refuses it in a sentence: {rc} {out.getvalue()!r}")
        same = [good[0], dict(good[1], name="stage left"), good[2]]
        check("both called 'stage left'" in refusal(same), "duplicate name")
        for e in (refusal(twice), refusal(unknown)):
            check("—" not in e and "–" not in e, f"no dashes: {e}")
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_one_flamesafe_config_or_none_starts():
    section("fire & ice: the Windows app's showpc.json, --flamesafe-config, "
            "ltcplay_fire_ice.json and ltcplay_remote.json must name the "
            "same flamesafe config, or ltc serve refuses to start in a "
            "sentence (review of PR #43, P1-4)")
    import contextlib
    import io
    import json as _json
    import shutil
    import tempfile
    import types
    from ltcplay import cli as _cli, remote as RM
    F = _fi_mod()
    work = tempfile.mkdtemp()
    real_load = RM.load_settings
    saved = os.environ.pop(_cli.FLAMESAFE_ENV, None)
    try:
        a = os.path.join(work, "a.json")
        b = os.path.join(work, "b.json")
        remote = {"flamesafe_config": None, "show_network_address": None,
                  "screen_arming": False, "path": "ltcplay_remote.json"}
        RM.load_settings = lambda folder=None: dict(remote)
        real_folder = RM.settings_folder
        RM.settings_folder = lambda: work
        fi = F.FireIceConfig(flamesafe_config=a,
                             path=os.path.join(work, "ltcplay_fire_ice.json"))
        args = types.SimpleNamespace(flamesafe_config=None)
        check(_cli._one_flamesafe_config(args, fi) == (a, None),
              "one place names it: that one")
        os.environ[_cli.FLAMESAFE_ENV] = os.path.join(work, ".", "a.json")
        remote["flamesafe_config"] = a
        check(_cli._one_flamesafe_config(args, fi) == (os.path.join(
            work, ".", "a.json"), None),
            "every place names the same file (spelt differently): fine")
        for where, setup in (
                ("showpc.json", lambda: os.environ.__setitem__(
                    _cli.FLAMESAFE_ENV, b)),
                ("--flamesafe-config", lambda: setattr(
                    args, "flamesafe_config", b)),
                ("ltcplay_remote.json", lambda: remote.__setitem__(
                    "flamesafe_config", b))):
            os.environ[_cli.FLAMESAFE_ENV] = a
            args.flamesafe_config = None
            remote["flamesafe_config"] = a
            setup()
            got, why = _cli._one_flamesafe_config(args, fi)
            check(got is None and why and "different flamesafe configs" in
                  why and a in why and b in why and "\u2014" not in why,
                  f"{where} naming another file is refused, naming both: "
                  f"{why}")
        # The real ltc serve start refuses it before binding anything.
        os.environ[_cli.FLAMESAFE_ENV] = b
        remote["flamesafe_config"] = None
        args.flamesafe_config = None
        fs, show, _doc = _fi_flame_files(work)
        with open(os.path.join(work, "ltcplay_fire_ice.json"), "w") as fh:
            _json.dump({"flamesafe_config": fs, "beyond_blank": "osc"}, fh)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), \
                contextlib.redirect_stderr(out):
            rc = _cli._cmd_serve(types.SimpleNamespace(
                folder=show, schedule=os.path.join(
                    work, "ltcplay_schedule.json")))
        check(rc and "different flamesafe configs" in out.getvalue(),
              f"ltc serve refuses to start: {rc} {out.getvalue()!r}")
        refused = os.path.join(work, _cli.REFUSED_FILE)
        got = open(refused, encoding="utf-8").read() \
            if os.path.exists(refused) else ""
        check("different flamesafe configs" in got,
              f"and leaves the reason in the settings folder for the Windows "
              f"supervisor and the rack screen (re-review P2-g): {got!r}")
        _cli._say_refused(None)
        check(not os.path.exists(refused),
              "a start that gets past the check clears it")
    finally:
        RM.load_settings = real_load
        try:
            RM.settings_folder = real_folder
        except NameError:
            pass
        os.environ.pop(_cli.FLAMESAFE_ENV, None)
        if saved is not None:
            os.environ[_cli.FLAMESAFE_ENV] = saved
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_config_defaults_and_refusals():
    section("fire & ice: the config file defaults to today's dry run, and "
            "anything that is not exactly true or false is refused")
    import tempfile
    F = _fi_mod()
    work = tempfile.mkdtemp()
    rule = os.path.join(work, "ltcplay_schedule.json")
    path = F.config_path_for(rule)
    check(path == os.path.join(work, "ltcplay_fire_ice.json"),
          f"the config sits beside the schedule rule file: {path}")
    cfg = F.FireIceConfig.load(path)
    check(cfg.scheduler_performs is False and cfg.madmapper is None and
          cfg.beyond is None and cfg.show_cue is None,
          "no file: the scheduler stays a dry run, no lasers, no video")
    for bad in ("true", 1, "yes", None):
        try:
            F.FireIceConfig.parse({"scheduler_performs": bad})
            check(False, f"scheduler_performs {bad!r} was accepted")
        except F.FireIceConfigError as e:
            check("true or false" in str(e), f"refused in a sentence: {e}")
    try:
        F.FireIceConfig.parse({"scheduler_perform": True})
        check(False, "a misspelt key was accepted")
    except F.FireIceConfigError as e:
        check("scheduler_perform" in str(e), f"names the typo: {e}")
    with open(path, "w") as fh:
        fh.write("{not json")
    try:
        F.FireIceConfig.load(path)
        check(False, "a broken file was accepted")
    except F.FireIceConfigError as e:
        check(path in str(e), f"a broken file is refused: {e}")
    cfg = F.FireIceConfig.parse({
        "scheduler_performs": True, "show_cue": "Show",
        "madmapper": {"surfaces": ["Quad-1"]}, "beyond": {}})
    check(cfg.scheduler_performs is True and cfg.show_cue == "Show" and
          cfg.madmapper is not None and cfg.beyond is not None,
          f"a full config parses: {cfg.summary()}")
    # The show's name comes from this file, not the shared brand file.
    import types
    from ltcplay import web as W
    from ltcplay import brand as B
    cfg = F.FireIceConfig.parse({"show_name": " Ignite the Night ",
                                 "venue": "Thanksgiving Point"})
    b = W.brand_doc(types.SimpleNamespace(fire_ice_config=cfg))
    check(b["show"] == "Ignite the Night" and
          b["venue"] == "Thanksgiving Point" and
          b["name"] == B.load()["name"],
          f"/api/brand names the Fire & Ice show from its own config, "
          f"under the global brand: {b}")
    plain = W.brand_doc(types.SimpleNamespace(fire_ice_config=None))
    page = screen_text()
    check("beyond_blank" not in b and "Lasers blanked" not in page and
          "black zone" not in page.lower(),
          "the web pages say nothing about how the lasers are blanked "
          "(Jeff, 2026-10-07)")
    check(plain["show"] == B.load()["show"] and
          "Ignite" not in json.dumps(B.load()),
          f"without Fire & Ice the shared brand file names no show: "
          f"{plain}")
    for bad in ("", 3):
        try:
            F.FireIceConfig.parse({"show_name": bad})
            check(False, f"show_name {bad!r} was accepted")
        except F.FireIceConfigError as e:
            check("show_name" in str(e), f"refused in a sentence: {e}")
    print("  ok")


def test_fire_ice_show_outputs():
    section("fire & ice: ShowOutputs drives the real show audio with the "
            "conductor's own fade, reads 'frozen' from the clock's own "
            "signal, blacks the pixels out and back, and an Abort's disarm "
            "fails loudly")
    import types
    F, C = _fi_mod(), _cond_mod()
    T = _CondTime()
    calls, lines = [], []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    control = types.SimpleNamespace(session=None)
    show = F.FireIceShow(control, journal=journal)
    check(any("no flame link" in t and f for t, f in lines),
          f"no flame link is a fault line at start: {lines}")
    # Nothing running: nothing is playing, and music refuses in words.
    check(show.playing() is False, "nothing running: nothing playing")
    r = show.music_hold(0.25)
    check(not r.ok and "show control" in r.sentence,
          f"music with nothing running is refused: {r}")
    check(show.music_frozen() is None, "no clock: frozen is unknown")
    check(not show.pixels_fade_out(0.25).ok, "pixels need a running show")
    s = _FiSession(calls, T)
    control.session = s
    check(show.playing() is False, "running, no cue: not playing")
    s.clock_play()
    check(show.playing() is True, "a cue playing reads as playing")
    # Hold: the fade the conductor asks for, in ms; frozen only once the
    # clock says so, not from the request.
    check(show.music_hold(0.25).ok, "Hold sent")
    check(calls[-1][:2] == ("music_hold", (250.0,)),
          f"AudioMaster.pause got the conductor's 0.25 s: {calls[-1]}")
    check(show.music_frozen() is False,
          "asked to hold but not frozen yet: frozen is False")
    T.wait(1.0)
    check(show.music_frozen() is True, "frozen once on_pause fires")
    check(s.parks == [True], "the session's own on_pause still runs first")
    check(show.music_hold(0).ok and calls[-1][:2] == ("music_hold", (0.0,)),
          f"rehearsal's instant Hold passes 0: {calls[-1]}")
    check(show.music_resume(0.25).ok and
          calls[-1][:2] == ("music_resume", (250.0,)),
          f"Resume passes its fade: {calls[-1]}")
    check(show.music_frozen() is True, "still frozen until it moves")
    for _ in range(3):              # one scheduled event per wait
        T.wait(1.0)
    check(show.music_frozen() is False and s.parks[-1] is False,
          "moving once on_resume fires, after the session's own")
    check(show.music_halt(1.0).ok and calls[-1][:2] == ("music_halt",
                                                        (1000.0,)),
          f"Abort's music fade is 1 s: {calls[-1]}")
    # Pixels: the operator's look before is put back, and a look the
    # operator picks while the conductor has them black stands.
    s.player.override = "preshow"
    check(show.pixels_fade_out(0.25).ok and s.player.override == "blackout",
          "pixels to black")
    check(any("not over 0.25 s" in t for t, _ in lines),
          "black at once is journaled as not a fade")
    check(show.pixels_restore(0.25).ok and s.player.override == "preshow",
          "the look from before comes back")
    show.pixels_fade_out(0)
    s.player.override = None          # the operator pressed auto
    check(show.pixels_restore(0).ok and s.player.override is None,
          "the operator's own look is left alone")
    s.player.override = "preshow"
    check(show.pixels_restore(0).ok and s.player.override == "preshow",
          "restore when the conductor never took them changes nothing")
    # Flames: no link in this build. Zero and release say so; the disarm
    # is never a quiet success.
    check(show.flames_zero().ok, "flame cues zero")
    del lines[:]
    check(show.flames_release().ok and
          any("no flame link" in t for t, _ in lines),
          f"a release with no flame link is journaled: {lines}")
    r = show.flames_disarm_all("Abort")
    check(not r.ok and "cannot disarm" in r.sentence and
          "CONTRACT.md" in r.sentence and show.flames == C.ZERO,
          f"the disarm fails loudly and the cues are zero: {r}")
    # With the flame link (PR #34): the disarm goes through its disarm_all,
    # which zeroes the cues itself, and is done only when it went out.
    fl = _FiFlames(calls, T)
    show2 = F.FireIceShow(control, journal=journal, flame_link=fl)
    show2.flames_release()
    r = show2.flames_disarm_all("Abort")
    check(r.ok and calls[-1][0] == "flames_disarm" and
          fl.reasons == ["Abort"] and show2.flames == C.ZERO and
          "Sent is not confirmed" in r.sentence,
          f"with a flame link the disarm goes through it, and says sent "
          f"is not confirmed: {r}")
    fl.disarm_ok = False
    r = show2.flames_disarm_all("Abort")
    check(not r.ok and "could NOT be sent" in r.sentence,
          f"a disarm that did not go out is a failure: {r}")
    fl.disarm_all = lambda reason: 1 / 0
    r = show2.flames_disarm_all("Abort")
    check(not r.ok, f"a flame link that raises is a failure, never a "
                    f"crash: {r}")
    print("  ok")


def test_audio_master_per_call_fade():
    section("audio_master: pause, resume and halt take one call's own fade "
            "(the conductor's), and without one are exactly as before")
    r = _am_rig(seconds=6.0)
    am, sim, eng, vc = r["am"], r["sim"], r["eng"], r["vc"]
    sent = []
    real_send = eng.send
    eng.send = lambda msg: (sent.append(msg), real_send(msg))[1]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 1.0)
    del sent[:]
    am.pause(fade_ms=0)
    check(sent and sent[0][:2] == ("pause", 0),
          f"pause(fade_ms=0) stops the audio at once: {sent}")
    check(len(r["calls"]["pause"]) == 1,
          "and the clock froze at once (on_pause)")
    sim.run(vc() + 0.3)
    del sent[:]
    am.resume(fade_ms=0)
    # ("resume", fade, token), or ("play", role, frame, fade, token) when
    # the audio process had not yet reported holding the cue.
    check(sent and ((sent[0][0] == "resume" and sent[0][1] == 0) or
                    (sent[0][0] == "play" and sent[0][3] == 0)),
          f"resume(fade_ms=0) comes back with no fade: {sent}")
    sim.run(vc() + 0.5)
    del sent[:]
    am.pause()
    check(sent and sent[0][:2] == ("pause", 12000),
          f"pause() is still hold_fade_ms, 250 ms: {sent}")
    sim.run(vc() + 0.6)
    del sent[:]
    am.resume()
    check(sent and sent[0][:2] == ("resume", 12000),
          f"resume() after a resume(fade_ms=0) is 250 ms again: {sent}")
    sim.run(vc() + 0.5)
    del sent[:]
    am.pause(fade_ms=500.0)
    check(sent and sent[0][:2] == ("pause", 24000),
          f"pause(fade_ms=500) fades over 500 ms: {sent}")
    sim.run(vc() + 0.8)
    am.resume(fade_ms=100)
    sim.run(vc() + 0.5)
    del sent[:]
    am.halt(fade_ms=500)
    check(sent and sent[0] == ("level", 0.0, 24000),
          f"halt(fade_ms=500) fades over 500 ms: {sent}")
    sim.run(vc() + 1.0)
    am.play(3600.0, None, "Show")
    sim.run(vc() + 1.0)
    del sent[:]
    am.halt()
    check(sent and sent[0] == ("level", 0.0, 48000),
          f"halt() is still abort_fade_ms, 1 s: {sent}")
    eng.send = real_send
    am.stop()
    print("  ok")


def test_lasers_blanking_not_set_up_is_loud():
    section("lasers: OSC blanking with no BEYOND OSC address is a standing "
            "fault (journal at startup and each show start, Lasers lamp "
            "bad, blank says False); a configured one is as before; a send "
            "that raises is a fault note, never an exception")
    import types
    import tempfile
    from ltcplay import beyondtc as BT, conductor as C, remote as RM
    F = _fi_mod()

    def chip(cond):
        sched = types.SimpleNamespace(conductor=cond, state_dir=None)
        r = RM.Remote(types.SimpleNamespace(session=None), sched,
                      folder=tempfile.gettempdir())
        got = [x for x in r.subsystems({}) if x["name"] == "Lasers"]
        return got[0] if got else None, r.laser_fault()

    for configured in (False, True):
        for mode in ("osc", "both"):
            lines = []

            def journal(text, **f):
                lines.append((text, bool(f.get("fault")), f.get("outcome")))
            osc = None
            if configured:
                osc = types.SimpleNamespace(
                    cfg=types.SimpleNamespace(host="10.0.0.9", port=8100),
                    last_result="ok")
                osc.blank = lambda show=None: True
                osc.unblank = lambda show=None, **k: True
            cfg = F.FireIceConfig(beyond_blank=mode,
                                  beyond_timecode_ip="10.0.0.9")
            b = F.build_blanking(cfg, osc, journal, threaded=False)
            tag = f"{mode}, {'configured' if configured else 'no beyond'}"
            nsu = [x for x in lines if x[2] == "not_set_up"]
            if configured:
                check(b.fault is None and not nsu,
                      f"{tag}: no standing fault: {b.fault} {nsu}")
            else:
                check(b.fault == BT.NOT_SET_UP == "Lasers: blanking not "
                      "set up" and len(nsu) == 1 and nsu[0][1],
                      f"{tag}: one startup fault journaled: {lines}")
                check(b.note_not_set_up("show start") and
                      sum(1 for x in lines if x[2] == "not_set_up") == 2,
                      f"{tag}: journaled again at a show start")
            if not configured:
                half = BT.Blanking(mode, osc=types.SimpleNamespace(
                    cfg=types.SimpleNamespace(host="", port=8100)))
                check(half.fault == BT.NOT_SET_UP,
                      f"{tag}: a beyond block with no host is not set up")
            check(b.blank() is configured,
                  f"{tag}: blank() says {configured}")
            dev = C.ConductorDevices(None, b, show=1)
            check(dev.lasers_blank().ok is configured,
                  f"{tag}: the conductor's laser blank ok={configured}")
            cond = types.SimpleNamespace(
                devices=dev, snapshot=lambda: {"applied": {"lasers": "BLACK"}})
            c, fault = chip(cond)
            if configured:
                check(c["state"] == "ok" and fault == "",
                      f"{tag}: the Lasers lamp as today: {c}")
            else:
                check(c["state"] == "bad" and c["word"] == "blanking not "
                      "set up" and fault == BT.NOT_SET_UP,
                      f"{tag}: the Lasers lamp is not ok: {c} {fault!r}")
            if b.gate is not None:
                b.gate.close()

    # attach(): the show-start check journals it and never refuses.
    n = _fi_night(session=False)
    if n.S is not None:
        lines = []
        ctl = types.SimpleNamespace(session=None)
        w = F.attach(n.svc, ctl, F.FireIceConfig(beyond_blank="osc"),
                     threaded=False,
                     journal=lambda t, **f: lines.append(f.get("outcome")))
        check(lines.count("not_set_up") == 1, f"attach: once at startup")
        got = ctl.before_open("/x/show1.json")
        check(got == {} and lines.count("not_set_up") == 2,
              f"attach: a show start journals it again and still opens: "
              f"{got} {lines.count('not_set_up')}")
        w.close()

    # A send that raises: a fault note and False, never an exception.
    for mode in ("osc", "both"):
        lines = []
        osc = types.SimpleNamespace(
            cfg=types.SimpleNamespace(host="10.0.0.9", port=8100),
            last_result=None)

        def boom(show=None, **k):
            raise OSError(65, "No route to host")
        osc.blank = osc.unblank = boom
        b = BT.Blanking(mode, osc=osc,
                        journal=lambda t, **f: lines.append(
                            (t, f.get("fault"), f.get("outcome"))))
        try:
            r1, r2 = b.blank(), b.unblank(in_show=True)
            raised = None
        except Exception as e:
            r1 = r2 = None
            raised = e
        check(raised is None and r1 is False and r2 is False,
              f"{mode}: a raising send is False, not {raised!r}")
        check(sum(1 for x in lines if x[2] == "send_failed" and x[1]) == 2,
              f"{mode}: each raising send is a fault note: {lines}")
    print("  ok")


def _fi_night(performs=True, session=True, flames=True, armed=True,
              work=None, auto_start="when_run_pressed",
              programming_lasers=None):
    """A Fire & Ice night: the real scheduler service on a fake wall clock,
    the real conductor built by fire_ice.attach() on fake time, the real
    ConductorDevices on real BEYOND and MadMapper links whose sockets write
    into the shared log, a fake session for music and pixels, and a fake
    flame link. And the laser arm (laserarm.py, Jeff 2026-10-22), attached
    the way web.serve attaches it, with both lasers armed unless `armed`
    is False (its start-up dark is not run: the log starts clean)."""
    import tempfile
    import types
    from ltcplay import madmapper as MM, beyond as B
    S = _sched()
    F = _fi_mod()
    T = _CondTime()
    calls, lines = [], []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    steps = _Steps()
    link = MM.Link(_mm_cfg(ramp_steps=5),
                   socket_factory=lambda: _StampSock("mm", calls, T.now),
                   clock=steps.clock, sleep=steps.sleep, journal=journal)
    for name in ("fade_surfaces", "set_surfaces", "cancel", "stop_bank",
                 "select_bank"):
        def rec(*a, _name=name, _fn=getattr(link, name), **k):
            calls.append(("mm_call", (_name,) + a, T.now()))
            return _fn(*a, **k)
        setattr(link, name, rec)
    bey = B.Beyond(B.BeyondConfig.parse({}),
                   socket_factory=lambda: _StampSock("beyond", calls, T.now),
                   clock=steps.clock, sleep=steps.sleep, journal=journal)
    sess = _FiSession(calls, T) if session else None
    control = types.SimpleNamespace(session=sess)
    work = work or tempfile.mkdtemp()
    now = [_den(S, 17, 55)]
    svc = _svc(S, work, now)
    # This rig proves the OSC path (beyond_blank "osc"); the timecode
    # black zone has tests of its own (test_beyond_timecode_blanking).
    cfg = F.FireIceConfig(scheduler_performs=performs, beyond_blank="osc",
                          auto_start=auto_start)
    w = F.attach(svc, control, cfg, madmapper=(link, None), beyond=bey,
                 journal=journal,
                 flame_link=_FiFlames(calls, T) if flames else None,
                 threaded=False, clock=T.now, waiter=T.wait,
                 programming_lasers=programming_lasers)
    from ltcplay import laserarm as LA
    c = w.conductor

    def blockers():
        st = svc.machine.state if svc.machine is not None else None
        if st in ("PAUSED", "HOLD") or c.snapshot()["look"] in ("HELD",
                                                               "DARK"):
            return "the show is on Hold; press Resume first, then arm"
        return ""
    arm = LA.LaserArm([("laser-1", "Laser 1"), ("laser-2", "Laser 2")],
                      output=lambda: w.devices.beyond, blockers=blockers,
                      blank_now=c.lasers_dark_now, journal=journal,
                      threaded=False, sleep=steps.sleep)
    arm._jobs.clear()
    w.attach_laser_arm(arm)
    if armed:
        check(arm.arm(list(arm.order), who="Andy", confirmed=True)[0],
              "setup: every laser armed")
        arm._jobs.clear()
    return types.SimpleNamespace(S=S, F=F, T=T, calls=calls, lines=lines,
                                 link=link, bey=bey, sess=sess,
                                 control=control, svc=svc, now=now, w=w,
                                 c=w.conductor, work=work, arm=arm)


def _fi_log(calls):
    """The shared log as (what, value), one entry per command: BEYOND's
    3 retries of one command collapse to one, MadMapper's own packets are
    dropped (their CALL is what is ordered, on the conductor's thread)."""
    from ltcplay import beyond as B
    out = []
    for kind, args, _t in calls:
        if kind == "mm":
            continue
        if kind == "beyond" and args[0] in B.OUTPUT_ADDRESSES:
            e = ("laser output", "on" if args[0] == B.ENABLE_OUTPUT_ADDR
                 else "off")
        elif kind == "beyond":
            e = ("lasers", "dark" if args[1] == B.BLANK_VALUE else "lit")
        elif kind == "mm_call":
            e = ("video", args[0] if args[0] != "fade_surfaces"
                 else f"fade {args[1]:g} to {args[2]:g}")
        elif kind == "pixels":
            e = ("pixels", args[0] or "auto")
        elif kind.startswith("music_"):
            e = ("music", kind[6:] + ("" if not args or args[0] is None or
                                      isinstance(args[0], str)
                                      else f" {args[0]:g} ms"))
        else:
            e = ("flames", kind[7:])
        if e == ("video", "cancel"):
            # A cancel of a fade that may or may not be running (PR #29's
            # fix rounds send one before every new fade): not an output
            # change, so not part of the order these tests check.
            continue
        if not out or out[-1] != e or e[0] not in ("lasers",
                                                    "laser output"):
            out.append(e)
    return out


def test_fire_ice_night_end_to_end():
    section("fire & ice end to end: a scheduled night with fake devices and "
            "a fake clock runs preshow, show start, Hold, Resume and Abort, "
            "and every command to lasers, video, music, pixels and flames "
            "goes out in order")
    n = _fi_night()
    if n.S is None:
        return
    S, svc, c, T = n.S, n.svc, n.c, n.T
    check(svc.conductor is c and svc.performer is n.w.runner and
          svc.dry_run is False,
          "attach() wires the conductor, the runner, and ends the dry run")
    check(c.wired, "BEYOND and MadMapper both given: the conductor is wired")
    bl = n.w.devices.beyond
    check(bl.arm_check is not None and bl._arm_refusal() is None,
          "the Blanking asks the laser arm too (every laser armed: yes)")
    n.w._arm_slot["arm"] = None
    check("not set up" in (bl._arm_refusal() or ""),
          "with no laser arm attached the lasers stay dark")
    n.w._arm_slot["arm"] = n.arm
    # Preshow: within the lead the scheduler is already in intermission.
    svc.tick()
    _settle(svc, c)
    check(svc.machine.state == S.STANDBY, f"preshow: {svc.machine.state}")
    check(c.laser_gate() is not None,
          "the laser gate is the scheduler's: no lasers in intermission")
    pre = _fi_log(n.calls)
    check(pre == [("flames", "zero"), ("lasers", "dark")],
          f"preshow: flame cues zero, lasers blanked, nothing else: {pre}")
    del n.calls[:]
    # Show start, on schedule.
    n.now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    _mm_flush(n.link)
    check(svc.machine.state == S.SHOW, "show 1 starts on schedule")
    start = _fi_log(n.calls)
    check(start == [("video", "select_bank"), ("music", "play")],
          f"show start: the show bank, then the show audio, and nothing "
          f"else until the timecode is seen moving: {start}")
    rows = [r for r in svc.journal if r.get("action") == "automatic start"]
    check(rows and rows[-1]["outcome"] == "done",
          f"the automatic start is journaled: {rows}")
    n.w.runner.poll()
    _settle(svc, c)
    check(svc.machine.slot(svc.machine.running).confirmed_at is None,
          "not confirmed before the timecode moves")
    check(_fi_log(n.calls) == start,
          "the conductor is not told a show started before it is confirmed")
    n.sess.clock._last_frame = 30
    n.w.runner.poll()
    _settle(svc, c)
    _mm_flush(n.link)
    check(svc.machine.slot(svc.machine.running).confirmed_at is not None,
          "confirmed once the timecode moves")
    start = _fi_log(n.calls)
    check(start == [("video", "select_bank"), ("music", "play"),
                    ("video", "fade 1 to 1"), ("laser output", "on"),
                    ("lasers", "lit"), ("flames", "release")],
          f"once confirmed: video up, BEYOND's laser output on, then the "
          f"lasers lit through the gate, flame cues last: {start}")
    check(c.laser_gate() is None, "in the show the gate allows the lasers")
    del n.calls[:]
    # Hold.
    n.now[0] = _den(S, 18, 1)
    T.t = 300.0
    out = svc._apply(_op(S, S.HOLD_ON))
    _settle(svc, c)
    _mm_flush(n.link)
    hold = _fi_log(n.calls)
    check(svc.machine.state == S.PAUSED and c.snapshot()["look"] == "HELD",
          f"Hold: {svc.machine.state} {c.snapshot()['look']}")
    check(n.arm.armed_ids() == [] and n.arm.pending() == ["dark"],
          "Hold disarmed every laser (Jeff, 2026-10-22)")
    n.arm._jobs.clear()
    check(hold == [("flames", "zero"), ("lasers", "dark"),
                   ("music", "hold 250 ms"), ("video", "fade 1 to 0"),
                   ("pixels", "blackout")],
          f"Hold: flames, lasers, then the 0.25 s music fade, video and "
          f"pixels to black: {hold}")
    check(not any("did not say it had frozen" in t for t, _ in n.lines),
          "the conductor saw the clock freeze, from its own signal")
    del n.calls[:]
    # Resume.
    n.now[0] = _den(S, 18, 2)
    out = svc._apply(_op(S, S.RESUME))
    _settle(svc, c)
    _mm_flush(n.link)
    res = _fi_log(n.calls)
    check(svc.machine.state == S.SHOW, "Resume: back in the show")
    check(res == [("music", "resume 250 ms"), ("video", "fade 0 to 1"),
                  ("pixels", "auto"), ("lasers", "dark"),
                  ("flames", "release")],
          f"Resume: music, video, pixels, then once the timecode moves the "
          f"lasers stay DARK (Hold disarmed them), and the flame cues last: "
          f"{res}")
    mus_before = [t for k, a, t in n.calls if k == "music_resume"]
    del n.calls[:]
    ok, text = n.arm.arm(list(n.arm.order), who="Andy", confirmed=True)
    n.arm._jobs.clear()
    _settle(svc, c)
    res = _fi_log(n.calls)
    check(ok and res == [("laser output", "on"), ("lasers", "lit")],
          f"re-armed after Resume: BEYOND's output on and the lasers lit, "
          f"nothing else: {text} {res}")
    lit = [t for k, a, t in n.calls if k == "beyond"]
    mus = mus_before
    check(lit and mus and min(lit) >= mus[0] + n.sess.clock.move_s - 1e-9,
          "the lasers came back only after the clock said it moved")
    del n.calls[:]
    # Stop (every guarantee the removed Abort had).
    n.now[0] = _den(S, 18, 3)
    T.t = 400.0
    out = svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(svc, c)
    _mm_flush(n.link)
    ab = _fi_log(n.calls)
    check(svc.machine.state == S.HOLD and
          c.snapshot()["look"] == "STOPPED_DARK" and
          n.arm.armed_ids() == [],
          f"Stop: {svc.machine.state}, {c.snapshot()['look']}, every laser "
          f"disarmed")
    # The cut first, then the disarm through the flame link, on the
    # pressing thread, before anything else; it went out, so the executor
    # does not send it again.
    check(ab[:2] == [("flames", "zero"), ("flames", "disarm")],
          f"Stop zeroes the flame cues, then disarms every group through "
          f"the flame link, first: {ab}")
    check(ab[2:] == [("lasers", "dark"), ("video", "fade 1 to 0"),
                     ("pixels", "blackout"), ("music", "halt 1000 ms"),
                     ("lasers", "dark"), ("video", "stop_bank")],
          f"then lasers dark, video, pixels and music fade over 1 s, then "
          f"the video stops: {ab}")
    stop = [t for k, a, t in n.calls if k == "mm_call" and
            a[0] == "stop_bank"]
    check(stop and abs(stop[0] - 401.0) < 1e-6,
          f"the video stops after the 1 s fade: {stop}")
    faults = [t for t, f in n.lines if f and "cannot disarm" in t]
    check(not faults, f"with a flame link the Stop's disarm is no fault: "
                      f"{faults}")
    # The runner reports nothing for a stopped show.
    before = len(svc.journal)
    n.w.runner.poll()
    check(len(svc.journal) == before, "nothing reported after the Stop")
    # The next show, on the Stop's Hold: nothing is started.
    del n.calls[:]
    n.now[0] = _den(S, 18, 20)
    svc.tick()
    _settle(svc, c)
    check(not any(k == "music_play" for k, _a, _t in n.calls),
          f"Stop's Hold: the next show's audio is not started: {n.calls}")
    n.w.runner.poll()
    s2 = [x for x in svc.machine.slots if x.n == 2]
    check(svc.machine.state == S.HOLD and s2 and
          s2[0].status != S.RUNNING,
          f"and the scheduler stays on the Stop's Hold until Resume: "
          f"{svc.machine.state} {s2}")
    c.close()
    n.link.close()
    print("  ok")


def _fi_rig_touched(calls, since=0):
    """Every command a Fire & Ice rig was sent after `since`: MadMapper
    (its packets and its calls), BEYOND, pixels, music and flames."""
    return [(k, a) for k, a, _t in calls[since:]
            if k in ("mm", "mm_call", "beyond", "pixels") or
            k.startswith("music_") or k.startswith("flames_")]


def test_fire_ice_stop_resume_start_now_video_follows_again():
    section("fire & ice: after Stop, Resume and Start now MadMapper's show "
            "bank is set following timecode again: the Stop's "
            "conductor/stop is answered by conductor/play T right after "
            "the bank select, before the show audio starts (Jeff's field "
            "report, 2026-10-28; bench B2)")
    from ltcplay import madmapper as MM
    n = _fi_night()
    if n.S is None:
        return
    S, svc, c = n.S, n.svc, n.c
    play = ("/timelines/Bank-1/conductor/play", None)
    select = ("/timelines/Bank-1/select", None)
    stop = ("/timelines/Bank-1/conductor/stop", None)

    def mm_sent(since):
        return [a for k, a, _t in n.calls[since:] if k == "mm"]

    def order(since):
        # MadMapper's packets go out on its Link's own thread, in the
        # order they were queued: select, then play. The show audio is
        # asked for after both were queued (fire_ice.ShowRunner.
        # start_show), whenever the worker sends them.
        return [a for k, a, _t in n.calls[since:]
                if k == "mm" and a in (play, select, stop)] + \
            [k for k, _a, _t in n.calls[since:] if k == "music_play"][:1]
    # The scheduled show: select, then play, then the show audio.
    at = len(n.calls)
    n.now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    _mm_flush(n.link)
    got = order(at)
    check(svc.machine.state == S.SHOW and
          got == [select, play, "music_play"],
          f"a scheduled show start: bank select, conductor/play T, then the "
          f"show audio: {got}")
    # The bytes are the documented message, bench B2's ",T".
    want = MM.encode("/timelines/Bank-1/conductor/play", (True,))
    check(want == b"/timelines/Bank-1/conductor/play\x00\x00\x00\x00"
          b",T\x00\x00", f"conductor/play T is {want!r}")
    n.sess.clock._last_frame = 30
    n.w.runner.poll()
    _settle(svc, c)
    # Stop: the bank is stopped, as before (Tier A unchanged).
    n.now[0] = _den(S, 18, 3)
    at = len(n.calls)
    svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(svc, c)
    _mm_flush(n.link)
    check(stop in mm_sent(at) and play not in mm_sent(at),
          f"the Stop still stops the show bank and sends no play: "
          f"{mm_sent(at)}")
    # Resume (the Stop's Hold), then Start now.
    out = svc._apply(_op(S, S.RESUME))
    _settle(svc, c)
    check(out.accepted and svc.machine.state == S.STANDBY,
          f"Resume: {out.refused} {svc.machine.state}")
    at = len(n.calls)
    n.now[0] = _den(S, 18, 5)
    svc._apply(_op(S, S.START_NOW, confirmed=True))
    _settle(svc, c)
    _mm_flush(n.link)
    got = order(at)
    check(got == [select, play, "music_play"],
          f"Start now after Stop and Resume: bank select, conductor/play T, "
          f"then the show audio: {got}")
    c.close()
    n.link.close()
    # A link that cannot send says so in the journal, and the show start
    # carries on (never raises).
    from ltcplay import fire_ice as F
    notes = []

    import types

    class Bad:
        cfg = types.SimpleNamespace(show_bank="Bank-1")

        def play(self, name, wait=True):
            raise OSError("no route")
    b = Bad()
    F.follow_show_bank(b, lambda text, **k: notes.append((text, k)))
    check(len(notes) == 1 and "following timecode again failed" in
          notes[0][0] and notes[0][1].get("fault") is True,
          f"a failed play is a fault line: {notes}")
    _no_dashes(notes[0][0], "the follow failure")
    print("  ok")


def _fi_walk(n, until_h, until_m, start=(17, 55)):
    """The night moved a minute at a time, the scheduler ticked, the show
    runner polled and every conductor call and effect run, as the engine
    does with nobody at the screen."""
    S, svc, c = n.S, n.svc, n.c
    h, m = start
    while (h, m) <= (until_h, until_m):
        n.now[0] = _den(S, h, m)
        svc.tick()
        _settle(svc, c)
        n.w.runner.poll()
        _settle(svc, c)
        n.now[0] = _den(S, h, m, 30)
        svc.tick()
        n.w.runner.poll()
        _settle(svc, c)
        m += 1
        if m == 60:
            h, m = h + 1, 0


def test_schedule_never_touches_the_rig_before_run():
    section("fire & ice: a schedule left live with Run never pressed tries "
            "each show, refuses it in words, and sends NOTHING to MadMapper, "
            "BEYOND, the surfaces, the pixels, the music or the flames: no "
            "failed-start fade, no dark sequence at a restart, no closing "
            "(Pico, 2026-10-23 overnight)")
    n = _fi_night(session=False, armed=False)
    if n.S is None:
        return
    S, svc, c = n.S, n.svc, n.c
    k0 = len(n.calls)
    _fi_walk(n, 19, 5)
    starts = [r for r in svc.journal if r.get("action") == "automatic start"]
    check(len(starts) >= 3 and
          all(r["outcome"] == "refused" and
              "Show control is off" in r["text"] for r in starts),
          f"every show that came due (18:00, 18:20, 18:40, 19:00) was "
          f"tried and refused because Run was not pressed: "
          f"{[(r['outcome'], r['text']) for r in starts]}")
    touched = _fi_rig_touched(n.calls, k0)
    check(touched == [],
          f"nothing at all reached the rig while Run was not pressed: "
          f"{touched[:8]}")
    sent = [r for r in svc.journal if r.get("action") == "conductor" and
            r.get("outcome") == "sent"]
    check(sent and all("Start the show" in r["text"] for r in sent),
          f"the show conductor was asked for nothing (no Failed start, no "
          f"Out of the show); only the performer was handed each start, to "
          f"refuse: {[r['text'] for r in sent][:4]}")
    failed = [r for r in svc.journal if r.get("action") == S.SHOW_FAILED]
    check(len(failed) >= 3 and
          all(S.NOTHING_SENT_TO_RIG in r["text"] and
              "faded to black" not in r["text"] and
              "MadMapper stopped" not in r["text"] for r in failed),
          f"each refused start is journaled as one that sent nothing, never "
          f"as a fade or a MadMapper stop: {[r['text'] for r in failed][:2]}")
    held = [r for r in svc.journal if r.get("outcome") == "held back"]
    check(all(svc.RUN_NOT_PRESSED in r["text"] for r in held),
          f"anything the scheduler would have asked of the conductor says "
          f"why it was held back: {[r['text'] for r in held][:2]}")
    slots = [s for s in svc.machine.slots if s.n <= 4]
    check(len(slots) == 4 and all(s.status == S.FAULT for s in slots),
          f"the shows are marked as not started: {slots}")
    # A restart while the rig is meant to be dark (after those refused
    # starts) still sends nothing while Run is not pressed: the dark
    # sequence a restart sends is held back too.
    check(svc.machine.dark, "the night is left dark after the refusals")
    k1 = len(n.calls)
    n2 = _fi_night(session=False, armed=False, work=n.work)
    n2.now[0] = n.now[0]
    n2.svc.tick()
    _settle(n2.svc, n2.c)
    n2.c.run_pending()
    again = [r for r in n2.svc.journal if r.get("action") == "conductor" and
             r.get("outcome") == "sent" and
             "Start the show" not in r["text"]]
    check(not again and _fi_rig_touched(n2.calls) == [] and
          len(n.calls) == k1,
          f"a restart with Run not pressed sends no dark sequence: "
          f"{[r['text'] for r in again]} {_fi_rig_touched(n2.calls)[:6]}")
    check(any(svc.RUN_NOT_PRESSED in r["text"] and
              svc.DARK_AGAIN in r["text"] for r in n2.svc.journal),
          f"and says it held the restart's dark sequence back: "
          f"{[r['text'] for r in n2.svc.journal][-6:]}")
    # The rest of the night, its closing included, with Run still not
    # pressed: nothing reaches the rig, and the night still closes.
    k2 = len(n.calls)
    _fi_walk(n, 22, 10, start=(19, 6))
    check(_fi_rig_touched(n.calls, k2) == [] and
          svc.machine.state == S.OFF,
          f"the night's closing with Run not pressed touches nothing and "
          f"still closes: {svc.machine.state} "
          f"{_fi_rig_touched(n.calls, k2)[:6]}")
    # A call decided while Run was in force reaches the line after Stop:
    # it is held back then too. An operator's own press still goes.
    from ltcplay import schedule_service as SV
    k3 = len(n.calls)
    late = SV._ConductorCall("Out of the show", "intermission",
                             "the scheduler", "")
    svc._run_conductor_call(late)
    c.run_pending()
    check(late.ok is False and svc.RUN_NOT_PRESSED in late.sentence and
          _fi_rig_touched(n.calls, k3) == [],
          f"a scheduler call that finds Run no longer pressed is not sent: "
          f"{late.ok} {late.sentence!r} {_fi_rig_touched(n.calls, k3)[:4]}")
    mine = SV._ConductorCall("Out of the show", "intermission", "Andy",
                             "Rack screen")
    svc._run_conductor_call(mine)
    c.run_pending()
    check(mine.ok is True and _fi_rig_touched(n.calls, k3) != [],
          f"an operator's own press is still carried out: {mine.ok} "
          f"{mine.sentence!r}")
    was = svc.run_gate

    def broken():
        raise RuntimeError("no idea")
    svc.run_gate = broken
    check(svc._run_pressed() is False,
          "a Run check that raises counts as Run not pressed")
    svc.run_gate = lambda: "yes"
    check(svc._run_pressed() is False,
          "only a plain True counts as Run pressed")
    svc.run_gate = was
    # Once Run is pressed, the next show is started as before.
    n3 = _fi_night(session=True, armed=False)
    _fi_walk(n3, 18, 0)
    ok = [r for r in n3.svc.journal if r.get("action") == "automatic start"]
    check(ok and ok[-1]["outcome"] == "done" and
          ("mm_call", ("select_bank", "Bank-1")) in
          [(k, a[:2]) for k, a in _fi_rig_touched(n3.calls)],
          f"with Run pressed the scheduled show starts (MadMapper's show "
          f"bank selected): {[r['text'] for r in ok]}")
    for x in (n, n2, n3):
        x.c.close()
        x.link.close()
    print("  ok")


def test_a_refused_start_sends_no_fade():
    section("fire & ice: a start refused before anything went out (Run "
            "pressed, auto_start off) sends no fade and no dark sequence: "
            "the slot is a fault, the alert says nothing was sent, and the "
            "rig is left exactly as it was")
    n = _fi_night(session=True, armed=False, auto_start="off")
    if n.S is None:
        return
    S, svc, c = n.S, n.svc, n.c
    got = []
    svc.alert_sink = lambda kind, text: got.append((kind, text))
    _fi_walk(n, 17, 59)
    k0 = len(n.calls)
    _fi_walk(n, 18, 1)
    starts = [r for r in svc.journal if r.get("action") == "automatic start"]
    check(starts and starts[-1]["outcome"] == "refused" and
          "auto_start is off" in starts[-1]["text"],
          f"the start is refused: {[r['text'] for r in starts]}")
    touched = _fi_rig_touched(n.calls, k0)
    check(touched == [],
          f"a refused start sends no fade, no blank and no stop: "
          f"{touched[:8]}")
    sent = [r for r in svc.journal if r.get("action") == "conductor" and
            "Failed start" in r["text"]]
    check(sent == [], f"failed_start is never asked: {sent[:1]}")
    s1 = [s for s in svc.machine.slots if s.n == 1]
    check(s1 and s1[0].status == S.FAULT and svc.machine.state == S.STANDBY,
          f"show 1 is a fault and the night carries on: {s1} "
          f"{svc.machine.state}")
    check(got and got[-1] == ("start", svc.start_alert(
              1, n.svc.performer.AUTO_START_OFF, svc.REFUSED_START_ALERT)) and
          "Nothing was sent" in svc.REFUSED_START_ALERT and
          "dark" not in svc.REFUSED_START_ALERT,
          f"the alert says nothing was sent, not that the rig went dark: "
          f"{got}")
    check(got and got[-1][1].startswith("Show 1 did not start: auto_start "
                                        "is off") and
          "press Start now" in got[-1][1],
          f"and says why, with what to press (Jeff, 2026-10-28): {got}")
    _no_dashes(svc.REFUSED_START_ALERT, "the refused start alert")
    _no_dashes(svc.RUN_NOT_PRESSED, "the held back line")
    _no_dashes(S.NOTHING_SENT_TO_RIG, "the refused start journal line")
    c.close()
    n.link.close()
    print("  ok")


# -- Jeff's field report, 2026-10-28: Stop, Reset from Hold, and every
# refused start saying why ---------------------------------------------------

def _fi_show_cue(n):
    """The fake session given a show file with a show cue and an
    intermission cue, each with its own show audio role on the clock, as
    the real clock.audio.cues has them. Returns the clock."""
    import types as _ty
    n.sess.tl = _ty.SimpleNamespace(cues=[
        _ty.SimpleNamespace(name="Show", path="/x/show.fseq",
                            tc_text="00:00:00:00"),
        _ty.SimpleNamespace(name="Intermission", path="/x/int.fseq",
                            tc_text="01:00:00:00")])
    clk = n.sess.clock
    clk.cues = {"Show": ("show", 48000 * 60),
                "Intermission": ("intermission", 48000 * 60)}
    clk._loaded, clk._load_failed = set(), {}
    return clk


def test_refused_starts_say_why_and_what_to_press():
    section("Jeff's field report (2026-10-28), refusals: a show refused with "
            "Run off says so on its slot and in its alert, with what to "
            "press; Start now with Run off, or while the show audio loads, "
            "is refused at once in plain words (Loading, wait) and never "
            "becomes a FAULT slot; every reason says what to press")
    n = _fi_night(session=False, armed=False)
    if n.S is None:
        return
    S, svc, F = n.S, n.svc, n.F
    R = svc.performer
    got = []
    svc.alert_sink = lambda kind, text: got.append((kind, text))
    _fi_walk(n, 18, 1)
    s1 = [s for s in svc.machine.slots if s.n == 1]
    check(s1 and s1[0].status == S.FAULT and R.RUN_OFF in s1[0].reason and
          "Turn show control on, then Start now" in s1[0].reason,
          f"the slot's status on the rack screen names the reason and what "
          f"to press: {s1}")
    check(got and got[-1][0] == "start" and
          got[-1][1].startswith("Show 1 did not start: Show control is "
                                "off") and
          "Turn show control on, then Start now" in got[-1][1]
          and "Nothing was sent to the rig" in got[-1][1],
          f"the alert says why and what to press, never only that the show "
          f"did not start: {got[-1:]}")
    check(all(t != "The show did not start." and
              not t.startswith("The show did not start. ") for _k, t in got),
          f"no generic alert is left: {got}")
    # Start now with Run off: refused at once, with the reason.
    slots0 = len(svc.machine.slots)
    sv = svc.state_view()
    check(sv.get("start_blocked") == {"text": R.RUN_OFF, "loading": False},
          f"the status says what Start now would be refused with: "
          f"{sv.get('start_blocked')}")
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    check(r["ok"] is False and r["text"].startswith(
              "Start now was refused: Show control is off") and
          "Turn show control on, then Start now" in r["text"] and
          "Nothing was started" in r["text"],
          f"Start now with Run off says why at once: {r}")
    check(len(svc.machine.slots) == slots0,
          f"and adds no show and no FAULT: {len(svc.machine.slots)} "
          f"{slots0}")
    rows = [x for x in svc.journal if x.get("action") == "start-now" and
            x.get("outcome") == "refused"]
    check(rows and R.RUN_OFF.split(";")[0] in rows[-1]["text"],
          f"journaled as a refused press, with the reason: {rows[-1:]}")
    n.c.close()
    n.link.close()

    # Run pressed, the show audio still loading (Start now 4 s after Run):
    # Start now waits for it, a bounded time, and Stop, Hold or Abort ends
    # the wait (review of #144, F2). Only the show cue's own audio counts
    # (F3): a slow or broken intermission file never holds a start back.
    import threading as _th
    import types as _ty
    n = _fi_night(armed=False)
    S, svc = n.S, n.svc
    R = svc.performer
    clk = n.sess.clock
    n.sess.tl = _ty.SimpleNamespace(cues=[
        _ty.SimpleNamespace(name="Show", path="/x/show.fseq",
                            tc_text="00:00:00:00"),
        _ty.SimpleNamespace(name="Intermission", path="/x/int.fseq",
                            tc_text="01:00:00:00")])
    clk.cues = {"Show": ("show", 48000 * 60),
                "Intermission": ("intermission", 48000 * 60)}
    clk._live, clk._device_ok = True, True
    clk._loaded, clk._load_failed = set(), {}
    svc.START_WAIT_S = 0.6
    n.now[0] = _den(S, 17, 56)
    svc.tick()
    sb = svc.state_view().get("start_blocked")
    check(sb == {"text": R.AUDIO_LOADING, "loading": True},
          f"loading: the status says so, for the button's state: {sb}")
    slots0 = len(svc.machine.slots)
    t0 = time.monotonic()
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    took = time.monotonic() - t0
    check(r["ok"] is False and r.get("loading") is True and
          "still loading after 0.6 s" in r["text"] and took >= 0.5 and
          len(svc.machine.slots) == slots0,
          f"Start now while the audio never loads: waits its bounded time, "
          f"then refused saying so, no FAULT slot: {r} {took:.2f} s")
    # It loads while Start now waits: the show starts.
    svc.START_WAIT_S = 5.0
    seen = []

    def load_later():
        time.sleep(0.3)
        seen.append(svc.state_view().get("start_waiting"))
        clk._loaded = {"show"}
    th = _th.Thread(target=load_later)
    th.start()
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    th.join()
    check(seen == [True] and r["ok"] is True and
          svc.machine.state == S.SHOW,
          f"Start now waited for the audio and started the show once it "
          f"loaded (the status said it was waiting): {seen} {r} "
          f"{svc.machine.state}")
    check(not svc.start_waiting(), "and nothing waits any more")
    n.c.close()
    n.link.close()

    # Hold, and Stop, end the wait: nothing starts. "hold again": the
    # schedule already on Hold (Start now works from there), so the Hold
    # press is refused by the schedule and its own press must end the wait.
    for how in ("hold", "stop", "hold again"):
        n = _fi_night(armed=False)
        S, svc = n.S, n.svc
        clk = _fi_show_cue(n)
        clk._loaded = set()
        svc.START_WAIT_S = 5.0
        n.now[0] = _den(S, 17, 56)
        svc.tick()
        if how == "hold again":
            svc.operator_press("hold", "Andy", "Rack screen")
            check(svc.machine.state == S.HOLD, "setup: on Hold")

        def press_later(how=how, svc=svc):
            time.sleep(0.3)
            if how.startswith("hold"):
                svc.operator_press("hold", "Andy", "Rack screen")
            else:
                svc.cancel_start_wait("Stop was pressed on the Rack screen")
        th = _th.Thread(target=press_later)
        th.start()
        t0 = time.monotonic()
        r = svc.operator_press("start-now", "Andy", "Rack screen")
        took = time.monotonic() - t0
        th.join()
        clk._loaded = {"show"}
        svc.tick()
        check(r["ok"] is False and r.get("cancelled") is True and
              took < 2.0 and svc.machine.state != S.SHOW and
              not svc.machine.running,
              f"{how} while Start now waits: the wait ends at once and "
              f"nothing starts: {r} {took:.2f} s {svc.machine.state}")
        n.c.close()
        n.link.close()

    # The rack screen's (or an iPad's) Stop ends the wait too: Remote's
    # Stop is the complete halt, and it cancels a waiting Start now first.
    R2 = _RemoteRig(S)
    try:
        sv = R2.svc
        perf = _ty.SimpleNamespace(
            start_blocked=lambda: {"text": "the show audio is still loading",
                                   "loading": True},
            start_show=lambda n, who="", stops=None: None)
        sv.performer, sv.dry_run = perf, False
        sv.START_WAIT_S = 5.0

        def stop_later():
            time.sleep(0.3)
            R2.remote.stop_press("Rack screen", "Rack screen")
        th = _th.Thread(target=stop_later)
        th.start()
        t0 = time.monotonic()
        r = sv.operator_press("start-now", "Andy", "Rack screen")
        took = time.monotonic() - t0
        th.join()
        check(r["ok"] is False and r.get("cancelled") is True and
              "Stop was pressed" in r["text"] and took < 2.0 and
              not sv.machine.running,
              f"a screen's Stop while Start now waits: nothing starts: {r} "
              f"{took:.2f} s")
    finally:
        R2.close()

    # Re-review of #144, N1: ANY Hold that is taken ends the wait, the
    # announcement's and the engine's own at showtime included, not only an
    # operator's Hold press. N2: while a Stop's halt is under way, Start now
    # and Run are refused.
    for how in ("announcement", "engine"):
        n = _fi_night(armed=False)
        S, svc = n.S, n.svc
        clk = _fi_show_cue(n)
        svc.START_WAIT_S = 5.0
        n.now[0] = _den(S, 17, 56)
        svc.tick()

        def hold_later(how=how, svc=svc):
            time.sleep(0.3)
            if how == "announcement":
                svc.hold_for_announcement("Andy", "Rack screen")
            else:
                with svc._locked():
                    svc._apply(S.Event(S.HOLD_ON, "system",
                                       who="LTC Player", screen="engine",
                                       detail="held the schedule at "
                                              "showtime because an alert "
                                              "is open (test)"))
            time.sleep(0.3)
            clk._loaded = {"show"}
        th = _th.Thread(target=hold_later)
        th.start()
        r = svc.operator_press("start-now", "Andy", "Rack screen")
        th.join()
        check(r["ok"] is False and r.get("cancelled") is True and
              svc.machine.state == S.HOLD and not svc.machine.running,
              f"N1: the {how}'s Hold ends a waiting Start now; no show "
              f"starts over the Hold: {r} {svc.machine.state}")
        n.c.close()
        n.link.close()
    n = _fi_night(armed=False)
    S, svc = n.S, n.svc
    clk = _fi_show_cue(n)
    clk._loaded = {"show"}
    n.now[0] = _den(S, 17, 56)
    svc.tick()
    svc.halt_begin()
    try:
        r = svc.operator_press("start-now", "Andy", "Rack screen")
        check(r["ok"] is False and r.get("halting") is True and
              "a Stop is under way" in r["text"] and
              not svc.machine.running,
              f"N2: Start now during a Stop's halt is refused: {r}")
    finally:
        svc.halt_end()
    check(not svc.halting(), "and the halt is over after halt_end")
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    check(r["ok"] is True, f"after it, Start now works: {r}")
    n.c.close()
    n.link.close()
    # A Hold landing just as the wait ends (after the last look, before
    # the start is made) is caught again under the lock.
    R4 = _RemoteRig(S)
    try:
        sv = R4.svc
        calls = [0]

        def blocked_then_held():
            calls[0] += 1
            if calls[0] == 1:
                return {"text": "the show audio is still loading",
                        "loading": True}
            sv.cancel_start_wait("the schedule was put on Hold")
            return None
        sv.performer = _ty.SimpleNamespace(start_blocked=blocked_then_held,
                                           start_show=lambda n, who="", stops=None: None)
        sv.dry_run = False
        slots0 = len(sv.machine.slots)
        r = sv.operator_press("start-now", "Andy", "Rack screen")
        check(r["ok"] is False and r.get("cancelled") is True and
              "just before it started" in r["text"] and
              len(sv.machine.slots) == slots0,
              f"a Hold just as the wait ended: refused under the lock, "
              f"nothing started: {r}")
    finally:
        R4.close()
    # C1: the engine's alert Hold taken by the tick the start itself makes
    # (showtime arrives as the wait ends) cancels it too.
    import tempfile as _tf1
    work = _tf1.mkdtemp()
    now1 = [_den(S, 17, 59, 50)]
    sv = _svc(S, work, now1, rule=_sched_doc(
        weekly={"sat": {"first_start": "18:00", "interval_min": 20,
                        "last_end": "22:00"}}, exceptions={},
        late_grace_s=15))
    sv.tick()
    gate = [False]
    sv.showtime_gate = (lambda: ("an alert is open", frozenset({1}))
                        if gate[0] else None)
    calls = [0]

    def loads_at_showtime():
        calls[0] += 1
        if calls[0] == 1:
            return {"text": "the show audio is still loading",
                    "loading": True}
        now1[0] = _den(S, 18, 0)
        gate[0] = True
        return None
    sv.performer = _ty.SimpleNamespace(start_blocked=loads_at_showtime,
                                       start_show=lambda n, who="", stops=None: None)
    sv.dry_run = False
    r = sv.operator_press("start-now", "Andy", "Rack screen")
    check(r["ok"] is False and r.get("cancelled") is True and
          sv.machine.state == S.HOLD and not sv.machine.running,
          f"C1: the alert Hold the start's own tick takes cancels it; no "
          f"extra show over the Hold: {r} {sv.machine.state}")
    sv.stop()
    # N2 on the web side: Run is refused while a halt is under way.
    from ltcplay import web as _web
    _src = open(_web.__file__, encoding="utf-8").read()
    check('if getattr(_svc, "halting", lambda: False)() is True:' in _src
          and "return self._halt_stop(body, c)" in _src,
          "Run (/api/start) is refused during a halt, and the deck's halt "
          "counts as one")
    R3 = _RemoteRig(S)
    try:
        R3.svc.halt_begin()
        try:
            st, _h, out = R3.ask("POST", "/api/start", {"timeline": "x"},
                                 client=("127.0.0.1", 50000))
        finally:
            R3.svc.halt_end()
        check(st == 409 and "a Stop is under way" in str(out),
              f"Run during a Stop's halt: refused, saying why: {st} {out}")
    finally:
        R3.close()

    # The other refusals before the show cue's audio, said at once.
    n = _fi_night(armed=False)
    S, svc = n.S, n.svc
    R = svc.performer
    clk = _fi_show_cue(n)
    clk._live, clk._device_ok = True, True
    clk._loaded, clk._load_failed = {"show"}, {
        "intermission": "int.wav could not be read"}
    n.now[0] = _den(S, 17, 56)
    svc.tick()
    check(svc.state_view().get("start_blocked") is None,
          f"a broken intermission file never blocks the show (F3): "
          f"{svc.state_view().get('start_blocked')}")
    clk._load_failed = {}
    check(svc.state_view().get("start_blocked") is None,
          "nor does an intermission still loading")
    clk._load_failed = {"show": "show.wav could not be read"}
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    check(r["ok"] is False and "did not load" in r["text"] and
          "show.wav could not be read" in r["text"] and
          "turn show control off and on again" in r["text"],
          f"audio that failed to load: says which and what to press: {r}")
    clk._load_failed = {}
    clk._device_ok, clk._fault = False, "The interface was unplugged."
    r = svc.operator_press("start-now", "Andy", "Rack screen")
    check(r["ok"] is False and "interface is not available" in r["text"] and
          "unplugged" in r["text"],
          f"the audio interface missing: says so: {r}")
    clk._device_ok, clk._fault = True, None
    check(svc.state_view().get("start_blocked") is None,
          "loaded: nothing in the way")
    r = svc.operator_press("start-now", "Andy", "Rack screen",
                           confirmed=True)
    check(r["ok"] is True and svc.machine.state == S.SHOW,
          f"and Start now starts the show: {r} {svc.machine.state}")
    n.c.close()
    n.link.close()

    # A scheduled start while the audio loads: the alert says to wait.
    n = _fi_night(armed=False)
    S, svc = n.S, n.svc
    R = svc.performer
    got = []
    svc.alert_sink = lambda kind, text: got.append((kind, text))
    clk = _fi_show_cue(n)
    clk._loaded = set()
    _fi_walk(n, 18, 1)
    check(got and "still loading" in got[-1][1] and "wait" in got[-1][1] and
          got[-1][1].startswith("Show 1 did not start: "),
          f"a scheduled start refused while the audio loads: the alert says "
          f"to wait: {got[-1:]}")
    n.c.close()
    n.link.close()

    # Every reason the runner gives: plain words, what to press, no dash.
    for name in ("AUTO_START_OFF", "RUN_OFF", "NOT_AUDIO_MASTER",
                 "AUDIO_LOADING", "AUDIO_FAILED", "AUDIO_DEVICE",
                 "NEVER_CONFIRMED", "SHOW_START_ERROR"):
        text = getattr(R, name)
        _no_dashes(text, f"ShowRunner.{name}")
        # What to press: a button ("press ...") or the switch ("turn show
        # control on/off", Jeff 2026-11-11).
        check(("press" in text or "turn show control" in text.lower()) and
              not text.rstrip().endswith("."),
              f"ShowRunner.{name} says what to press and ends without a "
              f"full stop (it is wrapped in FAULT (...)): {text!r}")
    # F8: a failure reported too late to be a failed start (the show runs
    # on) raises no "did not start" alert.
    import tempfile as _tf
    now = [_den(S, 17, 59)]
    bare = _svc(S, _tf.mkdtemp(), now)
    raised = []
    bare.alert_sink = lambda kind, text: raised.append((kind, text))
    bare.tick()
    now[0] = _den(S, 18, 0)
    bare.tick()
    now[0] = _den(S, 18, 0, 40)
    bare._apply(S.Event(S.SHOW_FAILED, "madmapper", detail="no timecode"))
    check(bare.machine.state == S.SHOW and raised == [],
          f"a late failure: the show runs on and no did-not-start alert: "
          f"{bare.machine.state} {raised}")
    check("no reason was given" in svc.start_alert(3, "", "x") and
          svc.start_alert(3, "a. ", "Tail.") == "Show 3 did not start: a. "
                                                 "Tail.",
          "an alert with no reason still never reads as only did not start")
    for t in (svc.FAILED_START_ALERT, svc.REFUSED_START_ALERT):
        _no_dashes(t, "the start alert's tail")
    print("  ok")


def test_reset_says_how_the_rig_stands():
    section("Resume (Reset until 2026-10-30) says, in plain words, how "
            "every subsystem stands: audio, "
            "pixels, flame link, timecode, MadMapper (its heartbeat), "
            "BEYOND, lasers, announcements; anything unhealthy in capitals "
            "with what to do; in the answer and the journal (Jeff's field "
            "report, 2026-10-28)")
    import types
    from ltcplay import righealth as RH
    from ltcplay import madmapper as MM, madmapperwatch as MW
    lamps = [{"name": "Audio", "state": "ok", "word": "ok"},
             {"name": "Pixels", "state": "ok", "word": "sending"},
             {"name": "Lasers", "state": "ok", "word": "black"},
             {"name": "Laser arm", "state": "off", "word": "disarmed"}]
    fl = {"connected": True, "stale": False, "fault": "",
          "groups": [{"name": "Wave", "armed": "disarmed"},
                     {"name": "Gas", "armed": "disarmed"}]}
    clk = {"artnet": ["MadMapper 10.250.1.1"], "failing": [],
           "holding": "00:01:27:10", "held_to": ["MadMapper"]}
    mm = {"link": "up", "heartbeat": "quiet"}
    ann = {"configured": True, "ok": True, "device_set": True,
           "device_available": True,
           "items": [{"id": "a", "name": "Delayed", "available": True}]}
    text, items = RH.summary(lamps, clk, mm, {"link": "up"}, fl, ann)
    want = ("Audio ready. Pixels ready. Flame link OK, all groups disarmed. "
            "Timecode ready, holding 00:01:27:10 for MadMapper until the "
            "next show. MadMapper running: heartbeat not seen yet (it must "
            "follow once a show starts; Start now sets its show bank "
            "following timecode again). BEYOND running. Lasers black, "
            "laser arm disarmed. Announcements ready.")
    check(text == want, f"a healthy rig, said exactly:\n{text}\n{want}")
    check([i["name"] for i in items] == [
        "audio", "pixels", "flame link", "timecode", "MadMapper", "BEYOND",
        "lasers", "announcements"] and
          not any(i["ok"] is False for i in items),
          f"in the fixed order, nothing flagged: {items}")
    _no_dashes(text, "the healthy Reset summary")
    mm_ok = dict(mm, heartbeat="ok")
    check("MadMapper running, heartbeat OK." in
          RH.summary(lamps, clk, mm_ok, None, fl, None)[0],
          "a fresh heartbeat is said")
    # Unhealthy: each in capitals with what to do, then the list.
    bad_lamps = [{"name": "Audio", "state": "bad", "word": "lost"},
                 {"name": "Pixels", "state": "off", "word": "stopped"},
                 {"name": "Lasers", "state": "bad", "word": "LINK LOST"}]
    text, items = RH.summary(
        bad_lamps, dict(clk, failing=["MadMapper (10.250.1.1)"]),
        {"link": "lost"}, {"link": "lost"}, {"connected": False},
        dict(ann, items=[{"name": "Delayed", "available": False}]))
    for part in ("Audio NOT READY (lost): check the show audio interface, "
                 "then turn show control off and on.",
                 "Pixels NOT READY: show control is off. Turn it on.",
                 "Flame link NOT READY: flamesafe is not connected. Start "
                 "flamesafe.",
                 "Timecode NOT READY: MadMapper (10.250.1.1) is not taking "
                 "Art-Net timecode. Check the show network.",
                 "MadMapper NOT RUNNING: start MadMapper and its project.",
                 "BEYOND NOT RUNNING: start BEYOND and its show.",
                 "Lasers NOT READY: LINK LOST.",
                 "Announcements NOT READY: Delayed cannot play.",
                 "Needs attention: audio, pixels, flame link, timecode, "
                 "MadMapper, BEYOND, lasers, announcements."):
        check(part in text, f"said: {part!r} in {text!r}")
    _no_dashes(text, "the unhealthy Reset summary")
    armed = dict(fl, groups=[{"name": "Wave", "armed": "armed"},
                             {"name": "Gas", "armed": "disarmed"}])
    check("Flame link OK, 1 group armed: Wave." in
          RH.summary(lamps, clk, None, None, armed, None)[0],
          "an armed group is named")
    # Review of #161: never "holding for MadMapper" when nothing can take
    # the held frame (TimecodeOut.held_dests empty), nor when unknown.
    t, it = RH.summary(lamps, dict(clk, held_to=[]), None, None, fl, None)
    check("Timecode NOT HELD for MadMapper" in t and
          "holding" not in t and
          [i["ok"] for i in it if i["name"] == "timecode"] == [False],
          f"no MadMapper receiver: said, never 'holding': {t}")
    t, it = RH.summary(lamps, dict(clk, held_to=None), None, None, fl, None)
    check("Timecode ready." in t and "holding" not in t,
          f"where it goes not known: no holding claim: {t}")
    # A heartbeat listener that cannot listen is said, and flagged.
    t, it = RH.summary(lamps, clk, {"link": "up", "heartbeat": "silent",
                                    "heartbeat_why": "The MadMapper "
                                    "heartbeat could not listen on "
                                    "127.0.0.1:9001: in use"},
                       None, fl, None)
    check("heartbeat listener NOT WORKING (The MadMapper heartbeat could "
          "not listen on 127.0.0.1:9001: in use)" in t and
          "not seen yet" not in t and
          [i["ok"] for i in it if i["name"] == "MadMapper"] == [False],
          f"a broken heartbeat listener: {t}")
    # Lasers: a laser arm not known is flagged; "none" is not ready.
    t, it = RH.summary([{"name": "Lasers", "state": "ok", "word": "black"},
                        {"name": "Laser arm", "state": "bad",
                         "word": "not known"}], None, None, None, fl, None)
    check("Laser arm NOT READY: not known." in t and
          [i["ok"] for i in it if i["name"] == "lasers"] == [False],
          f"the laser arm not known: {t}")
    t, it = RH.summary([{"name": "Lasers", "state": "off", "word": "none"}],
                       None, None, None, fl, None)
    check([i["ok"] for i in it if i["name"] == "lasers"] == [None],
          f"lasers 'none' is not ready: {it}")
    # A flamesafe fault still names the armed groups.
    t, it = RH.summary(lamps, clk, None, None,
                       dict(armed, fault="arm input lost"), None)
    check("flamesafe reports a fault (arm input lost)" in t and
          "1 group armed: Wave." in t,
          f"a fault still names the armed groups: {t}")
    # The engine asks the running clock where a held frame can go.
    import tempfile
    from ltcplay import remote as RM
    dests = [[]]
    snap = {"running": True,
            "clock": {"artnet": ["MadMapper 10.0.0.1"], "failing": [],
                      "holding": "00:00:07:00"}}
    ctl = types.SimpleNamespace(
        state=lambda: snap,
        session=types.SimpleNamespace(clock=types.SimpleNamespace(
            out=types.SimpleNamespace(held_dests=lambda: dests[0]))))
    rm = RM.Remote(ctl, None, folder=tempfile.gettempdir())
    t = rm.rig_health()[0]
    check("Timecode NOT HELD for MadMapper" in t,
          f"the engine: nothing takes the held frame: {t}")
    dests[0] = [("MadMapper", "10.0.0.1")]
    t = rm.rig_health()[0]
    check("holding 00:00:07:00 for MadMapper" in t,
          f"the engine: MadMapper takes it: {t}")
    t2, it2 = RH.summary(lamps, clk, None, None, fl, None)
    check(not any(i["name"] in ("MadMapper", "BEYOND") for i in it2) and
          "BEYOND" not in t2 and
          "Announcements" not in t2,
          f"what this engine does not have is left out: {t2}")
    check(RH.summary(None, None, None, None, None, None)[0].startswith(
        "Audio:"), "nothing known: never raises")
    # Through the route: a Stop, then Resume (Reset is removed, Jeff,
    # 2026-10-30: the Resume after a Stop says how the rig stands).
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        _live_show(R)
        st, _h, out = R.ask("POST", "/api/remote/resume", {"seen": R.seen()})
        R.settle()
        check(st == 409 and "health" not in out,
              f"a refused Resume is answered as before: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/reset", {"seen": R.seen()})
        check(st == 404, f"there is no Reset route: {st} {out}")
        _stop_hold(R)
        cfg = MM.HeartbeatConfig(show_len_s=60.0)
        R.remote.madmapper_watch = MW.MadMapperWatch(lambda: True)
        R.remote.madmapper_watch.check_once()
        R.remote.madmapper_heartbeat = MM.Watchdog(cfg)
        R.remote.madmapper_heartbeat_cfg = cfg
        st, _h, out = R.ask("POST", "/api/remote/resume", {"seen": R.seen()})
        R.settle()
        txt = str(out.get("text"))
        check(st == 200 and
              "Audio" in txt and "Pixels" in txt and "Flame link" in txt
              and "Timecode" in txt and
              "MadMapper running: heartbeat not seen yet" in txt and
              isinstance(out.get("health"), list) and out["health"],
              f"Resume says how the rig stands: {st} {out}")
        _no_dashes(txt, "the Resume answer")
        rows = [r for r in R.svc.journal if r.get("action") == "resume"
                and r.get("outcome") == "rig state"]
        check(rows and "Timecode" in rows[-1].get("text", ""),
              f"and the journal says it: {rows[-1:]}")
    finally:
        R.close()
    print("  ok")


def test_rack_screen_stop_in_place_of_start_now():
    section("Jeff's field report (2026-10-28), Stop: while a show is live "
            "Start now becomes Stop in the same place (the Run button on the "
            "Programming screen too), one Stop per screen, wholly on screen "
            "and at least 44 px tall at the CI runner's page heights; it "
            "posts the Stream Deck's complete halt; Loading while the show "
            "audio loads")
    import shutil as _sh
    here = os.path.dirname(os.path.abspath(__file__))
    page = screen_text()
    logic = page[page.find("// LOGIC BEGIN"):page.find("// LOGIC END")]
    for f in ("function startLook", "function runLook", "function stopWords",
              "function refusedWords", "function pressDecision",
              "const STOP_TITLE", "function stopShows",
              "function stopTapStep", "function stopTapKind",
              "const RUN_OFF_CONFIRM"):
        check(f in logic, f"{f} is pure page logic")
    # Stop is a double tap with no confirm box (Jeff, 2026-10-30), with
    # exactly the Abort sign's tap rule.
    import re as _re
    _sp = _re.search(r"function stopTapStep\(prev, nowMs, kind, enlarged\)"
                     r"\{(.*?)\n\}", logic, _re.S)
    check(_sp is not None and "abortTapStep" not in logic and
          "const STOP_TAP_MS = 3000;" in logic,
          "Stop's double tap is its own rule now (the Abort sign's, which "
          "is gone), 3 s (the Windows stress test, 2026-11-09)")
    _no_dashes(page[page.find("const STOP_TITLE"):
                    page.find("function runLook")], "Stop's words")
    node = _sh.which("node")
    if node:
        js = logic + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const live = (state) => ({schedule:{attached:true, state:state}, show:{running:true}});
for(const s of ["SHOW", "PAUSED"]){
  const a = startLook(live(s), false, false);
  t(a.mode === "stop" && a.label === "Stop" && a.disabled === false, s + ": Start now is Stop: " + JSON.stringify(a));
  t(startLook(live(s), true, false).mode === "stop" && startLook(live(s), true, false).disabled === false, s + ": never held back by a stale page");
}
for(const s of ["IDLE", "STANDBY", "HOLD"]){
  const a = startLook({schedule:{attached:true, state:s}, show:{running:true}}, false, false);
  t(a.mode === "start" && a.label === "Start now" && !a.disabled, s + ": Start now: " + JSON.stringify(a));
}
t(startLook({schedule:{attached:false}, show:{running:true}}, false, false).mode === "stop", "no scheduler, Run playing: Stop");
t(startLook({schedule:{attached:false}, show:{running:false, starting:true}}, false, false).mode === "stop", "no scheduler, Run starting: Stop");
const ld = startLook({schedule:{attached:true, state:"STANDBY", start_blocked:{text:"the show audio is still loading", loading:true}}, show:{running:true}}, false, false);
t(ld.label === "Start now" && ld.disabled === false && ld.sub === "audio loading" && ld.why === "", "loading: Start now still works and waits: " + JSON.stringify(ld));
const wt = startLook({schedule:{attached:true, state:"STANDBY", start_waiting:true}, show:{running:true}}, false, false);
t(wt.mode === "stop" && wt.label === "Stop" && wt.disabled === false && /starting when ready/.test(wt.sub), "waiting for the audio: a show is about to play, so Stop, starting when ready: " + JSON.stringify(wt));
t(startLook({schedule:{attached:true, state:"STANDBY"}, show:{running:true}}, false, true).label === "Loading", "this page's own wait reads Loading");
// Stop's second line is the gesture, never a sentence (Jeff, 2026-11-11).
t(startLook({schedule:{attached:true, state:"SHOW"}, show:{running:true, show_control_on:true}}, false, false).sub === "tap twice" &&
  runLook({schedule:{attached:true, state:"SHOW"}, show:{running:true, show_control_on:true}}, false).sub === "tap twice", "a live show: Stop, tap twice");
const off = startLook({schedule:{attached:true, state:"STANDBY", start_blocked:{text:"Run has not been pressed, so nothing may reach the rig; press Run", loading:false}}, show:{running:false}}, false, false);
t(off.mode === "start" && off.sub === "Show control is off" && /^Run has not been pressed/.test(off.why), "Run off: says so, and the why: " + JSON.stringify(off));
// "Run is off" on Start now is the engine's boolean, never its sentence
// (show control, PR 1); anything but true is off, never on.
const blk = (text, on) => ({schedule:{attached:true, state:"STANDBY", start_blocked:{text:text, loading:false}}, show:{running:true, show_control_on:on}});
t(startLook(blk("Run has not been pressed, so nothing may reach the rig; press Run", true), false, false).sub === "not ready, tap for why", "the old sentence with the boolean on: not read, so not ready");
t(startLook(blk("the show audio interface is not available", true), false, false).sub === "not ready, tap for why", "Run on, blocked for another reason: not ready");
for(const v of [false, undefined, null, "true", 1]){
  const lk = startLook(blk("Fireball practice is on", v), false, false);
  t(lk.sub === "Show control is off" && lk.why === "Fireball practice is on", "the boolean " + JSON.stringify(v) + ": Show control is off, with the engine's own why: " + JSON.stringify(lk));
}
// Run becomes Stop while Run is in force and there is something to stop;
// with nothing to stop it is Run off (Stop no longer turns Run off).
const att = (st, show, extra) => Object.assign({schedule:{attached:true, state:st}, show:show}, extra || {});
t(runLook(att("SHOW", {running:true})).mode === "stop" && runLook(att("STANDBY", {running:false})).mode === "run" && runLook(null).label === "Show control on", "Run becomes Stop while a show is live");
// Its words (Jeff, 2026-11-11): Show control on/off; Programming's Run is
// a rehearsal (Start rehearsal, End rehearsal). The modes are the same.
t(runLook(att("STANDBY", {running:false}), false, "show").label === "Show control on" && runLook(att("STANDBY", {running:false}), false, "programming").label === "Start rehearsal" && runLook(att("STANDBY", {running:false}), false, "programming").mode === "run", "Run's words: Show control on, or Start rehearsal with Programming picked");
t(runLook(att("STANDBY", {running:true}, {transport:{programming:true}}), false, "show").label === "End rehearsal" && runLook(att("STANDBY", {running:true}, {transport:{programming:true}}), false, "show").mode === "runoff" && runLook(att("STANDBY", {running:true}), false, "programming").label === "Show control off", "Run off's words: End rehearsal while a rehearsal is in force, else Show control off");
t(runLook(att("STANDBY", {running:true})).mode === "runoff" && runLook(att("STANDBY", {running:true})).label === "Show control off", "Run in force, nothing to stop: Run off");
t(runLook(att("HOLD", {running:false, starting:true})).mode === "runoff", "Run starting with nothing to stop: Run off (F4 now)");
t(runLook({schedule:{attached:false}, show:{running:true}}).mode === "stop" && runLook({schedule:{attached:false}, show:{running:false, starting:true}}).mode === "stop", "no scheduler: Run playing or starting is the show, so Stop");
t(runLook(att("STANDBY", {running:true}, {transport:{programming:true, playhead:"show_audio", playing:true}})).mode === "stop", "Programming playback on: Stop");
// Where Stop is drawn (Jeff, 2026-10-30: if nothing is playing there is no
// Stop button).
t(stopShows(att("SHOW", {})) && stopShows(att("PAUSED", {})), "a show live or paused: Stop");
t(stopShows({schedule:{attached:true, state:"HOLD", lit:true}}) && !stopShows({schedule:{attached:true, state:"HOLD", lit:false}}), "the conductor has the rig up, whatever the scheduler says: Stop");
// A rehearsal Run with its timecode moving is playing (cold review of
// #191, B1); one whose timecode is not moving is not.
t(stopShows(att("STANDBY", {running:true, state:"LOCKED"}, {transport:{programming:true}})) && stopShows(att("STANDBY", {running:true, state:"FREERUN"}, {transport:{programming:true}})), "a rehearsal Run with timecode moving: Stop");
t(!stopShows(att("STANDBY", {running:true, state:"LOST"}, {transport:{programming:true}})) && !stopShows(att("STANDBY", {running:true, state:"STANDBY"}, {transport:{programming:true}})) && !stopShows(att("STANDBY", {running:true, state:"LOCKED"})), "no timecode moving, or not a rehearsal: no Stop");
// The Run card with no contact is Stop, as Start now is (B2).
t(runLook(att("STANDBY", {running:true}), true).mode === "stop" && runLook(att("STANDBY", {running:false}), true).mode === "stop" && runLook(att("STANDBY", {running:true}), false).mode === "runoff", "the Run card with no contact: Stop");
t(!stopShows(att("IDLE", {running:true})) && !stopShows(att("STANDBY", {running:true})) && !stopShows(att("HOLD", {running:true})) && !stopShows(att("CLOSING", {})) && !stopShows(null), "nothing playing: no Stop");
t(stopShows(att("STANDBY", {}, {preroll:{state:"checking"}})) && stopShows(att("STANDBY", {}, {preroll:{state:"queued"}})), "the rig check before a show: Stop");
t(stopShows({schedule:{attached:true, state:"STANDBY", start_waiting:true}}), "Start now waiting for the audio: Stop");
t(stopShows(att("STANDBY", {}, {transport:{programming:true, playhead:"show_audio", playing:true}})) && !stopShows(att("STANDBY", {}, {transport:{programming:true, playhead:"show_audio", playing:false}})), "Programming playback playing: Stop; stopped: none");
t(startLook(att("STANDBY", {running:true}, {transport:{programming:true, playhead:"show_audio", playing:true}}), false, false).mode === "stop", "Start now is Stop while Programming playback plays");
// The double tap (the removed Abort sign's rule).
t(stopTapStep(null, 1000, "touch", false).fire === false && stopTapStep({at:1000, kind:"touch"}, 3500, "touch", false).fire === true, "a second tap within 3 s fires");
t(stopTapStep({at:1000, kind:"touch"}, 4500, "touch", false).fire === false && stopTapStep({at:1000, kind:"touch"}, 4500, "touch", true).fire === true, "later only while still showing Tap again");
t(STOP_MISSED_WORDS === "Stop not sent: tap twice" && STOP_MISSED_MS === 2000, "a lone tap: the message line says Stop was not sent, for 2 s");
t(JSON.stringify(stopLines(null, false)) === '["Stop show","tap twice"]' && JSON.stringify(stopLines(2500, false)) === '["Tap again","to stop (3)"]' && JSON.stringify(stopLines(900, false)) === '["Tap again","to stop (1)"]' && JSON.stringify(stopLines(null, true)) === '["Not sent","tap twice"]', "Stop show's two lines");
t(stopLeftS(3000) === 3 && stopLeftS(2001) === 3 && stopLeftS(2000) === 2 && stopLeftS(10) === 1 && stopLeftS(-50) === 1, "the countdown: whole seconds left, never 0: " + stopLeftS(2000));
t(stopTapStep({at:1000, kind:"mouse"}, 1500, "touch", false).fire === false, "a different pointer kind is a first tap");
t(stopTapKind({pointerType:"pen"}) === "pen" && stopTapKind({detail:0}) === "key", "the tap's kind");
t(/^Stopped\. The show ended/.test(stopWords({stopped:true, show:{ok:true}, flames:{disarmed:true}, lasers:{disarmed:true}})) && /Show control is off/.test(stopWords({stopped:true, run_on:false})), "Run off's answer: the show ended, show control is off");
const held = stopWords({stopped:true, run_on:true, show:{ok:true}, hold:{ok:true, text:""}, flames:{disarmed:true}});
t(/^Stopped\. The show ended/.test(held) && /on Hold/.test(held) && /Resume/.test(held) && !/Show control is off/.test(held), "Stop's answer: the show ended, the schedule is on Hold, Run stays on: " + held);
t(/Show control is still on/.test(stopWords({stopped:true, run_on:true})), "a Stop with nothing to hold says show control is still on");
t(/did NOT work: show/.test(stopWords({stopped:true, failed:["show"], flames:{disarmed:true}})), "a failed step is named");
t(/did NOT work: playback stop/.test(stopWords({stopped:false, failed:["playback stop"]})), "a failed playback stop is named");
t(/^Stopped\. /.test(stopWords({stopped:false, failed:[]})), "nothing was playing: still Stopped, no false failure");
t(refusedWords({ok:false, text:"Start now was refused: Run has not been pressed"}, "Conflict") === "Start now was refused: Run has not been pressed", "a scheduler refusal's own words, never Conflict");
t(refusedWords({error:"x"}, "Conflict") === "x" && refusedWords({}, "Conflict") === "Conflict" && refusedWords(null, "") !== "", "error first, then the status text");
// F5: a press decided by what was seen at touch-down.
t(pressDecision("stop", "start", 0, 10000, false).act === "none", "seen Stop, now Start: nothing is done");
t(pressDecision("start", "stop", 0, 10000, false).act === "none", "seen Start, now Stop: nothing is done either");
t(pressDecision("start", "start", 9000, 10000, false).act === "none", "Start within 2 s of Stop turning into Start: nothing");
t(pressDecision("start", "start", 7000, 10000, false).act === "start", "after the lock: Start");
t(pressDecision("stop", "stop", 9500, 10000, false).act === "stop", "Stop is never locked");
t(pressDecision("start", "start", 0, 10000, true).act === "none", "a halt under way: nothing (F6)");
console.log(JSON.stringify(out));
"""
        r = _node_js(node, js, capture_output=True, text=True, timeout=60)
        try:
            bad = json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            bad = None
        check(r.returncode == 0 and bad == [],
              f"Start now and Stop, in node: {r.stdout[-1200:]!r} "
              f"{r.stderr[-400:]!r}")
    else:
        check(not IN_CI, "node is missing on this CI runner")
    print("  ok")


def test_schedule_failed_start_effects_follow_what_was_sent():
    section("scheduler engine: a failed start that sent nothing has no "
            "effects; one that went out and never confirmed still fades")
    S = _sched()
    if S is None:
        return
    import tempfile
    for nothing, want in ((True, set()),
                          (False, {S.ZERO_FLAME_CUES, S.BLANK_LASERS,
                                   S.FADE_VIDEO_OUT, S.FADE_PIXELS,
                                   S.FADE_MUSIC_OUT, S.STOP_CONDUCTOR})):
        work = tempfile.mkdtemp()
        now = [_den(S, 17, 59)]
        svc = _svc(S, work, now)
        svc.tick()
        now[0] = _den(S, 18, 0)
        svc.tick()
        check(svc.machine.state == S.SHOW, "setup: show 1 started")
        now[0] = _den(S, 18, 0, 5)
        out = S.step(svc.machine, S.Event(S.SHOW_FAILED, "system",
                                          detail="refused",
                                          nothing_sent=nothing), now[0])
        kinds = {e.kind for e in out.effects}
        check(kinds >= want and (not nothing or kinds == set()),
              f"nothing_sent={nothing}: effects {sorted(kinds)}")
        s1 = out.machine.slot(1)
        check(s1.status == S.FAULT and out.machine.state == S.STANDBY,
              f"nothing_sent={nothing}: show 1 FAULT, STANDBY: {s1} "
              f"{out.machine.state}")
        text = " ".join(le.text for le in out.log)
        check((S.NOTHING_SENT_TO_RIG in text) == nothing and
              ("faded to black" in text) == (not nothing),
              f"nothing_sent={nothing}: the journal says what happened: "
              f"{text}")
    print("  ok")


def test_soak_schedule_is_refused_outside_the_soak():
    section("soak kit: the schedule and Fire & Ice settings the soak writes "
            "are marked soak_only, and outside the soak's own engine both "
            "are refused in words, so a leftover cannot run unattended")
    S = _sched()
    if S is None:
        return
    import json
    import tempfile
    from ltcplay import benchhooks as BH, schedule_service as SV
    F = _fi_mod()
    work = tempfile.mkdtemp()
    rule = _sched_doc(weekly={"sat": {"first_start": "18:00",
                                      "interval_min": 15,
                                      "last_end": "22:00"}},
                      exceptions={})
    rule["soak_only"] = True
    path = os.path.join(work, SV.RULE_FILE)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(rule, fh)
    soak_env = {BH.SOAK_ENV: "4242"}
    try:
        SV.load_rule(path, env={}, ppid=4242)
        check(False, "a soak_only schedule loaded outside the soak")
    except S.RuleError as e:
        check(SV.SOAK_ONLY_REFUSED in str(e),
              f"outside the soak it is refused in words: {e}")
        _no_dashes(str(e), "the soak schedule refusal")
    check(SV.load_rule(path, env=soak_env, ppid=4242) is not None,
          "the soak's own engine (its parent is the soak) loads it")
    try:
        SV.load_rule(path, env={BH.SOAK_ENV: "4242"}, ppid=99)
        check(False, "a leftover soak mark in the environment was trusted")
    except S.RuleError as e:
        check(SV.SOAK_ONLY_REFUSED in str(e),
              f"a mark naming another process is not the soak: {e}")
    rule["soak_only"] = "yes"
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(rule, fh)
    try:
        SV.load_rule(path, env=soak_env, ppid=4242)
        check(False, "soak_only 'yes' was accepted")
    except S.RuleError as e:
        check("soak_only" in str(e), f"only true or false: {e}")
    del rule["soak_only"]
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(rule, fh)
    check(SV.load_rule(path, env={}, ppid=1) is not None,
          "a show's own schedule (no soak_only) loads anywhere")
    # The Service with a leftover soak schedule: no night, a fault line.
    rule["soak_only"] = True
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(rule, fh)
    now = [_den(S, 18, 0)]
    svc = SV.Service(path, clock=lambda: now[0], state_dir=work,
                     ntp_query=lambda: 0.0)
    svc.tick()
    check(svc.machine is None and SV.SOAK_ONLY_REFUSED in svc.error and
          any(r.get("fault") and SV.SOAK_ONLY_REFUSED in r["text"]
              for r in svc.journal),
          f"the engine schedules nothing from it and says so as a fault: "
          f"{svc.error}")
    # Fire & Ice settings.
    cfg = F.FireIceConfig.parse({"soak_only": True,
                                 "scheduler_performs": True})
    why = F.soak_refusal(cfg, env={}, ppid=1)
    check(cfg.soak_only is True and why and "soak" in why,
          f"soak_only Fire & Ice settings are refused outside the soak: "
          f"{why}")
    _no_dashes(why or "", "the soak Fire & Ice refusal")
    check(F.soak_refusal(cfg, env=soak_env, ppid=4242) is None,
          "and taken by the soak's own engine")
    check(F.soak_refusal(F.FireIceConfig.parse({"scheduler_performs": True}),
                         env={}, ppid=1) is None,
          "a show's own settings are never refused for this")
    try:
        F.FireIceConfig.parse({"soak_only": 1})
        check(False, "soak_only 1 was accepted")
    except F.FireIceConfigError as e:
        check("soak_only" in str(e), f"only true or false: {e}")
    # The soak kit writes the mark in both files.
    sp = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                      "packaging", "windows")
    sys.path.insert(0, sp)
    was = sys.dont_write_bytecode
    sys.dont_write_bytecode = True
    try:
        for m in ("soak", "ltcwin", "soak_apps", "soak_exercise",
                  "supervisor"):
            sys.modules.pop(m, None)
        import soak
        s = soak.Soak(60, None, folder=os.path.join(work, "run"))
        s.show_s = 60.0
        s.mode = "fallback"
        s.engine_fs_cfg = os.path.join(work, "fs.json")
        s.make_schedule()
        with open(s.rule_path, encoding="utf-8") as fh:
            r = json.load(fh)
        with open(os.path.join(s.sched_dir, F.CONFIG_FILE),
                  encoding="utf-8") as fh:
            fi = json.load(fh)
        check(r.get("soak_only") is True and fi.get("soak_only") is True,
              f"the soak's schedule and Fire & Ice settings carry soak_only "
              f"true: {r.get('soak_only')!r} {fi.get('soak_only')!r}")
        check(S.parse_rule(json.dumps(r)) is not None and
              F.FireIceConfig.parse(fi).soak_only is True,
              "and both still parse")
        # The rig check (PR #162) is OFF in the soak kit, said at the top
        # of its report; outside a soak kit 0 is refused.
        check(fi.get("preroll_s") == 0 and
              F.FireIceConfig.parse(fi).preroll_s == 0,
              f"the soak kit runs with the rig check off: "
              f"{fi.get('preroll_s')!r}")
        check(soak.PREROLL_LINE.startswith("Pre-roll check: OFF (soak kit")
              and "PREROLL_LINE," in __import__("inspect").getsource(
                  soak.Soak.report_lines),
              "and its report says so")
        _no_dashes(soak.PREROLL_LINE, "the soak's pre-roll line")
        try:
            F.FireIceConfig.parse(dict(fi, soak_only=False))
            check(False, "preroll_s 0 outside a soak kit was accepted")
        except F.FireIceConfigError:
            pass
    finally:
        sys.dont_write_bytecode = was
        if sp in sys.path:
            sys.path.remove(sp)
        for m in ("soak", "ltcwin", "soak_apps", "soak_exercise",
                  "supervisor"):
            sys.modules.pop(m, None)
    print("  ok")


def test_soak_runs_on_the_show_pc():
    section("the soak on the real show PC (2026-11-09, build bench-2026.11.08"
            "-459f83a): its show names only Art-Net receivers the engine "
            "accepts (one loopback, every other on an address of its own "
            "this PC has); a fault alert open a minute in refuses the run; "
            "--audio-device resolves to one exact output name; MadMapper's "
            "and BEYOND's addresses come from this PC's settings; Stop soak "
            "now ends the soak and its programs at once; nothing elevated")
    import subprocess as _sp
    import tempfile
    import types
    from ltcplay import artnodes as A
    from ltcplay import fire_ice as F
    sp = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                      "packaging", "windows")
    sys.path.insert(0, sp)
    was = sys.dont_write_bytecode
    sys.dont_write_bytecode = True
    work = tempfile.mkdtemp()
    names = ("soak", "ltcwin", "soak_apps", "soak_exercise", "supervisor")
    try:
        for m in names:
            sys.modules.pop(m, None)
        import soak
        import soak_apps
        # A. The old layouts were refused by the engine's own rule.
        check(A.collisions({"MadMapper": "127.0.0.1",
                            "BEYOND": "127.0.0.2"}) and
              A.collisions({"MadMapper": "127.0.0.1", "BEYOND": "127.0.0.2",
                            "Soak": "127.0.0.9"}),
              "the old soak layouts share the loopback: refused, rightly")
        here = {"10.250.1.1", "10.250.2.1"}

        def on_pc(ip):
            return ip in here
        cands = {"MadMapper": ["10.250.1.1"], "BEYOND": ["10.250.2.1"]}
        p = soak.plan_addresses("fallback", cands, on_pc)
        check(p["nodes"] == {"MadMapper": "127.0.0.1",
                             "BEYOND": "10.250.2.1"} and
              p["beyond_tc"] == "10.250.2.1" and p["blank"] == "timecode" and
              p["said"] == ("Art-Net receivers: this program as MadMapper "
                            "on 127.0.0.1 and as BEYOND on 10.250.2.1 (its "
                            "own address on this PC), one address each"),
              f"fallback with BEYOND's own address: {p}")
        check(A.collisions(p["nodes"]) == [] and
              A.not_here(p["nodes"], adapters=here | {"127.0.0.1"},
                         probe=lambda a: a in here or a == "127.0.0.1") == [],
              "and the engine accepts it: no shared address, all on this PC")
        p = soak.plan_addresses("fallback", {"BEYOND": ["10.250.2.1",
                                                        "127.0.0.2"]},
                                lambda ip: False)
        check(p["nodes"] == {"MadMapper": "127.0.0.1"} and
              p["beyond_tc"] is None and p["blank"] == "osc" and
              p["said"] == ("Art-Net receivers: this program as MadMapper "
                            "on 127.0.0.1 only. This PC has no address of "
                            "BEYOND's own (looked for: 10.250.2.1, "
                            "127.0.0.2), and a second receiver on the "
                            "loopback would be refused, so BEYOND's timecode "
                            "black zone is not timed and the lasers are "
                            "blanked by OSC in this run"),
              f"one loopback only: exactly one node: {p}")
        check(soak.plan_addresses("fallback", {"BEYOND": ["127.0.0.2"]},
                                  lambda ip: True)["nodes"] ==
              {"MadMapper": "127.0.0.1"},
              "a second loopback address is never a second receiver")
        p = soak.plan_addresses("all programs", cands, on_pc)
        check(p["nodes"] == {"MadMapper": "10.250.1.1",
                             "BEYOND": "10.250.2.1", "Soak": "127.0.0.1"} and
              p["mm"] == "10.250.1.1" and p["beyond"] == "10.250.2.1" and
              A.collisions(p["nodes"]) == [] and
              p["said"] == ("Art-Net receivers: MadMapper on 10.250.1.1, "
                            "BEYOND on 10.250.2.1 (their own addresses on "
                            "this PC, where their OSC commands go too), and "
                            "this program on 127.0.0.1, one address each"),
              f"all programs on their real addresses: {p}")
        want_no = ("All programs mode needs MadMapper and BEYOND each on an "
                   "address of its own on this PC (the ShowNet loopbacks "
                   "10.250.1.1 and 10.250.2.1, or what this PC's settings "
                   "name), but BEYOND has none here (looked for MadMapper: "
                   "10.250.1.1; BEYOND: 127.0.0.2). The soak's commands "
                   "would not reach the real programs. Run with --mode "
                   "fallback, where this program plays both.")
        try:
            soak.plan_addresses("all programs", {"MadMapper": ["10.250.1.1"],
                                                 "BEYOND": ["127.0.0.2"]},
                                on_pc)
            check(False, "all programs with BEYOND on the loopback was taken")
        except RuntimeError as e:
            check(str(e) == want_no, f"said plainly: {e}")
        real_apps = {k: dict(v) for k, v in soak_apps.APPS.items()}
        real_cands = soak.pc_show_addresses
        try:
            soak.pc_show_addresses = lambda settings=None: {
                "MadMapper": ["10.250.1.1"], "BEYOND": ["127.0.0.2"]}
            mode, p = soak.choose_addresses("all programs", "auto", {},
                                            on_pc=on_pc)
            check(mode == "fallback" and
                  p["said"].startswith(want_no + " So this run is in "
                                       "fallback mode. Art-Net receivers:"),
                  f"auto: fallback mode, said: {mode} {p['said'][:80]}")
            try:
                soak.choose_addresses("all programs", "all", {}, on_pc=on_pc)
                check(False, "--mode all was quietly changed")
            except RuntimeError as e:
                check(str(e) == want_no, f"--mode all refuses: {e}")
            soak.pc_show_addresses = lambda settings=None: dict(cands)
            mode, p = soak.choose_addresses("all programs", "auto", {},
                                            on_pc=on_pc)
            check(mode == "all programs" and
                  soak_apps.APPS["MadMapper"]["ip"] == "10.250.1.1" and
                  soak_apps.APPS["BEYOND"]["ip"] == "10.250.2.1",
                  f"D: MadMapper's and BEYOND's readiness checks look at "
                  f"their real addresses: {soak_apps.APPS}")
        finally:
            soak.pc_show_addresses = real_cands
            for k, v in real_apps.items():
                soak_apps.APPS[k].clear()
                soak_apps.APPS[k].update(v)
        # The PC's own settings, in order, then the ShowNet loopbacks.
        files = {
            os.path.join("S", "ltcplay_fire_ice.json"): {
                "madmapper": {"host": "10.250.1.7"},
                "beyond_timecode_ip": "10.250.2.7",
                "beyond": {"host": "10.250.2.8"}},
            os.path.join("F", "show.json"): {"cues": [], "clock": {
                "artnet": {"nodes": {"MadMapper 2": "10.250.1.9",
                                     "BEYOND": "10.250.2.7"}}}}}
        got = soak.pc_show_addresses(
            {"schedule": os.path.join("S", "ltcplay_schedule.json"),
             "show_folder": "F"},
            read_json=lambda pth: files.get(pth),
            listdir=lambda d: ["show.json", "notes.txt"])
        check(got == {"MadMapper": ["10.250.1.7", "10.250.1.9",
                                    "10.250.1.1"],
                      "BEYOND": ["10.250.2.7", "10.250.2.8",
                                 "10.250.2.1"]},
              f"the addresses this PC's settings name, then ShowNet's: {got}")
        # The soak's own schedule follows the plan: BEYOND's timecode to
        # BEYOND's own address, or OSC blanking with none.
        for plan, blank, tc in (
                (soak.plan_addresses("fallback", cands, on_pc), "timecode",
                 "10.250.2.1"),
                (soak.plan_addresses("fallback", {}, on_pc), "osc", None)):
            s = soak.Soak(60, None, folder=os.path.join(work, blank))
            s.show_s, s.mode, s.addrs = 60.0, "fallback", plan
            s.engine_fs_cfg = os.path.join(work, "fs.json")
            s.make_schedule()
            with open(os.path.join(s.sched_dir, F.CONFIG_FILE),
                      encoding="utf-8") as fh:
                fi = json.load(fh)
            check(fi.get("beyond_blank") == blank and
                  fi.get("beyond_timecode_ip") == tc and
                  F.FireIceConfig.parse(fi).beyond_blank == blank,
                  f"the soak's settings follow the plan: {blank} {tc} "
                  f"{fi.get('beyond_blank')} {fi.get('beyond_timecode_ip')}")
        # B. Preflight.
        alerts = [{"id": 3, "kind": "audio", "severity": "fault",
                   "text": "The show audio interface X is not attached."},
                  {"id": 4, "kind": "output", "severity": "fault",
                   "text": "MadMapper's video output is OFF: this PC has "
                           "only one display."},
                  {"id": 5, "kind": "aim", "severity": "warning",
                   "text": "a warning"}]
        refuse, expected = soak.preflight_verdict(alerts, False)
        check(refuse == [(3, "audio: The show audio interface X is not "
                             "attached."),
                         (4, "output: MadMapper's video output is OFF: this "
                             "PC has only one display.")] and expected == [],
              f"every fault alert refuses; a warning does not: {refuse}")
        check(soak.preflight_refusal(refuse) ==
              "Preflight REFUSED: the engine has 2 fault alert(s) open a "
              "minute after it started, and an open fault alert holds every "
              "scheduled show, so this run would play no show: audio: The "
              "show audio interface X is not attached. | output: "
              "MadMapper's video output is OFF: this PC has only one "
              "display.. The soak stopped its programs; nothing else was "
              "started. If this PC is muted and dark on purpose, start the "
              "soak again with --video-output-off-ok.",
              f"the refusal: {soak.preflight_refusal(refuse)!r}")
        refuse, expected = soak.preflight_verdict(alerts, True)
        check([i for i, _t in refuse] == [3] and
              [i for i, _t in expected] == [4],
              "with --video-output-off-ok the video output OFF is expected")
        s = soak.Soak(60, None, folder=os.path.join(work, "pre"))
        calls, lines = [], []
        real_note = soak.note
        soak.note = lines.append
        try:
            s.video_off_ok = True
            s.engine = lambda route, body=None, **k: (
                calls.append((route, body)) or
                ({"alerts": alerts[1:]} if body is None else {}))
            check(s.preflight(wait_s=0, sleep=lambda t: None) is True and
                  calls == [("/api/remote/status", None),
                            ("/api/remote/alert",
                             {"id": 4, "action": "acknowledge"})] and
                  "preflight: expected on a muted, dark PC "
                  "(--video-output-off-ok): output: MadMapper's video "
                  "output is OFF: this PC has only one display.. "
                  "Acknowledged, so it holds no show." in lines,
                  f"expected, printed and acknowledged: {calls} {lines}")
            s.engine = lambda route, body=None, **k: {"alerts": alerts}
            try:
                s.preflight(wait_s=0, sleep=lambda t: None)
                check(False, "a fault alert did not refuse the run")
            except RuntimeError as e:
                check(str(e).startswith("Preflight REFUSED: the engine has "
                                        "1 fault alert(s) open"),
                      f"a fault alert refuses the run: {e}")
            check(soak.PREFLIGHT_S == 60.0, "after a minute")
        finally:
            soak.note = real_note
        # C. One exact output name.
        outs = ["StudioLive Series III ASIO", "Speakers (Realtek(R) Audio)",
                "StudioLive Series III ASIO", "Focusrite USB ASIO",
                "Focusrite USB (Focusrite USB Audio)"]
        check(soak.resolve_audio_name("StudioLive", outs) ==
              ("StudioLive Series III ASIO",
               "show audio interface: 'StudioLive' is the output "
               "'StudioLive Series III ASIO', the exact name the engine "
               "opens"),
              "a part of a name matching one output: that exact name, said")
        check(soak.resolve_audio_name("Focusrite USB ASIO", outs)[0] ==
              "Focusrite USB ASIO", "an exact name is itself")
        for wanted, said in (
                ("Focusrite", "--audio-device 'Focusrite' matches 2 "
                              "outputs: Focusrite USB (Focusrite USB "
                              "Audio); Focusrite USB ASIO. Give the one "
                              "exact name the engine should open, for "
                              "example --audio-device \"Focusrite USB "
                              "(Focusrite USB Audio)\". Nothing was "
                              "started."),
                ("Scarlett", "--audio-device 'Scarlett' is not an output on "
                             "this PC. Outputs: Focusrite USB (Focusrite USB "
                             "Audio); Focusrite USB ASIO; Speakers "
                             "(Realtek(R) Audio); StudioLive Series III "
                             "ASIO. Nothing was started.")):
            try:
                soak.resolve_audio_name(wanted, outs)
                check(False, f"{wanted} was taken")
            except RuntimeError as e:
                check(str(e) == said, f"refused, said: {e}")
        # E. Stop soak now.
        ran = []
        folder = os.path.join(work, "soakdir")
        out = soak.stop_now(folder, run=lambda cmd, **k: (
            ran.append(cmd) or types.SimpleNamespace(returncode=0, stdout="",
                                                     stderr="")),
            windows=True)
        check(os.path.exists(os.path.join(folder, "STOP_NOW")) and
              os.path.exists(os.path.join(folder, "STOP_UNATTENDED")) and
              soak.stop_now_requested(folder) and
              ran == [["schtasks", "/Delete", "/TN",
                       "LTC Player unattended soak", "/F"]] and
              out == ["Stop soak now: the soak stops within a second, stops "
                      "its own engine, flamesafe and deck, and does not "
                      "start again at sign-in.",
                      "The task 'LTC Player unattended soak' was removed."],
              f"Stop soak now: {ran} {out}")
        check(soak.confirm_refusal(None, "STOP", "x") is None and
              soak.confirm_refusal("STOP", "STOP", "x") is None and
              soak.confirm_refusal("stop", "STOP", "Stop soak now") ==
              "REFUSED. Stop soak now needs --confirm STOP (it said "
              "'stop'). Nothing was changed.",
              "the confirmation words are exact")
        # The soak's own child that does not stop is ended.

        class _P:
            killed = False

            def poll(self):
                return None

            def send_signal(self, sig):
                pass

            def wait(self, t=None):
                if not self.killed:
                    raise _sp.TimeoutExpired("x", t)
                return 0

            def kill(self):
                self.killed = True
        s = soak.Soak(60, None, folder=os.path.join(work, "kill"))
        child = _P()
        s.procs = {"deck": {"p": child}}
        lines = []
        soak.note = lines.append
        try:
            check(s.stop_program("deck") is True and child.killed and
                  lines == ["deck did not stop within 20 s (Ctrl-Break "
                            "sent), so the soak ended it (its own child)"],
                  f"a child that does not stop is ended: {lines}")
        finally:
            soak.note = real_note
        reg = open(os.path.join(sp, "register_soak_task.ps1"),
                   encoding="utf-8").read()
        check("-RunLevel Limited" in reg and "RunLevel Highest" not in reg
              and "$StopNow" in reg and "--stop-now --confirm STOP" in reg and
              "--resolve-audio $AudioDevice" in reg,
              "the task runs as the signed-in user, not elevated; -StopNow; "
              "the audio name resolved by the soak program")
        start = open(os.path.join(os.path.dirname(os.path.abspath(
            __file__)), "tools", "stress", "soak", "Start 48h soak.ps1"),
            encoding="utf-8").read()
        check("[switch]$StopNow" in start and
              "--stop-now --confirm STOP" in start and
              "--resolve-audio $AudioDevice" in start and
              "if ($admin) {" in start,
              "the 48 h start script: -StopNow, the exact audio name, and "
              "it refuses an elevated PowerShell")
        iss = open(os.path.join(sp, "installer.iss"), encoding="utf-8").read()
        check('Name: "{group}\\Start soak (6 h)"; Filename: '
              '"{app}\\ltcplay-soak.exe"; Parameters: "--hours 6 --confirm '
              'DISCONNECTED";' in iss and
              'Name: "{group}\\Stop soak now"; Filename: '
              '"{app}\\ltcplay-soak.exe"; Parameters: "--stop-now --confirm '
              'STOP";' in iss,
              "F: Start soak (6 h) and Stop soak now, with their words")
        for t in (want_no, soak.preflight_refusal(refuse),
                  soak.plan_addresses("fallback", {}, on_pc)["said"]):
            _no_dashes(t, "the soak's new sentences")
    finally:
        sys.dont_write_bytecode = was
        if sp in sys.path:
            sys.path.remove(sp)
        for m in names:
            sys.modules.pop(m, None)
        import shutil
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_runner_reports_the_show():
    section("fire & ice: when the scheduler performs, a show ends when its "
            "audio does, a start without Run fails, closing completes, and "
            "a dry run never asks the performer for anything")
    n = _fi_night()
    if n.S is None:
        return
    S, svc, c = n.S, n.svc, n.c
    svc.tick()
    n.now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    n.sess.clock._last_frame = 5
    n.w.runner.poll()
    _settle(svc, c)
    # Past the show's length the clock no longer ends it: the audio does.
    n.now[0] = _den(S, 18, 10)
    svc.tick()
    check(svc.machine.state == S.SHOW,
          "performing: the show is not ended by the scheduler's clock")
    n.sess.clock.playing = False
    n.sess.clock.last_ended = "Show finished"
    n.w.runner.poll()
    _settle(svc, c)
    check(svc.machine.state == S.STANDBY,
          f"the show ends when its audio does: {svc.machine.state}")
    done = [s for s in svc.machine.slots if s.n == 1]
    check(done and done[0].status == S.DONE, f"show 1 DONE: {done}")
    # A cue that stops before its timecode ever moved did not start.
    n.now[0] = _den(S, 18, 20)
    svc.tick()
    _settle(svc, c)
    check(svc.machine.state == S.SHOW, "show 2 starts")
    n.sess.clock.playing = False
    n.w.runner.poll()
    _settle(svc, c)
    s2 = [s for s in svc.machine.slots if s.n == 2]
    check(svc.machine.state == S.STANDBY and s2 and s2[0].status == S.FAULT,
          f"a cue that never moved is a failed start, not an ended show: "
          f"{svc.machine.state} {s2}")
    # Run not pressed: the start fails, the conductor is never asked.
    n.control.session = None
    n.now[0] = _den(S, 18, 40)
    svc.tick()
    _settle(svc, c)
    rows = [r for r in svc.journal if r.get("action") == "automatic start"]
    check(rows and rows[-1]["outcome"] == "refused" and
          "Show control is off" in rows[-1]["text"],
          f"no Run: the start is refused in words: {rows[-1:]}")
    n.w.runner.poll()
    _settle(svc, c)
    s3 = [s for s in svc.machine.slots if s.n == 3]
    check(svc.machine.state == S.STANDBY and s3 and s3[0].status == S.FAULT,
          f"and reported as a failed start: {svc.machine.state} {s3}")
    # Closing: End night, then the runner closes and reports it done.
    n.control.session = n.sess
    out = svc._apply(_op(S, S.END_NIGHT, confirmed=True))
    _settle(svc, c)
    check(svc.machine.state == S.CLOSING,
          f"performing: closing waits for its report: {svc.machine.state}")
    rows = [r for r in svc.journal if r.get("action") == "BLACKOUT"]
    check(rows and "Not performed: nothing in this build" in rows[-1]["text"],
          f"an effect nothing performs says so, not 'dry run': {rows[-1:]}")
    n.w.runner.poll()
    _settle(svc, c)
    check(svc.machine.state == S.OFF, f"closing done: {svc.machine.state}")
    check(n.sess.player.override == "blackout", "pixels black at closing")
    c.close()
    n.link.close()
    # A dry run (the default): the performer is never attached or asked.
    d = _fi_night(performs=False)
    check(d.svc.dry_run is True and d.svc.performer is None and
          d.w.runner is None,
          "scheduler_performs false: still a dry run, no performer")
    d.svc.tick()
    d.now[0] = _den(S, 18, 0)
    d.svc.tick()
    check(not any(k == "music_play" for k, _a, _t in d.calls),
          "a dry run never starts the show audio")
    d.svc.report(S.SHOW_ENDED, "x", show=1)
    check(d.svc.machine.state == S.SHOW, "a report in a dry run is ignored")
    d.now[0] = _den(S, 18, 10)
    d.svc.tick()
    check(d.svc.machine.state != S.SHOW,
          "a dry run still ends the show on the scheduler's clock")
    d.c.close()
    d.link.close()
    print("  ok")


_FI_NETWORKS = """<?xml version="1.0" encoding="UTF-8"?>
<Networks computer="test">
  <Controller Id="1" Name="Pixels A" Type="Ethernet" IP="127.0.0.1" ActiveState="Active">
    <network NetworkType="ArtNET" ComPort="127.0.0.1" BaudRate="1" MaxChannels="510" Enabled="Yes" />
  </Controller>
  <Controller Id="2" Name="Flames" Type="Ethernet" IP="10.0.0.9" ActiveState="{state}">
    <network NetworkType="E131" ComPort="10.0.0.9" BaudRate="7" MaxChannels="512" Enabled="Yes" />
  </Controller>
</Networks>
"""


def _fi_flame_files(work, state="Inactive", port=None):
    """A flamesafe config (its example, on a free port) and a show folder
    whose xlights_networks.xml has an inactive "Flames" controller at
    channels 511 to 1022."""
    import json as _json
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "flamesafe", "flamesafe.example.json"),
              encoding="utf-8") as fh:
        doc = _json.load(fh)
    doc["link"]["listen_port"] = port or _free_udp_port()
    doc["groups"] = doc["groups"][:3]    # the deck's three arm keys
    fs = os.path.join(work, "flamesafe.json")
    with open(fs, "w", encoding="utf-8") as fh:
        _json.dump(doc, fh)
    show = os.path.join(work, "show")
    os.makedirs(show, exist_ok=True)
    with open(os.path.join(show, "xlights_networks.xml"), "w",
              encoding="utf-8") as fh:
        fh.write(_FI_NETWORKS.replace("{state}", state))
    return fs, show, doc


def _free_udp_port():
    import socket as _s
    k = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
    k.bind(("127.0.0.1", 0))
    p = k.getsockname()[1]
    k.close()
    return p


def test_fire_ice_active_flame_controller_refused():
    section("fire & ice: an Active flame controller is refused at serve and "
            "at Run, the pixel output never sends the flame controller, and "
            "no flame_controller is said at startup (PR #43 review, item 3)")
    import json as _json
    import shutil
    import tempfile
    F = _fi_mod()
    from ltcplay import web as web_mod
    from ltcplay.session import Session, SessionError
    work = tempfile.mkdtemp()
    try:
        fs, show, _doc = _fi_flame_files(work, state="Active")
        net = os.path.join(show, "xlights_networks.xml")
        folder = os.path.join(work, "folder")
        os.makedirs(folder)
        tlp = os.path.join(folder, "fi_timeline.json")
        with open(tlp, "w", encoding="utf-8") as fh:
            _json.dump({"name": "fi", "fps": 30, "show_dir": show,
                        "cues": [{"tc": "01:00:00:00", "fseq": "Show.fseq",
                                  "name": "Show"}]}, fh)
        with open(os.path.join(folder, "notes.json"), "w") as fh:
            fh.write("{}")

        def refused(fn):
            try:
                fn()
            except F.FlameControllerError as e:
                return str(e)
            return None
        check(refused(lambda: F.refuse_active_flame_controller(
            tlp, "Flames")) is not None,
            "an Active flame controller is refused")
        with open(net, "w", encoding="utf-8") as fh:
            fh.write(_FI_NETWORKS.replace(' ActiveState="{state}"', ""))
        why = refused(lambda: F.refuse_active_flame_controller(
            tlp, "Flames"))
        check(why is not None and "The flame controller 'Flames' is Active" in why,
              f"a flame controller with no ActiveState (xLights reads it as "
              f"Active) is refused as Active: {why}")
        with open(net, "w", encoding="utf-8") as fh:
            fh.write(_FI_NETWORKS.replace("{state}", "Inactive"))
        check(refused(lambda: F.refuse_active_flame_controller(
            tlp, "Flames")) is None, "an Inactive one is not")
        why = refused(lambda: F.refuse_active_flame_controller(
            tlp, "Nope"))
        check(why is not None and "exactly that spelling" in why,
              f"a controller that is not there is refused, saying so (fix "
              f"round 2, B): {why}")
        # ltc serve startup: every show file in the folder. (Its show file
        # sends no timecode, so its lasers are blanked by OSC here: by
        # timecode it would be refused, test_beyond_timecode_needs_one_
        # route_through_the_gate.)
        cfg = F.FireIceConfig(flame_controller="Flames", flamesafe_config=fs,
                              beyond_blank="osc")
        F.check_flame_controllers(folder, cfg)
        check(True, "serve starts with the flame controller Inactive")
        with open(net, "w", encoding="utf-8") as fh:
            fh.write(_FI_NETWORKS.replace("{state}", "Active"))
        try:
            F.check_flame_controllers(folder, cfg)
            check(False, "ltc serve must refuse an Active flame controller")
        except F.FireIceConfigError as e:
            check("fi_timeline.json" in str(e) and "Active" in str(e),
                  f"ltc serve refuses it, naming the show file: {e}")
        F.check_flame_controllers(folder, F.FireIceConfig())
        check(True, "no flame controller named: nothing to check at serve")

        # Run: attach() puts the check in front of every Session the page
        # opens, and the flame controller in exclude_controllers.
        n = _fi_night()
        if n.S is None:
            return
        control = web_mod.Control(folder, sd=FakeSD())
        made = []

        class Rec:
            def __init__(self, path, **kw):
                made.append(kw)
                raise SessionError("stub: not opened here")
        lines = []

        def journal(text, **f):
            lines.append((text, f.get("fault", False)))
        F.attach(n.svc, control, cfg, journal=journal,
                 flame_link=_FiFlames(n.calls, n.T), threaded=False,
                 clock=n.T.now, waiter=n.T.wait)
        check(control.defaults.get("exclude_controllers") == ("Flames",),
              f"the page's sessions leave the flame controller out: "
              f"{control.defaults}")
        real = web_mod.Session
        web_mod.Session = Rec
        try:
            try:
                control.start("fi_timeline.json", no_output=True,
                              auto_reload=False)
                check(False, "Run must refuse an Active flame controller")
            except SessionError as e:
                check("will not start" in str(e) and "Active" in str(e)
                      and not made,
                      f"Run refuses it before anything opens: {e}")
            with open(net, "w", encoding="utf-8") as fh:
                fh.write(_FI_NETWORKS.replace("{state}", "Inactive"))
            try:
                control.start("fi_timeline.json", no_output=True,
                              auto_reload=False)
            except SessionError as e:
                check("stub" in str(e), f"Inactive: Run goes on: {e}")
            check(made and made[-1].get("exclude_controllers") ==
                  ("Flames",),
                  "and the session it opens leaves the flame controller "
                  "out of the pixel output")
            check(("10.0.0.9", 7, "e131") in
                  (made[-1].get("exclude_destinations") or ()),
                  f"and the flame node's address and universe too (fix "
                  f"round 2, B): {made[-1].get('exclude_destinations')}")
        finally:
            web_mod.Session = real
        check(not any(f and "flame" in t.lower() for t, f in lines),
              f"a named flame controller: no flame fault at startup: "
              f"{[t for t, f in lines if f]}")

        # No flame_controller with a flamesafe config: said at startup.
        n2 = _fi_night()
        lines2 = []
        c2 = web_mod.Control(folder, sd=FakeSD())
        F.attach(n2.svc, c2, F.FireIceConfig(flamesafe_config=fs, beyond_blank="osc"),
                 journal=lambda t, **f: lines2.append((t, f.get("fault"))),
                 flame_link=_FiFlames(n2.calls, n2.T), threaded=False,
                 clock=n2.T.now, waiter=n2.T.wait)
        check(any(f and "no flame cue is ever sent" in t for t, f in lines2),
              f"no flame_controller named: a startup fault says no flame "
              f"cue is ever sent: {lines2}")
        # Its only open check is the lasers' "blanking not set up" note
        # (beyond_blank "osc" with no BEYOND), which excludes nothing.
        check((getattr(c2, "before_open", None) is None or
               c2.before_open("show1.json") == {}) and
              "exclude_controllers" not in c2.defaults,
              "and nothing else changes")

        # The session itself: an Active flame controller in the map is not
        # in the pixel output's universes when it is excluded.
        with open(net, "w", encoding="utf-8") as fh:
            fh.write(_FI_NETWORKS.replace("{state}", "Active"))
        for excl in ((), ("Flames",)):
            sess = Session(tlp, no_output=True, no_log=True, sd=FakeSD(),
                           device="MOTU M4", channel=1,
                           exclude_controllers=excl)
            try:
                sess.open()
            except SessionError:
                pass
            ctl = sorted({u.controller for u in sess.nm.universes})
            if excl:
                check(ctl == ["Pixels A"] and any(
                    "Flames" in x and "pixel output" in x
                    for x in sess.notes),
                    f"excluded: the pixel output's map has no flame "
                    f"controller, and a note says so: {ctl} {sess.notes}")
            else:
                check(ctl == ["Flames", "Pixels A"],
                      f"the GPL path is unchanged: {ctl}")
    finally:
        shutil.rmtree(work, ignore_errors=True)


