def test_fire_ice_flame_cues_follow_a_changed_layout():
    section("fire & ice: the flame cues find the flame controller again for "
            "every session and whenever xlights_networks.xml changes, reopen "
            "a re-rendered FSEQ, refuse a render that does not match the "
            "layout, and refuse two cues with the playing name (fix round 2, "
            "A; R2-H9, R2-H11)")
    import shutil
    import tempfile
    import types
    import test_show_fixtures as _fx
    F = _fi_mod()
    work = tempfile.mkdtemp()
    lines = []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    try:
        show = os.path.join(work, "show")
        os.makedirs(show)
        net = os.path.join(show, "xlights_networks.xml")

        def layout(extra=""):
            with open(net, "w", encoding="utf-8") as fh:
                fh.write(_FI2_NETWORKS.format(extra=extra, name="Flames",
                                              state="Inactive", after=""))
        render = os.path.join(show, "Show.fseq")

        def rerender(channels, fill):
            _fx.write_fseq(render, frame_count=400, channel_count=channels,
                           step_ms=25, compression="zlib", block_frames=100,
                           fill=fill)
            st = os.stat(render)
            os.utime(render, ns=(st.st_atime_ns, st.st_mtime_ns + 10**9))
        layout()
        rerender(1022, 50)

        def session():
            clk = types.SimpleNamespace(
                source="audio_master", paused=False,
                _cue={"label": "Show", "position_s": 0.0},
                last_sent=(0, 0, 2, 15))
            player = types.SimpleNamespace(override=None, freerun_epoch=None)
            cue = types.SimpleNamespace(name="Show", path=render)
            return types.SimpleNamespace(
                running=True, clock=clk, player=player,
                tl=types.SimpleNamespace(show_dir=show, cues=[cue]))
        control = types.SimpleNamespace(session=session())
        cues = F.FlameCues(control, "Flames", journal)
        check(cues("00:00:02:15") == [50] * 512 and cues._span == (511, 512),
              f"setup: flame channels 511 to 1022: {cues._span}")
        # R2-H9: the same layout re-rendered: the new render is read.
        rerender(1022, 60)
        check(cues("00:00:02:15") == [60] * 512,
              "a re-rendered FSEQ is reopened, not read from the old one")
        # A: a 512-channel controller inserted before Flames with serve
        # running, and the show not yet rendered again: refused.
        layout(_fi2_ctl("Pixels B", "Active"))
        got = cues("00:00:02:15")
        check(got is None and cues._span == (1023, 512) and any(
            "render has 1022 channels but" in t for t, _f in lines),
            f"a layout changed under a running serve: the channels are found "
            f"again (1023), and a render made for the old layout is refused: "
            f"{cues._span} {got and got[:2]}")
        rerender(1534, 70)
        check(cues("00:00:02:15") == [70] * 512,
              "rendered again for the new layout: the cues come back")
        # A new session (Stop, then Run) always looks again.
        layout()
        rerender(1022, 80)
        control.session = session()
        check(cues("00:00:02:15") == [80] * 512 and cues._span == (511, 512),
              f"a new session finds the channels again: {cues._span}")
        # R2-H11: two cues with the name the show audio is playing.
        control.session.tl.cues = [
            types.SimpleNamespace(name="Show", path=render),
            types.SimpleNamespace(name="Show", path=render)]
        check(cues("00:00:02:15") is None,
              "two cues with the playing name: which render is meant cannot "
              "be told, so zeros")
        cues.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def _fi_cue_rig(work, total_after=True):
    """A show folder with layout A (Pixels A 1-510, Flames 511-1022,
    Pixels B 1023-1534), a FlameCues on a fake running session, and
    helpers: layout(order) rewrites xlights_networks.xml ("A", or "B" with
    Pixels B before Flames, the same 1534 channels), rerender(channels,
    fill) writes the render newer than the layout."""
    import types
    import test_show_fixtures as _fx
    show = os.path.join(work, "show")
    os.makedirs(show, exist_ok=True)
    net = os.path.join(show, "xlights_networks.xml")
    render = os.path.join(show, "Show.fseq")

    def layout(order="A"):
        pix = _fi2_ctl("Pixels B", "Active")
        with open(net, "w", encoding="utf-8") as fh:
            fh.write(_FI2_NETWORKS.format(
                extra=pix if order == "B" else "", name="Flames",
                state="Inactive", after="" if order == "B" else pix))

    def rerender(channels, fill, frames=400, step_ms=25):
        _fx.write_fseq(render, frame_count=frames, channel_count=channels,
                       step_ms=step_ms, compression="zlib", block_frames=100,
                       fill=fill)
        lay = os.stat(net).st_mtime_ns
        os.utime(render, ns=(lay, max(lay, os.stat(render).st_mtime_ns)
                             + 10 ** 9))
    clk = types.SimpleNamespace(source="audio_master", paused=False,
                                _cue={"label": "Show", "position_s": 0.0},
                                last_sent=(0, 0, 2, 15))
    player = types.SimpleNamespace(override=None, freerun_epoch=None)
    cue = types.SimpleNamespace(name="Show", path=render)
    sess = types.SimpleNamespace(running=True, clock=clk, player=player,
                                 tl=types.SimpleNamespace(show_dir=show,
                                                          cues=[cue]))
    return types.SimpleNamespace(show=show, net=net, render=render,
                                 layout=layout, rerender=rerender, clk=clk,
                                 control=types.SimpleNamespace(session=sess))


def test_fire_ice_flame_cues_refuse_a_render_older_than_the_layout():
    section("fire & ice: a layout changed with the same channel total moves "
            "the flames; a render older than xlights_networks.xml, or made "
            "when the flame controller started at another channel, is "
            "refused as a fault, never read as flames (review of PR #43, "
            "P0-6)")
    import shutil
    import tempfile
    F = _fi_mod()
    work = tempfile.mkdtemp()
    try:
        for bg in (False, True):
            lines = []
            rig = _fi_cue_rig(os.path.join(work, f"bg{bg}"))
            rig.layout("A")
            rig.rerender(1534, 50)
            cues = F.FlameCues(rig.control, "Flames",
                               lambda text, **f: lines.append(
                                   (text, f.get("fault", False))),
                               background=bg)
            if bg:
                cues._stop.set()          # no thread: refreshed by hand

            def ask():
                if bg:
                    cues._refresh_once()
                return cues("00:00:02:15")
            mode = "background" if bg else "in the call"
            check(ask() == [50] * 512 and cues.fault == "",
                  f"{mode}: setup: the flames from channel 511")
            # The same 1534 channels, the flames now at 1023: the render
            # still has the right count, so only its age can tell.
            rig.layout("B")
            r = os.stat(rig.render).st_mtime_ns
            os.utime(rig.net, ns=(r + 10 ** 9, r + 10 ** 9))
            got = ask()
            check(got is None and "older than xlights_networks.xml" in
                  cues.fault and any(f and "older than" in t
                                     for t, f in lines),
                  f"{mode}: a render older than the layout is refused, as a "
                  f"fault: {got and got[:2]} {cues.fault!r}")
            # The layout file made to look older than the render (copied
            # with its old date): the start channel the render was checked
            # at still tells.
            r = os.stat(rig.render).st_mtime_ns
            os.utime(rig.net, ns=(r - 10 ** 9, r - 10 ** 9))
            got = ask()
            check(got is None and "at channel 511 when this render was "
                                  "checked" in cues.fault,
                  f"{mode}: a render checked when the flames started at 511 "
                  f"is refused now they start at 1023: {cues.fault!r}")
            check("\u2014" not in cues.fault and "\u2013" not in cues.fault,
                  "no dashes")
            rig.rerender(1534, 70)
            check(ask() == [70] * 512 and cues.fault == "",
                  f"{mode}: rendered again for this layout: the cues come "
                  f"back and the fault clears: {cues.fault!r}")
            cues.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cues_a_tiny_overrun_is_zero_and_no_fault():
    section("fire & ice (2026-10-24): a render 20 ms shorter than its audio "
            "raised 'Flame cues are zero, a fault' at the end of every show. "
            "Past the render's last frame the flame output stays ZERO, "
            "always; the FAULT allows two frames of the render's step time; "
            "beyond that it is still a fault")
    import shutil
    import tempfile
    F = _fi_mod()
    check(F.RENDER_END_TOLERANCE_FRAMES == 2,
          f"the tolerance is two frames: {F.RENDER_END_TOLERANCE_FRAMES}")
    work = tempfile.mkdtemp()
    try:
        for bg in (False, True):
            lines = []
            rig = _fi_cue_rig(os.path.join(work, f"bg{bg}"))
            rig.layout("A")
            cues = F.FlameCues(rig.control, "Flames",
                               lambda text, **f: lines.append(
                                   (text, f.get("fault", False))),
                               background=bg)
            if bg:
                cues._stop.set()          # no thread: refreshed by hand
            mode = "background" if bg else "in the call"

            def at(frames, step, fill=50):
                # The timecode is 00:00:02:15, 2500 ms into the cue.
                rig.rerender(1534, fill, frames=frames, step_ms=step)
                if bg:
                    cues._refresh_once()
                n = len(lines)
                got = cues("00:00:02:15")
                return got, cues.fault, lines[n:]
            # Inside the render: the frame, as before.
            got, fault, _l = at(101, 25)
            check(got == [50] * 512 and fault == "",
                  f"{mode}: the last frame inside the render is read: "
                  f"{got and got[:2]} {fault!r}")
            # (step ms, frames, overrun ms): each within two frames. The
            # Pico's case: 20 ms short at a 20 ms step (444.40 s against
            # 444.42 s); 0 ms past (the first frame after the last); one
            # frame; exactly two frames.
            for step, frames, over in ((20, 124, 20), (25, 100, 0),
                                       (25, 99, 25), (25, 98, 50),
                                       (20, 123, 40)):
                got, fault, said = at(frames, step, fill=77)
                check(frames * step + over == 2500, "the case is what it says")
                check(got is None, f"{mode}: {over} ms past a {step} ms "
                                   f"render: the output is ZERO, never the "
                                   f"last frame held: {got and got[:2]}")
                check(fault == "", f"{mode}: {over} ms past a {step} ms "
                                   f"render: no fault: {fault!r}")
                check(not any(f for _t, f in said),
                      f"{mode}: {over} ms past: nothing journaled as a "
                      f"fault: {said}")
            # The rack screen and the Stream Deck read cues.fault: empty.
            check(cues.faults_now() == "",
                  f"{mode}: no CUES FAULT for the screens: "
                  f"{cues.faults_now()!r}")
            # Beyond two frames: still the fault, still zero.
            for step, frames, over in ((25, 97, 75), (20, 122, 60),
                                       (25, 40, 1500)):
                got, fault, said = at(frames, step, fill=77)
                check(frames * step + over == 2500, "the case is what it says")
                # Journaled once per episode: the first time the reason
                # changes to this one.
                check(got is None and "past the end of the show's render"
                      in fault and (over != 75 or any(
                          f and "past the end" in t for t, f in said)),
                      f"{mode}: {over} ms past a {step} ms render: zero and "
                      f"a fault, journaled: {got and got[:2]} {fault!r} "
                      f"{said}")
            # Past the render because the show deliberately runs longer
            # than its lights file ('clock.zones.show_len_s', the video):
            # zero, said, never a FAULT (safety review of #157, 4); past
            # that configured end it is the fault again.
            import types
            # A render simply shorter than its audio, with no configured
            # show length, is still the FAULT (review of #157): nothing else
            # warns of a stale or cut-short render.
            rig.clk.show_lengths = lambda label: (
                {"audio_s": 4.0, "show_s": 4.0} if label == "Show" else None)
            rig.clk.cfg = types.SimpleNamespace(
                zones=types.SimpleNamespace(show_len_s=None))
            got, fault, said = at(40, 25, fill=77)
            check(got is None and "past the end of the show's render" in
                  fault, f"{mode}: a render shorter than its audio, no "
                         f"show_len_s: the FAULT went quiet: {fault!r}")
            # A show_len_s set, but the audio is what runs past the render:
            # still the FAULT.
            rig.clk.cfg.zones.show_len_s = 3.0
            got, fault, said = at(40, 25, fill=77)
            check(got is None and "past the end of the show's render" in
                  fault, f"{mode}: the audio, not show_len_s, runs past the "
                         f"render: the FAULT went quiet: {fault!r}")
            rig.clk.show_lengths = lambda label: (
                {"audio_s": 1.0, "show_s": 4.0} if label == "Show" else None)
            # Longer than both, but no show_len_s says so: the FAULT.
            rig.clk.cfg.zones.show_len_s = None
            got, fault, said = at(40, 25, fill=77)
            check(got is None and "past the end of the show's render" in
                  fault, f"{mode}: no show_len_s set, yet the tail read as "
                         f"deliberate: {fault!r}")
            rig.clk.cfg.zones.show_len_s = 4.0
            got, fault, said = at(40, 25, fill=77)
            check(got is None and fault == "" and
                  not any(f for _t, f in said) and
                  "runs on to its configured length" in cues._why,
                  f"{mode}: a deliberate tail past the lights file read as "
                  f"a fault: {fault!r} {said} {cues._why!r}")
            rig.clk.show_lengths = lambda label: (
                {"audio_s": 1.0, "show_s": 2.0} if label == "Show" else None)
            got, fault, said = at(40, 25, fill=77)
            check(got is None and "past the end of the show's render" in
                  fault, f"{mode}: past the configured end too: still the "
                         f"fault: {fault!r}")
            del rig.clk.show_lengths
            del rig.clk.cfg
            # Within tolerance again after a fault: the fault clears, the
            # output stays zero.
            got, fault, _l = at(99, 25, fill=77)
            check(got is None and fault == "",
                  f"{mode}: back within two frames: zero, the fault "
                  f"cleared: {fault!r}")
            check(not any("\u2014" in t or "\u2013" in t for t, _f in lines),
                  "no dashes in what is journaled")
            cues.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cue_refusals_are_faults_on_the_screens():
    section("fire & ice: flame cues refused because the render does not fit "
            "the layout, runs out, or cannot be read are faults: journaled "
            "as faults, on /api/conductor, on the rack screen and on the "
            "Stream Deck (review of PR #43, P1-3)")
    import shutil
    import tempfile
    import types
    F = _fi_mod()
    from ltcplay import streamdeck as sd
    work = tempfile.mkdtemp()
    try:
        lines = []
        rig = _fi_cue_rig(work)
        rig.layout("A")
        rig.rerender(1534, 50)
        cues = F.FlameCues(rig.control, "Flames",
                           lambda text, **f: lines.append(
                               (text, f.get("fault", False))))
        check(cues("00:00:02:15") == [50] * 512 and cues.fault == "",
              "setup: cues out, no fault")
        rig.rerender(1022, 50)
        check(cues("00:00:02:15") is None and
              "render has 1022 channels but" in cues.fault and
              lines[-1][1], f"a render that does not fit the layout: a "
                            f"fault: {cues.fault!r} {lines[-1:]}")
        rig.rerender(1534, 50, frames=40)
        check(cues("00:00:02:15") is None and
              "past the end" in cues.fault and lines[-1][1],
              f"a timecode past the render's end: a fault: {cues.fault!r}")
        rig.rerender(1534, 50)
        size = os.path.getsize(rig.render)
        with open(rig.render, "r+b") as fh:
            fh.truncate(size // 3)
        st = os.stat(rig.render)
        os.utime(rig.render, ns=(st.st_atime_ns, st.st_mtime_ns + 10 ** 9))
        check(cues("00:00:02:15") is None and
              "could not be read" in cues.fault and lines[-1][1],
              f"a render that cannot be read: a fault: {cues.fault!r}")
        rig.clk.paused = True
        check(cues("00:00:02:15") is None and cues.fault == "",
              "a paused show is zero without a fault")
        rig.clk.paused = False
        rig.rerender(1022, 50)
        cues("00:00:02:15")
        why = cues.fault
        # /api/conductor (what the Stream Deck reads) and the rack screen.
        S = _sched()
        if S is not None:
            R = _RemoteRig(S)
            try:
                R.httpd.conductor = R.c
                R.httpd.fire_ice = types.SimpleNamespace(
                    flame_link=types.SimpleNamespace(
                        snapshot=lambda: {}, cues=cues), devices=None)
                R.remote.flame_cues = cues
                st, _h, out = _ask(R.httpd, "GET", "/api/conductor",
                                   client=("127.0.0.1", 5000))
                check(st == 200 and out.get("flame_cues", {}).get(
                    "fault") == why,
                    f"/api/conductor carries the fault: {st} {out}")
                st, _h, out = R.ask("GET", "/api/remote/status")
                check(st == 200 and out["flames"]["cues_fault"] == why,
                      f"the rack screen's status carries it: "
                      f"{out.get('flames')}")
            finally:
                R.close()
        page = screen_text()
        check("if(fl.cues_fault) items.push(" in page and
              "full:fl.cues_fault" in page, "the rack screen shows it")
        # The deck: read from /api/conductor, drawn on its own key.
        e = sd.EngineConductor(
            "http://127.0.0.1:1", poster=lambda p, b: (True, "ok"),
            fetcher=lambda path: {"conductor": {"latched": False,
                                                "look": ""},
                                  "flame_cues": {"fault": why}},
            poll_hz=50.0)
        e.start()
        try:
            deadline = time.time() + 2
            while not e.cues_fault and time.time() < deadline:
                time.sleep(0.01)
            check(e.cues_fault == why, f"the deck reads it: {e.cues_fault!r}")
            have_pil = not _pillow_missing("the deck's CUES FAULT key")
            if have_pil:
                fonts = sd.Fonts()
                fonts.text_block = lambda *a, **kw: None
                c2 = sd.Controller(_FakeArmSocket(3), _FakeStatusSocket(),
                                   ["front row", "cat-walk", "wave flamer"],
                                   operator_provider=lambda: "Andy",
                                   show_running_provider=lambda: True,
                                   conductor=e, clock=lambda: 100.0)
                e._last_ok = None
                e._threads = []           # not "unreachable": just this
                canvas = c2.draw(fonts, blink_on=True, chase=0)
                box = sd.face_box(sd.TOP_START)
                px = {canvas.getpixel((x, y))
                      for x in range(box[0], box[2], 3)
                      for y in range(box[1], box[3], 3)}
                check(sd.RED in px, "the deck shows CUES FAULT on its "
                                    "Start key")
        finally:
            e.stop()
        cues.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_node_address_never_in_the_pixel_output():
    section("fire & ice: a renamed, miscased, doubled or missing flame "
            "controller is refused at serve and at Run, and so is any Active "
            "controller sending to the flame node's address and universe or "
            "flamesafe's destination; the pixel map leaves them out by "
            "address as well as by name (fix round 2, B)")
    import json as _json
    import shutil
    import tempfile
    F = _fi_mod()
    from ltcplay.session import Session, SessionError
    work = tempfile.mkdtemp()
    try:
        fs, show, doc = _fi_flame_files(work)
        net = os.path.join(show, "xlights_networks.xml")
        folder = os.path.join(work, "folder")
        os.makedirs(folder)
        tlp = os.path.join(folder, "fi_timeline.json")
        with open(tlp, "w", encoding="utf-8") as fh:
            _json.dump({"name": "fi", "fps": 30, "show_dir": show,
                        "cues": [{"tc": "01:00:00:00", "fseq": "Show.fseq",
                                  "name": "Show"}]}, fh)
        fs_dest = F.flamesafe_destination(fs)
        check(fs_dest == (doc["destination"]["ip"], doc["universe"], "e131"),
              f"flamesafe's destination is read from its own config: "
              f"{fs_dest}")

        def write(name="Flames", state="Inactive", extra="", after=""):
            with open(net, "w", encoding="utf-8") as fh:
                fh.write(_FI2_NETWORKS.format(extra=extra, name=name,
                                              state=state, after=after))

        def why(cfg_name="Flames"):
            try:
                F.refuse_active_flame_controller(tlp, cfg_name, fs_dest)
            except F.FlameControllerError as e:
                return str(e)
            return None
        write()
        check(why() is None, "setup: Inactive and alone: not refused")
        cases = [
            ("renamed in xLights", dict(name="Flame Node", state="Active"),
             "Flames", "exactly that spelling"),
            ("a different case", dict(name="Flames", state="Active"),
             "flames", "There is one called 'Flames'"),
            ("two called Flames", dict(after=_fi2_ctl("Flames", "Inactive",
                                                     "10.0.0.10", 8, "E131")),
             "Flames", "2 controllers are called"),
            ("a second Active controller at the flame node's address",
             dict(after=_fi2_ctl("Flames spare", "Active", "10.0.0.9", 7,
                                 "E131")),
             "Flames", "the flame node's own address"),
            ("an Active controller at flamesafe's destination",
             dict(after=_fi2_ctl("Rogue", "Active", fs_dest[0], fs_dest[1],
                                 "E131")),
             "Flames", "the flame node's own address"),
        ]
        cfg = F.FireIceConfig(flame_controller="Flames", flamesafe_config=fs,
                              beyond_blank="osc")
        for label, kw, cfg_name, must in cases:
            write(**kw)
            w = why(cfg_name)
            check(w is not None and must in w,
                  f"{label}: refused at Run, saying why: {w}")
            try:
                F.check_flame_controllers(
                    folder, F.FireIceConfig(flame_controller=cfg_name,
                                            flamesafe_config=fs))
                check(False, f"{label}: ltc serve must refuse it")
            except F.FireIceConfigError as e:
                check(must in str(e), f"{label}: refused at serve: {e}")
        # Same address and universe on Art-Net is another universe space:
        # not the flame node.
        write(after=_fi2_ctl("Art-Net 7", "Active", "10.0.0.9", 7, "ArtNET"))
        check(why() is None, "an Art-Net universe of the same number is not "
                             "the flame node's sACN universe")
        # The pixel map leaves the flame node out by address too.
        write(after=_fi2_ctl("Flames spare", "Active", "10.0.0.9", 7, "E131"))
        for dests in ((), (("10.0.0.9", 7, "e131"),)):
            sess = Session(tlp, no_output=True, no_log=True, sd=FakeSD(),
                           device="MOTU M4", channel=1,
                           exclude_controllers=("Flames",),
                           exclude_destinations=dests)
            try:
                sess.open()
            except SessionError:
                pass
            ctl = sorted({u.controller for u in sess.nm.universes})
            want = (["Pixels A"] if dests else ["Flames spare", "Pixels A"])
            check(ctl == want, f"exclude_destinations={dests}: the pixel "
                               f"map is {ctl}")
        # Run: attach()'s check hands the session the addresses to leave out.
        write()
        n = _fi_night()
        from ltcplay import web as web_mod
        control = web_mod.Control(folder, sd=FakeSD())
        F.attach(n.svc, control, cfg, flame_link=_FiFlames(n.calls, n.T),
                 threaded=False, clock=n.T.now, waiter=n.T.wait)
        extra = control.before_open(tlp)
        check(set(extra["exclude_destinations"]) ==
              {("10.0.0.9", 7, "e131"), fs_dest},
              f"Run leaves out the flame node's address and flamesafe's: "
              f"{extra}")
        n.c.close()
        n.link.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cues_never_touch_the_disk_on_the_sender():
    section("fire & ice: in ltc serve the flame cues read the layout and the "
            "render (whole, into memory) on a thread of their own; the "
            "flame link's sender never opens or looks at a file, so a "
            "stalled drive cannot hold up a flame frame (show PC SSD "
            "stalls, 2026-09-25)")
    import builtins
    import shutil
    import tempfile
    import threading
    import types
    import test_show_fixtures as _fx
    F = _fi_mod()
    work = tempfile.mkdtemp()
    real_open, real_stat = builtins.open, os.stat
    on_caller = []
    me = threading.current_thread()
    # The background reader is held at its first file call until the first
    # cues() below has answered. Without this the test raced the reader: on
    # a fast runner the new thread read the layout and the whole 400 frame
    # render before cues() got back to look at it, and "zeros until the
    # background read is done" failed with the cues already there (PR #43
    # shard 31, PR #46 shard 5, PR #49 shard 25: the baseline, with nothing
    # mutated). The gate makes the first answer a real "still reading"
    # answer every time; what the test proves is unchanged.
    gate = threading.Event()

    def spy_open(*a, **k):
        if threading.current_thread() is me:
            on_caller.append(("open", a[0] if a else None))
        else:
            gate.wait(5.0)
        return real_open(*a, **k)

    def spy_stat(*a, **k):
        if threading.current_thread() is me:
            on_caller.append(("stat", a[0] if a else None))
        else:
            gate.wait(5.0)
        return real_stat(*a, **k)
    try:
        show = os.path.join(work, "show")
        os.makedirs(show)
        with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
            fh.write(_FI2_NETWORKS.format(extra="", name="Flames",
                                          state="Inactive", after=""))
        render = os.path.join(show, "Show.fseq")
        _fx.write_fseq(render, frame_count=400, channel_count=1022,
                       step_ms=25, compression="zlib", block_frames=100,
                       fill=40)
        clk = types.SimpleNamespace(source="audio_master", paused=False,
                                    _cue={"label": "Show", "position_s": 0.0},
                                    last_sent=(0, 0, 2, 15))
        sess = types.SimpleNamespace(
            running=True, clock=clk,
            player=types.SimpleNamespace(override=None, freerun_epoch=None),
            tl=types.SimpleNamespace(show_dir=show, cues=[
                types.SimpleNamespace(name="Show", path=render)]))
        cues = F.FlameCues(types.SimpleNamespace(session=sess), "Flames",
                           background=True)
        builtins.open, os.stat = spy_open, spy_stat
        first = cues("00:00:02:15")
        gate.set()
        got = None
        for _ in range(100):
            got = cues("00:00:02:15")
            if got:
                break
            time.sleep(0.02)
        builtins.open, os.stat = real_open, real_stat
        check(first is None and got == [40] * 512,
              f"zeros until the background read is done, then the cues: "
              f"{first} {got and got[:2]}")
        check(not on_caller, f"the caller (the flame link's sender) never "
                             f"opened or looked at a file: {on_caller[:3]}")
        cues.close()
    finally:
        gate.set()
        builtins.open, os.stat = real_open, real_stat
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def _fi_cut_show(work, ncues=1, frames=300, sparse=True, corrupt_block=None,
                  compression="zlib", cut_tail_frames=0):
    """A show folder for the cut-ahead tests: Pixels A 1-510, Flames
    511-1022; `ncues` renders of `frames` frames (zlib, 37 frames a
    block), each frame its own byte ((i * 7 + 3) & 255), sparse by default
    (part of the pixels, then flame channels 601 to 800 only). Optionally
    one block of the first render corrupted. Returns (control, clock,
    [render paths])."""
    import types
    import test_show_fixtures as _fx
    show = os.path.join(work, "show")
    os.makedirs(show, exist_ok=True)
    with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
        fh.write(_FI2_NETWORKS.format(extra="", name="Flames",
                                      state="Inactive", after=""))
    paths, cues = [], []
    for k in range(ncues):
        p = os.path.join(show, f"c{k}.fseq")
        _fx.write_fseq(p, frame_count=frames, step_ms=25,
                       compression=compression, block_frames=37,
                       **({"sparse_ranges": [(0, 100), (600, 200)]}
                          if sparse else {"channel_count": 1022}),
                       fill=lambda i: (i * 7 + 3) & 0xFF)
        paths.append(p)
        cues.append(types.SimpleNamespace(name=f"c{k}", path=p))
    if cut_tail_frames:
        # A render whose last frames are missing (cut short on disk).
        from ltcplay import fseq as FS
        f = FS.FSEQ(paths[0])
        cc = f.channel_count
        f.close()
        with open(paths[0], "r+b") as fh:
            fh.seek(0, 2)
            fh.truncate(fh.tell() - cut_tail_frames * cc - cc // 2)
    if corrupt_block is not None:
        from ltcplay import fseq as FS
        f = FS.FSEQ(paths[0])
        _first, off, length = f._blocks[corrupt_block]
        f.close()
        with open(paths[0], "r+b") as fh:
            fh.seek(off + length // 2)
            fh.write(b"\x00\xff" * 8)
    clk = types.SimpleNamespace(source="audio_master", paused=False,
                                _cue={"label": "c0", "position_s": 0.0},
                                last_sent=(0, 0, 0, 0))
    sess = types.SimpleNamespace(
        running=True, clock=clk,
        player=types.SimpleNamespace(override=None, freerun_epoch=None),
        tl=types.SimpleNamespace(show_dir=show, cues=cues))
    return types.SimpleNamespace(session=sess), clk, paths


def _fi_at(clk, n, label=None):
    """The show clock at frame n (30 a second) of cue `label`."""
    s, f = divmod(n, 30)
    m, s = divmod(s, 60)
    clk.last_sent = (0, m, s, f)
    if label is not None:
        clk._cue = {"label": label, "position_s": 0.0}
    return f"00:{m:02d}:{s:02d}:{f:02d}"


def _fi_settled(bg, tc):
    """bg(tc) once its CUT_FAULT_AFTER_S grace is over (a fake clock): what
    a frame that stays uncut finally says."""
    mono = [5000.0]
    bg._mono = lambda: mono[0]
    bg(tc)
    mono[0] += 2.0
    got = bg(tc)
    import time as _t
    bg._mono = _t.monotonic
    return got


def test_fire_ice_flame_cues_cut_ahead_match_and_never_decompress():
    section("fire & ice (2026-10-29): in serve's background mode the flame "
            "channels are cut from the render block by block on the reading "
            "thread, ahead of the show timecode, equal to the direct read "
            "frame by frame (a sparse render too); the sender never "
            "decompresses a block; a cut of another render or span is "
            "never used; a block not cut yet is a CUES FAULT, never a "
            "silent zero")
    import shutil
    import tempfile
    import threading
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()
    real_load = FS.FSEQ._load_block
    asking = threading.Event()
    on_ask = []

    def spy_load(self, idx):
        if asking.is_set():
            on_ask.append(idx)
        return real_load(self, idx)
    try:
        ctl, clk, paths = _fi_cut_show(work)
        direct = F.FlameCues(ctl, "Flames")
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()                    # no thread: driven by hand
        bg._check_renders_once()
        bg._refresh_once()
        FS.FSEQ._load_block = spy_load
        bad = []
        for n in range(0, 7 * 30 + 15):          # 7.5 s: every frame
            tc = _fi_at(clk, n)
            bg._cut_ahead()                       # the reading thread
            asking.set()
            a = bg(tc)
            asking.clear()
            b = direct(tc)
            if a != b:
                bad.append((tc, a and a[100:102], b and b[100:102]))
        FS.FSEQ._load_block = real_load
        check(not bad, f"cut ahead equals the direct read every frame: "
                       f"{bad[:3]}")
        check(not on_ask, f"asking (the sender) decompressed no block: "
                          f"{on_ask[:5]}")
        want = [0] * 512
        idx = int((3 + 10 / 30.0) * 1000.0 // 25)
        want[90:290] = [(idx * 7 + 3) & 0xFF] * 200
        check(bg(_fi_at(clk, 100)) == want,
              "flame channels 601 to 800 carry the frame, the rest zero")
        cut = bg._cuts[paths[0]]
        # A cut for another span, or of another FSEQ: never used, a fault.
        other = F._FlameCut.__new__(F._FlameCut)
        other.__dict__.update(cut.__dict__)
        other.span = (cut.span[0] + 1, cut.span[1])
        bg._cuts = {paths[0]: other}
        check(_fi_settled(bg, _fi_at(clk, 100)) is None and
              bg.fault == F.CUES_LOADING,
              f"a cut for another span: zero and a CUES FAULT: {bg.fault!r}")
        other.span = cut.span
        other.f = FS.FSEQ(paths[0])
        check(_fi_settled(bg, _fi_at(clk, 100)) is None and
              bg.fault == F.CUES_LOADING,
              "a cut of another FSEQ of the same render: never used")
        other.f.close()
        bg._cuts = {paths[0]: cut}
        check(bg(_fi_at(clk, 100)) == want and bg.fault == "",
              "its own cut again: the cues")
        # Not cut yet while the show plays: zero, a CUES FAULT only once it
        # has stayed so for CUT_FAULT_AFTER_S (no journal line, no blink, for
        # a move that is cut in time), then the cues once it is cut.
        far = 290 * 30 // 40
        check(cut._block(289) in cut.blocks, "the far block was cut ahead")
        cut.blocks.pop(cut._block(289), None)     # as if not cut yet
        mono = [1000.0]
        bg._mono = lambda: mono[0]
        lines = []
        bg._journal = lambda t, **k: lines.append((t, k))
        got = bg(_fi_at(clk, far))
        check(got is None and bg.fault == "" and not lines,
              f"a block not cut yet: zero, no fault and no line at first: "
              f"{bg.fault!r} {lines}")
        mono[0] += F.CUT_FAULT_AFTER_S - 0.1
        check(bg(_fi_at(clk, far)) is None and bg.fault == "",
              "still inside the grace: no fault")
        mono[0] += 0.2
        got = bg(_fi_at(clk, far))
        check(got is None and bg.fault == F.CUES_LOADING and
              len([1 for _t, k in lines if k.get("fault")]) == 1,
              f"still not cut after {F.CUT_FAULT_AFTER_S} s: a CUES FAULT, "
              f"never a silent zero: {bg.fault!r}")
        # A cutting thread that could not be started again: the fault at
        # once, and it says the cues will not follow.
        bg._start_failed.add("_cutter")
        mono[0] += 5
        check(bg(_fi_at(clk, far)) is None and
              bg.fault == F.CUES_CUTTER_DEAD and
              "restart LTC Player" in bg.fault,
              f"the cutter gone: the fault says so: {bg.fault!r}")
        bg._start_failed.clear()
        bg._cut_ahead()
        check(bg(_fi_at(clk, far)) == direct(_fi_at(clk, far)) and
              bg.fault == "", "cut by the next pass: the cues")
        bg.close()
        direct.close()
    finally:
        FS.FSEQ._load_block = real_load
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_guards():
    section("fire & ice (2026-10-29): the cut-ahead guards: a render whose "
            "bytes are another's is never cut; a cut of bytes with another "
            "frame or channel count is refused; the renders are published "
            "only after their cut starts; a block that cannot be cut is a "
            "CUES FAULT with its error, tried once; a many-cue show has "
            "every cue's start ready at once")
    import shutil
    import tempfile
    import test_show_fixtures as _fx
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()
    try:
        # A render whose bytes in memory belong to another render: never
        # cut from them.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "a"))
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        bg._check_renders_once()
        bg._refresh_once()
        f = bg._cuts[paths[0]].f
        alt = os.path.join(work, "alt.fseq")
        _fx.write_fseq(alt, frame_count=300, step_ms=25, compression="zlib",
                       block_frames=37, sparse_ranges=[(0, 100), (600, 200)],
                       fill=lambda i: 0xAA)
        with open(alt, "rb") as fh:
            alt_data = fh.read()
        bg._data[paths[0]] = (FS.FSEQ(alt), alt_data)
        bg._cuts = {}
        bg._refresh_once()
        got = _fi_settled(bg, _fi_at(clk, 10))
        check(paths[0] not in bg._cuts and got is None and
              bg.fault == F.CUES_LOADING,
              f"bytes that are another render's: not cut, a CUES FAULT, "
              f"never their values: {got and got[90:92]}")
        bg.close()
        # Bytes with another frame or channel count: refused.
        short = os.path.join(work, "short.fseq")
        _fx.write_fseq(short, frame_count=200, step_ms=25,
                       compression="zlib", block_frames=37,
                       sparse_ranges=[(0, 100), (600, 200)])
        with open(short, "rb") as fh:
            sdata = fh.read()
        try:
            F._FlameCut(paths[0], f, [(0, 0, 100),
                                       (600, 100, 200)],
                        (511, 512), sdata)
            check(False, "a cut of bytes with another frame count was made")
        except ValueError as e:
            check("changed" in str(e), f"refused: {e}")
        # Published in order: a render in _by_path always has its cut,
        # with its start already cut.
        seen = []

        class Spy(F.FlameCues):
            def __setattr__(self, k, v):
                if k == "_by_path" and v:
                    seen.append(all(
                        p in self._cuts and 0 in self._cuts[p].blocks
                        for p in v))
                super().__setattr__(k, v)
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "m"), ncues=12,
                                       frames=2000, sparse=False)
        sp = Spy(ctl, "Flames", background=True)
        sp._stop.set()
        sp._check_renders_once()
        t0 = time.perf_counter()
        sp._refresh_once()
        took = time.perf_counter() - t0
        check(seen == [True], f"the cuts are published before the renders, "
                              f"their start cut: {seen}")
        ok = []
        for k in range(12):
            got = sp(_fi_at(clk, 5, label=f"c{k}"))
            ok.append(bool(got) and sp.fault == "")
        check(all(ok), f"12 cues of 2000 frames: every cue's start ready "
                       f"after one pass ({took:.2f} s): {ok}")
        nb = [len(sp._cuts[p].blocks) for p in paths]
        check(all(n <= 4 for n in nb[1:]) and nb[0] < len(
            sp._cuts[paths[0]].firsts),
              f"only each cue's start is cut (the playing one ahead of its "
              f"timecode), never whole renders: {nb}")
        sp.close()
        # A block that cannot be cut: the frames before it as they are, then
        # a CUES FAULT with the render's own error, the block tried once.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "c"),
                                       corrupt_block=4)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        bg._check_renders_once()
        tried = []
        real_cut = F._FlameCut._cut_block

        def spy_cut(self, b):
            tried.append(b)
            return real_cut(self, b)
        F._FlameCut._cut_block = spy_cut
        try:
            bg._refresh_once()
            before = bg(_fi_at(clk, int(36 * 25 / 33.34)))
            n4 = 37 * 4 * 30 // 40 + 1
            for _ in range(6):
                _fi_at(clk, n4)
                bg._cut_ahead()
                bg._refresh_once()
            got = bg(_fi_at(clk, n4))
        finally:
            F._FlameCut._cut_block = real_cut
        check(before is not None and got is None and
              bg.fault.startswith("the show's render could not be read"),
              f"before the bad block the cues, at it a CUES FAULT with its "
              f"error: {bg.fault!r}")
        check(tried.count(4) == 1, f"the bad block was tried once: "
                                   f"{tried.count(4)}")
        bg.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_followups_of_174():
    section("fire & ice (review of #174): the cutting has a thread of its "
            "own, so a stalled read cannot starve the playing cue; a thread "
            "that dies is started again and journaled; an uncompressed "
            "render is cut in pieces straight from memory, never copied "
            "whole, and one missing its tail plays every frame it has; a "
            "compressed block's channel data is not kept")
    import shutil
    import tempfile
    import threading
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()
    try:
        # A stalled reading thread: the cutting thread still cuts ahead.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "s"), frames=1200)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg.start()
        for _ in range(250):
            if bg(_fi_at(clk, 5)):
                break
            time.sleep(0.02)
        stalled, release = threading.Event(), threading.Event()
        real_check = bg._check_renders_once

        def stuck():
            if threading.current_thread().name == "ltcplay-flame-cues-read":
                stalled.set()
                release.wait(10)
            return real_check()
        bg._check_renders_once = stuck
        check(stalled.wait(3), "setup: the reading thread is stalled")
        far = 25 * 30                       # 25 s on: never cut before
        cut = bg._cuts[paths[0]]
        n_far = int(25 * 1000 // 25)
        check(cut._block(n_far) not in cut.blocks, "setup: 25 s is not cut")
        got = None
        for _ in range(100):
            got = bg(_fi_at(clk, far))
            if got:
                break
            time.sleep(0.02)
        check(got is not None and bg.fault == "" and stalled.is_set()
              and not release.is_set(),
              f"with the reading thread stalled, the cutting thread cut the "
              f"playing cue ahead: {bg.fault!r}")
        release.set()
        # A thread that dies is started again on the next frame, said once.
        lines = []
        bg._journal = lambda t, **k: lines.append((t, k))

        class Die(BaseException):
            pass
        real_cut = bg._cut_ahead
        killed = threading.Event()

        def die():
            if not killed.is_set():
                killed.set()
                raise Die("killed by the test")
            return real_cut()
        old_t = bg._cutter
        bg._cut_ahead = die
        old_t.join(3)
        check(not old_t.is_alive(), "setup: the cutting thread died")
        bg(_fi_at(clk, far))
        new_t = bg._cutter
        check(new_t is not old_t and new_t.is_alive() and
              any("ltcplay-flame-cues-cut stopped (Die: killed by the "
                  "test)" in t and k.get("fault") for t, k in lines),
              f"started again on the next frame, journaled as a fault: "
              f"{[t for t, _k in lines]}")
        bg.close()
        # Uncompressed, the last 3 frames (and a half) missing: no copy of
        # the render, every frame it has equal to the direct read, the
        # missing ones the render's own fault.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "u"), frames=600,
                                       compression="none",
                                       cut_tail_frames=3)
        direct = F.FlameCues(ctl, "Flames")
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        real_load = FS.FSEQ._load_block
        loads = []

        def spy_load(self, idx):
            if any(self is c.g for c in list(bg._cuts.values())):
                loads.append(idx)
            return real_load(self, idx)
        FS.FSEQ._load_block = spy_load
        try:
            bg._check_renders_once()
            bg._refresh_once()
            cut = bg._cuts[paths[0]]
            cut.ensure(0, 599)
        finally:
            FS.FSEQ._load_block = real_load
        check(cut.whole and not loads and len(cut.blocks) == 3,
              f"an uncompressed render is cut in pieces straight from "
              f"memory: {len(cut.blocks)} pieces, block loads {loads}")
        bad = []
        for k in range(0, 595):
            n = int(k * 1000 // 25)
            tc = _fi_at(clk, int(k * 25 * 30 // 1000))
            a, b = _fi_settled(bg, tc), direct(tc)
            if a != b:
                bad.append(k)
        check(not bad, f"every frame it has, as the direct read: {bad[:4]}")
        tc = _fi_at(clk, int(599 * 25 * 30 // 1000))
        got = bg(tc)
        check(got is None and bg.fault.startswith(
            "the show's render could not be read"),
              f"a missing frame: the render's own fault: {bg.fault!r}")
        bg.close()
        direct.close()
        # Compressed: the block's channel data is not kept after its cut.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "z"), frames=300)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.ensure(0, 299)
        check(len(cut.blocks) == len(cut.firsts) and cut.g._cache == b"",
              f"every block cut, no block's channel data kept: "
              f"{len(cut.g._cache)} bytes")
        bg.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_round2_of_177():
    section("fire & ice (review of #177): a cue that stays uncut while it "
            "plays on across blocks is a CUES FAULT after 1 s, never silent "
            "zeros; a new episode after a served row has its grace again; "
            "the playing cue is cut far ahead, before its render is "
            "published; a thread that keeps dying is restarted later each "
            "time and becomes a fault on the screens; close() joins both "
            "threads; a render's first missing frame is exact")
    import shutil
    import tempfile
    import threading
    import types
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()
    try:
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "a"), frames=1200)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()                    # no thread: driven by hand
        bg._check_renders_once()
        _fi_at(clk, 10 * 30)              # the show at 10 s
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        check(bg(_fi_at(clk, 10 * 30)) is not None and bg.fault == "",
              "the playing cue is cut where it is before its render is "
              "published")
        check(F.CUT_AHEAD_S >= 10 and
              cut._block(int(22 * 1000 // 25)) in cut.blocks,
              f"and far ahead of it ({F.CUT_AHEAD_S} s): 22 s is cut")
        # Playing on across uncut blocks (37 frames, under 1 s each) with
        # nothing cutting: one episode, a CUES FAULT after 1 s.
        mono = [100.0]
        bg._mono = lambda: mono[0]
        for b in list(cut.blocks):
            if b >= cut._block(int(23 * 1000 // 25)):
                cut.blocks.pop(b, None)
        start = 23 * 30
        silent, first_fault = 0, None
        for k in range(90):               # 3 s of show at 30 frames a second
            got = bg(_fi_at(clk, start + k))
            if got is None and bg.fault == "":
                silent += 1
            if bg.fault == F.CUES_LOADING and first_fault is None:
                first_fault = k / 30.0
            mono[0] += 1 / 30.0
        check(first_fault is not None and first_fault <= F.CUT_FAULT_AFTER_S
              + 0.05 and silent <= 31,
              f"uncut across blocks: a CUES FAULT after {first_fault} s, "
              f"{silent} silent zero frames")
        # A served row ends the episode: the next one has its grace again.
        cut.ensure(int(start / 30 * 40), int((start + 200) / 30 * 40))
        mono[0] += 1.0
        check(bg(_fi_at(clk, start + 95)) is not None, "setup: served")
        cut.blocks.pop(cut._block(int(28 * 1000 // 25)), None)
        mono[0] += 0.5
        got = bg(_fi_at(clk, 28 * 30))
        check(got is None and bg.fault == "",
              f"a new uncut moment after a served row: its own grace: "
              f"{bg.fault!r}")
        # A cutting thread that could not be started is cleared once it is.
        bg._start_failed.add("_cutter")
        bg._stop.clear()
        bg._cutter = types.SimpleNamespace(is_alive=lambda: False)
        bg._restarts["_cutter"] = (0, None, mono[0])
        bg.start()
        check(not bg._start_failed and bg._cutter.is_alive(),
              "started again: no longer said to be gone")
        # close() joins both threads, even a busy cutter.
        bg._cut_ahead = lambda *a, **k: time.sleep(0.3)
        time.sleep(0.1)
        cutter = bg._cutter
        bg.close()
        check(not cutter.is_alive() and not (bg._thread and
                                             bg._thread.is_alive()),
              "close() joined the cutting and the reading thread")
        # The cutting thread looks every CUT_EVERY_S.
        waits = []

        class Stop:
            def wait(self, t):
                waits.append(t)
                return len(waits) > 2
        c2 = F.FlameCues(ctl, "Flames", background=True)
        c2._stop = Stop()
        c2._cut_ahead = lambda: None
        c2._cutting()
        check(F.CUT_EVERY_S <= 0.1 and waits and
              all(w == F.CUT_EVERY_S for w in waits),
              f"the cutting thread looks every {F.CUT_EVERY_S} s: {waits}")
        # A thread that dies on every pass: restarted later each time, a
        # line each restart, a screen fault after RESTART_FAULT_AFTER.
        c3 = F.FlameCues(ctl, "Flames", background=True)
        lines = []
        c3._journal = lambda t, **k: lines.append(t)
        m3 = [0.0]
        c3._mono = lambda: m3[0]

        def dies():
            raise RuntimeError("dies every pass")
        c3._cutting = dies
        starts = 0
        for step in range(400):           # 40 s, a frame every 0.1 s
            before = c3._cutter
            c3.start()
            if c3._cutter is not before:
                starts += 1
                c3._cutter.join(1)
            m3[0] += 0.1
        restarted = [t for t in lines if "ltcplay-flame-cues-cut stopped"
                     in t]
        check(5 <= len(restarted) <= 7 and starts == len(restarted) + 1,
              f"backed off: {len(restarted)} restarts in 40 s (1, 2, 5, 10, "
              f"30 s apart): {starts} starts")
        # faults_now() first: it may clear thread_fault, and reading
        # thread_fault before it hid a faults_now() that always clears it.
        shown = c3.faults_now()
        check("keeps stopping" in shown and "restart LTC Player" in shown
              and shown == c3.thread_fault,
              f"and a fault on the screens: {shown!r}")
        c3.close()
        # A render missing its tail: each frame up to the last whole one,
        # then the first missing one raises, exactly.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "u"), frames=600,
                                       compression="none",
                                       cut_tail_frames=3)
        c4 = F.FlameCues(ctl, "Flames", background=True)
        c4._stop.set()
        c4._check_renders_once()
        c4._refresh_once()
        cut4 = c4._cuts[paths[0]]
        cut4.ensure(0, 599)
        f = FS.FSEQ(paths[0])
        bad = []
        for i in range(560, 600):
            try:
                want = F.FlameCues._cut(f.frame(i), cut4.spans, cut4.span)
            except Exception:
                want = None
            try:
                got = cut4.row(i)
            except Exception:
                got = None
            if got != want or (want is not None and len(got) != 512):
                bad.append((i, got and len(got), want and len(want)))
        f.close()
        check(not bad, f"frame by frame to the first missing one: {bad[:4]}")
        c4.close()
        # Review B of #177. A render whose tail is missing across several
        # pieces: one journal line for it, not one a piece.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "t"), frames=900,
                                       compression="none",
                                       cut_tail_frames=500)
        c5 = F.FlameCues(ctl, "Flames", background=True)
        c5._stop.set()
        c5._check_renders_once()
        c5._refresh_once()
        lines = []
        c5._journal = lambda t, **k: lines.append((t, k.get("fault")))
        c5._cuts[paths[0]].ensure(0, 899)
        said5 = set()
        for k in range(0, 900, 7):
            c5(_fi_at(clk, int(k * 25 * 30 // 1000)))
            if c5.fault:
                said5.add(c5.fault)
        bad_lines = [t for t, f in lines if f and "could not be read" in t]
        check(len(bad_lines) == 1,
              f"a render missing its tail: one line for it: {bad_lines}")
        # And one sentence on the screens for it, the same in every piece
        # (no frame number in it): the journal alone no longer shows this,
        # it journals a fault once while it stays set.
        check(len(said5) == 1,
              f"a render missing its tail: one fault text for it: {said5}")
        c5.close()
        # A block that fails for a reason that is not the render's bytes
        # (memory): uncut, tried again later, then cut. A corrupt block
        # stays for good (test_fire_ice_flame_cut_guards).
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "m"), frames=300)
        c6 = F.FlameCues(ctl, "Flames", background=True)
        c6._stop.set()
        c6._check_renders_once()
        c6._refresh_once()
        cut6 = c6._cuts[paths[0]]
        cut6.blocks.pop(3, None)
        tick = [500.0]
        cut6.clock = lambda: tick[0]
        real_load = FS.FSEQ._load_block
        boom = [True]

        def flaky(self, idx):
            if idx == 3 and boom[0]:
                boom[0] = False
                raise MemoryError("for a moment")
            return real_load(self, idx)
        FS.FSEQ._load_block = flaky
        try:
            cut6.ensure(cut6.firsts[3], cut6.firsts[3])
            uncut = 3 not in cut6.blocks and 3 not in cut6.errors
            cut6.ensure(cut6.firsts[3], cut6.firsts[3])
            waited = 3 not in cut6.blocks
            tick[0] += 1.0
            cut6.ensure(cut6.firsts[3], cut6.firsts[3])
        finally:
            FS.FSEQ._load_block = real_load
        check(uncut and waited and 3 in cut6.blocks and not cut6.errors,
              f"a MemoryError: the block uncut, not before its retry, then "
              f"cut: {uncut} {waited} {sorted(cut6.blocks)} {cut6.errors}")
        c6.close()
        # A render still being read while the show plays: zero, and the
        # CUES FAULT after 1 s, never silent zeros for as long as it lasts.
        ctl, clk, paths = _fi_cut_show(os.path.join(work, "r"), frames=300)
        c7 = F.FlameCues(ctl, "Flames", background=True)
        c7._stop.set()                     # nothing reads: stalled at Run
        m7 = [10.0]
        c7._mono = lambda: m7[0]
        got = c7(_fi_at(clk, 30))
        quiet = got is None and c7.fault == ""
        m7[0] += F.CUT_FAULT_AFTER_S + 0.1
        got = c7(_fi_at(clk, 31))
        check(quiet and got is None and "still being read" in c7.fault,
              f"a reader stalled at Run: a CUES FAULT after 1 s: "
              f"{c7.fault!r}")
        c7.close()
        # Six first start()s at once (the sender and the screens' threads):
        # one reading and one cutting thread, never more.
        c8 = F.FlameCues(ctl, "Flames", background=True)
        real_mono = c8._mono

        def slow_mono():
            time.sleep(0.01)              # widen the window a race needs
            return real_mono()
        c8._mono = slow_mono
        go = threading.Event()

        def hit():
            go.wait()
            c8.start()
        ts = [threading.Thread(target=hit) for _ in range(6)]
        for t in ts:
            t.start()
        go.set()
        for t in ts:
            t.join(5)
        n = sum(1 for t in threading.enumerate()
                if t.name.startswith("ltcplay-flame-cues") and t.is_alive())
        check(n == 2, f"six start()s at once: {n} threads (2 wanted)")
        c8.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def _fi_one_block_render(path, header_frames, body_frames, entry_len=None,
                         trailing=b""):
    """An uncompressed FSEQ v2 render with a ONE-entry block table (sparse:
    channels 1 to 100 and 601 to 800, each frame its own byte as
    _fi_cut_show's). `entry_len` is the block's length in the table (the
    channel data's own length when None); `trailing` follows the frames."""
    import struct
    sparse = [(0, 100), (600, 200)]
    cc = sum(n for _s, n in sparse)
    body = b"".join(bytes(((i * 7 + 3) & 0xFF,)) * cc
                    for i in range(body_frames)) + trailing
    tbl = struct.pack("<II", 0, len(body) if entry_len is None
                      else entry_len)
    sp = b"".join(struct.pack("<I", s)[:3] + struct.pack("<I", n)[:3]
                  for s, n in sparse)
    off = 32 + len(tbl) + len(sp)
    head = bytearray(32)
    head[0:4] = b"PSEQ"
    struct.pack_into("<H", head, 4, off)
    head[6], head[7] = 2, 2
    struct.pack_into("<H", head, 8, off)
    struct.pack_into("<I", head, 10, cc)
    struct.pack_into("<I", head, 14, header_frames)
    head[18] = 25
    head[20], head[21], head[22] = 0, 1, len(sparse)   # none, 1 block
    with open(path, "wb") as fh:
        fh.write(bytes(head) + tbl + sp + body)
    return cc


def test_fire_ice_flame_cut_round3_of_177():
    section("fire & ice (review 3 of #177): an uncompressed render with one "
            "block is cut only to that block's end, faulting where the "
            "direct read does; a cut that keeps failing for any reason is "
            "named after its retries, and a block failing to cut is a fault "
            "at once; a thread that keeps stopping outranks 'they follow'; "
            "the restart back-off counts the time a thread ran; the grace "
            "ends at a pause, a stop, a new session or cue; a restart is "
            "journaled only once it runs")
    import shutil
    import tempfile
    import threading
    import types
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()

    def cut_of(name, **kw):
        ctl, clk, paths = _fi_cut_show(os.path.join(work, name), **kw)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()                    # no thread: driven by hand
        return ctl, clk, paths, bg

    def as_direct(cut, path, n):
        """Frames whose cut differs from the direct read (a value, or one
        raising and the other not), and the two errors at frame 0."""
        f = FS.FSEQ(path)
        bad, first = [], None
        for i in range(n):
            try:
                want, werr = F.FlameCues._cut(f.frame(i), cut.spans,
                                              cut.span), None
            except Exception as e:
                want, werr = None, e
            try:
                got, gerr = cut.row(i), None
            except Exception as e:
                got, gerr = None, e
            if i == 0:
                first = (werr, gerr)
            if got != want or (werr is None) != (gerr is None) or \
                    (got is None and gerr is None):
                bad.append(i)
        f.close()
        return bad, first
    try:
        # A. One-block uncompressed renders, cut only to the block's end.
        cases = (
            ("trailing", dict(header_frames=340, body_frames=300,
                              entry_len=300 * 300,
                              trailing=b"\xff" * (40 * 300)), 340),
            ("short entry", dict(header_frames=300, body_frames=300,
                                 entry_len=290 * 300), 300),
            ("truncated", dict(header_frames=300, body_frames=250,
                               entry_len=300 * 300), 300))
        for k, (what, kw, n) in enumerate(cases):
            ctl, clk, paths, bg = cut_of(f"a{k}", frames=300)
            _fi_one_block_render(paths[0], **kw)
            bg._check_renders_once()
            bg._refresh_once()
            cut = bg._cuts[paths[0]]
            cut.ensure(0, n - 1)
            bad, (werr, gerr) = as_direct(cut, paths[0], n)
            check(cut.whole and not bad,
                  f"one block, {what}: every frame as the direct read, a "
                  f"value or a fault: {bad[:4]} of {len(bad)}")
            if what == "truncated":
                check(isinstance(gerr, FS.FSEQError) and
                      str(gerr) == str(werr),
                      f"truncated: the direct read's own error: {gerr!r} "
                      f"{werr!r}")
            last = int((n - 1) * 25 * 30 // 1000)
            got = _fi_settled(bg, _fi_at(clk, last))
            check(got is None and bg.fault.startswith(
                "the show's render could not be read"),
                  f"one block, {what}: its last frame is a CUES FAULT, never "
                  f"junk: {got and got[90:92]} {bg.fault!r}")
            bg.close()
        # B. A cut that fails for a reason that is not the render's bytes
        # (a missing zstandard): a CUES FAULT naming it at once while it
        # waits for its retry, then, after CUT_RETRIES retries, for good,
        # journaled once.
        ctl, clk, paths, bg = cut_of("b", frames=300)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(3, None)           # frames 111 to 147
        tick = [0.0]
        cut.clock = lambda: tick[0]
        lines = []
        bg._journal = lambda t, **k: lines.append(t)
        mono = [100.0]
        bg._mono = lambda: mono[0]
        real_load = FS.FSEQ._load_block
        calls = []

        def nomod(self, idx):
            if idx == 3:
                calls.append(idx)
                raise ModuleNotFoundError("No module named 'zstandard'")
            return real_load(self, idx)
        FS.FSEQ._load_block = nomod
        try:
            cut.ensure(cut.firsts[3], cut.firsts[3])
            served = bg(_fi_at(clk, 75)) is not None      # frame 100
            got = bg(_fi_at(clk, 90))                      # frame 120
            check(served and got is None and
                  "ModuleNotFoundError" in bg.fault,
                  f"a block failing to cut between served rows: a CUES "
                  f"FAULT naming it at once, never a silent grace: "
                  f"{bg.fault!r}")
            for _ in range(10):            # 25 s: before any slow retry
                tick[0] += 2.5
                cut.ensure(cut.firsts[3], cut.firsts[3])
        finally:
            FS.FSEQ._load_block = real_load
        check(len(calls) == F.CUT_RETRIES + 1 and isinstance(
            cut.errors.get(3), ModuleNotFoundError) and 3 not in cut.retry,
              f"tried {len(calls)} times ({F.CUT_RETRIES} retries), then "
              f"for good: {cut.errors.get(3)!r}")
        for k in range(20):
            got = bg(_fi_at(clk, 90 + k % 5))
        named = [t for t in lines if "could not be cut from its render "
                 "(ModuleNotFoundError" in t]
        check(got is None and "ModuleNotFoundError: No module named" in
              bg.fault and "tried again every 30 s" in bg.fault and
              "could not be read" not in bg.fault and len(named) == 1,
              f"for good: the screens and one journal line name it: "
              f"{bg.fault!r} {named}")
        bg.close()
        # B. Each retry waits longer: 0.5, 1 then 2 s.
        ctl, clk, paths, bg = cut_of("r", frames=300)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(4, None)
        tick = [0.0]
        cut.clock = lambda: tick[0]
        calls = []

        def nomem(self, idx):
            if idx == 4:
                calls.append(tick[0])
                raise MemoryError("again")
            return real_load(self, idx)
        FS.FSEQ._load_block = nomem
        try:
            for t in (0.0, 0.6, 1.2, 1.7, 3.0, 3.8):
                tick[0] = t
                cut.ensure(cut.firsts[4], cut.firsts[4])
        finally:
            FS.FSEQ._load_block = real_load
        check(calls == [0.0, 0.6, 1.7, 3.8] and
              isinstance(cut.errors.get(4), MemoryError),
              f"retried after 0.5, 1 and 2 s, then for good: {calls} "
              f"{cut.errors.get(4)!r}")
        bg.close()
        # C. A thread that keeps stopping outranks 'they follow'.
        ctl, clk, paths, bg = cut_of("c", frames=600)
        bg._check_renders_once()
        bg._refresh_once()
        keeps = ("the thread that cuts the show's flame cues from its "
                 "renders keeps stopping (3 restarts, the last: X); restart "
                 "LTC Player")
        bg.thread_fault = keeps
        bg.fault = F.CUES_LOADING
        shown = bg.faults_now()
        bg.fault = F.RENDER_OLDER_THAN_LAYOUT
        refused = bg.faults_now()
        check(shown == keeps and refused == F.RENDER_OLDER_THAN_LAYOUT,
              f"a thread that keeps stopping outranks the loading fault, "
              f"never a refusal: {shown!r} {refused!r}")
        bg.thread_fault, bg.fault = "", ""
        # C. A cutter waiting out its back-off promises nothing.
        cut = bg._cuts[paths[0]]
        for b in list(cut.blocks):
            if b >= 5:
                cut.blocks.pop(b)
        bg._stop.clear()
        bg.start = lambda: bg             # nothing started by hand here
        bg._cutter = types.SimpleNamespace(is_alive=lambda: False)
        got = _fi_settled(bg, _fi_at(clk, 165))       # frame 220
        waiting = bg.fault
        bg.thread_fault = keeps
        _fi_settled(bg, _fi_at(clk, 166))
        check(got is None and waiting == F.CUES_CUTTER_WAITING and
              "within a second" not in waiting and bg.fault == keeps,
              f"a stopped cutter: no promise of a second, and one that "
              f"keeps stopping says so: {waiting!r} {bg.fault!r}")
        bg._cutter = None
        bg._stop.set()
        bg.close()
        # D. The back-off counts the time a thread RAN.
        ctl, clk, paths, c = cut_of("d", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        lines = []
        c._journal = lambda t, **k: lines.append(t)
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        gate = threading.Event()
        mode = ["short"]

        def body():
            if mode[0] == "long":
                gate.wait(5)
            raise RuntimeError("dies")
        c._cutting = body

        def step():
            before = c._cutter
            c.start()
            if c._cutter is not before:
                c._cutter.join(5)
                return True
            return False
        restarts = 0
        for _ in range(3000):
            if step() and c._restarts["_cutter"][0] >= 6:
                break
            m[0] += 0.1
        n6 = c._restarts["_cutter"][0]
        m[0] += 200.0                     # nobody asks for 200 s
        again = step()
        m[0] += 1.0
        soon = step()
        check(n6 == 6 and again and "(restart 7)" in lines[-1] and
              not soon,
              f"200 s with no start() call is not a thread that ran: "
              f"restart 7, then 60 s apart: {n6} {lines[-1:]} {soon}")
        mode[0] = "long"
        m[0] += 61.0
        before = c._cutter
        c.start()
        long_t = c._cutter
        m[0] += 61.0                      # it runs 61 s, then dies
        gate.set()
        long_t.join(5)
        restarts = step()
        check(long_t is not before and restarts and
              "(restart 1)" in lines[-1],
              f"a thread that ran 61 s before it died starts the count "
              f"again: {lines[-1:]}")
        c._stop.set()
        c._thread = None
        c.close()
        # E. The grace ends at a pause, a stop, a new cue or session.
        ctl, clk, paths, c = cut_of("e", frames=600, ncues=2)
        c._check_renders_once()
        c._refresh_once()
        for p in paths:
            cut = c._cuts[p]
            for b in list(cut.blocks):
                if b >= 5:
                    cut.blocks.pop(b)
        m = [10.0]
        c._mono = lambda: m[0]
        s = ctl.session
        for what in ("paused", "stopped"):
            c(_fi_at(clk, 165, label="c0"))
            m[0] += 0.9
            if what == "paused":
                clk.paused = True
            else:
                s.running = False
            c(_fi_at(clk, 165))
            m[0] += 5.0
            clk.paused, s.running = False, True
            got = c(_fi_at(clk, 166))
            check(got is None and c.fault == "",
                  f"{what} on an uncut frame, then on again: a grace of its "
                  f"own: {c.fault!r}")
            m[0] += 2.0
            c(_fi_at(clk, 167))
        c._uncut = None
        c(_fi_at(clk, 165, label="c0"))
        m[0] += 0.9
        c(_fi_at(clk, 166))
        m[0] += 0.2
        got = c(_fi_at(clk, 167, label="c1"))
        check(got is None and c.fault == "",
              f"another cue, uncut: a grace of its own: {c.fault!r}")
        c.close()
        # E. A new session still being read: a grace of its own; and a
        # fault left from before never shows while it lasts.
        ctl, clk, paths, c = cut_of("s", frames=300)
        m = [10.0]
        c._mono = lambda: m[0]
        c.fault = "a fault from before"
        c(_fi_at(clk, 30))
        quiet = c.fault == ""
        m[0] += 0.9
        c(_fi_at(clk, 31))
        ctl.session = types.SimpleNamespace(**vars(ctl.session))
        m[0] += 0.2
        got = c(_fi_at(clk, 32))
        check(quiet and got is None and c.fault == "",
              f"a fault from before is cleared in the grace, and a new "
              f"session has a grace of its own: {quiet} {c.fault!r}")
        c.close()
        # F. A thread that cannot be started: said so, never 'started
        # again'; once it starts, then said.
        ctl, clk, paths, c = cut_of("f", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        lines = []
        c._journal = lambda t, **k: lines.append(t)
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        dead = types.SimpleNamespace(is_alive=lambda: False)
        c._cutter = dead
        c._cutting = lambda: c._stop.wait(5)
        real_thread = F.threading.Thread

        class NoStart(real_thread):
            def start(self):
                raise RuntimeError("can't start new thread")
        F.threading.Thread = NoStart
        try:
            c.start()
        finally:
            F.threading.Thread = real_thread
        failed = list(lines)
        m[0] += 2.0
        c.start()
        check(any("could not be started (RuntimeError" in t for t in failed)
              and not any("started again" in t for t in failed) and
              c._cutter is not dead and c._cutter.is_alive() and
              "was started again" in lines[-1],
              f"a failed start is said as one, a restart only once it "
              f"runs: {failed} {lines[-1:]}")
        c._stop.set()
        c._thread = None
        c.close()
        # F. close() while a start() waits for the lock: nothing started.
        ctl, clk, paths, c = cut_of("g", frames=300)
        c._stop.clear()
        c._start_lock.acquire()
        t = threading.Thread(target=c.start)
        t.start()
        time.sleep(0.1)
        c._stop.set()
        c._start_lock.release()
        t.join(5)
        check(c._thread is None and c._cutter is None,
              "a start() that waited out a close() starts nothing")
        c.close()
        # G. A thread fault stays on the screens until both threads have
        # run RESTART_RESET_S since their last start, then clears.
        ctl, clk, paths, c = cut_of("h", frames=300)
        alive = types.SimpleNamespace(is_alive=lambda: True)
        c._thread = c._cutter = alive
        c._restarts = {"_thread": (0, 0.0, 0.0), "_cutter": (3, 0.0, 0.0)}
        m = [30.0]
        c._mono = lambda: m[0]
        c.thread_fault = keeps
        early = c.faults_now()
        m[0] = 61.0
        later = c.faults_now()
        check(early == keeps and later == "" and c.thread_fault == "",
              f"the thread fault holds until both ran 60 s, then clears: "
              f"{early!r} {later!r}")
        c._thread = c._cutter = None
        c.close()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_round4_of_177():
    section("fire & ice (round 2 review of #177): a cut fault that is not "
            "the render's bytes is tried again every 30 s, never kept for "
            "every later show; a look ends the uncut grace; the back-off "
            "counts from a death; a retry set meanwhile is seen under the "
            "lock; a first start that fails is backed off and its recovery "
            "said; a render whose sparse ranges disagree with its channel "
            "count is refused in both paths; a garbage frame count lists no "
            "pieces; a thread that dies at once keeps its reason")
    import shutil
    import struct
    import tempfile
    import threading
    import tracemalloc
    import types
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()

    def cut_of(name, **kw):
        ctl, clk, paths = _fi_cut_show(os.path.join(work, name), **kw)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        return ctl, clk, paths, bg
    real_load = FS.FSEQ._load_block
    try:
        # A1. MemoryError on block 5 at Run for longer than its retries:
        # named for good, then tried again every CUT_RETRY_SLOW_S, so a
        # later Run plays it.
        ctl, clk, paths, bg = cut_of("a1", frames=600)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        for b in list(cut.blocks):
            if b >= 5:
                cut.blocks.pop(b)
        tick = [0.0]
        cut.clock = lambda: tick[0]
        bad = [True]
        calls = []

        def nomem(self, idx):
            if idx >= 5:
                calls.append(idx)
                if bad[0]:
                    raise MemoryError("at Run")
            return real_load(self, idx)
        FS.FSEQ._load_block = nomem
        try:
            for _ in range(8):
                cut.ensure(cut.firsts[5], cut.firsts[5])
                tick[0] += 3.0
            named = isinstance(cut.errors.get(5), MemoryError)
            got = _fi_settled(bg, _fi_at(clk, 150))       # frame 200
            faulted = got is None and "MemoryError" in bg.fault
            bad[0] = False                # the memory came back
            n = len(calls)
            tick[0] += 5.0
            cut.ensure(cut.firsts[5], cut.firsts[5])
            early = len(calls) == n
            ctl.session.running = False   # Stop, then Run again
            bg(_fi_at(clk, 150))
            ctl.session.running = True
            tick[0] += F.CUT_RETRY_SLOW_S
            bg._refresh_once()
            _fi_at(clk, 150)
            bg._cut_ahead()
            got = bg(_fi_at(clk, 150))
        finally:
            FS.FSEQ._load_block = real_load
        check(named and faulted and early and got is not None and
              bg.fault == "" and 5 not in cut.errors,
              f"a passing error kept as a fault is tried again every "
              f"{F.CUT_RETRY_SLOW_S:g} s, and a later Run plays it: "
              f"{named} {faulted} {early} {bg.fault!r}")
        bg.close()
        # A2. A look ends the uncut grace.
        ctl, clk, paths, bg = cut_of("a2", frames=600)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        for b in list(cut.blocks):
            if b >= 5:
                cut.blocks.pop(b)
        m = [10.0]
        bg._mono = lambda: m[0]
        bg(_fi_at(clk, 165))
        m[0] += 0.9
        ctl.session.player.override = "blackout"
        bg(_fi_at(clk, 165))
        m[0] += 0.5
        ctl.session.player.override = None
        got = bg(_fi_at(clk, 166))
        check(got is None and bg.fault == "",
              f"a look on an uncut frame, then the show: a grace of its "
              f"own: {bg.fault!r}")
        bg.close()
        # A2. The back-off counts from when the thread died, not from when
        # it was started.
        ctl, clk, paths, c = cut_of("a3", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        gate = threading.Event()

        def body():
            gate.wait(5)
            raise RuntimeError("dies")
        c._cutting = body
        c.start()                         # first start at 0
        first = c._cutter
        gate.set()
        first.join(5)
        gate.clear()
        c.start()                         # restart 1 at once, at 0
        r1 = c._cutter
        m[0] = 30.0                       # it runs 30 s, then dies
        gate.set()
        r1.join(5)
        gate.clear()
        m[0] = 30.2
        c.start()
        soon = c._cutter is not r1
        m[0] = 31.1
        c.start()
        later = c._cutter is not r1
        check(not soon and later,
              f"restart 2 waits 1 s from the death, not from the start: "
              f"{soon} {later}")
        gate.set()
        c._stop.set()
        c._thread = None
        c.close()
        # A4. A retry set by the other cutting thread while this one waited
        # for the lock is seen under the lock: not cut again at once.
        ctl, clk, paths, bg = cut_of("a4", frames=300)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(4, None)
        cuts = []
        real_cb = cut._cut_block

        def spy(b):
            cuts.append(b)
            return real_cb(b)
        cut._cut_block = spy
        cut.lock.acquire()
        t = threading.Thread(target=cut.ensure,
                             args=(cut.firsts[4], cut.firsts[4]))
        t.start()
        time.sleep(0.2)
        cut.retry[4] = (1, cut.clock() + 100.0, MemoryError("other"))
        cut.lock.release()
        t.join(5)
        check(cuts == [], f"a retry set meanwhile is honoured: {cuts}")
        bg.close()
        # A5. A first start that fails: backed off, and the recovery said.
        ctl, clk, paths, c = cut_of("a5", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        lines = []
        c._journal = lambda t, **k: lines.append(t)
        tries = []
        real_thread = F.threading.Thread

        class NoStart(real_thread):
            def start(self):
                tries.append(self.name)
                raise RuntimeError("can't start new thread")
        c._cutting = lambda: c._stop.wait(5)
        c._refresher = lambda: c._stop.wait(5)
        F.threading.Thread = NoStart
        try:
            c.start()
            c.start()
            m[0] += 0.5
            c.start()
        finally:
            F.threading.Thread = real_thread
        n_tries = len(tries)
        m[0] += 1.0
        c.start()
        check(n_tries == 2 and c._cutter is not None and
              c._cutter.is_alive() and not c._start_failed and
              any("is running now, after it could not be started" in t
                  for t in lines),
              f"a failed first start is backed off ({n_tries} tries, 2 "
              f"wanted) and its recovery journaled: {lines[-2:]}")
        c._stop.set()
        c.close()
        # B1. Sparse ranges that cover more than the channel count: refused
        # in the direct path and the cut one, never shifted bytes.
        ctl, clk, paths, bg = cut_of("b1", frames=300)
        with open(paths[0], "r+b") as fh:
            head = bytearray(fh.read(32))
            n_blocks = ((head[20] & 0xF0) << 4) | head[21]
            fh.seek(32 + n_blocks * 8 + 6)            # the second range
            fh.write(struct.pack("<I", 600)[:3] + struct.pack("<I", 250)[:3])
        direct = F.FlameCues(ctl, "Flames")
        bg._check_renders_once()
        bg._refresh_once()
        tc = _fi_at(clk, 30)
        a, b = direct(tc), _fi_settled(bg, tc)
        check(a is None and b is None and
              direct.fault.startswith("the show's render has 300 channels "
                                      "but its sparse ranges cover 350") and
              bg.fault == direct.fault,
              f"ranges past the channels: refused in both paths: "
              f"{direct.fault!r} {bg.fault!r}")
        try:
            F.FlameCues._cut(bytes(300), [(0, 0, 100), (600, 100, 250)],
                             (511, 512))
            check(False, "a cut past the frame's bytes was made")
        except FS.FSEQError:
            check(True, "a cut past the frame's bytes raises")
        direct.close()
        bg.close()
        # B2. A garbage frame count lists no pieces.
        ctl, clk, paths, bg = cut_of("b2", frames=300)
        _fi_one_block_render(paths[0], header_frames=200_000_000,
                             body_frames=300)
        bg._check_renders_once()
        tracemalloc.start()
        try:
            bg._refresh_once()
            _cur, peak = tracemalloc.get_traced_memory()
        finally:
            tracemalloc.stop()
        cut = bg._cuts.get(paths[0])
        check(cut is not None and cut.whole and peak < 8_000_000 and
              cut.row(10) is not None,
              f"200 million frames in the header: {peak / 1e6:.1f} MB at "
              f"Run, the frames it has cut")
        bg.close()
        # B4. A thread that dies at once keeps its own reason.
        ctl, clk, paths, c = cut_of("b4", frames=300)
        c._stop.clear()
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        c._cutter = types.SimpleNamespace(is_alive=lambda: False)
        c._died["_cutter"] = "RuntimeError: the first death"

        def dies_at_once():
            raise RuntimeError("the second death")
        c._cutting = dies_at_once

        class JoinOnStart(real_thread):
            def start(self):
                super().start()
                self.join(5)
        F.threading.Thread = JoinOnStart
        try:
            c.start()
        finally:
            F.threading.Thread = real_thread
        check(c._died.get("_cutter") == "RuntimeError: the second death",
              f"a death during the start keeps its reason: "
              f"{c._died.get('_cutter')!r}")
        c._stop.set()
        c._thread = c._cutter = None
        c.close()
    finally:
        FS.FSEQ._load_block = real_load
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_round5_of_177():
    section("fire & ice (round 3 review of #177): a cut that could not be "
            "set up for a passing reason is set up again every 30 s, a "
            "damaged render never; failed starts are not restarts; a kept "
            "error carries no traceback; a passing fault says it is tried "
            "again and is journaled once per cause; ranges covering fewer "
            "channels than the header are refused; a stale death reason is "
            "never repeated; a failed slow retry waits 30 s again; a data "
            "error is never retried; zstd out of memory may pass")
    import shutil
    import struct
    import sys as _sys
    import tempfile
    import types
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()

    def cut_of(name, **kw):
        ctl, clk, paths = _fi_cut_show(os.path.join(work, name), **kw)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        return ctl, clk, paths, bg
    real_init = F._FlameCut.__init__
    real_load = FS.FSEQ._load_block
    real_thread = F.threading.Thread
    try:
        # A1. The set-up fails once with a MemoryError: a fault saying it
        # is tried again, kept (not set up on every pass) until 30 s, then
        # set up again and played. A damaged render's set-up is for good.
        for kind, err in (("passing", MemoryError("set up")),
                          ("damaged", ValueError("bad table"))):
            ctl, clk, paths, bg = cut_of("a1" + kind, frames=300)
            lines = []
            bg._journal = lambda t, **k: lines.append(t)
            inits = []

            def flaky(self, *a, **k):
                inits.append(1)
                if len(inits) == 1:
                    raise err
                return real_init(self, *a, **k)
            F._FlameCut.__init__ = flaky
            try:
                bg._check_renders_once()
                bg._refresh_once()
                first = bg._cuts[paths[0]]
                for k in range(10):
                    got = _fi_settled(bg, _fi_at(clk, 30 + k))
                fault = bg.fault
                bg._refresh_once()
                kept = bg._cuts[paths[0]] is first and len(inits) == 1
                first.clock = lambda: F._FlameCut.clock() + 31.0
                bg._refresh_once()
                got = bg(_fi_at(clk, 30))
            finally:
                F._FlameCut.__init__ = real_init
            said = [t for t in lines if "could not be" in t]
            if kind == "passing":
                check(kept and "MemoryError: set up" in fault and
                      "tried again every 30 s" in fault and
                      len(said) == 1 and len(inits) == 2 and
                      got is not None and bg.fault == "",
                      f"a passing set-up failure: said once as tried "
                      f"again, kept for 30 s, then set up and played: "
                      f"{fault!r} {said} {len(inits)} {bg.fault!r}")
            else:
                check(kept and fault.startswith(
                    "the show's render could not be read (ValueError") and
                      len(inits) == 1 and got is None,
                      f"a damaged render's set-up is for good: {fault!r} "
                      f"{len(inits)}")
            bg.close()
        # A2. Five failed starts of a dead thread are not five restarts.
        ctl, clk, paths, c = cut_of("a2", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        lines = []
        c._journal = lambda t, **k: lines.append(t)
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        c._cutter = types.SimpleNamespace(is_alive=lambda: False)

        def dies():
            raise RuntimeError("dies")
        c._cutting = dies

        class NoStart(real_thread):
            def start(self):
                raise RuntimeError("can't start new thread")
        F.threading.Thread = NoStart
        try:
            for _ in range(5):
                c.start()
                m[0] += 61.0
        finally:
            F.threading.Thread = real_thread
        c.start()
        first = lines[-1]
        c._cutter.join(5)
        m[0] += 1.1
        before = c._cutter
        c.start()
        check("(restart 1)" in first and c.thread_fault == "" and
              c._cutter is not before,
              f"failed starts are not restarts: {first!r}, and the next "
              f"death waits 1 s: {c.thread_fault!r}")
        c._stop.set()
        c._cutter.join(5)
        c._thread = None
        c.close()
        # A3. A kept error carries no traceback (it would pin the frames
        # and the decompressed block).
        ctl, clk, paths, bg = cut_of("a3", frames=300, corrupt_block=4)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(2, None)
        cut.blocks.pop(3, None)

        def nomem(self, idx):
            if idx in (2, 3):
                raise MemoryError(f"block {idx}")
            return real_load(self, idx)
        FS.FSEQ._load_block = nomem
        try:
            cut.ensure(cut.firsts[2], cut.firsts[4])
        finally:
            FS.FSEQ._load_block = real_load
        kept = [cut.errors.get(4)] + [r[2] for r in cut.retry.values()]
        check(len(kept) == 3 and all(e is not None and e.__traceback__ is None
                                     for e in kept),
              f"kept errors carry no traceback: "
              f"{[e is not None and e.__traceback__ for e in kept]}")
        failed = F._FlameCut.failed(cut.f, cut.span, MemoryError("x"))
        try:
            raise MemoryError("with a traceback")
        except MemoryError as e:
            failed2 = F._FlameCut.failed(cut.f, cut.span, e)
        check(failed2.errors[0].__traceback__ is None and failed is not None,
              "a failed set-up keeps its error with no traceback")
        bg.close()
        # B-2. Two blocks failing with their own words: one journal line.
        ctl, clk, paths, bg = cut_of("b2", frames=300)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(2, None)
        cut.blocks.pop(3, None)
        lines = []
        bg._journal = lambda t, **k: lines.append(t)
        FS.FSEQ._load_block = nomem
        try:
            cut.ensure(cut.firsts[2], cut.firsts[3])
        finally:
            FS.FSEQ._load_block = real_load
        for n in (60, 61, 90, 91, 60, 90):    # frames 80, 81, 120, 121
            bg(_fi_at(clk, n))
        said = [t for t in lines if "could not be cut here" in t]
        check(len(said) == 1 and "MemoryError" in bg.fault,
              f"one line per cause, not per block: {said}")
        bg.close()
        # A5. Ranges covering FEWER channels than the header: refused too.
        ctl, clk, paths, bg = cut_of("a5", frames=300)
        with open(paths[0], "r+b") as fh:
            head = bytearray(fh.read(32))
            n_blocks = ((head[20] & 0xF0) << 4) | head[21]
            fh.seek(32 + n_blocks * 8 + 6)
            fh.write(struct.pack("<I", 600)[:3] + struct.pack("<I", 150)[:3])
        direct = F.FlameCues(ctl, "Flames")
        got = direct(_fi_at(clk, 30))
        check(got is None and "sparse ranges cover 250" in direct.fault,
              f"ranges under the header's count: refused: {direct.fault!r}")
        direct.close()
        bg.close()
        # A5. A thread that died with a reason, then ended with none: the
        # next restart says it ended, never the old reason.
        ctl, clk, paths, c = cut_of("a6", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        lines = []
        c._journal = lambda t, **k: lines.append(t)
        c._thread = types.SimpleNamespace(is_alive=lambda: True)
        mode = ["raise"]

        def body():
            if mode[0] == "raise":
                raise RuntimeError("the old reason")
        c._cutting = body
        c.start()
        c._cutter.join(5)
        mode[0] = "return"
        c.start()                         # restart 1: says the old reason
        c._cutter.join(5)
        m[0] += 1.1
        c.start()                         # restart 2: it just ended
        check("the old reason" in lines[-2] and "(it ended)" in lines[-1],
              f"a stale reason is never repeated: {lines[-2:]}")
        c._stop.set()
        c._thread = None
        c.close()
        # A5. A slow retry that fails waits 30 s again; a data error is
        # never tried again.
        ctl, clk, paths, bg = cut_of("a7", frames=300, corrupt_block=4)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        cut.blocks.pop(2, None)
        cut.errors.pop(4, None)           # its first failure, on this clock
        cut.slow.pop(4, None)
        tick = [0.0]
        cut.clock = lambda: tick[0]
        tries = []
        real_cb = cut._cut_block

        def spy(b):
            tries.append((b, tick[0]))
            if b == 2:
                raise MemoryError("again")
            return real_cb(b)
        cut._cut_block = spy
        for t in (0.0, 1.0, 3.0, 6.0, 37.0, 38.0, 50.0, 68.0):
            tick[0] = t
            cut.ensure(cut.firsts[2], cut.firsts[2])
            cut.ensure(cut.firsts[4], cut.firsts[4])
        t2 = [t for b, t in tries if b == 2]
        t4 = [t for b, t in tries if b == 4]
        check(t2 == [0.0, 1.0, 3.0, 6.0, 37.0, 68.0],
              f"a slow retry that fails waits 30 s again: {t2}")
        check(t4 == [0.0] and 4 in cut.errors,
              f"a data error is never tried again: {t4}")
        bg.close()
        # B-3. zstd: out of memory may pass, bad data is for good.
        fake = types.ModuleType("zstandard")

        class ZstdError(Exception):
            pass
        fake.ZstdError = ZstdError
        saved = _sys.modules.get("zstandard")
        _sys.modules["zstandard"] = fake
        try:
            oom = F._cut_data_error(ZstdError(
                "decompression error: Allocation error : not enough memory"))
            bad = F._cut_data_error(ZstdError(
                "decompression error: Unknown frame descriptor"))
        finally:
            if saved is None:
                _sys.modules.pop("zstandard", None)
            else:
                _sys.modules["zstandard"] = saved
        check(not oom and bad, f"zstd out of memory may pass, bad data does "
                               f"not: {oom} {bad}")
    finally:
        F._FlameCut.__init__ = real_init
        FS.FSEQ._load_block = real_load
        F.threading.Thread = real_thread
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_cut_final_of_177():
    section("fire & ice (final review of #177): a render file that cannot be "
            "opened is a render that could not be read, never a cut tried "
            "again; a kept error raised on every frame never grows a "
            "traceback; a start that works ends its failed-start count; one "
            "journal line per cue, not per kind of fault")
    import shutil
    import tempfile
    import types
    from ltcplay import fseq as FS
    F = _fi_mod()
    work = tempfile.mkdtemp()

    def cut_of(name, **kw):
        ctl, clk, paths = _fi_cut_show(os.path.join(work, name), **kw)
        bg = F.FlameCues(ctl, "Flames", background=True)
        bg._stop.set()
        return ctl, clk, paths, bg
    real_load = FS.FSEQ._load_block
    real_thread = F.threading.Thread
    try:
        # (1) The render deleted: could not be read, FileNotFoundError.
        ctl, clk, paths, bg = cut_of("open", frames=300)
        os.remove(paths[0])
        bg._check_renders_once()
        bg._refresh_once()
        got = _fi_settled(bg, _fi_at(clk, 30))
        check(got is None and bg.fault.startswith(
            "the show's render could not be read (FileNotFoundError") and
              "tried again" not in bg.fault,
              f"a render that cannot be opened: could not be read: "
              f"{bg.fault!r}")
        bg.close()
        # (2) A kept error, a short render's too, raised on 200 frames:
        # its traceback stays short.
        ctl, clk, paths, bg = cut_of("tb", frames=300, corrupt_block=4)
        bg._check_renders_once()
        bg._refresh_once()
        cut = bg._cuts[paths[0]]
        n4 = int(cut.firsts[4] * 25 * 30 // 1000) + 1
        for _ in range(200):
            bg(_fi_at(clk, n4))
        ctl2, clk2, paths2, bg2 = cut_of("tbs", frames=600,
                                         compression="none",
                                         cut_tail_frames=3)
        bg2._check_renders_once()
        bg2._refresh_once()
        cut2 = bg2._cuts[paths2[0]]
        cut2.ensure(0, 599)
        for _ in range(200):
            bg2(_fi_at(clk2, int(599 * 25 * 30 // 1000)))

        def depth(e):
            n, tb = 0, e.__traceback__ if e is not None else None
            while tb is not None:
                n, tb = n + 1, tb.tb_next
            return n
        kept = cut.errors.get(4)
        short = next(iter(cut2.short.values()))[1]
        check(kept is not None and depth(kept) <= 3 and depth(short) <= 3
              and "could not be read" in bg.fault and
              "could not be read" in bg2.fault,
              f"raised 200 times, a kept error's traceback stays short: "
              f"{depth(kept)} {depth(short)} entries")
        bg.close()
        bg2.close()
        # (3) A start that works ends the failed-start count: a later
        # failed start is backed off from 1 s again, not 2.
        ctl, clk, paths, c = cut_of("tries", frames=300)
        c._stop.clear()
        m = [0.0]
        c._mono = lambda: m[0]
        c._journal = lambda t, **k: None
        c._thread = types.SimpleNamespace(is_alive=lambda: True)

        def dies():
            raise RuntimeError("dies")
        c._cutting = dies
        tries = []

        class NoStart(real_thread):
            def start(self):
                tries.append(m[0])
                raise RuntimeError("can't start new thread")
        F.threading.Thread = NoStart
        try:
            c.start()                     # a failed first start, at 0
        finally:
            F.threading.Thread = real_thread
        m[0] = 1.1
        c.start()                         # it works, and dies
        c._cutter.join(5)
        tries.clear()
        F.threading.Thread = NoStart
        try:
            m[0] = 2.0
            c.start()                     # fails: the first of a new count
            m[0] = 3.2
            c.start()                     # 1.2 s on: tried again
        finally:
            F.threading.Thread = real_thread
        check(tries == [2.0, 3.2],
              f"a start that works ends the failed-start count: {tries}")
        c._stop.set()
        c._thread = c._cutter = None
        c.close()
        # (4) The same fault on two cues: a journal line for each cue.
        ctl, clk, paths, bg = cut_of("cues", frames=300, ncues=2)
        bg._check_renders_once()
        bg._refresh_once()
        lines = []
        bg._journal = lambda t, **k: lines.append(t)

        def nomem(self, idx):
            if idx == 2:
                raise MemoryError("again")
            return real_load(self, idx)
        FS.FSEQ._load_block = nomem
        try:
            for p in paths:
                cut = bg._cuts[p]
                cut.blocks.pop(2, None)
                cut.ensure(cut.firsts[2], cut.firsts[2])
        finally:
            FS.FSEQ._load_block = real_load
        bg(_fi_at(clk, 60, label="c0"))
        bg(_fi_at(clk, 60, label="c1"))
        said = [t for t in lines if "could not be cut here" in t]
        check(len(said) == 2, f"one line for each cue: {said}")
        bg.close()
    finally:
        FS.FSEQ._load_block = real_load
        F.threading.Thread = real_thread
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_onlyone_named_lock_sees_a_copy_in_another_folder():
    section("one copy: on Windows every lock is also a named kernel mutex, "
            "so a copy whose files were redirected into another app's "
            "container (MSIX, show PC 2026-10-04) still refuses while the "
            "first runs, and starts once it has stopped")
    import shutil
    import tempfile
    from ltcplay import onlyone as O
    import warnings
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        try:
            with open(O.__file__, encoding="utf-8") as f:
                compile(f.read(), O.__file__, "exec")
            check(True, "onlyone.py compiles with no warning")
        except SyntaxError as e:
            check(False, f"onlyone.py warns when compiled (a second copy "
                         f"prints it ahead of its refusal): {e}")
    held = {}

    def fake_create(name):
        n = held.get(name, 0)
        held[name] = n + 1
        return name, n > 0

    def fake_close(h):
        held[h] -= 1
        if not held[h]:
            del held[h]
    saved = (O.NAMED, O._create_named, O._close_named)
    O.NAMED, O._create_named, O._close_named = True, fake_create, fake_close
    a_dir, b_dir = tempfile.mkdtemp(), tempfile.mkdtemp()
    try:
        a = O.OutputLock(where=os.path.join(a_dir, O.SHOW_LOCK),
                         note="the app").acquire()
        try:
            O.OutputLock(where=os.path.join(b_dir, O.SHOW_LOCK),
                         note="from inside another app").acquire()
            check(False, "a copy whose lock file is elsewhere must refuse")
        except O.AlreadyRunning as e:
            check("another app" in str(e.holder),
                  f"it refuses, saying where the other may be: {e.holder}")
        check(held == {"ltcplay-" + O.SHOW_LOCK: 1},
              f"the refused copy let go of its handle: {held}")
        a.release()
        check(not held, "release lets go of the mutex")
        b = O.OutputLock(where=os.path.join(b_dir, O.SHOW_LOCK)).acquire()
        b.release()
        check(True, "once the first has stopped, the second starts")
        # The usual Windows case, both copies' files in the SAME folder
        # (windows-latest CI, 2026-10-04 and 10-07): the mutex refuses
        # first, and the refusal must still carry the running copy's own
        # note (pid, port, show), read from the lock file it holds.
        same = os.path.join(a_dir, O.SHOW_LOCK)
        a = O.OutputLock(where=same, note="the Run window, port 8765"
                         ).acquire()
        try:
            O.OutputLock(where=same, note="second").acquire()
            check(False, "a second copy in the same folder must refuse")
        except O.AlreadyRunning as e:
            check("Run window, port 8765" in e.holder,
                  f"the refusal names who is holding it: {e.holder!r}")
        with open(same, encoding="utf-8") as f:
            check("Run window" in f.read(),
                  "the refused copy left the holder's note alone")
        check(held == {"ltcplay-" + O.SHOW_LOCK: 1},
              f"the refused copy let go of its handle: {held}")
        a.release()
        b = O.OutputLock(where=same, note="after").acquire()
        b.release()
        check(not held, "and the same folder starts again once it stops")
    finally:
        O.NAMED, O._create_named, O._close_named = saved
        shutil.rmtree(a_dir, ignore_errors=True)
        shutil.rmtree(b_dir, ignore_errors=True)
    print("  ok")


def test_onlyone_named_lock_is_machine_wide_or_says_so():
    section("one copy: the named lock is made in Global\\ (every Windows "
            "session and user); another user's copy holding it reads as "
            "running; any other failure falls back to Local\\ and says so "
            "loudly (review of PR #38, P2, locked decision 21)")
    from ltcplay import onlyone as O
    made, warned = [], []

    def run(results, there=None):
        it = iter(results)
        cur = [None]

        def create(full):
            made.append(full)
            cur[0] = next(it)
            return cur[0][0]
        return O._named_mutex("ltcplay-x.lock", create,
                              lambda: cur[0][1], warn=warned.append,
                              exists=there)
    got = run([(77, 0)])
    check(got == (77, False) and made == ["Global\\ltcplay-x.lock"] and
          not warned, f"Global\\ first, and that is all: {got} {made}")
    del made[:]
    got = run([(77, O.ERROR_ALREADY_EXISTS)])
    check(got == (77, True), f"a copy in this session: running: {got}")
    del made[:]
    got = run([(0, O.ERROR_ACCESS_DENIED)], there=lambda full: True)
    check(got == (None, True) and made == ["Global\\ltcplay-x.lock"] and
          not warned,
          f"another user's copy (access denied, and the mutex is there) is "
          f"running, and never a reason to fall back to Local\\: {got} "
          f"{made}")
    del made[:]
    got = run([(0, O.ERROR_ACCESS_DENIED), (88, 0)],
              there=lambda full: False)
    check(got == (88, False) and made[-1] == "Local\\ltcplay-x.lock" and
          warned and "falls back to Local" in warned[-1],
          f"access denied with no such mutex anywhere (this account may not "
          f"make Global\\ names) is NOT a running copy: Local\\, loudly: "
          f"{got} {warned[-1:]}")
    del warned[:]
    del made[:]
    got = run([(0, 1450), (88, 0)])
    check(got == (88, False) and made[-1] == "Local\\ltcplay-x.lock" and
          warned and "falls back to Local" in warned[-1] and
          "would NOT be seen" in warned[-1] and "\u2014" not in warned[-1],
          f"any other failure falls back to Local\\, loudly: {got} "
          f"{warned[-1:]}")
    del warned[:]
    got = run([(0, 1450), (0, 1450)])
    check(got is None and len(warned) == 2,
          f"neither: the file lock alone, and said: {warned}")
    # The same lock file: the refusal is the running copy's own note (who,
    # the show, the port), not the named mutex's generic sentence.
    held = {}

    def fake_create(name):
        held[name] = held.get(name, 0) + 1
        return name, held[name] > 1

    def fake_close(h):
        held[h] -= 1
    saved = (O.NAMED, O._create_named, O._close_named)
    O.NAMED, O._create_named, O._close_named = True, fake_create, fake_close
    import shutil
    import tempfile
    d = tempfile.mkdtemp()
    try:
        first = O.OutputLock(where=os.path.join(d, O.SHOW_LOCK),
                             note="pid 4242: ltc serve, show Ignite").acquire()
        try:
            O.OutputLock(where=os.path.join(d, O.SHOW_LOCK)).acquire()
            check(False, "a second copy on the same lock file must refuse")
        except O.AlreadyRunning as e:
            check("Ignite" in str(e.holder) and "4242" in str(e.holder),
                  f"the refusal carries the running copy's note: "
                  f"{e.holder!r}")
        check(held.get("ltcplay-" + O.SHOW_LOCK) == 1,
              f"and the refused copy let go of its mutex handle: {held}")
        first.release()
    finally:
        O.NAMED, O._create_named, O._close_named = saved
        shutil.rmtree(d, ignore_errors=True)
    import warnings
    src = open(O.__file__, encoding="utf-8").read()
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        try:
            compile(src, O.__file__, "exec")
            check(True, "")
        except SyntaxError as e:
            check(False, f"onlyone.py compiles with no warning: {e}")
    # A lock whose mutex another user holds refuses, closing nothing.
    saved = (O.NAMED, O._create_named, O._close_named)
    closed = []
    O.NAMED, O._create_named, O._close_named = (
        True, lambda name: (None, True), closed.append)
    import shutil
    import tempfile
    d = tempfile.mkdtemp()
    try:
        try:
            O.OutputLock(where=os.path.join(d, O.SHOW_LOCK)).acquire()
            check(False, "a copy another user holds must refuse")
        except O.AlreadyRunning:
            check(not closed, "refused, with no handle to close")
    finally:
        O.NAMED, O._create_named, O._close_named = saved
        shutil.rmtree(d, ignore_errors=True)
    print("  ok")


def test_fire_ice_flame_link_from_flamesafe_config():
    section("fire & ice: the flame link is built from flamesafe's own "
            "config, its cues are the show's flame universe only while the "
            "flame controller is Inactive in xLights, and a screen Abort's "
            "disarm goes out through it")
    import json as _json
    import socket as _s
    import tempfile
    import types
    F = _fi_mod()
    from ltcplay import conductor as C
    work = tempfile.mkdtemp()
    lines = []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    # The config: refusals first.
    for doc, want in (({"auto_start": "yes"}, "auto_start"),
                      ({"flame_controller": "Flames"}, "flamesafe_config"),
                      ({"flamesafe_config": ""}, "flamesafe_config"),
                      ({"flamesafe_config": "x.json", "flame_controller": 3},
                       "flame_controller")):
        try:
            F.FireIceConfig.parse(doc, os.path.join(work, F.CONFIG_FILE))
            check(False, f"{doc} must be refused")
        except F.FireIceConfigError as e:
            check(want in str(e), f"{doc} refused naming {want}: {e}")
    cfg = F.FireIceConfig.parse({"flamesafe_config": "flamesafe.json",
                                 "flame_controller": "Flames"},
                                os.path.join(work, F.CONFIG_FILE))
    check(cfg.flamesafe_config == os.path.join(work, "flamesafe.json"),
          f"a relative flamesafe_config is beside the Fire & Ice config: "
          f"{cfg.flamesafe_config}")
    check(cfg.auto_start == "when_run_pressed",
          "auto_start defaults to PR #32's reading: once Run is pressed")
    # The flame channels.
    fs, show, fsdoc = _fi_flame_files(work)
    check(F.flame_channels(os.path.join(show, "xlights_networks.xml"),
                           "Flames") == (511, 512),
          "the flame controller's channels, walked in xLights' order")
    _fi_flame_files(work, state="Active")
    try:
        F.flame_channels(os.path.join(show, "xlights_networks.xml"),
                         "Flames")
        check(False, "an Active flame controller must be refused")
    except F.FlameControllerError as e:
        check("Inactive" in str(e) and "around" in str(e),
              f"an Active flame controller is refused, saying why: {e}")
    # FlameCues, on a fake running session, reading the show's OWN render
    # (PR #43 review, finding 1): never the pixel output's buffer.
    import test_show_fixtures as _fx

    def fill_for(frame):
        return frame & 0xFF
    render = os.path.join(show, "Show.fseq")
    _fx.write_fseq(render, frame_count=400, channel_count=1022, step_ms=25,
                   compression="zlib", block_frames=100, fill=fill_for)
    clk = types.SimpleNamespace(source="audio_master", paused=False,
                                _cue={"label": "Show", "position_s": 3600.0},
                                last_sent=(0, 0, 2, 15))
    player = types.SimpleNamespace(override=None, freerun_epoch=None,
                                   _buf=bytearray([99]) * 1022)
    cue = types.SimpleNamespace(name="Show", path=render, tc_seconds=3600.0)
    sess = types.SimpleNamespace(running=True, clock=clk, player=player,
                                 tl=types.SimpleNamespace(show_dir=show,
                                                          cues=[cue]))
    control = types.SimpleNamespace(session=sess)
    cues = F.FlameCues(control, "Flames", journal)
    check(cues("00:00:02:15") is None and
          any(f and "Inactive" in t for t, f in lines),
          "Active controller: all zeros, and a fault line")
    n_faults = sum(1 for _t, f in lines if f)
    cues("00:00:02:15")
    check(sum(1 for _t, f in lines if f) == n_faults,
          "the same refusal is journaled once, not every frame")
    fs, show, fsdoc = _fi_flame_files(work, state="Inactive")
    sess.tl.show_dir = show + os.sep + "."
    # The layout file was just rewritten; the render is the one made for it
    # (a render older than the layout is refused: review of PR #43, P0-6).
    _lay = os.stat(os.path.join(show, "xlights_networks.xml")).st_mtime_ns
    os.utime(render, ns=(_lay, _lay + 10 ** 9))
    # 2.5 s into the cue is frame 100 of a 25 ms render.
    vals = cues("00:00:02:15")
    check(vals == [100] * 512,
          f"Inactive controller: the flame universe of the show's own frame "
          f"at the show timecode, not the pixel buffer: {vals and vals[:4]}")
    clk.last_sent = (0, 0, 3, 0)
    check(cues("00:00:03:00") == [120] * 512, "and it follows the timecode")
    check(cues("00:00:02:15") is None,
          "a timecode that is not the clock's own current frame: zeros")
    for look in ("blackout", "preshow", "some look"):
        player.override = look
        check(cues("00:00:03:00") is None,
              f"the pixel output on {look}: zeros")
    player.override = None
    player.freerun_epoch = 12.0
    check(cues("00:00:03:00") is None, "a GO free run: zeros")
    player.freerun_epoch = None
    clk.paused = True
    check(cues("00:00:03:00") is None, "show audio paused: zeros")
    clk.paused = False
    clk._cue = {"label": "Preshow loop", "position_s": 0.0}
    check(cues("00:00:03:00") is None,
          "the show audio playing something that is not a cue of the show "
          "file: zeros")
    clk._cue = {"label": "Show", "position_s": 3600.0}
    clk.last_sent = (0, 0, 59, 0)
    check(cues("00:00:59:00") is None, "past the render's end: zeros")
    clk.last_sent = (0, 0, 3, 0)
    check(cues("00:00:03:00") == [120] * 512, "and back")
    check(F.FlameCues(control, "Nope", journal)("00:00:03:00") is None,
          "a controller that is not there: all zeros")
    sess.running = False
    check(cues("00:00:03:00") is None, "nothing running: all zeros")
    sess.running = True
    cues.close()
    # build_flame_link: the real FlameLink, key and port from flamesafe's
    # own file, and the Abort's disarm reaches the wire.
    show_out = F.FireIceShow(control, journal=journal, flame_link=None)
    link = F.build_flame_link(F.FireIceConfig(flamesafe_config=fs,
                                              flame_controller="Flames"),
                              control, show_out, journal)
    try:
        check(link.cfg.key == fsdoc["link"]["key"] and
              link.cfg.port == fsdoc["link"]["listen_port"] and
              link.cfg.frame_stale_ms == fsdoc["frame_stale_ms"],
              "key, port and frame_stale_ms come from flamesafe's config")
        link.journal_line.flush()
        check(any("Stream Deck" in t for t, _ in lines),
              "it says it cannot see flamesafe's status frames itself")
        rx = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
        rx.bind(("127.0.0.1", link.cfg.port))
        rx.settimeout(2.0)
        try:
            link.open()
            show_out.flame_link = link
            r = show_out.flames_disarm_all("Abort pressed on the rack screen")
            check(r.ok, f"the screen Abort's disarm went out: {r}")
            kinds = []
            try:
                for _ in range(6):
                    kinds.append(_json.loads(rx.recv(70000))["t"])
            except _s.timeout:
                pass
            check("flame" in kinds and "disarm_all" in kinds,
                  f"a zero frame, then disarm_all, on the wire: {kinds}")
        finally:
            rx.close()
    finally:
        link.stop()
    # Missing flamesafe config: serve refuses to start, in words.
    try:
        F.build_flame_link(F.FireIceConfig(
            flamesafe_config=os.path.join(work, "nope.json")), control,
            show_out, journal)
        check(False, "a flamesafe_config that cannot be read must refuse")
    except F.FireIceConfigError as e:
        check("nope.json" in str(e), f"refused naming the file: {e}")
    _ = C
    print("  ok")


def test_fire_ice_status_mirror_reaches_the_flame_link():
    section("fire & ice with the remote (PR #39): flamesafe's status_mirror_"
            "port reaches the flame link that `ltc serve` built, so it sees "
            "flamesafe confirm a disarm; the remote's Disarm every flame "
            "group goes through that same link; the seek guard is on, at "
            "the show file's frame rate")
    import json as _json
    import socket as _s
    import tempfile
    import types
    from ltcplay import web as web_mod
    from ltcplay import schedule_service as SV
    F = _fi_mod()
    work = tempfile.mkdtemp()
    fs, show, doc = _fi_flame_files(work)
    doc["link"]["status_mirror_port"] = _free_udp_port()
    with open(fs, "w", encoding="utf-8") as fh:
        _json.dump(doc, fh)
    rule = os.path.join(work, SV.RULE_FILE)
    SV.save_rule(rule, _sched_doc())
    svc = SV.Service(rule, state_dir=work, ntp_query=lambda: 0.0)
    cfg = F.FireIceConfig(flamesafe_config=fs, flame_controller="Flames")
    httpd = web_mod.serve(work, port=_free_port(), schedule=svc,
                          fire_ice=cfg, flamesafe_config=fs)
    try:
        link = httpd.fire_ice.flame_link
        check(link is not None, "ltc serve built the flame link")
        # The laser arm (Jeff, 2026-10-22): built with the Morning page and
        # handed to the conductor's wiring, BEYOND's output switch reached
        # through the conductor's own Blanking.
        la = getattr(httpd.morning, "laser_arm", None)
        check(la is not None and httpd.fire_ice.laser_arm is la and
              la.on_permitted == httpd.conductor.lasers_armed and
              la._output_obj() is httpd.fire_ice.devices.beyond and
              la.blank_now is not None and la.armed_ids() == [],
              "ltc serve hands the Morning page's laser arm (every laser "
              "disarmed) to the conductor, through its own Blanking")
        check(httpd.fire_ice.devices.beyond._arm_refusal() is not None and
              httpd.conductor.lasers_disarm is not None,
              "the Blanking asks the arm (nothing armed: no), and Abort and "
              "Hold reach it")
        check(getattr(link, "seek_guard", False) is True,
              "the seek guard is on for the real flame cues")
        check(getattr(link.cues, "_bg", False) is True,
              "ltc serve's flame cues read files on their own thread, never "
              "the sender's")
        check(getattr(link, "status_mirrored", None) is True,
              "with a status mirror the link expects flamesafe to confirm "
              "a disarm, so an unconfirmed one is a fault")
        rows = [r for r in svc.journal if r.get("outcome") == "no_status"]
        check(not rows, f"with a status mirror it does not say it cannot "
                        f"see flamesafe: {rows}")
        rows = [r for r in svc.journal
                if r.get("outcome") == "status_mirror"]
        check(rows, "it says it reads flamesafe through the status mirror")
        # Review H7: serve starts the link's sender thread, not only opens
        # it: frames go out on their own.
        sent0 = link.sent
        deadline = time.time() + 3
        while time.time() < deadline and link.sent < sent0 + 5:
            time.sleep(0.02)
        check(link.sender_state() == "running" and link.sent >= sent0 + 5,
              f"ltc serve started the flame link's sender: "
              f"{link.sender_state()} {link.sent - sent0} frames")
        r = httpd.remote.disarm_all("Andy", "rack screen")
        check(getattr(link, "abort_state")() ==
              "sent, not yet confirmed by flamesafe",
              f"the remote's Disarm every flame group went through the "
              f"flame link: {r} {link.abort_state()}")
        tx = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
        try:
            # Review H4: a frame keyed with anything but flamesafe's key
            # never reaches the flame link (it could confirm a disarm).
            forged = {"v": 2, "t": "status", "k": "not-flamesafes-key",
                      "frames": {"seq": link.seq},
                      "disarm_all": {"last_id": link.abort_id}}
            for _ in range(10):
                tx.sendto(_json.dumps(forged).encode(),
                          ("127.0.0.1", doc["link"]["status_mirror_port"]))
                time.sleep(0.05)
            check(link.abort_state() != "confirmed by flamesafe",
                  f"a status frame with another key confirms nothing: "
                  f"{link.abort_state()}")
            frame = {"v": 2, "t": "status", "k": doc["link"]["key"],
                     "frames": {"seq": link.seq},
                     "disarm_all": {"last_id": link.abort_id}}
            deadline = time.time() + 5
            while time.time() < deadline and \
                    link.abort_state() != "confirmed by flamesafe":
                tx.sendto(_json.dumps(frame).encode(),
                          ("127.0.0.1", doc["link"]["status_mirror_port"]))
                time.sleep(0.05)
        finally:
            tx.close()
        check(link.abort_state() == "confirmed by flamesafe",
              f"flamesafe's confirmation reached the flame link through the "
              f"mirror: {link.abort_state()}")
        # The seek guard counts the show audio's own timecode frames, 30 a
        # second (clock.MASTER_FPS), whatever the show file's rate.
        check(link.tc_fps == 30.0,
              f"the seek guard reads the show audio's 30 fps timecode: "
              f"{link.tc_fps}")
        httpd.control.session = None
    finally:
        svc.halt()
        svc.stop()
        httpd.server_close()
    print("  ok")


def test_fire_ice_stop_and_hold_before_the_show_is_confirmed():
    section("fire & ice: a Stop or Hold pressed after a show cue started "
            "but before SHOW_CONFIRMED stops or freezes the music, even when "
            "an earlier Stop or failed start recorded it stopped (PR #43 "
            "review, item 4)")
    for press in ("stop", "hold", "failed start"):
        n = _fi_night()
        if n.S is None:
            return
        n.svc.tick()
        # Where a failed start (or a Stop) leaves the record.
        n.c.failed_start("the scheduler")
        n.c.run_pending()
        check(n.c.snapshot()["applied"]["music"] == "stopped",
              "setup: the record says the music is stopped")
        r = n.w.runner.start_show(7, who="Andy")
        check(r.ok, f"the cue started: {r}")
        check(n.c.snapshot()["applied"]["music"] == "playing",
              f"once the cue is started the conductor knows the music is "
              f"playing: {n.c.snapshot()['applied']}")
        del n.calls[:]
        if press == "stop":
            n.c.stop("Andy", "Rack screen")
            want = "music_halt"
        elif press == "hold":
            n.c.hold("Andy", "Rack screen")
            want = "music_hold"
        else:
            n.c.failed_start("the scheduler")
            want = "music_halt"
        n.c.run_pending()
        got = [k for k, _a, _t in n.calls]
        check(want in got, f"{press} before SHOW_CONFIRMED: {want} sent to "
                           f"the show audio: {got}")
        n.c.close()
        n.link.close()
    # A Stop that lands while the cue is starting: its music step may have
    # run before the cue began, so the runner stops the music itself.
    n = _fi_night()
    n.svc.tick()
    n.c.failed_start("the scheduler")
    n.c.run_pending()
    real = n.sess.clock_play

    def play_then_stop(cue=None):
        out = real(cue)
        n.c.stop("Andy", "Rack screen")
        n.c.run_pending()
        return out
    n.sess.clock_play = play_then_stop
    del n.calls[:]
    r = n.w.runner.start_show(8, who="Andy")
    got = [k for k, _a, _t in n.calls]
    check(not r.ok and "Stop was pressed while it was starting" in
          r.sentence and
          got.index("music_play") < len(got) - 1 - got[::-1].index(
              "music_halt"),
          f"a Stop during the start: the music is stopped after it began, "
          f"and the start is reported failed: {r.sentence} {got}")
    n.c.close()
    n.link.close()
    print("  ok")


def test_fire_ice_show_log_is_written_off_the_logging_threads():
    section("fire & ice: the show log is written on a thread of its own, so "
            "the timecode thread never writes, flushes or prints a line, nor "
            "waits on the logging lock; the GPL show log is unchanged (PR "
            "#43 review, item 9)")
    import io
    import json as _json
    import logging.handlers as LH
    import shutil
    import tempfile
    import threading
    import types
    from ltcplay import showlog
    from ltcplay.session import Session, SessionError
    F = _fi_mod()
    work = tempfile.mkdtemp()
    real_emit = LH.RotatingFileHandler.emit
    real_stdout = sys.stdout
    try:
        # The GPL path: written before event() returns, as always.
        gpl = showlog.ShowLog(os.path.join(work, "gpl.log"))
        gpl.event("clock", "one")
        check("one" in open(os.path.join(work, "gpl.log"),
                            encoding="utf-8").read() and
              not getattr(gpl, "background", False),
              "GPL: the line is in the file when event() returns")
        # Background: a file write that takes 300 ms, and a console that
        # does too, never hold up the thread that logs.
        slow = threading.Event()

        def slow_emit(self, record):
            slow.wait(0.3)
            return real_emit(self, record)
        LH.RotatingFileHandler.emit = slow_emit

        class SlowOut(io.StringIO):
            def write(self, x):
                slow.wait(0.3)
                return super().write(x)
        out = SlowOut()
        sys.stdout = out
        bg = F.BackgroundShowLog(os.path.join(work, "fi.log"), echo=True)
        took = []
        for i in range(5):
            t0 = time.perf_counter()
            bg.event("timecode", f"line {i}")
            took.append(time.perf_counter() - t0)
        check(max(took) < 0.05,
              f"logging with a 300 ms file and console never waits: "
              f"{[round(x * 1000) for x in took]} ms")
        slow.set()
        bg.flush()
        sys.stdout = real_stdout
        text = open(os.path.join(work, "fi.log"), encoding="utf-8").read()
        check([f"line {i}" in text for i in range(5)] == [True] * 5 and
              text.index("line 0") < text.index("line 4"),
              "every line reaches the file, in order, once flushed")
        check("line 4" in out.getvalue(),
              "and the console echo is written by the writer thread")
        LH.RotatingFileHandler.emit = real_emit
        # Fire & Ice asks for it; the session passes it on.
        n = _fi_night()
        if n.S is None:
            return
        control = types.SimpleNamespace(session=None)
        F.attach(n.svc, control, F.FireIceConfig(beyond_blank="osc"), threaded=False,
                 clock=n.T.now, waiter=n.T.wait)
        check(control.defaults.get("log_factory") is F.BackgroundShowLog,
              f"Fire & Ice sessions log in the background: "
              f"{control.defaults}")
        n.c.close()
        show = os.path.join(work, "show")
        os.makedirs(show)
        with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
            fh.write(_FI_NETWORKS.replace("{state}", "Inactive"))
        tlp = os.path.join(work, "t_timeline.json")
        with open(tlp, "w") as fh:
            _json.dump({"name": "t", "fps": 30, "show_dir": show,
                        "cues": [{"tc": "01:00:00:00", "fseq": "None.fseq",
                                  "name": "Show"}]}, fh)
        for factory in (None, F.BackgroundShowLog):
            sess = Session(tlp, no_output=True, sd=FakeSD(), device="MOTU M4",
                           channel=1, log_path=os.path.join(
                               work, f"s{int(bool(factory))}.log"),
                           log_factory=factory)
            try:
                sess.open()
            except SessionError:
                pass
            want = factory or showlog.ShowLog
            check(sess.log is not None and type(sess.log) is want,
                  f"the session's show log is a {want.__name__}: "
                  f"{type(sess.log).__name__}")
    finally:
        LH.RotatingFileHandler.emit = real_emit
        sys.stdout = real_stdout
        # Leave the logger the way a GPL run has it.
        showlog.ShowLog(os.path.join(work, "last.log"))
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def _one_show_work(S, shows=1):
    """A work folder whose rule has `shows` scheduled shows on Saturday
    from 18:00, 20 minutes apart, so the last one closes the night."""
    import tempfile
    from ltcplay import schedule_service as SV
    work = tempfile.mkdtemp()
    end = {1: "18:10", 2: "18:30"}[shows]
    SV.save_rule(os.path.join(work, SV.RULE_FILE), _sched_doc(
        weekly={"sat": {"first_start": "18:00", "interval_min": 20,
                        "last_end": end}}, exceptions={}))
    return work


def _px_ends_on_its_own(n):
    """The running show's cue confirms, then finishes by itself; the runner
    reports both and sees what the night does next (a closing, if any)."""
    clk = n.sess.clock
    n.sess.player.first_frame()
    clk._last_frame = 30
    n.w.runner.poll()
    _settle(n.svc, n.c)
    clk.playing = False
    clk.last_ended = "Show finished"
    n.w.runner.poll()
    _settle(n.svc, n.c)
    n.w.runner.poll()           # CLOSING, when it closes the night
    _settle(n.svc, n.c)
    n.w.runner.poll()
    _settle(n.svc, n.c)


def _px_cues_why(n):
    """What the show's flame cues say right now, through the real
    FlameCues, with the fake show audio playing its cue."""
    F = n.F
    clk = n.sess.clock
    clk._cue, clk.paused = {"label": "Show"}, False
    cues = F.FlameCues(n.control, "flames")
    cues(None)
    return cues._why


def _px_start_line(n, what):
    return [t for t, _f in n.lines
            if t.startswith(what) and "is cleared for the show" in t]


def test_every_show_start_clears_the_pixels():
    section("pixels: every show start (Start now, a scheduled start, the "
            "Programming screen's Play) clears whatever dark the last show "
            "left (the closing black after a show that ended on its own, a "
            "stale record of it, Stop and Resume), with the same "
            "journal line; a Start now show ends on the idle look; a look "
            "on the pixels during a show is a CUES FAULT (Jeff's report, "
            "2026-10-29)")
    import types
    S = _sched()
    if S is None:
        return
    # A: the night's last scheduled show ends on its own: the closing
    # blacks the pixels, outside the conductor.
    n = _fi_night(work=_one_show_work(S))
    n.svc.tick()
    n.now[0] = _den(S, 18, 0)
    n.svc.tick()
    _settle(n.svc, n.c)
    check(n.svc.machine.state == S.SHOW and
          _px_start_line(n, "Show 1 start"),
          f"setup: show 1 started on schedule with the start's pixel "
          f"line: {n.svc.machine.state}")
    n.now[0] = _den(S, 18, 8)
    _px_ends_on_its_own(n)
    check(n.svc.machine.state in (S.CLOSING, S.OFF) and
          n.sess.player.override == "blackout" and n.w.show._pix_ours,
          f"setup: the last scheduled show ended on its own and the "
          f"closing blacked the pixels: {n.svc.machine.state} "
          f"{n.sess.player.override!r}")
    # Start now: the black is taken off by the start itself, held until
    # the first show frame, then the show; the flame cues are never
    # refused for it.
    n.now[0] = _den(S, 18, 20)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    m = n.svc.machine
    held = n.sess.player.override
    n.sess.player.first_frame()
    check(m.state == S.SHOW and held == "blackout" and
          n.sess.player.override is None and not n.w.show._pix_ours,
          f"Start now after a show that ended on its own: the closing "
          f"black stays only until the first show frame, then the show "
          f"(Jeff's shows 4 and 6): {m.state} {held!r} "
          f"{n.sess.player.override!r}")
    line = _px_start_line(n, f"Show {m.running} start")
    check(line and "the show conductor's black" in line[-1],
          f"the start's own journal line says what it cleared: {line}")
    n.w.runner.poll()
    check(any("first show frame went out" in t for t, _f in n.lines),
          "the journal says when the first show frame went out")
    check("blackout" not in _px_cues_why(n),
          "the flame cues are not refused for a blackout after the start")
    n.sess.clock._cue = None
    # C: that Start now show ends on its own: the night closes again, but
    # the pixels stay on the idle look, like a scheduled show's end.
    del n.lines[:]
    _px_ends_on_its_own(n)
    check(n.svc.machine.state in (S.CLOSING, S.OFF) and
          n.sess.player.override is None and not n.w.show._pix_ours and
          any("stay on the idle look" in t for t, _f in n.lines),
          f"a Start now show that ends on its own ends on the idle look, "
          f"not on black: {n.svc.machine.state} "
          f"{n.sess.player.override!r}")
    # D: and Start now again starts with pixels, with the same line.
    n.now[0] = _den(S, 18, 40)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    m = n.svc.machine
    check(m.state == S.SHOW and n.sess.player.override is None and
          _px_start_line(n, f"Show {m.running} start"),
          f"Start now again after a Start now show ended: pixels on the "
          f"show, the same line: {m.state} {n.sess.player.override!r}")
    # Stop: the show conductor's black; Start now clears it.
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)
    check(n.sess.player.override == "blackout",
          f"setup: Stop blacked the pixels: {n.sess.player.override!r}")
    n.now[0] = _den(S, 18, 50)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    check(n.svc.machine.state == S.SHOW and n.sess.player.override is None,
          f"Start now after Stop: the show plays as rendered: "
          f"{n.sess.player.override!r}")
    # Stop, Resume, Start now.
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)
    n.svc._apply(_op(S, S.RESUME))
    _settle(n.svc, n.c)
    check(n.svc.machine.state == S.STANDBY,
          f"setup: the Stop's Hold was Resumed: {n.svc.machine.state}")
    n.now[0] = _den(S, 19, 0)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    check(n.svc.machine.state == S.SHOW and n.sess.player.override is None,
          f"Start now after Stop and Resume: the show plays as rendered: "
          f"{n.svc.machine.state} {n.sess.player.override!r}")
    # A Hold before the first show frame, then Resume: the show comes
    # back, never the black held at the start. The Stop really runs its
    # fade (the start before it put the conductor's pixels record to
    # UNKNOWN), so the look the start holds is black, not the idle look.
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)
    check(n.sess.player.override == "blackout" and n.w.show._pix_ours,
          f"setup: the Stop after a start ran its own black, not left to "
          f"the record of the Stop before: {n.sess.player.override!r}")
    n.now[0] = _den(S, 19, 10)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    check(n.sess.player.show_handoff is not None and
          n.sess.player.show_handoff[0] == "blackout",
          f"setup: the start holds the Stop's black until its first frame: "
          f"{n.sess.player.show_handoff!r}")
    n.svc._apply(_op(S, S.HOLD))            # the real Hold, mid start
    _settle(n.svc, n.c)
    n.sess.player.first_frame()             # no hand-over: Hold stands
    held = n.sess.player.override
    n.svc._apply(_op(S, S.RESUME))
    _settle(n.svc, n.c)
    check(held == "blackout" and n.sess.player.override is None,
          f"a Hold before the first show frame holds, and Resume gives "
          f"back the show, not the start's held black: {held!r} "
          f"{n.sess.player.override!r}")
    n.c.close()
    n.link.close()
    # The stale record (Jeff's show 5): the conductor's black on record,
    # the idle look on the output: nothing is put to black at the start.
    n = _fi_night()
    n.svc.tick()
    n.w.show._pix_ours, n.w.show._pix_prev = True, None
    del n.calls[:]
    n.now[0] = _den(S, 18, 0)
    n.svc.tick()
    _settle(n.svc, n.c)
    check(("pixels", ("blackout",)) not in [(k, a) for k, a, _t in n.calls]
          and not n.w.show._pix_ours,
          f"a stale record of the conductor's black never blacks the idle "
          f"look at the start: {[c for c in n.calls if c[0] == 'pixels']}")
    line = _px_start_line(n, "Show 1 start")
    check(line and "stale record" in line[-1] and
          "The idle look stays up until the first show frame" in line[-1],
          f"its journal line: {line}")
    # Manual, ended on its own, then the scheduled start.
    n.c.close()
    n.link.close()
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.now[0] = _den(S, 17, 48)
    _px_ends_on_its_own(n)
    check(n.sess.player.override is None,
          f"setup: a Start now show with shows to come ends on the idle "
          f"look: {n.svc.machine.state} {n.sess.player.override!r}")
    n.w.show._pix_ours = True              # however it got there
    n.sess.player.override = "blackout"
    n.now[0] = _den(S, 18, 0)
    n.svc.tick()
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    m = n.svc.machine
    check(m.state == S.SHOW and n.sess.player.override is None and
          _px_start_line(n, f"Show {m.running} start"),
          f"the scheduled start after a Start now show clears the black: "
          f"{m.state} {n.sess.player.override!r}")
    # Programming Play after the closing black.
    from ltcplay.playhead import ShowAudioPlayhead
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)
    n.svc.machine = types.SimpleNamespace(state="OFF")
    clk = n.sess.clock
    n.sess.playhead_clock = lambda: clk
    n.sess.clock_play_from = lambda s, check_only=False: (
        (types.SimpleNamespace(name="Show"), s) if check_only else
        (clk.play("Show"), (types.SimpleNamespace(name="Show"), s))[1])
    n.sess.clock_here = lambda: 0.0
    ph = ShowAudioPlayhead(n.control, n.svc)
    n.w.show.pixels_fade_out(1.0)           # the closing's black
    ph.play_from(3600.0, "Andy", "iPad")
    n.c.run_pending()
    n.sess.player.first_frame()
    check(n.sess.player.override is None and
          _px_start_line(n, "Play from on the Programming screen"),
          f"Programming Play after the closing black: the show plays as "
          f"rendered, with the start's line: {n.sess.player.override!r}")
    # On the Programming screen the page's own look stays.
    n.sess.player.override = "preshow"
    ph.play_from(3600.0, "Andy", "iPad")
    n.c.run_pending()
    check(n.sess.player.override == "preshow",
          "Programming Play keeps a look the operator put on the page")
    n.c.close()
    n.link.close()
    # The pre-roll never puts a look on the pixel output.
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "ltcplay", "preroll.py")) as fh:
        pre = fh.read()
    check(".override" not in pre and "pixels_fade_out" not in pre,
          "the pre-roll blacks MadMapper's surfaces, never the pixels")
    # 4: a look on the pixels while the show plays is a CUES FAULT once it
    # lasts, never during a Hold's or an Abort's own fade or a start's
    # hand-over.
    F = _fi_mod()
    t = [0.0]
    clk = types.SimpleNamespace(source="audio_master", _cue={"label": "S"},
                                paused=False, _halting=False,
                                _pause_req=False, last_sent=None)
    p = types.SimpleNamespace(override="blackout", show_handoff=None,
                              freerun_epoch=None)
    sess = types.SimpleNamespace(running=True, clock=clk, player=p)
    lines = []
    cues = F.FlameCues(types.SimpleNamespace(session=sess), "flames",
                       journal=lambda text, **f: lines.append((text, f)))
    cues._mono = lambda: t[0]
    cues(None)
    check(cues.fault == "", "a look over a playing show is not a fault at "
                            "once")
    t[0] = F.LOOK_IN_SHOW_FAULT_S + 0.1
    cues(None)
    check(cues.faults_now() == F.LOOK_IN_SHOW.format(look="black") and
          lines and lines[-1][1].get("fault"),
          f"once it lasts it is a CUES FAULT on the screens and in the "
          f"journal: {cues.fault!r}")
    # The rack screen's words (reviews of PR #171): only buttons the Fire
    # & Ice screen has (Stop on the Show file card, then Run), never the
    # GPL page's Black, Preshow or Auto, nor the Programming card's "Follow timecode again" / "Stop the show audio";
    # short as a whole, no sentence over eight words; "black", never
    # "blackout".
    said = cues.faults_now()
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "ltcplay", "web", "remote2.html"),
              encoding="utf-8") as fh:
        rack2 = fh.read()
    # 2.0's Schedule tab: from its pane to the next one.
    sched2 = rack2[rack2.find('id="t-schedule"'):]
    sched2 = sched2[:sched2.find('<section class="pane"')]
    check("Programming: End rehearsal, then Start rehearsal." in said and
          "On 2.0: the Schedule tab's Show file card." in said and
          "Open in 1.0" not in said and len(said.split()) <= 30 and
          '<div class="card col" id="p-run-card" hidden>' in sched2 and
          "<b>Show file, on this machine</b>" in sched2
          and "Follow timecode" not in said and "Auto" not in said and
          "Black" not in said and "blackout" not in said and
          "show audio" not in said and
          all(len(x.split()) <= 8 for x in said.split(". ")),
          f"the CUES FAULT says what to press on the rack screen: "
          f"{said!r}")
    # A look over the LAST show never counts toward the next one: no show
    # playing (between shows) starts the count again.
    clk._cue = None
    t[0] = 2.0
    cues(None)
    t[0] = 3.0
    clk._cue = {"label": "S"}
    cues(None)
    check(cues.fault == "", "a look between shows is no CUES FAULT for "
                            "the next show at once")
    t[0] = 3.0 + F.LOOK_IN_SHOW_FAULT_S + 0.1
    cues(None)
    check(cues.fault != "", "it is, once it lasts into that show")
    clk._cue = None
    cues(None)
    clk._cue = {"label": "S"}
    clk._halting = True
    cues(None)
    check(cues.fault == "", "an Abort's own fade is no CUES FAULT")
    clk._halting, p.show_handoff = False, ("blackout", 0)
    t[0] = 10.0
    cues(None)
    t[0] = 20.0
    cues(None)
    check(cues.fault == "", "a start's hand-over is no CUES FAULT")
    print("  ok")


def test_closed_night_stop_says_what_it_did():
    section("pixels: in a closed night (after a Start now show) there is no "
            "Abort route (removed, Jeff, 2026-10-30); Stop is a complete "
            "halt that disarms the flames and ends no show, and says so "
            "truthfully (OPERATOR.md, review of PR #171)")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S, at=_den(S, 23, 30))
    try:
        check(R.svc.machine.state == S.OFF, f"setup: the night is closed: "
                                            f"{R.svc.machine.state}")
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        check(st == 404 and not R.lines_for("abort disarm") and
              not hasattr(R.svc.machine, "abort_latched") and not hasattr(R.c, "latched"),
              f"there is no Abort route: nothing done, nothing latched: "
              f"{st} {out}")
        before = len(list(R.svc.journal))
        st, _h, out = R.ask("POST", "/api/remote/stop", {})
        R.settle()
        rows = R.lines_for("stop")
        new = list(R.svc.journal)[before:]
        check(rows and ": a complete halt." in rows[-1]["text"] and
              "show" not in out and
              (out.get("flames") or {}).get("disarmed") is True and
              not any("No show is running" in str(r.get("text"))
                      for r in new),
              f"Stop with no show is journaled as a complete halt and ends "
              f"no show (no 'No show is running' line): {out} "
              f"{rows[-1:]}")
    finally:
        R.close()
    print("  ok")


def _px_after_stop(S, ff=False):
    """A night with a Start now show, then Stop, then Start now again,
    with nothing confirmed yet; `ff`: its first frame has gone out (the
    0.1 to 0.3 s before SHOW_CONFIRMED)."""
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)
    check(n.sess.player.override == "blackout",
          f"setup: Stop blacked the pixels: {n.sess.player.override!r}")
    n.now[0] = _den(S, 17, 45)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    check(n.svc.machine.state == S.SHOW and
          n.sess.player.show_handoff is not None,
          f"setup: the start is waiting for its first frame: "
          f"{n.svc.machine.state} {n.sess.player.show_handoff!r}")
    if ff:
        n.sess.player.first_frame()
        check(n.sess.player.override is None,
              "setup: the first show frame went out, not confirmed yet")
    return n


def test_hold_and_stop_black_the_pixels_after_a_start():
    section("pixels: after a Stop and a new start, "
            "a Hold, a Stop or a failed start, before the first "
            "show frame or before the show is confirmed, still puts the "
            "pixels to black through the real show conductor (review of "
            "PR #171)")
    import types
    from ltcplay import conductor as C
    S = _sched()
    if S is None:
        return
    for ff in (False, True):
        when = ("between the first frame and the confirmation" if ff
                else "before the first show frame")
        n = _px_after_stop(S, ff)
        n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        _settle(n.svc, n.c)
        n.sess.player.first_frame()
        check(n.sess.player.override == "blackout" and
              n.sess.player.show_handoff is None,
              f"a second Stop {when}: the pixels are black, never the "
              f"show: {n.sess.player.override!r}")
        n.svc._apply(_op(S, S.RESUME))
        _settle(n.svc, n.c)
        n.sess.player.first_frame()
        check(n.sess.player.override == "blackout",
              f"and after Resume the pixels stay dark until a show starts: "
              f"{n.sess.player.override!r}")
        n.c.close()
        n.link.close()
        n = _px_after_stop(S, ff)
        n.svc._apply(_op(S, S.HOLD))
        _settle(n.svc, n.c)
        n.sess.player.first_frame()
        check(n.svc.machine.state == S.PAUSED and
              n.sess.player.override == "blackout",
              f"Hold {when}: the pixels are black, never the show: "
              f"{n.svc.machine.state} {n.sess.player.override!r}")
        n.c.close()
        n.link.close()
        n = _px_after_stop(S, ff)
        n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
        _settle(n.svc, n.c)
        n.sess.player.first_frame()
        check(n.sess.player.override == "blackout" and
              n.sess.player.show_handoff is None,
              f"Stop {when}: the pixels are black, never the show: "
              f"{n.sess.player.override!r}")
        n.c.close()
        n.link.close()
    # A failed start after a Stop ends on black, not on the idle look.
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.player.first_frame()
    n.svc._apply(_op(S, S.STOP_SHOW, confirmed=True))
    _settle(n.svc, n.c)

    def no_audio(cue=None):
        raise RuntimeError("the show audio is not there")
    n.sess.clock_play = no_audio
    n.now[0] = _den(S, 17, 45)
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    for _ in range(3):
        n.w.runner.poll()
        _settle(n.svc, n.c)
    n.sess.player.first_frame()
    check(n.sess.player.override == "blackout" and
          n.sess.player.show_handoff is None,
          f"a failed start after a Stop ends on black, with no hand-over "
          f"left: {n.svc.machine.state} {n.sess.player.override!r}")
    # The start itself puts its hand-over back when the clock refuses it,
    # before the conductor's failed start runs.
    n.sess.player.override = None
    n.w.show._pix_ours = False
    n.sess.player.show_handoff = None
    r = n.w.runner.start_show(9, who="Andy")
    check(not r.ok and n.sess.player.override == "blackout" and
          n.sess.player.show_handoff is None,
          f"a start the clock refused ends its own hand-over on black: "
          f"{n.sess.player.override!r} {n.sess.player.show_handoff!r}")
    n.c.close()
    n.link.close()
    # A Stop that lands while the cue is starting: the start puts the
    # black back itself, before the Stop's own fade runs.
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    real = n.sess.clock_play

    def stopped_meanwhile(cue=None):
        got = real(cue)
        n.c.stop("Andy", "Rack screen")
        return got
    n.sess.clock_play = stopped_meanwhile
    r = n.w.runner.start_show(9, who="Andy")
    check(not r.ok and n.sess.player.override == "blackout" and
          n.sess.player.show_handoff is None,
          f"a Stop while the cue was starting: black at once, no "
          f"hand-over: {n.sess.player.override!r} "
          f"{n.sess.player.show_handoff!r}")
    n.c.close()
    n.link.close()
    # A Stop just before the hand-over (as the removed Abort's latch did):
    # nothing goes out, the music never starts, the black stands.
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    to_show = n.c.pixels_to_show

    def stop_first(clear):
        n.sess.clock.playing = True         # an earlier cue still going
        n.c.stop("Andy", "Rack screen")
        n.c.run_pending()
        return to_show(clear)
    n.c.pixels_to_show = stop_first
    del n.calls[:]
    r = n.w.runner.start_show(9, who="Andy")
    n.sess.player.first_frame()
    check(not r.ok and "music_play" not in [k for k, _a, _t in n.calls] and
          n.sess.player.override == "blackout" and
          n.sess.player.show_handoff is None,
          f"a Stop just before the hand-over: refused, no music, its "
          f"black stands: {r.sentence} {n.sess.player.override!r}")
    del n.c.pixels_to_show
    n.c.close()
    n.link.close()
    # The Programming screen: a refused show start (an Abort landed) ends
    # on black; a Play the clock refused leaves no hand-over waiting; a
    # look the operator keeps ends a stale hand-over.
    from ltcplay.playhead import ShowAudioPlayhead, PlayheadError
    n = _fi_night()
    n.svc.tick()
    n.svc.machine = types.SimpleNamespace(state="OFF")
    clk = n.sess.clock
    n.sess.playhead_clock = lambda: clk
    n.sess.clock_play_from = lambda s, check_only=False: (
        (types.SimpleNamespace(name="Show"), s) if check_only else
        (clk.play("Show"), (types.SimpleNamespace(name="Show"), s))[1])
    n.sess.clock_here = lambda: 0.0
    n.sess.clock_halt = lambda: clk.halt()
    ph = ShowAudioPlayhead(n.control, n.svc)
    real_start = n.c.show_starting
    n.c.show_starting = lambda *a, **k: C.failed("aborted meanwhile")
    try:
        ph.play_from(3600.0, "Andy", "iPad")
    except PlayheadError:
        pass
    n.c.show_starting = real_start
    n.sess.player.first_frame()
    check(n.sess.player.override == "blackout" and
          n.sess.player.show_handoff is None,
          f"Programming Play refused at the show start: black, never the "
          f"show: {n.sess.player.override!r}")
    n.sess.player.override = None
    n.w.show._pix_ours = False

    def refused(s, check_only=False):
        if check_only:
            return types.SimpleNamespace(name="Show"), s
        raise RuntimeError("the clock refused it")
    n.sess.clock_play_from = refused
    try:
        ph.play_from(3600.0, "Andy", "iPad")
    except Exception:                            # noqa: BLE001
        pass
    check(n.sess.player.show_handoff is None,
          f"a Play the clock refused leaves no hand-over waiting: "
          f"{n.sess.player.show_handoff!r}")
    n.c.close()
    n.link.close()
    F = _fi_mod()
    calls = []
    p = _FiPlayer(calls, types.SimpleNamespace(now=lambda: 0.0))
    sess = types.SimpleNamespace(running=True, player=p, log=None)
    fis = F.FireIceShow(types.SimpleNamespace(session=sess),
                        flame_link=object())
    p.hold_until_show()                  # an earlier start, still waiting
    p.override = "preshow"               # the operator's look on the page
    p.show_handoff = ("preshow", 0)
    fis.pixels_for_show("Play from on the Programming screen",
                        programming=True)
    p.first_frame()
    check(p.override == "preshow" and p.show_handoff is None,
          f"a look the Programming screen keeps ends a stale hand-over, "
          f"so later timecode never lifts it: {p.override!r}")
    # A look set through the engine (/api/override) during a start's
    # hand-over stands, even the same black the start held.
    from ltcplay import web as web_mod
    p = _FiPlayer(calls, types.SimpleNamespace(now=lambda: 0.0))
    p.override = "blackout"
    p.hold_until_show()
    ctl = types.SimpleNamespace(session=types.SimpleNamespace(
        running=True, player=p, log=None))
    web_mod.Control.override(ctl, "blackout")
    p.first_frame()
    check(p.override == "blackout" and p.show_handoff is None,
          f"a Black set during the hand-over is never lifted by the first "
          f"show frame: {p.override!r}")
    # A start whose show failed or ended unconfirmed ends its own
    # hand-over, before anything the conductor does.
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    n.sess.player.override = "blackout"
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    check(n.sess.player.show_handoff is not None,
          "setup: the start is waiting for its first frame")
    n.sess.clock.playing = False
    n.sess.clock.last_ended = "Show stopped"
    n.w.runner.poll()
    check(n.sess.player.show_handoff is None,
          f"a show that ended before it was confirmed ends its start's "
          f"hand-over: {n.sess.player.show_handoff!r}")
    n.c.close()
    n.link.close()
    # The race: a new start arms the player's one hand-over slot after
    # poll() read the old cue. The old show's end never cancels the new
    # start's hand-over.
    n = _fi_night(work=_one_show_work(S, shows=2))
    n.now[0] = _den(S, 17, 40)
    n.svc.tick()
    n.sess.player.override = "blackout"
    n.svc._apply(_op(S, S.START_NOW))
    _settle(n.svc, n.c)
    n.sess.clock.playing = False
    n.sess.clock.last_ended = "Show stopped"
    n.sess.player.hold_until_show()          # the newer start's
    newer = n.sess.player.show_handoff
    n.w.runner.poll()
    check(n.sess.player.show_handoff is newer and newer is not None,
          f"an older show's end leaves a newer start's hand-over armed: "
          f"{n.sess.player.show_handoff!r}")
    n.c.close()
    n.link.close()
    print("  ok")


class _LitFSEQ(FakeFSEQ):
    """A FakeFSEQ whose every frame is lit (FakeFSEQ's frame 0 is all
    zeros, which would hide a dark frame)."""

    def __init__(self, base, **kw):
        FakeFSEQ.__init__(self, **kw)
        self.base = base

    def frame(self, i):
        FakeFSEQ.frame(self, i)
        return bytes([self.base + i % 50]) * self.channel_count


def test_the_show_takes_over_the_pixels_on_its_first_frame():
    section("pixels: a show start keeps the look that is up (the idle "
            "look, a black) until the first frame of the show's timecode "
            "and switches on that very tick: no dark frame between the "
            "idle look and the show (Jeff's show 5, 2026-10-29)")
    import types
    F = _fi_mod()
    idle = _LitFSEQ(100, frames=40, channels=64)
    show = _LitFSEQ(10, frames=400, channels=64)
    tl = _timeline([("01:00:00:00", "Show", show)], idle="/tmp/idle.fseq")

    def player():
        p = Player(tl, FakeNetmap(), CountingSender())
        p.on_lost = "hold"
        p.idle_cue = timeline.Cue("00:00:00:00", "/tmp/idle.fseq",
                                  "preshow loop")
        p.idle_cue.fseq = idle
        p.idle_cue._spans = [(0, 0, 64)]
        p.idle_cue._gaps = None
        return p

    def frames(p, k):
        return [bytes(p._alert_mix(p._tick()) or b"") for _ in range(k)]

    def lit(f):
        return len(f) > 0 and any(f)
    base = tcmod.parse_tc("01:00:00:00", 30)
    first_show = bytes(show.frame(0))
    # The idle look under a stale record of the conductor's black (Jeff's
    # show 5): through the real FireIceShow start.
    p = player()
    sess = types.SimpleNamespace(running=True, player=p, log=None)
    fis = F.FireIceShow(types.SimpleNamespace(session=sess),
                        flame_link=object())
    fis._pix_ours = True
    out = frames(p, 3)
    text = fis.pixels_for_show("Show 5 start")
    out += frames(p, 3)
    p.feed_timecode(base, _now(), False, "01:00:00:00")
    out += frames(p, 3)
    check(all(lit(f) for f in out),
          f"no dark frame from the idle look into the show: "
          f"{[f[:1] for f in out]}")
    check(out[5][:1] == bytes([100 + 0])[:1] or out[5][0] >= 100,
          "the idle look stays up until the show's timecode arrives")
    check(out[6] == first_show and p.override is None and
          p.show_handoff_done is not None and
          p.show_handoff_done[0] is None,
          f"the show's first frame goes out on the first tick after its "
          f"timecode: {out[6][:1]!r}")
    check("stale record" in text, f"the start's line: {text}")
    # A start that never played (the clock refused it, then stopped): no
    # hand-over left to lift the look on later timecode.
    p = player()
    p.override = "blackout"
    p.hold_until_show()
    p.drop_clock()
    p.feed_timecode(base, _now(), False, "01:00:00:00")
    frames(p, 2)
    check(p.override == "blackout" and p.show_handoff is None,
          "the show clock stopping ends a waiting hand-over")
    # A cancel names the hand-over it means: a newer one is never ended
    # for an older one.
    p = player()
    p.hold_until_show()
    older = p.show_handoff
    p.hold_until_show()
    check(p.cancel_show_handoff(older) is False and
          p.show_handoff is not None and
          p.cancel_show_handoff(p.show_handoff) is True and
          p.show_handoff is None,
          "cancel_show_handoff(hand) ends only that hand-over")
    # The closing black: black frames, then the show's first frame, with
    # no idle look flashed between.
    p = player()
    p.override = "blackout"
    out = frames(p, 2)
    p.hold_until_show()
    out += frames(p, 2)
    p.feed_timecode(base, _now(), False, "01:00:00:00")
    out += frames(p, 2)
    check(out[:4] == [b""] * 4 and out[4] == first_show,
          f"from black straight to the show on its first frame: "
          f"{[f[:1] for f in out]}")
    # A clock left from an earlier cue is not the new show's first frame.
    p = player()
    p.feed_timecode(base + 50.0, _now(), False, "01:00:50:00")
    p.override = "blackout"
    p.hold_until_show()
    out = frames(p, 2)
    check(out == [b"", b""] and p.override == "blackout",
          "the held look waits for a frame that came after the start")
    # Someone else's look since the start (a Hold's black) stands.
    p = player()
    p.hold_until_show()
    p.cancel_show_handoff()
    p.override = "blackout"
    p.feed_timecode(base, _now(), False, "01:00:00:00")
    frames(p, 2)
    check(p.override == "blackout", "a Hold's black during the hand-over "
                                    "is never lifted by it")
    p = player()
    p.hold_until_show()
    p.override = "preshow"          # the page's look, set straight on it
    p.feed_timecode(base, _now(), False, "01:00:00:00")
    frames(p, 2)
    check(p.override == "preshow" and p.show_handoff is None,
          "a look put on the pixels after the start stands: the hand-over "
          "lifts only the look it held")
    # The runner says when the first show frame went out.
    lines = []
    r = types.SimpleNamespace(_note=lambda text, **f: lines.append(text))
    cue = {"show": 5, "pix": types.SimpleNamespace(
        show_handoff_done=(None, 10.2)), "sent": 10.0}
    F.ShowRunner._first_frame(r, cue)
    F.ShowRunner._first_frame(r, cue)
    check(len(lines) == 1 and "first show frame went out" in lines[0] and
          "0.20 s" in lines[0],
          f"the journal says when the first show frame went out: {lines}")
    print("  ok")


def test_no_dark_frame_between_the_show_and_the_idle_look():
    section("pixels: at a show's end the show audio clock runs its "
            "timecode to the end of the lights file rounded up to the next "
            "timecode frame; the show's last frame is held through that "
            "frame, then the idle look, with no dark frame between, with "
            "the show file's Intermission cue after it or not (Jeff, "
            "2026-10-30: \"a little blip of black ... vice versa\"; review "
            "of #179, B1); a longer tail is still dark, gaps idle makes it "
            "the idle look, and a show chased off a timecode feed is "
            "unchanged")
    import types
    import ltcplay.player as plmod
    idle = _LitFSEQ(100, frames=40, channels=64)

    def show_end(lights_frames, audio_s, phase, intermission=True,
                 gaps=None, chased=False, hold_at=None):
        """The real Player, ticked every 25 ms (from `phase`), fed and
        ended by the real AudioMaster (_am_rig: its local audio engine on
        the test's clock): its sink is Player.feed_timecode, its on_stop
        Player.drop_clock, its on_pause/on_resume the hard park, as
        session.py wires them. The show file has the Show at 01:00:00:00
        and, with `intermission`, the Intermission at 02:00:00:00. With
        `hold_at`, the clock is paused that many seconds into the show
        for 1 s, then resumed. Returns the looks that went out from 0.5 s
        before the end of the lights file to 0.3 s after the clock
        ended the cue."""
        lights_s = lights_frames * 0.025
        r = _am_rig(seconds=audio_s, lengths={"Show": lights_s})
        am, sim, vc, tl = r["am"], r["sim"], r["vc"], r["tl"]
        for c in tl.cues:
            c.fseq = _LitFSEQ(10, frames=(lights_frames if c.name == "Show"
                                          else 40), channels=64)
            c.duration = c.fseq.duration_ms / 1000.0
            c._spans = [(0, 0, 64)]
            c._gaps = None
        if not intermission:
            tl.cues = [c for c in tl.cues if c.name == "Show"]
        p = Player(tl, FakeNetmap(), CountingSender(), gaps=gaps)
        p.idle_cue = timeline.Cue("00:00:00:00", "/tmp/idle.fseq",
                                  "preshow loop")
        p.idle_cue.fseq = idle
        p.idle_cue._spans = [(0, 0, 64)]
        p.idle_cue._gaps = None
        p.clock = (types.SimpleNamespace(source="ltc_audio_slave")
                   if chased else am)
        stopped = []
        am.sink = p.feed_timecode
        am.on_stop = lambda: (stopped.append(vc()), p.drop_clock())
        am.on_pause = lambda: p.set_hard_park(True)
        am.on_resume = lambda: p.set_hard_park(False)
        st = _Stepped(p, step_ms=25)
        looks = []
        try:
            am.play(3600.0, None, "Show")
            t0 = vc()
            k = 0
            held = None
            while not stopped or vc() < stopped[0] + 0.3:
                t = t0 + phase + k * 0.025
                k += 1
                if hold_at is not None and held is None and \
                        t - t0 >= hold_at:
                    held = t
                    am.pause(fade_ms=0)
                if held is not None and held > 0 and t - held >= 1.0:
                    held = -1.0
                    am.resume(fade_ms=0)
                sim.run(t)
                st.t = vc()
                f = bytes(p._alert_mix(p._tick()) or b"")
                if p.last_ltc_seconds is not None and \
                        p.last_ltc_seconds - 3600.0 >= lights_s - 0.5 or \
                        stopped:
                    looks.append("black" if not any(f) else
                                 "idle" if f[0] >= 100 else "show")
                if k > 4000:
                    break
        finally:
            st.close()
            am.stop()
        return looks

    def runs(looks):
        out = []
        for x in looks:
            if not out or out[-1][0] != x:
                out.append([x, 0])
            out[-1][1] += 1
        return [(x, n) for x, n in out]
    phases = [i * 0.0025 for i in range(10)]
    # Jeff's show: a lights file that ends between two timecode frames
    # (241 frames of 25 ms, 6.025 s; the timecode ends at 6.033 s), the
    # audio a little shorter, then 0.005 s longer (inside the held frame).
    for audio_s in (6.0, 6.03):
        for inter in (True, False):
            bad = []
            for ph in phases:
                got = runs(show_end(241, audio_s, ph, intermission=inter))
                if [x for x, _n in got] != ["show", "idle"]:
                    bad.append((ph, got))
            check(not bad,
                  f"audio {audio_s} s, Intermission cue {inter}: the "
                  f"show's last frame, then the idle look, with no dark "
                  f"frame between, at every tick phase: {bad[:3]}")
    check(plmod.SHOW_END_HOLD_S <= 0.07,
          f"the show's last frame is held at most two timecode frames: "
          f"{plmod.SHOW_END_HOLD_S}")
    # A Hold across the end, then Resume: the same.
    bad = []
    for ph in phases:
        got = runs(show_end(241, 6.0, ph, hold_at=5.9))
        if [x for x, _n in got] != ["show", "idle"]:
            bad.append((ph, got))
    check(not bad, f"a Hold just before the end, then Resume: no dark "
                   f"frame between the show and the idle look: {bad[:3]}")
    # The same show chased off a timecode feed (GPL's way): unchanged, the
    # rounding frame still goes out black at some tick phases.
    blacks = [runs(show_end(241, 6.0, ph, chased=True)) for ph in phases]
    check(any("black" in [x for x, _n in g] for g in blacks),
          f"a show chased off a timecode feed is unchanged: {blacks[:3]}")
    # Audio 1 s longer than the lights file: the tail past the lights
    # file is dark as before, with only the rounding frame held; with
    # "gaps": "idle" that tail is the idle look. With and without the
    # Intermission cue.
    for inter in (True, False):
        got = runs(show_end(241, 7.0, 0.0, intermission=inter))
        check([x for x, _n in got] == ["show", "black", "idle"] and
              got[1][1] >= 36,
              f"Intermission cue {inter}: a tail longer than a timecode "
              f"frame is still dark: {got}")
        got = runs(show_end(241, 7.0, 0.0, intermission=inter,
                            gaps="idle"))
        check([x for x, _n in got] == ["show", "idle"],
              f"Intermission cue {inter}: with gaps idle the tail is the "
              f"idle look: {got}")
    # By hand: a Hold's or an Abort's black over the held frame wins; the
    # hold ends after SHOW_END_HOLD_S whatever comes after the cue.
    base = tcmod.parse_tc("01:00:00:00", 30)
    show = _LitFSEQ(10, frames=400, channels=64)
    for cues in ([("01:00:00:00", "Show", show)],
                 [("01:00:00:00", "Show", show),
                  ("02:00:00:00", "Intermission",
                   _LitFSEQ(10, frames=40, channels=64))]):
        tl = _timeline(cues, idle="/tmp/idle.fseq")
        p = Player(tl, FakeNetmap(), CountingSender())
        p.clock = types.SimpleNamespace(source="audio_master")
        st = _Stepped(p, step_ms=25)
        try:
            st.feed(base + 9.99)
            st.t += 0.02
            held = bytes(p._tick() or b"")
            st.t += 0.1
            late = p._tick()
        finally:
            st.close()
        check(any(held) and not late,
              f"{len(cues)} cue(s): the last frame held in the rounding "
              f"frame, the gap look once SHOW_END_HOLD_S is past: "
              f"{held[:1]!r} {late!r}")
    # A Hold's or an Abort's black in the rounding frame wins: through the
    # real FireIceShow's black (pixels_fade_out), with the show audio
    # clock still in its last frame, the output is black and the source
    # says so; given back (pixels_restore), the held last frame again.
    F = _fi_mod()
    tl = _timeline([("01:00:00:00", "Show", show)], idle="/tmp/idle.fseq")
    p = Player(tl, FakeNetmap(), CountingSender())
    p.clock = types.SimpleNamespace(source="audio_master")
    sess = types.SimpleNamespace(running=True, player=p, log=None)
    fis = F.FireIceShow(types.SimpleNamespace(session=sess),
                        flame_link=object())
    st = _Stepped(p, step_ms=25)
    try:
        st.feed(base + 9.99)
        st.t += 0.02
        before = bytes(p._tick() or b"")
        fis.pixels_fade_out(0)
        dark = bytes(p._tick() or b"")
        dark_src = p.source
        fis.pixels_restore(0)
        back = bytes(p._tick() or b"")
    finally:
        st.close()
    check(any(before) and not any(dark) and dark_src == plmod.BLACK and
          back == before,
          f"a Hold's black over the held last frame: {before[:1]!r} "
          f"{dark[:1]!r} {dark_src!r} {back[:1]!r}")
    print("  ok")


def test_fire_ice_review_hand_mutations():
    section("fire & ice: the runner starts the show it was told, confirms "
            "only the cue it started, closes the night for real; a release "
            "that did not go out is not done; ltc serve checks flamesafe's "
            "config before it binds anything (PR #43 review, item 10: H5, "
            "H6, H9, H10, H12)")
    import tempfile
    import types
    import json as _json
    F = _fi_mod()
    # H6: the show number reaches the runner.
    n = _fi_night()
    if n.S is None:
        return
    S = n.S
    n.svc.tick()
    n.now[0] = _den(S, 18, 0)
    n.svc.tick()
    _settle(n.svc, n.c)
    want = n.svc.machine.running
    cue = n.w.runner._cue or {}
    check(want and cue.get("show") == want,
          f"the runner started show {want}, not {cue.get('show')!r}")
    # H5: another cue on the show audio is not the one it started.
    n.sess.clock.cues_played += 1
    n.sess.clock._last_frame = 9
    n.w.runner.poll()
    _settle(n.svc, n.c)
    check(not any(r.get("action") == "SHOW_CONFIRMED"
                  for r in n.svc.journal),
          "a cue the runner did not start never confirms the show")
    n.c.close()
    n.link.close()
    # Fix round 2, E: a Preshow (or any) look chosen on the page before the
    # show does not stay on all show.
    n.c.close()
    n.link.close()
    n = _fi_night()
    n.svc.tick()
    n.sess.player.override = "preshow"
    r = n.w.runner.start_show(9, who="Andy")
    held = n.sess.player.override
    n.sess.player.first_frame()
    check(r.ok and held == "preshow" and n.sess.player.override is None,
          f"a look chosen before the show stays up until the first show "
          f"frame, then is cleared on that frame: {held!r} "
          f"{n.sess.player.override!r} {r}")
    n.sess.player.override = None
    n.w.show._pix_ours, n.w.show._pix_prev = True, "preshow"
    n.sess.player.override = "blackout"
    n.w.runner.start_show(10, who="Andy")
    held = n.sess.player.override
    n.sess.player.first_frame()
    check(held == "blackout" and not n.w.show._pix_ours and
          n.w.show._pix_prev is None and n.sess.player.override is None,
          "the conductor's own black is cleared by the start itself (held "
          "until the first show frame, never left for the confirmation), "
          "and what was under it is forgotten (Jeff's report, 2026-10-29)")
    n.w.show._pix_ours, n.w.show._pix_prev = True, None
    n.sess.player.override = "preshow"      # the page, over that black
    n.w.runner.start_show(11, who="Andy")
    n.sess.player.first_frame()
    check(n.sess.player.override is None and not n.w.show._pix_ours,
          f"a look the page put over the conductor's black is cleared with "
          f"it: {n.sess.player.override!r}")
    # H12: closing zeroes the flames, blanks the lasers, blacks the pixels.
    n = _fi_night()
    n.svc.tick()
    reported = []
    n.svc.report = lambda *a, **k: reported.append(a)
    real = n.svc.machine
    n.svc.machine = types.SimpleNamespace(state="CLOSING")
    del n.calls[:]
    n.w.runner.poll()
    n.c.run_pending()
    n.svc.machine = real
    kinds = [k for k, _a, _t in n.calls]
    check("flames_zero" in kinds and n.sess.player.override == "blackout"
          and any(k == "beyond" or "laser" in str(k) for k in kinds)
          and reported and reported[0][0] == "CLOSING_DONE",
          f"closing: flames zero, lasers blanked, pixels black, then "
          f"CLOSING_DONE: {kinds} {reported}")
    n.c.close()
    n.link.close()
    # H9: a release on a link that is not open is not done.
    show = F.FireIceShow(types.SimpleNamespace(session=None),
                         flame_link=types.SimpleNamespace(
                             release=lambda: False))
    r = show.flames_release()
    check(not r.ok, f"a release that did not go out is reported: {r}")
    # H10: ltc serve refuses a flamesafe config it cannot read before it
    # binds anything.
    from ltcplay import cli as cli_mod, web as web_mod
    from ltcplay import schedule_service as SV
    work = tempfile.mkdtemp()
    bad = os.path.join(work, "broken_flamesafe.json")
    with open(bad, "w") as fh:
        fh.write("{ not json")
    rule = os.path.join(work, SV.RULE_FILE)
    SV.save_rule(rule, _sched_doc())
    with open(F.config_path_for(rule), "w") as fh:
        _json.dump({"flamesafe_config": bad}, fh)
    served, served_kw = [], []
    real_serve = web_mod.serve

    def no_serve(*a, **k):
        served.append(a)
        served_kw.append(k)
        raise RuntimeError("serve was reached")
    web_mod.serve = no_serve
    try:
        def serve_with(path):
            del served[:]
            with open(F.config_path_for(rule), "w") as fh:
                _json.dump({"flamesafe_config": path}, fh)
            args = types.SimpleNamespace(
                folder=work, schedule=rule, announce=None, port=0,
                bind="127.0.0.1", token=None, no_browser=True, network=False,
                flamesafe_config=None)
            try:
                return cli_mod._cmd_serve(args)
            except Exception as e:
                return f"raised {type(e).__name__}: {e}"
        good, _sh, _doc = _fi_flame_files(work)
        rc = serve_with(good)
        check(served, f"setup: a good flamesafe config gets as far as "
                      f"binding: {rc!r}")
        # Not valid JSON (Jeff, 2026-11-06): the engine starts anyway, with
        # no flame link and no flamesafe config (test_flamesafe_bad_json_*).
        rc = serve_with(bad)
        check(served and served_kw[-1].get("flamesafe_config") is None and
              served_kw[-1]["fire_ice"].flamesafe_config is None,
              f"ltc serve on flamesafe's config that is not JSON: it starts "
              f"with flames off: {rc!r} served={bool(served)}")
        # A file every other check reads fine (valid JSON, the example's
        # groups, destination and universe) whose link block only the flame
        # link's own check refuses: a listen address that is not loopback.
        # "{ not json" above no longer tells the H10 check apart from
        # check_flame_groups, which opens the same file and so also stops
        # serve on it; with the H10 line gone this case reaches the bind
        # (NOT CAUGHT in CI: PR #43 shard 23, PR #46 shard 22).
        link_only = os.path.join(work, "flamesafe_bad_link.json")
        with open(good, encoding="utf-8") as fh:
            doc2 = _json.load(fh)
        doc2["link"]["listen_ip"] = "10.0.0.5"
        with open(link_only, "w", encoding="utf-8") as fh:
            _json.dump(doc2, fh)
        rc = serve_with(link_only)
        check(rc not in (0, None) and not served,
              f"ltc serve stops on a flame link block only flame_link_config "
              f"refuses, before binding: {rc!r} served={bool(served)}")
    finally:
        web_mod.serve = real_serve
        import shutil
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_flamesafe_bad_json_starts_with_flames_off():
    section("flamesafe.json that is not valid JSON (Jeff, 2026-11-06): the "
            "engine and the rack screen still start, with no flame link and "
            "no flame groups, and the screens say the file, line and "
            "column; the supervisor starts neither flamesafe nor the deck, "
            "says why in flamesafe.log and in the start message, and keeps "
            "a last good copy only of a file flamesafe has run on")
    import io
    import contextlib
    import shutil
    import tempfile
    import types
    from ltcplay import flamesafecheck as FC
    work = tempfile.mkdtemp()
    try:
        fs = os.path.join(work, "flamesafe.json")
        good = os.path.join(work, "flamesafe.last-good.json")
        broken = b'{\n  "groups": []\n  "link": {}\n}\n'
        with open(fs, "wb") as fh:
            fh.write(broken)
        # 1. Where it is broken: the JSON error's own line and column.
        bad = FC.json_problem(fs)
        check(bad == {"path": os.path.abspath(fs), "line": 3, "column": 3,
                      "what": "Expecting ',' delimiter"},
              f"the problem: the file, line 3, column 3: {bad}")
        check(FC.last_good_path(fs) == good,
              f"the last good copy sits beside it: {FC.last_good_path(fs)}")
        want = (f"flamesafe.json is not valid JSON at line 3, column 3 "
                f"(Expecting ',' delimiter): {os.path.abspath(fs)}. Flames "
                f"are off: flamesafe is not running and no flame group can "
                f"be armed. Fix it (there is no last good copy yet). Then "
                f"start LTC Player again. flamesafe.log says the same.")
        check(FC.sentence(bad) == want,
              f"the screens' words, no last good copy: {FC.sentence(bad)!r}")
        check(FC.bytes_problem(b"[1, 2]", fs)["what"] ==
              "the file is not one JSON object { ... }" and
              FC.bytes_problem(b'{"a": "\xff"}', fs)["what"] ==
              "a character that is not UTF-8" and
              FC.json_problem(os.path.join(work, "none.json")) is None,
              "a list is not a config; a byte that is not UTF-8 is said; a "
              "missing file is said where it is used")
        # A byte-order mark (an older Notepad's "UTF-8"): flamesafe reads
        # strict UTF-8 and refuses it, so it counts as broken here too.
        bom = os.path.join(work, "bom.json")
        with open(bom, "wb") as fh:
            fh.write(b'\xef\xbb\xbf{"groups": []}')
        check(FC.json_problem(bom) == {
                  "path": os.path.abspath(bom), "line": 1, "column": 1,
                  "what": "it was saved with a byte-order mark (BOM); save "
                          "it as UTF-8 without BOM"},
              f"a file saved with a BOM is said, with what to do: "
              f"{FC.json_problem(bom)}")
        # 2. The last good copy: only valid JSON, written once, replaced.
        check(FC.save_last_good(fs, broken) is None and
              not os.path.exists(good),
              "bytes that are not valid JSON never become the last good copy")
        ok1 = b'{"groups": [], "n": 1}\n'
        check(FC.save_last_good(fs, ok1) == good and
              open(good, "rb").read() == ok1 and
              FC.save_last_good(fs, ok1) is None,
              "valid bytes are kept, and the same bytes again write nothing")
        import time as _time
        stamp = _time.mktime((2026, 11, 2, 18, 40, 0, 0, 0, -1))
        os.utime(good, (stamp, stamp))
        check(FC.sentence(bad) == want.replace(
                  "Fix it (there is no last good copy yet). ",
                  f"Fix it, or copy the last good copy back over it: "
                  f"{good}, saved 2026-11-02 18:40. It may be older than "
                  f"recent edits (a channel moved since, for example): "
                  f"check it before you use it. "),
              f"with a last good copy the screens name it, when it was "
              f"saved, and that it may be older than recent edits: "
              f"{FC.sentence(bad)!r}")
        check("–" not in want and "—" not in want,
              "no em or en dashes")
        # 3. The engine starts, with flames off, and says it.
        from ltcplay import cli as cli_mod, web as web_mod
        from ltcplay import fire_ice as F
        from ltcplay import schedule_service as SV
        S = _sched()
        if S is None:
            return
        rule = os.path.join(work, SV.RULE_FILE)
        SV.save_rule(rule, _sched_doc())
        with open(F.config_path_for(rule), "w") as fh:
            json.dump({"flamesafe_config": fs,
                       "flame_controller": "Flames"}, fh)
        seen = {}
        # A refused start writes cli.REFUSED_FILE into the settings
        # folder, which off Windows is the repo itself: keep it in
        # this test's own folder.
        from ltcplay import remote as RM_
        real_settings_folder = RM_.settings_folder
        RM_.settings_folder = lambda: work
        real_serve = web_mod.serve

        def fake_serve(*a, **k):
            seen.update(k)
            # Enough of an httpd for the line after serve; the next one
            # (httpd.schedule) stops the start here.
            return types.SimpleNamespace(remote=types.SimpleNamespace(
                flamesafe_problem=""), bind_address="127.0.0.1")
        web_mod.serve = fake_serve
        out = io.StringIO()
        try:
            for named in (None, fs):
                seen.clear()
                args = types.SimpleNamespace(
                    folder=work, schedule=rule, announce=None, port=0,
                    bind="127.0.0.1", token=None, no_browser=True,
                    network=False, flamesafe_config=named)
                httpd = None
                with contextlib.redirect_stdout(out), \
                        contextlib.redirect_stderr(out):
                    try:
                        cli_mod._cmd_serve(args)
                    except AttributeError:
                        pass
                fi = seen.get("fire_ice")
                check(seen and seen.get("flamesafe_config") is None and
                      fi is not None and fi.flamesafe_config is None and
                      fi.flame_controller == "Flames",
                      f"--flamesafe-config {named}: the engine starts with no "
                      f"flame link and no flamesafe config, the flame "
                      f"controller still named (the pixel output never sends "
                      f"it): {sorted(seen)} {fi and fi.flamesafe_config} "
                      f"{fi and fi.flame_controller}")
            check(f"FLAMES OFF: {FC.sentence(bad)}" in out.getvalue(),
                  f"its own log says it: {out.getvalue()[-600:]!r}")
            # The rack screen's red line: set on the remote it serves.
            got = []

            def fake_serve2(*a, **k):
                h = types.SimpleNamespace(remote=types.SimpleNamespace(
                    flamesafe_problem=""), bind_address="127.0.0.1")
                got.append(h)
                return h
            web_mod.serve = fake_serve2
            with contextlib.redirect_stdout(io.StringIO()):
                try:
                    cli_mod._cmd_serve(types.SimpleNamespace(
                        folder=work, schedule=rule, announce=None, port=0,
                        bind="127.0.0.1", token=None, no_browser=True,
                        network=False, flamesafe_config=None))
                except AttributeError:
                    pass
            check(got and got[0].remote.flamesafe_problem ==
                  FC.sentence(bad),
                  f"the rack screen gets the sentence: "
                  f"{got and got[0].remote.flamesafe_problem!r}")

            def start_out(folder, env=None):
                del got[:]
                o = io.StringIO()
                saved_env = os.environ.get(cli_mod.FLAMESAFE_ENV)
                if env:
                    os.environ[cli_mod.FLAMESAFE_ENV] = env
                try:
                    with contextlib.redirect_stdout(o), \
                            contextlib.redirect_stderr(o):
                        try:
                            rc = cli_mod._cmd_serve(types.SimpleNamespace(
                                folder=folder, schedule=rule, announce=None,
                                port=0, bind="127.0.0.1", token=None,
                                no_browser=True, network=False,
                                flamesafe_config=None))
                        except AttributeError:
                            rc = "served"
                finally:
                    os.environ.pop(cli_mod.FLAMESAFE_ENV, None)
                    if saved_env is not None:
                        os.environ[cli_mod.FLAMESAFE_ENV] = saved_env
                return rc, o.getvalue()
            # showpc.json naming another, valid file: still the one-config
            # refusal (P1-4), never a start on the other file.
            os.makedirs(os.path.join(work, "o"))
            other, _sh, _d = _fi_flame_files(os.path.join(work, "o"))
            rc, said = start_out(work, env=other)
            check(rc not in (0, None, "served") and not got and
                  "different flamesafe configs" in said,
                  f"another file named in showpc.json: refused as before: "
                  f"{rc!r} {said[-300:]!r}")
            # An Active flame controller in a show's layout: still refused
            # at startup with flamesafe.json broken.
            os.makedirs(os.path.join(work, "a"))
            _fs2, show2, _d2 = _fi_flame_files(os.path.join(work, "a"),
                                               state="Active")
            folder2 = os.path.join(work, "a", "folder")
            os.makedirs(folder2)
            with open(os.path.join(folder2, "fi_timeline.json"), "w",
                      encoding="utf-8") as fh:
                json.dump({"name": "fi", "fps": 30, "show_dir": show2,
                           "cues": [{"tc": "01:00:00:00",
                                     "fseq": "Show.fseq", "name": "Show"}]},
                          fh)
            with open(F.config_path_for(rule), "w") as fh:
                json.dump({"flamesafe_config": fs,
                           "flame_controller": "Flames",
                           "beyond_blank": "osc"}, fh)
            rc, said = start_out(folder2)
            check(rc not in (0, None, "served") and not got and
                  "fi_timeline.json" in said and "Active" in said,
                  f"an Active flame controller is still refused with "
                  f"flamesafe.json broken: {rc!r} {said[-300:]!r}")
        finally:
            web_mod.serve = real_serve
            RM_.settings_folder = real_settings_folder
        R = _RemoteRig(S)
        try:
            st, _h, s0 = R.ask("GET", "/api/remote/status")
            R.remote.flamesafe_problem = FC.sentence(bad)
            st1, _h, s1 = R.ask("GET", "/api/remote/status")
            check(s0.get("flamesafe_config_error") == "" and
                  s1.get("flamesafe_config_error") == FC.sentence(bad),
                  f"the status carries it for the screens: "
                  f"{s0.get('flamesafe_config_error')!r} "
                  f"{s1.get('flamesafe_config_error')!r}")
        finally:
            R.close()
        two = _ui2_pages()[1]
        check('if(s.flamesafe_config_error) items.push({key:"fscfg", '
              'tone:"bad", what:"Flame settings file broken.", do:"Flames '
              'are off. Tap here.", full:s.flamesafe_config_error});' in two,
              "2.0's alert slot shows it in red, the whole sentence behind "
              "a tap")
        # 4. The supervisor: neither flamesafe nor the deck, said where an
        # operator looks.
        os.remove(good)
        W, SUP, gone = _winpkg()
        old_local = os.environ.get("LOCALAPPDATA")
        try:
            os.environ["LOCALAPPDATA"] = work
            settings = {"show_folder": os.path.join(work, "shows"),
                        "flamesafe_config": fs, "port": 7878,
                        "run_flamesafe": True, "run_deck": True,
                        "show_mode": "fire_ice",
                        "schedule": os.path.join(work, "s.json")}
            want_ = SUP.wanted_args(settings)
            check(want_["flamesafe"] == (None, "flamesafe is not started: "
                                         + FC.sentence(bad)) and
                  want_["deck"] == (None, "the Stream Deck program is not "
                                    "started: flamesafe's config is not "
                                    "valid JSON (flamesafe.log says where)")
                  and want_["engine"][0] is not None,
                  f"bad JSON: no flamesafe, no deck, the engine runs: "
                  f"{want_['flamesafe']} {want_['deck']}")
            p = types.SimpleNamespace(said_why_not="")
            for _ in range(2):
                SUP.say_not_started("flamesafe", p,
                                    want_["flamesafe"][1])
            flog = os.path.join(SUP.log_dir(), "flamesafe.log")
            text = open(flog, encoding="utf-8").read() \
                if os.path.exists(flog) else ""
            check(text.count("LTC Player: flamesafe is not started: "
                             + FC.sentence(bad)) == 1,
                  f"flamesafe.log says why, once: {text[-400:]!r}")
            note = SUP.flamesafe_start_note(settings)
            check(note == (
                f"\n\nThe flamesafe config is invalid: flamesafe.json is not "
                f"valid JSON at line 3, column 3. Flames are off and "
                f"flamesafe is not started. flamesafe.log in "
                f"{SUP.log_dir()} says what to do."),
                f"the start message says it: {note!r}")
            # Starting LTC Player: the page opens, then the message says
            # flames are off and why (never only "did not answer").
            told, opened = [], []
            saved_ = (SUP.load_settings, SUP.supervisor_running,
                      SUP.engine_answers, SUP.open_page_now, SUP.tell,
                      SUP.QUIET)
            try:
                SUP.load_settings = lambda: settings
                SUP.supervisor_running = lambda: True
                SUP.engine_answers = lambda port: True
                SUP.open_page_now = lambda port: opened.append(port)
                SUP.tell = lambda text, error=False, **k: told.append(
                    (text, error))
                SUP.QUIET = False
                rc = SUP.cmd_start()
            finally:
                (SUP.load_settings, SUP.supervisor_running,
                 SUP.engine_answers, SUP.open_page_now, SUP.tell,
                 SUP.QUIET) = saved_
            check(rc == 0 and opened == [7878] and told == [
                      ("LTC Player has started, with flames off." + note,
                       True)],
                  f"LTC Player starts: the page, then the message: {rc} "
                  f"{opened} {told}")
            # Fixed: flamesafe and the deck start again on their own.
            with open(fs, "wb") as fh:
                fh.write(ok1)
            want_ = SUP.wanted_args(settings)
            check(want_["flamesafe"][0] == [os.path.abspath(fs)] and
                  want_["deck"][0] is not None and
                  SUP.flamesafe_start_note(settings) == "",
                  f"a valid file: both start, no note: {want_['flamesafe']}")
            # The last good copy: once flamesafe has run on its bytes.
            p = types.SimpleNamespace(last_good_kept=False, config_bytes=ok1,
                                      config_path=os.path.abspath(fs),
                                      started=100.0)
            SUP.keep_last_good(p, 100.0 + FC.LAST_GOOD_AFTER_S - 1)
            check(not os.path.exists(good) and not p.last_good_kept,
                  "not before flamesafe has run LAST_GOOD_AFTER_S on it")
            # The file edited since flamesafe started on it: not what
            # flamesafe ran, so not kept.
            q = types.SimpleNamespace(last_good_kept=False,
                                      config_bytes=b'{"older": 1}',
                                      config_path=os.path.abspath(fs),
                                      started=0.0)
            SUP.keep_last_good(q, 1000.0)
            check(not os.path.exists(good),
                  "a file edited since flamesafe started on it is not kept")
            SUP.keep_last_good(p, 100.0 + FC.LAST_GOOD_AFTER_S)
            check(os.path.exists(good) and open(good, "rb").read() == ok1
                  and p.last_good_kept,
                  "then its bytes are the last good copy")
            check(FC.LAST_GOOD_AFTER_S == 20.0, "after 20 s")
            os.remove(good)
            with open(fs, "wb") as fh:
                fh.write(broken)
            p = types.SimpleNamespace(last_good_kept=False,
                                      config_bytes=broken,
                                      config_path=os.path.abspath(fs),
                                      started=0.0)
            SUP.keep_last_good(p, 1000.0)
            check(not os.path.exists(good),
                  "bytes that are not JSON never become the last good copy")
        finally:
            if old_local is None:
                os.environ.pop("LOCALAPPDATA", None)
            else:
                os.environ["LOCALAPPDATA"] = old_local
            gone()
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fire_ice_start_rules_on_the_ordered_line():
    section("fire & ice: a dry run never asks the performer to start a "
            "show; a Stop decided before a waiting show start supersedes "
            "it; closing zeroes and stops the flame link last")
    import threading
    import types
    from ltcplay import schedule_service as SV
    # A dry run, with a performer attached anyway: never asked.
    d = _fi_night(performs=False)
    if d.S is None:
        return
    S = d.S
    asked = []
    d.svc.performer = types.SimpleNamespace(
        start_show=lambda n, who="", stops=None: asked.append(n))
    d.svc.tick()
    d.now[0] = _den(S, 18, 0)
    d.svc.tick()
    _settle(d.svc, d.c)
    check(d.svc.machine.state == S.SHOW and not asked,
          f"a dry run starts its show without the performer: {asked}")
    d.c.close()
    d.link.close()
    # The ordered line: a show start still waiting when a Stop is decided
    # is never sent.
    ran, gate = [], threading.Event()

    def run_one(call):
        if call.method == "hold":
            gate.wait(5)
        ran.append(call.method)
    line = SV._ConductorCalls(run_one)
    calls = [SV._ConductorCall("Hold", "hold", "x", "", 1),
             SV._ConductorCall("Start the show", "start_show", "x", "", 2),
             SV._ConductorCall("Stop", "stop", "x", "", 3)]
    for c in calls:
        line.put(c)
    check(calls[2].done.wait(3), "the Stop went out beside the stuck line")
    gate.set()
    line.flush(5)
    check("stop" in ran and "start_show" not in ran,
          f"the waiting show start was superseded by the Stop: {ran}")
    # Closing: the flame link is zeroed, then stopped, after the rest.
    F = _fi_mod()
    order = []
    fl = types.SimpleNamespace(zero=lambda: order.append("zero"),
                               stop=lambda: order.append("stop"))
    cond = types.SimpleNamespace(close=lambda: order.append("conductor"))
    F.Wiring(cond, None, None, None, flame_link=fl).close()
    check(order == ["conductor", "zero", "stop"],
          f"closing: the conductor first, then flame zeros, then the link "
          f"stops: {order}")
    print("  ok")


def test_fire_ice_show_end_burst_never_holds_up_the_flame_link():
    section("fire & ice: the show-end burst (lasers blanked, video faded, "
            "flame cues zeroed, journal lines) with every device and the "
            "journal taking 200 ms per call never holds up a flame frame: "
            "the flame link's own journal lines are written off its sender "
            "thread, and its frames keep CONTRACT.md's 50 ms floor")
    import json as _json
    import socket as _s
    import tempfile
    import threading
    import types
    F = _fi_mod()
    from ltcplay import conductor as C
    work = tempfile.mkdtemp()
    fs, show, doc = _fi_flame_files(work)
    slow = 0.2
    journal_threads = set()

    def slow_journal(text, **f):
        journal_threads.add(threading.current_thread().name)
        time.sleep(slow)

    # The show: a timecode that moves, then stops (the show's end), then
    # jumps (the next show's start), so the link writes its episode lines.
    st = {"tc": None, "live": False}
    control = types.SimpleNamespace(session=None)
    show_out = F.FireIceShow(control, journal=None, flame_link=None)
    link = F.build_flame_link(F.FireIceConfig(flamesafe_config=fs),
                              control, show_out, slow_journal)
    link.show_state = lambda: (st["tc"], st["live"])
    show_out.flame_link = link

    class SlowDevices(C.DeviceOutputs):
        def _slow(self, what):
            time.sleep(slow)
            slow_journal(what)
            return C.done(what)

        def lasers_blank(self):
            return self._slow("lasers blanked")

        def lasers_fade_out(self, seconds):
            return self._slow("lasers faded")

        def lasers_restore(self):
            return self._slow("lasers back")

        def video_fade_out(self, seconds):
            return self._slow("video faded")

        def video_restore(self, seconds):
            return self._slow("video back")

        def video_stop(self):
            return self._slow("video stopped")
    cond = C.Conductor(SlowDevices(), show_out, lambda: None,
                       journal=slow_journal, threaded=True)
    rx = _s.socket(_s.AF_INET, _s.SOCK_DGRAM)
    rx.bind(("127.0.0.1", link.cfg.port))
    rx.settimeout(0.2)
    got = []
    stop = threading.Event()

    def listen():
        while not stop.is_set():
            try:
                b = rx.recv(70000)
            except _s.timeout:
                continue
            except OSError:
                return
            if _json.loads(b).get("t") == "flame":
                got.append(time.perf_counter())
    lt = threading.Thread(target=listen, daemon=True)
    lt.start()
    # The sender's own clock as well as the receiver's: in this one process
    # the receiving thread can itself be woken late (a macOS CI runner did,
    # 2026-10-03), which is not the flame link holding a frame back.
    sent_at = []
    real_send = link.send_frame

    def timed_send():
        sent_at.append(time.perf_counter())
        return real_send()
    link.send_frame = timed_send
    marks = {}
    try:
        link.start()
        t0 = time.perf_counter()
        frame = 0
        while time.perf_counter() - t0 < 1.0:      # the show, moving
            frame += 1
            st.update(tc=f"01:00:{frame // 30 % 60:02d}:{frame % 30:02d}",
                      live=True)
            time.sleep(1 / 30)
        base = len(got)
        sbase = len(sent_at)
        marks["burst"] = time.perf_counter()
        # The show's end: the timecode stops, the conductor's intermission
        # burst runs, the flame cues are zeroed, and the next show's
        # timecode lands somewhere else entirely.
        cond.intermission("the scheduler", "")
        time.sleep(0.6)
        marks["jump"] = time.perf_counter()
        st.update(tc="01:05:00:00")
        time.sleep(0.4)
        marks["start"] = time.perf_counter()
        cond.show_starting("the scheduler", "")
        time.sleep(0.6)
    finally:
        stop.set()
        link.stop()
        cond.close()
        rx.close()
        lt.join(2)
    def worst_of(ts, start):
        g = [((b - a) * 1000.0, a) for a, b in zip(ts, ts[1:])][start:]
        return max(g or [(0.0, 0.0)])
    worst_rx, at_rx = worst_of(got, base)
    worst, at_tx = worst_of(sent_at, sbase)
    before_rx = worst_of(got[:base + 1], 0)[0]
    before = worst_of(sent_at[:sbase + 1], 0)[0]
    # A runner that cannot keep the floor even before the burst (a macOS
    # CI runner sent at about 15 frames a second throughout, 2026-10-03)
    # cannot judge the floor; there the burst must add nothing a 200 ms
    # call would: no worse than half again the runner's own worst before.
    limit = 50.0 if before < 50.0 else before * 1.5

    def when(t):
        return ", ".join(f"{k} {(t - v) * 1000:+.0f} ms" for k, v in
                         marks.items())
    where = (f"sender worst {worst:.1f} ms ({when(at_tx)}), {before:.1f} ms "
             f"before the burst; receiver worst {worst_rx:.1f} ms "
             f"({when(at_rx)}), {before_rx:.1f} ms before the burst; "
             f"{len(sent_at)} sent, {len(got)} received; limit {limit:.0f} ms")
    print(f"  note: {where}")
    check("ltcplay-flame-link" not in journal_threads,
          f"no journal line is ever written on the flame link's sender "
          f"thread: {sorted(journal_threads)}")
    link.journal_line.flush()
    check(any(n == "ltcplay-flame-journal" for n in journal_threads),
          f"the flame link's lines are written by its own journal thread: "
          f"{sorted(journal_threads)}")
    check(len(sent_at) > (40 if before < 50.0 else 20),
          f"the flame link kept sending: {where}")
    check(worst < limit, f"no gap of 50 ms or more between flame frames "
                         f"through the burst, by the sender's own clock "
                         f"(CONTRACT.md): {where}")
    print("  ok")


def test_fire_ice_auto_start_off_and_start_now():
    section("fire & ice: auto_start off never starts a scheduled show by "
            "itself, Start now still does, and every start is journaled")
    n = _fi_night()
    if n.S is None:
        return
    S, svc, c = n.S, n.svc, n.c
    n.w.runner.cfg.auto_start = "off"
    svc.tick()
    n.now[0] = _den(S, 18, 0)
    svc.tick()
    _settle(svc, c)
    check(not any(k == "music_play" for k, _a, _t in n.calls),
          "auto_start off: the show that came due is not started")
    rows = [r for r in svc.journal if r.get("action") == "automatic start"]
    check(rows and rows[-1]["outcome"] == "refused" and
          "auto_start is off" in rows[-1]["text"],
          f"and the refusal is journaled in words: {rows[-1:]}")
    n.w.runner.poll()
    _settle(svc, c)
    s1 = [x for x in svc.machine.slots if x.n == 1]
    check(s1 and s1[0].status == S.FAULT,
          f"reported as a failed start: {s1}")
    del n.calls[:]
    out = svc._apply(_op(S, S.START_NOW))
    _settle(svc, c)
    check(any(k == "music_play" for k, _a, _t in n.calls),
          f"Start now still starts the show: {out.refused if out else ''} "
          f"{n.calls}")
    rows = [r for r in svc.journal if r.get("action") == "start now"]
    check(rows and rows[-1]["outcome"] == "done" and "Andy" in
          rows[-1]["text"], f"Start now is journaled with who: {rows[-1:]}")
    c.close()
    n.link.close()
    print("  ok")


def _serve_spy(argv, extra_files=None):
    """`ltc serve` in a fresh process, with web.serve wrapped to report
    what it built and then stop. Returns the report."""
    import json as _json
    import subprocess
    import tempfile
    root = os.path.dirname(os.path.abspath(__file__))
    work = tempfile.mkdtemp()
    for name, doc in (extra_files or {}).items():
        with open(os.path.join(work, name), "w") as fh:
            _json.dump(doc, fh)
    argv = [a.replace("{work}", work) for a in argv]
    code = (
        "import sys, json\n"
        f"sys.path.insert(0, {root!r})\n"
        "from ltcplay import cli, web\n"
        "real = web.serve\n"
        "def spy(*a, **k):\n"
        "    h = real(*a, **k)\n"
        "    out = {'fire_ice': k.get('fire_ice') is not None,\n"
        "           'conductor': getattr(h, 'conductor', None) is not None,\n"
        "           'dry_run': getattr(h.schedule, 'dry_run', None),\n"
        "           'mods': sorted(m for m in sys.modules if m.split('.')[-1]\n"
        "                in ('conductor', 'devices', 'fire_ice', 'madmapper',\n"
        "                    'beyond', 'schedule_service'))}\n"
        "    if h.schedule is not None:\n"
        "        h.schedule.halt(); h.schedule.stop()\n"
        "    h.server_close()\n"
        "    print('SPY ' + json.dumps(out))\n"
        "    raise SystemExit(0)\n"
        "web.serve = spy\n"
        # The settings folder too (review of #150): off Windows it is the
        # program's own folder, and the users file and its marker that
        # serve writes there must never land in the checkout.
        "from ltcplay import settings as _settings\n"
        f"_settings.folder = lambda: {work!r}\n"
        # Tonight's file and the night journal go in the temp folder, never
        # beside the program.
        + ("from ltcplay import schedule_service as SV\n"
           f"SV.data_dir = lambda: {work!r}\n"
           if "--schedule" in argv else "")
        + f"cli.main({argv!r})\n")
    env = dict(os.environ, XDG_STATE_HOME=work, LOCALAPPDATA=work)
    rc = subprocess.run([sys.executable, "-c", code], capture_output=True,
                        text=True, timeout=120, cwd=work, env=env)
    got = [l for l in (rc.stdout or "").splitlines() if l.startswith("SPY ")]
    if not got:
        return {"error": (rc.stdout or "")[-500:] + (rc.stderr or "")[-800:]}
    return _json.loads(got[-1][4:])


def test_ltc_serve_gpl_builds_no_conductor():
    section("GPL: `ltc serve` with a GPL-style config builds no conductor, "
            "no devices and no ShowOutputs; with a schedule (Fire & Ice) "
            "it does")
    here = os.path.dirname(os.path.abspath(__file__))
    users_here = [n for n in ("ltcplay_users.json", "ltcplay_users.made")
                  if os.path.exists(os.path.join(here, n))]
    gpl = _serve_spy(["serve", "--folder", "{work}", "--no-browser",
                      "--port", "0"])
    check(gpl.get("fire_ice") is False and gpl.get("conductor") is False
          and gpl.get("mods") == [],
          f"GPL serve: no fire_ice config, no conductor, and none of "
          f"conductor, devices, fire_ice, madmapper, beyond or the "
          f"scheduler even loaded: {gpl}")
    if _sched() is None:
        _users_left_alone(here, users_here)
        return
    rule = _sched_doc(weekly={"sat": {"first_start": "18:00",
                                      "interval_min": 20,
                                      "last_end": "22:00"}}, exceptions={})
    fi = _serve_spy(["serve", "--folder", "{work}", "--no-browser", "--port", "0",
                     "--schedule", "{work}/ltcplay_schedule.json"],
                    {"ltcplay_schedule.json": rule})
    check(fi.get("fire_ice") is True and fi.get("conductor") is True and
          fi.get("dry_run") is True and "ltcplay.conductor" in fi["mods"]
          and "ltcplay.devices" not in fi["mods"],
          f"Fire & Ice serve: the conductor is built, the scheduler stays a "
          f"dry run without the switch: {fi}")
    fi2 = _serve_spy(["serve", "--folder", "{work}", "--no-browser", "--port", "0",
                      "--schedule", "{work}/ltcplay_schedule.json"],
                     {"ltcplay_schedule.json": rule,
                      "ltcplay_fire_ice.json": {"scheduler_performs": True}})
    check(fi2.get("conductor") is True and fi2.get("dry_run") is False,
          f"scheduler_performs true: the scheduler performs: {fi2}")
    _users_left_alone(here, users_here)
    print("  ok")


def _users_left_alone(here, before):
    """Review of #150: `ltc serve` in a test writes its users file and
    marker in its own temp folder, never beside the program (a stray
    marker there with no users file locks every control)."""
    after = [n for n in ("ltcplay_users.json", "ltcplay_users.made")
             if os.path.exists(os.path.join(here, n))]
    check(after == before, f"the test left {sorted(set(after) - set(before))}"
                           f" beside the program")


def test_the_gpl_path_never_loads_the_conductor():
    section("GPL: the conductor is never imported by the program")
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    top = []
    for name in sorted(os.listdir(os.path.join(here, "ltcplay"))):
        # fire_ice.py is the one module that builds a conductor, and is
        # itself imported only by `ltc serve` with a schedule: the
        # subprocess below proves the program never loads it either.
        if not name.endswith(".py") or name in ("conductor.py",
                                                "fire_ice.py"):
            continue
        for i, line in enumerate(open(os.path.join(here, "ltcplay", name),
                                      encoding="utf-8"), 1):
            if re.search(r"\bconductor\b", line) and \
                    re.match(r"\s*(from|import)\s", line):
                top.append(f"{name}:{i}")
    check(not top, f"the conductor is imported by the program: {top}")
    r = _sp.run([sys.executable, "-c",
                 "import sys; sys.path.insert(0, sys.argv[1]); "
                 "import ltcplay.session, ltcplay.web, ltcplay.cli; "
                 "print('ltcplay.conductor' in sys.modules, "
                 "'ltcplay.fire_ice' in sys.modules)", here],
                capture_output=True, text=True, timeout=60)
    check(r.stdout.strip() == "False False",
          f"loading the program loads no conductor and no fire_ice: "
          f"{r.stdout!r} {r.stderr[-300:]!r}")
    print("  ok")


# ------------------------------------------------ the flame link ----
# ltcplay/flamelink.py: ltcplay's side of flamesafe/CONTRACT.md's flame
# link. The unit tests drive it with fakes; the end-to-end test runs the
# REAL flamesafe as its own process (python -m flamesafe) and talks to it
# over real loopback UDP, so this process still never imports flamesafe.

# flamesafe's lamp words for a group its Abort disarmed (CONTRACT.md). Not
# imported (the wall): the test below checks the two files still say it.
FLAME_ABORT_WORDS = "Disarmed by the show's Stop. Cycle the arm to re-arm."


def _fl_key():
    import secrets
    # Made up per run: a real key is never written into this repo.
    return "selftest-" + secrets.token_hex(12)


class _FlJournal:
    def __init__(self):
        self.lines = []

    def __call__(self, text, **kw):
        self.lines.append((text, kw))

    def faults(self):
        return [t for t, kw in self.lines if kw.get("fault")]

    def outcomes(self):
        return [kw.get("outcome") for _t, kw in self.lines]


class _FlSock:
    """A socket that records what was sent, and fails while `failing`."""

    def __init__(self):
        self.sent = []
        self.failing = False

    def sendto(self, data, addr):
        if self.failing:
            raise OSError(111, "Connection refused")
        self.sent.append((data, addr))

    def close(self):
        pass


def _flk_unguarded(*a, **k):
    """A FlameLink with its seek guard off, for the tests written before
    the guard (2026-10-03) that test the OTHER rules: moving, released,
    the providers, the Abort. The guard itself is tested on its own, with
    the program's default (on), in test_flame_link_seek_guard."""
    from ltcplay import flamelink as fl
    k.setdefault("seek_guard", False)
    return fl.FlameLink(*a, **k)


def test_flame_link_unit():
    section("flame link: config, what goes in a frame, the wire format, "
            "zero/release/disarm_all, failing loud, the lock alarm")
    import json
    from ltcplay import flamelink as fl
    here = os.path.dirname(os.path.abspath(__file__))
    key = _fl_key()

    # Config. Every refusal is a sentence; the key is read, never built in.
    good = {"port": 5571, "universe": 1, "key": key, "frame_stale_ms": 500}
    c = fl.FlameLinkConfig.parse(good)
    check((c.ip, c.port, c.universe, c.key, c.send_hz, c.frame_stale_ms)
          == ("127.0.0.1", 5571, 1, key, 40, 500), "a minimal block parses")
    for bad in ({**good, "ip": "10.0.0.5"}, {**good, "ip": "localhost"},
                {k: v for k, v in good.items() if k != "frame_stale_ms"},
                {**good, "port": 0}, {**good, "port": True},
                {**good, "universe": 0}, {**good, "key": "short"},
                {**good, "key": "has a space in it ok"},
                {**good, "key": key + "\n"},
                {**good, "frame_stale_ms": 99},
                {**good, "frame_stale_ms": 2501},
                {**good, "frame_stale_ms": "500"},
                {k: v for k, v in good.items() if k != "key"},
                {**good, "send_hz": 19}, {**good, "send_hz": 101},
                {**good, "send_hz": 30.0}, {**good, "sendhz": 40}, []):
        try:
            fl.FlameLinkConfig.parse(bad)
            check(False, f"accepted a bad flame link block: {bad!r}")
        except fl.FlameLinkConfigError as e:
            check(str(e) and "—" not in str(e) and "–" not in str(e),
                  f"refused in a sentence with no dashes: {e}")
    ex = fl.FlameLinkConfig.from_flamesafe_config(
        os.path.join(here, "flamesafe", "flamesafe.example.json"))
    check((ex.ip, ex.port, ex.universe) == ("127.0.0.1", 5571, 1)
          and ex.key == fl.EXAMPLE_KEY,
          "flamesafe's own example config gives the link's address, "
          "universe and key, read as plain JSON")
    # Fix round 2, item 1 (the review's p11): flamesafe's OWN frame_stale_ms
    # is carried through, so the Abort repeats long enough for the real
    # flamesafe; and a flame_link block without it is refused above.
    import json as _json
    import tempfile as _tf
    exd = _json.load(open(os.path.join(here, "flamesafe",
                                       "flamesafe.example.json"),
                          encoding="utf-8"))
    exd["frame_stale_ms"] = 2500
    tmpd = _tf.mkdtemp()
    try:
        p = os.path.join(tmpd, "flamesafe.json")
        _json.dump(exd, open(p, "w", encoding="utf-8"))
        c25 = fl.FlameLinkConfig.from_flamesafe_config(p)
    finally:
        import shutil as _sh
        _sh.rmtree(tmpd, ignore_errors=True)
    check(c25.frame_stale_ms == 2500 and c25.abort_repeat_s == 2.75,
          f"flamesafe's frame_stale_ms 2500 is read from its config: the "
          f"Abort repeats {c25.abort_repeat_s} s")
    check(ex.frame_stale_ms == 500,
          f"and the example config's 500: {ex.frame_stale_ms}")
    check(fl.FlameLinkConfig("127.0.0.1", 5571, 1, key).frame_stale_ms
          == 2500, "a config built in code without it assumes the largest "
                   "frame_stale_ms flamesafe accepts, never a short one")
    src = open(os.path.join(here, "ltcplay", "flamelink.py"),
               encoding="utf-8").read()
    check(src.count(fl.EXAMPLE_KEY) == 1 and "EXAMPLE_KEY = " in src,
          "the only key written in flamelink.py is the example key, kept "
          "only to warn about it")

    # A link on fakes.
    t = [100.0]
    j = _FlJournal()
    state = {"tc": "00:00:10:00", "live": True}
    cues = {"v": None}

    def provider(tc):
        v = cues["v"]
        if isinstance(v, Exception):
            raise v
        return v

    link = _flk_unguarded(fl.FlameLinkConfig.parse(good), cues=provider,
                        show_state=lambda: (state["tc"], state["live"]),
                        journal=j, clock=lambda: t[0])
    sock = _FlSock()
    link._sock = sock
    fire = [0] * 512
    fire[410] = 200

    def last():
        return json.loads(sock.sent[-1][0])

    check(link.zeroed, "a new link starts with its cues zeroed")
    cues["v"] = fire
    link.send_frame()
    f = last()
    check(set(f) == {"v", "k", "t", "seq", "tc", "mono", "universe",
                     "values"} and f["v"] == 2 and f["k"] == key
          and f["t"] == "flame" and f["universe"] == 1
          and len(f["values"]) == 512 and f["tc"] == "00:00:10:00"
          and isinstance(f["mono"], float),
          f"a flame frame is exactly CONTRACT.md's: {sorted(f)}")
    check(json.loads(fl.encode_flame(1, None, 1.0, 1, [0] * 512, key,
                                     hazers_on=["Hazer 1"]))["hazers_on"]
          == ["Hazer 1"],
          "with hazers in flamesafe's config the frame also carries "
          "hazers_on (CONTRACT.md, optional); without any, it is left out")
    check(sock.sent[-1][1] == ("127.0.0.1", 5571), "sent to flamesafe")
    check(not any(f["values"]), "zeroed: all zeros though the cue has fire")
    check(link.release() is True, "release() answers True with the link open")
    link.send_frame()
    check(last()["values"][410] == 200, "released and live: the cue goes out")
    for what, setup in (
            ("not live (held, stopped or fading)",
             lambda: state.update(live=False)),
            ("no timecode", lambda: state.update(tc=None)),
            ("a timecode that is not HH:MM:SS:FF",
             lambda: state.update(tc="10 seconds")),
            ("a timecode with a trailing newline",
             lambda: state.update(tc="00:00:10:00\n")),
            ("a timecode with something after it",
             lambda: state.update(tc="00:00:10:00:00")),
            ("a timecode in non-ASCII digits",
             lambda: state.update(tc="٠٠:٠٠:١"
                                     "٠:٠٠")),
            ("live given as something other than True",
             lambda: state.update(live=1)),
            ("the provider raised", lambda: cues.update(v=RuntimeError("x"))),
            ("the provider answered 511 values",
             lambda: cues.update(v=fire[:511])),
            ("the provider answered a 256", lambda: cues.update(
                v=[256] + [0] * 511)),
            ("the provider answered a bool", lambda: cues.update(
                v=[True] + [0] * 511)),
            ("the provider answered None", lambda: cues.update(v=None))):
        state.update(tc="00:00:10:00", live=True)
        cues["v"] = fire
        setup()
        link.send_frame()
        check(not any(last()["values"]), f"{what}: all zeros")
    state.update(tc="00:00:10:00", live=True)
    cues["v"] = fire
    link.send_frame()
    check(last()["values"][410] == 200, "and back once it clears")
    probs = [t_ for t_, kw in j.lines if kw.get("outcome") == "cues_zero"]
    check(len(probs) == 2 and "raised" in probs[0] and "512" in probs[1],
          f"each kind of provider problem is one fault line, not one per "
          f"frame: {probs}")
    check("cues_back" in [kw.get("outcome") for _t, kw in j.lines],
          "and its end is a line")
    link.send_frame()
    link.send_frame()
    check(len([1 for _t, kw in j.lines if kw.get("outcome") == "cues_zero"])
          == 2, "a healthy frame writes nothing")
    state["tc"] = None

    def bad_state():
        raise RuntimeError("clock gone")
    link.show_state = bad_state
    link.send_frame()
    check(not any(last()["values"]) and last()["tc"] is None,
          "a show state that raises: zeros, no timecode")
    link.show_state = lambda: (state["tc"], state["live"])

    # seq and mono: up by one per datagram, mono never backwards, even when
    # the clock steps back.
    seqs = [json.loads(d)["seq"] for d, _a in sock.sent]
    check(seqs == list(range(seqs[0], seqs[0] + len(seqs))),
          "seq goes up by one per datagram")
    t[0] = 50.0
    link.send_frame()
    check(last()["mono"] >= 100.0, "mono never goes backwards")
    t[0] = 101.0

    # zero(): sends a zero frame at once.
    n = len(sock.sent)
    check(link.zero() is True and len(sock.sent) == n + 1
          and not any(last()["values"]) and link.zeroed,
          "zero() sends one all-zero frame at once and stays zeroed")

    # disarm_all: a zero frame, then the copies, one abort id, own seqs.
    link.release()
    n = len(sock.sent)
    check(link.disarm_all("Abort from the rack screen") is True,
          "disarm_all answers True when it went out")
    sent = [json.loads(d) for d, _a in sock.sent[n:]]
    check(len(sent) == 1 + fl.DISARM_COPIES and sent[0]["t"] == "flame"
          and not any(sent[0]["values"]),
          "first a zero flame frame, then the disarm copies")
    d = sent[1:]
    aid1 = link.abort_id
    check(all(set(x) == {"v", "k", "t", "seq", "mono", "id", "reason"}
              and x["t"] == "disarm_all" and x["k"] == key and x["v"] == 2
              and x["id"] == aid1
              and x["reason"] == "Abort from the rack screen"
              for x in d), f"each copy is exactly CONTRACT.md's: {d[0]}")
    check([x["seq"] for x in sent] == list(range(sent[0]["seq"],
                                                 sent[0]["seq"] + len(sent))),
          "every datagram, flame or disarm, takes the next seq")
    check(link.zeroed, "and the cues stay zero until a new release()")
    check(fl.DISARM_COPIES == 3 and fl.SEND_HZ_DEFAULT == 40
          and fl.LOCK_ALARM_S == 1.0 and fl.CONFIRM_S == 1.0,
          "the flame link's constants are pinned: changing one is a "
          "decision, made here on purpose")
    link.disarm_all("x" * 500 + "\n")
    d2 = json.loads(sock.sent[-1][0])
    check(d2["id"] == aid1 + 1 and len(d2["reason"]) <= 200,
          "a new Abort is a new id; a long reason is cut to the contract")

    # Sends that fail: one line when it starts, one when it ends. (First
    # let the Abort's repeat window run out, so each pass is one datagram.)
    t[0] += 1.0
    link.send_frame()
    check(link._abort_repeat is None, "the Abort's repeat window ends")
    j.lines.clear()
    sock.failing = True
    for _ in range(20):
        check(link.send_frame() is False, "a failed send answers False") \
            if _ == 0 else link.send_frame()
    check(link.zero() is False, "zero() answers False when it did not go out")
    check(link.disarm_all("Abort") is False,
          "disarm_all answers False when nothing went out")
    fails = [t_ for t_, kw in j.lines if kw.get("outcome") == "send_failed"]
    check(len(fails) == 1 and "Connection refused" in fails[0],
          f"one line for the whole outage: {fails}")
    check(any(kw.get("outcome") == "disarm_failed" and kw.get("fault")
              for _t, kw in j.lines),
          "a disarm that did not go out is its own fault line")
    t[0] += 3.0
    sock.failing = False
    link.send_frame()
    rec = [t_ for t_, kw in j.lines if kw.get("outcome") == "send_recovered"]
    check(len(rec) == 1 and "3.0 s" in rec[0] and "25 frame" in rec[0],
          f"and one when it ends, with how long and how many: {rec}")
    check(link.send_errors == 25 and link.snapshot()["sending_ok"],
          "the count stays; the snapshot says sending is fine again")

    # The lock alarm: flamesafe's last accepted seq not ours for > 1 s.
    j.lines.clear()
    ok = {"frames": {"seq": link.seq}}
    check(link.note_status(ok) == "", "our own seq: no alarm")
    rogue = {"frames": {"seq": link.seq + 10 ** 6}}
    link.note_status(rogue)
    t[0] += 0.9
    check(link.note_status(rogue) == "", "not ours for 0.9 s: no alarm yet")
    t[0] += 0.2
    check("not one this program sent" in link.note_status(rogue),
          "not ours for over 1 s: the alarm")
    link.note_status(rogue)
    check(len([1 for _t, kw in j.lines if kw.get("outcome") == "lock_alarm"])
          == 1, "journaled once")
    link.note_status({"frames": {"seq": None}})
    check(link.lock_alarm, "a status with no seq at all is not ours either")
    link.note_status(ok)
    check(link.lock_alarm == "" and "lock_back" in j.outcomes(),
          "clears, with a line, when ours again")

    # The disarm confirmation.
    j.lines.clear()
    link.release()
    link.disarm_all("Abort")
    aid = link.abort_id
    link.note_status({"frames": {"seq": link.seq},
                      "disarm_all": {"last_id": aid - 1}})
    link.note_status({"frames": {"seq": link.seq},
                      "disarm_all": {"last_id": aid + 1}})
    check(link._pending_abort is not None,
          "another Abort's id, larger or smaller, does not confirm this one")
    t[0] += 1.5
    link.note_status({"frames": {"seq": link.seq},
                      "disarm_all": {"last_id": aid - 1}})
    check("disarm_unconfirmed" in j.outcomes()
          and link.snapshot()["disarm_unconfirmed"],
          "not confirmed by flamesafe after 1 s: a fault")
    link.note_status({"frames": {"seq": link.seq},
                      "disarm_all": {"last_id": aid}})
    check("disarm_confirmed" in j.outcomes()
          and not link.snapshot()["disarm_unconfirmed"],
          "confirmed late: said so")
    # No status frame at all (flamesafe stopped or frozen, or no status
    # mirror): the flame frames themselves raise the fault (PR #43 review,
    # item 5).
    j.lines.clear()
    link.disarm_all("Abort")
    link.send_frame()
    check("disarm_unconfirmed" not in j.outcomes(),
          "not yet overdue: no fault")
    t[0] += 1.5
    link.send_frame()
    link.send_frame()
    check(j.outcomes().count("disarm_unconfirmed") == 1
          and link.snapshot()["disarm_unconfirmed"]
          and "NOT confirmed" in link.abort_state(),
          f"no status frame for over 1 s: one fault from the flame frames, "
          f"and the state says NOT confirmed: {j.outcomes()}")
    link.note_status({"frames": {"seq": link.seq},
                      "disarm_all": {"last_id": link.abort_id}})
    check("disarm_confirmed" in j.outcomes(), "and a late confirm still says so")
    check(link.note_status("garbage") == "", "a garbage status never raises")

    # Status frames: only ours.
    good_st = json.dumps({"v": 2, "t": "status", "k": key}).encode()
    check(fl.decode_status(good_st, key) is not None, "our status decodes")
    for bad in (json.dumps({"v": 2, "t": "status", "k": "other"}).encode(),
                json.dumps({"v": 1, "t": "status", "k": key}).encode(),
                json.dumps({"v": 2, "t": "flame", "k": key}).encode(),
                b"\xff", b"[]", None):
        check(fl.decode_status(bad, key) is None,
              f"not our status frame: {bad!r}")

    # The example key is a fault line at open.
    j2 = _FlJournal()
    l2 = _flk_unguarded(fl.FlameLinkConfig.parse({**good,
                                                "key": fl.EXAMPLE_KEY}),
                      journal=j2)
    l2.open()
    check("example_key" in j2.outcomes() and j2.faults(),
          "the repo's example key is a fault line at open")
    l2.stop()
    check(l2.zero() is False and l2.release() is False,
          "a stopped link says its calls did not go out")

    # audio_master_state on a stand-in clock.
    class Clk:
        playing, paused, _halting, last_sent = True, False, False, (0, 1, 2, 3)
    clk = Clk()
    st = fl.audio_master_state(lambda: clk)
    check(st() == ("00:01:02:03", True), f"a playing clock is live: {st()}")
    clk.paused = True
    check(st() == ("00:01:02:03", False), "paused (or fading into it): not "
                                          "live")
    clk.paused, clk._halting = False, True
    check(st()[1] is False, "fading out on an Abort: not live")
    clk._halting, clk.playing = False, False
    check(st() == (None, False), "stopped: no timecode, not live")
    check(fl.audio_master_state(lambda: None)() == (None, False),
          "no clock: not live")

    # The lamp words, in flamesafe and on the deck, without importing either
    # side into the other.
    comp = open(os.path.join(here, "flamesafe", "composer.py"),
                encoding="utf-8").read()
    contract = open(os.path.join(here, "flamesafe", "CONTRACT.md"),
                    encoding="utf-8").read()
    check(FLAME_ABORT_WORDS in comp and FLAME_ABORT_WORDS in contract,
          "the abort lamp words are the same in composer.py and CONTRACT.md")
    from ltcplay import streamdeck as sd
    look = sd.group_look({"armed": "held", "reason": FLAME_ABORT_WORDS,
                          "amber": "flashing", "dwell_s": 0})
    check(look[0] == "STOPPED" and look[4] is True,
          f"the deck shows STOPPED, flashing (cycle the arm): {look}")
    old = sd.group_look({"armed": "held", "reason": "Disarmed by the show's "
                         "Abort. Cycle the arm to re-arm.",
                         "amber": "flashing", "dwell_s": 0})
    check(old[0] == "STOPPED",
          f"an older flamesafe's words for it (Abort) read the same: {old}")
    print("  ok")


class _FlBadSock(_FlSock):
    """sendto raises something that is not an OSError while `mode` says
    so: "raise" an ordinary exception, "die" a BaseException."""

    class Die(BaseException):
        pass

    def __init__(self):
        super().__init__()
        self.mode = None

    def sendto(self, data, addr):
        if self.mode == "raise":
            raise RuntimeError("not a socket error")
        if self.mode == "die":
            raise self.Die("gone")
        super().sendto(data, addr)


def test_show_timing_diagnostics_and_priority():
    section("show PC timing (2026-10-04): the flame link keeps its sender's "
            "worst sleep overrun per minute for /api/conductor, and the show "
            "audio raises its own priority only when the Windows "
            "supervisor's scheduling protection asks (never on a Mac)")
    from ltcplay import flamelink as fl
    from ltcplay import showaudio as sa
    cfg = fl.FlameLinkConfig.parse({"port": 9, "universe": 1,
                                    "key": _fl_key(), "send_hz": 40,
                                    "frame_stale_ms": 500})
    link = fl.FlameLink(cfg)
    link._note_oversleep(0.004)
    link._note_oversleep(0.120)
    link._note_oversleep(0.010)
    by = link.snapshot()["oversleep_ms_by_minute"]
    check(list(by.values()) == [120.0],
          f"the worst overrun of the minute, in ms: {by}")
    for k in range(20):
        link._oversleep[k] = 1.0
    link._note_oversleep(0.001)
    check(len(link._oversleep) <= 16, "only the last 15 minutes are kept")
    calls = []
    saved = os.environ.get("LTCPLAY_PRIORITY")
    os.environ.pop("LTCPLAY_PRIORITY", None)
    try:
        sa._raise_priority()
        check(True, "unset: it does nothing and never raises")
        os.environ["LTCPLAY_PRIORITY"] = "high"
        sa._raise_priority()     # not Windows here: still nothing, no raise
        check(not calls, "set, but not Windows: nothing")
    finally:
        if saved is None:
            os.environ.pop("LTCPLAY_PRIORITY", None)
        else:
            os.environ["LTCPLAY_PRIORITY"] = saved
    print("  ok")


def test_flame_link_fix_round_1():
    section("flame link, fix round 1 of PR #34: the Abort repeats past "
            "frame_stale_ms, only its own id confirms it, seq and ids start "
            "at random, a still timecode is zeros, the sender thread "
            "survives and says so, zero() and disarm_all() never ask the "
            "providers")
    import json
    import threading
    from ltcplay import flamelink as fl
    key = _fl_key()
    good = {"port": 5571, "universe": 1, "key": key, "frame_stale_ms": 500}
    fire = [0] * 512
    fire[410] = 200

    def make(clock, sock=None, cfg=None, **kw):
        lk = _flk_unguarded(fl.FlameLinkConfig.parse({**good, **(cfg or {})}),
                          clock=clock, **kw)
        lk._sock = sock if sock is not None else _FlSock()
        return lk, lk._sock

    def sent(sock, since=0):
        return [json.loads(d) for d, _a in sock.sent[since:]]

    # -- a late frame is journaled with where the time went (show PC,
    # 2026-10-04: a 71 ms gap with no show running) ----------------------
    tl = [100.0]
    calls = [0]
    jl = _FlJournal()

    def late_sleep(d):
        calls[0] += 1
        tl[0] += d + (0.06 if calls[0] == 5 else 0.0)
        if calls[0] >= 12:
            lkl._stop.set()
    lkl, _sl = make(lambda: tl[0], journal=jl, sleep=late_sleep)
    lkl._run()
    late = [x for x, kw in jl.lines if kw.get("outcome") == "late_frame"]
    check(len(late) == 1 and "took 85.0 ms" in late[0] and
          lkl.snapshot()["late_frames"] == 1 and
          lkl.snapshot()["late_worst_ms"] >= 80.0,
          f"a frame 85 ms late is journaled once, naming the sleep that "
          f"overran: {late} {lkl.snapshot().get('late_frames')}")

    # -- item 1: one Abort, repeated once per frame past frame_stale_ms ----
    check(fl.ABORT_REPEAT_MIN_S == 0.75 and fl.TC_STILL_S == 0.1,
          "the repeat and still-timecode constants are pinned")
    check(fl.FlameLinkConfig.parse(good).abort_repeat_s == 0.75
          and fl.FlameLinkConfig.parse(
              {**good, "frame_stale_ms": 2000}).abort_repeat_s == 2.25,
          "an Abort repeats for 0.75 s, or 0.25 s past a longer "
          "frame_stale_ms")
    t = [100.0]
    j = _FlJournal()
    lk, sock = make(lambda: t[0], journal=j)
    check(lk.disarm_all("Abort from the rack screen") is True, "sent")
    aid = lk.abort_id
    line = [x for x, kw in j.lines if kw.get("outcome") == "disarm_sent"]
    check(len(line) == 1 and "NOT yet confirmed by flamesafe" in line[0]
          and "repeating it every frame for 0.75 s" in line[0],
          f"the journal says sent, not done: {line}")
    check(lk.snapshot()["abort"] == "sent, not yet confirmed by flamesafe",
          f"and so does the snapshot: {lk.snapshot()['abort']!r}")
    copies, flames = [], 0
    for _ in range(48):                  # 1.2 s at 40 Hz
        t[0] += 0.025
        n = len(sock.sent)
        lk.send_frame()
        new = sent(sock, n)
        flames += sum(1 for x in new if x["t"] == "flame")
        copies += [(t[0] - 100.0, x) for x in new if x["t"] == "disarm_all"]
    times = [round(tt, 3) for tt, _x in copies]
    check(flames == 48 and 29 <= len(copies) <= 30
          and {x["id"] for _tt, x in copies} == {aid}
          and max(times) <= 0.75 and min(times) == 0.025,
          f"one copy of the same Abort after every frame for 0.75 s, then "
          f"none: {len(copies)} copies, {times[:2]}..{times[-2:]}")
    seqs = [x["seq"] for x in sent(sock)]
    check(seqs == list(range(seqs[0], seqs[0] + len(seqs))),
          "every copy takes the next seq")
    lk.note_status({"frames": {"seq": lk.seq},
                    "disarm_all": {"last_id": aid}})
    ok = [x for x, kw in j.lines if kw.get("outcome") == "disarm_confirmed"]
    # 1.2 s of frames with no status frame: since PR #43's fix round 1
    # (item 5) the flame frames themselves raised "not confirmed" at 1 s,
    # so this confirmation is a late one, and says so.
    bad = [x for x, kw in j.lines if kw.get("outcome") == "disarm_unconfirmed"]
    check(lk.snapshot()["abort"] == "confirmed by flamesafe" and len(ok) == 1
          and "late" in ok[0] and len(bad) == 1,
          f"flamesafe's own status confirms it, and only then is it said "
          f"(late, after the 1 s fault): {ok} {bad}")
    # Every immediate copy lost (the review's p6): the repeats carry it.
    lk2, sock2 = make(lambda: t[0], cfg={"frame_stale_ms": 2000})
    sock2.failing = True
    check(lk2.disarm_all("Abort") is False,
          "nothing went out at once: disarm_all says so")
    sock2.failing = False
    got = []
    for _ in range(100):                 # 2.5 s
        t[0] += 0.025
        n = len(sock2.sent)
        lk2.send_frame()
        got += [(t[0], x) for x in sent(sock2, n) if x["t"] == "disarm_all"]
    check(got and {x["id"] for _t, x in got} == {lk2.abort_id}
          and got[-1][0] - got[0][0] > 2.0,
          f"...and the same Abort still reaches flamesafe on the next "
          f"frames, for longer than its frame_stale_ms: {len(got)} copies")

    # -- items 3 and 4: random starts; only this Abort's id confirms it ----
    a, _sa = make(time.perf_counter)
    b, _sb = make(time.perf_counter)
    check(min(a.seq, b.seq, a.abort_id, b.abort_id) >= fl.RANDOM_START_MIN
          and a.seq != b.seq and a.abort_id != b.abort_id,
          f"seq and abort ids start at a random large number per link: "
          f"{a.seq} {b.seq} {a.abort_id} {b.abort_id}")
    # A rogue holding flamesafe's lock, counting up from 1 like any fresh
    # sender (the review's p4 a20): its seq is never "ours".
    t5 = [0.0]
    j5 = _FlJournal()
    lk5, _s5 = make(lambda: t5[0], journal=j5)
    alarm = ""
    for i in range(30):
        t5[0] += 0.05
        lk5.send_frame()
        alarm = lk5.note_status({"frames": {"seq": 2 + i}}) or alarm
    check("not one this program sent" in alarm
          and "lock_alarm" in j5.outcomes(),
          f"a rogue counting from 1 raises the lock alarm: {alarm!r}")
    # A restarted ltcplay whose Abort flamesafe refused, with flamesafe
    # still reporting an earlier run's Abort (the review's p4 b).
    t6 = [0.0]
    j6 = _FlJournal()
    lk6, _s6 = make(lambda: t6[0], journal=j6)
    lk6.disarm_all("Abort from the rack screen")
    for _ in range(30):
        t6[0] += 0.05
        lk6.note_status({"frames": {"seq": 2},
                         "disarm_all": {"accepted": 12, "last_id": 4}})
    check(lk6._pending_abort is not None and "disarm_unconfirmed"
          in j6.outcomes()
          and lk6.snapshot()["abort"] == "sent but NOT confirmed by flamesafe",
          f"an earlier run's Abort never confirms this one: "
          f"{lk6.snapshot()['abort']!r}")

    # -- item 5: a timecode that is not moving is zeros --------------------
    t7 = [10.0]
    j7 = _FlJournal()
    st7 = {"tc": "00:00:10:00"}
    lk7, s7 = make(lambda: t7[0], journal=j7, cues=lambda tc: fire,
                   show_state=lambda: (st7["tc"], True))
    lk7.release()

    def val7():
        lk7.send_frame()
        return json.loads(s7.sent[-1][0])["values"][410]

    check(val7() == 200, "a moving show: the cue goes out")
    t7[0] += 0.05
    check(val7() == 200, "the same frame 50 ms later: still moving")
    t7[0] += 0.06
    check(val7() == 0, "the same frame 110 ms after it last changed: zeros")
    for _ in range(10):
        t7[0] += 0.025
        val7()
    still = [x for x, kw in j7.lines if kw.get("outcome") == "cues_zero"]
    check(len(still) == 1 and "has not moved" in still[0],
          f"one fault line for the whole stall: {still}")
    st7["tc"] = "00:00:10:01"
    check(val7() == 200 and "cues_back" in j7.outcomes(),
          "it moves again: the cue goes out, and that is a line")

    # Jeff, 2026-10-07: the stop while a Resume settles (the clock holds
    # the frame the Hold froze until the audio reaches the next one) is a
    # NOTE; the cues are zeros all the same. A freeze with no Hold behind
    # it, or one that outlasts the settle, stays a fault.
    t9 = [10.0]
    j9 = _FlJournal()
    st9 = {"tc": "00:00:30:13", "live": True}
    lk9, s9 = make(lambda: t9[0], journal=j9, cues=lambda tc: fire,
                   show_state=lambda: (st9["tc"], st9["live"]))
    lk9.release()

    def val9():
        lk9.send_frame()
        return json.loads(s9.sent[-1][0])["values"][410]

    def kinds9():
        return [(kw.get("outcome"), bool(kw.get("fault")))
                for _x, kw in j9.lines if kw.get("action") == "flame_link"
                and str(kw.get("outcome", "")).startswith("cues_zero")]
    check(val9() == 200, "Hold test: the show runs, the cue goes out")
    t9[0] += 0.03
    st9["tc"] = "00:00:30:14"
    val9()
    st9["live"] = False                     # Hold: frozen on 30:14
    for _ in range(40):
        t9[0] += 0.025
        check(val9() == 0, "Hold test: held, zeros")
    st9["live"] = True                      # Resume: same frame a while
    t9[0] += 0.025
    check(val9() == 0, "a Resume still on the held frame: zeros all the same")
    for _ in range(3):
        t9[0] += 0.025
        val9()
    check(kinds9() == [("cues_zero_note", False)],
          f"a stop while the Resume settles is one note, not a fault: "
          f"{kinds9()}")
    st9["tc"] = "00:00:30:15"
    t9[0] += 0.025
    check(val9() == 200, "the Resume settles: the cue goes out again")
    t9[0] += 0.2                            # a freeze with no Hold
    check(val9() == 0 and kinds9()[-1] == ("cues_zero", True),
          f"a freeze with no Hold behind it stays a fault: {kinds9()}")
    st9["tc"] = "00:00:30:16"
    t9[0] += 0.025
    val9()
    st9["live"] = False                     # another Hold...
    t9[0] += 0.025
    val9()
    st9["live"] = True                      # ...whose Resume never moves
    n9 = len(kinds9())
    for _ in range(60):
        t9[0] += 0.025
        val9()
    check(kinds9()[n9:] == [("cues_zero_note", False), ("cues_zero", True)],
          f"a Resume that never moves turns into a fault after "
          f"{fl.RESUME_SETTLE_S:g} s: {kinds9()[n9:]}")

    class Frozen:      # the review's p9: a clock thread that stopped
        playing, paused, _halting, last_sent = True, False, False, (0, 1, 2, 3)
    t8 = [0.0]
    lk8, s8 = make(lambda: t8[0], cues=lambda tc: fire,
                   show_state=fl.audio_master_state(lambda: Frozen()))
    lk8.release()
    nz = 0
    for _ in range(120):               # 3 s at 40 Hz
        t8[0] += 0.025
        lk8.send_frame()
        nz += any(json.loads(s8.sent[-1][0])["values"])
    check(nz <= 5, f"a frozen AudioMaster: zeros after 0.1 s (5 frames at "
                   f"40 Hz), not 3 s of "
                   f"cue ({nz} of 120 frames carried it)")

    # -- item 6: the sender thread survives, and says when it cannot -------
    class Weird(Exception):
        def __str__(self):
            raise RuntimeError("no words")

    def weird_state():
        raise Weird()
    j9 = _FlJournal()
    lk9, s9 = make(time.perf_counter, journal=j9, show_state=weird_state)
    check(lk9.send_frame() is True and not any(
        json.loads(s9.sent[-1][0])["values"]),
          "a show state raising an exception whose str() raises: zeros")
    check(any("could not be read" in x for x in j9.faults()),
          f"and a fault line, not a dead sender: {j9.faults()}")
    j10 = _FlJournal()
    bad = _FlBadSock()
    lk10, _s10 = make(time.perf_counter, sock=bad, journal=j10)

    def settle(cond, secs=1.0):
        end = time.perf_counter() + secs
        while time.perf_counter() < end and not cond():
            time.sleep(0.01)
        return cond()
    lk10.start()
    try:
        check(settle(lambda: len(bad.sent) > 3)
              and lk10.snapshot()["sender"] == "running"
              and lk10.snapshot()["sending_ok"],
              f"running: {lk10.snapshot()['sender']}")
        bad.mode = "raise"
        check(settle(lambda: lk10.run_errors > 3)
              and lk10.snapshot()["sender"] == "failing"
              and not lk10.snapshot()["sending_ok"],
              f"a pass that raises: the snapshot says failing: "
              f"{lk10.snapshot()['sender']}")
        check(j10.outcomes().count("sender_failed") == 1,
              f"one line for the episode: {j10.outcomes()}")
        n = len(bad.sent)
        bad.mode = None
        check(settle(lambda: len(bad.sent) > n + 3)
              and lk10.snapshot()["sender"] == "running"
              and "sender_recovered" in j10.outcomes(),
              "the loop carried on, and its recovery is a line")
        bad.mode = "die"
        check(settle(lambda: lk10.snapshot()["sender"] == "dead")
              and not lk10.snapshot()["sending_ok"]
              and "sender_dead" in j10.outcomes(),
              f"a thread that ends without stop(): dead, and journaled: "
              f"{lk10.snapshot()['sender']} {j10.outcomes()}")
    finally:
        bad.mode = None
        lk10.stop()

    # -- item 7: zero() and disarm_all() never ask the providers -----------
    t11 = [0.0]
    calls = [0]
    st11 = {"n": 0, "zero_inside": False}

    def state11():
        calls[0] += 1
        st11["n"] += 1
        return (f"00:00:{st11['n'] // 25 % 60:02d}:{st11['n'] % 25:02d}",
                True)

    def cues11(tc):
        if st11["zero_inside"]:
            # A zero() and then a release() land while this frame's cues
            # are being read: the frame was read before the zero, so it
            # must not go out with those values, released or not.
            st11["zero_inside"] = False
            lk11.zero()
            lk11.release()
        return fire
    lk11, s11 = make(lambda: t11[0], show_state=state11, cues=cues11)
    lk11.release()
    lk11.send_frame()
    check(json.loads(s11.sent[-1][0])["values"][410] == 200,
          "released, live, moving: the cue goes out")
    c0, n0 = calls[0], len(s11.sent)
    lk11.zero()
    f = sent(s11, n0)
    check(calls[0] == c0 and len(f) == 1 and not any(f[0]["values"]),
          "zero()'s own frame is zeros and asked no provider")
    lk11.release()
    lk11.send_frame()
    c0, n0 = calls[0], len(s11.sent)
    lk11.disarm_all("Abort")
    f = sent(s11, n0)
    check(calls[0] == c0 and f[0]["t"] == "flame" and not any(f[0]["values"]),
          "disarm_all's own first frame is zeros and asked no provider")
    lk11.release()
    st11["zero_inside"] = True
    n0 = len(s11.sent)
    lk11.send_frame()
    f = [x for x in sent(s11, n0) if x["t"] == "flame"]
    check(len(f) == 2 and not any(f[0]["values"]) and not any(f[1]["values"]),
          "a frame whose cues were read before a zero() landed goes out as "
          "zeros, even if a release() followed it")
    n0 = len(s11.sent)
    lk11.send_frame()
    f = [x for x in sent(s11, n0) if x["t"] == "flame"]
    check(len(f) == 1 and f[0]["values"][410] == 200,
          "and the next frame, read after the release, carries the cue")
    # Zeroed, the cue provider is not even asked (send_frame would zero its
    # answer anyway; not asking it means a broken provider cannot fill the
    # journal while no show is released).
    asked = []
    t13 = [0.0]
    lk13, s13 = make(lambda: t13[0], cues=lambda tc: asked.append(tc) or fire,
                     show_state=lambda: (f"00:00:00:{len(s13.sent) % 25:02d}",
                                         True))
    for _ in range(5):
        lk13.send_frame()
    check(not asked and not any(json.loads(s13.sent[-1][0])["values"]),
          f"zeroed: zeros, and the cue provider was never asked: {asked}")
    lk13.release()
    lk13.send_frame()
    check(len(asked) == 1, "released: it is asked")

    # A provider that hangs, on the real thread: the Abort does not wait.
    gate = threading.Event()
    hang = {"on": False}

    def state12():
        if hang["on"]:
            gate.wait(3.0)
        return (None, False)
    lk12, _s12 = make(time.perf_counter, show_state=state12)
    lk12.start()
    try:
        time.sleep(0.05)
        hang["on"] = True
        time.sleep(0.1)            # the sender thread is now stuck in it
        t0 = time.perf_counter()
        ok1 = lk12.disarm_all("Abort from the rack screen")
        ok2 = lk12.zero()
        dt = time.perf_counter() - t0
        # Half the 3 s hang: waiting on it takes 3 s, not waiting takes ms.
        check(ok1 and ok2 and dt < 1.5,
              f"a show state hung for 3 s does not hold up disarm_all() or "
              f"zero(): {dt:.3f} s")
    finally:
        gate.set()
        lk12.stop()
    print("  ok")


def test_flame_link_fix_round_2():
    section("flame link, fix round 2 of PR #34: a sender stuck without "
            "raising reads as stalled and says so once; an Abort voids a "
            "frame read before it; a resume is not a stuck timecode")
    import json
    import threading
    from ltcplay import flamelink as fl
    key = _fl_key()
    good = {"port": 5571, "universe": 1, "key": key, "frame_stale_ms": 500}
    fire = [0] * 512
    fire[410] = 200

    def settle(cond, secs=2.0):
        end = time.perf_counter() + secs
        while time.perf_counter() < end and not cond():
            time.sleep(0.01)
        return cond()

    # -- item 2: a provider that blocks without raising (the review's p13)
    gate = threading.Event()
    hang = {"on": False}
    n = {"i": 0}

    def state():
        if hang["on"]:
            gate.wait(5.0)
        n["i"] += 1
        return (f"00:00:{n['i'] // 25 % 60:02d}:{n['i'] % 25:02d}", True)
    j = _FlJournal()
    lk = _flk_unguarded(fl.FlameLinkConfig.parse(good), show_state=state,
                      journal=j)
    lk._sock = _FlSock()
    check(lk.stall_s() == 0.25, f"stalled after half of frame_stale_ms: "
                                f"{lk.stall_s()}")
    lk.start()
    try:
        check(settle(lambda: len(lk._sock.sent) > 3)
              and lk.snapshot()["sender"] == "running", "running at first")
        hang["on"] = True
        check(settle(lambda: lk.snapshot()["sender"] == "stalled"),
              f"a provider blocking without raising: stalled: "
              f"{lk.snapshot()['sender']}")
        check(not lk.snapshot()["sending_ok"], "and sending_ok is False")
        time.sleep(0.6)
        check(j.outcomes().count("sender_stalled") == 1
              and any("no flame frame" in t for t in j.faults()),
              f"journaled once for the episode, as a fault: {j.outcomes()}")
        hang["on"] = False
        gate.set()
        check(settle(lambda: lk.snapshot()["sender"] == "running")
              and settle(lambda: "sender_unstalled" in j.outcomes()),
              f"frames again: running, and that is a line: {j.outcomes()}")
    finally:
        hang["on"] = False
        gate.set()
        lk.stop()

    # The journal itself blocking (a stuck console or file write): the
    # snapshot still answers at once, and says stalled.
    block = threading.Event()
    release = threading.Event()

    def stuck_journal(text, **kw):
        if block.is_set() and "cues are zero" in text:
            release.wait(5.0)
    m = {"i": 0}

    def state2():
        m["i"] += 1
        return (f"00:00:01:{m['i'] % 25:02d}", True)
    lk2 = _flk_unguarded(fl.FlameLinkConfig.parse(good), show_state=state2,
                       cues=lambda tc: "garbage" if block.is_set() else None,
                       journal=stuck_journal)
    lk2._sock = _FlSock()
    lk2.start()
    lk2.release()
    try:
        time.sleep(0.15)
        block.set()
        time.sleep(0.5)
        t0 = time.perf_counter()
        snap = lk2.snapshot()
        dt = time.perf_counter() - t0
        check(snap["sender"] == "stalled" and not snap["sending_ok"]
              and dt < 0.1,
              f"a journal call stuck in the sender: the snapshot answers in "
              f"{dt * 1000:.0f} ms and says {snap['sender']!r}")
    finally:
        release.set()
        lk2.stop()

    # -- item 3 (R33): a disarm_all landing while a frame's cues are read
    # voids that frame, even if a release() follows it.
    t3 = [0.0]
    st3 = {"n": 0, "abort_inside": False}

    def state3():
        st3["n"] += 1
        return (f"00:00:{st3['n'] // 25 % 60:02d}:{st3['n'] % 25:02d}",
                True)

    def cues3(tc):
        if st3["abort_inside"]:
            st3["abort_inside"] = False
            lk3.disarm_all("Abort")
            lk3.release()
        return fire
    lk3 = _flk_unguarded(fl.FlameLinkConfig.parse(good), clock=lambda: t3[0],
                       show_state=state3, cues=cues3)
    lk3._sock = _FlSock()
    lk3.release()
    lk3.send_frame()
    st3["abort_inside"] = True
    n0 = len(lk3._sock.sent)
    lk3.send_frame()
    flames = [json.loads(d) for d, _a in lk3._sock.sent[n0:]]
    flames = [x for x in flames if x["t"] == "flame"]
    check(len(flames) == 2 and not any(flames[-1]["values"]),
          "a frame whose cues were read before an Abort landed goes out as "
          "zeros, even if a release() followed it")

    # A resume is not a stuck timecode: with the timecode moving through
    # the hold, the first live frame after it carries its cue.
    t4 = [0.0]
    st4 = {"n": 0, "live": False}

    def state4():
        return (f"00:00:{st4['n'] // 25 % 60:02d}:{st4['n'] % 25:02d}",
                st4["live"])
    lk4 = _flk_unguarded(fl.FlameLinkConfig.parse(good), clock=lambda: t4[0],
                       show_state=state4, cues=lambda tc: fire)
    lk4._sock = _FlSock()
    lk4.release()
    for _ in range(40):            # a second of a held show, clock moving
        t4[0] += 0.025
        st4["n"] += 1
        lk4.send_frame()
    st4["live"] = True             # resume: same moment, timecode moving
    t4[0] += 0.025
    st4["n"] += 1
    lk4.send_frame()
    check(json.loads(lk4._sock.sent[-1][0])["values"][410] == 200,
          "the first frame after a resume carries the cue")
    print("  ok")


# How long a Stream Deck may take, beyond its arm-hold, to deliver the
# hold's "wanted" after a press it began before a screen Abort, and still
# be refused by flamesafe's post-Abort window (fix round 2, item 4; the
# review's probe p12 found the edge at a 0.45 s deck stall).
DECK_LATENCY_SLACK_S = 0.3


def test_the_deck_arm_hold_fits_inside_the_post_abort_window():
    section("the Stream Deck's arm-hold is shorter than flamesafe's "
            "post-Abort window, with room for the deck to be late")
    # flamesafe refuses, for min_arm_dwell_ms after the last copy of a
    # screen Abort, a low that was already going on at it. A hold begun
    # before the Abort completes at most ARM_HOLD_S after it, so it is
    # refused only while ARM_HOLD_S (plus the deck's own lateness) is
    # under the SHORTEST dwell flamesafe allows. Read from both files as
    # text: this process never imports flamesafe (the wall).
    import re as _re
    from ltcplay import streamdeck as sd
    here = os.path.dirname(os.path.abspath(__file__))
    cfg_src = open(os.path.join(here, "flamesafe", "config.py"),
                   encoding="utf-8").read()
    mm = _re.search(r"^DWELL_MS_MIN, DWELL_MS_MAX = (\d+), (\d+)", cfg_src,
                    _re.M)
    check(mm is not None, "flamesafe/config.py still states DWELL_MS_MIN")
    dwell_min_s = int(mm.group(1)) / 1000.0 if mm else 0.0
    check(sd.ARM_HOLD_S + DECK_LATENCY_SLACK_S <= dwell_min_s,
          f"the deck's arm-hold ({sd.ARM_HOLD_S} s) plus "
          f"{DECK_LATENCY_SLACK_S} s for the deck to be late must fit in "
          f"flamesafe's shortest re-arm dwell ({dwell_min_s} s), or a hold "
          f"begun before a screen Abort can arm after it")
    print("  ok")


def test_flame_link_sends_at_its_rate_on_one_socket():
    section("flame link: a real socket, at send_hz, all from one source "
            "port, zeros when idle")
    import json
    import socket as _so
    from ltcplay import flamelink as fl
    rx = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
    rx.bind(("127.0.0.1", 0))
    rx.settimeout(0.5)
    cfg = fl.FlameLinkConfig.parse({"port": rx.getsockname()[1],
                                    "universe": 1, "key": _fl_key(),
                                    "send_hz": 40, "frame_stale_ms": 500})
    # A plain time.sleep(0.025) loop on a thread of its own, running WHILE
    # the frames are measured: whether this machine can keep a 25 ms sleep
    # is judged over the same second as the sender, not over a quiet
    # half-second before it. (Calibrating first and measuring after read
    # fit=True and then 11 frames in a second on a CI runner that was
    # starved only during the measurement.)
    import threading as _th
    sl = []

    def reference():
        for _ in range(36):
            w0 = time.perf_counter()
            time.sleep(0.025)
            sl.append(time.perf_counter() - w0)
    ref = _th.Thread(target=reference, daemon=True)
    link = fl.FlameLink(cfg).start()
    got, srcs = [], set()
    ref.start()
    end = time.perf_counter() + 1.0
    try:
        while time.perf_counter() < end:
            try:
                d, a = rx.recvfrom(65535)
            except _so.timeout:
                break
            got.append(json.loads(d))
            srcs.add(a)
    finally:
        link.stop()
        rx.close()
    ref.join(5)
    check(len(srcs) == 1, f"every frame from ONE socket: {srcs}")
    check(all(not any(f["values"]) and f["tc"] is None for f in got),
          "idle, nothing wired: every frame is all zeros with no timecode")
    # Fix round 1, item 8: this used to say "never more than 50 ms between
    # frames" of a real thread on a shared machine, and failed at 0.051 s
    # when the OS was slow to wake it. What the CODE schedules is proved
    # exactly below, on a fake clock; here the real thread has to keep its
    # rate (mean gap near 25 ms), keep 95% of its gaps inside the
    # contract's 50 ms floor, and never leave a gap anywhere near
    # flamesafe's smallest frame_stale_ms (100 ms), the gap that matters.
    # The mean, not the median: on Windows a wait lands on a 15.6 ms timer
    # tick, so the gaps alternate about 31 and 16 ms around a true 25 ms.
    gaps = sorted(b["mono"] - a["mono"] for a, b in zip(got, got[1:]))
    mean = sum(gaps) / len(gaps) if gaps else 0
    p95 = gaps[int(len(gaps) * 0.95)] if gaps else 0
    # The same calibration as test_pixel_output_frame_jitter: these bounds
    # only mean anything on a machine that could keep a 25 ms sleep while
    # the frames were being sent (the reference thread above). CI runners
    # have been seen taking 80 to 170 ms over time.sleep(0.025) at this
    # point in the run; there the fake-clock proof below carries it.
    fit = bool(sl) and sorted(sl)[len(sl) // 2] < 0.035 and max(sl) <= 0.075
    print(f"  note: {len(got)} frames in 1 s, mean gap {mean * 1000:.1f}ms, "
          f"95% under {p95 * 1000:.1f}ms, longest "
          f"{(gaps[-1] if gaps else 0) * 1000:.1f}ms; time.sleep(0.025) here "
          f"took {min(sl) * 1000:.0f} to {max(sl) * 1000:.0f}ms; "
          f"{_th.active_count()} threads alive (fit={fit})")
    check(len(got) > 0, "the real sender thread sent nothing in 1 s")
    if fit:
        check(len(got) >= 30, f"about 40 frames in a second, at least the "
                              f"contract's 20 Hz floor with room: {len(got)}")
        check(gaps and 0.02 <= mean <= 0.03 and p95 < 0.05 and gaps[-1] < 0.1,
              f"at its rate on a real thread: mean gap {mean:.4f} s, 95% "
              f"under {p95:.3f} s, longest {gaps[-1] if gaps else 0:.3f} s "
              f"(flamesafe's shortest frame_stale_ms is 0.100 s)")
    else:
        print("  note: this machine cannot keep a 25 ms sleep right now, so "
              "the real-thread rate bounds are not applied here; the "
              "fake-clock schedule check below proves the pacing regardless "
              "of the machine")

    # The schedule itself, on a fake clock: exactly one period between
    # frames, and after a stall (the OS late to wake the thread) the next
    # frame comes straight away and then one period at a time again, never
    # a burst to catch up.
    clk = [0.0]
    late = {50: 0.2}

    class FakeStop:
        def __init__(self, n):
            self.n = n
            self.waits = 0

        def is_set(self):
            return self.n <= 0

        def set(self):
            self.n = 0

        def clear(self):
            pass
    stop_after = FakeStop(120)

    def fake_sleep(d):
        stop_after.waits += 1
        clk[0] += d + late.get(stop_after.waits, 0.0)
        stop_after.n -= 1
    paced = fl.FlameLink(cfg, clock=lambda: clk[0], sleep=fake_sleep)
    psock = _FlSock()
    paced._sock = psock
    paced._stop = stop_after
    paced._run()
    monos = [json.loads(d)["mono"] for d, _a in psock.sent]
    pg = [round(b - a, 6) for a, b in zip(monos, monos[1:])]
    period = 1.0 / 40
    stall = [g for g in pg if g > period + 1e-6]
    check(len(monos) >= 100 and len(stall) == 1
          and abs(stall[0] - (period + 0.2)) < 1e-6
          and all(abs(g - period) < 1e-6 for g in pg if g not in stall),
          f"the schedule: one period between frames, the stall once, no "
          f"burst after it: {sorted(set(pg))}")


def test_flame_link_schedule_absolute_deadlines_no_burst():
    section("flame link timing (2026-10-29): absolute deadlines on a fake "
            "clock, no drift from late wakes, and after a stall the latest "
            "frame once and then the next grid point, never a burst")
    import json
    from ltcplay import flamelink as fl
    P = 0.025
    nd = fl.next_deadline
    G = P * fl.MIN_GAP_SHARE                 # 5 ms at 40 a second
    # Waking late is made up on the next sleep: the deadlines stay on the
    # grid of the first frame (no drift builds up, the rate stays 40).
    check(abs(nd(1.000, 1.003, P) - 1.025) < 1e-9 and
          abs(nd(1.025, 1.0374, P) - 1.050) < 1e-9 and
          abs(nd(1.000, 1.019, P) - 1.025) < 1e-9,
          "a late wake keeps the grid")
    # The next grid point too close (or gone): skipped, never sent late.
    check(abs(nd(1.000, 1.022, P) - 1.050) < 1e-9 and
          abs(nd(1.000, 1.200, P) - 1.225) < 1e-9 and
          abs(nd(1.000, 1.2051, P) - 1.225) < 1e-9 and
          abs(nd(1.000, 1.2210, P) - 1.250) < 1e-9,
          "behind: the next grid point at least 5 ms away")
    for now in (1.0, 1.001, 1.0124, 1.0126, 1.02, 1.0201, 1.0249, 1.03,
                1.3, 5.0, 5.0123):
        got = nd(1.0, now, P)
        steps = (got - 1.0) / P
        check(got - now >= G - 1e-9 and abs(steps - round(steps)) < 1e-6,
              f"on the grid and never sooner than 5 ms: {now} -> {got}")

    cfg = fl.FlameLinkConfig.parse({"port": 5571, "universe": 1,
                                    "key": _fl_key(), "send_hz": 40,
                                    "frame_stale_ms": 500})

    def run(late, n=200, early=0.0):
        """The real _run on a fake clock: each sleep takes what it was
        asked for plus late[k] (the k-th sleep), minus `early` never."""
        clk = [100.0]

        class Stop:
            def __init__(self):
                self.left = n
                self.k = 0

            def is_set(self):
                return self.left <= 0

            def set(self):
                self.left = 0

            def clear(self):
                pass
        st = Stop()

        def sleep(d):
            st.k += 1
            clk[0] += d + late.get(st.k, 0.0)
            st.left -= 1
        lk = fl.FlameLink(cfg, clock=lambda: clk[0], sleep=sleep)
        sk = _FlSock()
        lk._sock = sk
        lk._stop = st
        lk._run()
        mono = [json.loads(d)["mono"] for d, _a in sk.sent]
        return lk, [round(b - a, 6) for a, b in zip(mono, mono[1:])], mono

    # Every sleep 3 ms late: the cadence stays 25 ms on average and every
    # frame stays on the 25 ms grid from the first one (absolute deadlines).
    lk, gaps, mono = run({k: 0.003 for k in range(1, 400)})
    span = mono[-1] - mono[0]
    check(abs(span / (len(mono) - 1) - P) < 1e-4,
          f"3 ms late every time: still 40 a second on average "
          f"({span / (len(mono) - 1) * 1000:.2f} ms)")
    check(all(abs(((m - mono[0]) / P) - round((m - mono[0]) / P)) * P
              <= 0.0031 for m in mono),
          "and each frame within 3 ms of its own grid point: no drift")
    # One 210 ms stall: one long gap, the overdue frame once, then the
    # next grid point (never the missed ones, so never a burst), and the
    # cadence again.
    lk, gaps, mono = run({60: 0.21})
    long_ = [g for g in gaps if g > P * 1.5]
    check(len(long_) == 1 and abs(long_[0] - (P + 0.21)) < 1e-6,
          f"the stall shows once: {sorted(set(gaps))[-3:]}")
    i = gaps.index(long_[0])
    check(abs(gaps[i + 1] - 0.015) < 1e-6 and
          all(abs(g - P) < 1e-6 for g in gaps[i + 2:]),
          f"after the stall the next grid point, then the cadence: "
          f"{gaps[i + 1:i + 5]}")
    check(len(mono) == 200 and min(gaps) >= G - 1e-6,
          f"no burst: one frame a wake, shortest gap {min(gaps)}")
    span = mono[-1] - mono[0]
    check(abs(round(span / P) * P - span) < 1e-6,
          "and every frame still on the grid of the first")
    # A wake 22 ms late: the late frame goes; the grid point 3 ms after it
    # is skipped, the next one after that is not.
    lk, gaps, mono = run({60: 0.022})
    check(min(gaps) >= G - 1e-6 and max(gaps) <= P + 0.022 + 1e-6 and
          any(abs(g - 0.028) < 1e-6 for g in gaps),
          f"a 22 ms late wake: no frame squeezed in 3 ms after it: "
          f"{sorted(set(gaps))}")
    # The timing counters saw the same intervals the frames carry.
    v = lk.timing_view()["since_start"]
    check(v["intervals"] == len(gaps) and abs(v["worst_ms"] - 47.0) < 0.01,
          f"the sender counted every interval and the worst: {v}")
    print("  ok")


def test_flame_link_frame_timing_counts_and_journals():
    section("flame link timing (2026-10-29): intervals counted per show and "
            "per hour on the sender (over 50, 75, 100, 150 ms, worst, 99 in "
            "100), journaled by the watch thread, the last hour's late "
            "frames for the alert, in the status")
    from ltcplay import flamelink as fl
    t = fl.FrameTiming(0.0)
    for _ in range(990):
        t.add(0.025)
    for ms in (60, 80, 120, 178, 40, 30, 26, 27, 28, 29):
        t.add(ms / 1000.0)
    v = t.view()
    check(v["intervals"] == 1000 and v["over_ms"] == {"50": 4, "75": 3,
                                                      "100": 2, "150": 1}
          and abs(v["worst_ms"] - 178.0) < 1e-6 and v["over_limit"] == 2
          and v["limit_ms"] == 100,
          f"counts over each limit, the worst: {v}")
    check(v["p99_ms"] == 26, f"99 in 100 within 26 ms (to the ms above): "
                             f"{v['p99_ms']}")
    t3 = fl.FrameTiming()
    for _ in range(980):
        t3.add(0.025)
    for _ in range(20):
        t3.add(0.060)
    check(t3.p99_ms() == 61, f"the 99th in 100 is in the tail: "
                             f"{t3.p99_ms()}")
    s = t.sentence("this hour")
    check("worst 178 ms" in s and "over 100 ms: 2" in s and
          "\u2013" not in s and "\u2014" not in s,
          f"one plain line, no dashes: {s}")
    check(fl.FrameTiming().view()["p99_ms"] == 0 and
          fl.FrameTiming().view()["mean_ms"] == 0.0, "empty: zeros")
    t2 = fl.FrameTiming()
    t2.add(2.0)
    check(t2.view()["p99_ms"] == 301 and t2.view()["worst_ms"] == 2000.0,
          f"past the last bin: at least 300, the worst exact: {t2.view()}")
    t2.add("rubbish")
    check(t2.frames == 1, "rubbish is not counted and does not raise")

    # On the link: the sender's _timing_add, a show window from the first
    # live frame to the first frame with no show timecode, an hour window,
    # each finished one journaled once by the watch thread's half.
    cfg = fl.FlameLinkConfig.parse({"port": 5571, "universe": 1,
                                    "key": _fl_key(), "frame_stale_ms": 500})
    clk = [1000.0]
    jl = _FlJournal()
    lk = fl.FlameLink(cfg, clock=lambda: clk[0], journal=jl)

    def tick(gap, live, tc):
        clk[0] += gap
        lk._haze_live, lk._frame_tc = live, tc
        lk._timing_add(gap, clk[0])
    for _ in range(10):
        tick(0.025, False, None)
    check(lk.timing_view()["this_show"] is None, "no show: no show window")
    tick(0.025, True, "00:00:00:01")
    for _ in range(40):
        tick(0.025, True, "00:00:01:00")
    tick(0.130, True, "00:00:02:00")             # one late frame in the show
    tick(0.025, False, "00:00:02:00")            # a Hold: still the show
    check(lk.timing_view()["this_show"]["intervals"] == 42,
          f"the show window counts from its first live frame, through a "
          f"Hold: {lk.timing_view()['this_show']}")
    tick(0.025, False, None)                     # the show is over
    check(lk.timing_view()["this_show"] is None, "the show window closed")
    lk._timing_journal()
    lines = [(t, kw) for t, kw in jl.lines
             if kw.get("outcome") in ("frame_timing", "frames_late")]
    check(len(lines) == 2 and "in the show that just ended" in lines[0][0]
          and "over 100 ms: 1" in lines[0][0]
          and lines[0][1]["timing"]["over_limit"] == 1
          and lines[1][0].startswith("Flame frames late: 1 in the show")
          and not any(kw.get("fault") for _t, kw in lines),
          f"one line for the show, one more for its late frame, notes "
          f"(the alert is the fault): {lines}")
    lk._timing_journal()
    check(len([1 for _t, kw in jl.lines
               if kw.get("outcome") == "frame_timing"]) == 1,
          "each finished window is journaled once")
    n, worst = lk.late_last_hour()
    check((n, worst) == (1, 130.0), f"the last hour: 1, 130 ms: {n} {worst}")
    # An hour on: the hour window rolls over and is journaled; the late
    # frame drops out of "the last hour".
    clk[0] += fl.TIMING_HOUR_S
    tick(0.025, False, None)
    lk._timing_journal()
    check(any("in the last hour" in t for t, _kw in jl.lines),
          "the finished hour is journaled")
    tv = lk.timing_view()
    check(tv["late_last_hour"] == 0 and tv["last_hour"]["over_limit"] == 1
          and tv["this_hour"]["intervals"] == 1
          and tv["since_start"]["intervals"] == 55
          and tv["in_shows"]["intervals"] == 43
          and tv["in_shows"]["over_limit"] == 1,
          f"the late frame is out of the last hour; the hour that had it is "
          f"kept as last_hour: {tv}")
    snap = lk.snapshot()
    check(snap["frame_timing"]["limit_ms"] == 100 and
          "since_start" in snap["frame_timing"],
          "the status carries frame_timing")
    # The limit is flamesafe's own fire_hold_ms, read from its config with
    # the rest of the link: at 250 a 178 ms gap is not late, 260 ms is.
    import json
    import tempfile
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "flamesafe", "flamesafe.example.json"),
              encoding="utf-8") as fh:
        doc = json.load(fh)
    d = tempfile.mkdtemp()
    try:
        for hold, gaps, late in ((100, (0.178,), 1), (250, (0.178, 0.26), 1),
                                 (None, (0.120,), 1)):
            dd = dict(doc)
            if hold is None:
                dd.pop("fire_hold_ms", None)
            else:
                dd["fire_hold_ms"] = hold
            path = os.path.join(d, f"fs{hold}.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(dd, fh)
            c2 = fl.FlameLinkConfig.from_flamesafe_config(path)
            k2 = [10.0]
            l2 = fl.FlameLink(c2, clock=lambda: k2[0])
            for g in gaps:
                k2[0] += g
                l2._timing_add(g, k2[0])
            tv = l2.timing_view()
            check(c2.fire_hold_ms == hold and
                  tv["limit_ms"] == (hold or fl.TIMING_ALERT_MS) and
                  tv["late_last_hour"] == late and
                  tv["since_start"]["over_limit"] == late,
                  f"fire_hold_ms {hold}: limit and late frames {tv}")
            check(f"over flamesafe's fire_hold_ms ({hold or 100} ms): {late}"
                  in l2._timing_total.sentence("since start"),
                  "the journal line names flamesafe's fire_hold_ms")
    finally:
        import shutil
        shutil.rmtree(d, ignore_errors=True)
    print("  ok")


def test_flame_link_sender_not_held_by_other_threads():
    section("flame link timing (2026-10-29): the real sender thread keeps "
            "sending while another thread holds the show's lock and a "
            "request-style lock, while the journal hangs, and while another "
            "thread sleeps holding them")
    import threading as _th
    from ltcplay import flamelink as fl
    F = _fi_mod()
    import types
    cfg = fl.FlameLinkConfig.parse({"port": 5571, "universe": 1,
                                    "key": _fl_key(), "send_hz": 40,
                                    "frame_stale_ms": 500})
    hang = _th.Event()

    def stuck_journal(text, **kw):
        hang.wait(10.0)              # a journal that never comes back
    jr = F.OffThreadJournal(stuck_journal)
    clk = types.SimpleNamespace(source="audio_master", playing=True,
                                paused=False, _halting=False,
                                last_sent=(0, 0, 1, 0), _paused=False,
                                on_pause=None, on_resume=None)
    control = types.SimpleNamespace(session=types.SimpleNamespace(
        running=True, clock=clk, player=None, tl=None))
    show = F.FireIceShow(control, journal=None, flame_link=object())
    calls = [0]

    def raising_cues(tc):
        calls[0] += 1
        raise RuntimeError("a provider that fails every frame")
    lk = fl.FlameLink(cfg, cues=raising_cues,
                      show_state=fl.audio_master_state(show.clock_nolock),
                      journal=jr)
    sk = _FlSock()
    lk._sock = sk
    request_lock = _th.Lock()
    held = _th.Event()

    def hold_locks():
        # A request thread holding the show's own lock and a lock of its
        # own, asleep with both held (GIL-free), for the whole measurement.
        with show._lock, request_lock:
            held.set()
            hang.wait(10.0)
    h = _th.Thread(target=hold_locks, daemon=True)
    h.start()
    held.wait(2.0)
    # The timecode moves, so the provider is asked (and raises, so the
    # sender writes a journal line, which hangs on its own thread).
    def move():
        f = 0
        while not hang.is_set():
            f = (f + 1) % 30
            clk.last_sent = (0, 0, 1 + (f // 30), f)
            time.sleep(0.03)
    m = _th.Thread(target=move, daemon=True)
    m.start()
    lk.release()
    lk.start()
    time.sleep(0.6)
    n = len(sk.sent)
    sender = lk.sender_state()
    hang.set()
    lk.stop()
    h.join(2.0)
    m.join(2.0)
    check(n >= 12 and calls[0] >= 5,
          f"the sender kept sending ({n} frames in 0.6 s, the provider asked "
          f"{calls[0]} times) with the show's lock and a request lock held "
          f"by a sleeping thread and the journal hung")
    check(sender in ("running",),
          f"and it never read as stalled: {sender}")
    print("  ok")


def test_flame_link_encode_is_byte_for_byte_the_same():
    section("flame link timing (2026-10-29): a flame frame built from parts, "
            "its values' text kept from the frame before, is byte for byte "
            "what json.dumps of the whole frame gives")
    import json
    import random
    from ltcplay import flamelink as fl

    def ref(seq, tc, mono, universe, values, key, hazers_on=None):
        obj = {"v": fl.CONTRACT_VERSION, "k": key, "t": "flame",
               "seq": int(seq), "tc": tc, "mono": float(mono),
               "universe": int(universe),
               "values": [int(v) for v in values]}
        if hazers_on is not None:
            obj["hazers_on"] = sorted(str(h) for h in hazers_on)
        return json.dumps(obj, separators=(",", ":")).encode("utf-8")
    r = random.Random(20261029)
    bad = []
    prev = bytes(512)
    for i in range(1500):
        # Runs of the same values (the cache), new ones, lists and bytes.
        if i % 5 == 0:
            prev = bytes(r.randrange(256) for _ in range(512))
        vals = prev if i % 7 else bytearray(prev)
        v = vals if i % 2 else list(vals)
        hz = [None, [], ["Hazer 2", "Hazer 1"], {"a\"b", "\u00e9"}][i % 4]
        tc = [None, "00:01:02:03"][i % 2]
        key = "".join(chr(r.randrange(0x21, 0x7f))
                      for _ in range(r.randrange(16, 40)))
        a = (r.randrange(10 ** 12), tc, r.random() * 1e5,
             r.randrange(1, 64000), v, key, hz)
        if fl.encode_flame(*a) != ref(*a):
            bad.append(a[:4])
    check(not bad, f"every frame byte for byte the same: {bad[:2]}")
    print("  ok")


def test_flame_frame_timing_alert_and_systems_line():
    section("flame link timing (2026-10-29): frames over 100 ms in the last "
            "hour raise a display only 'timing' alert in plain words (again "
            "only for new late frames), and the rack screen's Systems sheet "
            "has a Flame timing line")
    import tempfile
    from ltcplay import alerts as AL
    from ltcplay import flamelink as fl
    from ltcplay import remote as RM
    check("timing" in AL.KINDS and "timing" in AL.DISPLAY_ONLY and
          AL.SEVERITY["timing"] == "warning",
          "timing is a display only kind: shown and journaled, no booth "
          "note, never holds a show")
    cfg = fl.FlameLinkConfig.parse({"port": 5571, "universe": 1,
                                    "key": _fl_key(), "frame_stale_ms": 500})
    clk = [5000.0]
    lk = fl.FlameLink(cfg, clock=lambda: clk[0])
    rm = RM.Remote(None, None, folder=tempfile.mkdtemp(), log=lambda t: None)
    lines = []
    rm._journal = lambda *a, **k: lines.append(a)

    def row():
        got = [x for x in rm.subsystems({}) if x["name"] == "Flame timing"]
        return got[0] if got else None
    check(row() is None, "no flame link: no Flame timing line")
    rm._frame_timing_work()
    check(not rm.alerts.open(), "no flame link: no alert")
    rm.flame_link_get = lambda: lk
    for _ in range(100):
        clk[0] += 0.025
        lk._timing_add(0.025, clk[0])
    rm._frame_timing_work()
    r = row()
    check(not rm.alerts.open() and r and r["state"] == "ok" and
          r["word"] == "on time, worst 25 ms this hour",
          f"on time: no alert, the line says so: {r}")
    clk[0] += 0.178
    lk._timing_add(0.178, clk[0])
    rm._frame_timing_work()
    al = rm.alerts.open()
    r = row()
    check(len(al) == 1 and al[0].kind == "timing" and
          al[0].text.startswith("Flame frames late, last hour: 1. ") and
          "worst 178 ms" in al[0].text and
          "Nothing was changed" in al[0].text and
          _op_shaped(al[0].full) and "worst" not in
          al[0].full.split("\n\n")[0] and
          "\u2013" not in al[0].text and "\u2014" not in al[0].text,
          f"a frame 178 ms late: the alert, in plain words: "
          f"{[a.text for a in al]}")
    check(r and r["state"] == "warn" and
          r["word"] == "1 frame(s) late in the last hour, worst 178 ms",
          f"and the Systems line: {r}")
    if al:
        rm.alerts.clear(id=al[0].id, who="Andy", action="Acknowledge",
                        screen="rack")
    rm._frame_timing_work()
    check(not rm.alerts.open(), "acknowledged, and no new late frame: it "
                                "stays cleared")
    clk[0] += 0.120
    lk._timing_add(0.120, clk[0])
    rm._frame_timing_work()
    al = rm.alerts.open()
    check(len(al) == 1 and al[0].text.startswith(
        "Flame frames late, last hour: 2.") and "worst 178 ms" in al[0].text,
          f"a new late frame raises it again: {[a.text for a in al]}")
    print("  ok")


def test_flame_serve_keeps_frames_on_time():
    section("flame link timing (2026-10-29): `ltc serve` with a flame link "
            "sets a 1 ms switch interval and sets the start up objects "
            "aside from the garbage collector, says so, and never raises")
    import types
    F = _fi_mod()
    calls = []
    fsys = types.SimpleNamespace(
        getswitchinterval=lambda: 0.005,
        setswitchinterval=lambda v: calls.append(("switch", v)))
    fgc = types.SimpleNamespace(
        collect=lambda: calls.append(("collect",)),
        freeze=lambda: calls.append(("freeze",)),
        get_freeze_count=lambda: 123456)
    line = F.keep_flame_frames_on_time(fsys, fgc)
    check(calls == [("switch", 0.001), ("collect",), ("freeze",)],
          f"switch interval 1 ms, one collection, then freeze: {calls}")
    check("every 1 ms (was 5 ms)" in line and "123456 objects" in line
          and "\u2013" not in line and "\u2014" not in line,
          f"one plain line: {line}")

    def boom(*a):
        raise RuntimeError("no")
    line = F.keep_flame_frames_on_time(
        types.SimpleNamespace(getswitchinterval=boom, setswitchinterval=boom),
        types.SimpleNamespace(collect=boom, freeze=boom,
                              get_freeze_count=boom))
    check("could not be set" in line and "could not be set aside" in line,
          f"failures are said, never raised: {line}")
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "ltcplay", "cli.py"),
              encoding="utf-8") as fh:
        src = fh.read()
    i = src.find("keep_flame_frames_on_time()")
    check(i > 0 and src.rfind("if _link is not None:", 0, i) > 0 and
          src.find("httpd.serve_forever", i) > i,
          "cli serve calls it with a flame link only, before it serves")
    print("  ok")


def test_flame_link_end_to_end_against_the_real_flamesafe():
    section("flame link end to end: the real flamesafe in its own process, "
            "the real FlameLink, a deck sending real arm frames, over "
            "loopback UDP")
    import json
    import socket as _so
    import subprocess
    import tempfile
    import threading
    from ltcplay import flamelink as fl
    from ltcplay import streamdeck as sd
    here = os.path.dirname(os.path.abspath(__file__))
    key = _fl_key()
    names = ["front row", "cat-walk", "wave flamer"]

    def free_port():
        s = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
        s.bind(("127.0.0.1", 0))
        p = s.getsockname()[1]
        s.close()
        return p

    node = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
    node.bind(("127.0.0.1", 0))
    status_rx = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
    status_rx.bind(("127.0.0.1", 0))
    status_rx.settimeout(0.2)
    listen, arm = free_port(), free_port()
    work = tempfile.mkdtemp()
    cfg_path = os.path.join(work, "flamesafe.json")
    json.dump({
        "flamesafe_config": 1, "confirmed": False, "note": "selftest",
        "universe": 1,
        "destination": {"ip": "127.0.0.1", "port": node.getsockname()[1]},
        "link": {"listen_ip": "127.0.0.1", "listen_port": listen,
                 "status_ip": "127.0.0.1",
                 "status_port": status_rx.getsockname()[1],
                 "arm_port": arm, "key": key},
        "gflame_range": "30-50%", "arm_value": 78,
        "accept_unsourced_risk": False, "min_arm_dwell_ms": 1000,
        "arm_stale_ms": 500, "frame_stale_ms": 500, "fire_hold_ms": 100,
        "tick_hz": 40, "overrun_ms": 250, "log_dir": None,
        "groups": [{"name": "front row", "safety": 401, "fire": [411, 412]},
                   {"name": "cat-walk", "safety": 402, "fire": [421]},
                   {"name": "wave flamer", "safety": 403, "fire": [431]}]},
        open(cfg_path, "w"))
    proc = subprocess.Popen([sys.executable, "-u", "-m", "flamesafe",
                             cfg_path], cwd=here, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)
    out_lines = []
    stop = threading.Event()
    statuses = []           # (perf_counter, status dict)
    j = _FlJournal()
    state = {"live": True}
    cue = {"v": None}
    cfg = fl.FlameLinkConfig.from_flamesafe_config(cfg_path)
    t_show = time.perf_counter()

    def show_tc():
        # A moving timecode at 30 fps: a still one is zeros (fix round 1,
        # item 5).
        n = int((time.perf_counter() - t_show) * 30)
        return f"00:{n // 1800 % 60:02d}:{n // 30 % 60:02d}:{n % 30:02d}"
    link = _flk_unguarded(cfg, cues=lambda tc: cue["v"],
                        show_state=lambda: (show_tc(), state["live"]),
                        journal=j)
    deck = {"wanted": [False, False, False], "on": True}

    def read_out():
        for line in proc.stdout:
            out_lines.append(line.rstrip())

    def read_status():
        while not stop.is_set():
            try:
                d, _a = status_rx.recvfrom(65535)
            except (_so.timeout, OSError):
                continue
            obj = fl.decode_status(d, key)
            if obj is not None:
                statuses.append((time.perf_counter(), obj))
                link.note_status(obj)

    def run_deck():
        s = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
        seq = 0
        while not stop.is_set():
            if deck["on"]:
                seq += 1
                s.sendto(sd.encode_arm_frame(seq, deck["wanted"], names, key),
                         ("127.0.0.1", arm))
            time.sleep(0.05)
        s.close()

    def latest():
        return statuses[-1][1] if statuses else None

    def wait_for(pred, timeout):
        end = time.perf_counter() + timeout
        while time.perf_counter() < end:
            s = latest()
            if s is not None:
                try:
                    if pred(s):
                        return s
                except (KeyError, IndexError, TypeError):
                    pass
            time.sleep(0.01)
        return None

    def armed(s, i):
        return s["groups"][i]["armed"] == "armed" and \
            s["groups"][i]["sent_safety"] == 78

    def journal(fragment):
        return [l for l in out_lines if fragment in l]

    threads = [threading.Thread(target=f, daemon=True)
               for f in (read_out, read_status, run_deck)]
    for th in threads:
        th.start()
    try:
        s = wait_for(lambda s: s["heartbeat"] > 0, 10.0)
        check(s is not None and s["frames"]["state"] == "never",
              f"the real flamesafe is up, and has had no flame frame yet: "
              f"{s and s['frames']}")
        if s is None:
            print("\n".join(out_lines[-20:]))
            return
        link.start()
        s = wait_for(lambda s: s["frames"]["state"] == "fresh", 3.0)
        check(s is not None, "flamesafe accepts the real sender's frames")
        t0 = time.perf_counter()
        time.sleep(1.0)
        window = [x for t_, x in statuses if t_ > t0]
        check(window and all(x["frames"]["state"] == "fresh"
                             and x["frames"]["rejected"] == 0
                             for x in window),
              "a second of zeros keeps the link fresh, nothing rejected")
        check(link.lock_alarm == "" and link.first_seq is not None
              and link.first_seq <= latest()["frames"]["seq"] <= link.seq,
              "the last accepted seq is ours: no lock alarm")

        # The operator arms two groups with a genuine cycle.
        time.sleep(0.3)
        deck["wanted"] = [True, True, False]
        s = wait_for(lambda s: armed(s, 0) and armed(s, 1), 3.0)
        check(s is not None, f"a genuine deck cycle arms two groups: "
                             f"{latest()['groups'][:2]}")

        # Cue values: none while zeroed, through once released.
        fire = [0] * 512
        fire[410] = 200
        cue["v"] = fire
        time.sleep(0.2)
        check(latest()["groups"][0]["commanded_fire"][0] == 0,
              "zeroed (no release yet): flamesafe is commanded nothing")
        link.release()
        s = wait_for(lambda s: s["groups"][0]["sent_fire"][0] == 200, 2.0)
        check(s is not None, "released and live: the cue reaches the wire "
                             "through flamesafe")

        # The show's Abort.
        hb = latest()["heartbeat"]
        check(link.disarm_all("Abort from the rack screen") is True,
              "disarm_all went out")
        s = wait_for(lambda s: s["heartbeat"] >= hb + 2, 2.0)
        firsts = [x for _t, x in statuses if x["heartbeat"] >= hb + 2]
        s = firsts[0] if firsts else None
        check(s is not None and all(g["sent_safety"] == 0
                                    and not any(g["sent_fire"])
                                    for g in s["groups"]),
              f"within one tick every group is off the wire: "
              f"{s and [(g['sent_safety'], g['sent_fire']) for g in s['groups']]}")
        check(s is not None and s["disarm_all"]["last_id"] == link.abort_id
              and s["groups"][0]["reason"] == FLAME_ABORT_WORDS
              and s["groups"][0]["amber"] == "flashing",
              f"and flamesafe says which Abort, and why, on the lamp: "
              f"{s and (s['disarm_all'], s['groups'][0]['reason'])}")
        time.sleep(0.1)
        check(link._pending_abort is None
              and "disarm_unconfirmed" not in j.outcomes(),
              "the sender saw flamesafe confirm it")

        # The deck never stopped asking. Nothing comes back by itself, even
        # with the cues released again (a new show) and well past the dwell.
        cue["v"] = None
        link.release()
        t0 = time.perf_counter()
        time.sleep(2.0)
        window = [x for t_, x in statuses if t_ > t0]
        check(window and not any(g["sent_safety"] for x in window
                                 for g in x["groups"]),
              "2 s of the deck still asking: no group re-arms")
        check(len(journal("disarm-all: the show program's Stop")) == 1,
              f"flamesafe journaled the Abort once, though it got "
              f"{fl.DISARM_COPIES} copies: "
              f"{journal('disarm-all')}")

        # A fresh genuine cycle re-arms that group only.
        deck["wanted"] = [False, True, False]
        time.sleep(0.4)
        deck["wanted"] = [True, True, False]
        s = wait_for(lambda s: armed(s, 0), 3.0)
        check(s is not None and not armed(s, 1)
              and s["groups"][1]["reason"] == FLAME_ABORT_WORDS,
              f"a fresh genuine cycle re-arms that group, and only that "
              f"one: {latest()['groups'][:2]}")

        # Fix round 1, item 1 (the review's p6): every one of an Abort's
        # immediate copies lost. The repeats on the following frames carry
        # the same Abort, and flamesafe's status confirms it.
        class DropFirstCopies:
            def __init__(self, real, n):
                self.real, self.n = real, n

            def sendto(self, data, addr):
                if self.n and b'"t":"disarm_all"' in data:
                    self.n -= 1
                    return len(data)
                return self.real.sendto(data, addr)

            def close(self):
                self.real.close()
        real_sock = link._sock
        link._sock = DropFirstCopies(real_sock, fl.DISARM_COPIES)
        try:
            link.disarm_all("Abort, its first copies lost")
            s = wait_for(lambda s: s["disarm_all"]["last_id"] == link.abort_id
                         and not armed(s, 0), 1.5)
        finally:
            link._sock = real_sock
        check(s is not None, f"every immediate copy lost: the repeats still "
                             f"disarm: {latest()['disarm_all']}")
        end = time.perf_counter() + 1.0
        while time.perf_counter() < end and \
                link.snapshot()["abort"] != "confirmed by flamesafe":
            time.sleep(0.02)
        check(link.snapshot()["abort"] == "confirmed by flamesafe",
              f"and only flamesafe's own status says it was taken: "
              f"{link.snapshot()['abort']!r}")

        # Fix round 1, item 2 (the review's p2 s2): an arm-hold begun before
        # a screen Abort completes after it. The deck kept reporting group
        # 2 low all through the hold; that low must not count.
        time.sleep(2.0)            # past that Abort's repeats and window
        t_ab = time.perf_counter()
        link.disarm_all("Abort during an arm-hold")
        time.sleep(0.3)
        deck["wanted"] = [True, True, True]     # the hold completes
        time.sleep(2.0)
        window = [x for t_, x in statuses if t_ > t_ab]
        check(window and not any(x["groups"][2]["sent_safety"]
                                 for x in window)
              and latest()["groups"][2]["reason"] == FLAME_ABORT_WORDS,
              f"a hold begun before the Abort and finished after it arms "
              f"nothing: {latest()['groups'][2]}")
        # A fresh cycle afterwards still works (group 0, for what follows).
        deck["wanted"] = [False, True, False]
        time.sleep(0.4)
        deck["wanted"] = [True, True, False]
        s = wait_for(lambda s: armed(s, 0), 3.0)
        check(s is not None, f"and a fresh cycle afterwards re-arms as "
                             f"before: {latest()['groups'][0]}")

        # A foreign sender with the right key: refused as the show's Abort,
        # journaled once; and since fix round 1 of PR #40 a second keyed
        # sender on the flame link disarms every group (second-copy guard).
        rogue = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
        for i in range(20):
            rogue.sendto(fl.encode_disarm_all(10 ** 7 + i, 1e9, 99, "rogue",
                                              key), ("127.0.0.1", listen))
            time.sleep(0.005)
        time.sleep(0.2)
        s = latest()
        check(not armed(s, 0) and "another sender" in s["frames"]["last_reject"]
              and s["disarm_all"]["last_id"] == link.abort_id,
              f"a disarm_all from another socket is refused as an Abort, and "
              f"the second sender disarms every group: "
              f"{s['frames']['last_reject']!r} {s['groups'][0]['armed']}")
        # Once it has gone, a fresh cycle re-arms group 0 for what follows.
        time.sleep(0.6)
        deck["wanted"] = [False, True, False]
        time.sleep(0.4)
        deck["wanted"] = [True, True, False]
        s = wait_for(lambda s: armed(s, 0), 3.0)
        check(s is not None, f"re-armed by a fresh cycle once the other "
                             f"socket has gone: {latest()['groups'][0]}")
        # The wrong key and the wrong version, from the locked socket itself.
        for i in range(10):
            link._sock.sendto(fl.encode_disarm_all(
                link.seq + 1, 1e9, 98, "x", "wrong-" + key),
                (cfg.ip, cfg.port))
            d = json.loads(fl.encode_disarm_all(link.seq + 1, 1e9, 97, "x",
                                                key))
            d["v"] = 3
            link._sock.sendto(json.dumps(d).encode(), (cfg.ip, cfg.port))
            time.sleep(0.005)
        time.sleep(0.2)
        check(armed(latest(), 0), "a wrong-key or wrong-version disarm_all "
                                  "from the locked sender disarms nothing")
        time.sleep(0.3)
        t_last_reject = time.perf_counter()
        check(len(journal(": disarm_all: another sender.")) == 1,
              f"the foreign disarm_alls: one journal line: "
              f"{journal('another sender')}")
        check(len(journal(": wrong key.")) == 1
              and len(journal(": wrong contract version")) == 1,
              f"wrong key, wrong version: one line each: "
              f"{journal('datagram rejected')}")
        check(latest()["disarm_all"]["last_id"] == link.abort_id,
              "no refused disarm_all was counted as an Abort")
        rogue.close()

        # The sender stops: flamesafe fails safe inside frame_stale_ms.
        t_stop = time.perf_counter()
        n_before = len(statuses)
        link.stop()
        t_stopped = time.perf_counter() - t_stop
        s = wait_for(lambda s: s["frames"]["fire"] == "zeroed", 1.0)
        t_fire = time.perf_counter() - t_stop
        s = wait_for(lambda s: s["frames"]["state"] == "stale", 2.0)
        t_stale = time.perf_counter() - t_stop
        # What this proves is the SEQUENCE through two real processes and a
        # real socket: the sender stops, the fire slots go to zero, then the
        # link goes stale and every group disarms, with nothing else
        # needed. The exact windows (fire_hold_ms 100, frame_stale_ms 500)
        # are proved in flamesafe's own suite on a fake clock, where they
        # mean something; measured here, on a shared runner, they read
        # 0.25 to 0.34 s and 0.76 to 0.82 s with the code right, so the
        # bounds here are only wide enough to tell "did" from "never did".
        # The real timing is measured on the show PC by the bench soak.
        print(f"  note: fire zeroed {t_fire:.3f} s and link stale "
              f"{t_stale:.3f} s after the sender stopped (fire_hold_ms "
              f"100, frame_stale_ms 500; exact on the show PC only)")
        check(t_fire < 1.0, f"fire zeroed {t_fire:.3f} s after the sender "
                            f"stopped (fire_hold_ms 100)")
        check(s is not None and t_stale < 2.0
              and all(g["sent_safety"] == 0 for g in s["groups"]),
              f"link stale and every group disarmed {t_stale:.3f} s after "
              f"the sender stopped (frame_stale_ms 500)")
        # And the order, with no clock at all: fire_hold_ms is shorter than
        # frame_stale_ms, so flamesafe's own status frames must show the
        # fire slots zeroed WHILE the link still reads fresh. A fire value
        # held until the link went stale (a real mutation) never shows
        # that frame, however fast or slow the runner.
        after = [x for t_, x in statuses if t_ > t_stop]
        check(any(x["frames"]["fire"] == "zeroed"
                  and x["frames"]["state"] == "fresh" for x in after),
              f"flamesafe reported the fire zeroed while the link was still "
              f"fresh, before it went stale: "
              f"{[(x['frames']['fire'], x['frames']['state']) for x in after][:12]}")
        check(link.disarm_all("Abort") is False,
              "a disarm_all on a stopped link answers False")
        # The rejection episodes close after 5 s of quiet (the arm link's
        # own throttle), each with one line and its count.
        time.sleep(max(0.0, 5.6 - (time.perf_counter() - t_last_reject)))
        check(len(journal("(disarm_all: another sender) stopped after 20 "
                          "rejected")) == 1
              and len(journal("(wrong key) stopped after 10 rejected")) == 1
              and len(journal("(wrong contract version) stopped after 10 "
                              "rejected")) == 1,
              f"and one closing line per episode with its count: "
              f"{journal('stopped after')}")
    finally:
        stop.set()
        try:
            link.stop()
        except Exception:
            pass
        proc.terminate()
        try:
            proc.wait(10)
        except Exception:
            proc.kill()
        for th in threads:
            th.join(2)
        node.close()
        status_rx.close()
        import shutil
        shutil.rmtree(work, ignore_errors=True)


def test_audio_interface_watch():
    section("audio interface watch (Fire & Ice, 2026-10-15): before Run, a "
            "show file's audio device that is not on this PC raises the "
            "audio alert once per outage, naming the device and the outputs "
            "seen, the Audio chip reads not attached, nothing is listed while "
            "a session runs, and a listing that fails is a log line, never a "
            "false alarm")
    import json as _j
    import shutil
    import tempfile
    from ltcplay import audiowatch as AW
    from ltcplay.alerts import Alerts
    folder = tempfile.mkdtemp()
    try:
        def put(name, doc):
            with open(os.path.join(folder, name), "w", encoding="utf-8") as fh:
                _j.dump(doc, fh)
        put("show.json", {"cues": [], "clock": {"source": "audio_master",
                          "audio": {"device": "PreSonus Studio 1824c",
                                    "channels": 8, "cues": {}}}})
        put("ltc_show.json", {"cues": [], "clock": {"source": "ltc"}})
        put("ltcplay_prefs.json", {"auto_reload": True})
        put("second.json", {"cues": [], "clock": {"source": "audio_master",
                            "audio": {"device": " PreSonus Studio 1824c "}}})
        with open(os.path.join(folder, "broken.json"), "w") as fh:
            fh.write("{not json")
        want = AW.wanted_devices(folder)
        check(want == {"PreSonus Studio 1824c": "second.json"},
              f"the devices wanted are read from the audio_master show files "
              f"only, trimmed, the first file (by name) named: {want}")
        check(AW.missing(want, ["presonus studio 1824c", "Speakers"]) == []
              and AW.missing(want, ["Speakers (Realtek)"]) ==
              ["PreSonus Studio 1824c"]
              and AW.missing(want, ["PreSonus Studio 1824"]) ==
              ["PreSonus Studio 1824c"],
              "a device is matched by its exact name, case aside, never by "
              "a substring")
        journal = []
        alerts = Alerts(journal=lambda text, **kw: journal.append((text, kw)),
                        clock=lambda: 0.0, wall=lambda: 0.0)
        outs = [["Speakers (Realtek)", "Monitor HDMI"]]
        calls = []
        busy = [False]
        log = []

        def lister():
            calls.append(1)
            if isinstance(outs[0], Exception):
                raise outs[0]
            return outs[0]
        w = AW.AudioInterfaceWatch(folder, alerts=alerts, log=log.append,
                                   lister=lister, busy=lambda: busy[0],
                                   clock=lambda: 100.0, interval_s=30)
        st = w.check()
        a = alerts.open()
        check(st["missing"] == ["PreSonus Studio 1824c"] and len(a) == 1 and
              a[0].kind == "audio" and "'PreSonus Studio 1824c'" in a[0].text
              and "second.json" in a[0].text and
              "Monitor HDMI, Speakers (Realtek)" in a[0].text and
              "same USB port" in a[0].text and "every 30 seconds" in a[0].text,
              f"the missing interface raises the audio alert, naming the "
              f"device, its show file and the outputs seen: {st} "
              f"{[x.text for x in a]}")
        # Less prose (Jeff, 2026-11-11): a headline of 6 words or fewer,
        # bullets of 8 or fewer, the names behind More. The rack screen's
        # Details reads the lines; the journal and text are one line.
        full = a[0].full.split("\n")
        bullets = [x[2:] for x in full if x.startswith("- ")]
        check(len(full[0].split()) <= 6 and len(bullets) == 3 and
              all(len(x.split()) <= 8 for x in bullets) and
              bullets[0].startswith("Do: ") and full[-1].startswith("More: ")
              and "second.json" in full[-1] and "second.json" not in
              "".join(full[:-1]) and "\n" not in a[0].text and
              not any("\n" in t for t, _kw in journal) and
              not any("\n" in x for x in log),
              f"the audio alert is a headline, Do, Then, Why and More; "
              f"one line in the journal and the log: {full}")
        raised = [t for t, kw in journal if kw.get("outcome") == "raised"]
        w.check()
        w.check()
        check(len(alerts.open()) == 1 and len(raised) == 1 and
              len([t for t, kw in journal if kw.get("outcome") in
                   ("raised", "updated")]) == 1,
              f"a second and third check in the same outage raise nothing "
              f"more: {journal}")
        v = w.view()
        check(v["missing"] == ["PreSonus Studio 1824c"] and
              v["outputs"] == ["Speakers (Realtek)", "Monitor HDMI"] and
              v["checked_ago_s"] == 0.0 and v["skipped"] == "" and
              v["error"] == "", f"the view for the rack screen: {v}")
        # Plugged in again: said in the log, the banner stays for a person.
        outs[0] = ["Speakers (Realtek)", "PreSonus Studio 1824c"]
        st = w.check()
        check(st["missing"] == [] and len(alerts.open()) == 1 and
              any("attached again" in l for l in log),
              f"the device back is a log line; the alert waits for a person: "
              f"{st['missing']} {log[-1:]}")
        # Unplugged again: a new outage, one new raise (an update of the
        # one open alert, since nobody acknowledged the first).
        outs[0] = ["Speakers (Realtek)"]
        w.check()
        n_raise = len([t for t, kw in journal if kw.get("outcome") in
                       ("raised", "updated")])
        check(n_raise == 2 and len(alerts.open()) == 1,
              f"a new outage is said once more: {n_raise} raises")
        # A running session: nothing is listed, the last answer stands.
        before = len(calls)
        busy[0] = True
        st = w.check()
        check(len(calls) == before and "session is running" in st["skipped"]
              and st["missing"] == ["PreSonus Studio 1824c"],
              f"while a session runs nothing is listed: {st['skipped']!r}")
        busy[0] = False
        # A listing that fails: a log line, the state kept, no alert change.
        outs[0] = OSError("the audio device list did not come back")
        st = w.check()
        check("did not come back" in st["error"] and
              any("did not come back" in l for l in log) and n_raise ==
              len([t for t, kw in journal if kw.get("outcome") in
                   ("raised", "updated")]),
              f"a failed listing is a log line, never an alert: {st['error']}")
        # No show file asks for a device: nothing wanted, nothing listed.
        for n in ("show.json", "second.json"):
            os.remove(os.path.join(folder, n))
        before = len(calls)
        st = w.check()
        check(st["wanted"] == {} and st["missing"] == [] and
              len(calls) == before,
              f"with no audio_master show file nothing is looked for: {st}")
    finally:
        shutil.rmtree(folder, ignore_errors=True)
    # The rack screen's chip and status carry it.
    S = _sched()
    if S is None:
        print("  ok")
        return
    R = _RemoteRig(S)
    try:
        class W:
            def view(self):
                return {"missing": ["PreSonus Studio 1824c"],
                        "outputs": ["Speakers"], "checked_ago_s": 1.0,
                        "skipped": "", "error": "", "wanted": {}}
        st, _h, out = R.ask("GET", "/api/remote/status",
                            client=("127.0.0.1", 5000))
        check(st == 200 and out["audio_interface"] is None and
              not any(x["word"] == "not attached" for x in out["subsystems"]),
              f"without the watch the status says None and the chip is as "
              f"before: {out.get('audio_interface')}")
        R.remote.audio_watch = W()
        st, _h, out = R.ask("GET", "/api/remote/status",
                            client=("127.0.0.1", 5000))
        chip = [x for x in out["subsystems"] if x["name"] == "Show audio"]
        check(st == 200 and out["audio_interface"]["missing"] ==
              ["PreSonus Studio 1824c"] and chip ==
              [{"name": "Show audio", "state": "bad",
                "word": "not attached"}],
              f"with the interface missing the status carries it and the "
              f"Audio chip reads not attached: {chip} "
              f"{out['audio_interface']}")
        # The supervisor's disk file (packaging/windows/housekeeping.py):
        # a Disk chip and the sentence for the banner while it is there.
        check(out["disk"] is None and not any(
            x["name"] == "Disk" for x in out["subsystems"]),
              "with no disk file there is no Disk chip")
        R.remote.disk_file = os.path.join(R.work, "disk-low.txt")
        with open(R.remote.disk_file, "w", encoding="utf-8") as fh:
            fh.write("critical\nThe disk holding C:\\x has only 0.6 GB "
                     "free. Free some space now.\n")
        R.remote._disk = (None, 0.0)
        st, _h, out = R.ask("GET", "/api/remote/status",
                            client=("127.0.0.1", 5000))
        chip = [x for x in out["subsystems"] if x["name"] == "Disk"]
        check(out["disk"] == {"state": "critical", "text": "The disk holding "
              "C:\\x has only 0.6 GB free. Free some space now."} and chip ==
              [{"name": "Disk", "state": "bad", "word": "critical"}],
              f"the supervisor's disk-low.txt becomes the Disk chip and the "
              f"banner's sentence: {out['disk']} {chip}")
        R.mono[0] += 31
        os.remove(R.remote.disk_file)
        st, _h, out = R.ask("GET", "/api/remote/status",
                            client=("127.0.0.1", 5000))
        check(out["disk"] is None, "the file gone, the chip goes within 30 s")
    finally:
        R.close()
    print("  ok")


def test_mutate_reports_every_failure_it_can_have():
    """mutate.py is run against a tiny fake tree (its own selftest.py, one
    target file) and forced into every way it can end red. Each one must
    say what happened as a GitHub annotation that names the shard, the
    kind of failure and the mutation or test, and write the run's table to
    the job summary, with the exit codes and the log lines the workflow
    reads left as they were. PR #46's shards 14 and 28 ran three hours and
    ended with "exit code 1" and nothing else: that is what this forbids."""
    section("mutate.py says why it is red: annotation, summary, exit code")
    import contextlib
    import io
    import mutate

    tree = tempfile.mkdtemp()
    fake_suite = (
        "import os, sys, time\n"
        "src = open('target.py', encoding='utf-8').read()\n"
        "if 'SLEEP' in src:\n"
        "    time.sleep(10)\n"
        "if 'CRASH' in src:\n"
        "    raise ValueError('a test let this out')\n"
        "if 'FLAKY' in src:\n"
        "    if not os.path.exists('flaky.once'):\n"
        "        open('flaky.once', 'w').close()\n"
        "        print('  FAIL  took 0.9 s on a slow runner'); sys.exit(1)\n"
        "if 'BAD' in src:\n"
        "    print('  FAIL  the guard is gone'); sys.exit(1)\n"
        "print('all checks passed')\n")
    with open(os.path.join(tree, "selftest.py"), "w", encoding="utf-8") as fh:
        fh.write(fake_suite)
    target = os.path.join(tree, "target.py")
    expected_file = os.path.join(tree, "expected.txt")
    summary_file = os.path.join(tree, "summary.md")
    GUARD = "ok\nGUARD\n"

    def run(argv, mutations, target_text=GUARD, expected=None, **patch):
        """(exit code, printed lines, annotations, summary text)."""
        with open(target, "w", encoding="utf-8", newline="") as fh:
            fh.write(target_text)
        for p in ("flaky.once", ".mutating"):
            try:
                os.remove(os.path.join(tree, p))
            except OSError:
                pass
        if expected is not None:
            with open(expected_file, "w", encoding="utf-8") as fh:
                fh.write(expected)
            argv = argv + ["--expected", expected_file]
        with open(summary_file, "w", encoding="utf-8") as fh:
            fh.write("")
        saved = {k: getattr(mutate, k) for k in
                 ("HERE", "LOCK", "MUTATIONS", "CI", "SUITE_TIMEOUT",
                  "_write")}
        env_saved = os.environ.get("GITHUB_STEP_SUMMARY")
        old_argv = sys.argv
        buf = io.StringIO()
        try:
            mutate.HERE = tree
            mutate.LOCK = os.path.join(tree, ".mutating")
            mutate.MUTATIONS = list(mutations)
            mutate.CI = True
            for k, v in patch.items():
                setattr(mutate, k, v)
            os.environ["GITHUB_STEP_SUMMARY"] = summary_file
            sys.argv = ["mutate.py"] + argv
            with contextlib.redirect_stdout(buf):
                code = mutate.main()
        finally:
            for k, v in saved.items():
                setattr(mutate, k, v)
            if env_saved is None:
                os.environ.pop("GITHUB_STEP_SUMMARY", None)
            else:
                os.environ["GITHUB_STEP_SUMMARY"] = env_saved
            sys.argv = old_argv
        lines = buf.getvalue().splitlines()
        notes = [l for l in lines if l.startswith("::error ")]
        with open(summary_file, encoding="utf-8") as fh:
            summary = fh.read()
        check(not os.path.exists(os.path.join(tree, ".mutating")),
              f"{argv}: the .mutating lock was left behind")
        return code, lines, notes, summary

    def said(notes, *words):
        """One annotation carries every word. Newlines in a word are looked
        for the way GitHub wants them escaped; a word is otherwise taken
        as written, escaped or not."""
        esc = lambda s: s.replace("\n", "%0A")
        return any(all(esc(w) in n for w in words) for n in notes)

    caught = ("the guard is gone", "target.py", "GUARD", "BAD")
    missed = ("nothing notices this", "target.py", "GUARD", "NOTHING")

    # Green: no annotation, a summary that says so, the log lines as before.
    code, lines, notes, summary = run(["--shard", "0/1"], [caught])
    check(code == 0 and not notes, f"a clean sweep: exit {code}, {notes}")
    check("  caught      the guard is gone" in lines,
          "the caught line the workflow reads is unchanged")
    check("shard 0/1: 1 mutations to run" in lines,
          "the 'mutations to run' line the timeout step reads is printed")
    check("| shard 0/1 | 1 | 1 | 0 |" in summary and "| green | yes |" in summary
          and "ok" in summary, f"a clean sweep's summary table:\n{summary}")

    # NOT CAUGHT, with and without the expected-miss list. This is the exit
    # 1 that used to say nothing.
    code, lines, notes, summary = run(["--shard", "0/1"], [caught, missed])
    check(code == 1, f"a miss exits 1, got {code}")
    check(said(notes, "title=mutate shard 0/1%3A mutation NOT CAUGHT",
               "file: target.py", "mutation: nothing notices this",
               "was:  GUARD", "now:  NOTHING", "nothing tests this guarantee"),
          f"a miss is annotated with the shard, the file and the mutation: {notes}")
    check("  NOT CAUGHT  nothing notices this" in lines,
          "the NOT CAUGHT log line is unchanged")
    check("**Why it is red**" in summary and "mutation NOT CAUGHT" in summary
          and "`target.py`: nothing notices this" in summary
          and "FAIL (exit 1)" in summary, f"a miss is in the summary:\n{summary}")
    code, lines, notes, summary = run(["--shard", "0/1"], [caught, missed],
                                      expected="")
    check(code == 1 and said(notes, "mutation NOT CAUGHT", "nothing notices this")
          and "  UNEXPECTED MISS  nothing notices this" in lines,
          f"an UNEXPECTED MISS is annotated: {code} {notes}")
    # Listed: an expected miss is not red and not annotated.
    code, lines, notes, summary = run(
        ["--shard", "0/1"], [caught, missed],
        expected="all | nothing notices this | only the real show catches it")
    check(code == 0 and not notes and "**Expected misses** (1)" in summary,
          f"an expected miss is green and listed: {code} {notes}")

    # NOW CAUGHT and a stale list line, each its own annotation.
    code, lines, notes, summary = run(
        ["--shard", "0/1"], [caught],
        expected="all | the guard is gone | x\nall | ghost | y")
    check(code == 1 and said(notes, "NOW CAUGHT", "the guard is gone")
          and said(notes, "expected-miss list is stale", "ghost"),
          f"NOW CAUGHT and a stale line are annotated: {code} {notes}")

    # A flaky catch: red once, green the second time, is NOT CAUGHT and the
    # annotation carries the first failure.
    flaky = ("flaky guard", "target.py", "GUARD", "FLAKY")
    code, lines, notes, summary = run(["--shard", "0/1"], [flaky], expected="")
    check(code == 1 and said(notes, "NOT CAUGHT (flaky)",
                             "caught once, then not",
                             "FAIL  took 0.9 s on a slow runner"),
          f"a flaky catch is annotated with its first failure: {code} {notes}")
    check("| 1 | 0 | 1 | 0 | 1 | 0 |" in summary,
          f"the flaky column counts it:\n{summary}")

    # SETUP FAIL: the text to break is not in the file.
    stale = ("refreshed away", "target.py", "ABSENT", "x")
    code, lines, notes, summary = run(["--shard", "0/1"], [caught, stale],
                                      expected="")
    check(code == 1 and said(notes, "mutation setup failed",
                             "pattern appears 0 times in target.py: refreshed away"),
          f"a SETUP FAIL is annotated: {code} {notes}")
    check("  SETUP FAIL  refreshed away (pattern appears 0 times in target.py)"
          in lines, "the SETUP FAIL log line is unchanged")

    # The baseline fails: which test, from the first FAIL line.
    code, lines, notes, summary = run(["--shard", "0/1"], [caught],
                                      target_text="BAD\nGUARD\n")
    check(code == 2 and said(notes, "the suite FAILS with nothing mutated",
                             "FAIL  the guard is gone"),
          f"a red baseline is annotated with the failing check: {code} {notes}")
    check("| FAILED |" in summary, f"the baseline column says so:\n{summary}")
    # ... and when the suite hangs instead.
    code, lines, notes, summary = run(["--shard", "0/1"], [caught],
                                      target_text="SLEEP\nGUARD\n",
                                      SUITE_TIMEOUT=1)
    check(code == 2 and said(notes, "INFRASTRUCTURE", "nothing mutated",
                             "did not finish inside 1 s"),
          f"a hung baseline is annotated as a timeout: {code} {notes}")
    check("| TIMED OUT |" in summary and "running it once more" in
          "\n".join(lines) and not any("NOT CAUGHT" in l for l in lines),
          f"a hung baseline is retried once, then an infrastructure failure, "
          f"never a miss:\n{summary}")
    # ... and when a test lets an exception out: the traceback's last line.
    code, lines, notes, summary = run(["--shard", "0/1"], [caught],
                                      target_text="CRASH\nGUARD\n")
    check(code == 2 and said(notes, "nothing mutated",
                             "ValueError: a test let this out"),
          f"a crashing baseline is annotated with its exception: {code} {notes}")

    # The restore proof fails: a write that leaves the mutation behind.
    real_write = mutate._write

    def leaky_write(path, text):
        real_write(path, text if "GUARD" not in text else text + "# left\n")
    code, lines, notes, summary = run(["--shard", "0/1"], [caught],
                                      _write=leaky_write)
    check(code == 2 and said(notes, "restore proof failed",
                             "a restore did not land in target.py"),
          f"a failed restore is annotated: {code} {notes}")
    check("| NO |" in summary, f"the restored column says NO:\n{summary}")

    # An unexpected exception: the traceback's last lines, and the lock is
    # released all the same.
    gone = ("file is gone", "missing.py", "a", "b")
    code, lines, notes, summary = run(["--shard", "0/1"], [gone])
    check(code == 1 and said(notes, "unexpected exception",
                             "FileNotFoundError", "missing.py"),
          f"an exception is annotated with its traceback: {code} {notes}")
    check(not os.path.exists(os.path.join(tree, ".mutating")),
          "the lock is released after an exception")

    # Another run holds the tree.
    open(os.path.join(tree, ".mutating"), "w").close()
    saved_lock, saved_ci = mutate.LOCK, mutate.CI
    env_saved = os.environ.get("GITHUB_STEP_SUMMARY")
    try:
        mutate.LOCK = os.path.join(tree, ".mutating")
        with open(summary_file, "w"):
            pass
        os.environ["GITHUB_STEP_SUMMARY"] = summary_file
        mutate.CI = True
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            code = mutate.main()
    finally:
        mutate.LOCK, mutate.CI = saved_lock, saved_ci
        if env_saved is None:
            os.environ.pop("GITHUB_STEP_SUMMARY", None)
        else:
            os.environ["GITHUB_STEP_SUMMARY"] = env_saved
        os.remove(os.path.join(tree, ".mutating"))
    notes = [l for l in buf.getvalue().splitlines() if l.startswith("::error ")]
    check(code == 3 and said(notes, "another run holds the tree", ".mutating"),
          f"a held tree is annotated: {code} {notes}")

    # The diff cannot be read (no git repository here).
    code, lines, notes, summary = run(["--shard", "0/1", "--changed", "nope"],
                                      [caught])
    check(code == 2 and said(notes, "cannot read the diff"),
          f"an unreadable diff is annotated: {code} {notes}")

    # GitHub keeps ten annotations a step: the tenth says there are more
    # and the summary lists every one.
    many = [(f"miss number {i}", "target.py", "GUARD", "NOTHING")
            for i in range(12)]
    code, lines, notes, summary = run(["--shard", "0/1"], many)
    check(code == 1 and len(notes) == 10 and "more problems" in notes[-1]
          and summary.count("`target.py`: miss number") == 12,
          f"twelve misses: {len(notes)} annotations, the last says more: "
          f"{notes[-1:]}")

    # An annotation never runs past GitHub's size, however long the lines.
    note = mutate.annotation("t", ["x" * 5000] + ["y"] * 20)
    check(len(note) < 3200 and "(cut)" in note and "more lines in the log" in note,
          f"a long annotation is cut: {len(note)} chars")
    check(mutate.annotation("a, b: c", ["p%q"]).startswith(
        "::error title=a%2C b%3A c::p%25q"),
          "the title's commas and colons are escaped, the body's percent too")


def test_mutate_never_runs_stale_bytecode():
    section("mutate.py: a mutant the same size as the line it replaces, "
            "written in the same second the original was compiled, is what "
            "runs, not the original's cached bytecode (nightly run "
            "40469889985, shard 15)")
    import py_compile
    import subprocess
    import mutate
    with tempfile.TemporaryDirectory() as d:
        src = os.path.join(d, "fademod.py")
        orig, mutant = "LEVEL = 0.0\n", "LEVEL = 1.0\n"
        with open(src, "w", encoding="utf-8", newline="") as fh:
            fh.write(orig)
        st = os.stat(src)
        py_compile.compile(src, doraise=True)    # the original, cached

        def level():
            r = subprocess.run([sys.executable, "-c",
                                "import fademod; print(fademod.LEVEL)"],
                               cwd=d, capture_output=True, text=True,
                               timeout=60)
            return r.stdout.strip() or r.stderr.strip()[-200:]

        # The trap: same size, same whole-second mtime as the compiled
        # original. Written plainly, Python runs the cached original.
        with open(src, "w", encoding="utf-8", newline="") as fh:
            fh.write(mutant)
        os.utime(src, ns=(st.st_atime_ns, st.st_mtime_ns))
        check(level() == "0.0",
              f"setup: a plain write in the same second runs the stale "
              f"original (the trap this guards against): {level()}")
        # mutate.py's own write, with the same mtime forced back.
        py_compile.compile(src, doraise=True)
        with open(src, "w", encoding="utf-8", newline="") as fh:
            fh.write(orig)
        os.utime(src, ns=(st.st_atime_ns, st.st_mtime_ns))
        py_compile.compile(src, doraise=True)    # the original, cached
        mutate._write(src, mutant)
        os.utime(src, ns=(st.st_atime_ns, st.st_mtime_ns))
        check(level() == "1.0",
              f"mutate.py's write runs the mutant: {level()}")
        # And the restore runs the restored source, not the mutant's
        # bytecode.
        mutate._write(src, orig)
        os.utime(src, ns=(st.st_atime_ns, st.st_mtime_ns))
        check(level() == "0.0",
              f"mutate.py's restore runs the original again: {level()}")
        mutate._write(os.path.join(d, "notes.txt"), "x")   # not .py: fine
    print("  ok")


def test_release_tags_are_ltc_only():
    section("release tags: a new release is tagged ltc-YYYY.MM.DD.N and only "
            "an ltc-* tag builds the installer (no workflow trigger names a "
            "gpl- tag, and a gpl-* tag fails the selftest run with the "
            "reason); the updater and the rollback still read the old gpl- "
            "names, so an old install is offered the new release by its "
            "date digits")
    import re
    here = os.path.dirname(os.path.abspath(__file__))
    wfdir = os.path.join(here, ".github", "workflows")
    names = sorted(n for n in os.listdir(wfdir) if n.endswith((".yml",
                                                               ".yaml")))
    check("windows-app.yml" in names and "selftest.yml" in names,
          f"the workflows are where this test reads them: {names}")
    texts = {}
    for n in names:
        texts[n] = open(os.path.join(wfdir, n), encoding="utf-8").read()
        # The trigger block: from "on:" to the next top-level key. Comments
        # may name the old tag (as history); a pattern may not.
        m = re.search(r"^on:\s*\n(.*?)(?=^\S)", texts[n], re.M | re.S)
        block = m.group(1) if m else ""
        live = "\n".join(ln.split("#", 1)[0] for ln in block.splitlines())
        check("gpl" not in live.lower(),
              f"{n}: a trigger still names a gpl- tag, so a release could "
              f"be cut under the old name: "
              f"{[ln.strip() for ln in live.splitlines() if 'gpl' in ln.lower()]}")
    wa = texts.get("windows-app.yml", "")
    tags = re.findall(r"^\s*tags:\s*(\[.*?\])\s*$", wa, re.M)
    check(tags == ['["ltc-*"]'],
          f"windows-app.yml builds a release for ltc-* tags only: {tags}")
    check('v="${GITHUB_REF_NAME#ltc-}"' in wa and "#gpl-" not in wa,
          "the installer's version is the tag without ltc- (ltc-2026.11.14.1 "
          "-> 2026.11.14.1, as on the rack screen and the installer's name)")
    check('if [[ ! "$GITHUB_REF_NAME" =~ ^ltc-[0-9]+(\\.[0-9]+){1,3}$ ]]; '
          'then' in wa,
          "Run workflow pointed at an old gpl- tag (or any tag that is not "
          "ltc- and a dated number) fails with the reason, never builds")
    check('--title "LTC Player release $VER"' in wa and
          '"LTC Player $TAG"' not in wa,
          "the Release's title is the dated number, never the tag name")
    # The refusal lives in .github/scripts/mutate_plan.py's mode (the CI
    # diet, #255): the changes job asks it first, under set -euo pipefail,
    # so a gpl-* tag stops the run red with the reason before anything
    # else is decided. test_mutate_shards_fit_their_time_limit runs it.
    st = texts.get("selftest.yml", "")
    ask = st.find('python3 .github/scripts/mutate_plan.py mode "$EVENT" '
                  '"$REF" "$BASE_REF" | tee')
    check(ask > 0 and st.rfind("set -euo pipefail", 0, ask) > 0
          and st.find("say ", ask) > ask,
          "selftest.yml asks mutate_plan.py first, so a gpl-* tag fails "
          "with the reason before anything else is decided")
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "mutate_plan", os.path.join(here, ".github", "scripts",
                                    "mutate_plan.py"))
    plan = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(plan)
    m_, why_ = plan.mode("push", "refs/tags/gpl-2026.11.14.1", "")
    check(m_ == "refuse" and "ltc-YYYY.MM.DD.N" in why_
          and plan.mode("push", "refs/tags/ltc-2026.11.14.1", "")[0] == "none",
          "a gpl-* tag is refused with the reason; an ltc-* tag is not: "
          f"{m_} {why_!r}")
    sp = os.path.join(here, "packaging", "windows")
    sys.path.insert(0, sp)
    for m_ in ("supervisor", "ltcwin", "updater"):
        sys.modules.pop(m_, None)
    was = sys.dont_write_bytecode
    sys.dont_write_bytecode = True
    try:
        import updater as U
        import supervisor as S
    finally:
        sys.dont_write_bytecode = was
    try:
        for old, want in (("ltc-2026.11.14.1", "2026.11.14.1"),
                          ("gpl-2026.10.30.1", "2026.10.30.1"),
                          ("GPL-2026.09.15.10", "2026.09.15.10"),
                          ("2026.11.14.1", "2026.11.14.1"),
                          ("bench-2026.11.13-abc1234",
                           "bench-2026.11.13-abc1234")):
            check(U.release_number(old) == want,
                  f"updater reads {old} as {U.release_number(old)!r}, "
                  f"want {want!r}")
        check(U.is_release("ltc-2026.11.14.1") and
              U.is_release("gpl-2026.09.15.10") and
              U.is_release("2026.10.30.1") and
              not U.is_release("bench-2026.11.13-abc1234") and
              not U.is_release("ltc-") and not U.is_release(""),
              "ltc- and gpl- release names are releases; bench and empty "
              "are not")
        for new, old in (("2026.11.14.1", "2026.10.30.1"),
                         ("2026.11.14.1", "gpl-2026.10.30.1"),
                         ("ltc-2026.11.14.1", "gpl-2026.09.15.10"),
                         ("2026.11.14.2", "ltc-2026.11.14.1")):
            check(U.is_newer(new, old) and not U.is_newer(old, new),
                  f"{new} is newer than {old} by its date digits, and "
                  f"never the other way round")
        check(not U.is_newer("2026.10.30.1", "gpl-2026.10.30.1") and
              not U.is_newer("ltc-2026.11.14.1", "2026.11.14.1"),
              "the same number with or without its prefix is up to date")
        lines = list(U.self_test())
        check(any("ltc- release is newer than a gpl- one" in ln
                  for ln in lines),
              f"the updater's own self-check proves the ltc- release: "
              f"{lines}")
        for v_, want in (("ltc-2026.11.14.1", (2026, 11, 14, 1)),
                         ("gpl-2026.10.30.1", (2026, 10, 30, 1)),
                         ("2026.09.15.10", (2026, 9, 15, 10)),
                         ("bench-2026.11.13-abc1234", ())):
            got = S._installer_key_for_version(v_)
            check(got == want, f"the rollback reads {v_} as {got}, want "
                               f"{want}")
        import tempfile
        d = tempfile.mkdtemp()
        try:
            files = []
            for i, n in enumerate(("LTC Player Setup ltc-2026.11.14.1.exe",
                                   "LTC Player Setup 2026.09.15.10.exe",
                                   "LTC Player Setup gpl-2026.10.30.1.exe",
                                   "LTC Player Setup 2026.11.14.2.exe")):
                p = os.path.join(d, n)
                with open(p, "wb") as fh:
                    fh.write(b"x")
                os.utime(p, (1000 + i, 1000 + i))
                files.append(p)
            order = [os.path.basename(p) for p in
                     sorted(files, key=S._installer_key)]
            check(order == ["LTC Player Setup 2026.09.15.10.exe",
                            "LTC Player Setup gpl-2026.10.30.1.exe",
                            "LTC Player Setup ltc-2026.11.14.1.exe",
                            "LTC Player Setup 2026.11.14.2.exe"],
                  f"saved installers sort by their date digits, whatever "
                  f"the prefix, so Roll back picks the one before: {order}")
        finally:
            import shutil as _sh
            _sh.rmtree(d, ignore_errors=True)
    finally:
        if sp in sys.path:
            sys.path.remove(sp)
        for m_ in ("supervisor", "ltcwin", "updater"):
            sys.modules.pop(m_, None)
    for doc in (os.path.join(here, "CLAUDE.md"),
                os.path.join(sp, "INSTALL.md")):
        t = open(doc, encoding="utf-8").read()
        check("ltc-YYYY.MM.DD.N" in t and "gpl-YYYY" not in t,
              f"{os.path.relpath(doc, here)} names new release tags "
              f"ltc-YYYY.MM.DD.N")
    print("  ok")


def test_mutate_shards_fit_their_time_limit():
    section("the mutate shards (the CI diet, 2026-11-13): only a PR into "
            "main runs them per PR; one rule for how many and how many at "
            "once in selftest.yml, nightly-mutate.yml and weekly-mutate.yml "
            "(.github/scripts/mutate_plan.py); a shard ends far inside its "
            "340 minute limit; never more at once than the job slots minus "
            "the reserve; shards that trust the selftest job need it")
    import importlib.util
    import re
    here = os.path.dirname(os.path.abspath(__file__))
    spec = importlib.util.spec_from_file_location(
        "mutate_plan", os.path.join(here, ".github", "scripts",
                                    "mutate_plan.py"))
    plan = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(plan)

    # Who runs shards: a PR into main, nothing else.
    for event, ref, base, want in (
            ("pull_request", "refs/pull/9/merge", "main", "affected"),
            ("pull_request", "refs/pull/9/merge", "bench-build", "none"),
            ("pull_request", "refs/pull/9/merge", "haze-fluid-tracker", "none"),
            ("pull_request", "refs/pull/9/merge", "", "none"),
            ("push", "refs/heads/main", "", "none"),
            ("push", "refs/tags/ltc-2026.11.20.1", "", "none"),
            ("push", "refs/tags/gpl-2026.11.20.1", "", "refuse")):
        got, why = plan.mode(event, ref, base)
        check(got == want and why,
              f"{event} {ref} into {base or '(none)'}: {got}, want {want}")
    # A gpl-* tag (the old release name) builds nothing: the changes job
    # stops red with the reason, and no shard, no sweep starts.
    import subprocess as _sp
    r = _sp.run([sys.executable, os.path.join(here, ".github", "scripts",
                                              "mutate_plan.py"),
                 "mode", "push", "refs/tags/gpl-2026.11.20.1", ""],
                capture_output=True, text=True, timeout=60)
    check(r.returncode == 1 and "mode=refuse" in r.stdout
          and "::error::gpl-2026.11.20.1 uses the old release tag name"
          in r.stdout and "ltc-YYYY.MM.DD.N" in r.stdout,
          f"a gpl-* tag is refused with the reason, exit 1: "
          f"{r.returncode} {r.stdout[-300:]!r}")

    # mutate-safety on a bench-build PR: a touched safety file's own
    # mutations; the whole core only when a core file changed; nothing for
    # docs, wording or the page.
    for changed, want in (
            (["README.md", "ltcplay/web/remote2.html", "ltcplay/remote.py"],
             []),
            (["ltcplay/users.py", "TESTING.md"], ["ltcplay/users.py"]),
            (["flamesafe/CONTRACT.md", "flamesafe/flamesafe.example.json"],
             []),
            (["ltcplay/fuelpump.py", "ltcplay/laserarm.py"],
             ["ltcplay/fuelpump.py", "ltcplay/laserarm.py"]),
            (["flamesafe/link.py"], ["flamesafe/", "flamesafe/link.py",
                                     "ltcplay/conductor.py",
                                     "ltcplay/flamelink.py"]),
            (["ltcplay/conductor.py", "ltcplay/users.py"],
             ["flamesafe/", "ltcplay/conductor.py", "ltcplay/flamelink.py",
              "ltcplay/users.py"])):
        got, why = plan.safety_targets(changed)
        check(got == want and why,
              f"mutate-safety for {changed}: {got}, want {want}")
    check(plan.safety_size(0, {}) == (0, 0)
          and plan.safety_size(553, {}) == (23, 4)
          and plan.safety_size(78, {}) == (4, 4)
          and plan.safety_size(30, {}) == (2, 2)
          and plan.safety_size(553, {"CI_SLOT_RESERVE": "6",
                                     "CI_JOB_SLOTS": "40"}) == (23, 6)
          and plan.safety_size(553, {"MUTATE_SAFETY_AT_ONCE": "2"}) == (23, 2),
          "mutate-safety runs at most the reserve (4) at once, or "
          "MUTATE_SAFETY_AT_ONCE")
    check(plan.nightly_cap({}) == 1500
          and plan.nightly_cap({"MUTATE_NIGHTLY_MAX": "900"}) == 900,
          "the nightly cap is 1500 mutations unless MUTATE_NIGHTLY_MAX says")
    # A matrix holds at most 256 jobs: a list that would need more stops
    # the plan with a sentence, never a red run with nothing said.
    for n, oses, ok in ((256 * 45, 1, True), (256 * 45 + 1, 1, False),
                        (128 * 45, 2, True), (128 * 45 + 1, 2, False)):
        try:
            plan.size(n, {}, oses)
            fine = True
        except ValueError as e:
            fine = False
            check("256 jobs one matrix may hold" in str(e),
                  f"the matrix limit is said plainly: {e}")
        check(fine == ok, f"{n} mutations on {oses} OS(es): "
                          f"{'fits' if fine else 'refused'}")

    # How many: about 25 a shard, at most MUTATE_SHARDS (30), never more
    # than 45 a shard; at once, never more than the slots minus the reserve.
    env = {}
    check(plan.size(0, env) == (0, 0), "nothing to run: no shard")
    for n, want in ((1, (1, 1)), (25, (1, 1)), (26, (2, 2)),
                    (400, (16, 16)), (551, (23, 16)), (750, (30, 16)),
                    (2649, (59, 16)), (4368, (98, 16))):
        check(plan.size(n, env) == want,
              f"{n} mutations: {plan.size(n, env)}, want {want}")
    check(plan.size(750, {"CI_JOB_SLOTS": "40"}) == (30, 30)
          and plan.size(4368, {"CI_JOB_SLOTS": "40"}) == (98, 36)
          and plan.size(4368, {"CI_JOB_SLOTS": "60",
                               "CI_SLOT_RESERVE": "10"}) == (98, 50),
          "more job slots: more shards at once, the reserve still free")
    for bad in ({"CI_JOB_SLOTS": "twenty"}, {"CI_JOB_SLOTS": "4",
                                             "CI_SLOT_RESERVE": "4"},
                {"MUTATE_SHARDS": "0"}):
        try:
            plan.size(100, bad)
            ok = False
        except ValueError:
            ok = True
        check(ok, f"a repository variable that cannot be right is an "
                  f"error, never a guess: {bad}")
    most = 0
    for n in range(1, 6000, 7):
        k, at_once = plan.size(n, env)
        most = max(most, -(-n // k))
        if not (1 <= at_once <= 16 and at_once <= k):
            check(False, f"{n} mutations: {k} shards, {at_once} at once")
            break
    # Measured 2026-11-13 (536 finished ubuntu shards, --jobs 3): about
    # 2.8 minutes of a shard a mutation; the sanity run that stands in for
    # the baseline is a few minutes; the old baseline was 15 to 19.
    worst = 19 + most * 2.8
    check(most <= plan.MOST_PER_SHARD and worst <= 150,
          f"at most {most} mutations a shard, about {worst:.0f} minutes at "
          f"the measured speed even with a whole baseline; want 150 or less")
    tree = __import__("ast").parse(open(os.path.join(here, "mutate.py"),
                                        encoding="utf-8").read())
    total = 0
    for node in __import__("ast").walk(tree):
        if isinstance(node, __import__("ast").Assign) and any(
                getattr(t, "id", None) == "MUTATIONS" for t in node.targets):
            total = len(node.value.elts)
    check(total > 1000 and -(-total // plan.size(total, env)[0]) <= 45,
          f"the whole list, {total}, fits shards of 45 or fewer")

    # The workflows use that rule and nothing of their own.
    wfdir = os.path.join(here, ".github", "workflows")
    text = {}
    for name in ("selftest.yml", "nightly-mutate.yml", "weekly-mutate.yml"):
        with open(os.path.join(wfdir, name), encoding="utf-8") as fh:
            text[name] = fh.read()
    for name, t in text.items():
        check("mutate_plan.py size" in t,
              f"{name}: the shard count comes from mutate_plan.py")
        par = re.findall(r"max-parallel: (.+)", t)
        check(par and all(re.fullmatch(
                  r"\$\{\{ fromJSON\(needs\.\w+\.outputs\."
                  r"(safety_)?parallel\) \}\}", p.strip()) for p in par),
              f"{name}: max-parallel is mutate_plan.py's, never a number of "
              f"its own: {par}")
        check(re.findall(r"timeout-minutes: 340\b", t) and
              re.findall(r"timeout-minutes: 355\b", t),
              f"{name}: the 340 minute step limit and the 355 minute job "
              f"limit stay as the backstop")
        check("python3 .github/scripts/shard_timeout.py" in t,
              f"{name}: a shard that ran out of time is said as such")
        check(re.search(r"upload-artifact@v4\n\s+if: always\(\)\n\s+"
                        r"continue-on-error: true\n\s+with:\n\s+name: "
                        r"mutate-log-", t),
              f"{name}: an upload error never turns a shard red")
        check("\u2013" not in t and "\u2014" not in t,
              f"{name} has no em or en dashes")
        # --trust-baseline only where the shards need a green selftest of
        # the same commit in the same run: every job that passes it.
        for job in re.split(r"\n  (?=[\w-]+:\n)",
                            t.split("\njobs:\n", 1)[-1]):
            if "--trust-baseline" in job:
                check(re.match(r"[\w-]+:\n    needs: \[(changes|plan), "
                               r"selftest\]\n", job),
                      f"{name}: {job.split(':')[0]} trusts the selftest job "
                      f"and needs it")
    st = text["selftest.yml"]
    check("mutate_plan.py mode \"$EVENT\" \"$REF\" \"$BASE_REF\"" in st
          and "python3 mutate.py --changed \"$base\" ${core:+\"$core\"} "
          "--list" in st
          and "narrow=(--changed \"$BASE\" ${CORE:+\"$CORE\"})" in st,
          "selftest.yml: the mode is mutate_plan.py's, and a PR into main "
          "lists and runs its selection with the safety core")
    check("mutate.py lost --with-core, which its base has" in st,
          "selftest.yml: a PR into main cannot drop the safety core by "
          "editing mutate.py")
    check("int(os.environ.get(\"NSHARDS\") or 0)" in st and '"no job"' in st,
          "mutate-report counts a shard that never got a job as red")
    nm = text["nightly-mutate.yml"]
    check("name: green at ${{ needs.plan.outputs.sha }}" in nm and
          "sed -n 's/^green at \\([0-9a-f]\\{40\\}\\)$/\\1/p'" in nm and
          "git merge-base --is-ancestor \"$g\" \"$sha\"" in nm,
          "the nightly sweep records its green commit and reads the last "
          "one this commit descends from")
    check("needs.selftest.result == 'success' && needs.sweep.result == "
          "'success'" in nm,
          "a night is recorded green only when its selftest and shards are")
    for name in ("nightly-mutate.yml", "weekly-mutate.yml"):
        t = text[name]
        check("group: mutate-sweeps" in t and
              "cancel-in-progress: false" in t,
              f"{name}: one sweep at a time, nightly and weekly together")
        check(re.search(r"\n  report:\n    needs: \[plan, selftest, sweep\]"
                        r"\n    if: always\(\)\n", t)
              and "PLAN: ${{ needs.plan.result }}" in t,
              f"{name}: the report always runs, and a failed plan is red")
    check('if [[ "${OFFICIAL:-}" != true ]]; then' in open(
              os.path.join(here, ".github", "scripts", "sweep_report.sh"),
              encoding="utf-8").read()
          and 'env("PLAN") != "success"' in open(
              os.path.join(here, ".github", "scripts", "sweep_report.sh"),
              encoding="utf-8").read(),
          "only the record sweep touches the issue; a failed plan is red")
    # The night is the evening, Mountain time, and only the record night
    # moves the marker.
    check('- cron: "17 2 * * 1-6"' in nm and "19:17 Mountain" in nm,
          "the nightly sweep starts at 19:17 Mountain Standard Time")
    check("if: always() && (github.event_name == 'schedule' || (inputs.ref == "
          "'bench-build' && inputs.base == '')) && needs.plan.result == "
          "'success'" in nm,
          "only a scheduled night, or one by hand on bench-build with no "
          "base of its own, writes the green marker")
    check("mutate_plan.py nightly-cap" in nm and
          "safety-targets --with-core" in nm and
          'narrow=(--targets "$TARGETS")' in nm,
          "a night over its cap runs the core and the touched safety files")
    check('- cron: "12 2 * * 0"' in text["weekly-mutate.yml"] and
          'mutate_plan.py size "$n" "$noses"' in text["weekly-mutate.yml"],
          "the weekly sweep starts Saturday evening, Mountain time, and "
          "checks the matrix limit for every OS it runs")
    with open(os.path.join(wfdir, "sweep-dropped.yml"), encoding="utf-8") as fh:
        dropped = fh.read()
    check('workflows: ["nightly mutate", "weekly mutate"]' in dropped and
          "github.event.workflow_run.conclusion == 'cancelled'" in dropped,
          "a scheduled sweep dropped from the queue still opens its issue")
    # mutate-safety: a ready PR that touches a safety file, never required,
    # the reserve at most at once.
    check(re.search(r"\n  mutate-safety:\n    needs: \[changes, selftest\]\n"
                    r"    if: github\.event_name == 'pull_request' && "
                    r"github\.event\.pull_request\.draft == false", st)
          and "--targets \"$TARGETS\"" in st,
          "selftest.yml: mutate-safety runs on a ready PR, its targets only")
    # An edit that did not move the base runs nothing but ci, and never
    # cancels the real run.
    check("github.event.action != 'edited' || github.event.changes.base"
          in st and st.count("    if: github.event.action != 'edited' || "
                             "github.event.changes.base\n") == 2,
          "selftest.yml: an edit of a PR's text runs no selftest or changes")
    print("  ok")


def test_ci_verdict_rules():
    section("ci, the one required check on main (.github/scripts/"
            "ci_verdict.sh): green only for a push or a PR into main whose "
            "selftest, changes and needed shards are green; red when the "
            "base is not main, the mode is unknown, or a needed shard did "
            "not pass; an edit of a PR's text copies the last verdict on "
            "the commit, never invents one")
    import re
    import shutil
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(here, ".github", "scripts", "ci_verdict.sh")
    with open(script, encoding="utf-8") as fh:
        src = fh.read()
    check("\u2013" not in src and "\u2014" not in src,
          "ci_verdict.sh has no em or en dashes")
    # Run on ubuntu only: on windows `bash` may be WSL's, not Git's, and
    # the verdict is run by an ubuntu job anyway.
    bash = shutil.which("bash")
    if sys.platform == "win32" or not bash:
        print("  (the verdict runs are skipped here: no plain bash)")
    else:
        with tempfile.TemporaryDirectory() as d:
            fake = os.path.join(d, "gh")
            with open(fake, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("#!/bin/sh\n[ -n \"$FAKE_GH\" ] && echo \"$FAKE_GH\"\n"
                         "[ -n \"$FAKE_GH\" ]\n")
            os.chmod(fake, 0o755)

            def verdict(**kw):
                env = {"PATH": d + os.pathsep + os.environ.get("PATH", ""),
                       "REPO": "o/r", "RUN_ID": "7", "HEAD_SHA": "abc",
                       "GH_TOKEN": "x"}
                env.update({k.upper(): v for k, v in kw.items()})
                r = _sp.run([bash, script], capture_output=True, text=True,
                            env=env, timeout=60)
                return r.returncode, r.stdout + r.stderr

            ok = dict(selftest="success", changes="success")
            cases = [
                # (what, event, settings, green?)
                ("a PR into main, nothing to mutate",
                 dict(event="pull_request", base_ref="main", mode="none",
                      mutate="skipped", **ok), True),
                ("a PR into main, every shard green",
                 dict(event="pull_request", base_ref="main", mode="affected",
                      mutate="success", **ok), True),
                ("a push to main", dict(event="push", mode="none",
                                        mutate="skipped", **ok), True),
                ("a PR into bench-build, all green",
                 dict(event="pull_request", base_ref="bench-build",
                      mode="none", mutate="skipped", **ok), False),
                ("a PR with no base", dict(event="pull_request", mode="none",
                                           mutate="skipped", **ok), False),
                ("the mode is empty (changes failed to say)",
                 dict(event="pull_request", base_ref="main", mode="",
                      mutate="skipped", **ok), False),
                ("an unknown mode", dict(event="pull_request", base_ref="main",
                                         mode="weird", mutate="skipped", **ok),
                 False),
                ("shards skipped while required",
                 dict(event="pull_request", base_ref="main", mode="affected",
                      mutate="skipped", **ok), False),
                ("shards cancelled", dict(event="pull_request", base_ref="main",
                                          mode="affected", mutate="cancelled",
                                          **ok), False),
                ("shards failed", dict(event="pull_request", base_ref="main",
                                       mode="full", mutate="failure", **ok),
                 False),
                ("shards ran with mode none",
                 dict(event="pull_request", base_ref="main", mode="none",
                      mutate="success", **ok), False),
                ("selftest red", dict(event="pull_request", base_ref="main",
                                      mode="none", mutate="skipped",
                                      selftest="failure", changes="success"),
                 False),
                ("changes red", dict(event="pull_request", base_ref="main",
                                     mode="none", mutate="skipped",
                                     selftest="success", changes="failure"),
                 False),
                ("a scheduled event", dict(event="schedule", mode="none",
                                           mutate="skipped", **ok), False),
                ("a text edit, the last verdict green",
                 dict(event="pull_request", action="edited", base_ref="main",
                      fake_gh="success"), True),
                ("a text edit, the last verdict red",
                 dict(event="pull_request", action="edited", base_ref="main",
                      fake_gh="failure"), False),
                ("a text edit, no verdict to copy (lookup fails)",
                 dict(event="pull_request", action="edited", base_ref="main"),
                 False),
                ("a text edit of a PR into bench-build",
                 dict(event="pull_request", action="edited",
                      base_ref="bench-build", fake_gh="success"), False),
                ("a retarget to main (edited, base changed) judged in full",
                 dict(event="pull_request", action="edited", base_changed="true",
                      base_ref="main", mode="affected", mutate="success",
                      fake_gh="failure", **ok), True),
                ("a retarget to main with shards not run",
                 dict(event="pull_request", action="edited", base_changed="true",
                      base_ref="main", mode="affected", mutate="skipped",
                      fake_gh="success", **ok), False)]
            for what, kw, green in cases:
                code, out = verdict(**kw)
                check((code == 0) == green,
                      f"ci for {what}: exit {code}, want "
                      f"{'green' if green else 'red'}: {out[-300:]!r}")

    # The workflow on main runs exactly this script with the needed jobs'
    # results, whatever happened to them, and listens for a retarget.
    with open(os.path.join(here, ".github", "workflows", "selftest.yml"),
              encoding="utf-8") as fh:
        st = fh.read()
    if "\n  ci:\n" in st:
        ci = st.split("\n  ci:\n", 1)[1]
        check(ci.startswith("    needs: [selftest, changes, mutate]\n"
                            "    if: always() && (github.event_name != "
                            "'pull_request' || github.event.pull_request."
                            "draft == false)\n"),
              "ci needs selftest, changes and mutate, and runs whatever "
              "they did")
        for line in ("SELFTEST: ${{ needs.selftest.result }}",
                     "CHANGES: ${{ needs.changes.result }}",
                     "MUTATE: ${{ needs.mutate.result }}",
                     "MODE: ${{ needs.changes.outputs.mode }}",
                     "BASE_REF: ${{ github.base_ref }}",
                     "ACTION: ${{ github.event.action }}",
                     "BASE_CHANGED: ${{ github.event.changes.base != null }}",
                     "\n          bash .github/scripts/ci_verdict.sh\n"):
            check(line in ci, f"ci passes {line!r}")
        check(re.search(r"types: \[[^\]]*\bedited\b[^\]]*\]", st)
              and re.search(r"types: \[[^\]]*\breopened\b[^\]]*\]", st),
              "main's selftest.yml runs again when a PR is edited "
              "(retargeted) or reopened")
    print("  ok")


def test_mutate_mutant_limit_follows_the_baseline():
    """A mutant's suite is stopped at a limit measured from the unmutated
    baseline on the same runner, not a fixed 300 s, and a baseline that does
    not finish is an infrastructure failure, retried once, never a missed
    mutation. PR #87 shards 10 and 13 went red because a clean baseline took
    longer than 300 s on a loaded runner. The suite runs here are faked with
    chosen durations, so nothing waits."""
    section("mutate.py: the mutant limit is relative to the baseline")
    import contextlib
    import io
    import mutate

    # The rule itself: three times the baseline, never under the old 300 s,
    # never over the ceiling.
    for base, want in ((0, 300), (60, 300), (100, 300), (150, 450),
                       (280, 840), (600, 1800), (1800, 5400),
                       (5000, 5400)):
        check(mutate.mutant_timeout(base) == want,
              f"baseline {base} s: mutant limit "
              f"{mutate.mutant_timeout(base)} s, want {want} s")
    check(mutate.MUTANT_CEILING <= mutate.SUITE_TIMEOUT,
          "no mutant may run longer than the baseline is allowed to")
    HANG = float("inf")

    with tempfile.TemporaryDirectory() as tree:
        target = os.path.join(tree, "target.py")

        def sweep(baselines, mutant, mutant_red=False, ci=True):
            """Run main() with the suite faked: `baselines` are the seconds
            each unmutated run takes, `mutant` the seconds a mutated one
            takes (HANG for never). (exit, lines, notes, calls, report)."""
            with open(target, "w", encoding="utf-8", newline="") as fh:
                fh.write("ok\nGUARD\n")
            baselines = list(baselines)
            calls = []

            def fake_suite(limit=None, *_fast, **_where):
                # The fast-path settings (fail fast, a hint, a worker's
                # tree) do not change how long these fake runs take.
                limit = mutate.SUITE_TIMEOUT if limit is None else limit
                with open(target, encoding="utf-8") as fh:
                    mutated = "GUARD" not in fh.read()
                took = mutant if mutated else baselines.pop(0)
                calls.append(("mutant" if mutated else "baseline", limit))
                if took > limit:
                    mutate._LAST_RUN[:] = [limit, True]
                    mutate._LAST_FAILS[:] = [
                        f"FAIL  the suite did not finish inside {limit} s "
                        f"(TimeoutExpired)"]
                    return False
                mutate._LAST_RUN[:] = [took, False]
                red = mutated and mutant_red
                mutate._LAST_FAILS[:] = ["FAIL  the guard is gone"] if red else []
                return not red

            saved = {k: getattr(mutate, k) for k in
                     ("HERE", "LOCK", "MUTATIONS", "CI", "run_suite")}
            env_saved = os.environ.pop("GITHUB_STEP_SUMMARY", None)
            old_argv = sys.argv
            buf = io.StringIO()
            try:
                mutate.HERE = tree
                mutate.LOCK = os.path.join(tree, ".mutating")
                mutate.MUTATIONS = [("the guard is gone", "target.py",
                                     "GUARD", "BROKEN")]
                mutate.CI = ci
                mutate.run_suite = fake_suite
                sys.argv = ["mutate.py", "--shard", "0/1",
                            "--expected", os.devnull]
                with contextlib.redirect_stdout(buf):
                    code = mutate.main()
            finally:
                for k, v in saved.items():
                    setattr(mutate, k, v)
                if env_saved is not None:
                    os.environ["GITHUB_STEP_SUMMARY"] = env_saved
                sys.argv = old_argv
            lines = buf.getvalue().splitlines()
            notes = [l for l in lines if l.startswith("::error ")]
            return code, lines, notes, calls, mutate.REPORT

        # A slow runner: the clean suite takes 290 s. A mutant that makes it
        # hang is stopped at 870 s and caught, twice in CI.
        code, lines, notes, calls, rep = sweep([290], HANG)
        check(code == 0 and calls == [("baseline", mutate.SUITE_TIMEOUT),
                                      ("mutant", 870), ("mutant", 870)],
              f"a hanging mutant is stopped at 3 x the baseline and caught: "
              f"exit {code}, runs {calls}")
        check("  caught      the guard is gone" in lines
              and any("did not finish inside 870 s" in l for l in lines)
              and rep.limits == "290 s / 870 s",
              f"the catch says it was a timeout at the measured limit: "
              f"{lines} {rep.limits}")

        # The same slow runner, a mutant that nothing tests: its suite is
        # merely slow (400 s), not hung. The old fixed 300 s stopped it and
        # called it caught; now it finishes green and is reported missed.
        code, lines, notes, calls, rep = sweep([290], 400)
        check(code == 1 and "  NOT CAUGHT  the guard is gone" in lines
              and calls == [("baseline", mutate.SUITE_TIMEOUT),
                            ("mutant", 870)],
              f"a slow mutant is not passed off as caught by timeout: "
              f"exit {code}, runs {calls}")

        # An ordinary catch is unchanged.
        code, lines, notes, calls, rep = sweep([120], 100, mutant_red=True)
        check(code == 0 and calls[1:] == [("mutant", 360), ("mutant", 360)]
              and "  caught      the guard is gone" in lines,
              f"a red mutant is caught as before: exit {code}, runs {calls}")

        # A fast runner: the floor keeps the old 300 s.
        code, lines, notes, calls, rep = sweep([40], HANG)
        check(code == 0 and calls[1:] == [("mutant", 300), ("mutant", 300)],
              f"a fast baseline keeps the 300 s floor: {calls}")

        # The baseline does not finish once: run once more, then measure the
        # mutant limit from the run that finished.
        code, lines, notes, calls, rep = sweep([HANG, 200], HANG)
        check(code == 0 and [c[0] for c in calls] == [
                  "baseline", "baseline", "mutant", "mutant"]
              and calls[2] == ("mutant", 600)
              and any("running it once more" in l for l in lines)
              and rep.baseline == "green" and not notes,
              f"a baseline timeout is retried once and the sweep goes on: "
              f"exit {code}, runs {calls}, {notes}")

        # Twice: an infrastructure failure. No mutant runs, nothing is
        # counted missed or caught, and it says so in its own words.
        code, lines, notes, calls, rep = sweep([HANG, HANG], HANG)
        check(code == 2 and [c[0] for c in calls] == ["baseline", "baseline"],
              f"two baseline timeouts stop the shard before any mutant: "
              f"exit {code}, runs {calls}")
        check(rep.baseline == "TIMED OUT" and not rep.missed
              and not rep.caught
              and any(l.startswith("INFRASTRUCTURE FAILURE") for l in lines)
              and any("INFRASTRUCTURE" in n and "not a missed mutation" in n
                      for n in notes)
              and not any("NOT CAUGHT" in l or "FAILS with nothing mutated"
                          in l for l in lines),
              f"a baseline that never finishes is infrastructure, not a "
              f"miss or a red suite: {rep.baseline} {lines} {notes}")


def test_mutate_fast_path_never_turns_red_green():
    """mutate.py's fast path (fail fast, the catcher hint run first, --jobs)
    changes how long a sweep takes, never a verdict: the baseline runs every
    test in file order with none of the settings, a hinted run counts only
    when it failed in the hinted test after that test passed run first with
    nothing mutated, anything else runs again in file order, a mutation is
    caught only when two runs fail and the second is plain file order with
    no hint, and with --jobs each copy runs its own whole baseline and is
    proved restored, a baseline red once and then green named as flaky.
    The suite runs are faked."""
    section("mutate.py: the fast path changes the time, not the verdict")
    import contextlib
    import io
    import subprocess as _sp
    import mutate

    # selftest.py's own order: every test exactly once, the named ones
    # first, names that are not tests ignored.
    def a(): pass
    def b(): pass
    def c(): pass
    saved_first = os.environ.get("LTC_SELFTEST_FIRST")
    try:
        os.environ["LTC_SELFTEST_FIRST"] = "c,nope,c,a"
        order, head = _test_order([a, b, c])
        check(order == [c, a, b] and head == [c, a],
              f"LTC_SELFTEST_FIRST puts c, a first, every test once: "
              f"{[f.__name__ for f in order]}")
        os.environ["LTC_SELFTEST_FIRST"] = ""
        order, head = _test_order([a, b, c])
        check(order == [a, b, c] and head == [],
              "no LTC_SELFTEST_FIRST: file order")
    finally:
        if saved_first is None:
            os.environ.pop("LTC_SELFTEST_FIRST", None)
        else:
            os.environ["LTC_SELFTEST_FIRST"] = saved_first

    # A baseline never inherits a fast-path setting from the environment.
    seen = []

    class _R:
        returncode, stdout, stderr = 0, "", ""

    def fake_run(*a, **k):
        seen.append(dict(k.get("env") or {}))
        return _R()

    saved_env = {k: os.environ.get(k) for k in mutate._FAST_ENV}
    saved_run = mutate.subprocess.run
    try:
        for k in mutate._FAST_ENV:
            os.environ[k] = "1"
        mutate.subprocess.run = fake_run
        mutate.run_suite(10)
        mutate.run_suite(10, True, "test_x")
    finally:
        mutate.subprocess.run = saved_run
        for k, v in saved_env.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    check(len(seen) == 2 and not any(k in seen[0] for k in mutate._FAST_ENV),
          f"a plain run (the baseline) carries none of {mutate._FAST_ENV}")
    check(len(seen) == 2 and seen[1].get("LTC_SELFTEST_FAILFAST") == "1"
          and seen[1].get("LTC_SELFTEST_FIRST") == "test_x"
          and "LTC_SELFTEST_PROBE" not in seen[1],
          "a mutated run carries exactly what it was asked for")
    check(mutate.PROBE_EXIT == PROBE_EXIT != 0,
          "a probe's exit is never 0, and both files agree on it")

    with tempfile.TemporaryDirectory() as tree:
        names = ["m one", "m two"]

        def sweep(behave, hints=None, jobs=1, ci=True, listed=True,
                  extra=()):
            """behave(name, failfast, first, probe) -> (green, stopped in).
            (exit, lines, calls, catchers written)."""
            for i, n in enumerate(names):
                with open(os.path.join(tree, f"t{i}.py"), "w",
                          encoding="utf-8", newline="") as fh:
                    fh.write(f"ok\nGUARD{i}\n")
            calls = []
            lock = threading.Lock()

            def fake_suite(limit=None, failfast=False, first=None,
                           probe=False, root=None, extra_env=None):
                root = root or tree
                hit = None
                for i, n in enumerate(names):
                    with open(os.path.join(root, f"t{i}.py"),
                              encoding="utf-8") as fh:
                        if f"GUARD{i}" not in fh.read():
                            hit = n
                with lock:
                    calls.append((hit, bool(failfast), first, bool(probe),
                                  root == tree))
                mutate._LAST_RUN[:] = [5.0, False]
                mutate._LAST_STOP[:] = ["", False]
                green, stop = behave(hit, failfast, first, probe)
                if probe and green:
                    mutate._LAST_STOP[1] = True
                    green = False
                mutate._LAST_STOP[0] = stop if failfast else ""
                mutate._LAST_FAILS[:] = [] if green else [f"FAIL  in {stop}"]
                return green

            hf = os.path.join(tree, "hints.json")
            wf = os.path.join(tree, "learned.json")
            for p in (hf, wf):
                if os.path.exists(p):
                    os.remove(p)
            if hints is not None:
                with open(hf, "w", encoding="utf-8") as fh:
                    json.dump(hints, fh)
            saved = {k: getattr(mutate, k) for k in
                     ("HERE", "LOCK", "MUTATIONS", "CI", "run_suite")}
            env_saved = os.environ.pop("GITHUB_STEP_SUMMARY", None)
            old_argv = sys.argv
            buf = io.StringIO()
            try:
                mutate.HERE = tree
                mutate.LOCK = os.path.join(tree, ".mutating")
                mutate.MUTATIONS = [(n, f"t{i}.py", f"GUARD{i}", "BROKEN")
                                    for i, n in enumerate(names)]
                mutate.CI = ci
                mutate.run_suite = fake_suite
                sys.argv = (["mutate.py", "--shard", "0/1"]
                            + (["--expected", os.devnull] if listed else [])
                            + ["--hints", hf, "--write-catchers", wf,
                               "--jobs", str(jobs)] + list(extra))
                with contextlib.redirect_stdout(buf):
                    code = mutate.main()
            finally:
                for k, v in saved.items():
                    setattr(mutate, k, v)
                if env_saved is not None:
                    os.environ["GITHUB_STEP_SUMMARY"] = env_saved
                sys.argv = old_argv
            learned = {}
            if os.path.exists(wf):
                with open(wf, encoding="utf-8") as fh:
                    learned = json.load(fh)
            return code, buf.getvalue().splitlines(), calls, learned

        def base_runs(calls):
            return [c for c in calls if c[0] is None and not c[3]]

        # Caught by the hinted test, run first, twice. The baseline ran with
        # no fast-path setting at all; the probe ran once for the shared hint.
        def red_in_t_guard(hit, ff, first, probe):
            return (hit is None, "test_guard")
        code, lines, calls, learned = sweep(
            red_in_t_guard, {"m one": "test_guard", "m two": "test_guard"})
        check(code == 0 and base_runs(calls) == [(None, False, None, False, True)],
              f"the baseline is one full run in file order: {calls}")
        check([c for c in calls if c[3]] == [(None, True, "test_guard", True, True)],
              f"the hint is probed once, with nothing mutated: {calls}")
        check([c for c in calls if c[0]] == [
                  ("m one", True, "test_guard", False, True),
                  ("m one", True, None, False, True),
                  ("m two", True, "test_guard", False, True),
                  ("m two", True, None, False, True)],
              f"each mutation: two fail-fast runs, the hint first, then the "
              f"confirming one in file order with no hint: {calls}")
        check(learned == {"m one": "test_guard", "m two": "test_guard"},
              f"--write-catchers records where each was caught: {learned}")

        # The hinted run fails in another test: that run does not count, and
        # the run in file order does.
        def red_elsewhere(hit, ff, first, probe):
            if hit is None:
                return True, ""
            return False, "test_other"
        code, lines, calls, learned = sweep(red_elsewhere,
                                            {"m one": "test_guard"})
        mine = [c for c in calls if c[0] == "m one"]
        check(code == 0 and mine == [("m one", True, "test_guard", False, True),
                                     ("m one", True, None, False, True),
                                     ("m one", True, None, False, True)],
              f"red in another test than the hint: run again in file order, "
              f"twice: {mine}")
        check(learned.get("m one") == "test_other",
              f"the catcher learned is where it really stopped: {learned}")

        # A hint may name several tests, comma separated: a run red in any
        # of them counts as the hinted run (confirmed in file order).
        code, lines, calls, learned = sweep(
            red_in_t_guard, {"m one": "test_other,test_guard"})
        mine = [c for c in calls if c[0] == "m one"]
        check(code == 0 and mine == [
                  ("m one", True, "test_other,test_guard", False, True),
                  ("m one", True, None, False, True)],
              f"red in the second test a hint names counts: {mine}")
        check(learned.get("m one") == "test_guard",
              f"the catcher learned is the one test it stopped in: {learned}")

        # Red only when the hinted test runs first (an order-dependent leak:
        # the suite in file order is green under the mutation). The file
        # order confirm run is green, so it is NOT CAUGHT, flagged flaky,
        # and the hint is never written back as a catcher.
        def red_only_hint_first(hit, ff, first, probe):
            if hit is None:
                return True, ""
            return (first != "test_guard", "test_guard")
        code, lines, calls, learned = sweep(
            red_only_hint_first, {"m one": "test_guard", "m two": "test_guard"})
        mine = [c for c in calls if c[0] == "m one"]
        check(code == 1 and "  NOT CAUGHT  m one" in lines
              and "  NOT CAUGHT  m two" in lines
              and "  caught      m one" not in lines,
              f"red only with the hint first is NOT CAUGHT: exit {code}, "
              f"{lines}")
        check(mine == [("m one", True, "test_guard", False, True),
                       ("m one", True, None, False, True)],
              f"the confirming run is file order with no hint: {mine}")
        check(not learned,
              f"an order-only catch is never written as a catcher: {learned}")
        check(any("red only with test_guard run first" in l for l in lines),
              f"the flaky line says it was the order: {lines}")
        code, lines, calls, learned = sweep(
            red_only_hint_first, {"m one": "test_guard"}, ci=False,
            listed=False)
        check([c for c in calls if c[0] == "m one"][-1:] ==
              [("m one", True, None, False, True)]
              and "  caught      m one" not in lines and not learned,
              f"with no expected-miss list too, a hinted red is confirmed "
              f"in file order: {calls} {learned}")

        # The hinted test does not pass run first with nothing mutated: the
        # hint is dropped, its mutations run in file order.
        def probe_fails(hit, ff, first, probe):
            if probe:
                return False, "test_guard"
            return (hit is None, "test_guard")
        code, lines, calls, learned = sweep(probe_fails,
                                            {"m one": "test_guard"})
        check(code == 0 and all(c[2] is None for c in calls if c[0])
              and any("does not pass when run first" in l for l in lines),
              f"a hint that fails on its own is not used: {calls}")

        # A mutation nothing catches: green in the hinted run and in file
        # order, NOT CAUGHT, whatever the hint said.
        def nothing_catches(hit, ff, first, probe):
            return True, ""
        code, lines, calls, learned = sweep(nothing_catches,
                                            {"m one": "test_guard"})
        check(code == 1 and "  NOT CAUGHT  m one" in lines
              and "  NOT CAUGHT  m two" in lines and not learned,
              f"green is green, hint or not: exit {code}, {lines}")

        # Caught once, then green: NOT CAUGHT, as without the fast path.
        once = {"n": 0}

        def flaky(hit, ff, first, probe):
            if hit is None:
                return True, ""
            once["n"] += 1
            return (once["n"] % 2 == 0, "test_guard")
        code, lines, calls, learned = sweep(flaky)
        check(code == 1 and "  NOT CAUGHT  m one" in lines
              and any(l.startswith("  caught once, then not") for l in lines),
              f"one red run of two is not caught: {lines}")

        # --jobs 2: each copy runs its own whole baseline, the tree itself is
        # never mutated, and every copy is proved restored.
        code, lines, calls, learned = sweep(
            red_in_t_guard, {"m one": "test_guard"}, jobs=2)
        bases = base_runs(calls)
        check(code == 0 and len(bases) == 2
              and all(b == (None, False, None, False, False) for b in bases),
              f"--jobs 2: two whole baselines, one per copy: {bases}")
        check(not any(c[4] for c in calls)
              and "  caught      m one" in lines
              and "  caught      m two" in lines
              and any("in each of 2 copies" in l for l in lines),
              f"--jobs 2: mutations run in the copies only, both caught, "
              f"every copy restored: {lines}")
        for i in range(2):
            with open(os.path.join(tree, f"t{i}.py"), encoding="utf-8") as fh:
                check(fh.read() == f"ok\nGUARD{i}\n",
                      f"the tree's own t{i}.py is untouched")

        # --jobs 2 with one baseline red once, then green: the sweep goes on
        # (the second run was whole and green) but says it was flaky.
        base_seen = {"n": 0}

        def red_base_once(hit, ff, first, probe):
            if hit is None and not probe:
                with lock_once:
                    base_seen["n"] += 1
                    if base_seen["n"] == 1:
                        return False, "test_wobbly"
            return (hit is None, "test_guard")
        lock_once = threading.Lock()
        code, lines, calls, learned = sweep(red_base_once, jobs=2)
        check(code == 0 and len(base_runs(calls)) == 3
              and any(l.startswith("FLAKY BASELINE: 1 of 2") for l in lines)
              and any("FAIL  in test_wobbly" in l for l in lines),
              f"--jobs 2: a baseline red once then green is reported as "
              f"flaky, never silently: {lines}")

        # A red baseline gets one more full run; red twice stops the shard.
        def red_base(hit, ff, first, probe):
            return False, "test_guard"
        code, lines, calls, learned = sweep(red_base)
        check(code == 2 and len(base_runs(calls)) == 2
              and not [c for c in calls if c[0]]
              and any("FAILS with nothing mutated" in l for l in lines),
              f"a red baseline is run once more, then stops the shard: "
              f"{calls}")

        # --trust-baseline (the CI diet, 2026-11-13): the selftest job of the
        # same run passed the whole suite on this commit, so no copy runs it
        # again. Each copy runs its hinted tests first instead (the sanity
        # run), and every test a caught mutant stopped in is proved green
        # alone in that copy, or the copy runs its whole baseline after all.
        trust = ("--trust-baseline", "1200")
        both = {"m one": "test_guard", "m two": "test_guard"}
        for jobs in (1, 2):
            code, lines, calls, learned = sweep(red_in_t_guard, both,
                                                jobs=jobs, extra=trust)
            sanity = [c for c in calls if c[0] is None and c[3]]
            check(code == 0 and not base_runs(calls)
                  and len(sanity) == jobs
                  and all(c[2] == "test_guard" for c in sanity)
                  and "  caught      m one" in lines
                  and "  caught      m two" in lines
                  and any(l.startswith("baseline trusted:") for l in lines),
                  f"--trust-baseline, --jobs {jobs}: no whole baseline, one "
                  f"sanity run per copy, both caught: {calls} {lines}")
            check([c for c in calls if c[0] == "m one"] == [
                      ("m one", True, "test_guard", False, jobs == 1),
                      ("m one", True, None, False, jobs == 1)],
                  f"--trust-baseline changes no mutated run: {calls}")
            check(any(l.startswith("baseline trusted:") and "after 3600 s"
                      in l for l in lines),
                  f"the mutant limit is three times the trusted 1200 s: "
                  f"{lines}")
        # A sanity run that is red: that copy runs its whole baseline, as
        # without the option.
        code, lines, calls, learned = sweep(probe_fails, both, extra=trust)
        check(code == 0 and len(base_runs(calls)) == 1
              and any("sanity run" in l and "was red" in l for l in lines)
              and not any(l.startswith("baseline trusted:") for l in lines),
              f"a red sanity run costs the copy its whole baseline: {calls}")
        # No hint at all: nothing can stand in for the baseline.
        code, lines, calls, learned = sweep(red_in_t_guard, None,
                                            extra=trust)
        check(code == 0 and len(base_runs(calls)) == 1
              and any("nothing can stand in for the baseline" in l
                      for l in lines),
              f"--trust-baseline without hints runs the baseline: {calls}")

        # A caught mutant that stopped in a test the sanity run did not run
        # first: that test is proved green alone in the copy, nothing
        # mutated, once, and the verdict stands.
        def stop_other(hit, ff, first, probe):
            if hit is None:
                return True, ""
            return False, ("test_guard" if first == "test_guard"
                           else "test_other")
        code, lines, calls, learned = sweep(
            stop_other, {"m one": "test_guard"}, extra=trust)
        alone = [c for c in calls if c[0] is None and c[3]
                 and c[2] == "test_other"]
        check(code == 0 and not base_runs(calls) and len(alone) == 1
              and "  caught      m one" in lines
              and "  caught      m two" in lines,
              f"a stopping test outside the sanity run is proved alone, "
              f"once per copy: {calls} {lines}")

        # That test is red alone (it needs a test before it): the copy runs
        # its whole baseline; green, and the verdict stands.
        def other_red_alone(hit, ff, first, probe):
            if probe and first == "test_other":
                return False, "test_other"
            if hit is None:
                return True, ""
            return False, "test_other"
        code, lines, calls, learned = sweep(
            other_red_alone, {"m one": "test_guard"}, extra=trust)
        check(code == 0 and len(base_runs(calls)) == 1
              and "  caught      m one" in lines
              and "  caught      m two" in lines,
              f"a stopping test red alone costs the copy one whole baseline, "
              f"then the verdicts stand: {calls} {lines}")

        # And that baseline is red: no caught mutation of the copy counts,
        # the shard says the suite fails with nothing mutated, exit 2.
        def copy_broken(hit, ff, first, probe):
            if probe:
                return first != "test_other", "test_other"
            return False, "test_other"
        code, lines, calls, learned = sweep(
            copy_broken, {"m one": "test_guard"}, extra=trust)
        check(code == 2 and "  caught      m one" not in lines
              and any(l.startswith("  NO VERDICT  m one") for l in lines)
              and any(l.startswith("The suite FAILS with nothing mutated")
                      for l in lines)
              and not learned,
              f"a copy whose baseline is red gives no verdict at all: "
              f"exit {code}, {lines}")

    # --with-core: on a PR into main every flamesafe, conductor and flame
    # link mutation runs, whatever the diff, a doc included.
    with tempfile.TemporaryDirectory() as tree:
        saved = {k: getattr(mutate, k) for k in ("HERE", "LOCK", "MUTATIONS")}
        old_argv = sys.argv
        try:
            mutate.HERE = tree
            mutate.LOCK = os.path.join(tree, ".mutating")
            mutate.MUTATIONS = [
                ("core a", "flamesafe/composer.py", "x", "y"),
                ("core b", "ltcplay/conductor.py", "x", "y"),
                ("core c", "ltcplay/flamelink.py", "x", "y"),
                ("other d", "ltcplay/remote.py", "x", "y")]

            def listed(*args):
                sys.argv = ["mutate.py", "--list"] + list(args)
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    code = mutate.main()
                return code, sorted(l.split(": ", 1)[1] for l in
                                    buf.getvalue().splitlines()
                                    if l.startswith("  would run  "))
            code, got = listed("--files", "README.md")
            check(code == 0 and got == [],
                  f"a doc alone selects nothing: {got}")
            code, got = listed("--files", "README.md", "--with-core")
            check(code == 0 and got == ["core a", "core b", "core c"],
                  f"--with-core adds the safety core to a doc: {got}")
            code, got = listed("--files", "ltcplay/remote.py", "--with-core")
            check(code == 0 and got == ["core a", "core b", "core c",
                                        "other d"],
                  f"--with-core adds the core to a file's own: {got}")
        finally:
            for k, v in saved.items():
                setattr(mutate, k, v)
            sys.argv = old_argv


def test_the_gpl_path_never_loads_the_flame_link():
    section("GPL: the flame link is never imported by the program")
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    top = []
    for name in sorted(os.listdir(os.path.join(here, "ltcplay"))):
        if not name.endswith(".py") or name == "flamelink.py":
            continue
        for i, line in enumerate(open(os.path.join(here, "ltcplay", name),
                                      encoding="utf-8"), 1):
            if re.search(r"\bflamelink\b", line) and \
                    re.match(r"\s*(from|import)\s", line):
                top.append(f"{name}:{i}")
    # The one import allowed (show-assembly, 2026-10-03): fire_ice.py, which
    # is itself loaded only for Fire & Ice (test_the_gpl_path_never_loads_
    # the_conductor), imports it inside build_flame_link() and
    # flame_link_config() only, so even loading fire_ice.py loads no flame
    # link (checked below). Found by the
    # parser (PR #43 review, item 7): an import anywhere else in the file,
    # indented or not, is refused.
    import ast as _ast
    fi_tree = _ast.parse(open(os.path.join(here, "ltcplay", "fire_ice.py"),
                              encoding="utf-8").read())
    inside, allowed = set(), []
    for fn in _ast.walk(fi_tree):
        if isinstance(fn, _ast.FunctionDef) and \
                fn.name in ("build_flame_link", "flame_link_config"):
            inside |= {id(x) for x in _ast.walk(fn)}
    for node in _ast.walk(fi_tree):
        names = []
        if isinstance(node, _ast.Import):
            names = [a.name for a in node.names]
        elif isinstance(node, _ast.ImportFrom):
            names = [node.module or ""] + [a.name for a in node.names]
        if any("flamelink" in (n or "") for n in names) and \
                id(node) not in inside:
            allowed.append(f"fire_ice.py:{node.lineno} (outside "
                           f"build_flame_link and flame_link_config)")
    top = [t for t in top if not t.startswith("fire_ice.py:")] + allowed
    check(not top, f"the flame link is imported by the program: {top}")
    r = _sp.run([sys.executable, "-c",
                 "import sys; sys.path.insert(0, sys.argv[1]); "
                 "import ltcplay.session, ltcplay.web, ltcplay.cli; "
                 "a = 'ltcplay.flamelink' in sys.modules; "
                 "import ltcplay.fire_ice; "
                 "print(a, 'ltcplay.flamelink' in sys.modules)", here],
                capture_output=True, text=True, timeout=60)
    check(r.stdout.strip() == "False False",
          f"loading the program (and even fire_ice.py) loads no flame link: "
          f"{r.stdout!r} {r.stderr[-300:]!r}")
    # At run time (PR #43 review, item 7): a real GPL `ltc serve` answering
    # the page's and the remote's routes loads none of the show-only
    # modules. /api/remote/status used to load the scheduler.
    port = _free_port()
    code = (
        "import sys, json, threading, tempfile, urllib.request, "
        "urllib.error\n"
        f"sys.path.insert(0, {here!r})\n"
        "from ltcplay import web, cli, session\n"
        "d = tempfile.mkdtemp()\n"
        f"h = web.serve(d, port={port})\n"
        "t = threading.Thread(target=h.serve_forever, "
        "kwargs={'poll_interval': 0.05}, daemon=True)\n"
        "t.start()\n"
        "codes = []\n"
        "for r in ('/api/remote/status', '/api/remote/whoami', "
        "'/api/state', '/api/timelines', '/'):\n"
        "    try:\n"
        f"        urllib.request.urlopen('http://127.0.0.1:{port}' + r, "
        "timeout=5)\n"
        "        codes.append(200)\n"
        "    except urllib.error.HTTPError as e:\n"
        "        codes.append(e.code)\n"
        "h.shutdown(); h.server_close()\n"
        "show_only = ('schedule', 'schedule_service', 'conductor', "
        "'fire_ice', 'flamelink', 'devices', 'madmapper', 'beyond', "
        "'streamdeck', 'showaudio')\n"
        "print(json.dumps({'codes': codes, 'loaded': sorted(\n"
        "    m for m in sys.modules if m.startswith('ltcplay.') and\n"
        "    m.split('.')[1] in show_only)}))\n"
        "import shutil; shutil.rmtree(d, ignore_errors=True)\n")
    env = dict(os.environ)
    for k in ("HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy",
              "ALL_PROXY", "all_proxy"):
        env.pop(k, None)
    env["NO_PROXY"] = env["no_proxy"] = "*"
    r = _sp.run([sys.executable, "-c", code], capture_output=True,
                text=True, timeout=60, env=env)
    try:
        out = json.loads(r.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        check(False, f"the GPL run-time check did not run: {r.stderr[-800:]}")
        print("  ok")
        return
    check(out["codes"][0] == 200 and out["codes"][2] == 200,
          f"the GPL serve answered the remote and the page: {out['codes']}")
    check(out["loaded"] == [],
          f"a GPL serve answering the remote's routes loaded show-only "
          f"modules: {out['loaded']}")
    print("  ok")


# -------------------------------------------------- the iPad remote --


class _FakeSock:
    """Drives web.Handler with no socket: the request bytes in, the
    response bytes out. Lets a test ask as any client address, which a
    real socket on a test machine cannot."""

    def __init__(self, raw):
        import io
        self._in = io.BytesIO(raw)
        self.out = b""

    def makefile(self, mode, *a, **k):
        if "r" in mode:
            return self._in
        import io
        sock = self

        class W(io.RawIOBase):
            def writable(self):
                return True

            def write(self, b):
                sock.out += bytes(b)
                return len(b)
        return W()

    def sendall(self, b):
        self.out += bytes(b)

    def settimeout(self, t):
        pass

    def setsockopt(self, *a):
        pass

    def shutdown(self, *a):
        pass

    def close(self):
        pass


def _ask(httpd, method, path, body=None, client=("10.20.0.44", 50000),
         headers=None, host=None, raw_body=None, content_length=None):
    """(status, headers, json or text) for one request as `client`."""
    import json as _j
    from ltcplay import web as web_mod
    port = httpd.server_address[1]
    if host is None:
        host = (f"127.0.0.1:{port}" if client[0] in web_mod.LOOPBACK
                else f"{httpd.bind_address}:{port}")
    data = raw_body if raw_body is not None else (
        _j.dumps(body).encode() if body is not None else b"")
    h = {"Host": host}
    if data or method == "POST":
        h["Content-Type"] = "application/json"
        h["Content-Length"] = str(len(data) if content_length is None
                                  else content_length)
    h.update(headers or {})
    head = f"{method} {path} HTTP/1.1\r\n" + "".join(
        f"{k}: {v}\r\n" for k, v in h.items() if v is not None) + \
        "Connection: close\r\n\r\n"
    sock = _FakeSock(head.encode() + data)
    web_mod.Handler(sock, client, httpd)
    raw = sock.out
    head_b, _, payload = raw.partition(b"\r\n\r\n")
    lines = head_b.decode("latin-1").split("\r\n")
    status = int(lines[0].split()[1]) if lines and lines[0] else 0
    hdrs = {}
    for ln in lines[1:]:
        k, _, v = ln.partition(":")
        hdrs.setdefault(k.strip().lower(), []).append(v.strip())
    try:
        out = _j.loads(payload or b"null")
    except ValueError:
        out = payload.decode("utf-8", "replace")
    return status, hdrs, out


class _RemoteRig:
    """A scheduler with a conductor, a web server built round them, and a
    Remote with a clock and wall the test moves. Nothing here listens on a
    network: requests go through _ask."""

    def __init__(self, S, at=None, conductor=True):
        import tempfile
        from ltcplay import web as web_mod
        from ltcplay import remote as remote_mod
        self.S = S
        self.work = tempfile.mkdtemp()
        self.folder = tempfile.mkdtemp()
        self.now = [at or _den(S, 17, 55)]
        if conductor:
            self.c, self.rig, self.T, self.lines = _cond()
        else:
            self.c = self.rig = None
        self.svc = _svc(S, self.work, self.now, conductor=self.c)
        self.svc.tick()
        self.settle()
        self.httpd = web_mod.serve(self.folder, port=0, bind="127.0.0.1")
        self.httpd.bind_address = "10.20.0.5"     # as if on the show network
        self.httpd.schedule = self.svc
        self.mono = [1000.0]
        self.wall = [1_800_000_000.0]
        self.remote = remote_mod.Remote(
            self.httpd.control, self.svc, folder=self.work,
            clock=lambda: self.mono[0], wall=lambda: self.wall[0],
            log=lambda t: None)
        self.httpd.remote = self.remote

    def settle(self):
        if self.c is not None:
            check(self.svc.flush_conductor(5), "the conductor calls all ran")
            self.c.run_pending()

    def ask(self, method, path, body=None, **kw):
        """As a device on the show network (10.20.0.44) unless `client`
        says otherwise. No sign-in (Jeff, 2026-10-07)."""
        hd = dict(kw.pop("headers", None) or {})
        return _ask(self.httpd, method, path, body, headers=hd, **kw)

    def seen(self):
        return int(self.wall[0] * 1000)

    def lines_for(self, action):
        return [r for r in self.svc.journal if r.get("action") == action]

    def close(self):
        self.httpd.server_close()
        self.remote.close_alerts()
        self.svc.stop()
        # A show selection still being written (off the request) lands
        # before its folder goes.
        self.remote.selection_written(5.0)
        import shutil
        shutil.rmtree(self.work, ignore_errors=True)
        shutil.rmtree(self.folder, ignore_errors=True)


def _stop_hold(R):
    """An operator's Stop, the scheduler's own press, so a Stop's Hold
    stands (the Abort and its latch are removed, Jeff, 2026-10-30)."""
    R.svc.operator_press("stop-show", "Andy", "iPad", confirmed=True)
    R.settle()


def _live_show(R):
    """Show 1 running and confirmed, as tests elsewhere get it."""
    S = R.S
    R.now[0] = _den(S, 18, 0)
    R.svc.tick()
    R.settle()
    R.now[0] = _den(S, 18, 0, 1)
    _confirm(S, R.svc)
    R.settle()
    check(R.svc.machine.state == S.SHOW, "setup: show 1 is running")


def test_remote_no_sign_in_over_the_network():
    section("iPad remote (Jeff, 2026-10-07): no PIN, no sign-in, no operator "
            "names; a device on the show network uses the remote page's own "
            "routes as it is, the journal names the surface by its address, "
            "and the legacy routes and wildcard binds stay refused")
    S = _sched()
    if S is None:
        return
    from ltcplay import remote as RM
    from ltcplay import web as web_mod
    R = _RemoteRig(S)
    try:
        for name in ("PinStore", "Sessions", "Throttle", "PIN_FILE",
                     "COOKIE", "FREE_TRIES", "LOCK_BASE_S", "LOCK_MAX_S"):
            check(not hasattr(RM, name), f"remote.{name} is gone")
        for r in ("login", "logout", "pin", "operator"):
            check(r not in RM.POST_ROUTES, f"no {r} route")
        check(not hasattr(web_mod, "OPEN_POSTS") and
              not hasattr(web_mod.Handler, "_authorised"),
              "web.py has no sign-in gate left")
        for path in ("/api/remote/login", "/api/remote/logout",
                     "/api/remote/pin", "/api/remote/operator"):
            st, _h, out = R.ask("POST", path, {"who": "Andy", "pin": "2468",
                                               "device": "iPad"})
            check(st == 404, f"{path} does not exist: {st} {out}")
        st, _h, out = R.ask("GET", "/remote")
        # Users (2026-10-20): signing in is optional (the header's Sign in
        # and the Users pane); presses need no PIN or picker.
        page = str(out)
        check(st == 200 and "<title>Show remote 2.0</title>" in page and
              "li-pin" not in page and 'id="op-pick"' not in page
              and "/api/remote/login" not in page,
              f"the network gets the remote page, with no sign-in form, PIN "
              f"or operator picker for presses: {st}")
        st, _h, out = R.ask("GET", "/api/remote/whoami")
        check(st == 200 and out == {"local": False,
                                    "device": "iPad at 10.20.0.44",
                                    "screen": "iPad", "fresh_s": RM.FRESH_S},
              f"whoami names the surface by its address: {out}")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200 and "served_at" in out and
              "operators" not in out["schedule"] and
              "current_operator" not in out["schedule"] and
              "signed_in" not in out["arming"],
              f"the status answers with no sign-in, and names nobody: {st}")
        from ltcplay import version as _ver
        check(out.get("version") == _ver.status() and
              ("build" in out["version"] or "release" in out["version"]),
              f"the status names which LTC Player this is (release and "
              f"build id), as version.status() says it: {out.get('version')!r}")
        st, _h, out = R.ask("POST", "/api/remote/hold",
                            {"who": "Andy", "screen": "Rack screen"})
        held = [r for r in R.svc.journal
                if "Hold" in str(r.get("text", ""))]
        check(held and all(r.get("who") == "iPad at 10.20.0.44" and
                           r.get("screen") == "iPad" for r in held),
              f"a Hold from the iPad is journaled as the iPad at its "
              f"address, never as the name the body gave: "
              f"{[(r.get('who'), r.get('screen')) for r in held]}")
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/whoami",
                           client=("127.0.0.1", 5000))
        check(out.get("device") == "Rack screen" and out.get("local"),
              f"the machine itself is the Rack screen: {out}")
        for method, path, body in (
                ("GET", "/api/state", None),
                ("GET", "/api/timelines", None),
                ("GET", "/api/schedule/state", None),
                ("POST", "/api/stop", {}),
                ("POST", "/api/start", {"timeline": "x.json"}),
                ("POST", "/api/schedule/operator", {"who": "Andy"})):
            st, _h, out = R.ask(method, path, body)
            check(st == 403, f"{method} {path} from the network is still "
                             f"refused: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/network",
                            {"address": "10.20.0.9"})
        check(st == 403, f"the show network is set only on the machine "
                         f"itself: {st}")
        check(not os.path.exists(os.path.join(R.work,
                                              "ltcplay_remote_pins.json")),
              "no PIN file is written")
        # Wildcard binds are refused outright.
        for wild in ("0.0.0.0", "::", "", "0", "0.0", "000.000.000.000"):
            try:
                h2 = web_mod.serve(R.folder, port=0, bind=wild)
                h2.server_close()
                check(False, f"serving on {wild} was allowed")
            except ValueError as e:
                check("show Wi-Fi" in str(e), f"{wild} refused: {e}")
    finally:
        R.close()
    print("  ok")


LEGACY_POSTS = (
    ("/api/stop", {}), ("/api/start", {"timeline": "x.json"}),
    ("/api/go", {"at": "00:00:10:00"}), ("/api/skip", {"seconds": 5}),
    ("/api/release", {}), ("/api/input", {"device": "", "channel": 1}),
    ("/api/showdir", {"timeline": "x.json", "folder": "/tmp"}),
    ("/api/reinput", {}), ("/api/trigger", {"on": True}),
    ("/api/reload", {}), ("/api/override", {"look": "blackout"}),
    ("/api/autoreload", {"on": True}), ("/api/check", {"timeline": "x"}),
    ("/api/find", {"seconds": 0.1}),
    ("/api/schedule/operator", {"who": "Jeff", "screen": "iPad"}),
    ("/api/schedule/deck-event", {"text": "front row arm pressed by Jeff",
                                  "who": "Jeff", "action": "arm"}),
    ("/api/schedule/tonight", {"op": "remove", "show": 5, "who": "Jeff",
                               "screen": "iPad"}),
    ("/api/schedule/incident", {"who": "Jeff", "screen": "iPad"}),
    ("/api/announce/play", {"id": 1}))
LEGACY_GETS = ("/api/state", "/api/devices", "/api/timelines", "/api/log",
               "/api/schedule", "/api/schedule/state",
               "/api/schedule/operator", "/api/schedule/journal",
               "/api/announce")


def test_remote_network_session_reaches_only_remote_routes():
    section("iPad remote, fix round 1 F1: a device on the network "
            "reaches the remote page's own routes and nothing else; every "
            "legacy and scheduler route is refused from the network, and "
            "the Stream Deck's journal route answers only the machine")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        op0 = R.svc.current_operator
        n0 = len(R.svc.journal)
        for path, body in LEGACY_POSTS:
            st, _h, out = R.ask("POST", path, dict(body, seen=R.seen()))
            check(st == 403, f"POST {path} from the iPad is refused: "
                             f"{st} {out}")
        for path in LEGACY_GETS:
            st, _h, out = R.ask("GET", path)
            check(st == 403, f"GET {path} from the iPad is refused: "
                             f"{st}")
        check(R.svc.current_operator == op0,
              f"the operator was not changed from the network: "
              f"{R.svc.current_operator}")
        new = list(R.svc.journal)[n0:]
        check(not any("arm pressed" in r.get("text", "") for r in new) and
              not any(r.get("action") in ("operator", "deck", "arm")
                      for r in new),
              f"no forged deck line or operator change was journaled: "
              f"{[r.get('text') for r in new][:3]}")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200, "the remote page's own status still answers")
        st, _h, out = R.ask("GET", "/")
        check(st == 200 and "<title>Show remote 2.0</title>" in str(out),
              "and the remote page itself (2.0, the default)")
        st, _h, out = R.ask("GET", "/brand/logo_small.png")
        check(st in (200, 404), f"and the logo route: {st}")
        # The machine itself keeps every route, the deck's journal too.
        st, _h, out = _ask(R.httpd, "POST", "/api/schedule/deck-event",
                           {"text": "front row disarm pressed by Andy",
                            "who": "Andy", "action": "disarm"}, client=loop)
        check(st == 200, f"the Stream Deck on this machine still posts its "
                         f"lines: {st} {out}")
        st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop)
        check(st == 200, "and the machine still reads /api/state")
        from ltcplay import web as web_mod
        check(not web_mod.network_may_reach("/api/schedule/deck-event") and
              not web_mod.network_may_reach("/api/stop") and
              web_mod.network_may_reach("/api/remote/hold"),
              "network_may_reach is the remote routes, the page and the logo")
    finally:
        R.close()
    print("  ok")


def test_web_page_icons():
    section("web page icons (Jeff, 2026-10-24): every page the engine "
            "serves names the LTC Player icon, the manifest and the iPad's "
            "home screen icon; the engine serves them itself, with the "
            "right types and a long cache, to the network without sign-in, "
            "and opening them widens nothing else")
    import struct
    import tempfile
    import threading
    import urllib.request
    from ltcplay import web as web_mod
    folder = tempfile.mkdtemp()
    httpd = web_mod.serve(folder, port=0, bind="127.0.0.1")
    t = threading.Thread(target=httpd.serve_forever,
                         kwargs={"poll_interval": 0.05}, daemon=True)
    t.start()
    base = f"http://127.0.0.1:{httpd.server_address[1]}"

    def fetch(path):
        try:
            with urllib.request.urlopen(base + path, timeout=5) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    want = {"/favicon.ico": "image/x-icon",
            "/apple-touch-icon.png": "image/png",
            "/apple-touch-icon-precomposed.png": "image/png",
            "/icon-192.png": "image/png", "/icon-512.png": "image/png",
            "/manifest.webmanifest": "application/manifest+json"}
    got = {}
    try:
        for path, kind in want.items():
            st, h, body = fetch(path)
            got[path] = body
            check(st == 200, f"GET {path} answers: {st}")
            check((h.get("Content-Type") or "") == kind,
                  f"{path} is {kind}: {h.get('Content-Type')}")
            check(len(body) > 0, f"{path} is not empty")
            cc = h.get("Cache-Control") or ""
            m = re.search(r"max-age=(\d+)", cc)
            check("no-store" not in cc and m and int(m.group(1)) >= 86400,
                  f"{path} may be kept by the browser: {cc!r}")
        ico = got.get("/favicon.ico", b"")
        n = struct.unpack("<HHH", ico[:6])[2] if len(ico) >= 6 else 0
        sizes = sorted((ico[6 + 16 * i] or 256)
                       for i in range(n) if len(ico) >= 22 + 16 * i)
        check(ico[:4] == b"\0\0\1\0" and sizes == [16, 32, 48],
              f"favicon.ico holds 16, 32 and 48 px: {sizes}")
        for path, px in (("/apple-touch-icon.png", 180),
                         ("/icon-192.png", 192), ("/icon-512.png", 512)):
            b = got.get(path, b"")
            w, hh = struct.unpack(">II", b[16:24]) if len(b) >= 24 else (0, 0)
            check(b[:8] == b"\x89PNG\r\n\x1a\n" and (w, hh) == (px, px),
                  f"{path} is a {px} px PNG: {(w, hh)}")
        try:
            man = json.loads(got.get("/manifest.webmanifest") or b"{}")
        except ValueError:
            man = {}
        check(man.get("name") == "LTC Player" and
              man.get("short_name") == "LTC Player" and
              man.get("display") == "standalone" and
              man.get("theme_color") == man.get("background_color") ==
              "#070605", f"the manifest names LTC Player in the pages' "
                         f"colours: {man}")
        for icon in man.get("icons") or [{}]:
            st, _h, _b = fetch(icon.get("src") or "/missing")
            check(st == 200, f"the manifest's icon {icon} is served: {st}")
        # Every HTML page the engine serves: the operator page on "/", the
        # rack screen and iPad remote on "/remote" (the Startup page and
        # the rest are views of it).
        for path in ("/", "/remote", "/remote2"):
            st, h, body = fetch(path)
            page = body.decode("utf-8", "replace")
            head = page.split("</head>")[0]
            check(st == 200 and "text/html" in (h.get("Content-Type") or ""),
                  f"{path} is a page: {st}")
            for tag in ('<link rel="icon" href="/favicon.ico"',
                        '<link rel="apple-touch-icon" '
                        'href="/apple-touch-icon.png"',
                        '<link rel="manifest" href="/manifest.webmanifest"'):
                check(tag in head, f"{path} names its icon in <head>: {tag}")
            for href in re.findall(r'<link rel="(?:icon|apple-touch-icon|'
                                   r'manifest)"[^>]*href="([^"]+)"', head):
                st, _h, b = fetch(href)
                check(st == 200 and b, f"{path} links {href}, which is "
                                       f"served: {st}")
            check(re.search(r"<title>[^<]+</title>", head),
                  f"{path} has a title")
        # Only the fixed list: no folder of files opened up.
        for path in ("/icons/favicon.ico", "/favicon.svg",
                     "/favicon.ico/x", "/icon-1024.png"):
            st, _h, _b = fetch(path)
            check(st == 404, f"GET {path} is not an icon: {st}")
    finally:
        httpd.shutdown()
        httpd.server_close()
        import shutil
        shutil.rmtree(folder, ignore_errors=True)
    # From the show network, signed out: the icons answer (an iPad adds the
    # home screen icon before anyone signs in); nothing else was opened.
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        for path, kind in want.items():
            st, h, _out = R.ask("GET", path)
            check(st == 200 and h.get("content-type") == [kind] and
                  int((h.get("content-length") or ["0"])[0]) > 0,
                  f"the iPad, signed out, gets {path}: {st} {h}")
        for path in ("/api/state", "/icons/favicon.ico", "/favicon.svg"):
            st, _h, _out = R.ask("GET", path)
            check(st in (403, 404), f"and not {path} from the network: {st}")
        check(all(web_mod.network_may_reach(p) for p in want) and
              not web_mod.network_may_reach("/favicon.ico/x") and
              not web_mod.network_may_reach("/api/stop"),
              "network_may_reach gained the icon addresses and nothing else")
    finally:
        R.close()
    print("  ok")


def test_remote_countdown_left_in_this_show():
    section("rack screen countdown (Jeff, 2026-10-07): during a running show "
            "the time left in THIS show from the engine's own show clock; "
            "held, it stays still; between shows the countdown to the next; "
            "a show of unknown length shows none")
    from ltcplay import remote as RM
    cv = RM.countdown_view
    run = {"attached": True, "state": "SHOW",
           "next": {"show": 2, "start": "19:00", "in_s": 3600}}
    c = cv(run, {"running": True}, {"duration": 440.0, "elapsed": 100.25})
    check(c == {"kind": "left", "label": "Left in this show", "s": 339.8,
                "running": True},
          f"running: length minus the show clock's place, not the next "
          f"show: {c}")
    c = cv(dict(run, state="PAUSED"), {"running": True},
           {"duration": 440.0, "elapsed": 100.25})
    check(c and c["kind"] == "left" and c["s"] == 339.8 and
          c["running"] is False,
          f"held: the same time left, marked not running so the page does "
          f"not age it: {c}")
    c = cv(dict(run, state="WAITING"), {"running": False}, None)
    check(c == {"kind": "next", "label": "Next show", "s": 3600,
                "running": True},
          f"between shows: the countdown to the next show: {c}")
    for now in (None, {}, {"duration": None, "elapsed": 3.0},
                {"duration": 0, "elapsed": 1.0},
                {"duration": float("nan"), "elapsed": 1.0},
                {"duration": True, "elapsed": 1.0},
                {"duration": 300.0}):
        check(cv(run, {"running": True}, now) is None,
              f"a show of unknown length shows no countdown at all, never "
              f"the next show's: {now}")
    c = cv(run, {"running": True}, {"duration": 300.0, "elapsed": 320.0})
    check(c["s"] == 0.0, "past its end: zero, never negative")
    # Soak 2026-10-21: the page counted down from whole seconds rounded
    # down, so its last digit flickered. The exact figure goes out when
    # the engine has one.
    c = cv(dict(run, state="WAITING",
                next={"show": 2, "start": "19:00", "in_s": 3599,
                      "in_s_exact": 3599.437}), {"running": False}, None)
    check(c == {"kind": "next", "label": "Next show", "s": 3599.437,
                "running": True},
          f"between shows: the exact time to the next show, not whole "
          f"seconds: {c}")
    S0 = _sched()
    if S0 is not None:
        n0 = _Night(S0, _one_night_rule(S0))
        n0.boot(_den(S0, 17, 0))
        v0 = S0.machine_view(n0.m, _den(S0, 17, 59, 57, 600000))
        check(v0["next"]["in_s"] == 2 and
              v0["next"]["in_s_exact"] == 2.4,
              f"the scheduler gives the next show to the millisecond as "
              f"well as in whole seconds: {v0['next']}")
    check(cv({"attached": True, "state": "WAITING", "next": None},
             {}, None) is None, "nothing next: nothing shown")
    c = cv({"attached": False}, {"running": True},
           {"duration": 60.0, "elapsed": 10.0})
    check(c and c["kind"] == "left" and c["s"] == 50.0,
          "with no scheduler, a playing show still shows its time left")
    # Through the real status route: the engine's own snapshot.
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        _live_show(R)
        real = R.httpd.control.state
        R.httpd.control.state = lambda: {"running": True, "show": "x",
                                         "now": {"duration": 444.0,
                                                 "elapsed": 44.0}}
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200 and out["countdown"] == {
            "kind": "left", "label": "Left in this show", "s": 400.0,
            "running": True}, f"the status carries it: {out.get('countdown')}")
        R.svc.operator_press("hold", "Jeff", "Rack screen")
        R.settle()
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["countdown"]["running"] is False and
              out["countdown"]["s"] == 400.0,
              f"held: frozen: {out['countdown']}")
        names = [x["name"] for x in out.get("subsystems", [])]
        check(names == ["Deck", "Flamesafe", "Show audio", "Video",
                        "Lasers", "Pixels"] and all(x["state"] in
                                          ("ok", "warn", "bad", "off")
                                          for x in out["subsystems"]),
              f"the compact status strip names each subsystem: "
              f"{out.get('subsystems')}")
        check(out["subsystems"][0]["state"] == "off",
              "the deck has not asked yet: off")
        R.remote.deck_input("hw=1&arm_ms=10")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["subsystems"][0]["state"] == "ok",
              "the deck asked, its USB deck here and its arm link fresh: ok")
        R.mono[0] += 5
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["subsystems"][0]["state"] == "bad",
              "the deck quiet for 5 s: bad")
        R.httpd.control.state = real
    finally:
        R.close()
    print("  ok")


def test_remote_cross_site_posts_refused_on_loopback():
    section("iPad remote, fix round 1 F2: on the show machine itself, a "
            "press from a sandboxed or data: page (Origin null), from "
            "another site, or not sent as JSON is refused")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        state0 = R.svc.machine.state
        cases = [("Origin null", {"Origin": "null"}, None),
                 ("Origin NULL", {"Origin": "NULL"}, None),
                 ("another site", {"Origin": "http://evil.example"}, None),
                 ("Sec-Fetch-Site cross-site",
                  {"Sec-Fetch-Site": "cross-site"}, None),
                 ("Sec-Fetch-Site same-site",
                  {"Sec-Fetch-Site": "same-site"}, None),
                 ("text/plain", {"Content-Type": "text/plain"}, None),
                 ("form", {"Content-Type":
                           "application/x-www-form-urlencoded"}, None),
                 ("no content type", {"Content-Type": None}, None)]
        for path, body in (("/api/stop", {}),
                           ("/api/remote/network",
                            {"address": "198.51.100.7"}),
                           ("/api/remote/start-now",
                            {"confirmed": True, "seen": R.seen(),
                             "who": "Andy", "screen": "Rack screen"}),
                           ("/api/schedule/deck-event", {"text": "x"})):
            for label, hd, _x in cases:
                st, _h, out = _ask(R.httpd, "POST", path, body,
                                   client=loop, headers=hd)
                check(st == 403, f"{path} with {label} from loopback is "
                                 f"refused: {st} {out}")
        # With no sign-in (Jeff, 2026-10-07) these walls are what keep
        # another site's page off the controls from the show network too.
        for path, body in (("/api/remote/start-now",
                            {"confirmed": True, "seen": R.seen()}),
                           ("/api/remote/arm-hold",
                            {"group": 0, "seen": R.seen()}),
                           ("/api/remote/stop", {})):
            for label, hd, _x in cases:
                st, _h, out = R.ask("POST", path, body, headers=hd)
                check(st == 403, f"{path} with {label} from the network is "
                                 f"refused: {st} {out}")
        check(not R.lines_for("stop") and not R.lines_for("arm hold"),
              "no Stop or arm hold reached the remote")
        from ltcplay import remote as RM
        check(RM.load_settings(R.work)["show_network_address"] is None,
              "no show network address was planted")
        check(R.svc.machine.state == state0, "nothing was started")
        # The page's own presses still work: same origin, JSON.
        port = R.httpd.server_address[1]
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/network",
                           {"address": "10.20.0.5"}, client=loop,
                           headers={"Origin": f"http://127.0.0.1:{port}",
                                    "Sec-Fetch-Site": "same-origin"})
        check(st == 200, f"a same-origin JSON press from the page is "
                         f"taken: {st} {out}")
        page = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "ltcplay", "web", "index.html"),
                    encoding="utf-8").read()
        check('headers:{"Content-Type":"application/json"}' in page,
              "the operator page sends its presses as JSON")
    finally:
        R.close()
    print("  ok")


def test_remote_localhost_unaffected_and_proxies_refused():
    section("iPad remote: the machine itself is the Rack screen; "
            "anything that looks proxied, misaddressed or cross-site is "
            "refused, loopback included")
    S = _sched()
    if S is None:
        return
    import urllib.request
    import urllib.error
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop)
        check(st == 200, f"loopback reads the state with no session: {st}")
        st, _h, out = _ask(R.httpd, "GET", "/", client=loop)
        check(st == 200 and "<title>Show remote</title>" not in str(out),
              "loopback still gets the operator page at /")
        st, _h, out = _ask(R.httpd, "GET", "/remote", client=loop)
        check(st == 200 and "<title>Show remote 2.0</title>" in str(out),
              "and the remote page (2.0, the default) at /remote")
        st, h, out = _ask(R.httpd, "GET", "/remote1", client=loop)
        check(st == 302 and h.get("location") == ["/remote"],
              f"and the first screen's /remote1 sends it to /remote: {st} "
              f"{h}")
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/whoami", client=loop)
        check(out["local"] is True and out["device"] == "Rack screen",
              f"whoami says it is the machine itself: {out}")
        # The real thing, over a real loopback socket.
        import threading
        from ltcplay import web as web_mod
        h2 = web_mod.serve(R.folder, port=0, bind="127.0.0.1")
        t = threading.Thread(target=h2.serve_forever,
                             kwargs={"poll_interval": 0.05}, daemon=True)
        t.start()
        try:
            base = f"http://127.0.0.1:{h2.server_address[1]}"
            with urllib.request.urlopen(base + "/api/state", timeout=5) as r:
                check(r.status == 200, "a real loopback request needs no PIN")
            req = urllib.request.Request(base + "/api/state", headers={
                "X-Forwarded-For": "203.0.113.9"})
            try:
                urllib.request.urlopen(req, timeout=5)
                check(False, "a forwarded request from loopback was let in")
            except urllib.error.HTTPError as e:
                check(e.code == 403, f"forwarded is refused: {e.code}")
        finally:
            h2.shutdown()
            h2.server_close()
        for hname, val in (("X-Forwarded-For", "203.0.113.9"),
                           ("Forwarded", "for=203.0.113.9"),
                           ("Via", "1.1 tunnel"),
                           ("X-Real-IP", "203.0.113.9"),
                           ("CF-Connecting-IP", "203.0.113.9")):
            st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop,
                               headers={hname: val})
            check(st == 403 and "proxy" in out["error"],
                  f"{hname} from loopback is refused: {st}")
        st, _h, _o = R.ask("GET", "/api/state",
                           headers={"X-Forwarded-For": "10.0.0.1"})
        check(st == 403, "and from a device on the network too")
        st, _h, _o = R.ask("GET", "/api/state", host="evil.example:7878")
        check(st == 403, f"a Host that is not this server is refused: {st}")
        st, _h, _o = _ask(R.httpd, "GET", "/api/state", client=loop,
                          host="evil.example")
        check(st == 403, "on loopback too (DNS rebinding)")
        st, _h, _o = R.ask("POST", "/api/remote/hold",
                           {"seen": R.seen()},
                           headers={"Origin": "http://evil.example"})
        check(st == 403, f"a press posted from another site is refused: {st}")
        check(not R.lines_for("HOLD"), "and nothing was held")
    finally:
        R.close()
    print("  ok")


# ---------------------------------------------------------------------------
# Remote access over Tailscale (Jeff, 2026-11-12): off by default; on, a
# second door on this PC's own Tailscale address (100.64.0.0/10 only), with
# less authority than an iPad.
# ---------------------------------------------------------------------------

_TS_ADDR = "100.101.102.103"
_TS_PEER = ("100.88.1.2", 50000)


_TS_LOGIN = "andy@example.com"


def _ts_door(R, addr=_TS_ADDR, login=_TS_LOGIN):
    """A Tailscale door beside the rig's show network door, as web.serve
    makes it, on loopback (this machine has no Tailscale address); requests
    go through _ask, which names it by `addr` and its real port."""
    import http.server
    from ltcplay import web as web_mod
    d = http.server.ThreadingHTTPServer(("127.0.0.1", 0), web_mod.Handler)
    d.control, d.token, d.bind_address = R.httpd.control, None, addr
    d.tailscale_door = True
    d.daemon_threads = True
    d.schedule, d.remote = R.httpd.schedule, R.httpd.remote
    d.fire_ice_config = None
    # Who is who on the tailnet: the allow list and a stand-in for this PC's
    # own `tailscale whois` (test_tailscale_allow_list tests both).
    if login:
        from ltcplay import remote as RM
        RM.save_settings(R.work, tailscale_logins=[login])
        R.remote._tailscale_whois = lambda ip, _l=login: _l
        R.remote._ts_logins_cache = None
        R.remote._ts_whois_cache = {}
    return d


class _TsRun:
    """A stand-in for subprocess.run answering `tailscale ip -4`."""

    def __init__(self, out="", rc=0, boom=False):
        self.out, self.rc, self.boom, self.calls = out, rc, boom, []

    def __call__(self, cmd, **kw):
        self.calls.append(cmd)
        if self.boom:
            raise OSError("no such program")

        class P:
            pass
        p = P()
        p.returncode, p.stdout, p.stderr = self.rc, self.out, ""
        return p


class _TsRunBy:
    """subprocess.run for Tailscale's program, answering by its command:
    {"ip": stdout, "status": stdout, "whois": stdout}."""

    def __init__(self, answers):
        self.answers, self.calls = answers, []

    def __call__(self, cmd, **kw):
        self.calls.append(cmd)
        out = self.answers.get(cmd[1])

        class P:
            pass
        p = P()
        p.returncode, p.stdout, p.stderr = (1, "", "") if out is None \
            else (0, out, "")
        return p


