def test_windows_supervisor_sets_madmapper_back_to_normal():
    section("Windows app: the supervisor sets MadMapper back to Normal "
            "priority whenever it is found at High or above, after every "
            "MadMapper restart too; never the engine, deck or flamesafe; a "
            "refusal is said once and never raised; \"leave\" turns it off")
    W, SUP, gone = _winpkg()
    HIGH, REALTIME, NORMAL, BELOW = 0x80, 0x100, 0x20, 0x4000
    try:
        table = {10: "MadMapper.exe", 20: "ltcplay.exe",
                 21: "ltcplay-deck.exe", 22: "flamesafe.exe",
                 30: "BEYOND.exe"}
        pri = {10: HIGH, 20: HIGH, 21: 0x8000, 22: HIGH, 30: HIGH}
        sets, lines, deny = [], [], set()

        class Win:
            def priority(self, pid):
                return pri.get(pid)

            def set_priority(self, pid, cls):
                sets.append((pid, cls))
                if pid in deny:
                    return "Windows refused (error 5)"
                pri[pid] = cls
                return ""
        m = SUP.MadMapperPriority(log=lines.append, procs=lambda: table,
                                  win=Win())
        m.tick()
        check(sets == [(10, NORMAL)] and pri[10] == NORMAL,
              f"MadMapper at High is set to Normal, nothing else is "
              f"touched: {sets}")
        check(len(lines) == 1 and "pid 10" in lines[0]
              and "High" in lines[0] and "Normal" in lines[0],
              f"one note line says so: {lines}")
        m.tick()
        check(len(sets) == 1 and len(lines) == 1,
              "at Normal it is left alone, with no more lines")
        pri[10] = BELOW
        m.tick()
        check(len(sets) == 1, "Below normal (containment) is left alone")
        # MadMapper restarted: a new process, back at High by its own
        # preference.
        del table[10]
        table[11] = "MadMapper.exe"
        pri[11] = REALTIME
        m.tick()
        check(sets[-1] == (11, NORMAL) and len(lines) == 2
              and "Realtime" in lines[-1],
              f"the restarted MadMapper is set to Normal again: {sets} "
              f"{lines}")
        # Access denied: said once, never raised, tried again quietly.
        table[12] = "MadMapperDemo.exe"
        pri[12] = HIGH
        deny.add(12)
        m.tick()
        m.tick()
        refused = [x for x in lines if "could not be set" in x]
        check(len(refused) == 1 and "error 5" in refused[0],
              f"a refusal is one note: {lines}")
        check(all("—" not in x and "–" not in x for x in lines),
              "no dashes in the notes")
        check(all(p not in (20, 21, 22, 30) for p, _c in sets),
              f"the engine, the deck, flamesafe and BEYOND are never "
              f"touched: {sets}")
        deny.clear()
        m.tick()
        check(pri[12] == NORMAL, "once Windows allows it, it is set")
        # The showpc.json key.
        check(SUP.start_madmapper_priority(
            {"madmapper_priority": "leave"}) is None,
            "\"leave\" turns it off")
        check(isinstance(SUP.start_madmapper_priority({}),
                         SUP.MadMapperPriority),
              "it is on by default")
    finally:
        if SUP._LOG is not None:
            SUP._LOG.close()
            SUP._LOG = None
        gone()
    print("  ok")

def test_windows_supervisor_never_passes_bench_hooks():
    section("Windows app: the supervisor passes no bench test hook "
            "(LTCPLAY_BENCH_*, LTC_TRACEMALLOC) to the engine, the deck or "
            "flamesafe, whatever is left in its own environment (safety "
            "audit of bench-build, P1)")
    import tempfile
    W, SUP, gone = _winpkg()
    work = tempfile.mkdtemp()
    old_local = os.environ.get("LOCALAPPDATA")
    real_popen = SUP.subprocess.Popen
    hooks = {"LTCPLAY_BENCH_FAKE_AUDIO": "Focusrite USB ASIO",
             "LTCPLAY_BENCH_VIRTUAL_DECK": "1",
             "LTCPLAY_BENCH_STALLS": os.path.join(work, "s.json"),
             "LTCPLAY_BENCH_SENDGAPS": os.path.join(work, "g.json"),
             "LTCPLAY_BENCH_SOAK": str(os.getpid()),
             "LTC_TRACEMALLOC": "1"}
    try:
        os.environ["LOCALAPPDATA"] = work
        os.environ.update(hooks)
        settings = {"show_folder": os.path.join(work, "shows"),
                    "flamesafe_config": "", "port": 7878,
                    "run_flamesafe": True, "run_deck": True,
                    "show_mode": "fire_ice",
                    "schedule": os.path.join(work, "s.json")}
        want = SUP.wanted_args(settings)
        seen = []

        class FakeProc:
            pid = 4243

            def __init__(self, cmd, **kw):
                seen.append(kw.get("env") or {})

            def poll(self):
                return None
        SUP.subprocess.Popen = FakeProc
        for name in SUP.PROGRAMS:
            p = SUP.Program(name)
            p.start(want[name][0] or [], settings)
            p.out.close()
        check(len(seen) == len(SUP.PROGRAMS), f"every program started: "
                                              f"{len(seen)}")
        for env in seen:
            left = sorted(k for k in env if k.upper() in hooks)
            check(not left, f"no bench hook reaches a show program: {left}")
            check(env.get("LOCALAPPDATA") == work,
                  "the rest of the environment is still passed on")
        check(W.without_bench_hooks({"ltcplay_bench_x": "1", "PATH": "p"})
              == {"PATH": "p"}, "names are matched in any case, as on "
                                "Windows")
        soak = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "packaging", "windows", "soak.py"),
                    encoding="utf-8").read()
        check('env["LTCPLAY_BENCH_SOAK"] = str(os.getpid())' in soak,
              "the soak still marks the programs it starts as its own")
    finally:
        SUP.subprocess.Popen = real_popen
        for k in hooks:
            os.environ.pop(k, None)
        if old_local is None:
            os.environ.pop("LOCALAPPDATA", None)
        else:
            os.environ["LOCALAPPDATA"] = old_local
        if SUP._LOG is not None:
            SUP._LOG.close()
            SUP._LOG = None
        gone()
    print("  ok")


def test_engine_refuses_run_with_a_bench_hook_outside_the_soak():
    section("engine: Run is refused, naming the hook, while a bench test "
            "hook is set and the soak did not start this engine (safety "
            "audit of bench-build, P1)")
    import tempfile
    from ltcplay import benchhooks as B
    from ltcplay import web as web_mod
    from ltcplay.session import SessionError
    me = os.getppid()
    check(B.run_refusal({}, me) is None, "no hook: Run goes ahead")
    check(B.run_refusal({"LTC_TRACEMALLOC": "0", "PATH": "x"}, me) is None,
          "a hook set to 0 is off")
    for name in ("LTCPLAY_BENCH_FAKE_AUDIO", "LTCPLAY_BENCH_VIRTUAL_DECK",
                 "LTCPLAY_BENCH_STALLS", "LTCPLAY_BENCH_SENDGAPS",
                 "LTC_TRACEMALLOC", "LTCPLAY_BENCH_SOMETHING_NEW"):
        why = B.run_refusal({name: "1"}, me)
        check(why and name in why and "Show control on refused" in why
              and "—" not in why and "–" not in why,
              f"{name} refuses Run in a sentence naming it, no dashes: "
              f"{why}")
        check(B.run_refusal({name: "1", B.SOAK_ENV: str(me + 1)}, me),
              f"{name} with a soak mark naming another process (one left "
              f"in the environment) still refuses Run")
        check(B.run_refusal({name: "1", B.SOAK_ENV: str(me)}, me) is None,
              f"{name} set by the soak that started this engine: Run goes "
              f"ahead")
    check(B.run_refusal({B.SOAK_ENV: "123"}, me) is None,
          "the soak's mark alone is not a hook")
    c = web_mod.Control(tempfile.mkdtemp(), sd=FakeSD())
    saved = {k: os.environ.pop(k) for k in list(os.environ)
             if B.is_hook(k)}
    try:
        os.environ["LTCPLAY_BENCH_FAKE_AUDIO"] = "Focusrite USB ASIO"
        try:
            c.start("show.json")
            check(False, "Run went ahead with a fake audio device set")
        except SessionError as e:
            check("LTCPLAY_BENCH_FAKE_AUDIO" in str(e)
                  and "silent" in str(e),
                  f"the rack screen's Run is refused, saying why: {e}")
        os.environ.pop("LTCPLAY_BENCH_FAKE_AUDIO")
        try:
            c.start("show.json")
        except SessionError as e:
            check("Show control on refused" not in str(e),
                  f"with no hook set, Run is not refused for one: {e}")
    finally:
        os.environ.pop("LTCPLAY_BENCH_FAKE_AUDIO", None)
        os.environ.update(saved)
    print("  ok")


def test_fire_ice_no_mirror_no_fault_on_every_stop():
    section("flame link: with no status mirror in flamesafe's config an "
            "Abort raises no disarm fault (it cannot be confirmed here), "
            "one note says so when the link starts; with a mirror an "
            "unconfirmed disarm is still a fault (safety audit of "
            "bench-build, P2 a)")
    import tempfile
    from ltcplay import web as web_mod
    from ltcplay import schedule_service as SV
    F = _fi_mod()
    work = tempfile.mkdtemp()
    fs, show, doc = _fi_flame_files(work)
    rule = os.path.join(work, SV.RULE_FILE)
    SV.save_rule(rule, _sched_doc())
    svc = SV.Service(rule, state_dir=work, ntp_query=lambda: 0.0)
    cfg = F.FireIceConfig(flamesafe_config=fs, flame_controller="Flames")
    httpd = web_mod.serve(work, port=_free_port(), schedule=svc,
                          fire_ice=cfg, flamesafe_config=fs)
    try:
        link = httpd.fire_ice.flame_link
        check(link is not None
              and getattr(link, "status_mirrored", None) is False,
              "no status_mirror_port: the link knows it")

        def outcomes(o):
            return [r for r in svc.journal if r.get("outcome") == o]
        for _ in range(3):
            httpd.remote.disarm_all("Andy", "rack screen")
            time.sleep(fl_confirm_s() + 0.4)
        time.sleep(0.3)
        check(not outcomes("disarm_unconfirmed"),
              f"three Aborts with no mirror: no disarm fault: "
              f"{outcomes('disarm_unconfirmed')}")
        check(len(outcomes("no_status")) == 1,
              f"one note when the link started: {outcomes('no_status')}")
        link.status_mirrored = True
        httpd.remote.disarm_all("Andy", "rack screen")
        deadline = time.time() + fl_confirm_s() + 3
        while time.time() < deadline and not outcomes("disarm_unconfirmed"):
            time.sleep(0.05)
        check(outcomes("disarm_unconfirmed"),
              "with a mirror, a disarm flamesafe never confirms is still a "
              "fault")
        httpd.control.session = None
    finally:
        svc.halt()
        svc.stop()
        httpd.server_close()
    print("  ok")


def fl_confirm_s():
    from ltcplay import flamelink as fl
    return fl.CONFIRM_S


def test_remote_stale_state_refused_and_banner():
    section("iPad remote: presses that act on what the page shows are refused "
            "on a status older than 2 s; the page shows a banner and turns "
            "those controls off; Stop, Hold and disarm never wait on it")
    S = _sched()
    if S is None:
        return
    from ltcplay import remote as RM
    R = _RemoteRig(S)
    try:
        _live_show(R)
        check(RM.FRESH_S == 2.0, "fresh means 2 s")
        st, _h, out = R.ask("POST", "/api/remote/hold", {"seen": 1})
        R.settle()
        check(st == 200 and R.svc.machine.state == S.PAUSED,
              "Hold goes with a stale page")
        old = R.seen() - 2500
        st, _h, out = R.ask("POST", "/api/remote/resume", {"seen": old})
        R.settle()
        check(st == 409 and out.get("stale") and
              R.svc.machine.state == S.PAUSED,
              f"Resume on a 2.5 s old status is refused: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/resume", {})
        check(st == 409 and R.svc.machine.state == S.PAUSED,
              "and with no status at all")
        st, _h, out = R.ask("POST", "/api/remote/resume",
                            {"seen": R.seen() - 1500})
        R.settle()
        check(st == 200 and R.svc.machine.state == S.SHOW,
              f"on a 1.5 s old status it goes: {st} {out}")
        for route, extra in (("start-now", {"confirmed": True}),
                             ("jump", {"seconds": 5}),
                             ("play-from", {"at": "00:00:10:00"})):
            body = dict(extra, seen=old)
            st, _h, out = R.ask("POST", "/api/remote/" + route, body)
            check(st == 409 and out.get("stale"),
                  f"{route} on a stale status is refused: {st} {out}")
        check(any(r.get("outcome") == "refused" and "s old" in r["text"]
                  for r in R.svc.journal), "stale refusals are journaled")
        st, _h, out = R.ask("POST", "/api/remote/stop", {"seen": 1})
        R.settle()
        check(st == 200 and R.c.snapshot()["look"] == "STOPPED_DARK",
              f"Stop goes with a stale page: {st} {out} {R.c.snapshot()}")
        # The status reports whether flamesafe's lamps are live.
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["flames"]["connected"] is False and out["flames"]["stale"],
              "with no flamesafe status the lamps say so")
        fs = RM.FlameStatus("127.0.0.1", 0, "k" * 20, ["front row"],
                            clock=lambda: R.mono[0])
        R.remote.flame_status = fs
        import json as _j
        frame = {"t": "status", "k": "k" * 20, "fault": "", "groups": [
            {"name": "front row", "armed": "armed", "wanted": True,
             "reason": ""}]}
        fs.note(_j.dumps(frame).encode())
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(not out["flames"]["stale"] and
              out["flames"]["groups"][0]["armed"] == "armed",
              f"a fresh frame shows the real armed state: {out['flames']}")
        check(out["flames"]["confirmed"] is True,
              f"a frame with no `confirmed` reads confirmed: {out['flames']}")
        fs.note(_j.dumps(dict(frame, confirmed=False)).encode())
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["flames"]["confirmed"] is False and
              out["flames"]["groups"][0]["armed"] == "armed",
              f"flamesafe's confirmed false reaches the status beside the "
              f"real state, for the Info popup (2026-10-19): {out['flames']}")
        fs.note(_j.dumps(dict(frame, k="x" * 20)).encode())
        R.mono[0] += 1.2
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["flames"]["stale"] and
              out["flames"]["groups"][0]["armed"] == "unknown" and
              out["flames"]["confirmed"] is None,
              f"1.2 s later (and a wrongly keyed frame ignored) the lamp is "
              f"unknown, never the old armed, and confirmed is not claimed "
              f"either way: {out['flames']}")
        _remote_page_logic_in_node()
    finally:
        R.close()
    print("  ok")


def _remote_page_logic_in_node():
    """The page's own stale and control logic, run in node when this
    machine has it (CI does). The functions are cut out of the rules
    (remote_rules.js) between their LOGIC markers, so this tests the
    page's real code."""
    import shutil
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    page = screen_text()
    a = page.find("// LOGIC BEGIN")
    b = page.find("// LOGIC END")
    check(a != -1 and b > a, "the page's logic block is marked")
    logic = page[a:b]
    node = shutil.which("node")
    if not node:
        # On CI the page's logic MUST run: a runner without node would pass
        # this check by reading only, and nothing would say so (second
        # review of PR #68, P3-3). A Mac without node is told, not failed.
        check(not IN_CI, "node is missing on this CI runner, so the page's "
                         "logic cannot be run; install node in the workflow")
        print("  note: node is not on this machine, so the page's logic was "
              "checked by reading only (CI runs it)")
        return
    js = logic + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
t(isStale(10000, null, 2), "never heard is stale");
t(!isStale(10000, 9000, 2), "1 s old is fresh");
t(!isStale(10000, 8000, 2), "2 s old is still fresh");
t(isStale(10000, 7900, 2), "2.1 s old is stale");
const st = {schedule:{attached:true}, transport:{programming:true}};
let c = controlStates(st, true);
t(c.hold && c.disarm && !("abort" in c), "stale: Hold and disarm stay on (no Abort)");
t(!c.startNow && !c.resume && !c.transport && !("reset" in c),
  "stale: everything acting on shown state is off");
c = controlStates(st, false);
t(c.startNow && c.resume && c.transport,
  "fresh: all on");
c = controlStates(null, false);
t(!c.startNow && !c.transport && c.hold, "no status yet: only the safe ones");
c = controlStates({schedule:{attached:true}, transport:{programming:false}}, false);
t(!c.transport, "no programming session: transport off");
t(lampClass({armed:"armed"}, {connected:true, stale:true}) === "unknown",
  "a stale armed lamp reads unknown");
t(lampClass({armed:"armed"}, {connected:true, stale:false}) === "armed",
  "a fresh armed lamp reads armed");
t(staleText(10000, 6000).indexOf("CONNECTION LOST") === 0,
  "the banner says connection lost");
const ast = {arming:{enabled:true, fresh_s:1.0},
  flames:{connected:true, stale:false, age_ms:100,
          groups:[{name:"a", armed:"disarmed", wanted:false},
                  {name:"b", armed:"armed", wanted:true}]}};
t(armState(ast, 10000, 9500, 0).ok, "live, no sign-in, off: may hold to arm");
t(!armState(ast, 10000, 8900, 0).ok, "1.1 s since the engine: may not");
t(!armState(ast, 10000, 9500, 1).ok, "already armed: may not");
t(!armState(Object.assign({}, ast, {me:{may:{arm:false}}}), 10000, 9500, 0).ok &&
  armState(Object.assign({}, ast, {me:{may:{arm:false}}}), 10000, 9500, 0).signin === true,
  "signed out, or a role that may not arm: may not, and says sign in");
t(!cleaningState({available:true, state:"idle"}, false, false, true).ok &&
  cleaningState({available:true, state:"idle"}, false, false, true).block.indexOf("Signed out: this screen is view only.") === 0,
  "the cleaning: signed out is view only");
t(cleaningState({available:true, state:"idle"}, false, false, false).ok,
  "the cleaning: signed in, idle: a hold may start");
t(!armState(Object.assign({}, ast, {arming:{enabled:false}}),
  10000, 9500, 0).ok, "arming switched off: may not");
t(armState(Object.assign({}, ast, {arming:{enabled:false}}),
  10000, 9500, 0).why.indexOf("Programming, Arming from a screen, Turn on") > 0,
  "and the page says how to turn it on");
t(!armState(Object.assign({}, ast, {flames:Object.assign({}, ast.flames,
  {age_ms:1200})}), 10000, 9500, 0).ok, "flamesafe 1.2 s old: may not");
t(!armState(Object.assign({}, ast, {flames:Object.assign({}, ast.flames,
  {stale:true})}), 10000, 9500, 0).ok, "flamesafe stale: may not");
t(!armState(null, 10000, 9500, 0).ok, "no status: may not");
// The countdown (Jeff, 2026-10-07): left in this show while it runs,
// frozen while held, the next show between shows, nothing when unknown.
let ca = countdownAnchor(null, {kind:"left", label:"Left in this show", s:300, running:true}, 8000);
let cd = countdownRead(ca, 10000);
t(cd && cd.kind === "left" && Math.abs(cd.s - 298) < 1e-9, "running: counts down from when it was heard");
ca = countdownAnchor(ca, {kind:"left", label:"Left in this show", s:300, running:false}, 8000);
cd = countdownRead(ca, 10000);
t(cd && cd.s === 300, "held: frozen, not aged");
cd = countdownRead(countdownAnchor(ca, {kind:"next", label:"Next show", s:60, running:true}, 9000), 10000);
t(cd && cd.kind === "next" && cd.s === 59, "between shows: the next show");
t(countdownRead(countdownAnchor(ca, null, 9000), 10000) === null, "unknown length: nothing shown");
t(countdownRead(countdownAnchor(null, {kind:"left", s:2, running:true}, 5000), 10000).s === 0, "never below zero");
// The soak's flicker (2026-10-21): a status every 250 ms that arrives 5 to
// 120 ms late, the screen drawn every 20 ms. The digit must only ever go
// down, one second at a time, whether the engine's figure is exact or
// whole seconds rounded down (an older engine).
function soakDigits(whole){
  let seed = 7, a = null, last = null, bad = [], seen = 0;
  const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
  const end = 20000;                         // the show starts at 20 s
  let nextPoll = 0, arrive = null, sent = null;
  for(let now = 0; now <= end + 500; now += 20){
    if(arrive === null && now >= nextPoll){
      const left = Math.max(0, (end - now) / 1000);
      sent = whole ? Math.floor(left) : Math.round(left * 1000) / 1000;
      arrive = now + 5 + Math.floor(rnd() * 115);
      nextPoll = now + 250;
    }
    if(arrive !== null && now >= arrive){
      a = countdownAnchor(a, {kind:"next", label:"Next show", s:sent, running:true}, now);
      arrive = null;
    }
    const r = countdownRead(a, now);
    if(!r) continue;
    const d = Math.floor(r.s);
    if(last !== null && (d > last || last - d > 1)) bad.push(last + "->" + d + " at " + now);
    if(last !== null && d !== last) seen++;
    last = d;
  }
  return {bad:bad, seen:seen, last:last};
}
let sk = soakDigits(false);
t(sk.bad.length === 0 && sk.seen >= 18 && sk.last === 0, "exact figures: the digit only counts down " + JSON.stringify(sk.bad.slice(0, 4)));
sk = soakDigits(true);
t(sk.bad.length === 0 && sk.seen >= 18 && sk.last === 0, "whole-second figures: the digit only counts down " + JSON.stringify(sk.bad.slice(0, 4)));
// A delayed show, or a different next show, moves the moment later: taken.
ca = countdownAnchor(null, {kind:"next", label:"Next show", s:10, running:true}, 0);
ca = countdownAnchor(ca, {kind:"next", label:"Next show", s:610, running:true}, 1000);
t(Math.abs(countdownRead(ca, 1000).s - 610) < 1e-9, "a show delayed by 10 minutes is followed");
// A reply that came late never puts the count back up.
ca = countdownAnchor(null, {kind:"next", label:"Next show", s:10, running:true}, 0);
ca = countdownAnchor(ca, {kind:"next", label:"Next show", s:9.75, running:true}, 400);
t(Math.abs(countdownRead(ca, 400).s - 9.6) < 1e-9, "a late reply does not move the count up");
t(clockText(3725) === "1:02:05" && clockText(65.9) === "1:05" && clockText(-3) === "0:00", "clock text");
console.log(JSON.stringify(out));
"""
    r = _node_js(node, js, capture_output=True, text=True, timeout=60)
    try:
        bad = json.loads(r.stdout.strip() or "null")
    except ValueError:
        bad = None
    check(r.returncode == 0 and bad == [],
          f"the page's stale logic, in node: {r.stdout!r} {r.stderr[-400:]!r}")


def _morning_page_logic_in_node():
    """The Morning page's pure helpers (MORNING.md, "How it is tested"), run
    in node when this machine has it: fireKeyLapsed, the rule that ends a
    Space press whose key repeat events have stopped (review of PR #68,
    P1-4), and machineLook, what a machine tile reads."""
    import shutil
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    page = screen_text()
    a = page.find("// LOGIC BEGIN")
    b = page.find("// LOGIC END")
    logic = page[a:b]
    check("function fireKeyLapsed(" in logic and
          "function machineLook(" in logic and
          "function laserArmLine(" in logic,
          "fireKeyLapsed, machineLook and laserArmLine sit in the page's "
          "LOGIC block")
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner, so the Morning "
                         "page's helpers cannot be run; install node in the "
                         "workflow")
        print("  note: node is not on this machine, so the Morning page's "
              "helpers were checked by reading only (CI runs them)")
        return
    js = logic + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const G = 2500, P = 1000;
// A fresh press: within the grace time nothing can end it, repeat or not.
t(!fireKeyLapsed(1000, 0, 0, G, P), "1 s in, no repeat yet: holds");
t(!fireKeyLapsed(2500, 0, 0, G, P), "at the grace edge: holds");
// Past the grace time the key repeat events are the evidence.
t(fireKeyLapsed(2501, 0, 0, G, P), "2.5 s in, never a repeat event: ends (OS key repeat off, or a lost keyup)");
t(!fireKeyLapsed(5000, 0, 4500, G, P), "a repeat 0.5 s ago: holds");
t(!fireKeyLapsed(5000, 0, 4000, G, P), "a repeat exactly 1 s ago: holds");
t(fireKeyLapsed(5001, 0, 4000, G, P), "a repeat 1.001 s ago: ends");
t(fireKeyLapsed(60000, 0, 58000, G, P), "a long press whose repeats stopped 2 s ago: ends");
t(!fireKeyLapsed(60000, 0, 59900, G, P), "a long press still repeating: holds (a physically stuck key looks the same: the page is not a dead-man switch)");
t(fireKeyLapsed(3000, 0, undefined, G, P), "no repeatAt at all counts as none (undefined)");
t(fireKeyLapsed(3000, 0, null, G, P), "no repeatAt at all counts as none (null)");
t(!fireKeyLapsed(3000, 2000, 0, G, P), "a press that started 1 s ago holds whatever the old repeatAt says");
// machineLook: locked beats everything; nothing reads FIRING unless the
// engine says firing AND flamesafe reports the group armed on a fresh frame.
const m = {id:"g1", name:"G1", group:"front row"};
const mo = {lockout:{machines:{}}};
const fl = {stale:false, groups:[{name:"front row", armed:"armed", wanted:true, reason:""}]};
t(machineLook(m, {lockout:{machines:{g1:{}}}}, fl, {selected:["g1"], firing:true}).cls === "locked", "locked out reads locked even if selected and firing");
t(machineLook(m, mo, fl, {selected:[], firing:false}).word === "Off", "not selected: Off");
t(machineLook(m, mo, fl, {selected:["g1"], firing:false}).cls === "armed", "selected and armed: Purge armed");
t(machineLook(m, mo, fl, {selected:["g1"], firing:true}).cls === "firing", "selected, armed, firing: FIRING");
t(machineLook(m, mo, Object.assign({}, fl, {stale:true}), {selected:["g1"], firing:true}).cls === "sel", "flamesafe stale: never FIRING, never armed");
t(machineLook(m, mo, {stale:false, groups:[{name:"front row", armed:"held", reason:"latched"}]}, {selected:["g1"], firing:true}).word === "Held: latched", "a held group says why");
t(machineLook(m, mo, null, {selected:["g1"], firing:true}).cls === "sel", "no flamesafe at all: Arming..., never FIRING");
t(machineLook(m, null, fl, null).word === "Off", "no engine view, no purge: Off");
// A default wave flamer (a waver with no pan or tilt) says it is never purged, even firing.
const wv = {id:"w9", name:"wave flamer 1", kind:"waver", group:"front row", pan:null, tilt:null};
t(machineLook(wv, mo, fl, {selected:["w9"], firing:true}).word === "Never purged: no pan, tilt and fire map yet", "a waver with no pan or tilt: never purged, never FIRING");
t(machineLook(wv, mo, fl, {selected:[], firing:false}).word.indexOf("Never purged") === 0, "and says so when not selected");
t(machineLook(Object.assign({}, wv, {pan:432, tilt:433}), mo, fl, {selected:["w9"], firing:true}).cls === "firing", "a waver with pan and tilt reads as before");
t(machineLook(wv, {lockout:{machines:{w9:{}}}}, fl, null).cls === "locked", "locked still beats it");
// A fireball is never purged: the tile says so, never FIRING, locked still beats it.
const fbm = {id:"fb", name:"Fireball", kind:"fireball", group:"front row", pan:null, tilt:null};
t(machineLook(fbm, mo, fl, {selected:["fb"], firing:true}).word === "Never purged: a fireball has no purge sequence yet", "a fireball: never purged, never FIRING");
t(machineLook(fbm, mo, fl, {selected:[], firing:false}).word.indexOf("Never purged") === 0, "and says so when not selected");
t(machineLook(fbm, {lockout:{machines:{fb:{}}}}, fl, null).cls === "locked", "a locked fireball reads locked");
// Anything else the engine never purges says so in the engine's words (review of #120, P2-1).
const unk = {id:"fb-1", name:"FB 1", kind:"gflame", group:"front row", never_purged:"unknown multi-channel group, declare it in fireball_groups"};
t(machineLook(unk, mo, fl, {selected:[], firing:false}).word === "Never purged: unknown multi-channel group, declare it in fireball_groups", "an unknown multi-channel group's machine says why it is never purged");
t(machineLook(Object.assign({}, unk, {never_purged:""}), mo, fl, {selected:[], firing:false}).word === "Off", "a machine the engine purges reads as before");
// The laser arm's one line (Jeff, 2026-10-22): never "on" unless the engine says every laser is armed.
const L1 = {id:"l1", name:"Laser 1", armed:false}, L2 = {id:"l2", name:"Laser 2", armed:false};
t(laserArmLine({lasers:[L1, L2]}).indexOf("DISARMED, every laser") >= 0, "none armed: DISARMED");
t(laserArmLine({lasers:[L1, L2], output_fault:"Lasers: blanking not set up"}).indexOf("Arming is off: Lasers: blanking not set up") >= 0, "not set up: said");
t(laserArmLine({lasers:[{id:"l1", name:"Laser 1", armed:true}, L2], output_permitted:false, why_off:"Laser 2 is not"}).indexOf("Laser 1 ARMED (1 of 2). BEYOND's laser output stays OFF: Laser 2 is not") >= 0, "one of two: output stays off, and why");
t(laserArmLine({lasers:[{id:"l1", name:"Laser 1", armed:true}, {id:"l2", name:"Laser 2", armed:true}], output_permitted:false}).indexOf("ALL ARMED") < 0, "all armed but the engine says no: never ALL ARMED");
t(laserArmLine({lasers:[{id:"l1", name:"Laser 1", armed:true}], output_permitted:true}).indexOf("ALL ARMED") >= 0, "the engine says yes: ALL ARMED");
t(laserArmLine({lasers:[]}) === "No lasers are configured.", "no lasers");
console.log(JSON.stringify(out));
"""
    r = _node_js(node, js, capture_output=True, text=True, timeout=60)
    try:
        bad = json.loads(r.stdout.strip() or "null")
    except ValueError:
        bad = None
    check(r.returncode == 0 and bad == [],
          f"the Morning page's helpers, in node: {r.stdout!r} "
          f"{r.stderr[-400:]!r}")


def test_remote_has_no_arm_route():
    section("iPad remote: no route arms anything by itself; the only arm "
            "routes are the screen hold and its release, which the Stream "
            "Deck reads; nothing here or in web.py touches the arm link")
    import re as _re
    from ltcplay import remote as RM
    here = os.path.dirname(os.path.abspath(__file__))
    every = list(RM.GET_ROUTES) + list(RM.POST_ROUTES)
    armish = sorted(r for r in every if _re.search(r"(?<!dis)arm", r))
    # laser-arm (Jeff, 2026-10-22) arms LASERS (laserarm.py, BEYOND's laser
    # output switch); it never reaches the flame arm link: the checks below
    # on remote.py and web.py, and morning.py's own, still hold.
    # screen-arming (2026-10-22) is the switch for arming from a screen,
    # set on the show machine itself only; it arms nothing (turning it off
    # lets every hold go). test_screen_arming_switch_and_refusals proves it.
    # hazers-arm-all (Jeff, 2026-11-11) arms HAZERS only: each hazer of
    # the engine's own hazer list that flamesafe types "hazer", through
    # the per-hazer arm (hazers.Hazers.arm_all); never a flame group or a
    # laser. Pinned below, and in test_arm_all_hazers_only_arms_hazers.
    check(armish == ["arm-hold", "arm-release", "hazers-arm-all",
                     "laser-arm", "screen-arming"],
          f"the only flame arm routes are the hold and its release, the "
          f"one laser arm route, the hazer-only Arm all hazers and the "
          f"switch: {armish}")
    import inspect as _insp
    from ltcplay import hazers as _HZ
    from ltcplay import users as _U
    check("hazers-arm-all" in RM.HAZER_POST_ROUTES and
          "hazers-arm-all" not in RM.ARM_ROUTES and
          _U.REMOTE_ROUTES.get("hazers-arm-all") == "arm" and
          _U.classify("/api/remote/hazers-arm-all", {}) == "arm",
          "Arm all hazers is a hazer route (not a flame arm route) and "
          "needs the arm row, the per-hazer arm's own")
    src = _insp.getsource(_HZ.Hazers.arm_all).split('"""')[2]  # code only
    check("for n in names:" in src and "names = self.names()" in src and
          'if k != "hazer":' in src and "self.kind_of(n, fl)" in src and
          "self.set(n, True" in src and "hazers_set" not in src and
          "group" not in src and "laser" not in src,
          "Arm all hazers walks only the engine's hazer list, decides by "
          "flamesafe's type (never the name), and arms each through the "
          "per-hazer arm, never the link or a group directly")
    hp = _insp.getsource(RM.Remote.hazer_post)
    blk = hp[hp.find('if name == "hazers-arm-all":'):]
    blk = blk[:blk.find("return 200, out")]
    check("hz.arm_all(" in blk and "may_act_from" in blk and
          "arm_group" not in blk and "laser" not in blk,
          "its route calls only Hazers.arm_all, after screen_arming")
    check("screen-arming" in RM.LOCAL_ONLY,
          "the switch is the show machine's own, never the network's")
    check(RM.ARM_ROUTES == ("arm-hold", "arm-release", "group-disarm"),
          f"the arm routes: {RM.ARM_ROUTES}")
    for name in ("remote.py", "web.py"):
        src = open(os.path.join(here, "ltcplay", name), encoding="utf-8").read()
        routes = _re.findall(r'"/api/[a-z/_-]*"', src)
        armish = [r for r in routes if _re.search(r"(?<!dis)arm", r)]
        check(not armish, f"{name} names no other arm route: {armish}")
        for word in ("ArmSocket", "arm_port", "encode_arm_frame",
                     "set_group(", "set_all(True", "import streamdeck",
                     "from . import streamdeck"):
            check(word not in src,
                  f"{name} never touches the arm link ({word})")
    page = screen_text()
    posted = set(_re.findall(r'/api/remote/([a-z-]+)', page)) | set(
        _re.findall(r'press\("([a-z-]+)"', page))
    check({p for p in posted if _re.search(r"(?<!dis)arm", p)} <=
          {"arm-hold", "arm-release", "laser-arm", "screen-arming",
           "hazers-arm-all"},
          f"the page posts to no other arm route: {sorted(posted)}")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        for path in ("/api/remote/arm", "/api/remote/arm-all",
                     "/api/remote/arm-group", "/api/arm"):
            st, _h, out = R.ask("POST", path, {"group": "front row",
                                                "seen": R.seen()})
            check(st == (404 if path.startswith("/api/remote/") else 403),
                  f"{path} does not exist (or is not served to the "
                  f"network at all): {st}")
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/arm",
                           {"group": "front row"},
                           client=("127.0.0.1", 5000))
        check(st == 404, "not from the machine itself either")
    finally:
        R.close()
    print("  ok")


def _css_rules(page):
    """The page's top-level style rules as [(selector, {prop: value})],
    with @media and @font-face blocks left out (their rules are read
    separately by _css_media). A small parser, enough for this page."""
    import re as _re
    a = page.find("<style>")
    b = page.find("</style>", a)
    css = _re.sub(r"/\*.*?\*/", "", page[a + 7:b], flags=_re.S)
    out, i, n = [], 0, len(css)
    while i < n:
        j = css.find("{", i)
        if j == -1:
            break
        head = css[i:j].strip()
        if head.startswith("@"):
            depth, k = 1, j + 1
            while k < n and depth:
                depth += {"{": 1, "}": -1}.get(css[k], 0)
                k += 1
            i = k
            continue
        k = css.find("}", j)
        decl = {}
        for part in css[j + 1:k].split(";"):
            if ":" in part:
                p, _, v = part.partition(":")
                decl[p.strip().lower()] = v.strip().lower()
        out.append((head, decl))
        i = k + 1
    return out


def _css_rule(rules, selector):
    for sel, decl in rules:
        if sel.replace(" ", "") == selector.replace(" ", ""):
            return decl
    return None


# -- the rack screen in a real browser (Jeff, 2026-10-24) --------------------
# On the Windows show PC (Edge, 1920x1080, STANDBY) two red FAULT banners and
# a yellow flame note filled the top of the rack screen, the three flame
# group cards were squashed to slivers about 15 px tall, their Hold to arm
# and Disarm buttons could not be seen or reached, Disarm all flame groups
# overlapped them and the mouse wheel did not scroll. The CSS contract above
# could not see it: only a browser laying the page out can. This draws the
# page in headless Chromium (or Chrome or Edge) at the show PC's sizes with
# three or more banners, and measures every button that arms, disarms or
# stops.

def _node_js(node, js, **kw):
    """node running `js`, as subprocess.run([node, "-e", js], **kw) did,
    but from a temporary file: the page's logic block alone is over 30,000
    characters, and Windows refuses a command line over 32,767 (WinError
    206). The same output and return code on every OS."""
    import subprocess as _subp
    import tempfile as _tf
    fd, path = _tf.mkstemp(suffix=".js", prefix="ltc-node-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(js)
        return _subp.run([node, path], **kw)
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


def _find_chromium():
    """A Chromium, Chrome or Edge to draw the page with, or None.
    LTCPLAY_CHROME names one by hand."""
    import glob
    import shutil
    env = os.environ.get("LTCPLAY_CHROME")
    if env and os.path.isfile(env):
        return env
    for n in ("chromium", "chromium-browser", "google-chrome",
              "google-chrome-stable", "chrome", "msedge"):
        p = shutil.which(n)
        if p:
            return p
    for p in (sorted(glob.glob("/opt/pw-browsers/chromium-*/chrome-linux/"
                               "chrome"), reverse=True) +
              [r"C:\Program Files\Google\Chrome\Application\chrome.exe",
               r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
               r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
               r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
               "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"]):
        if os.path.isfile(p):
            return p
    return None


