def test_timed_purge_deck_key():
    section("timed purge on the Stream Deck (Jeff, 2026-10-29): while the "
            "engine says one runs, key 0 reads PURGING and the engine's "
            "seconds left (rounded up), the group stays wanted with the "
            "page closed, and pressing FIRE is a second purge press sent "
            "to the engine (which ends it); it goes back to normal after")
    from ltcplay import streamdeck as sd
    arm = _FakeArmSocket(3)
    names = ["front row", "cat-walk", "wave flamer"]
    t = [100.0]
    scr = _FakeMorningScreen()
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      conductor=_FakeConductor(),
                      journal=lambda t_, **kw: None,
                      clock=lambda: t[0], screen=scr)
    pf = _FakePurgeFire()
    c.purge_fire = pf

    def mo(left):
        scr.mo = {"open": True, "purge_enabled": True,
                  "purge": {"wanted_groups": [0], "selected": 1,
                            "firing": left is not None,
                            "timed_left_s": left},
                  "locks": {"groups_fully_locked": []}}

    def step(dt=0.05):
        t[0] += dt
        c.screen_pass()
        c.tick()
    mo(None)
    step()
    check(c.purge_timed_left() is None, "no timed purge: None")
    for bad in (True, "7", float("nan"), None):
        scr.mo["purge"]["timed_left_s"] = bad
        check(c.purge_timed_left() is None,
              f"timed_left_s {bad!r}: not a countdown")
    mo(7.2)
    step()
    check(c.purge_timed_left() == 7.2 and arm.wanted[0] is True,
          f"running: the seconds left, and the group stays armed: "
          f"{arm.wanted}")
    fonts, faces, restore = _deck_face_recorder(sd)
    try:
        if fonts is not None:
            c.draw(fonts, blink_on=False, chase=0)
            check(faces[0][0] == ["PURGING", "8 S"],
                  f"key 0 reads PURGING 8 S: {faces[0]}")
            mo(0.04)
            step()
            c.draw(fonts, blink_on=True, chase=0)
            check(faces[0][0] == ["PURGING", "1 S"],
                  f"0.04 s left reads 1 S, never 0 while it runs: "
                  f"{faces[0]}")
        down, up = [True] + [False] * 5, [False] * 6
        c.run_once(down)
        check(pf.calls and pf.calls[-1][0] == "start",
              f"FIRE pressed while it runs: a purge press goes to the "
              f"engine (a second press, which ends it): {pf.calls}")
        c.run_once(up)
        mo(None)
        step()
        if fonts is not None:
            c.draw(fonts, blink_on=False, chase=0)
            check(faces[0][0] == ["FIRE", "HOLD"],
                  f"once it has ended: FIRE HOLD again: {faces[0]}")
    finally:
        restore()
    print("  ok")


def test_timed_purge_stall_inside_a_send_and_a_signed_out_deck():
    section("timed purge, re-review of #172 (B1, B2): a pause INSIDE one "
            "send of the engine's timer, long or short, never relights a "
            "frame the flame link has dropped (the real FlameLink on the "
            "test's clock); a zero landing after the count was read is "
            "refused under the link's lock; and the Stream Deck's FIRE "
            "with nobody signed in on the rack screen still ends a timed "
            "purge an iPad started")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import flamelink as fl
    from ltcplay import streamdeck as sd
    from ltcplay import users as U
    R = _tp_rig(S)

    def real_link():
        cfg = fl.FlameLinkConfig("127.0.0.1", 5571, 1, _fl_key(),
                                 frame_stale_ms=500)
        lk = fl.FlameLink(cfg, cues=lambda tc: [0] * 512,
                          show_state=lambda: (None, False),
                          clock=lambda: R.mono[0], seek_guard=False)
        lk._send = lambda d: True
        lk.sender_state = lambda: "running"
        return lk

    def slot(lk):
        return lk.values_now()[1][410]

    def step(dt):
        R.mono[0] += dt
        R.wall[0] += dt
        R.feed()
        R.remote._deck_seen = R.mono[0]

    def fresh_start(seconds=10):
        R.m.purge.clear("test reset")
        R.m.open_beat("Rack screen")
        R.ask("POST", "/api/remote/purge-select",
              {"machine": "g1", "seen": R.seen()}, client=R.loop)
        st, out, _r = _tp_hold(R, seconds)
        return check(st == 200 and out.get("started"),
                     f"setup: a timed purge running: {out}")
    real_checks = R.m.timed_blockers
    try:
        # B1, large: a 2 s pause inside one send, after its first look.
        R.link = link = real_link()
        if fresh_start():
            check(slot(link) == 240, "firing on the real link")
            _tp_step(R, 0.1)
            seen = {}

            def slow(t):
                r = real_checks(t)
                if t is not None and not seen:
                    step(2.0)
                    seen["during"] = slot(link)
                return r
            R.m.timed_blockers = slow
            step(0.1)
            why = R.m.purge.timed_send()
            R.m.timed_blockers = real_checks
            check(seen.get("during") == 0,
                  "the link dropped the frame during the pause")
            check(why and not R.m.purge.timed_running() and slot(link) == 0,
                  f"after a 2 s pause inside the send: ended, the frame "
                  f"never comes back: {why!r} slot {slot(link)}")
            check("stalled" in why or "did not take" in why,
                  f"and said why: {why!r}")
        # The engine's own look, alone (a link with no belt): the same
        # pause inside a send ends it there, and the frame is never set.
        R.link = fake = _FakeTimedLink()
        if fresh_start():
            _tp_step(R, 0.1)
            n0 = len(fake.frames)
            seen = {}

            def slow_fake(t):
                r = real_checks(t)
                if t is not None and not seen:
                    seen["x"] = True
                    step(0.5)
                return r
            R.m.timed_blockers = slow_fake
            step(0.1)
            why = R.m.purge.timed_send()
            R.m.timed_blockers = real_checks
            check("stalled" in why and len(fake.frames) == n0,
                  f"a 0.5 s pause inside the send: the engine itself ends "
                  f"it and sets no frame: {why!r}")
        # And a link that refuses the frame (zeroed, dropped, past its
        # hard end): the engine ends it, never carries on unheard.
        R.link = fake = _FakeTimedLink()
        if fresh_start():
            fake.purge_set = lambda values, gen=None: False
            step(0.1)
            why = R.m.purge.timed_send()
            check("did not take" in why and not R.m.purge.timed_running(),
                  f"a refused frame ends it: {why!r}")
        # B1, small: 0.225 s with no send, then 60 ms inside the send.
        R.link = link = real_link()
        if fresh_start():
            trace = []
            for _ in range(9):
                step(0.025)
                trace.append(slot(link))

            def slow2(t):
                r = real_checks(t)
                if t is not None:
                    for _ in range(3):
                        step(0.02)
                        trace.append(slot(link))
                return r
            R.m.timed_blockers = slow2
            why = R.m.purge.timed_send()
            R.m.timed_blockers = real_checks
            after = []
            for _ in range(8):
                step(0.025)
                R.m.tick()
                after.append(slot(link))
            check(0 in trace and not any(after) and
                  not R.m.purge.timed_running(),
                  f"the link dropped it at 0.25 s; the send that came late "
                  f"ends it rather than relight it: {trace} -> {after} "
                  f"({why!r})")
        # A pause after the send's last look and before the link's lock
        # (round 3 of #172): the link sees the frame it would replace has
        # gone stale and refuses it; the engine ends the purge.
        R.link = link = real_link()
        if fresh_start():
            _tp_step(R, 0.1)
            real_set = link.purge_set

            def paused(vals, gen=None):
                step(2.0)
                return real_set(vals, gen=gen)
            link.purge_set = paused
            step(0.1)
            why = R.m.purge.timed_send()
            link.purge_set = real_set
            check(slot(link) == 0 and not link.purge_active() and
                  not R.m.purge.timed_running(),
                  f"a 2 s pause just before the link's lock: nothing "
                  f"relit, ended: {why!r}")
        # A pause between the engine reading its clock and the link
        # taking its hard end (round 3 of #172): the end stays the
        # engine's deadline, never later.
        R.link = link = real_link()
        real_limit = link.purge_limit

        def slow_limit(s, **kw):
            step(0.2)
            return real_limit(s, **kw)
        link.purge_limit = slow_limit
        try:
            ok = fresh_start(2)
        finally:
            link.purge_limit = real_limit
        if ok:
            dl = R.m.purge.fire["timed"]["deadline"]
            check(link._purge_until is not None and
                  link._purge_until <= dl + 1e-9,
                  f"a 0.2 s pause before the link's lock: its hard end is "
                  f"the deadline, not later (+"
                  f"{(link._purge_until or 0) - dl:.3f} s)")
            R.m.purge.clear("test reset")
        # A momentary press whose frame the link refuses is never answered
        # as firing.
        R.link = fake = _FakeTimedLink()
        R.m.purge.clear("test reset")
        R.m.open_beat("Rack screen")
        R.ask("POST", "/api/remote/purge-select",
              {"machine": "g1", "seen": R.seen()}, client=R.loop)
        fake.purge_set = lambda values, gen=None: False
        st, out = R.m.purge.fire_beat({"on": True}, "Rack screen", True)
        check(st == 409 and "did not take" in out.get("error", "") and
              R.m.purge.fire is None,
              f"a refused momentary frame: not firing, said so: {st} {out}")
        R.m.purge.clear("test reset")
        # A Space press that looked before a timed purge started on its
        # own screen and lands after: it ends it with its line, never
        # overwrites it.
        R.link = fake = _FakeTimedLink()
        if fresh_start():
            n_end = len(_tp_lines(R, "timed_end"))
            R.m.purge.timed_running = lambda: False
            try:
                st, out = R.m.purge.fire_beat({"on": True}, "Rack screen",
                                              True)
            finally:
                del R.m.purge.timed_running
            ln = _tp_lines(R, "timed_end")
            check(st == 409 and R.m.purge.fire is None and
                  len(ln) == n_end + 1 and
                  "second purge press" in ln[-1]["text"],
                  f"a press that raced a timed purge's start ends it with a "
                  f"journal line: {st} {out} {ln[-1:]}")
        # The link's own belt: a timed purge's frame that went stale is
        # refused from then on, until purge_clear().
        lk = real_link()
        frame = bytes([0] * 410 + [240] + [0] * 101)
        lk.purge_limit(30)
        lk.purge_set(frame)
        step(0.3)
        check(slot(lk) == 0 and lk.purge_set(frame) is False and
              slot(lk) == 0, "a timed frame dropped stale is never set "
                             "again by the link")
        lk.purge_clear()
        check(lk.purge_set(frame) is True, "until purge_clear()")
        # The zero count, under the link's lock.
        g = lk._zero_gen
        lk.zero()
        check(lk.purge_set(frame, gen=g) is False and slot(lk) == 0,
              "a frame whose count was read before a zero is refused")
        check(lk.purge_set(frame, gen=lk._zero_gen) is True,
              "with the current count it is taken")
        # B2: nobody signed in on the rack screen; Ollie started it on an
        # iPad; the deck's FIRE ends it.
        R.link = link = real_link()
        udir = tempfile.mkdtemp()
        us = U.Users(udir, hash_params=_U_FAST)
        us.seed([("Jeff", "admin"), ("Ollie", "operator")])
        R.remote.users = us
        ok, why, tok, _n = us.sign_in("Ollie", "", True, "rack",
                                      new_password="Ollie-pw-1234")
        us.sign_out(tok, "rack", local=True)
        ok, why, tok, _n = us.sign_in("Ollie", "Ollie-pw-1234", False,
                                      "10.20.0.44")
        hdr = {"Cookie": f"{U.COOKIE}={tok}"}
        R.m.purge.clear("test reset")
        R.m.open_beat("iPad at 10.20.0.44")
        R.ask("POST", "/api/remote/purge-select",
              {"machine": "g1", "seen": R.seen()}, client=R.ipad,
              headers=hdr)
        st, out, _r = _tp_hold(R, 30, client=R.ipad, headers=hdr)
        if check(st == 200 and out.get("started"),
                 f"setup: Ollie's timed purge from the iPad: {out}"):
            posts = []

            def poster(path, body):
                st_, _h_, o = R.ask("POST", path, body, client=R.loop)
                posts.append((path, st_, bool((o or {}).get("ended"))))
                return (st_ == 200, (o or {}).get("error", ""), o)
            pf = sd.PurgeFire(poster)
            pf.start(who="")
            pf.join(2.0)
            check(not R.m.purge.timed_running() and slot(link) == 0,
                  f"the deck's FIRE with nobody signed in ends it: "
                  f"{posts}")
            check(posts and posts[0][:3] == ("/api/remote/purge-fire", 403,
                                             True),
                  f"the press itself ended it (refused as an arm, but a "
                  f"second purge press): {posts}")
            check(any(p[:2] == ("/api/remote/purge-stop", 200)
                      for p in posts),
                  f"and the refused press posts purge-stop on its way out: "
                  f"{posts}")
            pf.stop(who="")
        R.remote.users = None
    finally:
        R.m.timed_blockers = real_checks
        R.close()
    print("  ok")


def test_windows_rack_window_and_explorer_front():
    section("rack screen window (Jeff, 2026-10-19): the Windows app opens "
            "the page as an ordinary Edge app window, Minimize, Maximize "
            "and Close in its title bar, maximized on the show monitor, "
            "never a kiosk or full screen; a folder the page opens is "
            "found by its new Explorer window and brought to the front; "
            "the page says how to minimize and where the folder is")
    W, SUP, gone = _winpkg()
    try:
        cmd = SUP.rack_page_command(7878, 2, [(0, 0, 1920, 1080),
                                              (1920, 0, 3840, 1080)],
                                    r"C:\Edge\msedge.exe", r"C:\p")
        check(cmd[0] == r"C:\Edge\msedge.exe" and
              cmd[1] == "--app=http://127.0.0.1:7878/remote",
              f"Edge opens the page as an app window: {cmd}")
        check(not any("kiosk" in a or "fullscreen" in a or "always-on-top"
                      in a for a in cmd),
              f"never a kiosk, full screen or always on top: {cmd}")
        check("--start-maximized" in cmd and "--window-size=1920,1080" in cmd
              and cmd[-1] == "--window-position=1920,0",
              f"maximized on the show monitor, sized to it as the fallback: "
              f"{cmd}")
        check("--no-first-run" in cmd and f"--user-data-dir=C:\\p" in cmd,
              f"its own profile, no first-run questions: {cmd}")
        check(SUP.rack_page_command(7878, 9, [(0, 0, 1, 1)], "e", "p")[-1]
              == "--window-position=0,0" and
              SUP.rack_page_command(7878, 1, [], None, "p") is None,
              "an unknown monitor is the main one; no Edge, no command")
        ref = SUP.rack_page_command(0, 1, [], "e", "p",
                                    url="file:///C:/r.html")
        check(ref[1] == "--app=file:///C:/r.html" and "--kiosk" not in ref,
              f"the refusal page uses the same window: {ref}")
        src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "packaging", "windows", "supervisor.py"),
                   encoding="utf-8").read()
        check("--kiosk" not in src.replace('a.startswith("--kiosk")', "") and
              "--edge-kiosk-type" not in src,
              "no kiosk flag is left anywhere in the supervisor")
    finally:
        gone()
    from ltcplay import remote as RM
    path = r"C:\Users\show\AppData\Local\ltcplay"
    before = [(1, "CabinetWClass", "Documents"),
              (2, "Chrome_WidgetWin_1", "Ignite the Night remote")]
    pick = RM.pick_explorer_window
    check(pick(path, before, before) is None, "no new window yet: nothing")
    check(pick(path, before, before + [(3, "CabinetWClass", "ltcplay")]) == 3,
          "the new Explorer window titled with the folder's name")
    check(pick(path, before, before + [(3, "CabinetWClass", path)]) == 3,
          "or with its full path (Explorer's other title setting)")
    check(pick(path, before, before + [(3, "CabinetWClass", "Pictures")])
          == 3, "the one new Explorer window, whatever its title")
    check(pick(path, before, before + [(3, "CabinetWClass", "Pictures"),
                                       (4, "CabinetWClass", "Music")])
          is None, "two new ones and neither is this folder: neither is "
                   "pulled forward")
    check(pick(path, before, before + [(3, "CabinetWClass", "Pictures"),
                                       (4, "CabinetWClass", "ltcplay")])
          == 4, "two new ones and one is this folder: that one")
    check(pick(path, before, before + [(3, "Notepad", "ltcplay")]) is None,
          "a new window that is not Explorer's is never touched")
    check(pick(path, before, before + [(1, "CabinetWClass", "ltcplay")])
          is None, "a window that was already there is not new")
    check(pick(path, before, before + [(1, "CabinetWClass", "ltcplay")],
               reuse=True) == 1,
          "but once the wait is over with nothing new, the Explorer window "
          "already open on this folder (Explorer reused it) is brought "
          "forward")
    check(pick(path, before, before, reuse=True) is None and
          pick(path, before, before + [(5, "Notepad", "ltcplay")],
               reuse=True) is None,
          "reuse never pulls forward a window that is not Explorer's on "
          "this folder")
    check(pick(path, before, before + [(3, "CabinetWClass", "Pictures"),
                                       (4, "CabinetWClass", "Music"),
                                       (1, "CabinetWClass", "ltcplay")],
               reuse=True) is None,
          "reuse only when nothing new came")
    check("reuse=True)" in open(os.path.join(os.path.dirname(
        os.path.abspath(__file__)), "ltcplay", "remote.py"),
        encoding="utf-8").read(),
          "the front-bringer falls back to a reused Explorer window")
    check(RM._explorer_to_front(path, before, wait_s=0) is False,
          "with no window to find (or off Windows) it says so and does "
          "nothing")
    check(RM.EXPLORER_FRONT_WAIT_S >= 2.0,
          "Explorer gets at least 2 s to open its window")
    rm_src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "ltcplay", "remote.py"), encoding="utf-8").read()
    check('threading.Thread(target=_explorer_to_front' in rm_src and
          'before = _explorer_windows()' in rm_src and
          "os.startfile(path)" in rm_src,
          "on Windows the opener snapshots the windows, opens the folder "
          "and brings its new window forward on a thread")
    check('brought it to the front. If you do not' in rm_src and
          'see it, it is on the taskbar.' in rm_src,
          "the route's answer says where the folder is")
    page = screen_text()
    info = page[page.find('<div id="info"'):page.find('<script id="remote-logic">')]
    check("Minimize, Maximize and Close buttons" in info and
          "<kbd>Windows</kbd> key + <kbd>Down arrow</kbd>" in info and
          "it is on the taskbar" in info,
          "the info panel says how to minimize and where an opened folder is")
    for bad in ("—", "–"):
        check(bad not in info and bad not in rm_src, "no em or en dashes")
    print("  ok")


def _re_findall(pattern, text):
    import re as _re
    return _re.findall(pattern, text)


# ------------------------------------------------ users and the audit log --
# Jeff, 2026-10-20 (USERS.md): named users with passwords, a role matrix
# that never touches a safety press, and an append-only, hash-chained audit
# log of every press, sent nightly to his server once switched on.

_U_FAST = {"n": 2 ** 10}           # a cheap scrypt for the tests only


def _u_clock(start=1000.0):
    t = [start]
    return t, (lambda: t[0])


def test_users_passwords_are_slow_salted_hashes_and_never_stored():
    section("users: passwords are salted slow hashes, never stored or "
            "answered; seeded people choose theirs at first sign-in; a "
            "temporary password is changed at first sign-in")
    import json as _j
    from ltcplay import users as U
    a = U.hash_password("Fire-and-Ice-1")
    b = U.hash_password("Fire-and-Ice-1")
    check(a["alg"] in ("scrypt", "pbkdf2_sha256") and a["salt"] != b["salt"]
          and a["hash"] != b["hash"], "a salt of its own per password")
    if a["alg"] == "scrypt":
        check(a["n"] >= 2 ** 14 and a["r"] == 8,
              f"scrypt at a real cost by default: {a}")
    check(U.check_password("Fire-and-Ice-1", a) and
          not U.check_password("fire-and-ice-1", a) and
          not U.check_password("", a), "only the right password checks")
    p = U.hash_password("pw-123456", alg="pbkdf2_sha256")
    check(p["iterations"] >= 600_000 and U.check_password("pw-123456", p)
          and not U.check_password("pw-12345", p),
          "the PBKDF2 fallback is slow too, and checks")
    check(not U.check_password("x", {"alg": "md5", "salt": "00",
                                     "hash": "00"}) and
          not U.check_password("x", {}), "a broken record is never a match")
    d = tempfile.mkdtemp()
    t, clock = _u_clock()
    notes = []
    us = U.Users(d, clock=clock, hash_params=_U_FAST,
                 audit=lambda **k: notes.append(k))
    check(not us.active() and us.may(None, "settings"),
          "before any user exists every press may (nothing switched on)")
    check(us.seed(U.SEED_USERS) and not us.seed(U.SEED_USERS),
          "first run seeds the people once, never again")
    check([(u["name"], u["role"]) for u in sorted(
        us.listing(), key=lambda u: u["name"])] ==
          sorted([("Jeff", "admin"), ("Andy", "admin"), ("Dallen", "operator"),
                  ("Dave", "operator"), ("Jared", "operator")]),
          f"Jeff and Andy admins, Dallen, Dave, Jared operators: "
          f"{us.listing()}")
    check(all(not u["password_set"] for u in us.listing()),
          "no password is shipped: every seeded person chooses their own")
    ok, why, tok, need = us.sign_in("Jeff", "", True, "Rack screen")
    check(not ok and need and tok is None and "Choose your own" in why,
          f"a first sign-in asks for a password of their own: {why}")
    ok, why, tok, need = us.sign_in("jeff", "", True, "Rack screen",
                                    new_password="short")
    check(not ok and need, "too short a password is refused")
    ok, why, tok, need = us.sign_in("jeff", "", True, "Rack screen",
                                    new_password="Jeff-own-pw")
    check(ok and tok and us.session(tok)["name"] == "Jeff",
          f"Jeff chooses his and is signed in: {why}")
    ok, *_ = us.sign_in("Jeff", "", True, "Rack screen",
                        new_password="steal-it-now")
    check(not ok, "once chosen, nobody can choose it again")
    # Admins add people with a temporary password.
    said = us.add("Pat", "operator", "temp-pass-1")
    check("temporary" in said, said)
    ok, why, tok2, need = us.sign_in("Pat", "temp-pass-1", False, "iPad")
    check(not ok and need and tok2 is None,
          f"a temporary password does not sign in by itself: {why}")
    ok, why, tok2, need = us.sign_in("Pat", "temp-pass-1", False, "iPad",
                                     new_password="temp-pass-1")
    check(not ok, "the new password has to differ from the temporary one")
    ok, why, tok2, need = us.sign_in("Pat", "temp-pass-1", False, "iPad",
                                     new_password="pat-own-pw")
    check(ok and not need, f"Pat replaces it and is in: {why}")
    ok, *_ = us.sign_in("Pat", "temp-pass-1", False, "iPad")
    check(not ok, "the temporary password no longer works")
    # Reset, role, remove, and the last admin.
    us.set_password("Pat", "reset-pass-9")
    check(us.session(tok2) is None, "a reset ends that person's sessions")
    ok, *_, need = us.sign_in("Pat", "reset-pass-9", False, "iPad")
    check(not ok and need, "a reset password is temporary too")
    us.clear_password("Pat")
    check(not [u for u in us.listing() if u["name"] == "Pat"][0]
          ["password_set"], "clear: Pat chooses one at the next sign-in")
    check("viewer" in us.set_role("Pat", "viewer"), "a role changes")
    us.remove("Andy")
    for f, args in ((us.remove, ("Jeff",)), (us.set_role, ("Jeff", "operator"))):
        try:
            f(*args)
            check(False, f"{f.__name__} of the last admin was allowed")
        except ValueError as e:
            check("last admin" in str(e), str(e))
    us.add("Andy", "admin", "andy-temp-1")
    us.set_role("Jeff", "operator")
    check(us.role_of("Jeff") == "operator", "with another admin it may")
    try:
        us.add("jeff", "viewer", "whatever-1")
        check(False, "a second Jeff was added")
    except ValueError:
        pass
    for bad in ("", "unsigned", "System", "x" * 41, "<b>"):
        try:
            us.add(bad, "operator", "whatever-1")
            check(False, f"the name {bad!r} was accepted")
        except ValueError:
            pass
    raw = open(os.path.join(d, U.USERS_FILE), encoding="utf-8").read()
    for pw in ("Jeff-own-pw", "pat-own-pw", "temp-pass-1", "reset-pass-9",
               "andy-temp-1"):
        check(pw not in raw, f"{pw} is not in the users file")
    view = _j.dumps(us.view())
    check('"hash"' not in view and '"salt"' not in view and
          "Jeff-own-pw" not in view, "the Users screen never gets a hash")
    check(all("Jeff-own-pw" not in _j.dumps(n) for n in notes) and
          any(n["action"] == "sign-in" and n["user"] == "Jeff" and
              n["result"] == "accepted" for n in notes),
          "sign-ins are told to the audit log, never a password")
    if os.name != "nt":
        check(os.stat(os.path.join(d, U.USERS_FILE)).st_mode & 0o077 == 0,
              "the users file is private to this account")


def test_users_lockout_is_short_and_never_permanent():
    section("users: wrong passwords lock the name for a short while, "
            "doubling to 5 minutes at most; an admin clears it")
    from ltcplay import users as U
    d = tempfile.mkdtemp()
    t, clock = _u_clock()
    us = U.Users(d, clock=clock, hash_params=_U_FAST)
    us.add("Jeff", "admin", "jeff-temp-1")
    us.sign_in("Jeff", "jeff-temp-1", True, "Rack screen",
               new_password="right-pw-1")
    for i in range(U.FREE_TRIES):
        ok, why, *_ = us.sign_in("Jeff", "wrong", True, f"dev{i}")
        check(not ok and "do not match" in why, f"try {i + 1} costs nothing")
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "devX")
    check(ok, f"inside the free tries the right password works: {why}")
    for i in range(U.FREE_TRIES):
        us.sign_in("Jeff", "wrong", True, f"devY{i}")
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "devZ")
    check(ok, f"a right password started the count again: {why}")
    for i in range(U.FREE_TRIES + 1):
        us.sign_in("Jeff", "wrong", True, "dev-a")
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "dev-b")
    check(not ok and "Try again in 30 s" in why,
          f"the 6th wrong one locks the name for 30 s: {why}")
    t[0] += 31
    ok, *_ = us.sign_in("Jeff", "wrong", True, "dev-c")
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "dev-d")
    check(not ok and "Try again in 60 s" in why, f"then 60 s: {why}")
    for _ in range(10):
        t[0] += 400
        us.sign_in("Jeff", "wrong", True, "dev-e")
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "dev-f")
    check(not ok and "Try again in 300 s" in why,
          f"never more than 5 minutes: {why}")
    t[0] += U.LOCK_MAX_S + 1
    ok, why, *_ = us.sign_in("Jeff", "right-pw-1", True, "dev-g")
    check(ok, f"and never permanent: {why}")
    for _ in range(U.FREE_TRIES + 1):
        us.sign_in("Jeff", "wrong", True, "dev-h")
    check(us.listing()[0]["locked_s"] > 0, "the Users screen shows the lock")
    us.clear_lockouts()
    ok, *_ = us.sign_in("Jeff", "right-pw-1", True, "dev-h")
    check(ok, "an admin's Clear sign-in lockouts lets them in at once")
    ok, why, *_ = us.sign_in("Nobody", "x", True, "dev-i")
    check(not ok and why == "That name and password do not match.",
          "an unknown name reads exactly like a wrong password")
    # Idle sign out: off by default (the show PC), on when set.
    ok, _w, tok, _n = us.sign_in("Jeff", "right-pw-1", True, "rack")
    check(us.idle_minutes() == 0, "idle sign out is off by default")
    t[0] += 24 * 3600
    check(us.session(tok) is not None, "off: a day idle and still signed in")
    us.set_idle(2)
    us.touch(tok)
    t[0] += 100
    check(us.session(tok) is not None, "inside the idle time: still in")
    t[0] += 21
    check(us.session(tok) is None and us.machine_user() is None,
          "past it: signed out, and the deck acts as nobody")
    for bad in (-1, 1441, True, "5"):
        try:
            us.set_idle(bad)
            check(False, f"idle {bad!r} was accepted")
        except ValueError:
            pass


# -- settings changed on disk (Jeff's field report 2026-10-28, item 11) -----
# flamesafe.json was fixed at 01:54 while the supervisor restarted flamesafe
# five times; flamesafe read the final file at 01:55:54, but the engine and
# the Stream Deck program had read it at 01:54:49 and kept that copy, and
# nothing on the rack screen said so. ltcplay_announce.json too: the status
# page showed the old value after the file was edited.

def _cfg_dashes(text):
    return "\u2014" not in text and "\u2013" not in text


def test_config_watch_names_the_file_and_who_is_behind():
    section("Settings changed on disk: the notice names the file and every "
            "program still on the older copy, by content, display only, and "
            "clears once the file matches again (configwatch.py)")
    import shutil as _sh
    from ltcplay import configwatch as CW
    d = tempfile.mkdtemp()
    try:
        def put(name, doc, mtime, raw=None):
            p = os.path.join(d, name)
            with open(p, "wb") as fh:
                fh.write(raw if raw is not None else
                         json.dumps(doc).encode("utf-8"))
            os.utime(p, (mtime, mtime))
            return p
        t0 = 1_800_000_000.0
        old_doc = {"groups": [{"name": "wave flamer", "aim": []}]}
        new_doc = {"groups": [{"name": "wave flamer", "aim": [1, 7, 13]}]}
        fs = put("flamesafe.json", old_doc, t0 - 100)
        h_old = CW.file_hash(fs)
        lines = []
        w = CW.ConfigWatch(journal=lines.append, wall=lambda: t0)
        w.add("flamesafe config", fs, others=(CW.DECK, CW.FLAMESAFE))
        progs = {"flamesafe": {"running": True, "started": t0,
                               "read": {fs: h_old}},
                 "engine": {"running": True, "started": t0},
                 "deck": {"running": True, "started": t0,
                          "read": {fs: h_old}}}
        check(w.check(progs) == [] and w.view()["text"] == "" and
              lines == [],
              f"nothing changed: no notice and no journal line: "
              f"{w.view()} {lines}")
        # The aim list is fixed; the supervisor restarts flamesafe and it
        # reads the final file.
        put("flamesafe.json", new_doc, t0 + 61)
        progs["flamesafe"]["read"] = {fs: CW.file_hash(fs)}
        items = w.check(progs)
        v = w.view()
        check(len(items) == 1 and items[0]["file"] == "flamesafe.json" and
              items[0]["behind"] == [CW.ENGINE, CW.DECK] and
              v["engine_behind"],
              f"the engine and the deck are behind, flamesafe is not: "
              f"{items}")
        t = v["text"]
        check(t.startswith("Settings changed on disk: flamesafe.json") and
              "older copy in the engine and the Stream Deck program" in t and
              "Restart LTC Player between shows, when nothing is armed, to "
              "use them (Start menu, Stop LTC Player then Start LTC "
              "Player)." in t and t.endswith(CW.AIM_NOTE) and
              t.count("Aim slots") == 1 and _cfg_dashes(t),
              f"the notice in plain words, with what to do and when, and "
              f"the aim alert named once: {t!r}")
        check(lines == [t], f"one journal line for it: {lines}")
        w.check(progs)
        check(lines == [t], f"not said again while nothing changes: {lines}")
        # flamesafe not restarted: it is behind too.
        progs["flamesafe"]["read"] = {fs: h_old}
        items = w.check(progs)
        check(items[0]["behind"] == [CW.ENGINE, CW.DECK, CW.FLAMESAFE] and
              "flamesafe" in w.view()["text"] and len(lines) == 2,
              f"a program that read the older copy is named: {items}")
        # An adopted program (nothing known of what it read) or one not
        # running is not judged; off the show PC there is no programs.json.
        items = w.check({"deck": {"running": True, "started": t0},
                         "flamesafe": {"running": False,
                                       "read": {fs: h_old}}})
        check(items[0]["behind"] == [CW.ENGINE],
              f"only what is known is said: {items}")
        check(w.check(None)[0]["behind"] == [CW.ENGINE],
              "off the show PC the engine's own copy is judged")
        # An Explorer copy keeps the source's older modified time and the
        # same size: still a change, by content.
        w5 = CW.ConfigWatch(wall=lambda: t0)
        p5 = put("copy.json", None, t0 - 50, raw=b'{"aim": [1]}')
        w5.add("flamesafe config", p5)
        put("copy.json", None, t0 - 50, raw=b'{"aim": [7]}')
        check(len(w5.check(None)) == 1,
              "a copy with the old modified time and size is still a change")
        # The same settings with a BOM and Windows line ends: no change.
        put("flamesafe.json", None, t0 + 90,
            raw=b"\xef\xbb\xbf" + json.dumps(old_doc, indent=1).replace(
                "\n", "\r\n").encode("utf-8"))
        w6 = CW.ConfigWatch(wall=lambda: t0)
        p6 = put("lf.json", None, t0, raw=json.dumps(
            old_doc, indent=1).encode("utf-8"))
        w6.add("flamesafe config", p6)
        put("lf.json", None, t0 + 5, raw=b"\xef\xbb\xbf" + json.dumps(
            old_doc, indent=1).replace("\n", "\r\n").encode("utf-8"))
        check(w6.check(None) == [], "a BOM and CRLF are not a change")
        # Changed back to what the engine read: cleared, and said.
        put("flamesafe.json", old_doc, t0 + 95)
        check(w.check(None) == [] and w.view()["text"] == "" and
              "as they are on disk" in lines[-1],
              f"changed back: cleared, and said: {lines[-1]!r}")
        os.remove(fs)
        items = w.check(None)
        check(items and items[0]["gone"] and "removed" in
              CW.notice_text(items), f"a removed file is said: {items}")
        # The rack screen settings: only what is read at start counts.
        rp = put("ltcplay_remote.json", {"screen_arming": False,
                                         "booth_alert": None}, t0 - 5)
        w2 = CW.ConfigWatch(wall=lambda: t0)
        w2.add("rack screen settings", rp,
               digest=CW.keys_hash(("booth_alert", "alert_pixels",
                                    "flamesafe_config")))
        put("ltcplay_remote.json", {"screen_arming": True,
                                    "booth_alert": None}, t0 + 5)
        check(w2.check(None) == [],
              "a setting read live (screen_arming) is not a change")
        put("ltcplay_remote.json", {"screen_arming": True,
                                    "booth_alert": {"device": "Booth"}},
            t0 + 6)
        check(len(w2.check(None)) == 1,
              "a setting read at start (booth_alert) is a change")
        with open(rp, "w", encoding="utf-8") as fh:
            fh.write("{ not json")
        check(len(w2.check(None)) == 1, "a broken file is a change")
        # Morning: the fuel block is read again live by fuel.py.
        mp = put("ltcplay_morning.json", {"machines": [1], "fuel": {"a": 1}},
                 t0)
        w7 = CW.ConfigWatch(wall=lambda: t0)
        w7.add("Morning settings", mp, digest=CW.without_hash(("fuel",)))
        put("ltcplay_morning.json", {"machines": [1], "fuel": {"a": 2}}, t0)
        check(w7.check(None) == [], "the fuel block alone is not a change")
        put("ltcplay_morning.json", {"machines": [2], "fuel": {"a": 2}}, t0)
        check(len(w7.check(None)) == 1, "the rest of it is")
        # The operator list: missing at start, then written by the
        # scheduler with its defaults: the same settings, no notice.
        op = os.path.join(d, "ltcplay_operators.json")
        w8 = CW.ConfigWatch(wall=lambda: t0)
        w8.add("operator list", op, digest=CW.default_hash(
            {"operators": ["Andy", "Jeff"]}))
        with open(op, "w", encoding="utf-8") as fh:
            json.dump({"operators": ["Andy", "Jeff"]}, fh, indent=2)
        check(w8.check(None) == [],
              "the defaults written at first start are not a change")
        with open(op, "w", encoding="utf-8") as fh:
            json.dump({"operators": ["Andy", "Jeff", "Pico"]}, fh)
        check(len(w8.check(None)) == 1, "a name added is")
        # A file only the deck reads (ltcplay_deck.json).
        dp = put("ltcplay_deck.json", {"keys": {}}, t0 - 5)
        dh = CW.file_hash(dp)
        w3 = CW.ConfigWatch(wall=lambda: t0)
        w3.add("Stream Deck layout", dp, engine=False, others=(CW.DECK,))
        put("ltcplay_deck.json", {"keys": {"1": "front row"}}, t0 + 5)
        items = w3.check({"deck": {"running": True, "read": {dp: dh}}})
        check(items and items[0]["behind"] == [CW.DECK] and
              not w3.view()["engine_behind"] and
              CW.AIM_NOTE not in w3.view()["text"],
              f"a file the engine does not read names the deck only: "
              f"{items}")
        # showpc.json, as the supervisor says it in programs.json.
        items = w3.check({"supervisor": {"started": t0,
                                         "showpc": os.path.join(d,
                                                                "showpc.json"),
                                         "showpc_changed": ["port"],
                                         "changed_at": "01:56:00"}})
        txt = CW.notice_text(items)
        check(any(i["file"] == "showpc.json" and i["behind"] ==
                  [CW.SUPERVISOR] for i in items) and
              "showpc.json (changed 01:56:00: port; older copy in LTC "
              "Player itself)" in txt and _cfg_dashes(txt),
              f"showpc.json names LTC Player itself: {txt!r}")
        w3.add("flamesafe config", dp, others=(CW.FLAMESAFE,))
        check(w3.paths() == [os.path.abspath(dp)], "noted once")
    finally:
        _sh.rmtree(d, ignore_errors=True)
    print("  ok")


def test_config_watch_reloads_only_what_is_safe_and_is_quick():
    section("Settings changed on disk: the announcements are read again "
            "live once nothing plays and no show runs, and only when the "
            "new file is good; the check runs on its own thread and sees a "
            "change within seconds")
    import shutil as _sh
    from ltcplay import configwatch as CW
    from ltcplay import announce as AN
    d = tempfile.mkdtemp()
    try:
        ap = os.path.join(d, "ltcplay_announce.json")

        def put(device, mtime):
            with open(ap, "w", encoding="utf-8") as fh:
                json.dump({"device": device, "files": {
                    i: f"Announcements/{i}.wav" for i in AN.IDS}}, fh)
            os.utime(ap, (mtime, mtime))
        put("Old Speakers", 1_800_000_000.0)
        lines = []
        w = CW.ConfigWatch(journal=lines.append)
        w.add("announcements", ap)
        svc = AN.AnnounceService(ap, operators_folder=d)
        check(svc.device_name == "Old Speakers", "the file at start")
        busy = [True]
        w.set_reload(ap, lambda: svc.reload_if_idle(busy[0]))
        put("Booth Speakers", 1_800_000_100.0)
        items = w.check(None)
        t = w.view()["text"]
        check(len(items) == 1 and "it reads it again by itself once no show "
              "is running" in t and "Restart LTC Player" not in t and
              svc.device_name == "Old Speakers" and _cfg_dashes(t),
              f"during a show it waits, and says so: {t!r}")
        busy[0] = False
        svc.playing = AN.DELAYED
        items = w.check(None)
        check(items and "once no announcement is playing" in
              items[0]["waiting"] and svc.device_name == "Old Speakers",
              f"never while an announcement plays: {items}")
        svc.playing = None
        # Half written (a truncated save): the old settings stay, and the
        # notice says the file is not valid.
        with open(ap, "w", encoding="utf-8") as fh:
            fh.write('{"device": "Booth Spea')
        before = dict(svc.status_by_id)
        items = w.check(None)
        t = w.view()["text"]
        check(items and "the file is not valid" in t and
              "keeps the old settings" in t and
              svc.device_name == "Old Speakers" and svc.error == "" and
              svc.status_by_id == before and _cfg_dashes(t),
              f"a truncated file is never taken; the old settings stay: "
              f"{t!r} {svc.device_name!r} {svc.error!r}")
        os.remove(ap)
        items = w.check(None)
        check(items and "not valid" in items[0]["waiting"] and
              svc.device_name == "Old Speakers",
              f"nor a missing one: {items}")
        put("Booth Speakers", 1_800_000_200.0)
        items = w.check(None)
        check(items == [] and svc.device_name == "Booth Speakers" and
              svc.status()["device"] == "Booth Speakers" and
              any("read it again" in ln for ln in lines) and
              any(r.get("outcome") == "reloaded" for r in svc.journal),
              f"between shows a good file is read again, the status shows "
              f"the new value and it is journaled: {items} {lines}")
        # The optional keys travel with it (#158): a hand edit of the
        # level, the show outputs or the audio system is read again too.
        with open(ap, "w", encoding="utf-8") as fh:
            json.dump({"device": "Booth Speakers", "hostapi": "MME",
                       "show_outputs": [3, 4], "gain_db": -12,
                       "files": {i: f"Announcements/{i}.wav"
                                 for i in AN.IDS}}, fh)
        os.utime(ap, (1_800_000_300.0, 1_800_000_300.0))
        items = w.check(None)
        check(items == [] and svc.options == {
                  "hostapi": "MME", "show_outputs": (3, 4),
                  "gain_db": -12.0},
              f"show_outputs, gain_db and hostapi are read again: "
              f"{items} {svc.options}")
        # The picker's own save (save_device) is the engine's copy too.
        svc.config_watch = w
        real_list = AN.list_outputs
        AN.list_outputs = lambda sd: [{"index": 0, "name": "Booth Speakers",
                                        "channels": 2, "rate": 48000,
                                        "hostapi": "MME", "default": False}]
        try:
            svc._sd_obj = object()
            svc.save_device("Booth Speakers")
        finally:
            AN.list_outputs = real_list
        check(w.check(None) == [],
              "the picker's own save is never an edit the engine is "
              "behind on")
        # The engine's own save (the Programming screen's schedule) is its
        # copy: refresh.
        sp = os.path.join(d, "ltcplay_schedule.json")
        with open(sp, "w", encoding="utf-8") as fh:
            fh.write("{}")
        w.add("schedule", sp)
        with open(sp, "w", encoding="utf-8") as fh:
            fh.write('{"a": 1}')
        check(len(w.check(None)) == 1, "a hand edit is a change")
        w.refresh(sp)
        check(w.check(None) == [], "the engine's own save and reload is not")
        check(CW.CHECK_EVERY_S <= 2.0,
              f"checked every {CW.CHECK_EVERY_S} s, so the notice is up "
              f"within about 5 s")
        seen = threading.Event()
        w.start(lambda: (seen.set(), None)[1], every_s=0.05)
        try:
            with open(sp, "w", encoding="utf-8") as fh:
                fh.write('{"a": 2}')
            end = time.monotonic() + 5.0
            while time.monotonic() < end and not w.view()["text"]:
                time.sleep(0.02)
            check(seen.is_set() and "ltcplay_schedule.json" in
                  w.view()["text"],
                  f"its own thread found it: {w.view()}")
        finally:
            w.stop()
        w.set_reload(sp, lambda: 1 / 0)
        items = w.check(None)
        check(items and "ZeroDivisionError" in items[0]["waiting"] and
              "keeps the old settings" in items[0]["waiting"],
              f"a failing reload is said: {items}")
    finally:
        _sh.rmtree(d, ignore_errors=True)
    print("  ok")


def test_config_watch_on_the_status_and_reload_engine():
    section("Settings changed on disk: on /api/remote/status; Reload engine "
            "offered on the rack screen only between shows with nothing "
            "armed, firing or unknown, behind the Settings permission; the "
            "supervisor's restart-check says the same")
    import shutil as _sh
    import types as _ty
    from ltcplay import configwatch as CW
    from ltcplay import remote as RM
    from ltcplay import users as U
    from ltcplay import cli as CLI
    d = tempfile.mkdtemp()
    real_folder = RM.settings_folder
    RM.settings_folder = lambda: d
    try:
        fp = os.path.join(d, "flamesafe.json")
        with open(fp, "w", encoding="utf-8") as fh:
            fh.write("{}")
        w = CW.ConfigWatch()
        w.add("flamesafe config", fp, others=(CW.DECK, CW.FLAMESAFE))
        rm = RM.Remote(None, None, folder=d, log=lambda t: None)
        rack, ipad = RM.Ctx(True, "127.0.0.1"), RM.Ctx(False, "10.0.0.9")
        check(rm.config_changed_view(rack) == {"files": [], "text": "",
                                               "engine_behind": False},
              "no watch: nothing")
        rm.config_watch = w
        with open(fp, "w", encoding="utf-8") as fh:
            fh.write('{"aim": [1, 7, 13]}')
        w.check(None)
        groups = [{"name": "wave flamer", "armed": "disarmed",
                   "wanted": False}]
        fresh = {"stale": False}

        def fview():
            return dict(fresh, groups=groups)
        rm.flame_status = _ty.SimpleNamespace(view=fview)
        v = rm.config_changed_view(ipad)
        check("flamesafe.json" in v["text"] and "reload" not in v,
              f"a remote session reads the notice, with no button: {v}")
        v = rm.config_changed_view(rack)
        check(v["reload"]["offered"] is False and "supervisor" in
              v["reload"]["why"],
              f"off the show PC there is no supervisor to restart it: {v}")
        with open(os.path.join(d, "showpc.json"), "w",
                  encoding="utf-8") as fh:
            fh.write("{}")
        v = rm.config_changed_view(rack)
        check(v["reload"] == {"offered": True, "why": "",
                              "flamesafe": True},
              f"between shows, nothing armed: offered: {v}")
        code, body = rm.get("/api/remote/restart-check", rack)[:2]
        check(code == 200 and body == {"refusal": ""},
              f"the supervisor's check agrees: {code} {body}")
        code, body = rm.get("/api/remote/restart-check", ipad)[:2]
        check(code == 403, f"never from the network: {code}")

        def refused(word, what):
            why = rm.reload_engine_refusal() or ""
            got = rm.get("/api/remote/restart-check", rack)[1]
            check(word.lower() in why.lower() and
                  got.get("refusal") == why and _cfg_dashes(why),
                  f"refused {what}: {why!r} {got}")
        groups[0]["armed"] = "armed"
        refused("armed", "while a group is armed")
        code, body = rm.reload_engine({})
        check(code == 409 and not os.path.exists(
                  os.path.join(d, RM.RESTART_ENGINE_FILE)),
              f"and the press writes nothing: {code} {body}")
        groups[0]["armed"], groups[0]["wanted"] = "disarmed", True
        refused("armed", "while one is being armed")
        groups[0]["armed"], groups[0]["wanted"] = "held", False
        refused("armed", "while one is held")
        groups[0]["armed"] = "disarmed"
        fresh["stale"] = True
        refused("not seen", "while flamesafe's state is stale")
        fresh["stale"] = False
        keep = list(groups)
        groups.clear()
        refused("not seen", "while flamesafe lists no groups")
        groups.extend(keep)
        fs_was, rm.flame_status = rm.flame_status, None
        refused("not connected", "with no flamesafe status at all")
        rm.flame_status = _ty.SimpleNamespace(view=lambda: 1 / 0)
        refused("could not be checked", "when the check itself fails")
        rm.flame_status = fs_was
        rm.show_busy_for_reload = lambda: True
        refused("show is running", "while a show runs")
        del rm.show_busy_for_reload
        rm.announce = _ty.SimpleNamespace(playing="delayed")
        refused("announcement", "while an announcement plays")
        rm.announce = None
        rm.live_flame = _ty.SimpleNamespace(on=True)
        refused("live flame", "with live flame programming on")
        rm.live_flame = _ty.SimpleNamespace(on=False)
        rm.fireball = _ty.SimpleNamespace(
            summary=lambda: {"on": ["ignite"], "owner": "x"})
        refused("Fireball", "with the Fireball page in use")
        rm.fireball = _ty.SimpleNamespace(
            summary=lambda: {"on": [], "owner": None})
        mv = {"purge": True, "laser_tests_on": [], "laser_arm":
              {"armed": []}}
        rm.morning = _ty.SimpleNamespace(status_view=lambda: dict(mv))
        refused("purge", "with a purge selected or firing")
        mv["purge"], mv["laser_tests_on"] = False, ["L1"]
        refused("laser test", "with a laser test on")
        mv["laser_tests_on"], mv["laser_arm"] = [], {"armed": ["Left"]}
        refused("laser is armed", "with a laser armed")
        mv["laser_arm"] = {"armed": []}
        check(rm.reload_engine_refusal() is None, "all clear again")
        code, body = rm.reload_engine({})
        check(code == 200 and os.path.exists(
                  os.path.join(d, RM.RESTART_ENGINE_FILE)) and
              "flamesafe" in body["text"] and _cfg_dashes(body["text"]),
              f"pressed: the supervisor is asked to restart the engine: "
              f"{code} {body}")
        check("reload-engine" in RM.SETUP_POST_ROUTES and
              U.classify("/api/remote/reload-engine", {}) == "settings",
              "a setup route of the show machine, behind the Settings "
              "permission")
        code, body, _h = rm.post("/api/remote/reload-engine", {}, ipad)
        check(code == 403, f"never from the network: {code} {body}")
        st = rm.status(rack)
        check("flamesafe.json" in (st.get("config_changed") or {}).get(
                  "text", ""), f"on the status: {st.get('config_changed')}")
        # What `ltc serve` notes before it reads anything.
        args = _ty.SimpleNamespace(announce="", flamesafe_config=None)
        env_was = os.environ.pop(CLI.FLAMESAFE_ENV, None)
        os.environ[CLI.FLAMESAFE_ENV] = fp
        try:
            w2 = CLI._config_watch_at_start(
                args, os.path.join(d, "ltcplay_schedule.json"))
        finally:
            os.environ.pop(CLI.FLAMESAFE_ENV, None)
            if env_was is not None:
                os.environ[CLI.FLAMESAFE_ENV] = env_was
        names = {os.path.basename(p) for p in w2.paths()}
        check({"flamesafe.json", "ltcplay_schedule.json",
               "ltcplay_fire_ice.json", "ltcplay_operators.json",
               "ltcplay_morning.json", "ltcplay_deck.json",
               "ltcplay_announce.json", "ltcplay_remote.json"} <= names,
              f"every file the engine reads at start is noted: {names}")
    finally:
        RM.settings_folder = real_folder
        _sh.rmtree(d, ignore_errors=True)
    print("  ok")


def test_config_watch_supervisor_and_rack_screen_note():
    section("Settings changed on disk: the supervisor hashes what each "
            "program reads before it starts it, names the showpc.json "
            "settings changed since, logs a restart that leaves others on an "
            "older copy, asks the engine again before a restart (failing "
            "closed), and the rack screen shows the note and Reload engine")
    import shutil as _sh
    import http.server as _hs
    from ltcplay import configwatch as CW
    W, SUP, gone = _winpkg()
    d = tempfile.mkdtemp()
    srv = None
    try:
        check(SUP.showpc_changed({"port": 7878, "show_folder": "a"},
                                 {"port": 7879, "show_folder": "b"}) ==
              ["port"], "show_folder is followed by itself; port is not")
        fs = os.path.join(d, "flamesafe.json")
        for raw in (b'{"a": 1}\n', b'\xef\xbb\xbf{"a": 1}\r\n'):
            with open(fs, "wb") as fh:
                fh.write(raw)
            check(SUP.config_hash(fs) == CW.file_hash(fs),
                  f"the supervisor and the engine hash alike: {raw!r}")
        check(SUP.config_hash(os.path.join(d, "none.json")) is None,
              "a missing file is None on both sides")
        check(SUP.files_read("flamesafe", {"flamesafe_config": fs}) ==
              [os.path.abspath(fs)] and
              SUP.files_read("engine", {"flamesafe_config": fs}) == [] and
              len(SUP.files_read("deck", {"flamesafe_config": fs})) == 2,
              "flamesafe and the deck read flamesafe's config, the deck its "
              "layout too")

        class _P:
            def __init__(self, alive, started, proc=True, read=None):
                self._a, self.started_wall = alive, started
                self.proc = object() if proc else None
                self.read = read or {}

            def alive(self):
                return self._a
        t0 = 1_800_000_000.0
        os.utime(fs, (t0 + 61, t0 + 61))
        progs = {"flamesafe": _P(True, t0 + 65), "engine": _P(True, t0),
                 "deck": _P(True, t0)}
        note = SUP.restart_note("flamesafe", progs, fs,
                                clock_hms=lambda t: f"T{t - t0:+.0f}")
        check(note.startswith("flamesafe.exe started at T+65 with "
                              "flamesafe.json as changed at T+61") and
              "ltcplay.exe (started T+0)" in note and
              "ltcplay-deck.exe (started T+0)" in note and _cfg_dashes(note),
              f"the restart names who kept the older copy: {note!r}")
        progs["engine"] = _P(True, t0 + 70)
        progs["deck"] = _P(True, t0 + 70)
        check(SUP.restart_note("flamesafe", progs, fs) == "",
              "nothing to say when the others started after the change")
        pf = SUP.ProgramsFile(os.path.join(d, "p.json"))
        progs = {"flamesafe": _P(True, t0 + 65, read={fs: "h1"}),
                 "engine": _P(True, t0),
                 "deck": _P(True, t0, proc=False, read={fs: "h0"})}
        blk = SUP.supervisor_block(t0, os.path.join(d, "showpc.json"),
                                   ["port"], "01:56:00")
        pf.update(progs, {n: (["x"], "") for n in SUP.PROGRAMS}, blk)
        doc = json.load(open(os.path.join(d, "p.json"), encoding="utf-8"))
        check(doc["flamesafe"]["started"] == t0 + 65 and
              doc["flamesafe"]["read"] == {fs: "h1"} and
              "started" not in doc["deck"] and "read" not in doc["deck"] and
              doc["supervisor"]["showpc_changed"] == ["port"],
              f"programs.json carries the starts, what each read and "
              f"showpc.json's changes; an adopted program has neither: "
              f"{doc}")
        # The second check before a restart: the engine's own word, and
        # fail closed when it does not answer or answers nonsense.
        import socket as _so
        s_ = _so.socket()
        s_.bind(("127.0.0.1", 0))
        dead = s_.getsockname()[1]
        s_.close()
        why = SUP.engine_restart_refusal(dead)
        check(why and "left running" in why,
              f"no answer: the engine is not restarted: {why!r}")
        answer = [b'{"refusal": ""}']

        class _H(_hs.BaseHTTPRequestHandler):
            def do_GET(self):
                ok = self.path == "/api/remote/restart-check"
                self.send_response(200 if ok else 404)
                self.end_headers()
                self.wfile.write(answer[0] if ok else b"{}")

            def log_message(self, *a):
                pass
        srv = _hs.HTTPServer(("127.0.0.1", 0), _H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        port = srv.server_address[1]
        check(SUP.engine_restart_refusal(port) == "",
              "the engine says it may: restarted")
        state = [b'{"running": true}']
        answer[0] = b'{"refusal": ""}'
        _get = _H.do_GET

        def do_get(self):
            if self.path == "/api/state":
                self.send_response(200)
                self.end_headers()
                self.wfile.write(state[0])
                return
            _get(self)
        _H.do_GET = do_get
        busy, why = SUP.engine_restart_blocked(port)
        check(busy and "show is running" in why,
              f"a show running is refused first: {busy} {why!r}")
        state[0] = b'{"starting": true}'
        check(SUP.engine_restart_blocked(port)[0], "and one starting")
        state[0] = b'{}'
        answer[0] = b'{"refusal": "A flame group is armed."}'
        check(SUP.engine_restart_refusal(port) == "A flame group is armed.",
              "the engine says why not: refused with its words")
        check(SUP.engine_restart_blocked(port) ==
              (True, "A flame group is armed."),
              "every restart request asks the engine again, after the "
              "show check")
        answer[0] = b'["no"]'
        check("left running" in SUP.engine_restart_refusal(port),
              "an answer it cannot read: refused")
        check(SUP.engine_restart_blocked(dead)[0],
              "no engine answering: blocked, never restarted blind")
    finally:
        if srv is not None:
            srv.shutdown()
            srv.server_close()
        gone()
        _sh.rmtree(d, ignore_errors=True)
    page = screen_text()
    for need in ('<div class="pline warn" id="cfg-note" hidden></div>',
                 '<button class="b blue" id="cfg-reload" hidden>',
                 'setWarn("cfg-note", cn.text);',
                 '$("cfg-reload").hidden = !cn.offer || '
                 '!mayRow(s, "settings");',
                 'post("/api/remote/reload-engine", {})'):
        check(need in page, f"the rack screen has {need!r}")
    check(not re.search(r'LOCAL_FAULT\["cfg-note"\]', page),
          "the note is never a fault")
    import shutil
    node = shutil.which("node")
    if node is None:
        print("  (node not found: the note's words are not run here)")
        print("  ok")
        return
    js = _js_fn(page, "cfgNote") + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
t(JSON.stringify(cfgNote(null)) === '{"text":"","offer":false}', "none");
const base = {text:"Settings changed on disk: flamesafe.json."};
let r = cfgNote(base);
t(r.text === base.text && !r.offer, "no reload block: the text alone");
r = cfgNote(Object.assign({reload:{offered:true, why:"", flamesafe:true}}, base));
t(r.offer && r.text.includes("stop LTC Player and start it again"), "offered, flamesafe: " + r.text);
r = cfgNote(Object.assign({reload:{offered:false, why:"A flame group is armed."}}, base));
t(!r.offer && r.text.endsWith("Reload engine is not offered now: A flame group is armed."), "refused: " + r.text);
console.log(JSON.stringify(out));
"""
    rr = _node_js(node, js, capture_output=True, text=True, timeout=60)
    try:
        bad = json.loads(rr.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        bad = None
    check(rr.returncode == 0 and bad == [],
          f"cfgNote in node: {rr.stdout!r} {rr.stderr[-400:]!r}")
    print("  ok")


def test_users_sign_out_after_the_last_show():
    """Jeff, 2026-10-26: once the night's last show has ended, and N
    minutes have passed (default 10, 0 is off), everyone signed in is
    signed out, once for that night; a sign-in after that stays; never
    while a show is live, held or an Abort stands; no schedule, never."""
    section("users: everyone is signed out N minutes after the last show "
            "of the night (default 10, 0 off), once a night; a later "
            "sign-in stays; never while live, held or aborted")
    import shutil
    import types
    from datetime import datetime, timezone
    from ltcplay import users as U
    from ltcplay import remote as RM
    d = tempfile.mkdtemp()
    try:
        t, clock = _u_clock()
        w = [1_800_000_000.0]
        notes = []
        us = U.Users(d, clock=clock, wall=lambda: w[0],
                     hash_params=_U_FAST,
                     audit=lambda **kw: notes.append(kw))
        us.add("Jeff", "admin", "jeff-temp-1")
        us.add("Andy", "admin", "andy-temp-1")
        us.sign_in("Jeff", "jeff-temp-1", True, "Rack screen",
                   new_password="right-pw-1")
        us.sign_in("Andy", "andy-temp-1", False, "iPad",
                   new_password="right-pw-2")
        check(us.last_show_minutes() == 10 and
              U.LAST_SHOW_SIGNOUT_DEFAULT_MIN == 10 and
              us.view()["signout_after_last_show_min"] == 10 and
              us.idle_minutes() == 0,
              "on by default at 10 minutes; idle sign out stays off")
        info = [None]
        us.last_show = lambda: info[0]

        def sin(name, pw, local=True, src="Rack screen"):
            ok, why, tok, _n = us.sign_in(name, pw, local, src)
            check(ok, f"setup: {name} signs in: {why}")
            return tok
        a = sin("Jeff", "right-pw-1")
        b = sin("Andy", "right-pw-2", False, "iPad")
        w[0] += 6 * 3600
        t[0] += 6 * 3600
        check(us.session(a) is not None and us.session(b) is not None,
              "no last show over (None from the engine): nobody is "
              "signed out, hours later")
        ended = w[0]
        info[0] = {"night": "2026-11-14", "ended": ended}
        w[0] = ended + 9 * 60 + 59
        check(us.session(a) is not None and us.machine_user() is not None,
              "9:59 after the last show ended: still signed in")
        c = sin("Andy", "right-pw-2", False, "iPad 2")   # inside the grace
        w[0] = ended + 10 * 60
        check(us.session(a) is None and us.session(b) is None and
              us.machine_user() is None,
              "10 minutes after: every session from before the show ended "
              "is signed out, and the deck acts as nobody")
        check(us.session(c) is not None,
              "a sign-in after the show ended (inside the grace) is not "
              "signed out (review of PR #125, P2-5)")
        us.sign_out(c)
        outs = [n for n in notes if n.get("action") == "sign-out" and
                "after the last show" in n.get("reason", "")]
        # Four sessions: the two first sign-ins (choosing a password), a
        # and b.
        check(len(outs) == 4 and {n["user"] for n in outs} ==
              {"Jeff", "Andy"} and all("—" not in n["reason"] and "–" not in
                                       n["reason"] for n in outs),
              f"each one journaled as signed out after the last show: "
              f"{outs}")
        e = sin("Jeff", "right-pw-1")
        w[0] += 3 * 3600
        t[0] += 60
        check(us.session(e) is not None,
              "a sign-in after it is not signed out again that night")
        us.after_last_show_tick()
        check(us.session(e) is not None, "nor by the engine's own beat")
        # An extra show (Start now) ends later the same night: the night
        # was already signed out once, so the later sign-in stays.
        info[0] = {"night": "2026-11-14", "ended": w[0]}
        w[0] += 3600
        us.after_last_show_tick()
        check(us.session(e) is not None,
              "a later show ending the same night signs nobody out again")
        # A restart (a new Users, the same file) with a sign-in after the
        # sign out: it is not signed out either.
        us2 = U.Users(d, clock=clock, wall=lambda: w[0], hash_params=_U_FAST)
        us2.last_show = lambda: info[0]
        ok, _w, f, _n = us2.sign_in("Jeff", "right-pw-1", True, "Rack")
        w[0] += 60
        check(ok and us2.session(f) is not None,
              "after a restart a later sign-in stays signed in")
        # The next night: again, once. The Stream Deck's own read (who
        # is signed in on this machine) finds it on its own.
        info[0] = {"night": "2026-11-15", "ended": w[0]}
        w[0] += 10 * 60
        check(us.machine_user() is None, "the next night's last show: the "
                                         "deck reads nobody signed in")
        check(us.session(e) is None, "signed out again, once")
        # Live, held, aborted: the engine says None; nothing happens.
        g = sin("Jeff", "right-pw-1")
        info[0] = None
        w[0] += 24 * 3600
        check(us.session(g) is not None, "while the engine says no: never")
        # A broken answer from the engine never signs anyone out.
        us.last_show = lambda: 1 / 0
        check(us.session(g) is not None, "an engine error: nothing")
        us.last_show = lambda: {"night": "2026-11-16"}
        check(us.session(g) is not None, "a half answer: nothing")
        # 0 is off.
        us.last_show = lambda: info[0]
        check("off" in us.set_last_show(0), "0 turns it off")
        info[0] = {"night": "2026-11-17", "ended": w[0] - 3600}
        check(us.session(g) is not None and us.last_show_minutes() == 0,
              "off: never signed out")
        check("30 min" in us.set_last_show(30) and
              us.view()["signout_after_last_show_min"] == 30,
              "an admin sets it in minutes")
        check(us.session(g) is None, "and on again it applies")
        for bad in (-1, 1441, True, "10", 2.5, None):
            try:
                us.set_last_show(bad)
                check(False, f"{bad!r} accepted")
            except ValueError as ex:
                check("0 (off) to 1440" in str(ex), f"{bad!r} refused")
        check(U.classify("/api/remote/last-show-signout", {}) == "settings"
              and "last-show-signout" in RM.USER_POST_ROUTES,
              "setting it is a Settings press, on the Users screen")
    finally:
        shutil.rmtree(d, ignore_errors=True)
    # The engine's side: when is the last show over?
    import threading as _th
    utc = timezone.utc
    end = datetime(2026, 11, 15, 4, 30, tzinfo=utc)
    early = datetime(2026, 11, 15, 2, 0, tzinfo=utc)

    def slot(ended=end, origin="rule"):
        return types.SimpleNamespace(ended_at=ended, origin=origin)

    def machine(**kw):
        base = dict(state="CLOSING", running=0, last_end=end,
                    date="2026-11-14",
                    pending=False, slots=(slot(early), slot(end)))
        base.update(kw)
        m = types.SimpleNamespace(**base)
        m.waiting = lambda: m.pending
        return m

    def rig(m, look=None, latched=False, playing=False):
        svc = types.SimpleNamespace(
            machine=m, conductor=types.SimpleNamespace(_look=look,
                                                       latched=latched))
        clk = types.SimpleNamespace(playing=playing)
        r = types.SimpleNamespace(
            schedule=svc, control=types.SimpleNamespace(
                session=types.SimpleNamespace(clock=clk)),
            _arm_lock=_th.Lock(), _holds={}, morning=None,
            flame_status=None, _last_show_seen=None)
        r.show_live_refusal = lambda: RM.Remote.show_live_refusal(r)
        r.rig_busy = lambda armed=False: RM.Remote.rig_busy(r, armed)
        r.ask = lambda: RM.Remote.last_show_over(r)
        return r

    def engine(m, **kw):
        return rig(m, **kw).ask()
    got = engine(machine())
    check(got == {"night": "2026-11-14", "ended": end.timestamp()},
          f"the last show ended: the night and when: {got}")
    check(engine(machine(state="IDLE")) == got and
          engine(machine(state="OFF")) == got,
          "standing dark after the night closed still counts")
    check(engine(machine(slots=(slot(end), slot(early, "operator")))) ==
          got, "the latest end counts, whatever the slot order")
    got_op = engine(machine(slots=(slot(early), slot(end, "operator"))))
    check(got_op == got, "a Start now show after the scheduled ones counts")
    for why, eng in (
            ("no schedule", lambda: RM.Remote.last_show_over(
                types.SimpleNamespace(schedule=None))),
            ("a show live", lambda: engine(machine(state="SHOW",
                                                   running=3))),
            ("paused", lambda: engine(machine(state="PAUSED", running=3))),
            ("on Hold", lambda: engine(machine(state="HOLD"))),
            ("the conductor holding", lambda: engine(machine(),
                                                     look="HELD")),
            ("a show still to come or delayed", lambda: engine(
                machine(state="STANDBY", pending=True))),
            ("the show clock playing", lambda: engine(machine(),
                                                      playing=True)),
            ("no show ended tonight (a restart's assumed end does not "
             "count)", lambda: engine(machine(slots=(slot(None),)))),
            ("a night with no show on the schedule, only Start now",
             lambda: engine(machine(slots=(slot(end, "operator"),))))):
        check(eng() is None, f"{why}: not over, nobody is signed out")
    # Anything going on at the rig: wait until it is clear (P2-5).

    class _Purge:
        fire = None
        selected = []

    class _Lasers:
        on = {}

    class _Arm:
        ids = []

        def armed_ids(self):
            return list(self.ids)

    class _Flames:
        def __init__(self):
            self.v = {"stale": False, "groups": [
                {"name": "front row", "armed": "disarmed", "wanted": False}]}

        def view(self):
            return self.v
    r = rig(machine())
    r.morning = types.SimpleNamespace(purge=_Purge(), lasers=_Lasers(),
                                      laser_arm=_Arm())
    r.flame_status = _Flames()
    check(r.ask() == got, "setup: a quiet rig, the last show is over")
    for why, on, off in (
            ("a purge firing",
             lambda: setattr(r.morning.purge, "fire", {"id": 1}),
             lambda: setattr(r.morning.purge, "fire", None)),
            ("machines armed for a purge",
             lambda: setattr(r.morning.purge, "selected", ["g1"]),
             lambda: setattr(r.morning.purge, "selected", [])),
            ("a laser test on",
             lambda: setattr(r.morning.lasers, "on", {"l1": {}}),
             lambda: setattr(r.morning.lasers, "on", {})),
            ("a laser armed",
             lambda: setattr(r.morning.laser_arm, "ids", ["l1"]),
             lambda: setattr(r.morning.laser_arm, "ids", [])),
            ("a flame group armed",
             lambda: r.flame_status.v["groups"][0].update(armed="armed"),
             lambda: r.flame_status.v["groups"][0].update(
                 armed="disarmed")),
            ("a deck hold (flamesafe: wanted)",
             lambda: r.flame_status.v["groups"][0].update(wanted=True),
             lambda: r.flame_status.v["groups"][0].update(wanted=False)),
            ("a screen's hold to arm",
             lambda: r._holds.update({0: {}}),
             lambda: r._holds.clear()),
            ("a rig state that cannot be read",
             lambda: setattr(r, "morning", None) or setattr(
                 r, "flame_status", types.SimpleNamespace(
                     view=lambda: 1 / 0)),
             lambda: setattr(r, "flame_status", _Flames()))):
        on()
        check(r.ask() is None, f"{why}: it waits")
        off()
        check(r.ask() == got, f"{why} over: it goes")
    # A night whose last show ended just before the 02:00 reset: the new
    # night (its shows still to come) carries the old night's end, so the
    # sign-out still comes (P2-8).
    r = rig(machine())
    check(r.ask() == got, "setup: the night's last show seen")
    r.schedule.machine = machine(date="2026-11-15", state="IDLE",
                                 pending=True, slots=(slot(None),),
                                 last_end=None)
    check(r.ask() == got, "after the reset the closed night's end still "
                          "counts")
    r.schedule.machine = machine(date="2026-11-15", state="SHOW",
                                 running=1, pending=True)
    check(r.ask() is None, "but never while the new night's show is live")
    r2 = rig(machine(state="STANDBY", pending=True))
    check(r2.ask() is None, "setup: a show still to come tonight")
    r2.schedule.machine = machine(state="STANDBY", pending=True,
                                  date="2026-11-14")
    check(r2.ask() is None, "the same night is never carried")
    # Users' own beat signs out with no page asking (P2-6).
    d2 = tempfile.mkdtemp()
    try:
        w2 = [1_800_000_000.0]
        u2 = U.Users(d2, wall=lambda: w2[0], hash_params=_U_FAST)
        u2.add("Jeff", "admin", "jeff-temp-1")
        u2.sign_in("Jeff", "jeff-temp-1", True, "Rack",
                   new_password="right-pw-1")
        ended2 = w2[0] + 1
        w2[0] += 3600
        u2.last_show = lambda: {"night": "n", "ended": ended2}
        u2.start(every_s=0.02)
        deadline = time.monotonic() + 5
        while u2._sessions and time.monotonic() < deadline:
            time.sleep(0.02)
        check(not u2._sessions, "the users' own beat signs out with no "
                                "session read at all")
        u2.stop()
        check(u2._beat is None, "and it stops with the engine")
    finally:
        shutil.rmtree(d2, ignore_errors=True)
    src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "ltcplay", "web.py"), encoding="utf-8").read()
    check("r.users.last_show = r.last_show_over" in src and
          "r.users.start()" in src and "r.users.stop()" in src,
          "web.serve gives the users the engine's answer")
    page = screen_text()
    check('post("/api/remote/last-show-signout", {minutes:lastShow})' in
          page and 'id="au-lastshow"' in page,
          "the Users screen has the setting and saves it")
    # A blank or wrong number is said and nothing is saved, never read as
    # 0 (off) (review of PR #125, P2-7).
    h = page[page.find('$("au-save").addEventListener'):]
    h = h[:h.find("});")]
    check(h.find("lastShowMinutes(") >= 0 and
          0 <= h.find("if(lastShow === null)") < h.find("post(") and
          "Nothing was saved" in h and "parseInt($(\"au-lastshow\")" not
          in h, "Save checks the minutes before it sends anything")
    import shutil as _sh2
    import json as _json2
    logic = page[page.find("// LOGIC BEGIN"):page.find("// LOGIC END")]
    check("function lastShowMinutes(" in logic, "lastShowMinutes is pure "
                                                "page logic")
    node = _sh2.which("node")
    if node:
        cases = [["", None], ["  ", None], ["abc", None], ["-1", None],
                 ["2.5", None], ["1441", None], ["99999", None],
                 [None, None], ["0", 0], ["10", 10], [" 30 ", 30],
                 ["1440", 1440]]
        js = logic + "console.log(JSON.stringify(" + _json2.dumps(cases) + \
            ".map(c => [c[0], lastShowMinutes(c[0]), c[1]])));"
        # Through a temporary file (_node_js): the logic block is over
        # Windows' 32,767 character command line (WinError 206).
        r = _node_js(node, js, capture_output=True, text=True, timeout=60)
        try:
            got = _json2.loads(r.stdout)
        except ValueError:
            got = None
        check(got is not None and all(g[1] == g[2] for g in got),
              f"the page reads the minutes right: {got or r.stderr[-300:]}")
    print("  ok")


def test_users_role_matrix_never_restricts_a_safety_press():
    section("users: the role matrix restricts only what is not safety; "
            "every route is classified; Abort, Hold, Stop and disarms "
            "always may")
    from ltcplay import users as U
    from ltcplay import remote as RM
    every = (RM.POST_ROUTES + RM.SETUP_POST_ROUTES + RM.USER_POST_ROUTES)
    missing = [r for r in every if r not in U.REMOTE_ROUTES]
    check(not missing, f"every remote POST route has a row: {missing}")
    safety = ("stop", "hold", "disarm-all", "group-disarm", "arm-release",
              "alert", "purge-stop", "purge-clear", "signin", "signout")
    for r in safety:
        check(U.classify("/api/remote/" + r, {}) == "safety",
              f"{r} is a safety press")
    check("abort" not in U.REMOTE_ROUTES and
          U.classify("/api/remote/abort", {}) is None,
          "there is no Abort row: the route is gone (Jeff, 2026-10-30)")
    for r, body in (("purge-select", {"on": False}),
                    ("purge-fire", {"on": False}),
                    ("laser-test", {"on": False}), ("laser-test", {}),
                    ("lock", {"kind": "machine", "id": "m1", "on": True}),
                    ("lock", {"kind": "machine", "id": "m1"})):
        check(U.classify("/api/remote/" + r, body) == "safety",
              f"{r} {body} only lowers risk: safety")
    check(U.classify("/api/remote/lock", {"on": False}) == "unlock" and
          U.classify("/api/remote/laser-test", {"on": True}) == "unlock" and
          U.classify("/api/remote/purge-select", {"machine": "a"}) == "arm"
          and U.classify("/api/remote/arm-hold", {}) == "arm" and
          U.classify("/api/remote/start-now", {}) == "show" and
          U.classify("/api/remote/network", {}) == "settings" and
          U.classify("/api/remote/users", {}) == "users",
          "risk-raising presses carry their row")
    check(U.classify("/api/stop") == "safety" and
          U.classify("/api/override", {"look": "blackout"}) == "safety" and
          U.classify("/api/start") == "show",
          "the old page's Stop and blackout are safety")
    m = U.normalise_matrix(None)
    for col in U.COLUMNS + ("nonsense",):
        role = None if col == U.SIGNED_OUT else col
        check(U.allowed(m, role, "safety") and U.allowed(m, role, None),
              f"{col}: safety and harmless presses always may")
    check(not any(U.allowed(m, None, p) for p in U.PERM_KEYS),
          "signed out is view only (2026-10-28): no run, no arm, no "
          "settings")
    check(U.allowed(m, "operator", "arm") and
          not U.allowed(m, "operator", "users") and
          not U.allowed(m, "viewer", "show") and
          all(U.allowed(m, "admin", p) for p in U.PERM_KEYS) and
          not U.allowed(m, "nonsense", "show"),
          "the proposed defaults")
    d = tempfile.mkdtemp()
    us = U.Users(d, hash_params=_U_FAST)
    us.add("Jeff", "admin", "jeff-temp-1")
    try:
        us.set_matrix({"admin": {"users": False}})
        check(False, "an admin's users cell could be turned off")
    except ValueError:
        pass
    us.set_matrix({"signed_out": {"arm": False}, "viewer": {"show": True}})
    check(not us.may(None, "arm") and us.may("viewer", "show") and
          us.may(None, "safety"), "the saved matrix is what decides")
    for bad in ({"pilot": {"arm": True}}, {"admin": {"fly": True}},
                {"admin": {"show": "yes"}}):
        try:
            us.set_matrix(bad)
            check(False, f"{bad} was accepted")
        except ValueError:
            pass


def _accounts_engine(seed=(("Jeff", "admin"), ("Vic", "viewer")),
                     transport=None):
    """A real engine on loopback with users and the audit log, and an
    http(path, body, cookie, window) helper."""
    import json as _j
    import urllib.request
    import urllib.error
    from ltcplay import web as W
    from ltcplay import users as U
    work = tempfile.mkdtemp()
    folder = tempfile.mkdtemp()
    httpd = W.serve(folder, port=0, bind="127.0.0.1", remote_folder=work)
    W._attach_accounts(httpd, users_seed=list(seed), transport=transport)
    httpd.remote.users._hash_params = _U_FAST
    threading.Thread(target=httpd.serve_forever,
                     kwargs={"poll_interval": 0.05}, daemon=True).start()
    base = f"http://127.0.0.1:{httpd.server_address[1]}"
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))

    def http(path, body=None, cookie=None, window=None):
        h = {"Content-Type": "application/json"}
        if cookie:
            h["Cookie"] = f"{U.COOKIE}={cookie}"
        if window:
            h["X-LTC-Window"] = window
        req = urllib.request.Request(
            base + path, data=None if body is None else _j.dumps(body).encode(),
            method="GET" if body is None else "POST", headers=h)
        try:
            with opener.open(req, timeout=10) as r:
                return r.status, _j.loads(r.read() or b"{}"), r.headers
        except urllib.error.HTTPError as e:
            return e.code, _j.loads(e.read() or b"{}"), e.headers

    def cookie_of(headers):
        c = headers.get("Set-Cookie") or ""
        return c.split(";")[0].split("=", 1)[1] if "=" in c else ""
    return httpd, http, cookie_of, work


def _audit_lines(folder):
    import json as _j
    from ltcplay import audit as A
    out = []
    for n in A.audit_files(folder):
        with open(os.path.join(folder, n), encoding="utf-8") as fh:
            out += [_j.loads(l) for l in fh if l.strip()]
    return out


# ------------------------------------------------ the SuperUser (2026-11-13)
# Jeff: "The 'upload log' feature is not something I want Andy to be able
# to turn off. Let's make a SuperUser function that is the only level that
# can see that." SUPERUSER.md; USERS.md, "The SuperUser"; the cold review
# of #251 (M1 to M6).

def _su_fast():
    """The local command line's pause after a wrong password, off for the
    selftest."""
    from ltcplay import users as U
    U.AUTH_FAIL_PAUSE_S = 0.0
    return U


def _su_users(folder=None):
    """A users file with Jeff a SuperUser (by the local command line, his
    own password), Andy an admin and Dallen an operator, each with their
    own password. (Users, folder, notes)."""
    U = _su_fast()
    d = folder or tempfile.mkdtemp()
    notes = []
    us = U.Users(d, hash_params=_U_FAST,
                 audit=lambda **kw: notes.append(kw))
    us.seed((("Jeff", "admin"), ("Andy", "admin"), ("Dallen", "operator")))
    for n in ("Jeff", "Andy", "Dallen"):
        ok, _w, _t, _n = us.sign_in(n, "", True, "Rack screen",
                                    new_password=f"{n.lower()}-own-pw-1")
        check(ok, f"{n} chooses a password")
    said = []
    rc = U.main(["superuser", "Jeff"], folder=d, who="account showpc",
                read_password=lambda _p: "jeff-own-pw-1", out=said.append)
    check(rc == 0 and us.role_of("Jeff") == U.SUPERUSER,
          f"the local command line makes Jeff a SuperUser: {rc} {said}")
    us.flush_pending_audit()
    return us, d, notes


def test_superuser_role_and_matrix():
    section("the SuperUser: one level above admin; every admin row fixed "
            "on; the upload row is the role's alone, never in a stored "
            "matrix, never in whoami's may, never ticked by any matrix "
            "edit, and refused with the same words as any unknown row; an "
            "older role list reads it as no role (fails closed)")
    U = _su_fast()
    check(U.ROLES[0] == U.SUPERUSER == "superuser" and
          U.ADMIN_ROLES == ("superuser", "admin") and
          U.COLUMNS == U.ROLES + (U.SIGNED_OUT,),
          f"roles: {U.ROLES}")
    check(U.UPLOAD not in U.PERM_KEYS and U.SUPERUSER_PERMS == ("upload",),
          "the upload row is not a row of the editable matrix")
    check(all(U.FIXED.get((U.SUPERUSER, p)) is True for p in U.PERM_KEYS),
          "every admin row is fixed on for a SuperUser")
    check(not any(s for s in U.SEED_USERS if s[1] == U.SUPERUSER),
          "a first run never makes a SuperUser")
    wild = {c: {p: True for p in U.PERM_KEYS + U.SUPERUSER_PERMS}
            for c in U.COLUMNS}
    m = U.normalise_matrix(wild)
    check(all(U.UPLOAD not in row for row in m.values()),
          "a stored upload cell is dropped, never kept")
    for role in ("admin", "operator", "viewer", None, "Superuser",
                 "superuser ", "root", ""):
        for mx in (wild, m, None, U.DEFAULT_MATRIX):
            check(not U.allowed(mx, role, U.UPLOAD),
                  f"{role!r} may never use the upload")
    check(U.allowed(None, U.SUPERUSER, U.UPLOAD) and
          all(U.allowed(m, U.SUPERUSER, p) for p in U.PERM_KEYS),
          "a SuperUser may use the upload and every admin row")
    off = U.normalise_matrix({"superuser": {p: False for p in U.PERM_KEYS}})
    check(all(off[U.SUPERUSER][p] for p in U.PERM_KEYS),
          "a stored SuperUser column off reads back on")
    us, d, _n = _su_users()

    def err(change):
        before = open(us.path, "rb").read()
        try:
            us.set_matrix(change)
            return None
        except ValueError as e:
            check(open(us.path, "rb").read() == before,
                  f"{change} left the users file as it was")
            return type(e).__name__, str(e).replace(
                "upload", "X").replace("fly", "X")
    unknown = err({"admin": {"fly": True}})
    for bad in ({"admin": {"upload": True}}, {"operator": {"upload": True}},
                {"superuser": {"upload": False}},
                {"signed_out": {"upload": True}}):
        check(err(bad) == unknown and unknown is not None,
              f"{bad}: refused with exactly the words of an unknown row "
              f"(no tell): {err(bad)} {unknown}")
    check(err({"superuser": {"settings": False}})[0] == "RankRefused",
          "a SuperUser's column cannot be turned off")
    us.set_matrix({"admin": {"show": True}, "viewer": {"show": True}})
    doc = json.load(open(us.path, encoding="utf-8"))
    check("upload" not in json.dumps(doc.get("matrix")),
          "a saved matrix never holds an upload cell")
    check(not us.may("admin", U.UPLOAD) and us.may(U.SUPERUSER, U.UPLOAD)
          and not us.may(None, U.UPLOAD),
          "the live check: admin no, SuperUser yes, nobody no")
    blank = U.Users(tempfile.mkdtemp(), hash_params=_U_FAST)
    check(not blank.may(U.SUPERUSER, U.UPLOAD) and
          blank.may(None, "settings"),
          "no users: the upload is refused (fail closed)")
    old_roles = U.ROLES
    try:
        U.ROLES = ("admin", "operator", "viewer")
        before = open(us.path, "rb").read()
        check(us.role_of("Jeff") is None and
              not any(U.allowed(U.normalise_matrix(None), "superuser", p)
                      for p in U.PERM_KEYS) and
              us.listing() and open(us.path, "rb").read() == before,
              "an older role list reads a SuperUser as no role, view only, "
              "and writes nothing")
    finally:
        U.ROLES = old_roles
    for n in ("journal-upload-now", "Journal-Upload", "upload-settings",
              "upload-card.js"):
        check(U.is_upload_route(n) and
              U.classify("/api/remote/" + n, {}) == U.UPLOAD,
              f"a route that says upload is the SuperUser's: {n}")
    from ltcplay import fuel as FU
    import types as _t
    act = _t.SimpleNamespace(active=lambda: True)
    for role, refill, undo in (("superuser", True, True),
                               ("admin", True, True),
                               ("operator", True, False),
                               ("viewer", False, False)):
        c = _t.SimpleNamespace(local=True, session={"name": "X",
                                                    "role": role})
        check(FU.may_refill(c, act)[0] is refill and
              FU.may_undo(c, act)[0] is undo,
              f"fuel: {role} refill {refill}, undo {undo}")
    check("upload" not in U.perm_label("settings").lower(),
          "the Settings row does not name the upload")
    print("  ok")


def test_superuser_every_users_edit_path():
    section("the SuperUser: only a SuperUser adds, changes the role of, "
            "resets, clears or removes a SuperUser, or makes one; an admin "
            "never raises their own role; the last SuperUser stays; a "
            "SuperUser's password is never cleared or claimed; each "
            "refusal changes nothing")
    U = _su_fast()
    us, d, notes = _su_users()

    def same(fn, what, by):
        before = open(us.path, "rb").read()
        try:
            fn()
            check(False, f"{what} went through for {by!r}")
        except U.RankRefused as e:
            check(str(e) == U.SUPERUSER_ONLY,
                  f"{what}: refused with the plain sentence: {e}")
        check(open(us.path, "rb").read() == before,
              f"{what} by {by!r} changed nothing in the file")
    for by in ("admin", None, "operator", "viewer", "Superuser", ""):
        same(lambda: us.add("Kim", U.SUPERUSER, "kim-temp-1", by=by),
             "add a SuperUser", by)
        same(lambda: us.set_role("Jeff", "admin", by=by),
             "demote a SuperUser", by)
        same(lambda: us.set_role("Jeff", "viewer", by=by),
             "make a SuperUser a viewer", by)
        same(lambda: us.set_role("Andy", U.SUPERUSER, by=by),
             "an admin raising their own role", by)
        same(lambda: us.set_role("Dallen", U.SUPERUSER, by=by),
             "make an operator a SuperUser", by)
        same(lambda: us.set_password("Jeff", "temp-pw-9", by=by),
             "reset a SuperUser's password", by)
        same(lambda: us.clear_password("Jeff", by=by),
             "clear a SuperUser's password", by)
        same(lambda: us.remove("Jeff", by=by), "remove a SuperUser", by)
    us.set_role("Dallen", "viewer", by="admin")
    us.set_password("Dallen", "dallen-temp-2", by="admin")
    us.clear_password("Dallen", by="admin")
    us.add("Kim", "operator", "kim-temp-1", by="admin")
    us.remove("Kim", by="admin")
    check(us.role_of("Dallen") == "viewer" and "Kim" not in us.names(),
          "an admin manages everyone but a SuperUser")
    us.add("Sam", U.SUPERUSER, "sam-temp-1", by=U.SUPERUSER)
    check(us.role_of("Sam") == U.SUPERUSER, "a SuperUser adds a SuperUser")
    us.set_role("Sam", "admin", by=U.SUPERUSER)
    us.set_role("Sam", U.SUPERUSER, by=U.SUPERUSER)
    us.set_password("Sam", "sam-temp-2", by=U.SUPERUSER)
    try:
        us.clear_password("Sam", by=U.SUPERUSER)
        check(False, "a SuperUser's password was cleared")
    except ValueError as e:
        check("never cleared" in str(e), f"never cleared: {e}")
    us.remove("Sam", by=U.SUPERUSER)
    for fn, what in ((lambda: us.set_role("Jeff", "admin",
                                          by=U.SUPERUSER), "demoted"),
                     (lambda: us.remove("Jeff", by=U.SUPERUSER),
                      "removed")):
        before = open(us.path, "rb").read()
        try:
            fn()
            check(False, f"the last SuperUser was {what}")
        except ValueError as e:
            check("last SuperUser" in str(e) and
                  open(us.path, "rb").read() == before,
                  f"the last SuperUser cannot be {what}: {e}")
    us.remove("Andy", by="admin")
    check("Andy" not in us.names(), "with a SuperUser, the last admin may go")
    try:
        U.Users(tempfile.mkdtemp(), hash_params=_U_FAST).seed(
            (("Jeff", U.SUPERUSER), ("Andy", "admin")))
        check(False, "a first run made a SuperUser")
    except ValueError:
        pass
    # A SuperUser's password is never claimed, even in a record this
    # build signed: none at all, or a temporary one a SuperUser did not
    # set (written here through the engine's own save, so it is trusted).
    for rec in ({"pw": None, "must_change": False},
                {"pw": U.hash_password("known-to-andy", params=_U_FAST),
                 "must_change": True, "reset_by": "admin"},
                {"pw": U.hash_password("known-to-andy", params=_U_FAST),
                 "must_change": True}):
        def put(doc, rec=rec):
            doc["users"]["Jeff"].update(rec)
            if "reset_by" not in rec:
                doc["users"]["Jeff"].pop("reset_by", None)
        us._change(put)
        check(us.role_of("Jeff") == U.SUPERUSER, "still a SuperUser")
        for local in (True, False):
            ok, why, tok, need = us.sign_in(
                "Jeff", "known-to-andy", local, "Rack screen",
                new_password="andy-takes-it-1")
            check(not ok and tok is None and not need,
                  f"a SuperUser's account is not claimed "
                  f"({rec.get('reset_by')}, local {local}): {why}")
        us.clear_lockouts()
    us.set_password("Jeff", "set-by-su-1", by=U.SUPERUSER)
    ok, _w, _t, need = us.sign_in("Jeff", "set-by-su-1", True, "Rack screen")
    check(not ok and need, "a SuperUser's temporary password asks for one")
    ok, _w, tok, _n = us.sign_in("Jeff", "set-by-su-1", True, "Rack screen",
                                 new_password="jeff-own-pw-2")
    check(ok and tok and us.role_of("Jeff") == U.SUPERUSER and
          "reset_by" not in json.load(open(us.path))["users"]["Jeff"],
          "and with their own it signs in, still a SuperUser")
    print("  ok")


def test_superuser_changed_outside_the_engine():
    section("the SuperUser record changed outside the engine (reviews of "
            "#251, M1, M2, B1): a SuperUser added by hand (even with a "
            "forged key and set), an older build's password reset (the "
            "hash alone too) or role change read as admin at once; a "
            "missing key, set record or fingerprint trusts NO SuperUser "
            "until one this program made confirms with the password it "
            "wrote; each is audited (superuser-set-changed) with a display "
            "only alert; nobody is ever promoted by it")
    U = _su_fast()
    from ltcplay import alerts as AL
    check("superuser" in AL.KINDS and "superuser" in AL.DISPLAY_ONLY and
          AL.SEVERITY["superuser"] == "warning",
          "the alert is display only: it never holds a show")
    us, d, notes = _su_users()
    got = []
    us.on_alert = got.append

    def hand(fn):
        doc = json.load(open(us.path, encoding="utf-8"))
        fn(doc)
        U._write_private(us.path, doc)
        us._doc = None

    def flush():
        del got[:]
        n0 = len(notes)
        us.flush_pending_audit()
        return [x for x in notes[n0:]
                if x["action"] == "superuser-set-changed"]

    def back():
        """Jeff a trusted SuperUser again, through the engine's own save,
        and nothing left to say."""
        us._lockdown = False
        us._change(lambda doc: doc["users"]["Jeff"].update(
            role="superuser"))
        flush()
        check(us.role_of("Jeff") == U.SUPERUSER and not us.lockdown(),
              "Jeff a SuperUser again")
    check(flush() == [] and got == [], "a consistent file raises nothing")
    # 1. Andy adds himself by hand.
    hand(lambda doc: doc["users"]["Andy"].update(role="superuser"))
    check(us.role_of("Andy") == "admin" and us.role_of("Jeff") ==
          U.SUPERUSER and
          [x for x in us.listing() if x["name"] == "Andy"][0]["unconfirmed"],
          "a SuperUser added by hand reads as admin at once; Jeff stays")
    lines = flush()
    check(lines and lines[0]["user"] == "unknown" and
          lines[0]["source"] == "outside the engine" and
          lines[0]["result"] == "error" and "Andy" in lines[0]["reason"] and
          got and "Andy" in " ".join(got[0]),
          f"audited and alerted: {lines} {got}")
    check(json.load(open(us.path))["users"]["Andy"]["role"] == "admin" and
          flush() == [], "the file is put right once, and says it once")
    # 2. The same with the key forged: Andy writes a new key, signs
    # himself and the set with it. The engine's own set (memory) says no.
    import hmac as _h
    import hashlib as _hl

    def forge(doc):
        k = b"k" * 32
        U._write_private(us.key_path, {"key": k.hex()})
        doc["users"]["Andy"]["role"] = "superuser"
        for n in ("Jeff", "Andy"):
            doc["users"][n]["su_fp"] = us._fp(k, n, doc["users"][n])
        doc["su_set"] = {"names": ["andy", "jeff"],
                         "sig": us._mac(k, ["su-set-1", ["andy", "jeff"]])}
    hand(forge)
    check(us.role_of("Andy") == "admin",
          "a forged key and set: Andy, not in the engine's own set, is an "
          "admin")
    check(any("differs" in x["reason"] or "Andy" in x["reason"]
              for x in flush()) and got, "and it is said")
    back()
    # 3. An older build resets Jeff's password: only the hash changes
    # (M2: the hash alone is fingerprinted).
    newh = U.hash_password("andy-knows", params=_U_FAST)["hash"]
    hand(lambda doc: doc["users"]["Jeff"]["pw"].update(hash=newh))
    check(us.role_of("Jeff") == "admin", "a changed hash alone: admin now")
    check(any("Jeff" in x["reason"] for x in flush()) and got, "said")
    check(json.load(open(us.path))["users"]["Jeff"]["role"] == "admin",
          "demoted in the file, never deleted")
    check(not us.may_confirm("Jeff"),
          "a password changed outside the engine cannot confirm: whoever "
          "set it knows it (SUPERUSER.md's emergency procedure is the way "
          "back)")
    hand(lambda doc: doc["users"]["Jeff"].update(
        role="superuser"))
    us._doc = None
    check(us.role_of("Jeff") == "admin", "and a hand edit back is no way")
    flush()
    # The engine puts the password back as it was for the rest.
    doc = json.load(open(us.path, encoding="utf-8"))
    us._change(lambda d2: d2["users"]["Jeff"].update(
        pw=U.hash_password("jeff-own-pw-1", params=_U_FAST)))
    us._known_pw["jeff"] = U._pw_digest(json.load(open(us.path))["users"]
                                        ["Jeff"])
    back()
    # 4. An older build makes Jeff an admin: the set changed; Jeff, with
    # the password this program wrote, may confirm himself.
    hand(lambda doc: doc["users"]["Jeff"].update(role="admin"))
    lines = flush()
    check(any("No longer a SuperUser" in x["reason"] and "jeff" in
              x["reason"] for x in lines) and got,
          f"a SuperUser removed outside the engine is said: {lines}")
    check(us.may_confirm("Jeff") and not us.may_confirm("Andy"),
          "Jeff may confirm himself; Andy, never one, may not")
    try:
        us.confirm_superuser("Andy", "andy-own-pw-1", "Rack screen")
        check(False, "Andy confirmed himself")
    except ValueError:
        pass
    try:
        us.confirm_superuser("Jeff", "wrong", "Rack screen")
        check(False, "a wrong password confirmed")
    except ValueError:
        pass
    us.confirm_superuser("Jeff", "jeff-own-pw-1", "Rack screen")
    check(us.role_of("Jeff") == U.SUPERUSER and
          any(n["action"] == "superuser-confirmed" for n in notes),
          "Jeff confirmed, audited")
    flush()
    # 5. B1b: the key, the set record or a fingerprint removed: NO
    # SuperUser is trusted (lockdown), nobody is promoted, until Jeff
    # confirms with his password.
    for what, fn in (("the key", lambda doc: os.remove(us.key_path)),
                     ("the set record", lambda doc: doc.pop("su_set")),
                     ("a fingerprint",
                      lambda doc: doc["users"]["Jeff"].pop("su_fp"))):
        hand(fn)
        check(us.role_of("Jeff") == "admin" and us.lockdown(),
              f"{what} removed: lockdown, Jeff an admin")
        lines = flush()
        check(any("Missing" in x["reason"] for x in lines) and got,
              f"{what}: audited and alerted: {lines}")
        check(not us.may_confirm("Andy") and us.may_confirm("Jeff"),
              f"{what}: only Jeff may confirm")
        us.confirm_superuser("Jeff", "jeff-own-pw-1", "Rack screen")
        check(us.role_of("Jeff") == U.SUPERUSER and not us.lockdown() and
              flush() == [], f"{what}: Jeff confirmed; lockdown over")
    # A restarted engine remembers the set (the second copy) and lockdown.
    os.remove(us.key_path)
    fresh = U.Users(d, hash_params=_U_FAST)
    check(fresh.role_of("Jeff") == "admin" and fresh.lockdown() and
          fresh.may_confirm("Jeff"),
          "a restarted engine: the key gone is lockdown, from the second "
          "copy")
    fresh.confirm_superuser("Jeff", "jeff-own-pw-1", "Rack screen")
    us._doc = None
    us._known = None
    us._lockdown = False
    check(us.role_of("Jeff") == U.SUPERUSER, "confirmed")
    flush()
    # A SuperUser the local command line seems to have made, with no
    # line of its own in the audit log: not taken (B1c, B1d).
    def fake_cli(doc):
        doc["users"]["Andy"]["role"] = "superuser"
        doc["pending_audit"] = [{"action": "superuser-set", "user": "x",
                                 "id": "made-up", "target": "Andy",
                                 "source": U.LOCAL_COMMAND, "reason": "",
                                 "at": ""}]
        U._write_private(os.path.join(d, U.SU_SECOND),
                         {"names": ["andy", "jeff"], "pw": {}})
    hand(fake_cli)
    check(us.role_of("Andy") == "admin",
          "a pending line and a second copy without the command's own "
          "audit line make nobody a SuperUser")
    flush()
    us._write_second()
    # Found by another process first: still audited and alerted here.
    hand(lambda doc: doc["users"]["Andy"].update(role="superuser"))
    other = U.Users(d, hash_params=_U_FAST)
    other.set_idle(5)
    check(any("Andy" in x["reason"] for x in flush()) and got,
          "found by another process: still audited and alerted here")
    print("  ok")


def test_superuser_session_limit_and_password_again():
    section("a SuperUser's session ends after SUPERUSER_IDLE_S with no "
            "press whatever the admin's idle settings say; an admin's "
            "session is not touched by it; every upload change asks for "
            "the SuperUser's password again (review of #251, M3)")
    U = _su_fast()
    from ltcplay import remote as RM
    now = [1000.0]
    d = tempfile.mkdtemp()
    us, d, notes = _su_users(d)
    us._clock = lambda: now[0]
    check(U.SUPERUSER_IDLE_S == 15 * 60, "15 minutes")
    ok, _w, jt, _n = us.sign_in("Jeff", "jeff-own-pw-1", True, "Rack screen")
    ok, _w, at, _n = us.sign_in("Andy", "andy-own-pw-1", True, "Rack screen")
    us.set_idle(0)
    us.set_last_show(0)
    now[0] += U.SUPERUSER_IDLE_S - 5
    us.touch(at)
    check(us.session(jt) is not None, "Jeff before the limit")
    now[0] += 10
    check(us.session(jt) is None and us.session(at) is not None,
          "Jeff's session ended at the limit; Andy's, with no idle sign "
          "out, did not")
    check(any(x["action"] == "sign-out" and x["user"] == "Jeff" and
              "SuperUser idle" in x["reason"] for x in notes),
          "audited")
    ok, _w, jt, _n = us.sign_in("Jeff", "jeff-own-pw-1", True, "Rack screen")
    us.touch(jt)
    now[0] += U.SUPERUSER_IDLE_S - 1
    check(us.session(jt) is not None, "a press keeps it")
    # The password again, for every upload change.
    rem = RM.Remote.__new__(RM.Remote)
    rem.users, rem.audit, rem.uploader, rem.folder = us, None, None, d
    ctx = RM.Ctx(True, "127.0.0.1", session=us.session(jt), token=jt)
    for pw in (None, "", "wrong-one", "andy-own-pw-1"):
        code, out, _h = rem.users_post("audit-settings",
                                       {"enabled": False, "password": pw},
                                       ctx)
        check(code == 403 and out["error"] == RM.UPLOAD_PASSWORD,
              f"no change without Jeff's own password ({pw!r}): {code}")
    code, out, _h = rem.users_post("audit-settings",
                                   {"enabled": False,
                                    "password": "jeff-own-pw-1"}, ctx)
    check(code == 200, f"with it: {code} {out}")
    # The same for Send now, making someone a SuperUser and resetting a
    # SuperUser's password (verification review of #251, M3).
    import types as _t
    ran = []
    rem.uploader = _t.SimpleNamespace(run=lambda force=False: ran.append(1))
    for pw in (None, "andy-own-pw-1"):
        code, out, _h = rem.users_post("audit-upload-now", {"password": pw},
                                       ctx)
        check(code == 403 and out["error"] == RM.UPLOAD_PASSWORD,
              f"Send now without Jeff's password ({pw!r}): {code}")
    code, out, _h = rem.users_post("audit-upload-now",
                                   {"password": "jeff-own-pw-1"}, ctx)
    check(code == 200, f"Send now with it: {code} {out}")
    for body in ({"op": "role", "name": "Andy", "role": "superuser"},
                 {"op": "add", "name": "Kim", "role": "superuser",
                  "password": "kim-temp-1"}):
        for mine in (None, "wrong-pw-1"):
            b = dict(body, my_password=mine) if mine else dict(body)
            code, out, _h = rem.users_post("users", b, ctx)
            check(code == 403 and out.get("password_again") and
                  us.role_of(body["name"]) != U.SUPERUSER,
                  f"{body['op']} a SuperUser without Jeff's password "
                  f"({mine!r}): {code} {out}")
        code, out, _h = rem.users_post(
            "users", dict(body, my_password="jeff-own-pw-1"), ctx)
        check(code == 200 and us.role_of(body["name"]) == U.SUPERUSER,
              f"{body['op']} with it: {code} {out}")
    for body in ({"op": "password", "name": "Andy",
                  "password": "andy-temp-9"},
                 {"op": "role", "name": "Andy", "role": "admin"},
                 {"op": "remove", "name": "Kim"}):
        code, out, _h = rem.users_post("users", dict(body), ctx)
        check(code == 403 and out.get("password_again"),
              f"{body['op']} on a SuperUser without the password: {code}")
        code, out, _h = rem.users_post(
            "users", dict(body, my_password="jeff-own-pw-1"), ctx)
        check(code == 200, f"{body['op']} with it: {code} {out}")
    # Wrong passwords typed again never count toward the sign-in lockout
    # (last round of #251): someone at a borrowed SuperUser session
    # cannot lock Jeff out of signing in. They have their own small
    # counter, which pauses only the password typed again.
    us.clear_lockouts()
    for _i in range(U.FREE_TRIES + 3):
        check(not us.confirm("Jeff", "wrong-again", "Rack screen"),
              "a wrong password typed again")
    check(not us._locked([("name", "jeff"), ("from", "Rack screen")],
                         us._clock()),
          "wrong passwords typed again never lock Jeff's sign-in")
    ok, _w, jt2, _n = us.sign_in("Jeff", "jeff-own-pw-1", True,
                                 "Rack screen")
    check(ok and jt2, "Jeff still signs in at once")
    check(not us.confirm("Jeff", "jeff-own-pw-1", "Rack screen"),
          "the password typed again pauses after too many wrong ones")
    now[0] += U.LOCK_MAX_S + 1
    check(us.confirm("Jeff", "jeff-own-pw-1", "Rack screen"),
          "and takes the right one after the pause")
    print("  ok")


def test_superuser_local_command_line():
    section("the SuperUser is made only by the local command line on the "
            "show PC (ltcplay superuser NAME, the double-click launchers): "
            "the first one with their own password, every later one and "
            "every password reset with a CURRENT SuperUser's; passwords "
            "only asked for, hidden; a held file retried, an error a "
            "sentence; the running engine told of a reset by a signed "
            "signal file; no route reaches it")
    U = _su_fast()
    d = tempfile.mkdtemp()
    out = []
    it = [iter(())]

    def run(argv, answers=(), line="", **kw):
        it[0] = iter(answers)
        return U.main(argv, folder=d, who=kw.get("who", "x"),
                      read_password=lambda _p: next(it[0]),
                      read_line=lambda _p: line, out=out.append,
                      pause=kw.get("pause", lambda _s: None))
    check(run(["superuser", "Jeff"]) == 1 and
          "Start LTC Player once" in out[-1],
          f"no users file: nothing made: {out[-1:]}")
    notes = []
    us = U.Users(d, hash_params=_U_FAST, audit=lambda **kw: notes.append(kw))
    us.seed((("Jeff", "admin"), ("Andy", "admin")))
    before = open(us.path, "rb").read()
    check(run(["superuser", "Jeff"], ["anything"]) == 1 and
          open(us.path, "rb").read() == before,
          f"a name with no password yet is never made one: {out[-1]}")
    us.sign_in("Jeff", "", True, "Rack screen", new_password="jeff-own-1")
    us.sign_in("Andy", "", True, "Rack screen", new_password="andy-own-1")
    for argv in ([], ["superuser"], ["admin", "Jeff"], ["superuser", "Jeff",
                                                        "jeff-own-1"],
                 ["superuser", "Jeff", "--folder"], ["superuser", " "]):
        check(run(argv) == 2, f"usage for {argv} (never a password on "
                              f"the line)")
    check(run(["superuser", "Jeff"], ["andy-own-1"]) == 1 and
          us.role_of("Jeff") == "admin" and "own password" in out[-1],
          f"the first SuperUser needs their own password: {out[-1]}")
    try:
        us.promote_local("Jeff", "x", by_name="Andy",
                         by_password="andy-own-1")
        check(False, "the first SuperUser was made with Andy's password")
    except ValueError:
        check(us.role_of("Jeff") == "admin",
              "never with someone else's password, by any name")
    # A temporary password an admin set (and so knows) is not Jeff's own.
    us.set_password("Jeff", "andy-set-1", by="admin")
    check(run(["superuser", "Jeff"], ["andy-set-1"]) == 1 and
          us.role_of("Jeff") == "admin" and
          "not chosen their own password" in out[-1],
          f"never on a temporary password someone else knows: {out[-1]}")
    us.sign_in("Jeff", "andy-set-1", True, "Rack screen",
               new_password="jeff-own-1")
    check(run(["superuser", "Jeff"], ["jeff-own-1"],
              who="Windows account showpc") == 0 and
          us.role_of("Jeff") == U.SUPERUSER, f"made: {out[-2:]}")
    check(out[-1].startswith("Jeff is now a SuperUser") and
          "su_recovery" not in json.load(open(us.path, encoding="utf-8")),
          f"no recovery code is made or shown: {out[-1]!r}")
    # Its own audit line, written before it returned (B1d), with the id
    # the engine checks.
    from ltcplay import audit as A
    ad = A.default_folder(d)
    cli = [r for n in A.audit_files(ad) if A.parse_name(n)[1] == "cli"
           for r in A.read_lines(os.path.join(ad, n))[0]
           if r.get("action") == "superuser-set"]
    pend = json.load(open(us.path))["pending_audit"]
    check(len(cli) == 1 and cli[0]["user"] == "Windows account showpc" and
          cli[0]["target"] == "Jeff" and cli[0].get("id") and
          pend[-1]["id"] == cli[0]["id"] and
          A.verify_folder(ad)[0],
          f"the command's own audit line is in the log, chained: {cli}")
    check(not [n for n in os.listdir(d) if n.endswith(".tmp")],
          "written through the atomic write (no temp file left)")
    check(us.flush_pending_audit() >= 1 and us.flush_pending_audit() == 0,
          "the engine writes the audit line once")
    got = [n for n in notes if n["action"] == "superuser-set"]
    check(len(got) == 1 and got[0]["user"] == "Windows account showpc" and
          got[0]["source"] == U.LOCAL_COMMAND and got[0]["target"] == "Jeff"
          and "Jeff's password" in got[0]["reason"],
          f"audited: who, what, confirmed with whose password: {got}")
    # Now one exists: a current SuperUser's name and password, always.
    for line, answers in (("Andy", ["andy-own-1"]), ("Jeff", ["wrong"]),
                          ("", ["jeff-own-1"]), ("Nobody", ["x"])):
        check(run(["superuser", "Andy"], answers, line=line) == 1 and
              us.role_of("Andy") == "admin" and
              out[-1] == U.Users.NOT_A_SUPERUSER,
              f"Andy is not made one with {line!r}'s password: {out[-1]}")
    check(run(["superuser", "Andy"], ["jeff-own-1"], line="jeff") == 0 and
          us.role_of("Andy") == U.SUPERUSER,
          f"with Jeff's: made: {out[-3:]}")
    us.set_role("Andy", "admin", by=U.SUPERUSER)
    # A password reset: a current SuperUser's password, then the new one
    # twice; the running engine ends Jeff's sessions and lockout.
    ok, _w, tok, _n = us.sign_in("Jeff", "jeff-own-1", True, "Rack screen")
    for _i in range(7):
        us.sign_in("Jeff", "bad", False, "iPad")
    check(us.session(tok) is not None and us._locked(
        [("name", "jeff")], us._clock()), "Jeff signed in, and locked out")
    check(run(["superuser-password", "Jeff"], ["andy-own-1", "new-temp-1",
                                               "new-temp-1"],
              line="Andy") == 1, "never with an admin's password")
    check(run(["superuser-password", "Jeff"], ["jeff-own-1", "one-temp-1",
                                               "two-temp-1"],
              line="Jeff") == 1 and "did not match" in out[-1],
          "two different entries change nothing")
    check(run(["superuser-password", "Andy"], ["jeff-own-1", "a-temp-1",
                                               "a-temp-1"],
              line="Jeff") == 1, "only for a SuperUser")
    check(run(["superuser-password", "Jeff"], ["jeff-own-1", "new-temp-1",
                                               "new-temp-1"],
              line="Jeff") == 0 and os.path.exists(us.signal_path),
          f"reset, and the engine signalled: {out[-1]}")
    sig_txt = open(us.signal_path, encoding="utf-8").read()
    check(us.consume_signal() is True and not os.path.exists(us.signal_path)
          and us.session(tok) is None and
          not us._locked([("name", "jeff")], us._clock()),
          "the engine took it: Jeff's sessions ended, his lockout cleared")
    check(any(n["action"] == "superuser-signal" and n["result"] ==
              "accepted" for n in notes), "audited")
    ok, _w, tok2, _n = us.sign_in("Jeff", "new-temp-1", True, "Rack screen",
                                  new_password="jeff-own-x")
    with open(us.signal_path, "w", encoding="utf-8") as fh:
        fh.write(sig_txt)
    check(us.consume_signal() is False and us.session(tok2) is not None and
          "already used" in notes[-1]["reason"],
          "the same signal put back inside its time is refused (a replay)")
    us.set_password("Jeff", "new-temp-1", by=U.SUPERUSER)
    ok, _w, _t, need = us.sign_in("Jeff", "new-temp-1", True, "Rack screen")
    check(not ok and need, "the new one is temporary")
    us.sign_in("Jeff", "new-temp-1", True, "Rack screen",
               new_password="jeff-own-2")
    # A signal not signed, stale, or for nobody: ignored and said.
    key = us._key()
    t0 = us._wall()
    for doc, why in (({"name": "Jeff", "at": t0, "nonce": "n",
                       "sig": "0" * 64}, "not signed"),
                     ({"name": "Jeff", "at": t0 - 3600, "nonce": "n",
                       "sig": us._mac(key, ["su-signal-1", "Jeff",
                                            t0 - 3600, "n"])},
                      "too old"),
                     ({"name": "Andy", "at": t0, "nonce": "n",
                       "sig": us._mac(key, ["su-signal-1", "Andy", t0,
                                            "n"])},
                      "names no SuperUser"),
                     ("not json", "not readable")):
        ok, _w, tok, _n = us.sign_in("Jeff", "jeff-own-2", True,
                                     "Rack screen")
        with open(us.signal_path, "w") as fh:
            fh.write(doc if isinstance(doc, str) else json.dumps(doc))
        check(us.consume_signal() is False and us.session(tok) is not None
              and not os.path.exists(us.signal_path) and
              why in notes[-1]["reason"],
              f"a signal {why}: ignored, removed and said")
    # A file held by the engine (the cross-process lock): tried again.
    paused = []
    keep_wait, U.LOCK_WAIT_S = U.LOCK_WAIT_S, 0.1
    try:
        with U._file_lock(us.lock_path):
            rc = run(["superuser", "Andy"], ["jeff-own-2"], line="Jeff",
                     pause=paused.append)
    finally:
        U.LOCK_WAIT_S = keep_wait
    check(rc == 1 and len(paused) == U.LOCAL_TRIES - 1 and
          "Another program" in out[-1],
          f"a held lock: tried {U.LOCAL_TRIES} times, then a sentence: "
          f"{paused} {out[-1]}")
    real = U.Users.promote_local

    def boom(*a, **k):
        raise PermissionError(13, "Access is denied")
    U.Users.promote_local = boom
    try:
        rc = run(["superuser", "Andy"], ["jeff-own-2"], line="Jeff")
    finally:
        U.Users.promote_local = real
    check(rc == 1 and "could not be saved" in out[-1] and
          "Traceback" not in out[-1], f"an OSError is a sentence: {out[-1]}")
    # A command's own audit line missing (B1d): the engine says so.
    got_alert = []
    us.on_alert = got_alert.append
    us._audit_id = "not-in-the-log"
    us._change(lambda doc: us._pend(doc, "superuser-set", "x", "Jeff"))
    us._audit_id = None
    del got_alert[:]
    us.flush_pending_audit()
    check(any(n["action"] == "superuser-audit-missing" for n in notes) and
          got_alert, "a command line change with no audit line is said")
    # B1a: once a SuperUser has existed, the first SuperUser path is shut
    # while ANY ONE of the SuperUser's files is here (the mark, the key,
    # the second copy), whatever else is removed: the set record and the
    # fingerprints in the users file. Removing all three by hand is the
    # emergency procedure (test_superuser_emergency_procedure_by_hand).
    def strip(doc):
        doc.pop("su_set", None)
        for u in doc["users"].values():
            u.pop("su_fp", None)
    files = (us.key_path, os.path.join(d, U.SU_MARK),
             os.path.join(d, U.SU_SECOND))
    saved = {f: open(f, "rb").read() for f in files}
    for left in files:
        doc = json.load(open(us.path, encoding="utf-8"))
        strip(doc)
        U._write_private(us.path, doc)
        for f in files:
            if f != left and os.path.exists(f):
                os.remove(f)
            elif f == left:
                with open(f, "wb") as fh:
                    fh.write(saved[f])
        for who_ in ("Andy", "Jeff"):
            check(run(["superuser", who_], []) == 1 and
                  out[-1] == U.Users.EVER_REFUSED,
                  f"{who_} cannot take the first SuperUser path while "
                  f"{os.path.basename(left)} is here, and is not even "
                  f"asked for a password: {out[-1]}")
        fresh = U.Users(d, hash_params=_U_FAST)
        try:
            fresh.promote_local("Andy", "x", by_name="Andy",
                                by_password="andy-own-1")
            check(False, "promote_local took the first SuperUser path "
                         "again")
        except ValueError as e:
            check(str(e) == U.Users.EVER_REFUSED, f"refused: {e}")
        check(fresh.role_of("Jeff") == "admin" and fresh.role_of("Andy") ==
              "admin", "and nobody is promoted by any of it")
    # The packaged show PC has no Python: the same through ltcplay.exe.
    import builtins
    import contextlib
    import getpass
    import io
    from ltcplay import cli as CLI
    keep = (getpass.getpass, builtins.input)
    getpass.getpass = lambda _p="": "jeff-own-2"
    builtins.input = lambda _p="": "Jeff"
    try:
        with contextlib.redirect_stdout(io.StringIO()) as buf:
            rc = CLI.main(["superuser", "Andy", "--folder", d])
    finally:
        getpass.getpass, builtins.input = keep
    check(rc == 1 and U.Users.EVER_REFUSED in buf.getvalue(),
          f"ltcplay.exe superuser NAME is the same command: "
          f"{buf.getvalue()!r}")
    here = os.path.dirname(os.path.abspath(__file__))
    for f in ("remote.py", "web.py"):
        src = open(os.path.join(here, "ltcplay", f), encoding="utf-8").read()
        check("promote_local" not in src and
              "superuser_password_local" not in src and
              "users.main" not in src and "users_mod.main" not in src,
              f"{f} never calls the local command line's changes")
    # The double-click launchers: in the program folder, asking for the
    # name in their window; no password on any line.
    iss = open(os.path.join(here, "packaging", "windows", "installer.iss"),
               encoding="utf-8").read()
    for bat, cmd in (("Make me SuperUser.bat", "superuser"),
                     ("Reset SuperUser sign-in.bat", "superuser-password")):
        b = open(os.path.join(here, "packaging", "windows", bat),
                 encoding="utf-8").read()
        check(f'Source: "{bat}"; DestDir: "{{app}}"' in iss and
              f'"%~dp0ltcplay.exe" {cmd} "%NAME%"' in b and
              "set /p" in b and "pause" in b and
              b.count("ltcplay.exe\" ") == 1,
              f"{bat}: installed, asks for the name, passes no password")
        _no_dashes(b, bat)
    print("  ok")


def test_superuser_emergency_procedure_by_hand():
    section("Jeff's own way back (SUPERUSER.md, \"In an emergency\"): with "
            "LTC Player stopped, the SuperUser's three files removed by "
            "hand (and, for a forgotten password, his pw set to null in "
            "the users file), LTC Player starts, alerts once, trusts no "
            "SuperUser, and Make me SuperUser makes Jeff a working "
            "SuperUser again; a users file Jeff hand-edits while LTC "
            "Player is stopped never bricks it: it starts, alerts once, "
            "trusts no edited SuperUser for the upload until he confirms "
            "with his password on the rack screen, and then works")
    U = _su_fast()
    from ltcplay import remote as RM
    import shutil

    def engine(d):
        """LTC Player started on the settings folder `d`: (Users, notes,
        alerts, Remote)."""
        notes, alerts = [], []
        eng = U.Users(d, hash_params=_U_FAST,
                      audit=lambda **kw: notes.append(kw))
        eng.on_alert = alerts.append
        rem = RM.Remote.__new__(RM.Remote)
        rem.users, rem.audit, rem.uploader, rem.folder = eng, None, None, d
        return eng, notes, alerts, rem

    def rack(eng, rem, name, pw, new=None):
        """Signed in on the rack screen: (ctx, superuser_here)."""
        ok, why, tok, _n = eng.sign_in(name, pw, True, "Rack screen",
                                       new_password=new)
        check(ok, f"{name} signs in on the rack screen: {why}")
        ctx = RM.Ctx(True, "127.0.0.1", session=eng.session(tok), token=tok)
        return ctx, rem.superuser_here(ctx)

    def beats(eng, alerts, n=4):
        """The engine's beats: the alert is raised once, then never
        again for the same edit."""
        for _i in range(n):
            eng.flush_pending_audit()
            eng._doc = None
        return len(alerts)

    def make_me_superuser(d, pw, name="Jeff"):
        out = []
        rc = U.main(["superuser", name], folder=d, who="account showpc",
                    read_password=lambda _p: pw, read_line=lambda _p: "",
                    out=out.append, pause=lambda _s: None)
        return rc, out

    files = (U.SU_MARK, U.USERS_KEY, U.SU_SECOND, U.USERS_SIGNAL)
    # 1. The SuperUser role lost (the password known): delete the three
    # files, start, Make me SuperUser.
    us, d, _n0 = _su_users()
    check(all(os.path.exists(os.path.join(d, f)) for f in files[:3]),
          "a SuperUser leaves the mark, the key and the second copy")
    us = None                                   # LTC Player stopped
    for f in files:
        if os.path.exists(os.path.join(d, f)):
            os.remove(os.path.join(d, f))
    eng, notes, alerts, rem = engine(d)
    check(eng.active() and not eng.broken() and
          eng.role_of("Jeff") == "admin",
          f"it starts; Jeff reads as an admin: {eng.broken()!r}")
    check(beats(eng, alerts) == 1, f"one alert: {alerts}")
    ctx, here = rack(eng, rem, "Jeff", "jeff-own-pw-1")
    check(not here and not eng.ever_superuser(),
          "no SuperUser is trusted for the upload, and no SuperUser file "
          "came back by itself")
    rc, out = make_me_superuser(d, "jeff-own-pw-1")
    check(rc == 0 and "Jeff is now a SuperUser" in out[-1],
          f"Make me SuperUser takes the first path again: {out}")
    beats(eng, alerts)
    check(any(x["action"] == "superuser-set" and "removed by hand" in
              x["reason"] for x in notes) and len(alerts) == 2,
          "the engine writes it down with an alert: a SuperUser had been "
          "made here before")
    ctx, here = rack(eng, rem, "Jeff", "jeff-own-pw-1")
    check(here and eng.role_of("Jeff") == U.SUPERUSER and
          eng.role_of("Andy") == "admin",
          "Jeff is a working SuperUser on the running engine; Andy is not")
    code, body, _h = rem.users_post("audit-settings",
                                    {"enabled": False,
                                     "password": "jeff-own-pw-1"}, ctx)
    check(code == 200, f"and the upload's settings take his change: {code} "
                       f"{body}")
    eng2, _n2, alerts2, rem2 = engine(d)
    _c, here = rack(eng2, rem2, "Jeff", "jeff-own-pw-1")
    check(here and beats(eng2, alerts2) == 0,
          "after a restart too, with nothing to say")
    rc, out = make_me_superuser(d, "andy-own-pw-1", "Andy")
    check(rc == 1 and eng2.role_of("Andy") == "admin" and
          eng2.ever_superuser(),
          f"the files are back, so the first path is shut again: {out}")
    # 2. A forgotten password: the same, and Jeff's "pw" set to null in
    # the users file, so he chooses a new one on the rack screen.
    for f in files:
        if os.path.exists(os.path.join(d, f)):
            os.remove(os.path.join(d, f))
    doc = json.load(open(os.path.join(d, U.USERS_FILE), encoding="utf-8"))
    doc["users"]["Jeff"]["pw"] = None
    with open(os.path.join(d, U.USERS_FILE), "w", encoding="utf-8") as fh:
        json.dump(doc, fh, indent=2)            # a hand edit: no fsync, no
    eng, notes, alerts, rem = engine(d)         # fingerprints redone
    check(eng.active() and not eng.broken() and beats(eng, alerts) == 1,
          f"it starts and alerts once: {alerts}")
    _c, here = rack(eng, rem, "Jeff", "", new="jeff-new-pw-2")
    check(not here and not eng.ever_superuser(),
          "Jeff chooses a new password on the rack screen, as an admin; "
          "no SuperUser file came back by itself")
    check(eng.sign_in("Jeff", "", False, "iPad",
                      new_password="x-taken-1")[0] is False,
          "(a name with no password is claimed on the rack screen only)")
    rc, out = make_me_superuser(d, "jeff-new-pw-2")
    _c, here = rack(eng, rem, "Jeff", "jeff-new-pw-2")
    check(rc == 0 and here, f"Make me SuperUser: Jeff works again: {out}")
    beats(eng, alerts)
    # 3. Any hand edit of the users file while LTC Player is stopped: it
    # starts, says it once, trusts no edited SuperUser for the upload,
    # and Jeff confirms with his password on the rack screen.
    good = tempfile.mkdtemp()
    shutil.rmtree(good)
    shutil.copytree(d, good)

    def edit_pw_hash(doc):
        doc["users"]["Jeff"]["pw"]["hash"] = "00" * 32

    for what, fn, can_confirm in (
            ("Jeff's role", lambda doc: doc["users"]["Jeff"].update(
                role="admin"), True),
            ("the set record", lambda doc: doc.pop("su_set"), True),
            ("Jeff's fingerprint", lambda doc: doc["users"]["Jeff"].update(
                su_fp=5), True),
            ("odd values", lambda doc: doc.update(
                su_set="x", su_nonces=[1], pending_audit="x"), True),
            ("a SuperUser added", lambda doc: doc["users"]["Andy"].update(
                role="superuser"), None),
            ("the key", None, True),
            ("Jeff's password hash", edit_pw_hash, False)):
        shutil.rmtree(d)
        shutil.copytree(good, d)
        if fn is None:
            os.remove(os.path.join(d, U.USERS_KEY))
        else:
            doc = json.load(open(os.path.join(d, U.USERS_FILE),
                                 encoding="utf-8"))
            fn(doc)
            with open(os.path.join(d, U.USERS_FILE), "w",
                      encoding="utf-8") as fh:
                json.dump(doc, fh, indent=2)
        eng, notes, alerts, rem = engine(d)
        check(eng.active() and not eng.broken() and beats(eng, alerts) == 1,
              f"{what} edited by hand: it starts and alerts once: "
              f"{eng.broken()!r} {alerts}")
        ctx, here = rack(eng, rem, "Andy", "andy-own-pw-1")
        check(not here, f"{what}: Andy is never trusted for the upload")
        if can_confirm is None:
            continue
        if not can_confirm:
            check(not eng.may_confirm("Jeff") and
                  eng.role_of("Jeff") == "admin",
                  f"{what}: no confirm with a password set outside LTC "
                  f"Player (the emergency procedure is the way)")
            continue
        ctx, here = rack(eng, rem, "Jeff", "jeff-new-pw-2")
        check(not here and eng.role_of("Jeff") == "admin",
              f"{what}: Jeff is not trusted for the upload yet")
        code, body, _h = rem.users_post(
            "users", {"op": "confirm-superuser",
                      "my_password": "jeff-new-pw-2"}, ctx)
        check(code == 200, f"{what}: Jeff confirms on the rack screen: "
                           f"{code} {body}")
        ctx, here = rack(eng, rem, "Jeff", "jeff-new-pw-2")
        code, body, _h = rem.users_post("audit-settings",
                                        {"enabled": False,
                                         "password": "jeff-new-pw-2"}, ctx)
        check(here and code == 200 and beats(eng, alerts) == 1,
              f"{what}: then it works, with nothing more to say: {code} "
              f"{alerts}")
    print("  ok")


def test_superuser_cross_process_lock():
    section("every users file change takes a lock across processes: a "
            "change while another program holds it waits, then says so "
            "and changes nothing")
    U = _su_fast()
    us, d, _n = _su_users()
    other = U.Users(d, hash_params=_U_FAST)
    keep = U.LOCK_WAIT_S
    U.LOCK_WAIT_S = 0.2
    try:
        before = open(us.path, "rb").read()
        with U._file_lock(other.lock_path):
            try:
                us.set_idle(7)
                check(False, "a change went through under another's lock")
            except ValueError as e:
                check("Another program" in str(e) and
                      open(us.path, "rb").read() == before,
                      f"refused, nothing changed: {e}")
        us.set_idle(7)
        check(other.idle_minutes() == 7, "and goes through once it is free")
    finally:
        U.LOCK_WAIT_S = keep
    print("  ok")


