def types_ns(**k):
    import types
    return types.SimpleNamespace(**k)


def test_fireball_practice_vetoes_and_wiring():
    section("Fireball practice, the guards around it: Resume refused under "
            "the scheduler's lock, before the release of a Stop's Hold with "
            "nothing held; tonight's edits refused; the show runner starts "
            "nothing; Start now and the other routes refused at the press; "
            "the Show and Arm rows on any screen (the show PC with sign-in "
            "off); Done is safety; the flame link's record changes no byte; the clock's "
            "epoch; the playhead binds before the cues are released; the "
            "card and OPERATOR.md")
    import types
    from ltcplay import fireball_practice as FP
    from ltcplay import remote as RM
    from ltcplay import users as U
    from ltcplay import fire_ice as FI
    from ltcplay import flamelink as fl
    from ltcplay import clock as CK
    S = _sched()
    if S is None:
        return
    import tempfile as _tf
    import shutil
    work = _tf.mkdtemp()
    try:
        now = [_den(S, 17, 30)]
        svc = _svc(S, work, now).start(thread=False)
        loads = svc.night_loads
        check(loads >= 1, f"a night loaded counts: {loads}")
        svc.operator_press("stop-hold", "Andy", "Rack screen", confirmed=True,
                           detail="pressed Stop on the Rack screen, so the "
                                  "schedule is on Hold")
        check(svc.machine.state == S.HOLD and svc.machine.stop_hold,
              "a Stop's Hold")
        svc.resume_veto = lambda: FP.REFUSED_WHILE_OPEN
        svc.edit_veto = lambda: FP.REFUSED_WHILE_OPEN
        r = svc.operator_press("resume", "Andy", "Rack screen", surface=True)
        check(not r["ok"] and r["text"] == "Resume was refused: Fireball "
              "practice is open: press Done first." and
              svc.machine.state == S.HOLD and svc.stop_held(),
              f"Resume refused, the Stop's Hold stands: {r}")
        try:
            svc.edit_tonight({"op": "remove", "show": 1, "who": "Andy",
                              "screen": "rack screen"})
            check(False, "an edit of tonight was taken")
        except ValueError as e:
            check("Fireball practice is open" in str(e), f"{e}")
    finally:
        shutil.rmtree(work, ignore_errors=True)
    # Nothing held, a Stop's Hold standing (the night over): Resume would
    # release it with no _apply. Refused first.
    work = _tf.mkdtemp()
    try:
        now = [_den(S, 23, 30)]
        svc = _svc(S, work, now).start(thread=False)
        svc.tick()
        svc.tick()
        svc._stop_carry = {"night": "2026-11-14"}
        svc.resume_veto = lambda: FP.REFUSED_WHILE_OPEN
        st = svc.machine.state
        r = svc.operator_press("resume", "Andy", "Rack screen", surface=True)
        check(st not in (S.HOLD, S.PAUSED) and not r["ok"] and
              "Fireball practice is open" in r["text"] and svc.stop_held(),
              f"the night over ({st}): Resume refused, the Stop's Hold "
              f"stands: {r}")
        svc.resume_veto = None
        r = svc.operator_press("resume", "Andy", "Rack screen", surface=True)
        check(r["ok"], f"practice closed: Resume works again: {r}")
    finally:
        shutil.rmtree(work, ignore_errors=True)
    # The show runner: no start while practice is open.
    run = FI.ShowRunner.__new__(FI.ShowRunner)
    run.practice_refusal = lambda: FP.REFUSED_WHILE_OPEN
    check(run._refusal(None, None) == FP.REFUSED_WHILE_OPEN,
          "the runner refuses any start while practice is open")
    run.practice_refusal = lambda: ""
    check(run._refusal(None, None) == run.RUN_OFF, "closed: as before")
    run.practice_refusal = lambda: 1 / 0
    check("could not be asked" in run._refusal(None, None),
          "a veto that raises refuses")
    # The remote: routes refused at the press while practice is open.
    P = types.SimpleNamespace(blocking=True,
                              refusal=lambda: FP.REFUSED_WHILE_OPEN)
    fake = types.SimpleNamespace(fireball_practice=P)
    for name in ("start-now", "start-at-cue", "resume", "play-from", "jump",
                 "continue", "loop", "mark-a", "mark-b", "preroll-continue",
                 "announce-play", "schedule-file", "show-folder",
                 "show-select", "show-file-new", "reload-engine"):
        check(RM.Remote.fireball_practice_route_refusal(fake, name, {}) ==
              FP.REFUSED_WHILE_OPEN, f"{name} refused while practice is open")
    for name, body in (("stop", {}), ("hold", {}), ("disarm-all", {}),
                       ("pause", {}), ("follow", {}),
                       ("fireball-practice", {"action": "done"}),
                       ("live-flame", {"on": False}),
                       ("cleaning-beat", {"hold": False}),
                       ("fireball-timeline-save", {})):
        check(RM.Remote.fireball_practice_route_refusal(fake, name, body) ==
              "", f"{name} is never refused by practice")
    for name, body in (("live-flame", {"on": True}),
                       ("cleaning-beat", {"hold": True})):
        check(RM.Remote.fireball_practice_route_refusal(fake, name, body) ==
              FP.REFUSED_WHILE_OPEN, f"{name} on: refused")
    check(set(RM.PRACTICE_ENDS_ROUTES) == {"hold", "pause", "follow"},
          "a Hold, a Pause and Follow end practice")
    check(RM.Remote.programming_playback_refusal(fake) ==
          FP.REFUSED_WHILE_OPEN, "Start now's veto says practice")
    P.blocking = False
    check(RM.Remote.fireball_practice_route_refusal(fake, "resume", {}) == "",
          "closed: nothing refused")
    # Who may open and Step: the show PC or an admin, the Show and Arm
    # rows; sign-in off: the show PC only.
    def may(local, role, active=True, mx=None):
        f = types.SimpleNamespace(
            users_active=lambda: active,
            users=types.SimpleNamespace(
                matrix=lambda: mx or U.DEFAULT_MATRIX))
        ctx = types.SimpleNamespace(local=local, session={"role": role}
                                    if role else None)
        return RM.Remote._practice_may(f, ctx, "Step")
    check(may(True, "operator") == "", "an operator on the show PC")
    check(may(False, "operator") == "",
          "an operator on an iPad may Step (Jeff, 2026-11-08)")
    check("Show and Arm" in may(False, "viewer"), "a viewer: refused")
    no_arm = dict(U.DEFAULT_MATRIX, operator=dict(
        U.DEFAULT_MATRIX["operator"], arm=False))
    no_show = dict(U.DEFAULT_MATRIX, operator=dict(
        U.DEFAULT_MATRIX["operator"], show=False))
    check("Show and Arm" in may(True, "operator", mx=no_arm) and
          "Show and Arm" in may(True, "operator", mx=no_show),
          "an operator without the Arm row, or the Show row: refused")
    check(may(False, "admin") == "", "an admin anywhere")
    # Programming's own rule for moving the playhead is not loosened: it
    # is not what practice asks, and every other move stays refused for
    # an operator on an iPad while flames follow it.
    import inspect as _insp
    src = _insp.getsource(RM.Remote._practice_may)
    check("programming_move_refusal" not in src.split('"""')[-1] and
          "PROGRAMMING_MOVE_REFUSED" in _insp.getsource(
              RM.Remote.programming_move_refusal),
          "Step does not go through the playhead's move rule, which stays")
    check("Show and Arm" in may(True, None), "signed out: refused")
    check(may(True, None, active=False) == "" and
          "sign-in is off" in may(False, None, active=False),
          "sign-in off: the show PC only")
    check(U.classify("/api/remote/fireball-practice",
                     {"action": "open"}) == "arm" and
          U.classify("/api/remote/fireball-practice",
                     {"action": "step"}) == "arm" and
          U.classify("/api/remote/fireball-practice",
                     {"action": "beat"}) == "arm" and
          U.classify("/api/remote/fireball-practice",
                     {"action": "done"}) == "safety" and
          U.classify("/api/remote/fireball-practice", {}) == "safety",
          "open, Step and the beat are arm presses; Done is safety")
    # The flame link's record: the frame's own numbers, and not a byte of
    # any frame changes.
    noise = [((i * 37) % 251) + 1 for i in range(512)]
    cfg = fl.FlameLinkConfig.parse({"port": 5571, "universe": 1,
                                    "key": _fl_key(), "frame_stale_ms": 500})
    sent = {}
    seen = []
    oks = []
    # "raise": a record that raises anything (not only RuntimeError) never
    # reaches the sender: every frame still goes out, byte for byte, and
    # send_frame says it went (the sweep of #181 found this unguarded).
    errs = (ValueError("bad"), KeyError("k"), Exception("plain"),
            RuntimeError("broke"), ZeroDivisionError())
    for with_obs in (False, True, "raise"):
        clk = [1000.0]
        tc = [0]

        def state(tc=tc):
            return f"00:00:{tc[0] // 30:02d}:{tc[0] % 30:02d}", True
        lk = _flk_unguarded(cfg, cues=lambda t: noise, show_state=state,
                            clock=lambda clk=clk: clk[0])
        lk._sock = _FlSock()
        lk.seq = 7000          # the link starts its count at random
        lk.release()
        if with_obs == "raise":
            def boom(*a, n=[0]):
                n[0] += 1
                raise errs[n[0] % len(errs)]
            lk.sent_observer = boom
        elif with_obs:
            lk.sent_observer = lambda *a: seen.append((a, bytes(
                lk.show_sent)))
        for _ in range(20):
            tc[0] += 1
            clk[0] += 0.034
            try:
                ok = lk.send_frame()
            except BaseException as e:            # noqa: BLE001
                ok = "raised " + type(e).__name__
            if with_obs == "raise":
                oks.append(ok)
        sent[with_obs] = [d for d, _a in lk._sock.sent]
    check(sent[False] == sent[True] and len(sent[True]) == 20,
          "the record changes no byte of any frame")
    check(sent["raise"] == sent[False] and oks == [True] * 20,
          "a record that raises ValueError, KeyError, Exception, "
          "RuntimeError or ZeroDivisionError never reaches the sender: "
          f"every frame went, unchanged, and send_frame said so: {oks}")
    import json as _js
    frames = [_js.loads(d) for d in sent[True] if b'"flame"' in d]
    check(len(seen) == 20 and all(
        a[0] == f["mono"] and a[1] == f["tc"] and a[3] is True and
        a[2] == show for (a, show), f in zip(seen, frames)),
          "each record carries its frame's own mono, timecode and show part")
    a = CK.AudioMaster.__new__(CK.AudioMaster)
    a._epoch, a._mode = 12.5, "follow"
    check(a.heard_epoch() == (12.5, True), "following the audio")
    a._mode = "freerun"
    check(a.heard_epoch() == (12.5, False), "freerun: not against the audio")
    a._epoch = None
    check(a.heard_epoch() == (None, False), "no epoch")
    # The playhead binds the play before the flame cues are released.
    from ltcplay.playhead import ShowAudioPlayhead
    order = []

    class Sess:
        running = True

        def __init__(self):
            self._cue = None
            self.tl = types.SimpleNamespace(cues=[])

        def playhead_clock(self):
            return self

        def clock_play_from(self, s, check_only=False):
            if not check_only:
                self._cue = {"label": "Show", "position_s": 0.0}
                order.append("play")
            return None, s

        def clock_halt(self):
            order.append("halt")
            self._cue = None
    cond = types.SimpleNamespace(
        music_started=lambda: order.append("music"),
        show_starting=lambda *a, **k: (order.append("show_starting"),
                                       types.SimpleNamespace(ok=True))[1],
        intermission=lambda *a, **k: None)
    sess = Sess()
    ph = ShowAudioPlayhead(types.SimpleNamespace(session=sess),
                           types.SimpleNamespace(conductor=cond,
                                                 machine=None))
    ph._watch = lambda: None
    got = []
    ph.play_from(10.0, "Jeff", "Rack screen",
                 bind=lambda c: (got.append(c), order.append("bind")))
    check(order == ["play", "bind", "music", "show_starting"] and
          got and got[0] is sess._cue,
          f"bound to the clock's cue, before music_started and "
          f"show_starting: {order}")
    del order[:]

    def bad(c):
        raise ValueError("no")
    try:
        ph.play_from(10.0, "Jeff", "Rack screen", bind=bad)
        check(False, "a bind that failed was played")
    except ValueError:
        pass
    check(order == ["play", "halt"],
          f"a bind that fails stops the music; nothing is released: {order}")
    # The card and OPERATOR.md.
    here = os.path.dirname(os.path.abspath(__file__))
    page = open(os.path.join(here, "ltcplay", "web", "remote2.html"),
                encoding="utf-8").read()
    i = page.find('id="fbp"')
    card = page[i:page.find("</section>", i)]
    check(i > page.find('id="t-schedule"') > 0 and
          'data-safe class="b safe" id="fbp-done"' in card and
          "Done, Stop, any disarm or leaving this card disarms every group."
          in card and FP.FUEL_NOTE in card and 'id="fbp-deck"' in card and
          "Noted: " in js_all(page) and "The Fireball page pads stay live between steps." in
          card and "Timing edits go into the show's real timeline file." in
          card and "—" not in card and "–" not in card,
          "the card is on the Schedule tab, Done is a safe button, its lines")
    js = page[page.find("// ---- Fireball practice"):]
    check('action:"beat"' in js and 'action:"done"' in js and
          'TAB !== "schedule"' in js,
          "the card beats only while the Schedule tab shows it")
    doc = open(os.path.join(here, "OPERATOR.md"), encoding="utf-8").read()
    sec = doc[doc.find("## Fireball practice"):doc.find(
        "## The late limit")]
    check(sec and FP.REFUSE_VALVE_UNLIT.replace(" (0.1 s)", "") not in "" and
          "Valve Open has no Igniter lit when it opens" in sec and
          "Tanks charged: Purge on the Fireball page" in sec and
          "No software can see that" in sec and "—" not in sec and
          "–" not in sec,
          "OPERATOR.md says what practice does, in plain words")
    print("  ok")


def test_fireball_cues_never_drive_purge():
    section("the fireball timeline never drives Purge (59): not as a stage, "
            "not after a shot, not on Stop, Hold, the end of a show or an "
            "engine restart, whatever the FSEQ carries on 59")
    import shutil
    from ltcplay import fireball_cues as FQ
    from ltcplay import fireball_timeline as FT
    fseq = [255] * 512
    R = _fbq_rig([_st("fuel", "00:00:00:00", 100),
                  _st("air", "00:00:00:00", 100),
                  _st("igniter", "00:00:00:00", 100),
                  # The Valve after its Igniter has gone out (it opens only
                  # then: final review of #201), so the shot does fire.
                  _st("valve", "00:00:00:10", 90)])
    try:
        for state in ("empty", "charged", "unknown"):
            R.tank.tanks = {"fuel": state, "air": state}
            for f in range(0, 120):
                R.cue_obj = {"label": "Show"} if f == 0 else R.cue_obj
                check(R.frame(f, base=fseq)[58] == 0, f"{state} {f}")
        try:
            FT.check_stages([_st("purge", "00:00:01:00", 1)])
            check(False, "Purge accepted as a stage")
        except FT.TimelineError:
            pass
        src = open(FQ.__file__, encoding="utf-8").read()
        uses = [ln.strip() for ln in src.splitlines()
                if "PURGE_SLOT" in ln and not ln.strip().startswith("#")]
        check(uses == ["PURGE_SLOT = fbtl.PURGE_SLOT",
                       "out[PURGE_SLOT - 1] = 0"] and
              "purge_set" not in src,
              f"fireball_cues.py only ever ZEROES the purge slot, and has "
              f"no purge call: {uses}")
        # Not from an FSEQ show either (review of #187: Purge by hand
        # only), whatever the tanks say.
        R.session.timeline_path = "Plain.json"
        for state in ("empty", "charged", "unknown"):
            R.tank.tanks = {"fuel": state, "air": state}
            R.cue_obj = {"label": "Show"}
            check(all(R.frame(f, base=fseq)[58] == 0
                      for f in range(0, 60, 7)),
                  f"an FSEQ show, tanks {state}: 59 zero")
    finally:
        shutil.rmtree(R.work, ignore_errors=True)
    print("  ok")


def test_fireball_timeline_equals_an_equivalent_fseq():
    section("the fireball timeline through the real flame cues equals an "
            "FSEQ that carries the same windows: every frame of the show, "
            "every channel, compared")
    import random
    import shutil
    import types
    import test_show_fixtures as _fx
    F = _fi_mod()
    from ltcplay import fireball_cues as FQ
    from ltcplay import fireball_timeline as FT
    rng = random.Random(20261030)
    work = tempfile.mkdtemp()
    try:
        show = os.path.join(work, "show")
        os.makedirs(show)
        with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
            fh.write(_FI2_NETWORKS.format(extra="", name="Flames",
                                          state="Inactive", after=""))
        frames, step = 600, 25            # 15 s at 40 fps
        noise = [bytes(rng.randrange(256) for _ in range(1022))
                 for _ in range(frames)]
        stages = []
        for k in FT.STAGE_KEYS:
            s0 = rng.randrange(0, 300)
            stages.append(_st(k, FT.tc_text(s0),
                              rng.choice([0.5, 1, 1.25, 2.4, 7, 30])))
        ent = {"stages": FT.check_stages(stages, 15.0)}
        wins = {slot: (s0 * 30, s1 * 30) for slot, s0, s1 in
                FT.windows(ent)}

        def j_of(f):              # the render frame cue frame f reads
            return int((f / 30.0) * 1000.0 // step)
        cue_frames = range(0, int(frames * step / 1000.0 * 30))
        baked = [bytearray(r) for r in noise]
        for r in baked:
            for s in (55, 56, 57, 58, 59):
                r[509 + s] = 0
        for f in cue_frames:
            for slot, (a, b) in wins.items():
                if a <= f < b:
                    baked[j_of(f)][509 + slot] = 255
        ra = os.path.join(show, "A.fseq")
        rb = os.path.join(show, "B.fseq")
        _fb_fseq_rows(ra, lambda i: bytes(baked[i]), frames, 1022, step)
        _fb_fseq_rows(rb, lambda i: noise[i], frames, 1022, step)

        def run(render, source):
            clk = types.SimpleNamespace(
                source="audio_master", paused=False,
                _cue={"label": "Show", "position_s": 0.0}, last_sent=None)
            sess = types.SimpleNamespace(
                running=True, clock=clk, timeline_path=os.path.join(
                    work, "Show.json"),
                player=types.SimpleNamespace(override=None,
                                             freerun_epoch=None),
                tl=types.SimpleNamespace(show_dir=show, cues=[
                    types.SimpleNamespace(name="Show", path=render)]))
            cues = F.FlameCues(types.SimpleNamespace(session=sess), "Flames")
            # A store of its own each run (a file once saved and then
            # removed is a fault now, never "no timeline").
            st = FT.Store(tempfile.mkdtemp(dir=work))
            ok, text, _e = st.save("Show.json", "Show", 15.0, source,
                                   stages, 0)
            tank = _FbcTank()
            cues.fireball = FQ.FireballCues(st, charge_get=lambda: tank)
            out = []
            for f in cue_frames:
                clk.last_sent = (0, f // 1800 % 60, f // 30 % 60, f % 30)
                v = cues(f"00:{f // 1800 % 60:02d}:{f // 30 % 60:02d}:"
                         f"{f % 30:02d}")
                tank.last_sent = bytes(v) if v else bytes(512)
                out.append(v)
            cues.close()
            return out
        a = run(ra, "fseq")
        b = run(rb, "timeline")
        diff = [f for f, (x, y) in enumerate(zip(a, b)) if x != y]
        check(len(a) == len(b) == len(cue_frames) and all(a) and not diff,
              f"{len(cue_frames)} frames, 512 channels each: the timeline "
              f"show and the equivalent FSEQ are identical: first "
              f"differences at {diff[:5]}")
        check(any(x[54] for x in b) and any(x[57] for x in b),
              "and the stages did fire in it")
        check(all(x[58] == 0 for x in b), "and Purge never")
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_fireball_cues_wiring():
    section("the fireball timeline in the engine: built before a show can "
            "run, the flame cues ask it on every frame, a save reaches it "
            "at once, the reading thread reads it before the layout; if it "
            "cannot be built, no fireball from any show (never the FSEQ)")
    import types
    from ltcplay import web as W
    from ltcplay import remote as RM
    from ltcplay import fireball_cues as FQ
    F = _fi_mod()
    work = tempfile.mkdtemp()
    wsrc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                             "ltcplay", "web.py"), encoding="utf-8").read()
    check("group_get=fireball_slots, live_get=live_slots," in wsrc and
          'if str(g.get("name", "")).strip().lower() != "fireball":' in wsrc
          and 'sl = g.get("fire_slots")' in wsrc,
          "the engine gives the cues the running flamesafe's fireball "
          "slots (round-6 review 1)")

    class _Svc:
        conductor = None
        machine = None

        def journal_press(self, *a, **kw):
            pass
    rm = RM.Remote(None, _Svc(), folder=work, log=lambda t_: None)
    cues = F.FlameCues(types.SimpleNamespace(session=None), "Flames")
    link = types.SimpleNamespace(cues=cues, journal_line=None)
    httpd = types.SimpleNamespace(remote=rm, fire_ice=types.SimpleNamespace(
        flame_link=link), morning=types.SimpleNamespace(groups=[
            {"name": "fireball", "safeties": [77],
             "fire": [59, 58, 57, 56, 55]}]))
    try:
        W._attach_fireball_timeline(httpd)
        check(isinstance(cues.fireball, FQ.FireballCues) and
              rm.fireball_cues is cues.fireball and
              cues.fireball._plan is not None and
              cues.fireball._plan[1] == "",
              "built, read, and on the flame cues")
        link.show_sent = bytes([7] * 512)
        check(cues.fireball._sent(None) == bytes([7] * 512),
              "the timeline reads the flame link's show_sent (the show's "
              "own values, before the Fireball page's frame)")
        link.landings, link.guard_gen = 3, 7
        check(cues.fireball._land_count() == 7,
              "and the flame link's guard generation (a landing or a seek "
              "it saw itself): a move for the fireball (review of #201)")
        check(cues.fireball._group == [55, 56, 57, 58, 59],
              f"it reads flamesafe's fireball group from the Startup page "
              f"(review C-4): {cues.fireball._group}")
        httpd.morning.groups[0]["fire"] = [451, 452, 453, 454, 455]
        cues.fireball.refresh()
        check(cues.fireball._group == [451, 452, 453, 454, 455],
              "and again on every read")
        httpd.morning.groups[0]["fire"] = [55, 56, 57, 58, 59]
        cues.fireball.refresh()
        st = rm.fireball_timeline_store()
        ok, _t, _e = st.save("S.json", "Show", 60.0, "timeline",
                             [_st("fuel", "00:00:01:00", 1)], 0)
        check(ok and cues.fireball._plan[0] == 1 and
              "S.json" in cues.fireball._plan[2],
              "a save reaches the flame cues at once")
        # The audit log set up after the store: the same store, so the
        # flame cues still hear of every save.
        rm.audit = types.SimpleNamespace(event=lambda **k: None)
        st2 = rm.fireball_timeline_store()
        st2.save("S.json", "Show", 60.0, "fseq", [], 1)
        check(st2 is st and cues.fireball._plan[0] == 2,
              "one store for the engine, its listeners kept")
        v = rm.status(RM.Ctx(True, "127.0.0.1")).get("fireball_timeline")
        check(v is not None and v["rev"] == 2 and v["fault"] == "",
              f"in the status: {v}")
        # Background mode (ltc serve): the timeline on the frames the
        # sender slices from memory, read by the reading thread.
        import test_show_fixtures as _fx
        show = os.path.join(work, "show")
        os.makedirs(show)
        with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
            fh.write(_FI2_NETWORKS.format(extra="", name="Flames",
                                          state="Inactive", after=""))
        render = os.path.join(show, "S.fseq")
        _fx.write_fseq(render, frame_count=200, channel_count=1022,
                       step_ms=25, compression="zlib", block_frames=50,
                       fill=90)
        st.save("S.json", "Show", 60.0, "timeline",
                [_st("valve", "00:00:00:00", 2)], 2)
        bclk = types.SimpleNamespace(
            source="audio_master", paused=False,
            _cue={"label": "Show", "position_s": 0.0},
            last_sent=(0, 0, 0, 1))
        bsess = types.SimpleNamespace(
            running=True, clock=bclk, timeline_path="S.json",
            player=types.SimpleNamespace(override=None, freerun_epoch=None),
            tl=types.SimpleNamespace(show_dir=show, cues=[
                types.SimpleNamespace(name="Show", path=render)]))
        bg = F.FlameCues(types.SimpleNamespace(session=bsess), "Flames",
                         background=True)
        bg.fireball = cues.fireball
        got = None
        # Read from the top (a first frame part way into a stage is a
        # landing inside it, which never starts it: review B of #201).
        for _ in range(200):
            got = bg("00:00:00:01")
            if got:
                break
            time.sleep(0.02)
        bg.close()
        check(got is not None and got[56] == 255 and got[54] == 0 and
              got[55] == 0 and got[0] == 90,
              f"background mode: the Valve Open stage on, the FSEQ's 55 to 59 "
              f"masked: {got and got[53:60]}")
        # It cannot be built: fail closed.
        rm2 = RM.Remote(None, _Svc(), folder=work, log=lambda t_: None)
        rm2.fireball_timeline_store = lambda: (_ for _ in ()).throw(
            OSError("no settings folder"))
        cues2 = F.FlameCues(types.SimpleNamespace(session=None), "Flames")
        W._attach_fireball_timeline(types.SimpleNamespace(
            remote=rm2, fire_ice=types.SimpleNamespace(
                flame_link=types.SimpleNamespace(cues=cues2,
                                                 journal_line=None))))
        got = cues2.fireball.apply([200] * 512, types.SimpleNamespace(
            timeline_path="Any.json"), "Show", 1.0, {})
        check(all(got[s - 1] == 0 for s in (55, 56, 57, 58, 59)) and
              got[0] == 200 and "could not be set up" in
              cues2.fireball.fault,
              "could not be built: 55 to 59 zero for every show")
        # The reading thread reads the timeline before the layout.
        order = []
        fb = types.SimpleNamespace(refresh=lambda: order.append("fb"))
        c3 = F.FlameCues(types.SimpleNamespace(session=types.SimpleNamespace(
            running=True, tl=None, nm_path=None)), "Flames")
        c3.fireball = fb
        real = c3._locate
        c3._locate = lambda s: order.append("layout") or real(s)
        c3._refresh_once()
        check(order[:2] == ["fb", "layout"], f"read first: {order}")
    finally:
        import shutil
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


_FBT_MEASURE_JS = r"""
<script>
(function(){
const posts = [];
const realFetch = window.fetch;
window.fetch = function(u, o){
  if(o && o.method === "POST") posts.push({u:String(u), b:String(o.body || "")});
  return realFetch.apply(this, arguments);
};
const wait = ms => new Promise(r => setTimeout(r, ms));
const q = id => document.getElementById(id);
function shown(el){ return !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden"; }
function look(el){
  const cs = getComputedStyle(el), r = el.getBoundingClientRect();
  return {id:el.id, dis:!!el.disabled, op:Number(cs.opacity), filt:cs.filter, shown:shown(el),
    r:[Math.round(r.left), Math.round(r.top), Math.round(r.right), Math.round(r.bottom)]};
}
async function go(){
  for(let i = 0; i < 60 && !document.querySelector("#fbt-rows .fbt-row"); i++) await wait(100);
  await wait(800);
  const res = {vw:innerWidth, sw:document.scrollingElement.scrollWidth, card:shown(q("fbt"))};
  res.rows = [...document.querySelectorAll("#fbt-rows .fbt-row")].map(r => ({k:r.dataset.k,
    used:r.querySelector(".use").getAttribute("aria-pressed"), label:r.querySelector(".use").textContent,
    start:r.querySelector(".st").value, dur:r.querySelector(".du").value,
    dis:r.querySelector(".st").disabled, h:Math.round(r.querySelector(".st").getBoundingClientRect().height),
    w:Math.round(r.getBoundingClientRect().right)}));
  res.src = [...document.querySelectorAll("#fbt-src .b")].filter(b => b.classList.contains("on")).map(b => b.dataset.v);
  res.bands = [...document.querySelectorAll("#fbt-bar i")].map(i => i.dataset.k);
  res.save = {dis:q("fbt-save").disabled, why:q("fbt-why").textContent};
  res.msg = q("fbt-msg").textContent;
  res.mini = ["m-hold", "m-stop", "m-disf"].map(id => look(q(id)));
  // No Abort sign (removed, Jeff, 2026-10-30): nothing can be under it.
  res.under = q("b-abort") ? ["an Abort sign is still drawn"] : [];
  // An edit: Air's start into the past of a frame 30, then a bad one.
  const air = document.querySelector('#fbt-rows [data-k="air"] .st');
  const typeIn = (el, v) => { el.value = v; el.dispatchEvent(new Event("input", {bubbles:true})); };
  if(!air.disabled){
    typeIn(air, "00:00:02:30");
    await wait(300);
    res.bad = {err:document.querySelector('#fbt-rows [data-k="air"] .err').textContent, save:q("fbt-save").disabled, why:q("fbt-why").textContent};
    q("fbt-save").click(); await wait(300);
    // The belt under the greyed Save: asked to save anyway, it refuses.
    fbtSave(false); await wait(300);
    res.bad.posts = posts.filter(p => p.u.indexOf("fireball-timeline-save") >= 0).length;
    res.bad.msg = q("fbt-msg").textContent;
    typeIn(air, "00:00:02:15");
    document.querySelector('#fbt-rows [data-k="igniter"] .use').click();
    typeIn(document.querySelector('#fbt-rows [data-k="igniter"] .st'), "00:00:04:00");
    typeIn(document.querySelector('#fbt-rows [data-k="igniter"] .du'), "0.5");
    document.querySelector('#fbt-src [data-v="timeline"]').click();
    await wait(300);
    res.good_save = {dis:q("fbt-save").disabled, why:q("fbt-why").textContent};
    q("fbt-save").click(); await wait(1200);
  } else {
    q("fbt-save").click(); await wait(300);
  }
  res.posts = posts.filter(p => p.u.indexOf("fireball-timeline") >= 0).map(p => ({u:p.u, b:JSON.parse(p.b)}));
  res.after = q("fbt-msg").textContent;
  const pre = document.createElement("pre"); pre.id = "rack-measure";
  pre.textContent = JSON.stringify(res);
  document.body.appendChild(pre);
}
go();
})();
</script>
"""


_FBT_FLOW_JS = r"""
<script>
(function(){
const posts = [];
const V = {rev:4, show_len_s:300.0, error:"", show_problem:"", default_source:"fseq",
  entry:{source:"fseq", stages:[{stage:"fuel", start:"00:00:01:00", dur_s:1.0}], edited_by:"Andy", edited_at:""}};
let lists = 0, other = null, saveAnswer = null, readMode = "ok", moreShows = [];
const realFetch = window.fetch;
const J = (o, code) => new Response(JSON.stringify(o), {status:code || 200, headers:{"Content-Type":"application/json"}});
const saved = () => { V.rev += 1; return J({ok:true, text:"Saved.", entry:{rev:V.rev}}); };
window.fetch = function(u, o){
  u = String(u);
  if(o && o.method === "POST" && u.indexOf("fireball-timeline-save") >= 0){
    posts.push(JSON.parse(String(o.body || "{}")));
    return new Promise((res, rej) => {
      if(o.signal) o.signal.addEventListener("abort", () => rej(new DOMException("aborted", "AbortError")));
      setTimeout(() => res(saveAnswer ? saveAnswer() : saved()), 800);
    });
  }
  if(u.indexOf("/api/timelines") >= 0){ lists++; return Promise.resolve(J({timelines:[{file:"Show.json"}, {file:"Other.json"}].concat(moreShows)})); }
  if(u.indexOf("/api/remote/fireball-timeline?") >= 0){
    if(u.indexOf("Other.json") >= 0) return new Promise(r => { other = () => r(J(Object.assign({}, V, {rev:9, entry:{source:"timeline", stages:[]}}))); });
    if(readMode === "fail") return Promise.resolve(J({error:"Not readable now"}, 503));
    if(readMode === "slow") return new Promise(r => setTimeout(() => r(J(JSON.parse(JSON.stringify(V)))), 1000));
    return Promise.resolve(J(JSON.parse(JSON.stringify(V))));
  }
  return realFetch.apply(this, arguments);
};
const wait = ms => new Promise(r => setTimeout(r, ms));
const q = id => document.getElementById(id);
const row = k => document.querySelector('#fbt-rows [data-k="' + k + '"]');
const du = () => row("fuel").querySelector(".du").value;
const typeIn = (el, v) => { el.value = v; el.dispatchEvent(new Event("input", {bubbles:true})); };
const tab = t => document.querySelector('.tab[data-tab="' + t + '"]').click();
const save = () => ({dis:q("fbt-save").disabled, why:q("fbt-why").textContent});
const locked = () => [...document.querySelectorAll("#fbt-rows input")].every(i => i.disabled);
const pick = f => { q("fbt-show").value = f; q("fbt-show").dispatchEvent(new Event("change", {bubbles:true})); };
const shown = id => !q(id).hidden;
async function go(){
  for(let i = 0; i < 60 && !document.querySelector("#fbt-rows .fbt-row"); i++) await wait(100);
  await wait(600);
  const res = {sel_h:Math.round(q("fbt-show").getBoundingClientRect().height), lists0:lists};
  typeIn(row("igniter").querySelector(".st"), "00:00:04:00");
  await wait(100);
  res.typed_used = row("igniter").querySelector(".use").getAttribute("aria-pressed");
  typeIn(row("igniter").querySelector(".du"), "0.5");
  typeIn(row("fuel").querySelector(".du"), "2,5");
  // Back to the tab and its read fails: the unsaved edit stays, Retry.
  // A show file added meanwhile is in the list once the tab opens.
  readMode = "fail";
  tab("day"); await wait(300);
  moreShows = [{file:"Added.json"}];
  tab("schedule"); await wait(900);
  res.f1 = {dur:du(), retry:shown("fbt-retry"), save:save(), msg:q("fbt-msg").textContent, locked:locked(), lists:lists,
    added:[...q("fbt-show").options].some(o => o.value === "Added.json")};
  // Retry, and while that read is on its way nothing may be typed or saved.
  readMode = "slow"; V.rev = 5;
  q("fbt-retry").click(); await wait(200);
  res.f2 = {locked:locked(), save:save(), retry:shown("fbt-retry")};
  await wait(1300);
  readMode = "ok";
  res.b1 = {dur:du(), save:save(), msg:q("fbt-msg").textContent, lists:lists};
  q("fbt-save").click(); await wait(300);
  res.b1.posts = posts.length;
  // Revert with an unsaved edit asks first.
  q("fbt-revert").click(); await wait(200);
  res.ask_rev = {shown:shown("fbt-ask"), dur:du(), q:q("fbt-ask").textContent};
  q("fbt-keep").click(); await wait(100);
  res.ask_rev.kept = {hidden:q("fbt-ask").hidden, dur:du()};
  q("fbt-revert").click(); await wait(100);
  q("fbt-drop").click(); await wait(600);
  res.revert = {save:save(), dur:du()};
  typeIn(row("fuel").querySelector(".du"), "2,5");
  await wait(100);
  q("fbt-save").click(); await wait(200);
  res.inflight = {locked:locked(), save:save()};
  await wait(1500);
  res.saved = posts.slice(-1)[0] || null;
  // Saved, and reading it back fails: said, the rows stay and stay open,
  // and the next save is against the revision just saved.
  typeIn(row("fuel").querySelector(".du"), "3");
  readMode = "fail";
  q("fbt-save").click(); await wait(1500);
  res.f4a = {msg:q("fbt-msg").textContent, retry:shown("fbt-retry"), dur:du(), locked:locked(), save:save(), rev:V.rev};
  readMode = "ok";
  typeIn(row("fuel").querySelector(".du"), "4");
  q("fbt-save").click(); await wait(1500);
  res.f4a.next = posts.slice(-1)[0] || null;
  // Another show with an unsaved edit asks first.
  typeIn(row("fuel").querySelector(".du"), "5");
  pick("Other.json"); await wait(200);
  res.ask_show = {shown:shown("fbt-ask"), sel:q("fbt-show").value, dur:du(), show_dis:q("fbt-show").disabled};
  q("fbt-keep").click(); await wait(100);
  res.ask_show.kept = {hidden:q("fbt-ask").hidden, dur:du(), sel:q("fbt-show").value};
  pick("Other.json"); await wait(100);
  q("fbt-drop").click(); await wait(300);
  res.b2 = {starts:[...document.querySelectorAll("#fbt-rows .st")].map(i => i.value),
    locked:locked(), save:save()};
  const n = posts.length;
  q("fbt-save").click(); await wait(200);
  res.b2.posts = posts.length - n;
  if(other) other();
  await wait(600);
  res.b2.after = {src:[...document.querySelectorAll("#fbt-src .b.on")].map(b => b.dataset.v), locked:row("fuel").querySelector(".st").disabled};
  typeIn(row("fuel").querySelector(".st"), "00:00:01:00");
  typeIn(row("fuel").querySelector(".du"), "1");
  // A save with no answer: given up, said, unlocked.
  FBT_POST_MS = 300;
  saveAnswer = () => new Promise(() => {});
  q("fbt-save").click(); await wait(150);
  res.f4d = {during:locked()};
  await wait(900);
  Object.assign(res.f4d, {msg:q("fbt-msg").textContent, locked:locked(), save:save()});
  FBT_POST_MS = 15000;
  saveAnswer = () => J({error:"Not saved: someone saved the fireball timeline since this screen read it. Press Revert to read it again, check the times, and save again."}, 409);
  q("fbt-save").click(); await wait(1300);
  res.refused = {save:save(), msg:q("fbt-msg").textContent};
  // Another show whose read fails: nothing loading, Save says so, Retry.
  readMode = "fail";
  pick("Show.json"); await wait(100);
  q("fbt-drop").click(); await wait(500);
  res.f1b = {why:q("fbt-why").textContent, retry:shown("fbt-retry"), starts:[...document.querySelectorAll("#fbt-rows .st")].map(i => i.value), locked:locked()};
  readMode = "ok";
  q("fbt-retry").click(); await wait(500);
  res.f1b.after = {locked:locked(), dur:du(), retry:shown("fbt-retry")};
  const pre = document.createElement("pre"); pre.id = "rack-measure";
  pre.textContent = JSON.stringify(res);
  document.body.appendChild(pre);
}
go();
})();
</script>
"""


# ---------------------------------------------------------------------------
# Interface 2.0, P11 and P13 (docs/REMOVE_1_0_PLAN.md): 1.0's machine map
# and Arrange mode on DAY's Purge step, and 1.0's show machine switches
# (Arming from a screen, Live flame programming On, the announcement
# output and its test tone) on the Programming cards. 1.0's own code.
# ---------------------------------------------------------------------------

_UI2_C_BLOCKS = (
    ("the ARRANGE block", "// ARRANGE BEGIN.", "// ARRANGE END", ()),
    ("the machine map", "  // The field: every machine where the layout "
     "puts it.", "  // The fire key's state.", ()),
    ("the announcement output picker", "// The announcement output "
     "picker: the engine's list of outputs", "// The Show network card",
     ()),
    ("Arming from a screen and Live flame programming",
     "// What the switch lets screens do: every one of it",
     "// The show's flame cues in Programming",
     ('''  const ban = $("lf-banner");
  ban.hidden = !on;
  if(on){
    const map = (lf.map || []).map(m => "universe " + m.universe + " to slots " + m.slots).join(", ");
    const rx = lf.receiving ? "receiving xLights" : ("no xLights data for " + (lf.last_data_s || 0) + " s");
    $("lf-banner-text").textContent = "xLights drives the flames through flamesafe. Only an armed group fires. " + rx + "; source: " + ((lf.sender && lf.sender.from) || ("none yet, allowed " + (lf.source || "this PC"))) + "; map fingerprint " + (lf.fingerprint || "?") + " (" + (map || "") + "). Turned on by " + (lf.who || "someone") + ".";
  }
''', '''$("lf-banner-off").addEventListener("click", liveFlameOff);
''')))


def test_ui2_arrange_and_switches_are_1_0s():
    section("2.0, P11 and P13: the ARRANGE block, the machine map, the "
            "announcement output picker, and Arming from a screen with Live "
            "flame programming are 1.0's code word for word (the one "
            "difference 1.0's live flame banner, 2.0's pinned line); 1.0's "
            "ids; Arrange, Arming from a screen and the announcement output "
            "on the show PC only; leaving the Purge step, the map or DAY "
            "leaves Arrange mode; no stub left that says nothing is ever "
            "arranging; OPERATOR.md")
    one, two = _ui2_pages()
    # The ARRANGE block's three 2.0 changes (review of #212, 1 and 4):
    # outside Arrange a machine is chosen by a tap (machUp), never by a
    # press, and the Arrange button keeps its icon. Everything else is 1.0's.
    w2, d2, u2 = (_js_function(two, n) or "" for n in ("wireMachine",
                                                       "machDown", "machUp"))
    w1, d1 = _js_function(one, "wireMachine") or "", \
        _js_function(one, "machDown") or ""
    i2 = two.find(d2) + len(d2)
    d2x = two[two.find(d2):two.find(u2) + len(u2)] if d2 and u2 else ""
    arr_sub = ((w1, w2), (d1, d2x),
               ('  if(ab){ ab.disabled = ARRANGE; ab.textContent = '
                '"Arrange"; }', '  if(ab){ ab.disabled = ARRANGE; }'))
    check("moPress(" not in d2 and "dragStart(e, m)" in d2 and
          'purgeTap(m.id);' in u2 and
          'return moPress("purge-select", {machine:id, on:on});' in two and
          "MACH_TAP_PX" in u2 and "MACH_TAP_MS" in u2 and
          'el.addEventListener("pointerup", e => machUp(e, m));' in w2 and
          "const MACH_TAP_PX = 8, MACH_TAP_MS = 600;" in two,
          "outside Arrange a press never chooses a machine: only a tap "
          "under 8 px and 600 ms does, with 1.0's body")
    check(".mach{" in two and "touch-action:pan-y" in
          two[two.find(".mach{"):two.find("}", two.find(".mach{"))] and
          ".mach.drag{touch-action:none}" in two,
          "a tile lets a swipe scroll; only while arranging does it hold "
          "the pointer")
    for what, a, b, drops in _UI2_C_BLOCKS:
        i = one.find(a)
        j = one.find(b, i)
        blk = one[i:j] if 0 <= i < j else ""
        if what == "the ARRANGE block":
            for o_, n_ in arr_sub:
                check(o_ and blk.count(o_) == 1,
                      f"1.0's ARRANGE block has {o_[:40]!r}")
                blk = blk.replace(o_, n_)
        for d in drops:
            check(blk.count(d) == 1, f"1.0's {what} has the dropped part "
                                     f"{d[:40]!r}")
            blk = blk.replace(d, "")
        if what == "the machine map":
            # The one named difference (Jeff, 2026-11-14): a selected tile
            # flamesafe has not armed says "Selected, not armed" and what
            # a tap does, never 1.0's "Press Clear, then click it again".
            o1 = blk.find("    const wait = machineWait(m, fl, purge,")
            o2 = blk.find("refusedNow = true;", o1) + len("refusedNow = true;")
            n1 = two.find("    // Jeff, 2026-11-14: a selected unit flamesafe has "
                          "not armed says so,")
            n2 = two.find("refusedNow = wait;", n1) + len("refusedNow = wait;")
            p1 = blk.find("  if(refusedNow && $(\"mo-msg\")")
            p2 = blk.find("}", blk.find("$(\"mo-msg\").title", p1)) + 1
            q1 = two.find("  if(refusedNow && !FIRE && refusedNow !== PURGE_SAID)")
            q2 = two.find("PURGE_SAID = refusedNow || \"\";", q1) + len(
                "PURGE_SAID = refusedNow || \"\";")
            ok = min(o1, n1, p1, q1) >= 0 and o1 < o2 and p1 < p2
            check(ok, "1.0's and 2.0's tile words are found")
            if ok:
                blk = (blk[:o1] + two[n1:n2] + blk[o2:p1] + two[q1:q2] +
                       blk[p2:])
        if what == "Arming from a screen and Live flame programming":
            # The one named difference (Jeff, 2026-11-11: less prose): the
            # switch's words are shorter; remote.py says the same (checked
            # with the screen arming switch).
            m1 = re.search(r'const SCREEN_ARMING_ENABLES = "[^"]*";', blk)
            m2 = re.search(r'const SCREEN_ARMING_ENABLES = "[^"]*";', two)
            check(m1 and m2, "the arming switch's words are found")
            if m1 and m2:
                blk = blk.replace(m1.group(0), m2.group(0))
        check(len(blk) > 300 and blk in two,
              f"2.0's {what} is 1.0's code, word for word ({len(blk)} "
              f"characters)")
    check("const ARRANGE = false;" not in two and
          "function arrangeBlocked(){ return false; }" not in two and
          two.count("function openBeatBody(") == 1 and
          two.count("const BEAT_INST =") == 1,
          "2.0's stubs (no Arrange mode) are gone; one open beat, 1.0's")
    lz = _js_function(two, "lzTileClick") or ""
    check(0 < lz.find('if(arrangeBlocked("laser-arm", {on:true})) return null;')
          < lz.find("confirmBox("),
          "an Arm all lasers is held back in Arrange mode before its "
          "question, as 1.0's lzClick")
    check("if(ARRANGE) mapOff();\n      try{ const r = await post(\"/api/remote/signout\""
          in two, "signing out ends Arrange mode")
    end = two.rsplit("// END OF THE COPY.", 1)
    check(len(end) == 2 and "// ARRANGE BEGIN." in end[0],
          "the ARRANGE block is inside 2.0's copied region")
    for need in ('<div id="d-mapsec" hidden>', 'id="mo-arrange-bar" hidden>'
                 '<b>ARRANGING: arming disabled</b>', 'id="mo-arr-save"',
                 'id="mo-arr-reset"', 'id="mo-arr-cancel"',
                 'id="mo-arrange" hidden', 'id="mo-field"',
                 '<div class="card col" id="arming-card" hidden>',
                 'id="sa-on"', 'data-safe class="b safe" id="sa-off"',
                 'id="sa-now"', 'id="sa-what"', 'id="sa-msg"',
                 '<div class="card col" id="lf-card">', 'id="lf-on"',
                 'data-safe class="b safe" id="lf-off"', 'id="lf-now"',
                 'id="lf-what"', 'id="lf-msg"',
                 '<div class="card col" id="annout-card" hidden>',
                 'id="annout-pick"', 'id="annout-save"', 'id="annout-tone"',
                 'id="annout-msg"'):
        check(need in two, f"2.0 has {need}")
    dm = _js_function(two, "dayMap") or ""
    check('$("mo-arrange").hidden = !(ME && ME.local);' in dm and
          "renderField(MO" in dm and "renderArrange();" in dm,
          "the map draws 1.0's field and Arrange bar; Arrange on the show "
          "PC only")
    check('if(ARRANGE) arrangeExit("left");' in
          (_js_function(two, "mapOff") or "") and
          "mapOff();" in (_js_function(two, "dayView") or "") and
          'if(DAY_STEP === "purge") mapOff();' in
          (_js_function(two, "dayGo") or ""),
          "leaving DAY or the Purge step leaves Arrange mode (1.0's "
          "arrangeExit(\"left\"))")
    check('if(ARRANGE){ kk.className = "key"; kk.textContent = '
          'ARRANGE_BANNER; }' in two,
          "while arranging, the fire key line says so")
    rs = _js_function(two, "renderSwitches") or ""
    check('$("arming-card").hidden = !local;' in rs and
          "const an = !local || !L.show;" in rs,
          "Arming from a screen and the announcement output: the show PC "
          "only (1.0's whoami and renderAnnounce)")
    for p in ('post("/api/remote/screen-arming", {on: true})',
              'post("/api/remote/screen-arming", {on: false})',
              'post("/api/remote/live-flame", {on: true, confirmed: true})',
              'post("/api/remote/announce-test-tone", {})',
              'post("/api/remote/announce-output", JSON.parse(v))',
              'getJSON("/api/remote/announce-outputs", 3000)',
              'await moPress("layout", {positions: positions});',
              'await moPress("layout", {reset: true});'):
        check(p in one and p in two, f"1.0 and 2.0 both press {p}")
    sect = two[two.find('<div class="card col" id="arming-card"'):
               two.find('<div class="card"><div class="t"><b>More '
                        'programming</b>')]
    sect += two[two.find('<div id="d-mapsec"'):two.find('<div id="mo-field"')]
    check(len(sect) > 500 and "–" not in sect and "—" not in sect,
          "no em or en dashes on the new cards")
    here = os.path.dirname(os.path.abspath(__file__))
    op = open(os.path.join(here, "OPERATOR.md"), encoding="utf-8").read()
    i = op.find("- Machine map, Arrange and the show machine switches.")
    para = op[i:op.find("\n- ", i + 3)] if i >= 0 else ""
    for words in ("Map", "Arrange", "Save layout", "Reset layout", "Cancel",
                  "show PC only", "Arming from a screen", "Live flame",
                  "Test tone", "nothing arms", "Settings"):
        check(words in para, f"OPERATOR.md, 2.0 map and switches, says "
                             f"{words!r}")
    _no_dashes(para, "OPERATOR.md, 2.0 map and switches")
    print("  ok")


def test_ui2_map_and_arrange_driven():
    section("2.0's machine map and Arrange mode pressed in a real browser "
            "(1.0's code): a machine tap is 1.0's purge select; Arrange "
            "(the show PC only) tells the engine at once, clears this "
            "screen's selection, shows the banner and the key line, holds "
            "back every tap and the Space bar; a drag and Save layout send "
            "the new place; Cancel sends nothing; Reset asks first; leaving "
            "the step leaves Arrange; an iPad gets no Arrange")
    chrome = _find_chromium()
    if not chrome:
        check(not (IN_CI and sys.platform.startswith("linux")),
              "no Chromium or Chrome on this CI runner")
        print("  ok")
        return
    page = _ui2_page_inline()
    steps = r"""
const mark = () => window.__posts.length;
const since = n => window.__posts.slice(n);
const step = k => { const b = document.querySelector('#d-steps [data-step="' + k + '"]'); if(b) b.click(); return !!b; };
const q = id => document.getElementById(id);
const mach = id => document.querySelector('#mo-field .mach[data-id="' + id + '"]');
const pe = (el, type, x, y) => el.dispatchEvent(new PointerEvent(type, {bubbles:true, cancelable:true, pointerId:7, pointerType:"mouse", isPrimary:true, buttons:type === "pointerup" ? 0 : 1, clientX:x, clientY:y}));
await h.sleep(900);
step("purge");
await h.sleep(700);
q("d-map").click();
await h.sleep(700);
out.map = {shown:!q("d-mapsec").hidden, groups_hidden:q("mo-groups").hidden, n:document.querySelectorAll("#mo-field .mach").length,
  arrange:!q("mo-arrange").hidden, bar:!q("mo-arrange-bar").hidden};
let n = mark();
const m4 = mach("m4");
const r = m4.getBoundingClientRect();
pe(m4, "pointerdown", r.left + 10, r.top + 10); pe(m4, "pointerup", r.left + 10, r.top + 10);
await h.sleep(300);
out.tap = since(n).filter(p => p.route === "purge-select").map(p => p.body);
// Review of #212, 1: a tile lets a swipe scroll (touch-action pan-y), and
// a press is never a choice: a swipe the browser takes (pointercancel), a
// drag of 40 px, or a press held 700 ms chooses nothing.
out.touch = getComputedStyle(mach("m5")).touchAction;
n = mark();
const r5 = mach("m5").getBoundingClientRect();
pe(mach("m5"), "pointerdown", r5.left + 10, r5.top + 10);
mach("m5").dispatchEvent(new PointerEvent("pointercancel", {bubbles:true, pointerId:7, pointerType:"touch"}));
await h.sleep(150);
pe(mach("m5"), "pointerdown", r5.left + 10, r5.top + 10); pe(mach("m5"), "pointerup", r5.left + 10, r5.top + 50);
await h.sleep(150);
pe(mach("m5"), "pointerdown", r5.left + 10, r5.top + 10); await h.sleep(700); pe(mach("m5"), "pointerup", r5.left + 10, r5.top + 10);
await h.sleep(200);
out.swipes = since(n).filter(p => p.route === "purge-select").length;
// Arrange.
n = mark();
q("mo-arrange").click();
await h.sleep(400);
out.enter = {beats:since(n).filter(p => p.route === "morning-open").map(p => p.body.arranging), clear:since(n).filter(p => p.route === "purge-clear").length,
  bar:!q("mo-arrange-bar").hidden, arrange_dis:q("mo-arrange").disabled, key:(q("mo-key") || {}).textContent,
  key_title:(q("mo-key") || {}).title, touch:getComputedStyle(mach("m4")).touchAction, icon:!!q("mo-arrange").querySelector("svg")};
// While arranging: a tap picks up, never arms; Space fires nothing.
n = mark();
const fr = q("mo-field").getBoundingClientRect(), r2 = mach("m4").getBoundingClientRect();
pe(mach("m4"), "pointerdown", r2.left + 10, r2.top + 10);
window.dispatchEvent(new PointerEvent("pointermove", {bubbles:true, pointerId:7, pointerType:"mouse", buttons:1, clientX:fr.left + fr.width * 0.3, clientY:fr.top + fr.height * 0.4}));
await h.sleep(100);
window.dispatchEvent(new PointerEvent("pointerup", {bubbles:true, pointerId:7, pointerType:"mouse", buttons:0, clientX:fr.left + fr.width * 0.3, clientY:fr.top + fr.height * 0.4}));
await h.sleep(200);
document.dispatchEvent(new KeyboardEvent("keydown", {key:" ", code:"Space", bubbles:true}));
await h.sleep(300);
document.dispatchEvent(new KeyboardEvent("keyup", {key:" ", code:"Space", bubbles:true}));
out.held = since(n).filter(p => ["purge-select", "purge-fire", "lock"].includes(p.route)).map(p => p.route);
n = mark();
q("mo-arr-save").click();
await h.sleep(500);
const lay = since(n).filter(p => p.route === "layout").map(p => p.body);
out.save = {n:lay.length, m4:lay.length ? lay[0].positions.m4 : null, beat:since(n).filter(p => p.route === "morning-open").map(p => p.body.arranging), bar:!q("mo-arrange-bar").hidden};
// Cancel sends nothing.
q("mo-arrange").click(); await h.sleep(300);
n = mark();
q("mo-arr-cancel").click(); await h.sleep(400);
out.cancel = since(n).filter(p => p.route === "layout").length;
// Reset asks first.
q("mo-arrange").click(); await h.sleep(300);
n = mark();
q("mo-arr-reset").click(); await h.sleep(300);
out.reset_sheet = {open:!q("sheet").hidden, posts:since(n).filter(p => p.route === "layout").length};
const yes = document.querySelector('#sh-row [data-i="1"]'); if(yes) yes.click();
await h.sleep(500);
out.reset = since(n).filter(p => p.route === "layout").map(p => p.body.reset);
out.icon_after = !!q("mo-arrange").querySelector("svg");
// A window too short for the bar and the field: Arrange is not started,
// and one turning too short leaves it (review of #212, 5).
q("d-panel").style.maxHeight = "120px";
n = mark();
q("mo-arrange").click(); await h.sleep(400);
out.short = {arrange:ARRANGE, msg:q("mo-msg").textContent, beats:since(n).filter(p => p.route === "morning-open" && p.body.arranging).length};
q("d-panel").style.maxHeight = "";
await h.sleep(300);
q("mo-arrange").click(); await h.sleep(300);
const was = ARRANGE;
q("d-panel").style.maxHeight = "120px";
await h.sleep(600);
out.shrunk = {was:was, arrange:ARRANGE, msg:q("mo-msg").textContent};
q("d-panel").style.maxHeight = "";
await h.sleep(300);
// Leaving the step leaves Arrange (no save).
q("mo-arrange").click(); await h.sleep(300);
n = mark();
step("lasers") || step("locks");
await h.sleep(500);
out.left = {arrange:ARRANGE, layout:since(n).filter(p => p.route === "layout").length, beat:since(n).filter(p => p.route === "morning-open").map(p => p.body.arranging)};
// An iPad: no Arrange.
step("purge"); await h.sleep(500);
if(q("d-mapsec").hidden){ q("d-map").click(); await h.sleep(500); }
ME.local = false; await h.sleep(900);
out.ipad = {arrange:!q("mo-arrange").hidden, map:!q("d-mapsec").hidden};
ME.local = true;
"""
    # A tall window: Arrange needs room for its bar and the field, and
    # the CI runner's page is shorter than its window.
    m = _ui2_drive(chrome, page, _ui2_status_day(), steps, size=(1366, 1100),
                   frag="?tour=0#day",
                   routes={"/api/remote/morning":
                           _morning_view_pico(selected=("m1",))},
                   budget_ms=30000)
    if not check(isinstance(m, dict) and not m.get("problems"),
                 f"2.0's map and Arrange, pressed: {m!r}"[:1500]):
        print("  ok")
        return
    check(m["map"]["shown"] and m["map"]["groups_hidden"] and
          m["map"]["n"] >= 6 and m["map"]["arrange"] and not m["map"]["bar"],
          f"Map: 1.0's field in the group buttons' place, Arrange on the "
          f"show PC: {m['map']}")
    check(len(m["tap"]) == 1 and m["tap"][0].get("machine") == "m4" and
          m["tap"][0].get("on") is True,
          f"a machine tap is 1.0's purge select: {m['tap']}")
    check(m["touch"] == "pan-y" and m["swipes"] == 0,
          f"a tile lets a swipe scroll; a swipe the browser takes, a 40 px "
          f"drag or a 700 ms press chooses nothing: {m['touch']} "
          f"{m['swipes']}")
    check(m["enter"]["touch"] == "none" and m["enter"]["icon"] and
          m["icon_after"] and
          m["enter"]["key_title"] == "Save layout or Cancel first",
          f"while arranging a tile holds the pointer for the drag; the "
          f"Arrange button keeps its icon; the key line's title is 1.0's: "
          f"{m['enter']} {m['icon_after']}")
    check(m["short"]["arrange"] is False and m["short"]["beats"] == 0 and
          m["short"]["msg"].startswith("This window is too short to "
                                       "arrange") and
          m["shrunk"]["was"] is True and m["shrunk"]["arrange"] is False,
          f"a window too short: Arrange is not started; one turning too "
          f"short leaves it: {m['short']} {m['shrunk']}")
    e = m["enter"]
    check(e["beats"][:1] == [True] and e["clear"] == 1 and e["bar"] and
          e["arrange_dis"] and e["key"] == "ARRANGING: arming disabled",
          f"Arrange: the engine hears at once, this screen's selection is "
          f"cleared, the banner and the key line say so: {e}")
    check(m["held"] == [],
          f"while arranging, a tap and the Space bar send nothing that "
          f"arms or fires: {m['held']}")
    sv = m["save"]
    check(sv["n"] == 1 and sv["m4"] and abs(sv["m4"]["x"] - 30) < 2 and
          abs(sv["m4"]["y"] - 40) < 2 and
          sv["beat"][:1] == [False] and not sv["bar"],
          f"a drag and Save layout: the new place sent, the mode ended "
          f"first: {sv}")
    check(m["cancel"] == 0, f"Cancel sends nothing: {m['cancel']}")
    check(m["reset_sheet"]["open"] and m["reset_sheet"]["posts"] == 0 and
          m["reset"] == [True],
          f"Reset asks first, then sends reset: {m['reset_sheet']} "
          f"{m['reset']}")
    check(m["left"]["arrange"] is False and m["left"]["layout"] == 0 and
          False in m["left"]["beat"],
          f"leaving the step leaves Arrange, nothing saved: {m['left']}")
    check(not m["ipad"]["arrange"],
          f"an iPad gets no Arrange: {m['ipad']}")
    print("  ok")


def test_ui2_preshow_audio_card_driven():
    section("2.0's Pre-show audio card pressed in a real browser: on the "
            "Schedule tab of the show PC, the chosen file's name shown, its "
            "list from the engine; Turn on and Save file post the one "
            "setting; signed in without Settings both are off; an iPad gets "
            "no card; its words: a headline of 6 words or fewer, up to 3 "
            "lines of 8 words, no dashes, show control not Run")
    chrome = _find_chromium()
    page = _ui2_page_inline()
    card = page[page.find('id="psa-card"'):]
    card = card[:card.find("</div>\n        <!--")]
    head = re.findall(r"<b>([^<]*)</b>", card)
    lines = re.findall(r"<li>([^<]*)</li>", card)
    check(head == ["Pre-show audio"] and len(head[0].split()) <= 6 and
          1 <= len(lines) <= 3 and all(len(t.split()) <= 8 for t in lines)
          and not re.search(r"\bRun\b", card) and "show control" in card,
          f"the card's words keep the rules: {head} {lines}")
    _no_dashes(card, "the Pre-show audio card")
    if not chrome:
        check(not (IN_CI and sys.platform.startswith("linux")),
              "no Chromium or Chrome on this CI runner")
        print("  ok")
        return
    st = _ui2_status_day()
    st["preshow_audio"] = {"available": True, "on": False,
                           "name": "welcome.wav", "file_ok": True,
                           "length_s": 30.0, "lead_s": 120}
    got = {"on": False, "file": "C:/LTC/Announcements/welcome.wav",
           "choices": [
               {"path": "C:/LTC/Announcements/welcome.wav",
                "name": "welcome.wav", "available": True, "length_s": 30.0},
               {"path": "C:/LTC/Announcements/doors.wav",
                "name": "doors.wav", "available": True, "length_s": 12.0},
               {"path": "C:/LTC/Announcements/bad.wav", "name": "bad.wav",
                "available": False, "length_s": None},
               {"path": "C:/LTC/Announcements/long.wav", "name": "long.wav",
                "available": True, "length_s": 130.0, "too_long": True}]}
    steps = r"""
const mark = () => window.__posts.length;
const since = n => window.__posts.slice(n);
const q = id => document.getElementById(id);
const bare = b => { const o = Object.assign({}, b); delete o.seen; return o; };
document.querySelector('.tab[data-tab="schedule"]').click();
await h.sleep(1200);
out.card = {shown:!q("psa-card").hidden, now:q("psa-now").textContent,
  opts:[...q("psa-pick").options].map(o => o.textContent + (o.disabled ? " (off)" : "")),
  picked:q("psa-pick").value, on_dis:q("psa-on").disabled, off_dis:q("psa-off").disabled};
// A file chosen but not saved: Turn on still uses the SAVED file.
q("psa-pick").selectedIndex = 2; q("psa-pick").dispatchEvent(new Event("change"));
let n = mark();
q("psa-on").click(); await h.sleep(400);
out.on = since(n).filter(p => p.route === "preshow-audio").map(p => bare(p.body));
window.__patch = s => Object.assign(s, {preshow_audio:Object.assign({}, s.preshow_audio, {on:true})});
await h.sleep(900);
out.while_on = {now:q("psa-now").textContent, on_dis:q("psa-on").disabled, off_dis:q("psa-off").disabled};
q("psa-pick").selectedIndex = 4; q("psa-pick").dispatchEvent(new Event("change"));
out.warn = q("psa-msg").textContent;
n = mark();
q("psa-pick").selectedIndex = 2; q("psa-save").click(); await h.sleep(400);
q("psa-off").click(); await h.sleep(400);
out.saved = since(n).filter(p => p.route === "preshow-audio").map(p => bare(p.body));
window.__patch = s => Object.assign(s, {preshow_audio:Object.assign({}, s.preshow_audio, {on:false}), me:{users_active:true, user:"Ola", may:{show:true, arm:true, settings:false}}});
await h.sleep(900);
out.nosettings = {on:q("psa-on").disabled, save:q("psa-save").disabled};
window.__patch = null; await h.sleep(600);
ME.local = false; await h.sleep(900);
out.ipad = !q("psa-card").hidden;
ME.local = true;
"""
    m = _ui2_drive(chrome, page, st, steps, size=(1366, 768),
                   frag="?tour=0#day",
                   routes={"/api/remote/morning": _morning_view_pico(),
                           "/api/remote/preshow-audio": got,
                           "/api/timelines": {"timelines": []}},
                   budget_ms=30000)
    if not check(isinstance(m, dict) and not m.get("problems"),
                 f"2.0's Pre-show audio card, pressed: {m!r}"[:1500]):
        print("  ok")
        return
    c = m["card"]
    check(c["shown"] and c["now"] == "OFF: welcome.wav" and
          c["opts"] == ["Choose a file", "welcome.wav, 30 s",
                        "doors.wav, 12 s", "bad.wav, cannot play (off)",
                        "long.wav, 130 s, over 110 s"] and
          c["picked"] == "C:/LTC/Announcements/welcome.wav" and
          not c["on_dis"] and c["off_dis"],
          f"the show PC: the card, off, the chosen name, the engine's "
          f"list: {c}")
    check(m["on"] == [{"on": True,
                       "file": "C:/LTC/Announcements/welcome.wav"}],
          f"Turn on posts on true with the SAVED file, not an unsaved "
          f"choice: {m['on']}")
    check(m["warn"] == "long.wav is 130 s: over 110 s, it will not play.",
          f"a file over 110 s is said when chosen: {m['warn']!r}")
    check(m["while_on"] == {"now": "ON: welcome.wav", "on_dis": True,
                            "off_dis": False},
          f"while on: ON with the name, Turn off works: {m['while_on']}")
    check(m["saved"] == [{"on": True,
                          "file": "C:/LTC/Announcements/doors.wav"},
                         {"on": False,
                          "file": "C:/LTC/Announcements/doors.wav"}],
          f"Save file keeps it on with the new file; Turn off keeps the "
          f"file: {m['saved']}")
    check(m["nosettings"] == {"on": True, "save": True},
          f"a sign-in without Settings: both off: {m['nosettings']}")
    check(m["ipad"] is False, "an iPad gets no Pre-show audio card")
    print("  ok")


def test_ui2_show_machine_switches_driven():
    section("2.0's show machine switches pressed in a real browser (1.0's "
            "code): Arming from a screen asks first and posts on true, "
            "Turn off posts on false at once; Live flame On asks first and "
            "posts on true and confirmed, its On on the show PC only, Off "
            "only while on; both On buttons off for a sign-in without "
            "Settings; the announcement output's list, Save and Test tone; "
            "an iPad gets neither show PC card")
    chrome = _find_chromium()
    if not chrome:
        check(not (IN_CI and sys.platform.startswith("linux")),
              "no Chromium or Chrome on this CI runner")
        print("  ok")
        return
    page = _ui2_page_inline()
    st = _ui2_status_day()
    st["arming"] = {"enabled": False, "needs_s": 2.0, "fresh_s": 1.0,
                    "holds": []}
    st["live_flame"] = {"on": False, "available": True}
    outs = {"device": "MOTU M4", "outputs": [
        {"name": "MOTU M4", "label": "MOTU M4 (WASAPI, 4 ch)",
         "picked": True},
        {"name": "Speakers", "label": "Speakers (WASAPI, 2 ch)"}]}
    steps = r"""
const mark = () => window.__posts.length;
const since = n => window.__posts.slice(n);
const q = id => document.getElementById(id);
const yes = async () => { const b = document.querySelector('#sh-row [data-i="1"]'); if(b) b.click(); await h.sleep(400); };
const bare = b => { const o = Object.assign({}, b); delete o.seen; return o; };
document.querySelector('.tab[data-tab="schedule"]').click();
await h.sleep(1200);
out.cards = {arming:!q("arming-card").hidden, lf:!q("lf-card").hidden, ann:!q("annout-card").hidden,
  sa_now:q("sa-now").textContent, sa_on_dis:q("sa-on").disabled, sa_off_dis:q("sa-off").disabled,
  lf_now:q("lf-now").textContent, lf_on:!q("lf-on").hidden && !q("lf-on").disabled, lf_off_dis:q("lf-off").disabled,
  opts:[...q("annout-pick").options].map(o => o.textContent)};
let n = mark();
q("sa-on").click(); await h.sleep(300);
out.sa_sheet = {open:!q("sheet").hidden, h:q("sh-h").textContent, posts:since(n).filter(p => p.route === "screen-arming").length};
await yes();
out.sa_on = since(n).filter(p => p.route === "screen-arming").map(p => bare(p.body));
window.__patch = s => Object.assign(s, {arming:{enabled:true, holds:[]}, live_flame:{on:true, available:true}});
await h.sleep(900);
n = mark();
q("sa-off").click(); await h.sleep(300);
out.sa_off = {sheet:!q("sheet").hidden, posts:since(n).filter(p => p.route === "screen-arming").map(p => bare(p.body))};
out.on_state = {sa_on_dis:q("sa-on").disabled, lf_on_dis:q("lf-on").disabled, lf_off_dis:q("lf-off").disabled};
n = mark();
q("lf-off").click(); await h.sleep(300);
out.lf_off = since(n).filter(p => p.route === "live-flame").map(p => bare(p.body));
window.__patch = null; await h.sleep(900);
n = mark();
q("lf-on").click(); await h.sleep(300);
out.lf_sheet = {open:!q("sheet").hidden, h:q("sh-h").textContent, posts:since(n).filter(p => p.route === "live-flame").length};
await yes();
out.lf_on = since(n).filter(p => p.route === "live-flame").map(p => bare(p.body));
// The announcement output: Speakers, Save; Test tone.
n = mark();
q("annout-pick").selectedIndex = 2; q("annout-save").click(); await h.sleep(400);
q("annout-tone").click(); await h.sleep(400);
out.ann = since(n).filter(p => /^announce-/.test(p.route)).map(p => [p.route, bare(p.body)]);
// Signed in without Settings: both On buttons off.
window.__patch = s => Object.assign(s, {me:{users_active:true, user:"Ola", may:{show:true, arm:true, settings:false}}});
await h.sleep(900);
out.nosettings = {sa_on:q("sa-on").disabled, lf_on:q("lf-on").disabled, sa_off:q("sa-off").disabled};
window.__patch = null; await h.sleep(600);
ME.local = false; await h.sleep(900);
out.ipad = {arming:!q("arming-card").hidden, ann:!q("annout-card").hidden, lf_on:!q("lf-on").hidden, lf_card:!q("lf-card").hidden};
ME.local = true;
"""
    m = _ui2_drive(chrome, page, st, steps, size=(1366, 768),
                   frag="?tour=0#day",
                   routes={"/api/remote/morning": _morning_view_pico(),
                           "/api/remote/announce-outputs": outs,
                           "/api/timelines": {"timelines": []}},
                   budget_ms=30000)
    if not check(isinstance(m, dict) and not m.get("problems"),
                 f"2.0's switches, pressed: {m!r}"[:1500]):
        print("  ok")
        return
    c = m["cards"]
    check(c["arming"] and c["lf"] and c["ann"] and c["sa_now"] == "OFF" and
          not c["sa_on_dis"] and c["sa_off_dis"] and c["lf_now"] == "OFF"
          and c["lf_on"] and c["lf_off_dis"] and
          c["opts"][:1] == ["None: only through the show audio"] and
          "MOTU M4 (WASAPI, 4 ch), picked now" in c["opts"],
          f"the show PC: the three cards, both off, 1.0's outputs list: "
          f"{c}")
    check(m["sa_sheet"]["open"] and
          m["sa_sheet"]["h"] == "Turn on arming from a screen?" and
          m["sa_sheet"]["posts"] == 0 and m["sa_on"] == [{"on": True}],
          f"Arming from a screen On asks first, then posts on true: "
          f"{m['sa_sheet']} {m['sa_on']}")
    check(not m["sa_off"]["sheet"] and
          m["sa_off"]["posts"] == [{"on": False}],
          f"Turn off: at once, on false: {m['sa_off']}")
    check(m["on_state"] == {"sa_on_dis": True, "lf_on_dis": True,
                            "lf_off_dis": False},
          f"while on: On is off, Off works: {m['on_state']}")
    check(m["lf_off"] == [{"on": False}], f"Live flame Off: {m['lf_off']}")
    check(m["lf_sheet"]["open"] and
          m["lf_sheet"]["h"] == "Turn on live flame programming?" and
          m["lf_sheet"]["posts"] == 0 and
          m["lf_on"] == [{"on": True, "confirmed": True}],
          f"Live flame On asks first, then posts on true and confirmed: "
          f"{m['lf_sheet']} {m['lf_on']}")
    check(m["ann"] == [["announce-output", {"device": "Speakers",
                                            "hostapi": None}],
                       ["announce-test-tone", {}]],
          f"the announcement output's Save and Test tone, 1.0's bodies: "
          f"{m['ann']}")
    check(m["nosettings"] == {"sa_on": True, "lf_on": True, "sa_off": True},
          f"a sign-in without Settings: both On buttons off (Off is off "
          f"only because it is off): {m['nosettings']}")
    check(not m["ipad"]["arming"] and not m["ipad"]["ann"] and
          not m["ipad"]["lf_on"] and m["ipad"]["lf_card"],
          f"an iPad: no Arming from a screen, no output, Live flame On "
          f"hidden (its Off stays): {m['ipad']}")
    print("  ok")

def test_ui2_fireball_timeline_editor():
    section("interface 2.0's fireball timeline editor (Schedule): Jeff's "
            "four stages in his order with their channels, a start and a "
            "length each, FSEQ or Timeline, a preview bar; the page's own "
            "checks in plain words before anything is sent; Save is the "
            "fireball-timeline-save route with the revision it read; "
            "signed out or without the Settings row every field and Save "
            "are disabled and say why in 8 words or fewer and nothing is "
            "sent; Abort, Hold, Stop show and Disarm flames never dimmed, "
            "disabled or covered; drawn in a real browser")
    one, two = _ui2_pages()
    lo = one[one.find('<script id="remote-logic">') +
             len('<script id="remote-logic">'):]
    lo = lo[:lo.find("</script>")]
    sched = two[two.find('<section class="pane" id="t-schedule"'):]
    sched = sched[:sched.find("</section>")]
    check('id="fbt"' in sched and 'id="fbt-save"' in sched and
          'id="fbt-src"' in sched,
          "the editor is on the Schedule tab")
    js_a = two.find("// ---- The fireball timeline (fireball_timeline.py")
    js_b = two.find("// ---- The brand (1.0's loadBrand)")
    js = two[js_a:js_b]
    check(js_a > 0 and js_b > js_a and
          'fbtPost("/api/remote/fireball-timeline-save", actor(body));'
          in js
          and 'body = fbtBody(show, FBT_BASE, FBT_SRC, chk.stages);' in js
          and 'getJSON("/api/remote/fireball-timeline?show=" + '
              'encodeURIComponent(want)' in js,
          "it reads fireball-timeline and saves through "
          "fireball-timeline-save, with the actor's seen")
    fp = _js_function(two, "fbtPost") or ""
    check("let FBT_POST_MS = 15000;" in js and
          "setTimeout(() => ctl.abort(), FBT_POST_MS)" in fp and
          "signal:ctl.signal" in fp and '"X-LTC-Window": WINDOW_ID' in fp
          and '"No answer: check the connection"' in fp,
          "the save gives up after 15 s with no answer and says so "
          "(review of #194), with 1.0's window header")
    check("purge" not in js.lower().replace("purge is never a stage", "")
          .replace("never here. only by hand", ""),
          "the editor has no Purge stage and no purge press")
    check("—" not in js and "–" not in js and
          "—" not in sched and "–" not in sched,
          "no em or en dashes")
    m = re.search(r'fireball: \["Fireball timeline", (.*?)\]\],\n', two,
                  re.S)
    check(m and "Purge" in m.group(1) and "Admins" in m.group(1),
          "the ? says what each part does, Purge never here")
    for word in ("No contact", "Sign in to edit", "Admins only",
                 "Arming off here", "Show cannot be timed", "No changes",
                 "Loading", "File broken: replace it",
                 "Saved elsewhere: Revert", "Saving",
                 "Could not read: Retry", "Fix the marked rows",
                 "Keep editing", "Discard my changes"):
        check((('"' + word + '"') in js or ('>' + word + '<') in sched) and len(word.split()) <= 8,
              f"says why in 8 words or fewer: {word!r}")
    from ltcplay import fireball_timeline as FT
    check([(k, w, s) for k, w, s in FT.STAGES] ==
          [("fuel", "Fuel", 55), ("air", "Air", 56), ("igniter", "Igniter",
                                                     58),
           ("valve", "Valve Open", 57)] and
          'const FBT_STAGES = [["fuel", "Fuel", 55], ["air", "Air", 56], '
          '["igniter", "Igniter", 58], ["valve", "Valve Open", 57]];' in js
          and "const FBT_FPS = 30;" in js and FT.FPS == 30,
          "the page's stages and frames are the engine's")
    import shutil
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner")
    else:
        fns = "\n".join(_js_function(two, n) or "" for n in (
            "fbtParseTc", "fbtTcText", "fbtDurUnclear", "fbtDur",
            "fbtCheck", "fbtWhy",
            "fbtBlock", "fbtBody", "fbtBands"))
        consts = "\n".join(re.findall(r"^const FBT_(?:FPS|STAGES) = .*;$",
                                      two, re.M))
        body = lo + "\n" + consts + "\n" + fns + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
t(fbtParseTc("00:00:00:00") === 0 && fbtParseTc("00:01:30:15") === 2715 && fbtParseTc(" 01:00:00:29 ") === 108029, "timecodes to frames");
t(fbtParseTc("00:00:00:30") === null && fbtParseTc("00:60:00:00") === null && fbtParseTc("00:00:60:00") === null && fbtParseTc("0:00:00:00") === null && fbtParseTc("") === null && fbtParseTc(null) === null, "frame 30, minute 60, second 60, short, empty: not a timecode");
t(fbtTcText(2715) === "00:01:30:15" && fbtTcText(0) === "00:00:00:00", "frames to timecode");
let c = fbtCheck([{k:"fuel", used:true, start:"00:00:01:00", dur:"1.5"}, {k:"air", used:false, start:"rubbish", dur:""}, {k:"igniter", used:true, start:"00:00:02:30", dur:"0"}, {k:"valve", used:true, start:"00:10:00:00", dur:"1"}], 300);
t(JSON.stringify(c.stages) === JSON.stringify([{stage:"fuel", start:"00:00:01:00", dur_s:1.5}]), "only the good used rows are sent: " + JSON.stringify(c.stages));
t(!("air" in c.errors), "a row not used is never checked");
t(/HH:MM:SS:FF/.test(c.errors.igniter) && /seconds above 0/.test(c.errors.igniter), "a bad start and a 0 length, said: " + c.errors.igniter);
t(c.errors.valve === "Start is after the end of the show.", "a start past the show: " + c.errors.valve);
c = fbtCheck([{k:"fuel", used:true, start:"00:00:01:00", dur:"36000"}], 300);
t(c.stages.length === 1 && c.stages[0].dur_s === 36000, "no longest length (Jeff)");
// A Valve Open less than 3 frames after its Igniter: a warning under the
// Valve, never a refusal (review of #201).
c = fbtCheck([{k:"igniter", used:true, start:"00:00:05:00", dur:"1"}, {k:"valve", used:true, start:"00:00:05:00", dur:"0.5"}], 300);
t(c.stages.length === 2 && !Object.keys(c.errors).length && /own frame: it never runs/.test(c.warning) && /at least 3 frames/.test(c.warning), "same frame: warned, not refused: " + c.warning);
c = fbtCheck([{k:"igniter", used:true, start:"00:00:05:00", dur:"1"}, {k:"valve", used:true, start:"00:00:05:02", dur:"0.5"}], 300);
t(/2 frames after the Igniter/.test(c.warning), "2 frames: warned: " + c.warning);
c = fbtCheck([{k:"igniter", used:true, start:"00:00:05:00", dur:"1"}, {k:"valve", used:true, start:"00:00:05:03", dur:"0.5"}], 300);
t(c.warning === "", "3 frames: no warning");
c = fbtCheck([{k:"fuel", used:true, start:"00:00:01:00", dur:"-1"}, {k:"air", used:true, start:"00:00:01:00", dur:"x"}, {k:"valve", used:true, start:"00:00:01:00", dur:"Infinity"}], 300);
t(c.errors.fuel && c.errors.air && c.errors.valve && !c.stages.length, "negative, words, infinity: refused");
t(fbtDur("2,5") === 2.5 && fbtDur("2.5") === 2.5 && fbtDur(" 3 ") === 3 && fbtDur(".5") === 0.5, "a point or a comma before the decimals");
t(fbtDur("2,5,1") === null && fbtDur("1e3") === null && fbtDur("0") === null && fbtDur("") === null && fbtDur("2..5") === null && fbtDur("1,5.0") === null, "anything else is not a length");
t(fbtDur("1,000") === null && fbtDur(" 12,500 ") === null && fbtDur("1,0") === 1 && fbtDur("1,0000") === 1 && fbtDur("1000") === 1000, "a comma before exactly 3 digits is unclear: refused, never read as 1 (review of #194)");
c = fbtCheck([{k:"fuel", used:true, start:"00:00:01:00", dur:"1,000"}], 300);
t(c.errors.fuel === "Length: 1,000 is unclear: write 1000 or 1.000." && !c.stages.length, "1,000 said in words: " + c.errors.fuel);
t(fbtBlock(null, "S", "", false, false) === "Loading" && fbtBlock({rev:1}, "S", "T", false, false) === "Loading", "no data, or another show's: Loading");
t(fbtBlock(null, "S", "", false, false, false, true) === "Could not read: Retry" && fbtBlock({rev:1}, "S", "T", false, false, false, true) === "Could not read: Retry", "a read failed and nothing is loading: never Loading (review of #194)");
t(fbtBlock({rev:1}, "S", "S", false, false, true) === "Loading" && fbtBlock({rev:1}, "S", "S", false, false, false, true) === "", "a read on its way blocks Save; this show's data kept after a failed read does not");
t(fbtBlock({rev:1}, "S", "S", false, false, false, false, true) === "Fix the marked rows" && fbtBlock({rev:1}, "S", "S", true, false, false, false, true) === "Saved elsewhere: Revert", "red rows grey Save out (review of #194)");
t(fbtBlock({rev:1, error:"x"}, "S", "S", false, false) === "File broken: replace it", "a broken file");
t(fbtBlock({rev:1, show_problem:"x"}, "S", "S", false, false) === "Show cannot be timed", "a show that cannot be timed");
t(fbtBlock({rev:1}, "S", "S", true, false) === "Saved elsewhere: Revert", "stale: Revert first");
t(fbtBlock({rev:1}, "S", "S", false, true) === "Saving" && fbtBlock({rev:1}, "S", "S", false, false) === "", "saving; else nothing blocks");
const st = (me, arming) => ({me:me, arming:{enabled:!!arming}});
const admin = {user:"Andy", role:"admin", may:{settings:true}};
t(fbtWhy(st(admin, false), true, false) === "", "an admin on the show PC may");
t(fbtWhy(st(admin, true), false, false) === "", "an admin on an iPad with arming from a screen on may");
t(fbtWhy(st(admin, false), false, false) === "Arming off here", "an iPad with it off: says so");
t(fbtWhy(st({user:"Op", role:"operator", may:{settings:false}}, true), true, false) === "Admins only", "an operator: Admins only");
t(fbtWhy(st({user:null, may:{settings:false}}, true), true, false) === "Sign in to edit", "signed out: Sign in to edit");
t(fbtWhy(st({}, true), true, false) === "Sign in to edit", "no sign-in at all: Sign in to edit");
t(fbtWhy(st(admin, true), true, true) === "No contact", "no contact: No contact");
t(JSON.stringify(fbtBody("S.json", 7, "timeline", [{stage:"fuel", start:"00:00:01:00", dur_s:1}])) === JSON.stringify({show:"S.json", rev:7, source:"timeline", stages:[{stage:"fuel", start:"00:00:01:00", dur_s:1}]}), "the body: show, rev, source, stages");
const b = fbtBands([{stage:"fuel", start:"00:00:30:00", dur_s:30}, {stage:"air", start:"00:04:50:00", dur_s:60}], 300);
t(b.length === 2 && Math.abs(b[0].left - 10) < 1e-9 && Math.abs(b[0].width - 10) < 1e-9 && Math.abs(b[1].width - 100 * 10 / 300) < 1e-9, "the bands, in percent, cut at the show's end: " + JSON.stringify(b));
t(fbtBands([{stage:"fuel", start:"00:00:01:00", dur_s:1}], null).length === 0, "no length known: no bands");
console.log(JSON.stringify(out));
"""
        r = _node_js(node, body, capture_output=True, text=True, timeout=60)
        try:
            bad = json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            bad = [f"node did not run it: {r.stdout[-300:]!r} "
                   f"{r.stderr[-600:]!r}"]
        check(bad == [], f"the editor's rules, in node: {bad}")
    chrome = _find_chromium()
    if not chrome:
        check(not (IN_CI and sys.platform.startswith("linux")),
              "no Chromium or Chrome on this CI runner")
        print("  ok")
        return
    page = two.replace('<script src="/remote-logic.js"></script>',
                       "<script>" + lo + "</script>", 1)
    view = {"rev": 4, "error": "", "shows": {}, "fps": 30,
            "sources": ["fseq", "timeline"], "default_source": "fseq",
            "show": "Show.json", "cue": "Show", "show_len_s": 300.0,
            "show_problem": "",
            "stages": [{"stage": k, "word": w, "slot": s}
                       for k, w, s in FT.STAGES],
            "entry": {"source": "fseq", "cue": "Show", "show_len_s": 300.0,
                      "stages": [{"stage": "fuel", "start": "00:00:01:00",
                                  "dur_s": 1.0},
                                 {"stage": "air", "start": "00:00:01:15",
                                  "dur_s": 1.0},
                                 {"stage": "valve", "start": "00:00:04:05",
                                  "dur_s": 0.2}],
                      "edited_by": "Andy", "edited_at":
                          "2026-10-30T21:04:11Z", "screen": "Rack screen"}}
    routes = {"/api/timelines": {"timelines": [{"file": "Show.json"},
                                               {"file": "Other.json"}]},
              "/api/remote/fireball-timeline": view,
              "/api/brand": {"show": "Fire and Ice"}}
    posts = {"/api/remote/fireball-timeline-save": {
        "ok": True, "text": "Saved: Air start 00:00:01:15 to 00:00:02:15."}}

    def status(me):
        st = _ui2_status_running()
        st["fireball"] = {"available": True, "on": [], "owner": None}
        st["fireball_timeline"] = {"fault": "", "messages": [],
                                   "source": None, "rev": 4}
        st["selected_show"] = "Show.json"
        st["me"] = me
        return st
    admin = {"local": True, "user": "Andy", "role": "admin",
             "users_active": True, "view_only": False,
             "may": {"arm": True, "show": True, "settings": True}}
    out = {"local": True, "user": None, "role": None,
           "users_active": True, "view_only": True,
           "may": {"arm": False, "show": False, "settings": False}}
    for who, me, sizes in (("an admin", admin,
                            ((1366, 768), (1024, 768), (390, 844))),
                           ("signed out", out, ((1366, 768),))):
        got = _rack_screen_in_chromium(
            chrome, page, status(me), sizes, measure_js=_FBT_MEASURE_JS,
            frag="?tour=0#schedule", budget_ms=20000, routes=routes,
            posts=posts)
        for (w, h), res in got.items():
            where = f"2.0 Schedule, {who}, {w}x{h}"
            if not check(isinstance(res, dict) and res.get("card"),
                         f"{where}: the editor is drawn: {res!r}"[:700]):
                continue
            check([r["k"] for r in res["rows"]] ==
                  ["fuel", "air", "igniter", "valve"] and
                  [r["label"].split(",")[0] for r in res["rows"]] ==
                  ["FuelUsed", "AirUsed", "IgniterNot used",
                   "Valve OpenUsed"] and
                  [r["label"].split("ch ")[-1] for r in res["rows"]] ==
                  ["55", "56", "58", "57"],
                  f"{where}: Fuel, Air, Igniter, Valve Open, with their "
                  f"channels, the saved ones used: "
                  f"{[r['label'] for r in res['rows']]}")
            check([(r["start"], r["dur"]) for r in res["rows"]] ==
                  [("00:00:01:00", "1"), ("00:00:01:15", "1"), ("", ""),
                   ("00:00:04:05", "0.2")] and res["src"] == ["fseq"] and
                  res["bands"] == ["fuel", "air", "valve"],
                  f"{where}: the saved times, the source, the bar: "
                  f"{res['rows']} {res['src']} {res['bands']}")
            check(res["sw"] <= res["vw"] + 1 and
                  all(r["w"] <= res["vw"] + 1 for r in res["rows"]) and
                  all(r["h"] >= 44 for r in res["rows"]) and
                  not res["under"],
                  f"{where}: nothing off the side, fields big enough, "
                  f"no Abort sign: {res['sw']} {res['vw']} "
                  f"{res['under']}")
            check(all(not x["dis"] and x["op"] == 1 and
                      "saturate" not in x["filt"] and x["shown"]
                      for x in res["mini"]),
                  f"{where}: Hold, Stop show and Disarm flames are "
                  f"there, never disabled or dimmed: "
                  f"{res['mini']}")
            check("Last saved by Andy" in res["msg"] and
                  "A show is live" in res["msg"],
                  f"{where}: who saved it last, and that a show is live: "
                  f"{res['msg']!r}")
            if me is admin:
                check(res["save"] == {"dis": True, "why": "No changes"},
                      f"{where}: nothing changed: Save says so: "
                      f"{res['save']}")
                bad = res.get("bad") or {}
                check(bad.get("err") == "Start: write HH:MM:SS:FF, frames "
                      "00 to 29." and bad.get("posts") == 0 and
                      bad.get("save") is True and
                      bad.get("why") == "Fix the marked rows" and
                      "Not saved" in bad.get("msg", ""),
                      f"{where}: frame 30 is said in plain words, Save is "
                      f"greyed and nothing is sent: {bad}")
                check(res["good_save"] == {"dis": False, "why": ""},
                      f"{where}: fixed: Save may: {res['good_save']}")
                saves = [p for p in res["posts"]
                         if p["u"] == "/api/remote/fireball-timeline-save"]
                check(len(saves) == 1 and
                      {k: v for k, v in saves[0]["b"].items()
                       if k != "seen"} ==
                      {"show": "Show.json", "rev": 4, "source": "timeline",
                       "stages": [{"stage": "fuel", "start": "00:00:01:00",
                                   "dur_s": 1},
                                  {"stage": "air", "start": "00:00:02:15",
                                   "dur_s": 1},
                                  {"stage": "igniter",
                                   "start": "00:00:04:00", "dur_s": 0.5},
                                  {"stage": "valve", "start": "00:00:04:05",
                                   "dur_s": 0.2}]} and
                      "seen" in saves[0]["b"],
                      f"{where}: one save, the revision it read, the "
                      f"source, the stages in Jeff's order: {saves}")
                check("Saved" in res["after"],
                      f"{where}: the engine's answer is shown: "
                      f"{res['after']!r}")
            else:
                check(all(r["dis"] for r in res["rows"]) and
                      res["save"] == {"dis": True,
                                      "why": "Sign in to edit"} and
                      not [p for p in res["posts"] if "save" in p["u"]],
                      f"{where}: view only: every field and Save disabled, "
                      f"Save says why, nothing sent: {res['save']} "
                      f"{res['posts']}")
    # The review's flows (#194): one admin, the show PC.
    got = _rack_screen_in_chromium(
        chrome, page, status(admin), ((1366, 768),),
        measure_js=_FBT_FLOW_JS, frag="?tour=0#schedule", budget_ms=45000,
        routes=routes)
    res = got.get((1366, 768))
    if check(isinstance(res, dict) and "b1" in res,
             f"the flows ran: {res!r}"[:600]):
        check(res["sel_h"] >= 56, f"the show file picker is a 56 px "
                                  f"target: {res['sel_h']}")
        check(res["typed_used"] == "true",
              "a time typed into a stage not used uses it")
        f1 = res["f1"]
        check(f1["dur"] == "2,5" and f1["retry"] and not f1["locked"] and
              f1["save"] == {"dis": False, "why": ""} and
              "Could not read it again" in f1["msg"] and
              "Your changes are kept" in f1["msg"],
              f"back to the tab and the read fails: the unsaved edit stays, "
              f"Retry is offered (review of #194, 1): {f1}")
        check(res["f2"] == {"locked": True, "save": {"dis": True,
                                                     "why": "Loading"},
                            "retry": False},
              f"a read on its way: fields locked, Save greyed (review of "
              f"#194, 2): {res['f2']}")
        b1 = res["b1"]
        check(b1["dur"] == "2,5" and b1["save"] == {
            "dis": True, "why": "Saved elsewhere: Revert"} and
              "Press Revert" in b1["msg"] and b1["posts"] == 0,
              f"someone saved meanwhile (the tab left and opened): the "
              f"edit stays, Save waits for Revert, nothing sent: {b1}")
        # Before Retry: the tab opening alone reads the list again, so
        # a show file added meanwhile is offered (other parts of the
        # Schedule tab read /api/timelines too, so the count alone
        # cannot tell).
        check(res["f1"]["lists"] > res["lists0"] and res["f1"]["added"],
              f"the show list is read again when the tab opens: "
              f"{res['lists0']} {res['f1']}")
        ar = res["ask_rev"]
        check(ar["shown"] and ar["dur"] == "2,5" and
              "Your changes are not saved." in ar["q"] and
              "Keep editing" in ar["q"] and "Discard my changes" in ar["q"]
              and ar["kept"] == {"hidden": True, "dur": "2,5"},
              f"Revert with an unsaved edit asks first; Keep editing keeps "
              f"it (review of #194, 3): {ar}")
        check(res["revert"] == {"save": {"dis": True, "why": "No changes"},
                                "dur": "1"},
              f"Discard my changes: Revert reads the newer one: "
              f"{res['revert']}")
        check(res["inflight"]["locked"] and
              res["inflight"]["save"]["dis"],
              f"a save on its way: every field locked: {res['inflight']}")
        sv = res["saved"] or {}
        check(sv.get("rev") == 5 and sv.get("show") == "Show.json" and
              [s.get("dur_s") for s in sv.get("stages", [])
               if s.get("stage") == "fuel"] == [2.5],
              f"saved against the revision it was made on, 2,5 as 2.5: "
              f"{sv}")
        f4a = res["f4a"]
        check("Saved. Could not read it back: Retry" in f4a["msg"] and
              f4a["retry"] and f4a["dur"] == "3" and not f4a["locked"] and
              f4a["save"] == {"dis": True, "why": "No changes"},
              f"saved, read back failed: said, the rows stay open (review "
              f"of #194, 4): {f4a}")
        check((f4a["next"] or {}).get("rev") == f4a["rev"],
              f"the next save is against the revision just saved: "
              f"{f4a['next']} {f4a['rev']}")
        ak = res["ask_show"]
        check(ak["shown"] and ak["sel"] == "Show.json" and ak["dur"] == "5"
              and ak["kept"] == {"hidden": True, "dur": "5",
                                 "sel": "Show.json"},
              f"another show with an unsaved edit asks first; Keep editing "
              f"keeps it and the show (review of #194, 3): {ak}")
        b2 = res["b2"]
        check(b2["starts"] == ["", "", "", ""] and b2["locked"] and
              b2["save"]["dis"] and b2["save"]["why"] == "Loading" and
              b2["posts"] == 0,
              f"another show picked: nothing of the last one, locked, no "
              f"save until its own read: {b2}")
        check(b2["after"] == {"src": ["timeline"], "locked": False},
              f"its own read: its data, open: {b2['after']}")
        f4d = res["f4d"]
        check(f4d["during"] and not f4d["locked"] and
              "No answer: check the connection" in f4d["msg"] and
              f4d["save"] == {"dis": False, "why": ""},
              f"a save with no answer: given up, said, unlocked (review of "
              f"#194, 4): {f4d}")
        f1b = res["f1b"]
        check(f1b["why"] == "Could not read: Retry" and f1b["retry"] and
              f1b["starts"] == ["", "", "", ""] and f1b["locked"] and
              f1b["after"] == {"locked": False, "dur": "1", "retry": False},
              f"another show's read fails: Save says Could not read, not "
              f"Loading; Retry reads it (review of #194, 1): {f1b}")
        check(res["refused"]["save"] == {"dis": True,
                                         "why": "Saved elsewhere: Revert"}
              and "Press Revert" in res["refused"]["msg"],
              f"the engine refused a stale save: Save waits for Revert: "
              f"{res['refused']}")
    print("  ok")


def _fbm_link(live=True, guard=False):
    """A real FlameLink on a fake clock, its show state and cues set by the
    test: R.live, R.tc, R.cue (512 values or None)."""
    import types
    from ltcplay import flamelink as fl
    R = types.SimpleNamespace(clk=[1000.0], live=live, tc="00:00:01:00",
                              cue=[0] * 512, raise_state=False)

    def state():
        if R.raise_state:
            raise RuntimeError("show state")
        return R.tc, R.live
    cfg = fl.FlameLinkConfig("127.0.0.1", 5571, 1, _fl_key(),
                             frame_stale_ms=500)
    R.link = fl.FlameLink(cfg, cues=lambda tc: R.cue, show_state=state,
                          clock=lambda: R.clk[0], seek_guard=guard)
    R.link.release()
    R.fl = fl

    def now(step=1 / 30):
        """One frame `step` seconds on, the show timecode moving with it
        (a still timecode would zero the show's own values)."""
        from ltcplay import fireball_timeline as FT
        R.clk[0] += step
        R.f = getattr(R, "f", 30) + max(1, int(round(step * 30)))
        R.tc = FT.tc_text(R.f)
        return bytes(R.link.values_now()[1])
    R.now = now
    return R


def test_fireball_manual_merged_on_the_flame_link():
    section("the Fireball page's frame on the flame link (Jeff, 2026-10-30: "
            "any phase by hand at any time, during a show too): only the "
            "fireball's fire slots, never 77; the higher of the show's and "
            "the page's value per channel, live or not; never lowers the "
            "show's; dropped after MANUAL_HOLD_S, by zero() and "
            "disarm_all() (a late beat refused), by the lockout; not with "
            "live flame programming or an unreadable show state")
    from ltcplay import flamelink as fl
    check(fl.MANUAL_HOLD_S == fl.PURGE_HOLD_S == 0.25,
          "the page's frame is held a quarter second, as the purge's")
    R = _fbm_link()
    lk = R.link

    def page(**on):
        v = bytearray(512)
        for s, x in on.items():
            v[int(s[1:]) - 1] = x
        return bytes(v)
    # Before the engine names the fireball's slots nothing passes.
    check(lk.manual_set(page(s55=255)) is True and R.now()[54] == 0,
          "no slots named yet: the page's frame carries nothing")
    lk.set_manual_slots([55, 56, 57, 58, 59, True, 0, 513])
    check(lk.manual_slots == frozenset((55, 56, 57, 58, 59)),
          f"the slots: the fireball's five; not a slot 1 to 512 left out: "
          f"{sorted(lk.manual_slots)}")
    lk.set_manual_slots([55, "x"])
    check(lk.manual_slots == frozenset(),
          "a list that cannot be read: no slot at all (fails closed)")
    lk.set_manual_slots([55, 56, 57, 58, 59])
    # Live show: the show's frame (the timeline's Air on 56, a value on
    # 58, noise elsewhere) and the page's Fuel and Valve.
    R.cue = [0] * 512
    R.cue[55] = 255            # 56 Air from the timeline
    R.cue[57] = 200            # 58 from the show
    R.cue[56] = 100            # 57 from the show, lower than the page's
    R.cue[99] = 7
    lk.manual_set(page(s55=255, s57=255, s58=0, s60=255, s77=255,
                       s100=255))
    v = R.now()
    check(v[54] == 255 and v[55] == 255 and v[56] == 255 and v[57] == 200
          and v[99] == 7 and v[59] == 0 and v[76] == 0,
          f"live: the higher value on each fireball slot (55 page, 56 "
          f"show, 57 page over show, 58 show kept: the page never lowers "
          f"it); 60, 77 and 100 never from the page: "
          f"{[v[i] for i in (54, 55, 56, 57, 58, 59, 76, 99)]}")
    check(lk.manual_active() and lk.snapshot()["manual"] is True,
          "the link says the page's frame is held")
    check(lk._manual[0][59] == 0 and lk._manual[0][76] == 0 and
          lk._manual[0][99] == 0 and lk._manual[0][54] == 255,
          "the link keeps only the fireball's slots of the page's frame")
    # And a frame with other slots in it (as if kept unmasked) still
    # merges only the fireball's slots.
    lk._manual = (bytes([255] * 512), R.clk[0], lk.abort_id)
    v = R.now()
    check(v[54] == 255 and v[59] == 0 and v[76] == 0 and v[99] == 7,
          f"only the fireball's slots are merged, whatever the frame "
          f"holds: {[v[i] for i in (54, 59, 76, 99)]}")
    lk.manual_set(page(s55=255, s57=255))
    # Stale: dropped after MANUAL_HOLD_S on the link's own clock.
    lk.manual_set(page(s55=255))
    v = R.now(0.24)
    check(v[54] == 255, "still held at 0.24 s")
    v = R.now(0.02)
    check(v[54] == 0 and v[55] == 255 and lk._manual is None and
          not lk.manual_active(),
          "no beat for more than 0.25 s: the page's values are gone, the "
          "show's stay")
    # The clock going back drops it too.
    lk.manual_set(page(s55=255))
    R.clk[0] -= 1.0
    check(R.now(0)[54] == 0, "a clock that went back: dropped")
    # Not live (between shows, zeroed): the page's frame alone goes out,
    # with a Startup page purge frame beside it.
    R.live = False
    lk.zero()
    lk.manual_set(page(s56=255))
    lk.purge_set(page(s411=255))
    v = R.now()
    check(v[55] == 255 and v[410] == 255 and v[54] == 0,
          f"not live: the page's frame and the purge frame together: "
          f"{v[55]} {v[410]}")
    # send_frame with the cues zeroed (between shows): the page's frame
    # still goes out (the observer sees what went out).
    seen = []
    lk.observer = lambda tc, vals, ok: seen.append(bytes(vals))
    lk.purge_clear()
    lk.manual_set(page(s56=255))
    lk.send_frame()
    check(lk.zeroed and seen and seen[-1][55] == 255,
          "between shows (the cues zeroed): the page's frame goes out")
    # zero() (a Hold, a show's end) does NOT end it (Jeff, 2026-10-30):
    # the zero frame sent at once, and the frames after, still carry the
    # page's channels (the show's own values are zero), and a beat read
    # before the Hold is taken. disarm_all() (Stop, Abort) drops it and
    # refuses a beat read before.
    import types
    R.live = True
    lk.release()
    R.cue = [0] * 512
    R.cue[55] = 255                       # the show's own Air on 56
    zs = []
    lk._sock = types.SimpleNamespace(sendto=lambda d, a: zs.append(d) or
                                     len(d))
    g = lk.abort_id
    lk.manual_set(page(s55=255), g)
    lk.zero()
    check(lk.manual_active() and lk.last_values_nonzero,
          "zero() (a Hold, a show's end): the zero frame sent at once "
          "keeps the page's channel")
    v = R.now()
    check(v[54] == 255 and v[55] == 0,
          f"and after it: the page's Fuel on, the show's Air zero: "
          f"{v[54]} {v[55]}")
    check(lk.manual_set(page(s55=255), g) is True and R.now()[54] == 255,
          "a beat read before the Hold is taken")
    # A Hold landing while a frame is read (between the read and the
    # send): the show's values of that frame are dropped, the page's go
    # out.
    seen_h = []
    lk.observer = lambda tc, v, ok: seen_h.append(bytes(v))
    lk.release()
    lk.manual_set(page(s55=255), lk.abort_id)
    R.cue[55] = 255
    real_cues = lk.cues
    lk.cues = lambda tc: (lk.zero(), list(R.cue))[1]
    R.clk[0] += 1 / 30
    R.f = getattr(R, "f", 30) + 1
    from ltcplay import fireball_timeline as _FT
    R.tc = _FT.tc_text(R.f)
    lk.send_frame()
    lk.cues = real_cues
    lk.observer = None
    check(seen_h and seen_h[-1][54] == 255 and seen_h[-1][55] == 0 and
          lk.show_sent[55] == 0,
          f"a Hold during the read: the show's Air dropped, the page's "
          f"Fuel out: {seen_h[-1][54] if seen_h else None} "
          f"{seen_h[-1][55] if seen_h else None}")
    lk._sock = None
    R.cue = [0] * 512
    lk.release()
    g = lk.abort_id
    lk.manual_set(page(s55=255), g)
    lk.disarm_all("Stop")
    check(not lk.manual_active() and R.now()[54] == 0 and
          lk.manual_set(page(s55=255), g) is False,
          "disarm_all() (Stop, Abort): dropped, a late beat refused")
    lk.release()
    lk._abort_repeat = None
    # The lockout zeroes the page's slot.
    lk.manual_set(page(s55=255, s56=255), lk.abort_id)
    lk.set_locked_channels([55])
    v = R.now()
    check(v[54] == 0 and v[55] == 255, "a locked slot: zero from the page "
                                       "too")
    lk.set_locked_channels([])
    # Live flame programming on (live or not): the page's frame is not
    # merged (one source at a time).
    lk._program_on = True
    lk.manual_set(page(s55=255), lk.abort_id)
    check(R.now()[54] == 0, "live flame programming on during a show: no "
                            "page frame")
    R.live = False
    check(R.now()[54] == 0, "and not between shows either")
    lk._program_on = False
    R.live = True
    # The show state cannot be read: zeros, the page's frame too.
    R.raise_state = True
    lk.manual_set(page(s55=255), lk.abort_id)
    check(R.now()[54] == 0, "the show state unreadable: zeros, the page's "
                            "frame too")
    R.raise_state = False
    # manual_clear: off at once.
    lk.manual_set(page(s55=255), lk.abort_id)
    lk.manual_clear()
    check(R.now()[54] == 0, "manual_clear: off on the next frame")
    # The show path's own sent values (show_sent) never carry the page's
    # frame: the timeline judges "its own charge carrying on" from them
    # (third review D-F1: Andy's top-off read as the show's charge).
    import types as _ty
    R.live = True
    lk.release()
    lk._sock = _ty.SimpleNamespace(sendto=lambda d, a: len(d))
    seen_ = []
    lk.observer = lambda tc, v, ok: seen_.append(bytes(v))
    R.cue = [0] * 512
    R.now()
    lk.send_frame()             # the sender's frames come every 25 ms
    lk.manual_set(page(s55=255), lk.abort_id)
    lk.send_frame()
    check(seen_[-1][54] == 255 and lk.show_sent[54] == 0,
          f"the page's Fuel went out; the show's own values say 0: "
          f"{seen_[-1][54]} {lk.show_sent[54]}")
    R.cue[54] = 255
    lk.manual_set(page(s55=255), lk.abort_id)
    lk.send_frame()
    check(lk.show_sent[54] == 255, "the show's own Fuel: 255")
    lk.manual_clear()
    lk._sock = _ty.SimpleNamespace(sendto=lambda d, a: (_ for _ in ()).throw(
        OSError("down")))
    lk.send_frame()
    check(lk.show_sent[54] == 0, "a frame that did not go out: zeros")
    # A frame that did not go out drops the page's frame too, counted
    # (round-4 review, s95): when the link is back, Andy's Fuel does not
    # come back by itself.
    R.cue = [0] * 512
    d0 = getattr(lk, "manual_drops", 0)
    lk.manual_set(page(s55=255), lk.abort_id)
    lk.send_frame()
    check(lk._manual is None and getattr(lk, "manual_drops", 0) == d0 + 1,
          f"a send that failed: the page's frame dropped, counted: "
          f"{getattr(lk, 'manual_drops', 0) - d0}")
    lk._sock = _ty.SimpleNamespace(sendto=lambda d, a: len(d))
    lk.send_frame()
    check(seen_[-1][54] == 0, "the link back: the page's Fuel stays off "
                              "until a fresh press")
    # The show's own values that a zero() dropped mid-frame are never
    # read as the show's charge (round-4 review, E2): the page's frame
    # that went out instead is not the show's.
    R.cue = [0] * 512
    R.cue[54] = 255
    real_cues = lk.cues
    lk.cues = lambda tc: (lk.zero(), real_cues(tc))[1]
    lk.manual_set(page(s55=255), lk.abort_id)
    lk.send_frame()
    lk.cues = real_cues
    check(seen_[-1][54] == 255 and lk.show_sent[54] == 0,
          f"a zero() landed while the show's Fuel was read: the page's Fuel "
          f"went out, the show's own sent values say 0: {seen_[-1][54]} "
          f"{lk.show_sent[54]}")
    # A zero() (Hold, a show's end) clears the show's sent values at once
    # (round-4 review, E15).
    lk.manual_clear()
    lk.release()
    lk.send_frame()
    check(lk.show_sent[54] == 255, "the show's own Fuel went out")
    lk.zero()
    check(lk.show_sent[54] == 0, f"a zero(): the show's sent values are "
                                 f"zeros at once: {lk.show_sent[54]}")
    # Frames stalled for longer than flamesafe's fire hold (100 ms): the
    # page's frame is dropped and counted when they resume, never sent
    # again by itself (round-5 review B 3); a beat in flight with the old
    # count is refused (B 4).
    lk.release()
    R.cue = [0] * 512            # the show's own Fuel off from here on
    lk.send_frame()
    d1 = getattr(lk, "manual_drops", 0)
    lk.manual_set(page(s55=255), lk.abort_id, d1)
    R.clk[0] += 0.15
    lk.send_frame()
    check(seen_[-1][54] == 0 and getattr(lk, "manual_drops", 0) == d1 + 1,
          f"a 150 ms stall: the page's Fuel does not come back by itself: "
          f"{seen_[-1][54]}")
    check(lk.manual_set(page(s55=255), lk.abort_id, d1) is False and
          lk._manual is None,
          "a beat that read the count before the stall is refused")
    # A stall INSIDE the read (round-6 review 2): the gap is judged under
    # the lock right before the send, so a provider that blocks for longer
    # than flamesafe's fire hold drops the page's frame too.
    lk.send_frame()
    d2 = getattr(lk, "manual_drops", 0)
    lk.manual_set(page(s55=255), lk.abort_id, d2)
    real_cues_ = lk.cues
    from ltcplay import fireball_timeline as _FT
    R.f = getattr(R, "f", 30) + 3        # the show's timecode moves on
    R.tc = _FT.tc_text(R.f)
    read_ = []
    lk.cues = lambda tc: (read_.append(1),
                          R.clk.__setitem__(0, R.clk[0] + 0.15),
                          real_cues_(tc))[2]
    lk.send_frame()
    lk.cues = real_cues_
    check(read_ and seen_[-1][54] == 0 and
          getattr(lk, "manual_drops", 0) == d2 + 1,
          f"a 150 ms stall inside the read: the page's Fuel is not sent: "
          f"{seen_[-1][54]}")
    # The limit is flamesafe's own fire_hold_ms (round-6 review 2): 50 ms
    # drops a 70 ms gap, 200 ms keeps a 150 ms one.
    for hold_ms, gap, dropped_ in ((50, 0.07, True), (200, 0.15, False),
                                   (None, 0.07, False), (None, 0.15, True)):
        lk.send_frame()
        lk.timing_limit_ms = hold_ms
        d3 = getattr(lk, "manual_drops", 0)
        lk.manual_set(page(s55=255), lk.abort_id, d3)
        R.clk[0] += gap
        lk.send_frame()
        check((seen_[-1][54] == 0) == dropped_ and
              (getattr(lk, "manual_drops", 0) == d3 + 1) == dropped_,
              f"fire_hold_ms {hold_ms}, a {int(gap * 1000)} ms gap: the "
              f"page's Fuel {'dropped' if dropped_ else 'kept'}: "
              f"{seen_[-1][54]}")
    lk.timing_limit_ms = 100
    # A Hold or a show's end during a stall (round-7 review 4): the zero
    # frame carries the page's frame while frames are running, but not a
    # channel flamesafe has already zeroed.
    fl_ = R.fl
    sent_vals = []
    real_enc = fl_.encode_flame
    fl_.encode_flame = lambda *a, **k: (sent_vals.append(a[4]),
                                        real_enc(*a, **k))[1]
    try:
        lk.send_frame()
        d4 = getattr(lk, "manual_drops", 0)
        lk.manual_set(page(s57=255), lk.abort_id, d4)
        R.clk[0] += 0.03
        lk.zero()
        check(sent_vals[-1][56] == 255,
              "a Hold with frames running: the page's Valve Open stays "
              "(Jeff: a Hold does not end the page)")
        lk.release()
        lk.send_frame()
        d4 = getattr(lk, "manual_drops", 0)
        lk.manual_set(page(s57=255), lk.abort_id, d4)
        R.clk[0] += 0.12                    # a stall
        lk.zero()
        check(sent_vals[-1][56] == 0 and
              getattr(lk, "manual_drops", 0) == d4 + 1 and lk._manual is None,
              f"a Hold after a 120 ms stall: flamesafe has zeroed the Valve "
              f"and the zero frame does not send it again: "
              f"{sent_vals[-1][56]}")
    finally:
        fl_.encode_flame = real_enc
    lk.release()
    lk._sock = None
    lk.observer = None
    R.cue = [0] * 512
    # With the seek guard on: the show's cues held off after a jump, the
    # page's press still goes out (it is no cue).
    G = _fbm_link(guard=True)
    G.link.set_manual_slots([55, 56, 57, 58, 59])
    G.cue = [0] * 512
    G.cue[55] = 255
    G.link.manual_set(page(s55=255))
    v = G.now()
    check(v[55] == 0 and v[54] == 255,
          f"the seek guard holds the show's 56 off at the landing; the "
          f"page's 55 goes out: {v[54]} {v[55]}")
    print("  ok")


def test_fireball_page_beats_race_the_sender():
    section("the Fireball page's beat against the flame link's sender "
            "(review of #193): the charge state knows who holds a charge "
            "before the frame can go out, so Andy's charge is his and his "
            "top-off is never a double charge; a Stop or Abort that lands "
            "after the beat's checks, or while its frame is set, means "
            "nothing goes out (a Hold does not end the page's frame: "
            "Jeff, 2026-10-30); a frame of the wrong size is refused")
    import types
    from ltcplay import fireball as FB
    from ltcplay import fireball_charge as FC
    R = _fbm_link(live=False)
    real = R.link
    real.set_manual_slots([55, 56, 57, 58, 59])
    lines = []
    tr = FC.ChargeTracker(
        None, flames_get=lambda: {"connected": True, "stale": False,
                                  "age_ms": 10, "groups": [
                                      {"name": "fireball",
                                       "armed": "armed"}]},
        journal=lambda who, screen, outcome, text, fault=False:
        lines.append((who, outcome, text, fault)),
        clock=lambda: R.clk[0], threaded=False)
    sent = []

    class Sender:
        """The real link; the sender sends at the worst moment: right
        after the frame is set (and, with `zero_first`, a Stop lands just
        before it is set)."""
        zero_first = False
        hold_first = False

        def __getattr__(self, k):
            return getattr(real, k)

        def manual_set(self, values, gen=None, drops=None):
            if self.zero_first:
                real.disarm_all("Stop (selftest)")
            if self.hold_first:
                real.zero()
            took = real.manual_set(values, gen, drops)
            tc, v = real.values_now()
            tr._read_armed()
            tr.observe(tc, v, True)
            sent.append(bytes(v))
            return took
    link = Sender()
    group, _w = FB.find_group([{"name": "fireball", "safeties": [77],
                                "fire": [55, 56, 57, 58, 59]}])
    fl = {"connected": True, "stale": False, "age_ms": 10,
          "groups": [{"name": "fireball", "armed": "armed"}]}
    P = FB.FireballPanel(group, link_get=lambda: link,
                         flames_get=lambda: fl, threaded=False,
                         clock=lambda: R.clk[0])
    P.on_controls = lambda on, who, screen: tr.note_manual(on, who, screen)
    owner = ("Rack screen", "w1")
    seq = [0]

    def beat(on, run):
        seq[0] += 1
        R.clk[0] += 0.1
        return P.beat({"controls": {k: True for k in on}, "run": run,
                       "seq": seq[0]}, owner, who="Andy",
                      screen="Rack screen")
    try:
        code, _o = beat({"fuel"}, "r1")
        tr.pump()
        check(code == 200 and sent and sent[-1][54] == 255 and
              tr.state("fuel") == "charged" and
              tr.tanks["fuel"]["by"] == "Andy",
              f"Andy's first charge, sent the moment it was set, is "
              f"Andy's: {tr.tanks['fuel']}")
        beat(set(), "r1")
        R.clk[0] += 0.05
        tc, v = real.values_now()
        tr.observe(tc, v, True)
        code, _o = beat({"fuel"}, "r2")
        tr.pump()
        check(code == 200 and tr.tanks["fuel"]["topoffs"] == 1 and
              any(o == "topoff" and w == "Andy" for w, o, _t, _f in lines)
              and not any(o == "double_charge" for _w, o, _t, _f in lines),
              f"Andy's Fuel again on the charged tank: a top-off by Andy, "
              f"never a double charge: {[l[:2] for l in lines]}")
        beat(set(), "r2")
        # A Stop landing while the frame is set: refused at the link, so
        # nothing goes out, and the page says so.
        n = len(sent)
        link.zero_first = True
        code, out = beat({"valve"}, "r3")
        link.zero_first = False
        check(code == 409 and sent[n:] and
              all(s[56] == 0 for s in sent[n:]) and not P.active(),
              f"a Stop while the frame is set: nothing out, cut: {code} "
              f"{out} {[s[56] for s in sent[n:]]}")
        # A Stop landing after the beat's checks, before its run starts.
        n = len(sent)
        orig = P.refusal

        def refusal_then_stop(check_armed=True):
            why = orig(check_armed)
            real.disarm_all("Stop (selftest)")
            return why
        P.refusal = refusal_then_stop
        try:
            code, out = beat({"igniter"}, "r4")
        finally:
            P.refusal = orig
        check(code == 409 and all(s[57] == 0 for s in sent[n:]) and
              not P.active(),
              f"a Stop just after the checks: nothing out: {code} {out} "
              f"{[s[57] for s in sent[n:]]}")
        # A Hold (zero()) while the frame is set: the page's frame stands
        # and goes out (Jeff, 2026-10-30: Hold never ends it).
        n = len(sent)
        link.hold_first = True
        code, out = beat({"igniter"}, "r5")
        link.hold_first = False
        check(code == 200 and sent[n:] and sent[-1][57] == 255 and
              P.active(),
              f"a Hold while the frame is set: it goes out, the run goes "
              f"on: {code} {out} {[s[57] for s in sent[n:]]}")
        beat(set(), "r5")
        # A frame of the wrong size is refused.
        check(real.manual_set(bytes(513)) is False and
              real.manual_set(bytes(511)) is False,
              "a frame that is not 512 values is refused")
    finally:
        tr.close()
    print("  ok")


def test_fireball_manual_and_timeline_never_double_charge():
    section("the Fireball page and the timeline together on a real flame "
            "link and charge state: Andy's Fuel charges an EMPTY tank; the "
            "timeline's Fuel stage is then skipped (no double charge); the "
            "timeline's Air charges; Andy's Air during it is the same "
            "charge; Andy's Fuel again is a top-off by Andy, never a "
            "double charge; the shot empties both; Purge never from the "
            "timeline")
    import shutil
    from ltcplay import fireball_charge as FC
    from ltcplay import fireball_timeline as FT
    R = _fbm_link()
    lk = R.link
    lk.set_manual_slots([55, 56, 57, 58, 59])
    lines = []
    tr = FC.ChargeTracker(
        None, flames_get=lambda: {"connected": True, "stale": False,
                                  "age_ms": 10, "groups": [
                                      {"name": "fireball",
                                       "armed": "armed"}]},
        journal=lambda who, screen, outcome, text, fault=False:
        lines.append((who, outcome, text, fault)),
        clock=lambda: R.clk[0], threaded=False)
    Q = _fbq_rig([_st("fuel", "00:00:01:00", 1),
                  _st("air", "00:00:02:00", 1),
                  _st("valve", "00:00:04:00", 0.2)], tank=tr)
    cue_obj = Q.cue_obj
    frame = [0]
    R.cue = None

    def cues(tc):
        return Q.fq.apply([0] * 512, Q.session, "Show", frame[0] / 30.0,
                          cue_obj)
    lk.cues = cues
    andy = set()
    sent = []

    def step(f):
        frame[0] = f
        R.tc = FT.tc_text(f)
        if andy:
            v = bytearray(512)
            for s in andy:
                v[s - 1] = 255
            lk.manual_set(bytes(v), lk.abort_id)
        R.clk[0] += 1 / 30
        tr._read_armed()
        tc, vals = lk.values_now()
        tr.observe(tc, vals, True)
        sent.append(bytes(vals))
    try:
        for f in range(0, 10):
            step(f)
        andy.add(55)
        tr.note_manual({"fuel"}, "Andy", "Rack screen")
        for f in range(10, 20):
            tr.note_manual({"fuel"}, "Andy", "Rack screen")
            step(f)
        andy.clear()
        tr.note_manual(set())
        for f in range(20, 70):
            step(f)
        tr.pump()
        check(tr.state("fuel") == "charged" and
              tr.tanks["fuel"]["by"] == "Andy" and
              all(sent[f][54] == 0 for f in range(30, 70)),
              f"Andy's Fuel charged the EMPTY tank; the timeline's Fuel "
              f"stage (frames 30 to 60) never turned 55 on: "
              f"{tr.tanks['fuel']}")
        check("Fuel already charged: the Fuel stage was skipped (no double "
              "charge)." in Q.fq.messages, f"and said so: {Q.fq.messages}")
        check(all(sent[f][55] == 255 for f in range(60, 70)) and
              tr.state("air") == "charged" and
              tr.tanks["air"]["by"] == "the show",
              "the timeline's Air charges the EMPTY air tank")
        # Andy's Air during the timeline's Air: the same charge, 255 on.
        andy.add(56)
        for f in range(70, 95):
            tr.note_manual({"air"}, "Andy", "Rack screen")
            step(f)
        andy.clear()
        tr.note_manual(set())
        check(all(sent[f][55] == 255 for f in range(70, 95)) and
              tr.tanks["air"]["topoffs"] == 0,
              "Andy's Air during the timeline's: one continuous charge, no "
              "top-off counted")
        for f in range(95, 100):
            step(f)
        # Andy's Fuel again: a top-off, never a double charge.
        andy.add(55)
        for f in range(100, 105):
            tr.note_manual({"fuel"}, "Andy", "Rack screen")
            step(f)
        andy.clear()
        tr.note_manual(set())
        for f in range(105, 110):
            step(f)
        tr.pump()
        check(tr.tanks["fuel"]["topoffs"] == 1 and
              any(o == "topoff" and w == "Andy" for w, o, _t, _f in lines),
              f"Andy's Fuel on a charged tank: a top-off by Andy: "
              f"{tr.tanks['fuel']}")
        for f in range(110, 140):
            step(f)
        tr.pump()
        check(all(sent[f][56] == 255 for f in range(120, 126)) and
              tr.state("fuel") == "empty" and tr.state("air") == "empty",
              f"the shot (Valve Open 57) empties both tanks: "
              f"{tr.state('fuel')} {tr.state('air')}")
        check(not any(o == "double_charge" for _w, o, _t, _f in lines),
              f"never a double charge: {[l[1] for l in lines]}")
        check(all(s[58] == 0 for s in sent),
              "Purge (59) never set from the timeline")
    finally:
        tr.close()
        shutil.rmtree(Q.work, ignore_errors=True)
    print("  ok")


def test_fireball_timeline_end_to_end_real_flamesafe():
    section("the fireball timeline end to end: the real flamesafe with "
            "Jeff's fireball group (safety 77, fire 55 to 59), the real "
            "flame link, flame cues, charge state and arm link; the FSEQ's "
            "55 to 59 never reach the node; disarmed nothing fires; armed "
            "each stage fires at its timecode; Hold and Stop cut at the "
            "press; a Resume never re-charges; the next show skips a "
            "charged tank; a landing inside a window stays quiet; the link "
            "lost zeroes the node; Purge never")
    import json as _j
    import socket as _so
    import subprocess
    import types
    import test_show_fixtures as _fx
    from ltcplay import flamelink as fl
    from ltcplay import flameprog as fp
    from ltcplay import streamdeck as sd
    from ltcplay import fireball_timeline as FT
    from ltcplay import fireball_charge as FC
    from ltcplay import fireball_cues as FQ
    F = _fi_mod()
    here = os.path.dirname(os.path.abspath(__file__))
    key = _fl_key()
    node = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
    node.bind(("127.0.0.1", 0))
    node.settimeout(0.01)
    listen, statusp, armp = _lf_free_udps(3)
    work = tempfile.mkdtemp()
    cfg_path = os.path.join(work, "flamesafe.json")
    groups = [{"name": "front row", "safety": 401, "fire": [411]},
              {"name": "fireball", "safety": 77,
               "fire": [55, 56, 57, 58, 59]}]
    names = [g["name"] for g in groups]
    _j.dump({
        "flamesafe_config": 1, "confirmed": False, "note": "selftest",
        "universe": 1,
        "destination": {"ip": "127.0.0.1", "port": node.getsockname()[1]},
        "link": {"listen_ip": "127.0.0.1", "listen_port": listen,
                 "status_ip": "127.0.0.1", "status_port": statusp,
                 "arm_port": armp, "key": key},
        "gflame_range": "60-80%", "arm_value": 157,
        "accept_unsourced_risk": True, "min_arm_dwell_ms": 1000,
        "arm_stale_ms": 500, "frame_stale_ms": 500, "fire_hold_ms": 100,
        "tick_hz": 40, "overrun_ms": 250, "log_dir": None,
        "groups": groups}, open(cfg_path, "w"))
    # The show: a render whose flame controller carries noise (1 to 254)
    # on every channel of every frame, 55 to 59 included.
    show = os.path.join(work, "show")
    os.makedirs(show)
    with open(os.path.join(show, "xlights_networks.xml"), "w") as fh:
        fh.write(_FI2_NETWORKS.format(extra="", name="Flames",
                                      state="Inactive", after=""))
    render = os.path.join(show, "Show.fseq")
    _fb_fseq_rows(render, lambda i: bytes(((i * 7 + c) % 254) + 1
                                          for c in range(1022)), 800, 1022)
    store = FT.Store(work)
    ok, text, _e = store.save("Show.json", "Show", 20.0, "timeline", [
        _st("fuel", "00:00:01:15", 1), _st("air", "00:00:03:00", 1),
        _st("igniter", "00:00:05:00", 1.5),
        _st("valve", "00:00:05:15", 0.5)], 0, who="Andy")
    check(ok, f"the timeline saved: {text}")
    proc = subprocess.Popen([sys.executable, "-u", "-m", "flamesafe",
                             cfg_path], cwd=here, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)
    said = []
    threading.Thread(target=lambda: [said.append(l) for l in proc.stdout],
                     daemon=True).start()
    clk = _PfClock()
    clk.source = "audio_master"
    sess = types.SimpleNamespace(
        running=True, clock=clk, timeline_path=os.path.join(work,
                                                            "Show.json"),
        player=types.SimpleNamespace(override=None, freerun_epoch=None),
        tl=types.SimpleNamespace(show_dir=show, cues=[
            types.SimpleNamespace(name="Show", path=render)]))
    cues = F.FlameCues(types.SimpleNamespace(session=sess), "Flames")
    link = fl.FlameLink(fl.FlameLinkConfig.from_flamesafe_config(cfg_path),
                        cues=cues,
                        show_state=fl.audio_master_state(
                            lambda: clk if sess.running else None))
    link.tc_fps = 30.0
    arm = sd.ArmSocket("127.0.0.1", armp, key, 2)
    arm.open()
    status = sd.StatusSocket("127.0.0.1", statusp, key)
    status.open()
    stop = threading.Event()

    def flames():
        st, at = status.last, status.last_at
        if st is None or at is None:
            return None
        return {"connected": True, "stale": False,
                "age_ms": int((time.monotonic() - at) * 1000),
                "groups": [{"name": g.get("name"), "armed": g.get("armed"),
                            "fire_slots": g.get("fire_slots"),
                            "sent_fire": g.get("sent_fire")}
                           for g in st.get("groups") or []]}
    tracker = FC.ChargeTracker(work, flames_get=flames)
    # No record yet: both tanks start EMPTY (Jeff, 2026-10-30).
    check(tracker.state("fuel") == "empty" and
          tracker.state("air") == "empty",
          "no record: both tanks start EMPTY")
    link.observer = tracker.observe
    cues.fireball = FQ.FireballCues(store, charge_get=lambda: tracker)
    link.start()
    SL = (55, 56, 57, 58, 59)

    def deck():
        while not stop.is_set():
            arm.send(names)
            status.poll()
            time.sleep(0.02)

    def wait_for(cond, seconds):
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            if cond():
                return True
            time.sleep(0.02)
        return cond()

    def armed():
        st = status.last
        return st["groups"][1].get("armed") if st else None

    def arm_fireball():
        for _cycle in range(5):
            arm.set_group(1, False)
            time.sleep(1.2)
            arm.set_group(1, True)
            if wait_for(lambda: armed() == "armed", 4):
                return True
        return False

    def drain():
        while True:
            try:
                node.recvfrom(2048)
            except (_so.timeout, OSError):
                return

    def play(at_s=0.0):
        """A new play of the show cue from `at_s` (a new cue dict)."""
        link.release()
        clk.paused = False
        clk.stale = None
        clk._cue = {"label": "Show", "position_s": 0.0}
        clk.base, clk.t0 = at_s, time.monotonic()

    def record(until_cue_s, actions=()):
        """(cue time, slots 55 to 59) at the node until the cue time
        reaches `until_cue_s`; `actions`: [(cue time, fn)] run once each
        when the cue time passes it."""
        drain()
        out = []
        todo = sorted(actions, key=lambda a: a[0])
        end = time.monotonic() + until_cue_s + 10
        while time.monotonic() < end:
            p = clk.pos()
            if todo and p is not None and p >= todo[0][0]:
                todo.pop(0)[1]()
            try:
                data, _a = node.recvfrom(2048)
            except _so.timeout:
                continue
            p = clk.pos()
            v = fp.parse_e131(data).values
            out.append((p, tuple(v[s - 1] for s in SL)))
            if p is not None and p >= until_cue_s and not todo:
                break
        return out

    def spans(rec, slot):
        """[(first, last)] cue times where `slot` was on at the node."""
        i = SL.index(slot)
        got, cur = [], None
        for p, v in rec:
            if v[i] and p is not None:
                cur = [p, p] if cur is None else [cur[0], p]
            elif cur is not None:
                got.append(tuple(cur))
                cur = None
        if cur is not None:
            got.append(tuple(cur))
        return got

    def near(sp, a, b, tol=0.25, charge=None):
        """On from about `a` and never outside [a, b]. A busy machine can
        stall the show timecode for more than TC_STILL_S (0.1 s): the flame
        link then zeroes and waits for a steady run, so a window may come
        back in pieces (the Igniter, the Valve, as an FSEQ cue would) or,
        for a charge, stop for good (never a second charge); a stall at
        the start of a window starts it up to a settle (0.5 s) late."""
        if not sp or sp[0][0] < a - tol or \
                sp[0][0] > a + tol + 0.6 or \
                any(x < a - tol or y > b + tol for x, y in sp):
            return False
        if charge if charge is not None else False:
            # One charge: it may ride through stops of a frame or two
            # (fireball_cues.GAP_S), never come back after a longer one.
            # (Cue times: a stop is measured on the show clock, which a
            # busy machine stalls, so the bound has a frame of slack.)
            from ltcplay import fireball_cues as _FQ
            return all(b2[0] - a2[1] <= _FQ.GAP_S + 0.1
                       for a2, b2 in zip(sp, sp[1:]))
        return True
    threading.Thread(target=deck, daemon=True).start()
    try:
        if not check(wait_for(lambda: status.last is not None, 15),
                     "flamesafe is up: " + "".join(said)[-500:]):
            return
        wait_for(lambda: tracker.armed_now() != "unknown", 3)
        # 1. Not armed: the timeline goes out on the link, the node stays
        # at zero, nothing is charged.
        play(0.0)
        rec = record(6.4)
        check(rec and all(v == (0,) * 5 for _p, v in rec),
              f"not armed: zero at the node on 55 to 59: "
              f"{[v for _p, v in rec if any(v)][:3]}")
        check(tracker.state("fuel") == "empty" and
              tracker.state("air") == "empty",
              "and nothing is charged")
        clk._cue = None
        # 2. Armed: each stage at its timecode, 255 or 0 only (the FSEQ's
        # noise never), Purge never; the shot empties both tanks.
        check(arm_fireball(), f"the fireball armed: {armed()}")
        play(0.0)
        rec = record(6.6)
        clk._cue = None
        vals = {x for _p, v in rec for x in v}
        check(vals <= {0, 255},
              f"only the timeline's 0 and 255 reach 55 to 59, never the "
              f"FSEQ's: {sorted(vals)[:6]}")
        check(all(v[4] == 0 for _p, v in rec), "Purge (59) never")
        sp = {s: spans(rec, s) for s in SL}
        check(near(sp[55], 1.5, 2.5, charge=True) and
              near(sp[56], 3.0, 4.0, charge=True) and
              near(sp[58], 5.0, 6.5) and near(sp[57], 5.5, 6.0),
              f"each stage at its timecode for its duration: {sp}")
        check(wait_for(lambda: tracker.state("fuel") == "empty" and
                       tracker.state("air") == "empty" and
                       tracker.tanks["fuel"]["last_event"].startswith(
                           "the shot was fired"), 2),
              f"charged, then the shot: both tanks EMPTY: "
              f"{tracker.tanks}")
        # 3. Hold inside the Fuel window: zero at the press; Resume: the
        # Fuel stage never comes back (no re-charge); Stop cuts.
        if armed() != "armed":
            check(arm_fireball(), "armed again")
        held = {}

        def hold():
            held["at"] = time.monotonic()
            clk.frozen = clk.pos()
            clk.paused = True
            link.zero()

        def resume():
            link.release()
            clk.base, clk.t0 = clk.frozen, time.monotonic()
            clk.paused = False
        play(0.0)
        rec = record(1.95, [(1.9, hold)])
        check(any(v[0] == 255 for _p, v in rec),
              "the Fuel charge went out before the Hold")
        wait_for(lambda: tracker.state("fuel") == "charged", 1)
        drain()
        z = []
        end = time.monotonic() + 0.6
        while time.monotonic() < end:
            try:
                data, _a = node.recvfrom(2048)
            except _so.timeout:
                continue
            z.append(fp.parse_e131(data).values[54])
        check(z and z[-1] == 0 and z.count(255) <= 4,
              f"Hold: zero at the node at the press: {z[:8]}")
        resume()
        rec = record(2.9, [(2.8, lambda: link.disarm_all(
            "Stop held (selftest)"))])
        check(all(v[0] == 0 for p, v in rec if p is not None and p < 2.5),
              f"Resume inside the Fuel window: Fuel never on again: "
              f"{[(round(p, 2), v) for p, v in rec if v[0]][:3]}")
        check(any("Fuel charge cut short" in m and "not charged again "
                  "in this play" in m for m in cues.fireball.messages),
              f"said: {cues.fireball.messages}")
        check(wait_for(lambda: armed() != "armed", 3),
              "Stop: flamesafe disarmed the group")
        clk._cue = None
        check(tracker.state("fuel") == "charged",
              "Stop does not depressurise: fuel still CHARGED")
        # 4. The next show: Fuel is charged and no shot has fired, so the
        # Fuel stage is skipped; Air, the Igniter and the Valve run.
        check(arm_fireball(), "armed again after the Stop")
        play(0.0)
        rec = record(6.6)
        clk._cue = None
        sp = {s: spans(rec, s) for s in SL}
        check(sp[55] == [] and near(sp[56], 3.0, 4.0, charge=True) and
              near(sp[57], 5.5, 6.0),
              f"the next show: Fuel skipped (already charged), Air and the "
              f"shot fire: {sp}")
        check(any(m == "Fuel already charged: the Fuel stage was skipped "
                       "(no double charge)." for m in
                  cues.fireball.messages), f"{cues.fireball.messages}")
        check(wait_for(lambda: tracker.state("fuel") == "empty", 2),
              "and the shot emptied the tanks")
        # 5. A landing inside the Fuel window (Play from 1.8 s): the flame
        # link's own guard holds it, exactly as an FSEQ cue; Air fires.
        if armed() != "armed":
            check(arm_fireball(), "armed again")
        play(1.8)
        rec = record(4.2)
        clk._cue = None
        sp = {s: spans(rec, s) for s in SL}
        check(sp[55] == [] and near(sp[56], 3.0, 4.0, charge=True),
              f"a landing inside the Fuel window stays quiet; Air at its "
              f"time: {sp} {cues.fireball.messages} {link.seeks}")
        # 6. The flame link lost inside the Igniter window: flamesafe
        # zeroes the node by itself.
        if armed() != "armed":
            check(arm_fireball(), "armed again")
        # From 1 s before it (a stage opening in the landing's settle time
        # is skipped whole: review B of #201).
        play(4.0)
        rec = record(5.4)
        check(any(v[3] == 255 for _p, v in rec), "the Igniter is on")
        link.stop()
        time.sleep(0.8)
        drain()
        z = []
        end = time.monotonic() + 0.5
        while time.monotonic() < end:
            try:
                data, _a = node.recvfrom(2048)
            except _so.timeout:
                continue
            z.append(tuple(fp.parse_e131(data).values[s - 1] for s in SL))
        check(z and all(v == (0,) * 5 for v in z),
              f"the link lost: zero at the node: {z[:3]}")
        clk._cue = None
    finally:
        stop.set()
        try:
            link.stop()
        except Exception:
            pass
        tracker.close()
        cues.close()
        proc.terminate()
        try:
            proc.wait(10)
        except subprocess.TimeoutExpired:
            proc.kill()
        node.close()
        import shutil
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


# ------------------------------------- play-from cues, part 1: the list --

def test_play_from_cue_model():
    section("play-from cues: each cue a name (unique, case not counted, no "
            "long dash), a time from the top of the show cue inside the "
            "show audio, a lead-in (2 s when not given, 1 to 30 s, never "
            "before the top) and an optional note; refused in plain "
            "sentences; the file read strictly; ids kept across renames")
    from ltcplay import play_from as PF
    check(PF.FILE == "ltcplay_play_from.json" and
          PF.LEAD_IN_DEFAULT_S == 2 and PF.LEAD_IN_MIN_S == 1,
          "the file, and the lead-in's default and minimum")
    check(PF.parse_tc("00:08:12:15") == (8 * 60 + 12) * 30 + 15 and
          PF.tc_text((8 * 60 + 12) * 30 + 15) == "00:08:12:15" and
          PF.parse_tc(" 00:00:01:00 ") == 30, "a time reads and writes")
    for bad in ("00:00:01:30", "00:60:00:00", "00:00:60:00", "1:00:00:00",
                "00:00:01", "", None, 5, "00:00:01:00:00"):
        try:
            PF.parse_tc(bad)
            check(False, f"{bad!r} is refused as a time")
        except PF.CueError as e:
            check(_cfg_dashes(str(e)), f"{bad!r} refused: {e}")
    good = [{"name": "Finale", "tc": "00:01:40:00", "lead_in_s": 3,
             "note": "marketing cut"},
            {"name": "  Top   of act two ", "tc": "00:00:30:10"},
            {"name": "Edge", "tc": "00:00:01:00", "lead_in_s": 1}]
    got = PF.check_cues(good, 120.0)
    check([c["name"] for c in got] == ["Edge", "Top of act two", "Finale"]
          and got[1]["lead_in_s"] == 2 and got[1]["note"] == "" and
          got[2] == {"id": None, "name": "Finale", "tc": "00:01:40:00",
                     "lead_in_s": 3, "note": "marketing cut"},
          f"in time order, the lead-in 2 s when not given, spaces evened: "
          f"{got}")
    for cues, why in (
            ([{"name": "A", "tc": "00:02:00:00"}], "not inside the show "
             "audio, which is 00:02:00:00 long"),
            ([{"name": "A", "tc": "00:01:59:29"}], None),
            ([{"name": "A", "tc": "00:00:01:29"}], "start before the top"),
            ([{"name": "A", "tc": "00:00:02:00"}], None),
            ([{"name": "A", "tc": "00:00:03:00", "lead_in_s": 0}],
             "at least 1 s"),
            ([{"name": "A", "tc": "00:00:03:00", "lead_in_s": 31}],
             "at most 30 s"),
            ([{"name": "A", "tc": "00:00:40:00", "lead_in_s": 30}], None),
            ([{"name": "A", "tc": "00:00:03:00", "lead_in_s": 1.5}],
             "whole number"),
            ([{"name": "A", "tc": "00:00:03:00", "lead_in_s": True}],
             "whole number"),
            ([{"name": "A", "tc": "00:00:03:00", "lead_in_s": "2"}],
             "whole number"),
            ([{"name": "Finale", "tc": "00:00:03:00"},
              {"name": "finale", "tc": "00:00:05:00"}], "used twice"),
            ([{"name": "", "tc": "00:00:03:00"}], "needs a name"),
            ([{"name": "x" * 41, "tc": "00:00:03:00"}], "longer than 40"),
            ([{"name": "x" * 40, "tc": "00:00:03:00"}], None),
            ([{"name": "Act \u2013 two", "tc": "00:00:03:00"}],
             "long dash"),
            ([{"name": "A", "tc": "00:00:03:00", "note": "n" * 201}],
             "longer than 200"),
            ([{"name": "A", "tc": "00:00:03:00", "colour": "red"}],
             "unknown field colour"),
            ([{"name": "A", "tc": "00:00:03:00", "id": "k3"}],
             "not a cue id"),
            ([{"name": "A", "tc": "00:00:03:00", "id": "c1"},
              {"name": "B", "tc": "00:00:04:00", "id": "c1"}],
             "given twice"),
            ([{"name": "A%d" % i, "tc": "00:00:03:00"} for i in range(51)],
             "at most 50 cues"),
            ("Finale", "a list")):
        try:
            PF.check_cues(cues, 120.0)
            check(why is None, f"refused ({why}): {cues!r:.80}")
        except PF.CueError as e:
            check(why is not None and why in str(e) and
                  _cfg_dashes(str(e)), f"{why}: {e}")
    try:
        PF.check_cues([{"name": "A", "tc": "00:00:99:00", "lead_in_s": 0},
                       {"name": "a", "tc": "00:00:03:00"}], 120.0)
    except PF.CueError as e:
        check(str(e).count(";") == 2 and "A:" in str(e) and
              "used twice" in str(e), f"every problem at once: {e}")
    # Review of #192: a lead-in too big for a float, other scripts'
    # digits, control and invisible characters, and two spellings of one
    # name are all refused in words, never raised.
    for v in (10 ** 400, -10 ** 400, 1e300, float("inf")):
        try:
            PF.parse_lead_in(v)
            check(False, f"a lead-in of {str(v)[:12]} is refused")
        except PF.CueError as e:
            check(_cfg_dashes(str(e)), f"{str(v)[:12]}: {e}")
        except Exception as e:                   # noqa: BLE001
            check(False, f"a lead-in of {str(v)[:12]} raised "
                         f"{type(e).__name__}, not a refusal")
    check(PF.parse_lead_in(2.0) == 2 and PF.parse_lead_in(30) == 30,
          "2.0 and 30 are good lead-ins")
    for cues, why in (
            ([{"name": "Q", "tc": "\u0660\u0660:\u0660\u0661:\u0663\u0660:"
                                  "\u0660\u0660"}], "not a time"),
            ([{"name": "A\x00", "tc": "00:00:05:00"}], "control or invisible"),
            ([{"name": "A\u202e", "tc": "00:00:05:00"}],
             "control or invisible"),
            ([{"name": "\u200b", "tc": "00:00:05:00"}], "control or invisible"),
            ([{"name": "A", "tc": "00:00:05:00", "note": "x\ny"}],
             "control or invisible"),
            ([{"name": "A", "tc": "00:00:05:00", "note": "\x1b[31mred"}],
             "control or invisible"),
            ([{"name": "Cafe\u0301", "tc": "00:00:05:00"},
              {"name": "Caf\u00e9", "tc": "00:00:06:00"}], "used twice"),
            ([{"name": "\u200d\u200c", "tc": "00:00:05:00"}],
             "needs a name")):
        try:
            PF.check_cues(cues, 120.0)
            check(False, f"refused ({why}): {cues!r:.80}")
        except PF.CueError as e:
            check(why in str(e) and _cfg_dashes(str(e)), f"{why}: {e}")
    # Kept exactly as typed (review of #192): NFC only compares; circled
    # digits, TM, ligatures, joiners in a word all stay.
    typed = ["Cafe\u0301", "\u2460 \u2122 \ufb01nale", "a\u200db",
             "\u0645\u06cc\u200c\u0634\u0648\u062f", "\uff26inale"]
    got = PF.check_cues([{"name": n, "tc": f"00:00:{10 + i:02d}:00"}
                         for i, n in enumerate(typed + ["Finale"])], 120.0)
    check([c["name"] for c in got] == typed + ["Finale"],
          f"names are kept as typed: {[c['name'] for c in got]}")
    # The file: strict, every cue carries an id.
    doc = {"play_from_format": 1, "rev": 3, "shows": {"Show.json": {
        "cue": "Show", "audio_len_s": 120.0,
        "cues": [{"id": "c2", "name": "Finale", "tc": "00:01:40:00",
                  "lead_in_s": 3, "note": ""}],
        "edited_by": "Jeff", "edited_at": "", "screen": "Rack screen"}}}
    check(PF.read_doc(doc)["shows"]["Show.json"]["cues"][0]["id"] == "c2",
          "a good file reads")
    for change, why in (
            (lambda d: d.update(x=1), "unknown field x"),
            (lambda d: d.update(play_from_format=2), "play_from_format"),
            (lambda d: d.update(rev=-1), "rev"),
            (lambda d: d["shows"]["Show.json"]["cues"][0].pop("id"),
             "not a cue id"),
            (lambda d: d["shows"]["Show.json"].update(audio_len_s=0),
             "seconds above 0"),
            (lambda d: d["shows"]["Show.json"].update(cue=""),
             "names no show cue"),
            (lambda d: d["shows"]["Show.json"]["cues"][0].update(
                tc="00:02:00:00"), "not inside the show audio"),
            (lambda d: d["shows"].update({"../x.json": {}}),
             "not a show file name"),
            (lambda d: d["shows"]["Show.json"].update(next_id=2),
             "next_id"),
            (lambda d: d["shows"]["Show.json"].update(next_id="9"),
             "next_id")):
        d = json.loads(json.dumps(doc))
        change(d)
        try:
            PF.read_doc(d)
            check(False, f"the file is refused: {why}")
        except PF.CueError as e:
            check(why in str(e), f"the file is refused ({why}): {e}")
    # Ids: kept, never claimed, new ones numbered on.
    before = [{"id": "c2", "name": "Finale", "tc": "00:01:40:00",
               "lead_in_s": 3, "note": ""},
              {"id": "c7", "name": "Top", "tc": "00:00:10:00",
               "lead_in_s": 2, "note": ""}]
    after, nxt = PF.give_ids(before, PF.check_cues(
        [{"id": "c2", "name": "Big finale", "tc": "00:01:41:00",
          "lead_in_s": 3}, {"name": "New", "tc": "00:00:20:00"},
         {"name": "Newer", "tc": "00:00:21:00"}], 120.0))
    check([c["id"] for c in after] == ["c8", "c9", "c2"] and nxt == 10,
          f"a new cue gets the next id; a kept one its own: {after}")
    # The high-water mark: an id a deleted cue had is never given again.
    again, nxt2 = PF.give_ids(before[:1], PF.check_cues(
        [{"id": "c2", "name": "Finale", "tc": "00:01:40:00"},
         {"name": "New", "tc": "00:00:20:00"}], 120.0), next_id=10)
    check([c["id"] for c in again] == ["c10", "c2"] and nxt2 == 11,
          f"after c7 was deleted (next 10) a new cue is c10: {again}")
    try:
        PF.give_ids(before, PF.check_cues([{"id": "c9", "name": "X",
                                            "tc": "00:00:20:00"}], 120.0))
        check(False, "an id the list does not have is refused")
    except PF.CueError as e:
        check("not a cue in this list" in str(e), f"a claimed id: {e}")
    text = PF.describe_change(before, after)
    check(text == "New added at 00:00:20:00, lead-in 2 s; Newer added at "
                  "00:00:21:00, lead-in 2 s; Top deleted (was at "
                  "00:00:10:00); Finale renamed to Big finale, time "
                  "00:01:40:00 to 00:01:41:00", f"what changed: {text}")
    c3 = [dict(before[0], lead_in_s=5, note="x")]
    check(PF.describe_change(before[:1], c3) ==
          "Finale lead-in 3 s to 5 s, note changed" and
          PF.describe_change(before, before) == "",
          "a lead-in and a note change; nothing changed")
    # A new render at another length.
    e = {"cues": before, "audio_len_s": 120.0}
    check(PF.audio_note(e, 120.0 + 0.01) == "", "the same length: quiet")
    n = PF.audio_note(e, 90.0)
    check("00:01:30:00 long now, 00:02:00:00 when the list was saved" in n
          and "Past its end now: Finale." in n and _cfg_dashes(n),
          f"a shorter audio names the cue past its end: {n}")
    check(PF.audio_note(e, 150.0).endswith("was saved."),
          "a longer one only says so")
    print("  ok")


def test_play_from_cue_store():
    section("play-from cues: saved whole and atomically, a stale revision "
            "refused with nothing written, the version before kept (the "
            "last 50), a file that cannot be read is no cues for any show, "
            "a journal line and an audit event for every save and every "
            "refusal")
    import json as _j
    import shutil
    from ltcplay import play_from as PF
    work = tempfile.mkdtemp()
    lines, events = [], []
    wall = [1_800_000_000.0]

    class _Audit:
        def event(self, **kw):
            events.append(kw)
    store = PF.Store(work, journal=lambda *a, **k: lines.append((a, k)),
                     audit=_Audit(), wall=lambda: wall[0])
    show = "Fire and Ice.json"
    cues = [{"name": "Finale", "tc": "00:00:50:00", "lead_in_s": 3},
            {"name": "Top", "tc": "00:00:05:00", "note": "act one"}]
    keep = PF.HISTORY_KEEP
    try:
        d, err = store.load()
        check(d == PF.empty_doc() and err == "",
              "no file: no cues, revision 0, no error")
        ok, text, entry = store.save(show, "Show", 60.0, cues, 0,
                                     who="Jeff", screen="Rack screen")
        check(ok and entry["rev"] == 1 and entry["edited_by"] == "Jeff" and
              entry["cue"] == "Show" and entry["audio_len_s"] == 60.0 and
              [(c["id"], c["name"]) for c in entry["cues"]] ==
              [("c1", "Top"), ("c2", "Finale")],
              f"saved, in time order, ids given: {ok} {text} {entry}")
        check(text == "Saved: Top added at 00:00:05:00, lead-in 2 s; Finale "
                      "added at 00:00:50:00, lead-in 3 s.", f"said: {text}")
        check(not [n for n in os.listdir(work) if n.endswith(".tmp")],
              "no temporary file is left behind")
        raw = open(store.path, encoding="utf-8").read()
        check(PF.read_doc(_j.loads(raw))["rev"] == 1,
              "the file on disk is a good list at revision 1")
        check(len(store.history()) == 1 and
              store.history()[0].endswith("-rev1.json") and
              open(os.path.join(store.history_dir(), store.history()[0]),
                   "rb").read() == open(store.path, "rb").read(),
              "every saved file is kept too, the first one included")
        check(lines and lines[-1][0][2] == "saved" and
              "Jeff saved the play-from cues for Fire and Ice.json on the "
              "Rack screen (revision 1): Top added" in lines[-1][0][3],
              f"the journal line names who, where and what: {lines[-1:]}")
        check(events[-1]["user"] == "Jeff" and
              events[-1]["action"] == "play-from cues" and
              events[-1]["target"] == show and
              events[-1]["result"] == "accepted" and
              events[-1]["source"] == "Rack screen" and
              "Finale added" in events[-1]["reason"],
              f"the audit event: {events[-1]}")
        # A stale editor (based on revision 0): refused, nothing written.
        before = open(store.path, "rb").read()
        n_lines = len(lines)
        ok, text, entry = store.save(show, "Show", 60.0, [], 0,
                                     who="Andy", screen="iPad")
        check(not ok and entry is None and "someone saved" in text and
              open(store.path, "rb").read() == before and
              len(store.history()) == 1,
              f"a stale revision is refused and nothing written: {text}")
        check(events[-1]["result"] == "refused" and
              events[-1]["user"] == "Andy" and len(lines) == n_lines + 1 and
              lines[-1][0][2] == "refused",
              "and journaled and audited as refused")
        for bad_rev in (None, "1", True, 1.0, 2):
            ok, text, _e = store.save(show, "Show", 60.0, [], bad_rev)
            check(not ok and open(store.path, "rb").read() == before,
                  f"revision {bad_rev!r}: refused, nothing written")
        # A bad list: refused, nothing written.
        for args, why in (
                (("Show", 60.0, [{"name": "A", "tc": "00:01:00:00"}]),
                 "not inside the show audio"),
                (("Show", 60.0, [{"name": "A", "tc": "00:00:05:00"},
                                 {"name": "a", "tc": "00:00:06:00"}]),
                 "used twice"),
                (("Show", 60.0, [{"name": "A", "tc": "00:00:05:00",
                                  "lead_in_s": 0}]), "at least 1 s"),
                (("", 60.0, cues), "own cue"),
                (("Show", None, cues), "length"),
                (("Show", 60.0, [{"id": "c9", "name": "A",
                                  "tc": "00:00:05:00"}]),
                 "not a cue in this list")):
            ok, text, _e = store.save(show, *args, 1, who="Jeff")
            check(not ok and why in text and text.startswith("Not saved:")
                  and _cfg_dashes(text) and
                  open(store.path, "rb").read() == before,
                  f"refused ({why}), nothing written: {text}")
        ok, text, _e = store.save("../evil.json", "Show", 60.0, [], 1)
        check(not ok and "not a show file name" in text,
              f"a path is not a show file name: {text}")
        # Rename, retime and delete on revision 1: the version before kept.
        wall[0] += 60
        ok, text, entry = store.save(
            show, "Show", 60.0,
            [{"id": "c2", "name": "Big finale", "tc": "00:00:51:00",
              "lead_in_s": 3}], 1, who="Jeff", screen="iPad at 10.0.0.9")
        check(ok and entry["rev"] == 2 and text == (
            "Saved: Top deleted (was at 00:00:05:00); Finale renamed to Big "
            "finale, time 00:00:50:00 to 00:00:51:00.") and
            [c["id"] for c in entry["cues"]] == ["c2"],
            f"the second save: {text}")
        h = store.history()
        check(len(h) == 2 and h[0].endswith("-rev2.json") and
              h[1].endswith("-rev1.json") and
              open(os.path.join(store.history_dir(), h[1]), "rb").read() ==
              before and open(os.path.join(store.history_dir(), h[0]),
                              "rb").read() == open(store.path, "rb").read(),
              f"the version before and the new one are kept whole: {h}")
        # Another show beside it: the first is kept as it was.
        ok, _t, entry = store.save("Other.json", "Show", 30.0, [], 2,
                                   who="Jeff")
        d, err = store.load()
        check(ok and d["rev"] == 3 and set(d["shows"]) == {show,
                                                          "Other.json"} and
              d["shows"][show]["cues"][0]["name"] == "Big finale",
              "a save for another show keeps every other show")
        v = store.view(show)
        check(v["rev"] == 3 and v["entry"]["cues"][0]["id"] == "c2" and
              v["lead_in_default_s"] == 2 and v["lead_in_min_s"] == 1 and
              v["shows"] == ["Fire and Ice.json", "Other.json"] and
              store.view("New.json")["entry"]["cues"] == [],
              "the view: revision, entry, rules")
        # A new cue after a delete never reuses an old id.
        ok, _t, entry = store.save(show, "Show", 60.0,
                                   [{"id": "c2", "name": "Big finale",
                                     "tc": "00:00:51:00", "lead_in_s": 3},
                                    {"name": "Again", "tc": "00:00:05:00"}],
                                   3)
        check(ok and [c["id"] for c in entry["cues"]] == ["c3", "c2"],
              f"ids go on from the highest kept: {entry and entry['cues']}")
        # Only the last HISTORY_KEEP versions are kept.
        PF.HISTORY_KEEP = 4
        rev = entry["rev"]
        for i in range(6):
            wall[0] += 1
            ok, _t, entry = store.save(show, "Show", 60.0, [
                {"name": "A", "tc": f"00:00:{20 + i:02d}:00"}], rev)
            rev = entry["rev"]
        h = store.history()
        check(len(h) == 4 and h[0].endswith(f"-rev{rev}.json") and
              h[-1].endswith(f"-rev{rev - 3}.json"),
              f"the newest {PF.HISTORY_KEEP} are kept: {h}")
        PF.HISTORY_KEEP = keep
        # A write that fails: nothing is changed, said as a fault.
        before = open(store.path, "rb").read()
        real = store._write

        def boom(doc):
            raise OSError(28, "No space left on device")
        store._write = boom
        ok, text, _e = store.save(show, "Show", 60.0, [], rev)
        store._write = real
        check(not ok and "could not be written" in text and
              open(store.path, "rb").read() == before and
              lines[-1][1].get("fault") is True and
              events[-1]["result"] == "error",
              f"a failed write: nothing changed, a fault: {text}")
        # A file that cannot be read: no cues for any show, said, and its
        # revision is never below the highest one ever had.
        high = store.load()[0]["rev"]
        for broken in ("{not json", '{"play_from_format": 1, "rev": 1, '
                       '"shows": {}, "x": 1}'):
            with open(store.path, "w", encoding="utf-8") as fh:
                fh.write(broken)
            d, err = store.load()
            check(d["shows"] == {} and d["rev"] == high and
                  "could not be read" in err and
                  "no show has play-from cues" in err and _cfg_dashes(err),
                  f"a broken file, still revision {high}: {d['rev']} {err}")
            check(store.view(show)["entry"]["cues"] == [] and
                  store.view(show)["error"] == err and
                  store.view(show)["replace_needed"] is True,
                  "and the view says so")
        # (test_play_from_cue_file_is_never_lost proves a save is refused
        # here; an admin's replace saves over it, the broken one kept.)
        wall[0] += 1
        ok, text, entry = store.save(show, "Show", 60.0, cues, high,
                                     who="Jeff", replace=True)
        h = store.history()
        check(ok and entry["rev"] == high + 1 and len(h) > 1 and
              h[0].endswith(f"-rev{high + 1}.json") and h[1].endswith(
            f"-rev{high}-unreadable.json") and open(os.path.join(
                store.history_dir(), h[1]), encoding="utf-8").read() ==
              '{"play_from_format": 1, "rev": 1, "shows": {}, "x": 1}',
              f"replaced on purpose, the broken file kept: {text} {h[:3]} {high}")
        raw = open(store.path, encoding="utf-8").read()
        with open(store.path, "w", encoding="utf-8-sig") as fh:
            fh.write(raw)
        check(store.load()[1] == "", "a file with a BOM (Notepad) reads")
        nf = PF.Store(None)
        check(nf.load() == (PF.empty_doc(), ""), "no folder: empty")
    finally:
        PF.HISTORY_KEEP = keep
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_play_from_cue_file_is_never_lost():
    section("play-from cues (review of #192): a file the engine cannot read "
            "(damaged, a newer format, a number too big, nested too deep) "
            "is never saved over unless an admin asks to replace it; the "
            "revision never goes backwards, so an old page cannot pass the "
            "stale check; the version before is kept only once the new file "
            "is in place; a read never meets a save half way, and a file "
            "held open for a moment (Windows) is tried again")
    import builtins
    import shutil
    from ltcplay import play_from as PF
    work = tempfile.mkdtemp()
    lines, events = [], []

    class _Audit:
        def event(self, **kw):
            events.append(kw)
    store = PF.Store(work, journal=lambda *a, **k: lines.append((a, k)),
                     audit=_Audit())
    one = [{"name": "Finale", "tc": "00:00:50:00"}]

    def rev():
        return store.load()[0]["rev"]

    def body():
        with open(store.path, "rb") as fh:
            return fh.read()
    real_replace, real_open = os.replace, getattr(PF, "open", None)
    try:
        ok1 = store.save("A.json", "Show", 60.0, one, 0, who="Jeff")[0]
        ok2 = store.save("B.json", "Show", 60.0, one, 1, who="Jeff")[0]
        check(ok1 and ok2 and rev() == 2, "two shows' lists, revision 2")
        # The highest id deleted, then a cue added: never that id again.
        ok, _t, e = store.save("B.json", "Show", 60.0, [
            {"id": "c1", "name": "Finale", "tc": "00:00:50:00"},
            {"name": "Top", "tc": "00:00:05:00"}], 2)
        ok2, _t, e2 = store.save("B.json", "Show", 60.0, [
            {"id": "c1", "name": "Finale", "tc": "00:00:50:00"}], 3)
        ok3, _t, e3 = store.save("B.json", "Show", 60.0, [
            {"id": "c1", "name": "Finale", "tc": "00:00:50:00"},
            {"name": "New", "tc": "00:00:06:00"}], 4)
        check(ok and ok2 and ok3 and
              [c["id"] for c in e["cues"]] == ["c2", "c1"] and
              e2["next_id"] == 3 and
              [c["id"] for c in e3["cues"]] == ["c3", "c1"],
              f"c2 deleted, the next cue is c3: {e3 and e3['cues']}")
        ok, _t, _e = store.save("B.json", "Show", 60.0, one, 5)
        check(ok and rev() == 6, "back to one cue, revision 6")
        # Final review of #192: the file deleted, moved or quarantined.
        # A save from a page that read it must not make a file of only its
        # own show: it is refused, and the last saved copy (every show's
        # list) is offered and restored.
        saved = body()
        os.remove(store.path)
        v = store.view("A.json")
        check(v["error"] and "missing" in v["error"] and v["replace_needed"]
              and v["rev"] == 6 and v["restore_from"] and
              v["restore_shows"] == ["A.json", "B.json"],
              f"a missing file reads as missing, the last copy offered: "
              f"{v['error'][:80]} {v.get('restore_from')}")
        ok, text, _e = store.save("A.json", "Show", 60.0,
                                  [{"name": "New", "tc": "00:00:30:00"}], 6,
                                  who="Jeff")
        check(not ok and PF.REPLACE_WORDS in text and
              not os.path.exists(store.path),
              f"no save over a missing file: {text}")
        ok, text, _e = store.restore(5, who="Jeff")
        check(not ok and PF.STALE_WORDS in text, "a stale page restores "
                                                 "nothing")
        ok, text, _e = store.restore(6, who="Jeff", screen="Rack screen")
        d, err = store.load()
        check(ok and err == "" and d["rev"] == 7 and
              d["shows"] == json.loads(saved)["shows"] and
              "restored the last saved copy" in text and
              events[-1]["result"] == "accepted",
              f"restored, every show's list, revision 7: {text}")
        ok, text, _e = store.restore(7)
        check(not ok and "nothing to restore" in text,
              "a file that reads is not restored over")
        # Replace keeps the broken bytes FIRST: when they cannot be kept,
        # nothing is replaced.
        with open(store.path, "w", encoding="utf-8") as fh:
            fh.write("{broken but precious")
        hd = store.history_dir()
        moved = hd + ".away"
        os.rename(hd, moved)
        with open(hd, "w", encoding="utf-8") as fh:
            fh.write("not a folder")
        ok, text, _e = store.save("A.json", "Show", 60.0, one, rev(),
                                  replace=True)
        check(not ok and "could not be kept" in text and
              body() == b"{broken but precious",
              f"the broken file could not be kept, so it was not replaced: "
              f"{text}")
        os.remove(hd)
        os.rename(moved, hd)
        ok, text, _e = store.save("A.json", "Show", 60.0, one, rev(),
                                  replace=True)
        h = store.history()
        check(ok and any(open(os.path.join(hd, n), "rb").read() ==
                         b"{broken but precious" for n in h
                         if "-unreadable" in n),
              f"replaced, the broken bytes kept: {h[:3]}")
        # A good file held open for a second (a sync program, a virus
        # scanner) is waited for, never offered for replacement.
        slow = []

        def held_open(path, *a, **k):
            if path == store.path and len(slow) < 20:
                slow.append(path)
                raise PermissionError(13, "in use")
            return builtins.open(path, *a, **k)
        PF.open = held_open
        d, err = store.load()
        del PF.open
        check(err == "" and len(slow) == 20 and d["shows"],
              f"held open for about a second: read, not broken: {err}")
        for broken, what in (
                ("{not json", "bad JSON"),
                ('{"play_from_format": 2, "rev": 9, "shows": {}}',
                 "a newer format"),
                ('{"play_from_format": 1, "rev": 3, "shows": {"A.json": '
                 '{"cue": "Show", "audio_len_s": 60, "cues": [{"id": "c1", '
                 '"name": "x", "tc": "00:00:05:00", "lead_in_s": 1' +
                 "0" * 400 + ', "note": ""}]}}}', "a number too big"),
                ("[" * 100000, "nesting too deep")):
            with open(store.path, "w", encoding="utf-8") as fh:
                fh.write(broken)
            try:
                d, err = store.load()
                v = store.view("A.json")
            except Exception as e:               # noqa: BLE001
                check(False, f"{what}: load or view raised "
                             f"{type(e).__name__}")
                continue
            check(err and v["error"] == err and v["replace_needed"] and
                  d["rev"] >= 2 and _cfg_dashes(err),
                  f"{what}: read as broken, revision {d['rev']}: {err[:90]}")
            n = len(events)
            ok, text, _e = store.save("A.json", "Show", 60.0, one, d["rev"],
                                      who="Andy", screen="iPad")
            check(not ok and PF.REPLACE_WORDS in text and
                  "every show" in text and body() == broken.encode() and
                  events[n:] and events[-1]["result"] == "refused" and
                  lines[-1][0][2] == "refused",
                  f"{what}: a save is refused, the file untouched, "
                  f"journaled and audited: {text}")
        check(rev() >= 9, f"a newer file's revision 9 is not forgotten: "
                          f"{rev()}")
        # An old page (revision 0, read before anything was saved) cannot
        # replace it either: the revision never goes back to 0.
        ok, text, _e = store.save("A.json", "Show", 60.0, one, 0,
                                  replace=True)
        check(not ok and PF.STALE_WORDS in text,
              f"an old page's revision is stale even over a broken file: "
              f"{text}")
        # An admin replaces it on purpose: B's list goes, the broken file
        # is kept, the revision goes on up.
        r = rev()
        n_hist = len(store.history())
        ok, text, entry = store.save("A.json", "Show", 60.0, one, r,
                                     who="Jeff", replace=True)
        h = store.history()
        check(ok and entry["rev"] == r + 1 and
              "replaced the file that could not be read" in text and
              len(h) == n_hist + 2 and h[0].endswith(f"-rev{r + 1}.json")
              and "-unreadable" in h[1] and
              open(os.path.join(store.history_dir(), h[1]), "rb").read() ==
              b"[" * 100000 and list(store.load()[0]["shows"]) ==
              ["A.json"], f"replaced on purpose: {text} {h[:2]}")
        # Deleted, or put back from an old copy by hand: the revision is
        # still the highest one, and a page that read it before is stale.
        top = rev()
        os.remove(store.path)
        check(rev() == top, f"the file deleted: still revision {top}")
        ok, text, _e = store.save("A.json", "Show", 60.0, one, top)
        check(not ok and PF.REPLACE_WORDS in text and "missing" in
              store.load()[1] and not os.path.exists(store.path),
              f"a file that was saved before and is gone now: no save over "
              f"it, even from a page with the right revision: {text}")
        ok, text, _e = store.save("A.json", "Show", 60.0, one, 0,
                                  replace=True)
        check(not ok and PF.STALE_WORDS in text,
              "a page from before cannot replace a deleted file")
        with open(store.path, "w", encoding="utf-8") as fh:
            json.dump({"play_from_format": 1, "rev": 1, "shows": {}}, fh)
        store2 = PF.Store(work)          # a restart: from the history
        check(store2.load()[0]["rev"] >= top and store2.load()[1] == "",
              f"an old copy put back, after a restart: revision "
              f"{store2.load()[0]['rev']}, not 1")
        ok, text, _e = store2.save("A.json", "Show", 60.0, one, 1)
        check(not ok and PF.STALE_WORDS in text,
              "a page that read revision 1 is stale")
        # The version before is kept only once the new file is in place.
        r = rev()
        before, n_hist = body(), len(store.history())

        def no_space(doc):
            raise OSError(28, "No space left on device")
        real_write = store._write
        store._write = no_space
        ok, text, _e = store.save("A.json", "Show", 60.0, one, r)
        store._write = real_write
        check(not ok and body() == before and
              len(store.history()) == n_hist,
              f"a failed write keeps no history copy: {store.history()[:2]}")
        # Windows: a replace that meets the file held open is tried again.
        tries = []

        def busy_replace(src, dst):
            if dst == store.path and len(tries) < 2:
                tries.append(dst)
                raise PermissionError(13, "in use")
            return real_replace(src, dst)
        os.replace = busy_replace
        ok, text, _e = store.save("A.json", "Show", 60.0, one, r)
        os.replace = real_replace
        check(ok and len(tries) == 2, f"a busy file is replaced on the "
                                      f"third try: {text}")
        reads = []

        def busy_open(path, *a, **k):
            if path == store.path and len(reads) < 2:
                reads.append(path)
                raise PermissionError(13, "in use")
            return builtins.open(path, *a, **k)
        PF.open = busy_open
        d, err = store.load()
        del PF.open
        check(err == "" and len(reads) == 2 and d["shows"],
              f"a busy file is read on the third try: {err}")
        # A read never meets a save half way: it waits for the lock.
        got = []
        store._lock.acquire()
        t = threading.Thread(target=lambda: got.append(store.load()))
        t.start()
        t.join(0.2)
        waited = not got
        store._lock.release()
        t.join(5)
        check(waited and got, "a read waits while a save holds the file")
        # A hand-edited revision too big is clamped, never reset to 0.
        with open(store.path, "w", encoding="utf-8") as fh:
            json.dump({"play_from_format": 1, "rev": 10 ** 13,
                       "shows": {}}, fh)
        check(rev() == PF.MAX_REV, f"a revision of 10**13 counts as "
                                   f"{PF.MAX_REV}: {rev()}")
        ok, _t, e = store.save("A.json", "Show", 60.0, one, PF.MAX_REV)
        check(ok and e["rev"] == PF.MAX_REV + 1 and rev() >= PF.MAX_REV,
              "and the next save goes on from there")
    finally:
        os.replace = real_replace
        if real_open is None and hasattr(PF, "open"):
            del PF.open
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_play_from_cue_routes():
    section("play-from cue routes: anyone signed in reads; a save needs a "
            "signed-in admin (the Settings row), from the show network "
            "screen_arming too; the show's cue and audio length from the "
            "engine, never the page; journaled and audited; nothing sent "
            "and nothing on the start path reads the list")
    import shutil
    import types
    from ltcplay import remote as RM
    from ltcplay import users as U
    from ltcplay import play_from as PF
    check("play-from-cues-save" in RM.POST_ROUTES and
          "play-from-cues" in RM.GET_ROUTES and
          U.REMOTE_ROUTES["play-from-cues-save"] == "settings",
          "the routes, and a save is the Settings row")
    for body in ({}, {"cues": []}, {"show": "x"}, None):
        check(U.classify("/api/remote/play-from-cues-save", body) ==
              "settings", f"whatever the body: Settings ({body!r})")
    check(U.DEFAULT_MATRIX["admin"]["settings"] is True and
          U.DEFAULT_MATRIX["operator"]["settings"] is False and
          "the play-from cues" in dict(U.PERMS)["settings"],
          "admin only by default, and the row says so")
    here = os.path.dirname(os.path.abspath(__file__))
    users_md = open(os.path.join(here, "USERS.md"), encoding="utf-8").read()
    check("sign out after the last show, the play-from cues" in users_md
          and "| yes | no | no | never |" in users_md,
          "USERS.md's matrix row")
    # Sends nothing: the module imports only the standard library (and the
    # audit log, to write an event), and nothing but the routes reads it.
    src = open(os.path.join(here, "ltcplay", "play_from.py"),
               encoding="utf-8").read()
    imports = sorted(set(re.findall(r"^\s*(?:import|from)\s+([\w.]+)", src,
                                    re.M)))
    check(imports == [".", "datetime", "json", "math", "os", "re",
                      "threading", "time", "unicodedata"] and
          "from . import audit as audit_mod" in src,
          f"play_from.py imports nothing that sends: {imports}")
    users_of = []
    for f in sorted(os.listdir(os.path.join(here, "ltcplay"))):
        if f.endswith(".py") and f != "play_from.py":
            t = open(os.path.join(here, "ltcplay", f), encoding="utf-8").read()
            if re.search(r"import play_from\b|\bplay_from as\b|"
                         r"\bplay_from_(?:store|get|save|show_info)\b", t):
                users_of.append(f)
    # Part 2 (Start at a cue): the routes read the file (Remote.
    # start_at_cue); the scheduler and the runner only ever use the cue the
    # route handed them, through the model's pure helpers, never the Store.
    check(users_of == ["fire_ice.py", "remote.py", "schedule_service.py"],
          f"only the routes read the cue list; the start path gets the cue "
          f"from them: {users_of}")
    for f in ("fire_ice.py", "schedule_service.py"):
        t = open(os.path.join(here, "ltcplay", f), encoding="utf-8").read()
        used = set(re.findall(r"pf_mod\.(\w+)", t))
        check(used and used <= {"landing_s", "start_words",
                                "LANDING_FADE_S"} and "Store(" not in t,
              f"{f} reads no cue file, only the cue it was given: {used}")
    rsrc = open(os.path.join(here, "ltcplay", "remote.py"),
                encoding="utf-8").read()
    for fn in ("play_from_get", "play_from_save", "play_from_show_info",
               "play_from_store"):
        body = rsrc[rsrc.find(f"    def {fn}("):]
        body = body[:body.find("\n    def ", 10)]
        check(body and not re.search(r"\b(?:press|start_now|operator_press|"
                                     r"clock_play|send|arm|flame)\w*\(",
                                     body),
              f"{fn} presses, starts and sends nothing")
    work = tempfile.mkdtemp()
    journal = []
    events = []

    class _Svc:
        conductor = None
        machine = types.SimpleNamespace(state="IDLE")

        def journal_press(self, *a, **kw):
            journal.append(a)

    class _Audit:
        def event(self, **kw):
            events.append(kw)
    ctl = types.SimpleNamespace(session=None, folder=work,
                                state=lambda: {})
    rm = RM.Remote(ctl, _Svc(), folder=work, log=lambda t_: None)
    rm.audit = _Audit()
    matrix = U.normalise_matrix(None)

    def users_on():
        rm.users = types.SimpleNamespace(
            active=lambda: True, matrix=lambda: matrix,
            may=lambda role, perm: U.allowed(matrix, role, perm))
    users_on()
    info = {"Show.json": ("Show", 120.0, "")}
    opened = []

    def fake_info(show):
        opened.append(show)
        return info.get(show, (None, None, f"{show} is not in the show "
                                           f"folder"))
    rm.play_from_show_info = fake_info

    def ctx(role=None, local=True, name="Jeff"):
        return RM.Ctx(local, "127.0.0.1" if local else "10.0.0.9",
                      session={"name": name, "role": role} if role else None)
    good = {"show": "Show.json", "rev": 0,
            "cues": [{"name": "Finale", "tc": "00:01:40:00", "lead_in_s": 3},
                     {"name": "Top", "tc": "00:00:05:00", "note": "act"}]}
    path = os.path.join(work, PF.FILE)

    def save(body, c):
        return rm.post("/api/remote/play-from-cues-save", body, c)

    def read(c, q="show=Show.json"):
        return rm.get("/api/remote/play-from-cues", c, q)
    try:
        # Reading: signed in, any role, from the show PC or the network.
        for c in (ctx("viewer", False, "Vee"), ctx("operator", name="Dave"),
                  ctx("admin")):
            code, out = read(c)
            check(code == 200 and out["rev"] == 0 and out["cue"] == "Show"
                  and out["audio_len_s"] == 120.0 and
                  out["entry"]["cues"] == [] and out["show_problem"] == ""
                  and out["audio_note"] == "" and
                  out["may_edit"] == (c.session["role"] == "admin"),
                  f"{c.session['role']} reads it: {code} {out}")
        code, out = read(ctx(None))
        check(code == 403 and "Sign in" in out["error"],
              f"signed out: not read: {code} {out}")
        code, out = read(ctx("admin", local=False))
        check(code == 200 and out["may_edit"] is False,
              "an admin's iPad without screen_arming reads, may not edit")
        opened.clear()
        code, out = read(ctx("admin"), "")
        check(code == 200 and "entry" not in out and opened == [],
              "without ?show= no show file is opened")
        # Who may save.
        for c, why in ((ctx(None), "signed-in admin"),
                       (ctx("operator", name="Dave"), "may not"),
                       (ctx("viewer", name="Vee"), "may not"),
                       (ctx("admin", local=False), "screen_arming")):
            code, out, _h = save(good, c)
            check(code == 403 and why in out["error"] and
                  "Nothing was changed" in out["error"] and
                  _cfg_dashes(out["error"]) and not os.path.exists(path),
                  f"refused ({why}): {code} {out}")
        check(events and events[-1]["result"] == "refused" and
              events[-1]["action"] == "play-from cues" and
              journal and journal[-1][3] == "refused",
              "a refused save is journaled and audited")
        rm.users = types.SimpleNamespace(active=lambda: False,
                                         matrix=lambda: matrix,
                                         may=lambda r, p: True)
        code, out, _h = save(good, ctx("admin"))
        check(code == 403 and "signed-in admin" in out["error"],
              "with no users set up, nobody may save (admin only)")
        # With no users file, the show PC reads it as the other Settings
        # do (review of #192), read only, and says why; the network not.
        code, out = read(ctx(None))
        check(code == 200 and out["may_edit"] is False and
              "Set up users first" in out["edit_why"] and
              out["cue"] == "Show",
              f"no users: the show PC reads it, read only: {code} {out}")
        code, out = read(ctx(None, local=False))
        check(code == 403, "no users: the show network does not read it")
        users_on()
        code, out, _h = save(dict(good, show="Nope.json"), ctx("admin"))
        check(code == 409 and "Nope.json is not in the show folder" in
              out["error"] and not os.path.exists(path),
              f"a show that cannot be opened: {code} {out}")
        code, out, _h = save(dict(good, show=None), ctx("admin"))
        check(code == 400 and "choose a show file" in out["error"],
              "no show file")
        # Saved by an admin on the show PC; the cue and the audio length
        # are the engine's (the page's own are ignored).
        opened.clear()
        code, out, _h = save(dict(good, audio_len_s=99999, cue="Fake"),
                             ctx("admin"))
        check(code == 200 and out["entry"]["rev"] == 1 and
              out["entry"]["cue"] == "Show" and
              out["entry"]["audio_len_s"] == 120.0 and
              out["entry"]["edited_by"] == "Jeff" and
              out["entry"]["screen"] == "Rack screen" and
              [c["name"] for c in out["entry"]["cues"]] == ["Top", "Finale"]
              and opened == ["Show.json"], f"saved: {code} {out}")
        check(journal[-1][2] == "play-from cues" and
              journal[-1][3] == "saved" and "Jeff saved the play-from cues "
              "for Show.json on the Rack screen (revision 1)" in
              journal[-1][4] and events[-1]["result"] == "accepted" and
              events[-1]["user"] == "Jeff",
              f"journaled and audited: {journal[-1]}")
        # Past the end of the audio, by the engine's length.
        code, out, _h = save(dict(good, rev=1, cues=[
            {"name": "Late", "tc": "00:02:00:00"}]), ctx("admin"))
        check(code == 409 and "not inside the show audio" in out["error"]
              and out["error"].endswith("Nothing was changed."),
              f"a cue past the audio's end: {out}")
        code, out, _h = save(good, ctx("admin"))
        check(code == 409 and "someone saved" in out["error"],
              f"a stale page: {out}")
        # From the network with screen_arming: allowed.
        RM.save_settings(work, screen_arming=True)
        code, out = read(ctx("admin", False))
        ids = {c["name"]: c["id"] for c in out["entry"]["cues"]}
        code, out, _h = save({"show": "Show.json", "rev": out["rev"],
                              "cues": [{"id": ids["Finale"],
                                        "name": "Finale",
                                        "tc": "00:01:41:00",
                                        "lead_in_s": 3}]},
                             ctx("admin", local=False, name="Andy"))
        check(code == 200 and out["entry"]["rev"] == 2 and
              out["entry"]["screen"] == "iPad" and
              out["text"] == "Saved: Top deleted (was at 00:00:05:00); "
                             "Finale time 00:01:40:00 to 00:01:41:00.",
              f"an admin's iPad with screen_arming: {out}")
        # The audio rendered again shorter: the read says so.
        info["Show.json"] = ("Show", 90.0, "")
        code, out = read(ctx("viewer", False, "Vee"))
        check(code == 200 and "Past its end now: Finale" in
              out["audio_note"], f"a new render: {out.get('audio_note')}")
        # Review of #192: a list whose show file is gone is named; one that
        # is there is not.
        check(out["missing"] == ["Show.json"],
              f"no Show.json in the folder: named: {out['missing']}")
        open(os.path.join(work, "Show.json"), "w").close()
        code, out = read(ctx("viewer", False, "Vee"))
        check(out["missing"] == [], f"Show.json there: {out['missing']}")
        # The name exactly as the folder spells it, even on a disk that
        # does not tell case apart (Windows, macOS): simulated here.
        real_isfile = os.path.isfile
        os.path.isfile = lambda p_: True if os.path.dirname(p_) == work \
            else real_isfile(p_)
        try:
            got = RM.Remote.play_from_show_info(rm, "show.json")
        finally:
            os.path.isfile = real_isfile
        check(got[0] is None and "show.json is not in the show folder" in
              got[2], f"show.json is not Show.json: {got}")
        # A broken file: the save says so (the page offers Replace), and
        # the replace an admin asks for goes through.
        with open(path, "w", encoding="utf-8") as fh:
            fh.write("{broken")
        code, out = read(ctx("admin", False))
        r = out["rev"]
        check(out["replace_needed"] is True and r >= 2,
              f"a broken file is read as broken: {out.get('error')}")
        code, out, _h = save({"show": "Show.json", "rev": r, "cues": []},
                             ctx("admin"))
        check(code == 409 and out["replace_needed"] is True and
              out["stale"] is False and open(path).read() == "{broken",
              f"not saved over without replace: {out}")
        code, out, _h = save({"show": "Show.json", "rev": r - 1,
                              "cues": [], "replace": True}, ctx("admin"))
        check(code == 409 and out["stale"] is True and
              out["replace_needed"] is False, f"a stale page: {out}")
        code, out, _h = save({"show": "Show.json", "rev": r, "cues": [],
                              "replace": "yes"}, ctx("admin"))
        check(code == 409 and out["replace_needed"] is True,
              "replace is the JSON word true, nothing else")
        code, out, _h = save({"show": "Show.json", "rev": r, "cues": [],
                              "replace": True}, ctx("admin"))
        check(code == 200 and out["entry"]["rev"] == r + 1 and
              "replaced the file" in out["text"], f"replaced: {out}")
        # Final review of #192: the file gone; the last saved copy put back
        # through the route, an admin's Settings press like a save.
        os.remove(path)
        code, out = read(ctx("admin"))
        r = out["rev"]
        check(out["replace_needed"] and out["restore_from"],
              f"a missing file offers the last copy: {out.get('error')}")
        code, out, _h = save({"restore": True, "rev": r},
                             ctx("operator", name="Dave"))
        check(code == 403 and not os.path.exists(path),
              "an operator restores nothing")
        code, out, _h = save({"restore": True, "rev": r - 1}, ctx("admin"))
        check(code == 409 and out["stale"] is True, "a stale page neither")
        code, out, _h = save({"restore": True, "rev": r}, ctx("admin"))
        code2, out2 = read(ctx("admin"))
        check(code == 200 and "restored the last saved copy" in out["text"]
              and out2["error"] == "" and out2["rev"] == r + 1 and
              os.path.exists(path), f"restored: {out}")
        # One store per engine, whoever asks first (two requests at once).
        rm2 = RM.Remote(ctl, _Svc(), folder=work, log=lambda t_: None)
        stores = []
        gate = threading.Barrier(8)
        real_store = PF.Store

        class _SlowStore(real_store):
            # Made slowly, so eight first requests overlap for certain.
            def __init__(self, *a, **k):
                time.sleep(0.05)
                super().__init__(*a, **k)

        def first():
            gate.wait()
            stores.append(rm2.play_from_store())
        PF.Store = _SlowStore
        try:
            ts = [threading.Thread(target=first) for _ in range(8)]
            for t_ in ts:
                t_.start()
            for t_ in ts:
                t_.join(5)
        finally:
            PF.Store = real_store
        rm2.audit = _Audit()
        check(len(stores) == 8 and len({id(x) for x in stores}) == 1 and
              rm2.play_from_store() is stores[0] and
              stores[0].audit is rm2.audit,
              "one store per engine, made once; a new audit log is handed "
              "to it, never a second store")
    finally:
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_play_from_cue_audio_length_from_a_real_show_file():
    section("play-from cues: the show's own cue and its AUDIO length (not "
            "the longer lights file) come from the show file opened as the "
            "Check button opens it (nothing sent, nothing played)")
    import shutil
    import types
    from ltcplay import remote as RM
    from ltcplay import settings as st_mod
    import ltcplay.player as plmod
    real_path, real_prefs = st_mod.path, st_mod.prefs_path
    real_prepare = plmod.Player._prepare

    def fake_prepare(self, cue):
        cue.fseq = FakeFSEQ(frames=160)          # 4 s of lights
        cue.duration = cue.fseq.duration_ms / 1000.0
        cue._spans = [(0, 0, cue.fseq.channel_count)]
        cue._gaps = None
        return 0
    work = tempfile.mkdtemp()
    try:
        st_mod.path = lambda: os.path.join(work, st_mod.FILENAME)
        st_mod.prefs_path = lambda: os.path.join(work, st_mod.PREFS_FILE)
        plmod.Player._prepare = fake_prepare
        _tl, tlp, net = _am_show(work, 2.0)       # 2 s of audio
        ctl = types.SimpleNamespace(folder=work, defaults={"networks": net},
                                    _sd=FakeSD(), session=None)
        rm = RM.Remote(ctl, None, folder=work, log=lambda t_: None)
        cue, length, why = rm.play_from_show_info(os.path.basename(tlp))
        check(cue == "Show" and why == "" and abs(length - 2.0) < 0.05,
              f"the show cue and its audio's length: {cue} {length} {why}")
        for bad in ("nope.json", "../x.json", "", None):
            cue, length, why = rm.play_from_show_info(bad)
            check(cue is None and length is None and why and
                  _cfg_dashes(why), f"{bad!r}: {why}")
    finally:
        st_mod.path, st_mod.prefs_path = real_path, real_prefs
        plmod.Player._prepare = real_prepare
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_play_from_cue_card_in_2_0():
    section("2.0 Settings, Play-from cues: on the Settings tab only, never "
            "the SHOW tab; it reads and saves only the cue list routes; it "
            "marks a cue the engine would refuse, rule for rule, and sends "
            "the id it read, so a rename is a rename; OPERATOR.md says it "
            "in plain words")
    import shutil
    import subprocess
    from ltcplay import play_from as PF
    one, two = _ui2_pages()
    sec = two[two.find('<section class="pane" id="t-settings"'):]
    sec = sec[:sec.find("</section>")]
    show = two[two.find('<section class="pane" id="t-show"'):]
    show = show[:show.find("</section>")]
    check('id="set-pf"' in sec and "<b>Play-from cues</b>" in sec and
          'id="pf-add"' in sec and 'id="pf-save"' in sec and
          'id="pf-show"' in sec and "pf-" not in show,
          "the card is on the Settings tab, nothing of it on SHOW")
    check('"/api/remote/play-from-cues?show="' in two and
          'const body = {show:PF.show, rev:PF.rev, cues:cues};' in two and
          'post("/api/remote/play-from-cues-save", body)' in two and
          "/api/remote/play-from-cues" not in one,
          "it reads and saves the cue list routes, 2.0's own")
    for n in ("pfCheck", "pfFrames", "pfTc", "pfDraw", "loadPlayFrom"):
        f = _js_function(two, n)
        check(f is not None and not re.search(
            r'press\(|"/api/start"|"/api/remote/(?!play-from-cues)', f),
            f"{n} presses nothing and starts nothing")
    here = os.path.dirname(os.path.abspath(__file__))
    op = open(os.path.join(here, "OPERATOR.md"), encoding="utf-8").read()
    a = op.find('- Settings, "Play-from cues"')
    para = op[a:op.find("\n- ", a + 3)]
    for words in ("sends nothing to the rig", "ltcplay_play_from.json",
                  "play_from_history", "at least 1", "2 when left",
                  "inside the show AUDIO", "used once", "journal",
                  "Anyone signed in can read", "tap Reload",
                  "Restore the last saved copy", "gone now",
                  "Replace the", "exactly as", "nobody can save it",
                  "control or invisible"):
        check(a > 0 and words in para, f"OPERATOR.md says: {words}")
    check(a > 0 and _cfg_dashes(para), "OPERATOR.md: no long dashes")
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner")
        print("  note: node is not here; the card's rules were checked by "
              "reading only")
        print("  ok")
        return
    # The card's rules against the engine's, cue list by cue list: the card
    # marks a list exactly when the engine refuses it.
    cases = [
        [{"name": "A", "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:00:01:29", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:00:02:00", "lead_in_s": ""}],
        [{"name": "A", "tc": "00:00:01:00", "lead_in_s": 1}],
        [{"name": "A", "tc": "00:00:03:00", "lead_in_s": 0}],
        [{"name": "A", "tc": "00:00:50:00", "lead_in_s": 30}],
        [{"name": "A", "tc": "00:00:50:00", "lead_in_s": 31}],
        [{"name": "A", "tc": "00:00:50:00", "lead_in_s": "1.5"}],
        [{"name": "A", "tc": "00:01:59:29", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:02:00:00", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:00:05:30", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:60:05:00", "lead_in_s": 2}],
        [{"name": "A", "tc": "0:00:05:00", "lead_in_s": 2}],
        [{"name": "Finale", "tc": "00:00:05:00", "lead_in_s": 2},
         {"name": " finale ", "tc": "00:00:06:00", "lead_in_s": 2}],
        [{"name": "Cafe\u0301", "tc": "00:00:05:00", "lead_in_s": 2},
         {"name": "CAF\u00c9", "tc": "00:00:06:00", "lead_in_s": 2}],
        [{"name": "\uff26inale", "tc": "00:00:05:00", "lead_in_s": 2},
         {"name": "Finale", "tc": "00:00:06:00", "lead_in_s": 2}],
        [{"name": "Act  two", "tc": "00:00:05:00", "lead_in_s": 2},
         {"name": "act two", "tc": "00:00:06:00", "lead_in_s": 2}],
        [{"name": "", "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "   ", "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "x" * 40, "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "x" * 41, "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "Act \u2014 two", "tc": "00:00:05:00", "lead_in_s": 2}],
        [{"name": "A", "tc": "00:00:05:00", "lead_in_s": 2,
          "note": "n" * 200}],
        [{"name": "A", "tc": "00:00:05:00", "lead_in_s": 2,
          "note": "n" * 201}],
    ]
    want = []
    for cues in cases:
        sent = []
        for c in cues:
            o = dict(c)
            l_ = str(o.get("lead_in_s", "")).strip()
            o["lead_in_s"] = None if l_ == "" else float(l_)
            if o["lead_in_s"] is not None and o["lead_in_s"].is_integer():
                o["lead_in_s"] = int(o["lead_in_s"])
            o["name"] = o["name"].strip()
            sent.append(o)
        try:
            PF.check_cues(sent, 120.0)
            want.append(False)
        except PF.CueError:
            want.append(True)
    check(any(want) and not all(want), "the cases hold lists the engine "
          "saves and lists it refuses")
    # Review of #192: the broken file, the stale page, Reload, Replace and
    # a Time field wide enough for HH:MM:SS:FF.
    for need in ('id="pf-reload"', 'id="pf-replace" hidden',
                 "Replace the file</button>"):
        check(need in sec, f"the card has {need}")
    check('const PF_STALE_WORDS = "' + PF.STALE_WORDS + '";' in two,
          "the card knows the engine's stale words")
    check(re.search(r"\.pfrow\{display:grid;grid-template-columns:"
                    r"minmax\(0,2fr\) minmax\((1[7-9]\d|[2-9]\d\d)px,", two),
          "the Time column is never narrower than HH:MM:SS:FF (172 px)")
    check("if(PF.error && PF_REPLACE) body.replace = true;" in two and
          two.count("PF_REPLACE = true") == 1,
          "replace is sent only after Replace the file was chosen")
    fn_r = _js_function(two, "loadPlayFrom") or ""
    check("PF_STALE = false; PF_REPLACE = false;" in fn_r,
          "a fresh read clears the stale lock and the replace choice")
    flow = r"""
let PF = null, PF_DIRTY = false, PF_REPLACE = false, PF_STALE = false;
const PF_STALE_WORDS = "%s";
const PF_REPLACE_WORDS = "%s";
const out = [];
PF = {may_edit:true, error:""}; PF_DIRTY = true;
out.push(["edit", pfMayEdit(), pfSaveOk([[]])]);
out.push(["bad cue", pfSaveOk([["Name used twice."]])]);
PF = {may_edit:false, error:""};
out.push(["viewer", pfMayEdit(), pfSaveOk([[]])]);
PF = {may_edit:true, error:"could not be read"};
out.push(["broken", pfMayEdit(), pfSaveOk([[]])]);
PF_REPLACE = true;
out.push(["broken, replace chosen", pfMayEdit(), pfSaveOk([[]])]);
PF = {may_edit:true, error:""}; PF_REPLACE = false;
const said = pfRefused("Not saved: the name is too long.");
out.push(["other refusal", PF_STALE, said]);
const said2 = pfRefused("Not saved: someone saved the play-from cues %s. Reload.");
out.push(["stale", PF_STALE, pfMayEdit(), pfSaveOk([[]]), said2]);
PF = {may_edit:true, error:""}; PF_STALE = false; PF_DIRTY = true;
const said3 = pfRefused("Not saved: the file could not be read or is missing, and a save would replace the cue lists of every show in it. Restore the last saved copy, fix the file, or choose %s on 2.0 Settings.");
out.push(["broke after read", PF_STALE, !!PF.error, pfMayEdit(), pfSaveOk([[]])]);
console.log(JSON.stringify(out));
""" % (PF.STALE_WORDS, PF.REPLACE_WORDS, PF.STALE_WORDS, PF.REPLACE_WORDS)
    fns = "\n".join(_js_function(two, n) or "" for n in
                    ("pfFrames", "pfTc", "pfCheck", "pfBody"))
    js = ("const PF_DASH = /[\\u2013\\u2014]/;\n" + fns +
          "\nconst rules = " + json.dumps(PF.Store(None).view()) + ";\n"
          "const cases = " + json.dumps(cases) + ";\n"
          "console.log(JSON.stringify(cases.map(c => "
          "pfCheck(c, 120.0, rules))));\n"
          "console.log(JSON.stringify(pfBody([{id:\"c2\", name:\" Big  "
          "finale \", tc:\"00:01:41:00 \", lead_in_s:\"3\", note:\"\"}, "
          "{name:\"New\", tc:\"00:00:20:00\", lead_in_s:\"\"}, "
          "{name:\"Two\", tc:\"00:00:21:00\", lead_in_s:2, "
          "note:\" x \"}])));\n")
    with tempfile.TemporaryDirectory() as td:
        p = os.path.join(td, "pf.js")
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(js)
        r = subprocess.run([node, p], capture_output=True, text=True,
                           timeout=60)
    out_lines = r.stdout.strip().splitlines()
    try:
        got = json.loads(out_lines[0])
        sent = json.loads(out_lines[1])
    except (ValueError, IndexError):
        got = sent = None
    check(sent == [{"name": "Big  finale", "tc": "00:01:41:00", "note": "",
                    "lead_in_s": 3, "id": "c2"},
                   {"name": "New", "tc": "00:00:20:00", "note": "",
                    "lead_in_s": None},
                   {"name": "Two", "tc": "00:00:21:00", "note": "x",
                    "lead_in_s": 2}],
          f"Save sends each cue with the id it was read with (none for a "
          f"new one), trimmed, an empty lead-in as none: {sent}")
    check(got is not None and len(got) == len(cases),
          f"the card's rules ran: {r.stdout[:300]} {r.stderr[:600]}")
    for i, cues in enumerate(cases if got else []):
        marked = any(len(per) for per in got[i])
        said = [t for per in got[i] for t in per]
        check(marked == want[i],
              f"the card {'marks' if marked else 'passes'} what the engine "
              f"{'refuses' if want[i] else 'saves'}: {cues!r:.120} "
              f"{got[i]}")
        check(all(_cfg_dashes(t) and len(t.split()) <= 8 for t in said),
              f"the card's words are short, no long dashes: {said}")
    # Who may edit and save, over a broken file and after a stale save.
    fl = "\n".join(_js_function(two, n) or "" for n in
                    ("pfMayEdit", "pfSaveOk", "pfRefused")) + flow
    with tempfile.TemporaryDirectory() as td:
        p = os.path.join(td, "flow.js")
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(fl)
        r = subprocess.run([node, p], capture_output=True, text=True,
                           timeout=60)
    try:
        st = {row[0]: row[1:] for row in json.loads(r.stdout)}
    except (ValueError, TypeError):
        st = {}
    check(st.get("edit") == [True, True] and st.get("bad cue") == [False]
          and st.get("viewer") == [False, False],
          f"an admin edits and saves a good list; a viewer neither: {st} "
          f"{r.stderr[:300]}")
    check(st.get("broken") == [False, False] and
          st.get("broken, replace chosen") == [True, True],
          f"over a broken file nothing is edited or saved until Replace "
          f"the file is chosen: {st}")
    check(st.get("other refusal") == [False,
                                      "Not saved: the name is too long."]
          and (st.get("stale") or [None])[:3] == [True, False, False] and
          str((st.get("stale") or [""])[-1]).endswith("Tap Reload."),
          f"a stale save locks this copy until Reload: {st}")
    check(st.get("broke after read") == [False, True, False, False],
          f"a page that read the file before it broke: after its refused "
          f"save, no Save; Replace (and Restore) offered: {st}")
    check('const PF_REPLACE_WORDS = "' + PF.REPLACE_WORDS + '";' in two and
          'id="pf-restore" hidden' in sec and
          "Restore the last saved copy</button>" in sec and
          'post("/api/remote/play-from-cues-save", {restore:true, '
          'rev:PF.rev})' in two,
          "the card offers Restore the last saved copy, an admin's press")
    print("  ok")


# ---------------------------------------------------------------------------
# Play-from cues, part 3: the 2.0 Resume sheet. Resume offers the cue the
# engine offers (play-from-cues `resume`), and any saved cue can be picked
# from Resume or Start now; the start is POST start-at-cue with Start now's
# confirm. Show mode only.
# ---------------------------------------------------------------------------

def test_ui2_resume_from_a_cue():
    section("2.0's Resume sheet (play-from cues part 3): with saved cues for "
            "the show file running in Show mode, Resume offers 'Resume show "
            "N from <cue>' (the engine's offer, only while that cue is "
            "unchanged) and any cue, Start now offers From a cue; never in "
            "a rehearsal, never for another file's list; the start is "
            "start-at-cue with the cue's id, time and lead-in, after Start "
            "now's confirm and a re-check; the list is read only when the "
            "button is pressed; OPERATOR.md says it")
    import shutil
    one, two = _ui2_pages()
    check('press("start-at-cue", {show:file, cue_id:c.id, tc:c.tc, '
          'lead_in_s:c.lead_in_s, confirmed:true})' in two and
          "start-at-cue" not in one,
          "2.0 posts start-at-cue with the show, the cue's id, time and "
          "lead-in and confirmed (2.0's own route: 1.0 has no button for "
          "it)")
    cs = _js_function(two, "cueStart") or ""
    check(0 < cs.find("confirmBox(") < cs.find("tapStill(mk, false)") <
          cs.find('press("start-at-cue"'),
          "the start asks first, then checks nothing changed, then posts")
    check(two.count("cueRead(") == 3 and
          '"/api/remote/play-from-cues?show=" + encodeURIComponent(f)' in
          (_js_function(two, "cueRead") or ""),
          "the cues are read only when Resume or Start now is pressed, "
          "never polled (the engine opens the show file to answer)")
    check('if(d.act === "resume") return resumeOrCue();' in two,
          "Resume goes through the offer")
    here = os.path.dirname(os.path.abspath(__file__))
    doc = open(os.path.join(here, "OPERATOR.md"), encoding="utf-8").read()
    i = doc.find("## Start at a cue (play-from cues, Show mode)")
    sec = doc[i:doc.find("\n## ", i + 5)] if i >= 0 else ""
    for words in ("Resume show 4 from Finale", "Another cue", "From a cue",
                  "Yes, start", "read when you press"):
        check(words in sec, f"OPERATOR.md, Start at a cue, says {words!r}")
    check("comes in the next update" not in sec,
          "OPERATOR.md no longer says the sheet is still to come")
    _no_dashes(sec, "OPERATOR.md, Start at a cue")
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner")
        print("  note: node is not here; checked by reading only")
        print("  ok")
        return
    lo = one[one.find("// LOGIC BEGIN"):one.find("// LOGIC END")]
    fns = "\n".join(_js_function(two, n) or "" for n in (
        "isRehearsal", "cueFile", "cueChoices", "cueLanding", "pfFrames",
        "pfTc"))
    js = lo + "\n" + fns + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const F = "Fire and Ice.json";
const c1 = {id:"c1", name:"Opening", tc:"00:00:30:00", lead_in_s:2, note:""};
const c2 = {id:"c2", name:"Finale", tc:"00:08:12:00", lead_in_s:3, note:""};
const got = (o) => Object.assign({show:F, error:"", entry:{cue:"Show", cues:[c1, c2]}, resume:{show:4, stopped_at:"00:08:20:05", cue:c2}}, o || {});
const run = {show:{running:true, timeline:F}, transport:{programming:false}};
t(cueFile(run) === F, "Show mode: the show file running");
t(cueFile({show:{running:true, timeline:F}, transport:{programming:true}}) === "", "a rehearsal: nothing (Show mode only)");
t(cueFile({show:{running:false, timeline:F}}) === "", "no Run: nothing");
let c = cueChoices(got(), F, "resume");
t(c && c.cues.length === 2 && c.offer && c.offer.cue.id === "c2" && c.offer.show === 4 && c.offer.at === "00:08:20:05", "Resume: the engine's offer and every cue: " + JSON.stringify(c));
c = cueChoices(got(), F, "start");
t(c && c.cues.length === 2 && c.offer === null, "Start now: every cue, no offer");
t(cueChoices(got({resume:{show:4, stopped_at:"00:08:20:05", cue:Object.assign({}, c2, {tc:"00:08:10:00"})}}), F, "resume").offer === null, "an offer whose cue was retimed since is not made");
t(cueChoices(got({resume:{show:4, stopped_at:"00:00:10:00", cue:null}}), F, "resume").offer === null, "no cue before the stop: no offer, the cues still listed");
t(cueChoices(got({resume:null}), F, "resume").offer === null, "no stopped show: no offer");
t(cueChoices(got({show:"Other.json"}), F, "resume") === null, "another file's list: nothing");
t(cueChoices(got({error:"could not be read"}), F, "resume") === null, "a broken cue file: nothing (the engine would refuse)");
t(cueChoices(got({entry:{cues:[]}}), F, "resume") === null, "no saved cues: nothing, the plain press");
t(cueChoices(got(), "", "resume") === null, "no show file running: nothing");
t(cueChoices(null, F, "resume") === null, "no answer: nothing");
t(cueChoices(got({entry:{cues:[{id:"c9", name:"x", tc:"bad", lead_in_s:2}, c1]}}), F, "start").cues.length === 1, "a cue with no readable time is never offered");
t(cueLanding(c2) === "00:08:09:00", "Finale at 00:08:12:00, 3 s lead-in: played from 00:08:09:00: " + cueLanding(c2));
t(cueLanding({tc:"00:00:01:00", lead_in_s:2}) === "00:00:00:00", "never before the top");
t(cueLanding({tc:"00:00:10:00", lead_in_s:2.6}) === "00:00:08:00", "the lead-in in whole seconds, cut as the engine's int() cuts: " + cueLanding({tc:"00:00:10:00", lead_in_s:2.6}));
console.log(JSON.stringify(out));
"""
    r = _node_js(node, js, capture_output=True, text=True, timeout=60)
    check(r.returncode == 0 and r.stdout.strip() == "[]",
          f"the offer, in node: {r.stdout[-900:]!r} {r.stderr[-500:]!r}")
    print("  ok")


def _ui2_status_stopped():
    """Show mode, Run on, show 4 stopped part way: the Stop's Hold."""
    st = _ui2_status_running()
    st["schedule"].update({"state": "STANDBY", "running": None,
                           "stop_held": True, "held": True})
    st["show"] = {"running": True, "show_control_on": True, "timecode": "01:08:20:05",
                  "state": "STOPPED", "timeline": "Fire and Ice.json"}
    st["countdown"] = None
    st["transport"] = {"programming": False}
    st["laser_arm"]["lasers"][0]["armed"] = False
    st["flames"]["groups"] = [dict(g, armed="disarmed")
                              for g in st["flames"]["groups"]]
    return st


_UI2_CUE_JS = r"""
<script>
(function(){
const posts = [], gets = [];
const realFetch = window.fetch;
const C1 = {id:"c1", name:"Opening", tc:"00:00:30:00", lead_in_s:2, note:""};
const C2 = {id:"c2", name:"Finale", tc:"00:08:12:00", lead_in_s:3, note:""};
window.__cues = {show:"Fire and Ice.json", error:"", entry:{cue:"Show", cues:[C1, C2]}, resume:{show:4, stopped_at:"00:08:20:05", cue:C2}};
const J = (o) => Promise.resolve(new Response(JSON.stringify(o), {status:200, headers:{"Content-Type":"application/json"}}));
window.fetch = function(u, o){
  if(/play-from-cues\?show=/.test(String(u))){
    gets.push(decodeURIComponent(String(u).split("show=")[1]));
    const ans = window.__cues || {};
    return window.__hang ? new Promise(r => setTimeout(() => r(J(ans)), window.__hang)) : J(ans);
  }
  if(window.__mod && /\/api\/remote\/status/.test(String(u)))
    return realFetch.apply(this, arguments).then(r => r.json()).then(j => { window.__mod(j); return J(j); });
  if(o && o.method === "POST") posts.push({u:String(u), b:JSON.parse(String(o.body || "{}"))});
  return realFetch.apply(this, arguments);
};
const wait = ms => new Promise(r => setTimeout(r, ms));
const q = id => document.getElementById(id);
const bodies = () => posts.map(p => { const b = Object.assign({}, p.b); delete b.seen; return [p.u.replace("/api/remote/", ""), b]; });
const sheetLook = () => ({open:!q("sheet").hidden, h:q("sh-h").textContent, body:q("sh-body").textContent,
  btns:[...document.querySelectorAll("#sh-row button")].map(b => b.textContent.trim())});
async function pick(label){
  const b = [...document.querySelectorAll("#sh-row button")].filter(x => x.textContent.trim() === label)[0];
  if(b) b.click();
  await wait(400);
  return !!b;
}
async function tap(){ q("b-go").click(); await wait(600); }
async function go(){
  for(let i = 0; i < 80 && !(typeof ST !== "undefined" && ST && ST.schedule); i++) await wait(100);
  await wait(800);
  const out = {go:q("go-l").textContent};
  // Resume: the sheet, the engine's offer, then its confirm.
  posts.length = 0;
  await tap(); out.resume_sheet = sheetLook(); out.resume_gets = gets.slice(); out.resume_posts = bodies();
  await pick("Resume show 4 from Finale"); out.offer_confirm = sheetLook(); out.offer_before = bodies();
  await pick("Yes, start"); out.offer_after = bodies();
  // Resume, plain.
  posts.length = 0; await tap(); await pick("Resume"); out.plain = bodies();
  // Another cue.
  posts.length = 0; await tap(); await pick("Another cue"); out.list = sheetLook();
  await pick("Opening 00:00:30:00"); out.pick_confirm = sheetLook();
  await pick("Cancel"); out.pick_cancel = bodies();
  // The show changed while the question was up: nothing is started.
  await tap(); await pick("Resume show 4 from Finale");
  window.__mod = j => { j.schedule.state = "SHOW"; j.schedule.running = 4; j.schedule.stop_held = false; j.schedule.held = false; };
  await wait(1200);
  await pick("Yes, start"); out.changed = bodies(); out.changed_say = q("msg-t").textContent;
  window.__mod = j => { j.schedule.stop_held = false; j.schedule.held = false; };
  await wait(3000);
  // Start now: the same question, with From a cue.
  out.go2 = q("go-l").textContent;
  posts.length = 0; await tap(); out.start_sheet = sheetLook();
  await pick("Yes, start now"); out.start_now = bodies();
  posts.length = 0; await tap(); await pick("From a cue"); await pick("Finale 00:08:12:00");
  out.start_pick_confirm = sheetLook();
  await pick("Yes, start"); out.start_pick = bodies();
  // No saved cues: Resume is the one press it always was.
  window.__cues = {show:"Fire and Ice.json", error:"", entry:{cues:[]}, resume:null};
  window.__mod = null; await wait(1600);
  posts.length = 0; await tap(); out.none = {sheet:sheetLook().open, posts:bodies(), go:q("go-l").textContent};
  // Review of #209: a Hold pressed while the list is read wins: Resume is
  // not sent.
  window.__hang = 1000; await wait(2600); posts.length = 0;
  q("b-go").click(); await wait(300); q("b-hold").click(); await wait(1500);
  out.hold_during = bodies(); out.hold_during_say = q("msg-t").textContent;
  // A list that comes too late (over 1.5 s): nothing is sent.
  window.__hang = 2200; await wait(2600); posts.length = 0;
  q("b-go").click(); await wait(2800); out.slow = bodies();
  window.__hang = 0;
  // Any other Hold (not a Stop's): Resume at once, the list never read.
  window.__mod = j => { j.schedule.stop_held = false; }; await wait(2600);
  let g0 = gets.length; posts.length = 0; await tap();
  out.plain_hold = {posts:bodies(), read:gets.length - g0, sheet:sheetLook().open};
  // The engine's offer with no show number.
  window.__mod = null;
  window.__cues = {show:"Fire and Ice.json", error:"", entry:{cue:"Show", cues:[C1, C2]}, resume:{show:null, stopped_at:"00:08:20:05", cue:C2}};
  await wait(2600); await tap(); out.noshow = sheetLook(); await pick("Cancel");
  out.gets = gets;
  const pre = document.createElement("pre"); pre.id = "rack-measure";
  pre.textContent = JSON.stringify(out);
  document.body.appendChild(pre);
}
go();
})();
</script>
"""


