def _ui2_tools_copies(one):
    """The show PC's tools (P12, P14, P15, P16): each piece of 1.0's code
    2.0 copies, as it must read in 2.0, with the named differences: a
    question's Yes is 2.0's green (1.0's "start"), 1.0's Programming screen
    is the Schedule tab, Run's show file is p-file, Reload engine answers in
    its own card, and Getting started has no fitting around the flame
    groups. [(what, text)]; a text is "" when 1.0's own was not found."""
    def fn(name):
        m = re.search(r"^(async )?function " + name + r"\(", one, re.M)
        if not m:
            return ""
        j = one.find("\n}\n", m.start())
        return one[m.start():j + 3] if j > 0 else ""

    def blk(start, end="\n});\n"):
        i = one.find(start)
        j = one.find(end, i)
        return one[i:j + len(end)] if 0 <= i < j and \
            one.count(start) == 1 else ""

    def sub(text, a, b, n=1):
        return text.replace(a, b) if text.count(a) == n else ""
    ps = ("the Programming screen", "the Schedule tab")
    fit = "  try{ fitSetup(); }catch(e){}\n"
    out = [(n, fn(n)) for n in (
        "fill", "makeOffered", "checkWords", "loadDeckOp",
        "renderNetwork", "loadNetwork", "saveNetwork", "cfgNote",
        "setWarn")]
    # A named difference (Jeff, 2026-11-11: less prose): the show folder
    # problem keeps its line breaks (headline, bullets, More).
    out += [("loadFolders", sub(fn("loadFolders"),
                                "margin-top:4px\">${esc(j.show_folder_problem)}",
                                "margin-top:4px;white-space:pre-line\">"
                                "${esc(j.show_folder_problem)}"))]
    out += [("renderSetupFold", sub(fn("renderSetupFold"), fit, "")),
            ("renderSetup", sub(sub(fn("renderSetup"), fit, ""), ps[0],
                                ps[1], 2)),
            ("setupFolderWords", sub(fn("setupFolderWords"), ps[0], ps[1])),
            ("makeShowFile", sub(sub(fn("makeShowFile"),
                                     '"Yes, make it", "start"',
                                     '"Yes, make it", "green"'),
                                 "    await loadShowFiles(j.file);\n",
                                 "    await progFiles();\n    if(j.file && "
                                 "[...$(\"p-file\").options].some(o => "
                                 "o.value === j.file)){ $(\"p-file\").value"
                                 " = j.file; P_PICKED = true; }\n")),
            ("Open a folder", blk('document.querySelectorAll("[data-open]")'
                                  '.forEach(', "\n}));\n")),
            ("Make a show file", '$("fo-make").addEventListener("click", '
                                 'makeShowFile);\n'
             if '$("fo-make").addEventListener("click", makeShowFile);'
             in one else ""),
            ("Check the show file", sub(blk('$("fo-check").addEventListener('),
                                        '$("run-file")', '$("p-file")')),
            ("Use this folder", sub(blk('$("fo-save").addEventListener('),
                                    '"Yes, use it", "start"',
                                    '"Yes, use it", "green"')),
            ("Choose (Stream Deck operator)",
             blk('$("b-deck-op").addEventListener(')),
            ("Use (an address)", blk('$("net-uses").addEventListener(')),
            # Less prose (Jeff, 2026-11-11): the confirms are shorter,
            # every condition kept.
            ("Restart the engine",
             sub(sub(blk('$("net-restart").addEventListener('),
                     '"Yes, restart", "start"', '"Yes, restart", "green"'),
                 '"LTC Player restarts the show engine so it listens on the '
                 'saved show network address. It is refused while a show '
                 'runs or a flame group is armed. flamesafe and the Stream '
                 'Deck program keep running."',
                 '"Restarts the show engine on the saved address. Refused '
                 'while a show runs or a group is armed. flamesafe and the '
                 'Stream Deck keep running."')),
            ("Reload engine",
             sub(sub(sub(blk('$("cfg-reload").addEventListener('),
                         '"Yes, reload", "start"', '"Yes, reload", "green"'),
                     '$("ctl-msg")', '$("cfg-msg")', 2),
                 '"LTC Player restarts the show engine so it reads the '
                 'changed settings files. It is refused while a show runs or '
                 'a flame group is armed. flamesafe and the Stream Deck '
                 'program keep running."',
                 '"Restarts the show engine to read the changed files. '
                 'Refused while a show runs or a group is armed. flamesafe '
                 'and the Stream Deck keep running."')),
            ("Check the rig", blk('$("rc-run").addEventListener(')),
            ("Close this window", blk('$("info-exit").addEventListener('))]
    for ln in ('$("net-pick").addEventListener("change", () => { '
               'if($("net-pick").value) $("net-addr").value = '
               '$("net-pick").value; });',
               '$("net-save").addEventListener("click", () => '
               'saveNetwork($("net-addr").value));',
               '$("info-close").addEventListener("click", () => { '
               '$("info").hidden = true; });',
               '$("info").addEventListener("click", e => { if(e.target === '
               '$("info")) $("info").hidden = true; });',
               'document.addEventListener("keydown", e => { if(e.key === '
               '"Escape"){ $("info").hidden = true; } });',
               '$("mo-verify").addEventListener("click", () => moPress('
               '"checklist-verify", {}, "mo-cmsg"));',
               # 1.0's render(): the rig check card and the settings note
               '  rcard.hidden = !s.preroll || !(ME && ME.local);\n'
               '  if(s.preroll){\n    $("rc-now").textContent = prl.now;\n'
               '    $("rc-warn").hidden = !prl.warn;\n'
               '    $("rc-warn").textContent = prl.warn;\n'
               '    $("rc-items").textContent = prl.items.join(". ");\n'
               '    $("rc-run").disabled = prl.checking;\n  }',
               '  const cn = cfgNote(s.config_changed);\n'
               '  setWarn("cfg-note", cn.text);\n'
               '  $("cfg-reload").hidden = !cn.offer || !mayRow(s, '
               '"settings");',
               # 1.0's whoami: these cards on the show PC only
               '  $("admin").hidden = !ME.local;',
               '  $("deck-op").hidden = !ME.local;',
               '  $("folders").hidden = !ME.local;',
               '  $("info-device").textContent = ME.device || "";',
               '  if(ME.local) loadFolders();',
               # 1.0's renderMode: the info panel's flamesafe line
               '  $("info-flames").textContent = unconf ? "flamesafe\'s '
               'config is not yet confirmed by Andy'):
        # The one named difference here (Jeff, 2026-11-11): the rig
        # check's items one to a line (opText), not one run-on sentence.
        two_ln = ln.replace(
            '    $("rc-items").textContent = prl.items.join(". ");\n',
            '    // One check to a line (Jeff, 2026-11-11), not one run-on '
            'sentence.\n'
            '    setOpText($("rc-items"), prl.items.map(t => "- " + '
            'String(t).replace(/\\s+/g, " ")).join("\\n"));\n')
        out.append((ln[:60], two_ln if ln in one else ""))
    return out


def test_ui2_op_text_shapes_text_with_dom_nodes_only():
    section("2.0's opText (Jeff, 2026-11-11: less prose): the first line a "
            "bold headline, '- ' lines bullets, a blank line a new "
            "paragraph, More dimmed; one line of text reads as before; "
            "built from DOM nodes and textContent only, so a name with "
            "markup in it is shown as text; the alert Details, and the rig "
            "check's items one to a line, use it")
    two = _ui2_pages()[1]
    fns = [_js_function(two, n) for n in ("opText", "setOpText")]
    check(all(fns) and not any("innerHTML" in f or "insertAdjacent" in f or
                               "outerHTML" in f for f in fns),
          "opText and setOpText never write markup")
    check('const v = await sheet(it.what, body,' in two and
          'body.appendChild(opText(it.full));' in two and
          'full:a.full || a.text, act:"ack"' in two and
          '$("sh-body").appendChild(html); }' in two and
          'setOpText($("rc-items"), prl.items.map(' in two,
          "the alert Details sheet takes opText's nodes, an engine alert "
          "gives its lines (full), and the rig check card lists its items")
    import shutil
    node = shutil.which("node")
    if not node or not all(fns):
        check(not IN_CI, "node is missing on this CI runner")
        print("  ok")
        return
    stub = r"""
function El(tag){ this.tag = tag; this.className = ""; this.childNodes = [];
  this.dataset = {}; this._t = ""; }
Object.defineProperty(El.prototype, "textContent", {
  get(){ return this._t + this.childNodes.map(c => c.textContent).join(""); },
  set(v){ this._t = String(v); this.childNodes = []; }});
Object.defineProperty(El.prototype, "innerHTML", {
  set(v){ throw new Error("innerHTML used"); }});
El.prototype.appendChild = function(c){ this.childNodes.push(c); return c; };
Object.defineProperty(El.prototype, "firstChild", {
  get(){ return this.childNodes[0] || null; }});
const document = {createElement: (t) => new El(t)};
const shape = (e) => [e.tag, e.className.trim(), e._t].concat(
  e.childNodes.length ? [e.childNodes.map(shape)] : []);
"""
    cases = {
        "plain": "One line. With <b>x</b> & 'y'.",
        "shaped": "Head <i>line</i>.\n- Do: a.\n- Then: b.\n\nMore: 'n'.",
        "items": "- Audio OK\n- Video FAILED: gone",
        "one": "- Audio OK",
    }
    js = stub + fns[0] + "\n" + fns[1] + "\n" + \
        "const cases = " + json.dumps(cases) + ";\nconst out = {};\n" \
        "for(const k in cases) out[k] = shape(opText(cases[k]));\n" \
        "const host = new El('div'); setOpText(host, cases.items); " \
        "const first = host.childNodes[0]; setOpText(host, cases.items);\n" \
        "out.same = host.childNodes[0] === first;\n" \
        "console.log(JSON.stringify(out));\n"
    r = _node_js(node, js, capture_output=True, text=True, timeout=60)
    try:
        got = json.loads(r.stdout.strip() or "null")
    except ValueError:
        got = None
    want = {
        "plain": ["div", "full op", "One line. With <b>x</b> & 'y'."],
        "shaped": ["div", "full op", "", [
            ["b", "", "Head <i>line</i>."],
            ["ul", "", "", [["li", "", "Do: a."], ["li", "", "Then: b."]]],
            ["p", "gap dim", "More: 'n'."]]],
        "items": ["div", "full op", "", [["ul", "", "", [
            ["li", "", "Audio OK"], ["li", "", "Video FAILED: gone"]]]]],
        "one": ["div", "full op", "", [["ul", "", "", [
            ["li", "", "Audio OK"]]]]],
        "same": True,
    }
    check(r.returncode == 0 and got == want,
          f"opText builds a headline, bullets and paragraphs from text, "
          f"markup kept as text, and setOpText rebuilds only on a change: "
          f"{r.stdout.strip()[:800]} {r.stderr.strip()[:600]}")
    print("  ok")


